  ('scene-ayodhya-prepares', 'brothers-meet', 4, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":127,"sourceOrdinal":127,"sourceEndOrdinal":127,"spanSha256":"097c1dc22e4d379c367cf61a656856ea2f26face1092709ada5a1d75345c1837"}'::jsonb, '{"visualCue":"The two moving worlds meet around an embrace, then settle around the returned sandals.","characterIds":["rama","bharata","sita","lakshmana","sugriva","vibhishana"]}'::jsonb),
  ('scene-kingdom-returned', 'bharata-returns-burden', 1, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":128,"sourceOrdinal":128,"sourceEndOrdinal":128,"spanSha256":"0eab6905146d65e1f905b5e974d473712234c86fa12bf1902fcf9f1f435e9405"}'::jsonb, '{"visualCue":"Bharata speaks before the gathered household while Rama listens from a low seat.","characterIds":["bharata","rama"]}'::jsonb),
  ('scene-kingdom-returned', 'exile-clothes-fall-away', 2, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":128,"sourceOrdinal":128,"sourceEndOrdinal":128,"spanSha256":"0eab6905146d65e1f905b5e974d473712234c86fa12bf1902fcf9f1f435e9405"}'::jsonb, '{"visualCue":"Bark, dust, water, cloth, and ornaments mark a visible transition between lives.","characterIds":["rama","sita","lakshmana","bharata","sugriva","vibhishana"]}'::jsonb),
  ('scene-kingdom-returned', 'city-entry', 3, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":128,"sourceOrdinal":128,"sourceEndOrdinal":128,"spanSha256":"0eab6905146d65e1f905b5e974d473712234c86fa12bf1902fcf9f1f435e9405"}'::jsonb, '{"visualCue":"The procession enters beneath flags while brief visions of the allies'' deeds rise over the crowd.","characterIds":["rama","hanuman","sugriva","vibhishana"]}'::jsonb),
  ('scene-kingdom-returned', 'coronation-and-gifts', 4, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":128,"sourceOrdinal":128,"sourceEndOrdinal":128,"spanSha256":"0eab6905146d65e1f905b5e974d473712234c86fa12bf1902fcf9f1f435e9405"}'::jsonb, '{"visualCue":"Water, crown, white umbrellas, and the pearl necklace form four bright visual beats.","characterIds":["rama","sita","vasishta","hanuman","sugriva","vibhishana"]}'::jsonb),
  ('scene-kingdom-returned', 'rule-begins', 5, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":128,"sourceOrdinal":128,"sourceEndOrdinal":128,"spanSha256":"0eab6905146d65e1f905b5e974d473712234c86fa12bf1902fcf9f1f435e9405"}'::jsonb, '{"visualCue":"Departing paths spread from Ayodhya as the city settles into a dawn panorama.","characterIds":["rama","bharata","lakshmana","sugriva","vibhishana"]}'::jsonb)
) as beat(moment_slug, slug, beat_ordinal, source_range, visual_direction)
join public.narrative_series series on series.slug = 'ramayana-dutt-consumer-v1'
join public.narrative_moments moment on moment.series_id = series.id and moment.slug = beat.moment_slug
on conflict (moment_id, slug) do update set
  beat_ordinal = excluded.beat_ordinal,
  source_range = excluded.source_range,
  visual_direction = excluded.visual_direction,
  rights_lane = excluded.rights_lane,
  publication_state = excluded.publication_state,
  updated_at = now();

insert into public.narrative_beat_texts (
  beat_id, language_code, title, narration, text_status,
  rights_lane, publication_state
)
select beat.id, copy.language_code, copy.title, copy.narration,
  'source_aligned', 'derivative_allowed', 'published'
from (values
  ('scene-valmiki-asks-for-complete-human', 'valmiki-sets-impossible-question', 'en', 'Can all these qualities live in one person?', 'Valmiki asks Narada for someone living in the world who joins courage with compassion, truth with self-control, learning with practical judgment, and power with concern for others. He is not asking for a flawless statue, but for a life whose choices can be followed.'),
  ('scene-valmiki-asks-for-complete-human', 'valmiki-sets-impossible-question', 'hi', 'क्या ये सभी गुण एक मनुष्य में मिल सकते हैं?', 'वाल्मीकि नारद से ऐसे जीवित मनुष्य के बारे में पूछते हैं जिसमें साहस के साथ करुणा, सत्य के साथ संयम, ज्ञान के साथ व्यवहार-बुद्धि और शक्ति के साथ सबके हित की चिंता हो। वे किसी निर्जीव आदर्श की नहीं, ऐसे जीवन की खोज कर रहे हैं जिसके निर्णयों का अनुसरण किया जा सके।'),
  ('scene-valmiki-asks-for-complete-human', 'narada-names-rama', 'en', 'Narada answers with one name', 'Narada considers the demanding list and names Rama of the Ikshvaku line. He describes a prince disciplined in speech and anger, formidable in danger, attentive to duty, and able to make people feel protected rather than merely ruled.'),
  ('scene-valmiki-asks-for-complete-human', 'narada-names-rama', 'hi', 'नारद एक नाम लेते हैं', 'नारद उस कठिन सूची पर विचार करके इक्ष्वाकु वंश के राम का नाम लेते हैं। वे ऐसे राजकुमार का परिचय देते हैं जो वाणी और क्रोध पर संयम रखता है, संकट में प्रबल है, कर्तव्य के प्रति सजग है और लोगों को केवल शासित नहीं बल्कि सुरक्षित अनुभव कराता है।'),
  ('scene-valmiki-asks-for-complete-human', 'a-crown-turns-into-exile', 'en', 'A promised crown becomes a forest road', 'Narada races ahead: Dasharatha prepares to install Rama, Kaikeyi claims her old boons, and Rama accepts fourteen years of exile. Sita and Lakshmana choose to go with him, turning a political rupture into a shared journey away from Ayodhya.'),
  ('scene-valmiki-asks-for-complete-human', 'a-crown-turns-into-exile', 'hi', 'राज्याभिषेक की सुबह वन की राह बन जाती है', 'नारद कथा को तेजी से आगे ले जाते हैं—दशरथ राम के राज्याभिषेक की तैयारी करते हैं, कैकेयी पुराने वरदान माँगती हैं और राम चौदह वर्ष का वनवास स्वीकार कर लेते हैं। सीता और लक्ष्मण साथ चलने का निर्णय लेते हैं; राजमहल का संकट अयोध्या से दूर एक साझा यात्रा बन जाता है।'),
  ('scene-valmiki-asks-for-complete-human', 'loss-creates-an-alliance', 'en', 'Sita is taken, and strangers become allies', 'The forest story breaks when Ravana abducts Sita and Jatayu falls trying to stop him. Rama and Lakshmana''s search reaches Sugriva and Hanuman; grief becomes alliance, and scattered clues begin pointing across the ocean toward Lanka.'),
  ('scene-valmiki-asks-for-complete-human', 'loss-creates-an-alliance', 'hi', 'सीता का हरण होता है और अजनबी साथी बनते हैं', 'वन की कथा तब टूटती है जब रावण सीता का हरण करता है और उसे रोकते हुए जटायु गिर पड़ते हैं। राम और लक्ष्मण की खोज सुग्रीव और हनुमान तक पहुँचती है; शोक मित्रता में बदलता है और बिखरे संकेत समुद्र पार लंका की ओर इशारा करने लगते हैं।'),
  ('scene-valmiki-asks-for-complete-human', 'narada-reaches-the-return', 'en', 'The whole life flashes to its return', 'Narada''s preview crosses Hanuman''s leap, the bridge, the war, Ravana''s fall, Sita''s recovery, and the return to Ayodhya. It ends with the selected source''s sacred vision of Rama''s reign, giving Valmiki the scale of the life he is about to tell rather than replacing the journey itself.'),
  ('scene-valmiki-asks-for-complete-human', 'narada-reaches-the-return', 'hi', 'पूरे जीवन की झलक वापसी तक पहुँचती है', 'नारद की झलक हनुमान की छलाँग, सेतु, युद्ध, रावण के पतन, सीता की पुनर्प्राप्ति और अयोध्या वापसी से होकर गुजरती है। वह चुने हुए स्रोत में राम-राज्य की पवित्र कल्पना पर ठहरती है—यह आने वाली यात्रा का स्थान नहीं लेती, बल्कि वाल्मीकि को उस जीवन का विस्तार दिखाती है जिसे वे कथा बनाएँगे।'),
  ('scene-grief-becomes-first-verse', 'tamasa-seems-clear', 'en', 'A river as clear as a good mind', 'After Narada leaves, Valmiki walks with his disciple Bharadwaja to the Tamasa. The clear water and mudless bank promise a calm place for bathing; the scene begins in careful attention to an ordinary, peaceful landscape.'),
  ('scene-grief-becomes-first-verse', 'tamasa-seems-clear', 'hi', 'सज्जन मन की तरह निर्मल नदी', 'नारद के जाने के बाद वाल्मीकि अपने शिष्य भरद्वाज के साथ तमसा नदी तक जाते हैं। निर्मल जल और कीचड़-रहित तट स्नान के लिए शांत स्थान का आभास देते हैं; दृश्य एक साधारण, शांत भू-दृश्य को ध्यान से देखने के साथ आरंभ होता है।'),
  ('scene-grief-becomes-first-verse', 'krauncha-pair-in-peace', 'en', 'Two birds move without fear', 'Near the water, Valmiki notices a pair of krauncha birds calling to one another and moving in complete ease. Their unguarded companionship gives the next instant its force: nothing in the scene has prepared them for violence.'),
  ('scene-grief-becomes-first-verse', 'krauncha-pair-in-peace', 'hi', 'दो पक्षी निश्चिंत होकर विचरते हैं', 'जल के पास वाल्मीकि क्रौंच पक्षियों के एक जोड़े को एक-दूसरे को पुकारते और निश्चिंत होकर विचरते देखते हैं। उनका सहज साथ अगले क्षण को और तीखा बना देता है—दृश्य में ऐसा कुछ नहीं था जो उन्हें हिंसा के लिए तैयार करता।'),
  ('scene-grief-becomes-first-verse', 'arrow-breaks-the-pair', 'en', 'An arrow tears the scene in two', 'A hunter shoots the male bird without any quarrel or threat. He falls bleeding before Valmiki, and the surviving bird''s cry turns the death from a distant act into a felt separation witnessed at close range.'),
  ('scene-grief-becomes-first-verse', 'arrow-breaks-the-pair', 'hi', 'एक बाण दृश्य को दो भागों में तोड़ देता है', 'एक शिकारी बिना किसी झगड़े या खतरे के नर पक्षी को मार देता है। वह वाल्मीकि के सामने रक्त से भीगा गिरता है और जीवित पक्षी का विलाप उस मृत्यु को दूर की घटना नहीं रहने देता; बिछोह सबके सामने अनुभव होने लगता है।'),
  ('scene-grief-becomes-first-verse', 'grief-finds-meter', 'en', 'Grief speaks in a rhythm of its own', 'Compassion and anger rise together in Valmiki. His rebuke to the hunter comes out in equal measured parts; only after speaking does he notice that grief has shaped itself into a repeatable verse, shoka becoming shloka in the story''s own explanation.'),
  ('scene-grief-becomes-first-verse', 'grief-finds-meter', 'hi', 'शोक अपनी लय में बोल उठता है', 'वाल्मीकि के भीतर करुणा और आक्रोश एक साथ उठते हैं। शिकारी के लिए निकली उनकी वाणी समान लयबद्ध भागों में ढल जाती है; बोलने के बाद उन्हें समझ आता है कि शोक ने स्वयं को दोहराए जा सकने वाले श्लोक का रूप दे दिया है।'),
  ('scene-grief-becomes-first-verse', 'brahma-gives-the-verse-a-road', 'en', 'Brahma turns one verse into a commission', 'Back at the hermitage, Valmiki cannot stop thinking about the needless killing. Brahma appears and tells him the metre did not arise in vain: he must use it to tell Rama''s whole story truthfully, including what he has not yet seen, so that the poem can travel through the world.'),
  ('scene-grief-becomes-first-verse', 'brahma-gives-the-verse-a-road', 'hi', 'ब्रह्मा एक श्लोक को पूरी कथा का दायित्व देते हैं', 'आश्रम लौटकर भी वाल्मीकि उस निरर्थक हत्या को भूल नहीं पाते। ब्रह्मा प्रकट होकर कहते हैं कि वह छंद व्यर्थ नहीं आया—उसी में राम की पूरी कथा सत्यपूर्वक कही जाए, यहाँ तक कि वह भी जो अभी वाल्मीकि ने नहीं देखा, ताकि यह कथा संसार में यात्रा कर सके।'),
  ('scene-valmiki-sees-the-whole-life', 'valmiki-enters-contemplation', 'en', 'The storyteller becomes a witness', 'Valmiki sits facing east, steadies himself, and turns from Narada''s summary toward sustained contemplation. The story presents this as a change in access: he is no longer arranging hearsay but watching people speak, move, choose, and endure as if they were before him.'),
  ('scene-valmiki-sees-the-whole-life', 'valmiki-enters-contemplation', 'hi', 'कथाकार साक्षी बनता है', 'वाल्मीकि पूर्व की ओर बैठकर स्वयं को स्थिर करते हैं और नारद की संक्षिप्त रूपरेखा से गहरे ध्यान की ओर बढ़ते हैं। कथा इसे दृष्टि के परिवर्तन की तरह दिखाती है—अब वे सुनी-सुनाई बातों को नहीं जोड़ रहे, बल्कि लोगों को अपने सामने बोलते, चलते, चुनते और सहते देख रहे हैं।'),
  ('scene-valmiki-sees-the-whole-life', 'household-appears-in-motion', 'en', 'A family appears before it breaks', 'He sees Rama, Sita, Lakshmana, Dasharatha, and the queens not as names in a list but laughing, speaking, and acting inside their household. That ordinary movement matters because exile will soon separate the same people and transform every familiar room.'),
  ('scene-valmiki-sees-the-whole-life', 'household-appears-in-motion', 'hi', 'टूटने से पहले पूरा परिवार दिखाई देता है', 'वे राम, सीता, लक्ष्मण, दशरथ और रानियों को नामों की सूची की तरह नहीं, बल्कि परिवार में हँसते, बोलते और काम करते देखते हैं। यह सामान्य जीवन इसलिए महत्त्वपूर्ण है क्योंकि वनवास शीघ्र ही इन्हीं लोगों को अलग करेगा और हर परिचित कक्ष का अर्थ बदल देगा।'),
  ('scene-valmiki-sees-the-whole-life', 'the-road-opens-in-every-direction', 'en', 'The whole journey becomes visible', 'Birth, marriage, the broken bow, the lost coronation, exile, forest encounters, Sita''s abduction, the alliance with Sugriva, Hanuman''s search, and the war in Lanka unfold as connected consequences. Valmiki sees not only milestones but the conversations and grief that move people between them.'),
  ('scene-valmiki-sees-the-whole-life', 'the-road-opens-in-every-direction', 'hi', 'पूरी यात्रा एक साथ दिखाई देने लगती है', 'जन्म, विवाह, धनुष-भंग, रुका हुआ राज्याभिषेक, वनवास, वन के प्रसंग, सीता-हरण, सुग्रीव से मित्रता, हनुमान की खोज और लंका का युद्ध जुड़े हुए परिणामों की तरह खुलते हैं। वाल्मीकि केवल पड़ाव नहीं, उन संवादों और दुःखों को भी देखते हैं जो लोगों को एक पड़ाव से दूसरे तक ले जाते हैं।'),
  ('scene-valmiki-sees-the-whole-life', 'future-enters-the-composition', 'en', 'The ending is not hidden from the poet', 'The vision reaches the return, installation, and events the selected telling places later, including Sita''s eventual separation. Holding past and future together, Valmiki begins composing a story large enough for triumph, doubt, tenderness, violence, and unresolved pain.'),
  ('scene-valmiki-sees-the-whole-life', 'future-enters-the-composition', 'hi', 'कवि से आगे का अंत भी छिपा नहीं रहता', 'दृष्टि वापसी, राज्याभिषेक और चुनी हुई कथा में आगे आने वाली घटनाओं तक पहुँचती है, जिनमें सीता का बाद का वियोग भी शामिल है। अतीत और भविष्य को साथ रखकर वाल्मीकि ऐसी कथा रचना आरंभ करते हैं जिसमें विजय, संदेह, स्नेह, हिंसा और अधूरा दुःख सबके लिए स्थान हो।'),
  ('scene-lava-kusha-carry-the-story', 'valmiki-needs-voices', 'en', 'A story is unfinished until someone can carry it', 'After composing the Ramayana, Valmiki asks a practical question: who can bring so vast a work before real audiences? Lava and Kusha arrive at the hermitage with strong memories, musical ability, disciplined study, and the patience to learn meaning rather than merely recite sound.'),
  ('scene-lava-kusha-carry-the-story', 'valmiki-needs-voices', 'hi', 'कथा तब तक अधूरी है जब तक कोई उसे आगे न ले जाए', 'रामायण की रचना के बाद वाल्मीकि एक व्यावहारिक प्रश्न पूछते हैं—इतनी विशाल कथा को वास्तविक श्रोताओं तक कौन ले जाएगा? लव और कुश आश्रम में ऐसी स्मृति, संगीत-कौशल, अनुशासन और धैर्य के साथ आते हैं जो उन्हें केवल ध्वनि नहीं, अर्थ सीखने योग्य बनाता है।'),
  ('scene-lava-kusha-carry-the-story', 'story-learns-music-and-feeling', 'en', 'The epic learns how to move an audience', 'The brothers learn melody, measure, expression, movement, and the changing emotional colours of love, grief, humour, anger, fear, and courage. Performance is not decoration here; it is the technology that makes thousands of connected events graspable and memorable.'),
  ('scene-lava-kusha-carry-the-story', 'story-learns-music-and-feeling', 'hi', 'महाकाव्य श्रोताओं के मन तक पहुँचना सीखता है', 'दोनों भाई स्वर, ताल, अभिव्यक्ति, गति और प्रेम, शोक, हास्य, क्रोध, भय तथा वीरता के बदलते भाव सीखते हैं। यहाँ प्रस्तुति सजावट नहीं है; वही साधन है जो हजारों जुड़ी घटनाओं को समझने और याद रखने योग्य बनाता है।'),
  ('scene-lava-kusha-carry-the-story', 'hermitages-become-first-audiences', 'en', 'The first listeners know they have heard something vast', 'Lava and Kusha sing before gatherings of sages. Listeners are moved, praise the clarity and beauty of the telling, and offer the young performers the simple possessions available in hermitage life. The gifts show a story already travelling through relationship, not through royal command.'),
  ('scene-lava-kusha-carry-the-story', 'hermitages-become-first-audiences', 'hi', 'पहले श्रोता समझते हैं कि उन्होंने कुछ विशाल सुना है', 'लव और कुश ऋषियों की सभाओं में गाते हैं। श्रोता कथा की स्पष्टता और सौंदर्य से प्रभावित होकर उनकी प्रशंसा करते हैं और आश्रम-जीवन में उपलब्ध साधारण वस्तुएँ भेंट देते हैं। ये उपहार दिखाते हैं कि कथा राजाज्ञा से नहीं, मानवीय संबंधों के सहारे यात्रा करने लगी है।'),
  ('scene-lava-kusha-carry-the-story', 'rama-hears-his-own-life', 'en', 'The song reaches the person inside it', 'In Ayodhya, Rama notices the two ascetic-looking singers and brings them before his brothers and counsellors. As they begin, the court is captivated and Rama recognises signs of royalty in them; the epic''s frame closes on a startling encounter between a life, its retelling, and the people who do not yet understand every bond joining them.'),
  ('scene-lava-kusha-carry-the-story', 'rama-hears-his-own-life', 'hi', 'गीत उस व्यक्ति तक पहुँचता है जिसकी यह कथा है', 'अयोध्या में राम इन तपस्वी-वेशधारी गायकों को देखते हैं और उन्हें भाइयों तथा मंत्रियों की सभा में बुलाते हैं। गीत आरंभ होते ही दरबार मंत्रमुग्ध हो जाता है और राम उनमें राजवंश के संकेत पहचानते हैं; कथा का आरंभ एक विचित्र मिलन पर ठहरता है—जीवन, उसकी पुनर्कथा और वे लोग, जो अभी उन्हें जोड़ने वाले सभी संबंध नहीं जानते।'),
  ('scene-ayodhya-built-for-life', 'kosala-rises-by-sarayu', 'en', 'A fertile country gathers around the Sarayu', 'The story first locates Ayodhya inside Kosala, a prosperous country sustained by grain, wealth, and the Sarayu. Its dynastic memory reaches back through Ikshvaku and Sagara, placing Rama''s future family inside a much older landscape of rulers, settlements, rivers, and inherited responsibility.'),
  ('scene-ayodhya-built-for-life', 'kosala-rises-by-sarayu', 'hi', 'सरयू के किनारे समृद्ध कोसल बसता है', 'कथा पहले अयोध्या को कोसल के भीतर रखती है—अनाज, संपदा और सरयू से पोषित एक समृद्ध देश। उसकी वंश-स्मृति इक्ष्वाकु और सगर तक जाती है; इस तरह राम का भावी परिवार शासकों, बस्तियों, नदियों और विरासत में मिले उत्तरदायित्व के बहुत पुराने भू-दृश्य में स्थित होता है।'),
  ('scene-ayodhya-built-for-life', 'city-designed-for-movement', 'en', 'Roads, gates, markets, and water make a city', 'Ayodhya is not introduced as one palace floating above empty ground. Broad roads connect gates and markets; trees, watered streets, workshops, storehouses, homes, and public spaces support daily movement. Fortifications protect the city, but abundance and organisation are what make it feel inhabited.'),
  ('scene-ayodhya-built-for-life', 'city-designed-for-movement', 'hi', 'सड़कें, द्वार, बाज़ार और जल मिलकर नगर बनाते हैं', 'अयोध्या को खाली भूमि के ऊपर तैरते एक महल की तरह नहीं दिखाया जाता। चौड़ी सड़कें द्वारों और बाज़ारों को जोड़ती हैं; वृक्ष, सींची हुई गलियाँ, कार्यशालाएँ, भंडार, घर और सार्वजनिक स्थान रोज़मर्रा की गति को संभालते हैं। किलेबंदी रक्षा करती है, पर नगर को जीवित बनाती है उसकी समृद्धि और व्यवस्था।'),
  ('scene-ayodhya-built-for-life', 'culture-fills-the-streets', 'en', 'Skill and celebration give the city its voice', 'Musicians, performers, merchants, artisans, learned teachers, warriors, and householders fill the source''s city portrait. The variety matters: Ayodhya''s splendour comes from many kinds of work and knowledge meeting in one place, not only from royal treasure or military strength.'),
  ('scene-ayodhya-built-for-life', 'culture-fills-the-streets', 'hi', 'कौशल और उत्सव नगर को अपनी आवाज़ देते हैं', 'संगीतकार, कलाकार, व्यापारी, शिल्पी, विद्वान शिक्षक, योद्धा और गृहस्थ स्रोत के नगर-चित्र को भरते हैं। यह विविधता महत्त्वपूर्ण है—अयोध्या की शोभा केवल राजकोष या सेना से नहीं, अनेक प्रकार के श्रम और ज्ञान के एक स्थान पर मिलने से बनती है।'),
  ('scene-ayodhya-built-for-life', 'beauty-rests-on-security', 'en', 'Prosperity is paired with restraint', 'The selected telling praises trained defenders who can protect the city yet are expected not to strike the abandoned, hidden, or fleeing. Its idealised portrait connects beauty with security and security with rules, establishing the civic world whose unresolved absence of heirs will soon trouble Dasharatha.'),
  ('scene-ayodhya-built-for-life', 'beauty-rests-on-security', 'hi', 'समृद्धि के साथ संयम भी जुड़ा है', 'चुनी हुई कथा प्रशिक्षित रक्षकों की प्रशंसा करती है जो नगर की रक्षा कर सकते हैं, पर त्यागे हुए, छिपे या भागते व्यक्ति पर प्रहार न करने की मर्यादा रखते हैं। यह आदर्श चित्र सौंदर्य को सुरक्षा और सुरक्षा को नियमों से जोड़ता है—यही वह नागरिक संसार है जिसकी उत्तराधिकार-विहीनता शीघ्र ही दशरथ को चिंतित करेगी।'),
  ('scene-dasharatha-rules-with-council', 'dasharatha-enters-the-city', 'en', 'The king is measured by the city he protects', 'Dasharatha enters the narrative after the city, not before it. He is described as learned, self-controlled, far-sighted, formidable in war, and dear to rural and urban people. His power is meaningful because it serves a populated realm whose wellbeing the previous scene has made visible.'),
  ('scene-dasharatha-rules-with-council', 'dasharatha-enters-the-city', 'hi', 'राजा का मूल्य उस नगर से आँका जाता है जिसकी वह रक्षा करता है', 'दशरथ कथा में नगर के बाद आते हैं, उससे पहले नहीं। वे विद्वान, संयमी, दूरदर्शी, युद्ध में प्रबल और गाँव तथा नगर दोनों के लोगों के प्रिय बताए जाते हैं। उनकी शक्ति इसलिए अर्थपूर्ण है क्योंकि वह उस आबाद राज्य की सेवा करती है जिसका जीवन पिछला दृश्य दिखा चुका है।'),
  ('scene-dasharatha-rules-with-council', 'prosperity-is-governed', 'en', 'Order reaches beyond the palace', 'The source''s idealised Ayodhya contains prosperous households, ritual learning, trained forces, animals, trade, and public confidence. Dasharatha''s reign holds these systems together through administration and restraint; the city is secure enough for people to pursue different forms of life.'),
  ('scene-dasharatha-rules-with-council', 'prosperity-is-governed', 'hi', 'व्यवस्था महल से बहुत आगे तक जाती है', 'स्रोत की आदर्श अयोध्या में समृद्ध परिवार, अनुष्ठानिक अध्ययन, प्रशिक्षित सेना, पशुधन, व्यापार और सार्वजनिक विश्वास साथ दिखाई देते हैं। दशरथ का शासन प्रशासन और संयम से इन व्यवस्थाओं को जोड़ता है; नगर इतना सुरक्षित है कि लोग जीवन के अलग-अलग मार्ग अपना सकें।'),
  ('scene-dasharatha-rules-with-council', 'eight-ministers-test-decisions', 'en', 'Eight ministers turn information into judgment', 'Dhrishti, Vijaya, Surashtra, Rashtravardhana, Akopa, Dharmapala, and Sumantra are named among the king''s principal ministers. The telling values their ability to understand motives, protect confidentiality, gather intelligence, judge evidence, and remain committed to the realm rather than personal display.'),
  ('scene-dasharatha-rules-with-council', 'eight-ministers-test-decisions', 'hi', 'आठ मंत्री सूचना को निर्णय में बदलते हैं', 'धृष्टि, विजय, सुराष्ट्र, राष्ट्रवर्धन, अकोप, धर्मपाल और सुमंत्र राजा के प्रमुख मंत्रियों में गिने जाते हैं। कथा उनकी उस क्षमता को महत्त्व देती है जिससे वे उद्देश्यों को समझें, गोपनीयता रखें, सूचना जुटाएँ, प्रमाण पर निर्णय लें और निजी प्रदर्शन के बजाय राज्य के प्रति निष्ठावान रहें।'),
  ('scene-dasharatha-rules-with-council', 'priests-and-counsellors-share-the-burden', 'en', 'No single voice owns the future', 'Vasishta and Vamadeva serve as family priests alongside other learned counsellors. The source praises a court that investigates before punishing, guards secrets, recognises ability, and can disagree without abandoning duty. That collective structure will now face a problem force alone cannot solve.'),
  ('scene-dasharatha-rules-with-council', 'priests-and-counsellors-share-the-burden', 'hi', 'भविष्य पर किसी एक आवाज़ का अधिकार नहीं', 'वसिष्ठ और वामदेव अन्य विद्वान सलाहकारों के साथ राजपुरोहित हैं। स्रोत ऐसे दरबार की प्रशंसा करता है जो दंड से पहले जाँच करता है, रहस्य सुरक्षित रखता है, योग्यता पहचानता है और मतभेद के बीच भी कर्तव्य नहीं छोड़ता। अब इसी सामूहिक व्यवस्था के सामने ऐसा संकट आएगा जिसे केवल शक्ति हल नहीं कर सकती।'),
  ('scene-king-chooses-horse-sacrifice', 'absence-inside-abundance', 'en', 'A flourishing kingdom has no clear future', 'Despite Ayodhya''s wealth and Dasharatha''s capability, he has no son to continue the line. The contrast gives succession civic weight: the problem is not simply that a king wants a child, but that a stable realm does not know how authority and responsibility will continue after him.'),
  ('scene-king-chooses-horse-sacrifice', 'absence-inside-abundance', 'hi', 'समृद्ध राज्य का भविष्य स्पष्ट नहीं है', 'अयोध्या की संपदा और दशरथ की क्षमता के बावजूद उनका कोई पुत्र नहीं है जो वंश आगे बढ़ाए। यह विरोध उत्तराधिकार को सार्वजनिक महत्त्व देता है—समस्या केवल राजा की संतान-इच्छा नहीं, बल्कि यह है कि स्थिर राज्य को नहीं मालूम कि उनके बाद अधिकार और उत्तरदायित्व कैसे आगे बढ़ेंगे।'),
  ('scene-king-chooses-horse-sacrifice', 'idea-enters-council', 'en', 'Dasharatha refuses to decide alone', 'Dasharatha considers a horse sacrifice directed toward obtaining heirs, then calls Sumantra, the priests, and ritual specialists. He presents the proposal and asks them to assess it. Even a deeply personal hope must pass through expertise, consent, planning, and institutional memory.'),
  ('scene-king-chooses-horse-sacrifice', 'idea-enters-council', 'hi', 'दशरथ अकेले निर्णय नहीं लेते', 'दशरथ संतान-प्राप्ति के लिए अश्वमेध का विचार करते हैं, फिर सुमंत्र, पुरोहितों और अनुष्ठान-विशेषज्ञों को बुलाते हैं। वे प्रस्ताव सामने रखकर उनका मत माँगते हैं। अत्यंत निजी आशा भी विशेषज्ञता, सहमति, योजना और संस्थागत स्मृति से होकर गुजरती है।'),
  ('scene-king-chooses-horse-sacrifice', 'danger-is-named-before-action', 'en', 'The undertaking can fail if handled carelessly', 'The advisers approve but do not treat the sacrifice as automatic magic. They require exact preparation, qualified officiants, protection from disruption, a suitable ground on the Sarayu, and attention to every rule. The scene makes responsibility visible before spectacle begins.'),
  ('scene-king-chooses-horse-sacrifice', 'danger-is-named-before-action', 'hi', 'असावधानी से पूरा संकल्प विफल हो सकता है', 'सलाहकार सहमति देते हैं, पर यज्ञ को स्वतः फल देने वाला जादू नहीं मानते। वे शुद्ध तैयारी, योग्य आचार्य, विघ्न से सुरक्षा, सरयू तट पर उपयुक्त भूमि और प्रत्येक नियम पर ध्यान की माँग करते हैं। दृश्य आरंभ से पहले ही उत्तरदायित्व को स्पष्ट कर देता है।'),
  ('scene-king-chooses-horse-sacrifice', 'hope-reaches-the-queens', 'en', 'The decision returns to the family', 'After instructing the ministers, Dasharatha tells his wives that the undertaking is meant to bring children into the household. Their faces brighten after a long season of uncertainty. Public succession and intimate longing meet without becoming the same thing.'),
  ('scene-king-chooses-horse-sacrifice', 'hope-reaches-the-queens', 'hi', 'निर्णय फिर परिवार तक लौटता है', 'मंत्रियों को निर्देश देने के बाद दशरथ अपनी रानियों को बताते हैं कि यह संकल्प परिवार में संतान लाने के लिए है। लंबे अनिश्चित समय के बाद उनके चेहरे खिल उठते हैं। सार्वजनिक उत्तराधिकार और निजी आकांक्षा यहाँ मिलते हैं, पर एक-दूसरे में पूरी तरह घुलते नहीं।'),
  ('scene-rishyasringa-brought-from-seclusion', 'sumantra-remembers-a-prediction', 'en', 'An old prediction enters a present problem', 'Sumantra privately tells Dasharatha that an old teaching names Rishyasringa as the officiant connected with the birth of his sons. Rishyasringa has grown in forest seclusion under his father Vibhandaka, with little knowledge of society beyond disciplined study and service.'),
  ('scene-rishyasringa-brought-from-seclusion', 'sumantra-remembers-a-prediction', 'hi', 'पुरानी भविष्यवाणी वर्तमान संकट में लौटती है', 'सुमंत्र दशरथ को एक पुरानी भविष्यवाणी बताते हैं जिसमें ऋष्यशृंग को उनके पुत्र-जन्म से जुड़े आचार्य के रूप में नामित किया गया है। ऋष्यशृंग अपने पिता विभांडक के साथ वन के एकांत में बड़े हुए हैं और अनुशासित अध्ययन तथा सेवा के बाहर समाज का बहुत कम अनुभव रखते हैं।'),
  ('scene-rishyasringa-brought-from-seclusion', 'anga-uses-deception-against-drought', 'en', 'A kingdom in drought chooses manipulation', 'Sumantra recounts how Anga once suffered without rain and advisers sought to bring the secluded ascetic into the city. Courtesans approached him in disguise, using unfamiliar affection, food, fragrance, and performance. Devam retains the source sequence without presenting the manipulation as a model of consent.'),
  ('scene-rishyasringa-brought-from-seclusion', 'anga-uses-deception-against-drought', 'hi', 'सूखे से जूझता राज्य छल का मार्ग चुनता है', 'सुमंत्र बताते हैं कि अंग देश कभी वर्षा-विहीन हो गया था और सलाहकारों ने एकांतवासी ऋषि को नगर लाने की योजना बनाई। गणिकाएँ वेश बदलकर अपरिचित स्नेह, भोजन, सुगंध और प्रस्तुति के माध्यम से उनके पास पहुँचीं। देवम स्रोत का क्रम सुरक्षित रखता है, पर इस छल को सहमति का आदर्श नहीं मानता।'),
  ('scene-rishyasringa-brought-from-seclusion', 'rain-arrives-with-rishyasringa', 'en', 'The arrival changes Anga''s sky', 'When Rishyasringa reaches Anga, rain comes and King Romapada receives him with humility, anxious to prevent anger over the means used. Romapada joins him with Shanta, and the source moves from the troubling recruitment story toward a settled household and public relief.'),
  ('scene-rishyasringa-brought-from-seclusion', 'rain-arrives-with-rishyasringa', 'hi', 'ऋष्यशृंग के आगमन से अंग का आकाश बदलता है', 'ऋष्यशृंग के अंग पहुँचते ही वर्षा होती है। राजा रोमपाद विनम्रता से उनका स्वागत करते हैं और अपनाए गए उपाय पर उनके क्रोध से बचना चाहते हैं। रोमपाद उनका विवाह शांता से कराते हैं; स्रोत असहज बुलावे से आगे बढ़कर स्थिर गृहस्थ जीवन और सार्वजनिक राहत की ओर जाता है।'),
  ('scene-rishyasringa-brought-from-seclusion', 'shanta-rishyasringa-come-to-ayodhya', 'en', 'An alliance brings the couple to Ayodhya', 'Dasharatha travels to his friend Romapada and asks that Shanta and Rishyasringa come oversee the planned rites. They are welcomed into Ayodhya with public celebration and affection inside the household. Rishyasringa arrives not as a tool taken from a forest, but as Shanta''s husband and an honoured specialist whose cooperation is requested.'),
  ('scene-rishyasringa-brought-from-seclusion', 'shanta-rishyasringa-come-to-ayodhya', 'hi', 'सहयोग शांता और ऋष्यशृंग को अयोध्या लाता है', 'दशरथ अपने मित्र रोमपाद के पास जाकर शांता और ऋष्यशृंग से नियोजित अनुष्ठानों का संचालन करने का अनुरोध करते हैं। अयोध्या में उनका सार्वजनिक उत्सव और परिवार के स्नेह से स्वागत होता है। ऋष्यशृंग अब वन से लाए गए साधन नहीं, शांता के पति और सम्मानित विशेषज्ञ के रूप में आते हैं जिनका सहयोग माँगा गया है।'),
  ('scene-sacrifice-city-rises', 'horse-leaves-and-clock-begins', 'en', 'The horse is released and a year begins', 'In spring, Rishyasringa tells Dasharatha to gather provisions, release the consecrated horse, and prepare the ground north of the Sarayu. The undertaking stretches across seasons; its scale is established through waiting, supervision, and repeated preparation rather than one spectacular day.'),
  ('scene-sacrifice-city-rises', 'horse-leaves-and-clock-begins', 'hi', 'अश्व छोड़ा जाता है और एक वर्ष की घड़ी चलती है', 'वसंत में ऋष्यशृंग दशरथ से सामग्री जुटाने, यज्ञ-अश्व छोड़ने और सरयू के उत्तर तट पर भूमि तैयार करने को कहते हैं। यह संकल्प ऋतुओं तक फैलता है; उसका विस्तार एक चमत्कारी दिन से नहीं, प्रतीक्षा, निगरानी और बार-बार की तैयारी से बनता है।'),
  ('scene-sacrifice-city-rises', 'workers-build-a-temporary-world', 'en', 'Many kinds of work build the ritual ground', 'Vasishta coordinates priests, builders, carpenters, cooks, water carriers, accountants, guards, servants, and experienced elders. Roads, pavilions, residences, kitchens, storage, animal shelters, and water systems rise together. Ritual precision depends on ordinary labour being visible and supported.'),
  ('scene-sacrifice-city-rises', 'workers-build-a-temporary-world', 'hi', 'अनेक प्रकार का श्रम अनुष्ठान-स्थल बनाता है', 'वसिष्ठ पुरोहितों, निर्माणकारों, बढ़इयों, रसोइयों, जल-वाहकों, लेखाकारों, रक्षकों, सेवकों और अनुभवी बुज़ुर्गों का समन्वय करते हैं। सड़कें, मंडप, आवास, रसोई, भंडार, पशु-स्थल और जल-व्यवस्था साथ बनते हैं। अनुष्ठान की शुद्धता साधारण श्रम को देखने और सहारा देने पर निर्भर है।'),
  ('scene-sacrifice-city-rises', 'hospitality-is-not-optional', 'en', 'Every guest must be fed and respected', 'Kings, learned guests, families, travellers, workers, and people from different regions are invited and housed. The instructions repeatedly insist that food and regard must not be distributed carelessly or contemptuously. A rite meant to secure the future cannot be built on humiliation in the present.'),
  ('scene-sacrifice-city-rises', 'hospitality-is-not-optional', 'hi', 'हर अतिथि को भोजन और सम्मान मिलना चाहिए', 'राजाओं, विद्वानों, परिवारों, यात्रियों, श्रमिकों और अलग-अलग क्षेत्रों के लोगों को बुलाकर ठहराया जाता है। निर्देश बार-बार कहते हैं कि भोजन और सम्मान लापरवाही या तिरस्कार से न बाँटे जाएँ। भविष्य सुरक्षित करने वाला अनुष्ठान वर्तमान में अपमान पर नहीं खड़ा हो सकता।'),
  ('scene-sacrifice-city-rises', 'horse-returns-and-rite-completes', 'en', 'The returning horse closes one vow and opens another', 'After a full year the horse returns and the officiants complete the demanding sequence on the Sarayu. Dasharatha gives lavish gifts, but Rishyasringa''s promise matters most: four sons will be born. The horse sacrifice ends, and a more focused rite for offspring begins.'),
  ('scene-sacrifice-city-rises', 'horse-returns-and-rite-completes', 'hi', 'लौटता अश्व एक संकल्प पूरा कर दूसरा खोलता है', 'पूरा वर्ष बीतने पर अश्व लौटता है और आचार्य सरयू तट पर कठिन अनुष्ठान-क्रम पूरा करते हैं। दशरथ बड़े दान देते हैं, पर सबसे महत्त्वपूर्ण ऋष्यशृंग का आश्वासन है—चार पुत्र जन्म लेंगे। अश्वमेध समाप्त होता है और संतान के लिए अधिक केंद्रित अनुष्ठान आरंभ होता है।'),
  ('scene-gods-name-ravana-problem', 'rite-turns-toward-sons', 'en', 'Rishyasringa begins the son-conferring rite', 'Rishyasringa uses the prescribed mantras and offerings for the focused rite Dasharatha requested. The household''s hope remains present, but the narrative viewpoint widens as celestial beings gather for their shares and bring a danger that extends far beyond Ayodhya.'),
  ('scene-gods-name-ravana-problem', 'rite-turns-toward-sons', 'hi', 'ऋष्यशृंग पुत्र-प्राप्ति का अनुष्ठान आरंभ करते हैं', 'ऋष्यशृंग दशरथ की संतान-कामना के लिए निर्धारित मंत्रों और आहुतियों से केंद्रित अनुष्ठान आरंभ करते हैं। परिवार की आशा बनी रहती है, पर कथा का दृष्टिकोण फैल जाता है—देवता अपने भाग के लिए आते हैं और अयोध्या से बहुत बड़ा संकट सामने रखते हैं।'),
  ('scene-gods-name-ravana-problem', 'ravana-protected-by-boon', 'en', 'A boon has become shelter for abuse', 'The gods tell Brahma that Ravana uses the protection earned through austerity to terrorise worlds, obstruct sacred practice, and act without restraint. The problem is not strength by itself; it is power insulated from consequence by the terms of an old boon.'),
  ('scene-gods-name-ravana-problem', 'ravana-protected-by-boon', 'hi', 'एक वरदान अत्याचार की ढाल बन गया है', 'देवता ब्रह्मा से कहते हैं कि रावण तपस्या से मिले संरक्षण का उपयोग लोकों को आतंकित करने, साधना में विघ्न डालने और बिना मर्यादा चलने के लिए करता है। समस्या केवल शक्ति नहीं, बल्कि पुराने वरदान की शर्तों से परिणामों से बची हुई शक्ति है।'),
  ('scene-gods-name-ravana-problem', 'forgotten-human-exception', 'en', 'The ignored possibility becomes the opening', 'Brahma remembers the exact boundary of his promise: Ravana asked protection from powerful classes of beings but dismissed humans as beneath concern. The loophole is not invented after the fact; it lies inside Ravana''s own contempt and the source''s stated terms.'),
  ('scene-gods-name-ravana-problem', 'forgotten-human-exception', 'hi', 'जिस संभावना को तुच्छ समझा गया वही मार्ग बनती है', 'ब्रह्मा अपने वरदान की ठीक सीमा याद करते हैं—रावण ने शक्तिशाली प्राणी-वर्गों से सुरक्षा माँगी थी, पर मनुष्यों को तुच्छ समझकर छोड़ दिया। यह मार्ग बाद में बनाया गया बहाना नहीं; वह रावण के अपने अहंकार और स्रोत में कही शर्तों के भीतर मौजूद है।'),
  ('scene-gods-name-ravana-problem', 'assembly-turns-to-vishnu', 'en', 'The gods ask Vishnu to enter human life', 'The assembly turns to Vishnu and asks him to take human birth, uproot Ravana''s violence, and relieve the worlds. The request does not yet decide the family or form; that answer will connect the cosmic problem directly to Dasharatha''s waiting household.'),
  ('scene-gods-name-ravana-problem', 'assembly-turns-to-vishnu', 'hi', 'देवता विष्णु से मानव जीवन में आने का अनुरोध करते हैं', 'सभा विष्णु से मानव जन्म लेने, रावण की हिंसा का अंत करने और लोकों को राहत देने का अनुरोध करती है। अभी परिवार और रूप निश्चित नहीं हुआ है; अगला उत्तर इस व्यापक संकट को सीधे दशरथ के प्रतीक्षारत परिवार से जोड़ेगा।'),
  ('scene-vishnu-chooses-fourfold-birth', 'vishnu-accepts-human-form', 'en', 'Vishnu chooses the disregarded human path', 'Vishnu asks the gods to state the means clearly, then accepts their answer: Ravana can be defeated through human form. He chooses to be born in four portions among Dasharatha''s sons, joining the cosmic response to a real family rather than appearing as a detached weapon.'),
  ('scene-vishnu-chooses-fourfold-birth', 'vishnu-accepts-human-form', 'hi', 'विष्णु उपेक्षित मानव मार्ग चुनते हैं', 'विष्णु देवताओं से उपाय स्पष्ट कहने को कहते हैं, फिर उत्तर स्वीकार करते हैं—रावण का अंत मानव रूप से संभव है। वे दशरथ के पुत्रों में चार अंशों के रूप में जन्म लेने का निर्णय करते हैं; इस तरह व्यापक उत्तर किसी अलग हथियार की तरह नहीं, वास्तविक परिवार के भीतर आता है।'),
  ('scene-vishnu-chooses-fourfold-birth', 'being-rises-from-fire', 'en', 'A messenger emerges carrying the food', 'A radiant, formidable being rises from the fire holding a golden vessel of payasa prepared by the gods. He identifies himself as a messenger and tells Dasharatha to give the food to his wives. The invisible decision becomes a concrete act the family must perform.'),
  ('scene-vishnu-chooses-fourfold-birth', 'being-rises-from-fire', 'hi', 'अग्नि से प्रसाद लिए एक दूत प्रकट होता है', 'अग्नि से एक तेजस्वी और प्रभावशाली पुरुष स्वर्ण-पात्र में देवताओं द्वारा तैयार पायस लेकर प्रकट होता है। वह स्वयं को दूत बताकर दशरथ से यह प्रसाद अपनी रानियों को देने को कहता है। अदृश्य निर्णय अब परिवार द्वारा किए जाने वाले ठोस कार्य में बदल जाता है।'),
  ('scene-vishnu-chooses-fourfold-birth', 'dasharatha-distributes-payasa', 'en', 'Dasharatha shares the vessel among the queens', 'Dasharatha receives the vessel reverently and distributes its portions among Kausalya, Sumitra, and Kaikeyi, with Sumitra receiving from the shared division twice. The scene is intimate and deliberate: the future brothers enter the story through one vessel distributed across relationships.'),
  ('scene-vishnu-chooses-fourfold-birth', 'dasharatha-distributes-payasa', 'hi', 'दशरथ प्रसाद को रानियों में बाँटते हैं', 'दशरथ पात्र को आदर से ग्रहण करके उसका भाग कौसल्या, सुमित्रा और कैकेयी में बाँटते हैं; साझा विभाजन में सुमित्रा को दो बार अंश मिलता है। दृश्य निजी और सावधान है—भावी भाई एक ही पात्र से रिश्तों के बीच बाँटे गए प्रसाद के माध्यम से कथा में प्रवेश करते हैं।'),
  ('scene-vishnu-chooses-fourfold-birth', 'waiting-becomes-pregnancy', 'en', 'The household''s long uncertainty changes form', 'After receiving the payasa, the queens become pregnant, and Dasharatha sees the hoped-for future begin to take shape. The source compares their radiance to fire and sun; the turn ends before the births, holding the family in expectant transformation.'),
  ('scene-vishnu-chooses-fourfold-birth', 'waiting-becomes-pregnancy', 'hi', 'परिवार की लंबी प्रतीक्षा नया रूप लेती है', 'पायस ग्रहण करने के बाद रानियाँ गर्भवती होती हैं और दशरथ अपनी प्रतीक्षित भविष्य-रेखा को आकार लेते देखते हैं। स्रोत उनकी दीप्ति की तुलना अग्नि और सूर्य से करता है; दृश्य जन्म से पहले रुकता है और परिवार को आशापूर्ण परिवर्तन में थामे रखता है।'),
  ('scene-allies-born-for-future-war', 'brahma-asks-for-allies', 'en', 'A human hero will not be sent alone', 'After Vishnu accepts human birth, Brahma asks the gods and other celestial beings to create powerful allies able to change form, move with extraordinary speed, understand strategy, resist weapons, and act with intelligence. The response to Ravana is designed as cooperation, not solitary destiny.'),
  ('scene-allies-born-for-future-war', 'brahma-asks-for-allies', 'hi', 'मानव नायक को अकेला नहीं भेजा जाएगा', 'विष्णु के मानव जन्म स्वीकार करने के बाद ब्रह्मा देवताओं और अन्य दिव्य प्राणियों से ऐसे शक्तिशाली सहयोगी उत्पन्न करने को कहते हैं जो रूप बदल सकें, तीव्र गति से चलें, नीति समझें, अस्त्र सह सकें और बुद्धि से काम लें। रावण के विरुद्ध उत्तर अकेली नियति नहीं, सहयोग के रूप में बनाया जाता है।'),
  ('scene-allies-born-for-future-war', 'future-leaders-take-form', 'en', 'The future leaders appear in different lineages', 'The source names future vanara and bear leaders connected with different divine powers: Vali, Sugriva, Tara, Nala, Nila, Mainda, Dvivida, Sushena, Sharabha, and the already-created Jambavan. Their varied origins anticipate distinct abilities rather than one interchangeable army.'),
  ('scene-allies-born-for-future-war', 'future-leaders-take-form', 'hi', 'भावी नेता अलग-अलग वंशों में जन्म लेते हैं', 'स्रोत अलग-अलग दिव्य शक्तियों से जुड़े भावी वानर और ऋक्ष नेताओं के नाम लेता है—वालि, सुग्रीव, तार, नल, नील, मैंद, द्विविद, सुषेण, शरभ और पहले से उत्पन्न जाम्बवान। उनकी विविध उत्पत्तियाँ एक जैसी सेना नहीं, अलग-अलग क्षमताओं का संकेत देती हैं।'),
  ('scene-allies-born-for-future-war', 'hanuman-carries-wind-and-thunder', 'en', 'Hanuman enters with the force of wind', 'Hanuman is born through the wind-god''s power, with immense strength and movement compared to thunder and storm. At this point he has not met Rama and no devotion scene is invented; the narrative simply places his capacity in the world long before the relationship that will give it direction.'),
  ('scene-allies-born-for-future-war', 'hanuman-carries-wind-and-thunder', 'hi', 'हनुमान वायु के वेग के साथ कथा में आते हैं', 'हनुमान वायु-देव की शक्ति से जन्म लेते हैं; उनकी गति और बल की तुलना तूफ़ान तथा गर्जना से की जाती है। अभी उनकी राम से भेंट नहीं हुई है और यहाँ कोई बाद की भक्ति-कथा नहीं जोड़ी जाती; कथा केवल उनकी क्षमता को उस संबंध से बहुत पहले संसार में रखती है जो उसे दिशा देगा।'),
  ('scene-allies-born-for-future-war', 'earth-fills-with-unmet-companions', 'en', 'The world fills with companions who have not met', 'Mountains, forests, caves, and ocean edges become home to immense communities of vanaras, bears, and related beings. They carry strength, intelligence, distinctive marks, and local leadership. The scene closes on dramatic irony: the network that will help Rama already exists, but none of its members yet knows the story that will connect them.'),
  ('scene-allies-born-for-future-war', 'earth-fills-with-unmet-companions', 'hi', 'संसार उन साथियों से भरता है जो अभी मिले नहीं हैं', 'पर्वत, वन, गुफाएँ और समुद्र-तट वानरों, ऋक्षों और संबंधित प्राणियों के विशाल समुदायों का घर बनते हैं। उनके पास बल, बुद्धि, अलग पहचान और स्थानीय नेतृत्व है। दृश्य इस विडंबना पर समाप्त होता है कि राम की सहायता करने वाला जाल पहले से मौजूद है, पर उसके सदस्य अभी उस कथा को नहीं जानते जो उन्हें जोड़ेगी।'),
  ('scene-four-princes-grow-together', 'seasons-end-in-four-births', 'en', 'The waiting ends across three chambers', 'After the rite, six seasons pass before the births. Kausalya gives birth to Rama, Kaikeyi to Bharata, and Sumitra to Lakshmana and Shatrughna. The selected source surrounds the moment with auspicious celestial timing, but the emotional centre is a household finally receiving four children.'),
  ('scene-four-princes-grow-together', 'seasons-end-in-four-births', 'hi', 'तीन कक्षों में लंबी प्रतीक्षा समाप्त होती है', 'अनुष्ठान के बाद छह ऋतुएँ बीतती हैं। कौसल्या राम को, कैकेयी भरत को और सुमित्रा लक्ष्मण तथा शत्रुघ्न को जन्म देती हैं। चुना हुआ स्रोत इस क्षण को शुभ आकाशीय समय से घेरता है, पर भावनात्मक केंद्र वह परिवार है जिसे अंततः चार बच्चे मिलते हैं।'),
  ('scene-four-princes-grow-together', 'ayodhya-celebrates-and-names', 'en', 'The city celebrates before the children are named', 'Music, gifts, food, and public joy spread through Ayodhya. On the appointed day Vasishta names Rama, Bharata, Lakshmana, and Shatrughna. The names distinguish the four boys, while the shared celebration presents their arrival as a civic event as well as a family one.'),
  ('scene-four-princes-grow-together', 'ayodhya-celebrates-and-names', 'hi', 'नामकरण से पहले पूरा नगर उत्सव मनाता है', 'संगीत, दान, भोजन और सार्वजनिक आनंद अयोध्या में फैलते हैं। नियत दिन वसिष्ठ राम, भरत, लक्ष्मण और शत्रुघ्न का नामकरण करते हैं। नाम चारों बालकों को अलग पहचान देते हैं, जबकि साझा उत्सव उनके आगमन को पारिवारिक ही नहीं, नागरिक घटना भी बनाता है।'),
  ('scene-four-princes-grow-together', 'princes-learn-many-disciplines', 'en', 'Childhood becomes disciplined preparation', 'The princes grow through study, physical training, weapons practice, riding, public conduct, and attention to elders. Rama becomes especially admired, but the source keeps all four inside the same education. Their abilities develop through repeated work rather than arriving complete at birth.'),
  ('scene-four-princes-grow-together', 'princes-learn-many-disciplines', 'hi', 'बाल्यकाल अनुशासित तैयारी में बदलता है', 'राजकुमार अध्ययन, शारीरिक प्रशिक्षण, अस्त्र-अभ्यास, सवारी, सार्वजनिक आचरण और बड़ों के प्रति ध्यान के साथ बड़े होते हैं। राम विशेष रूप से प्रिय बनते हैं, पर स्रोत चारों को एक ही शिक्षा-व्यवस्था में रखता है। उनकी क्षमताएँ जन्म से पूर्ण नहीं, निरंतर अभ्यास से विकसित होती हैं।'),
  ('scene-four-princes-grow-together', 'two-brother-pairs-form', 'en', 'Lakshmana follows Rama; Shatrughna follows Bharata', 'Lakshmana becomes so attached to Rama that food and rest feel incomplete without him; Shatrughna forms a similar bond with Bharata. These are not interchangeable companions. The two pairings create emotional routes that will later pull the family across exile, absence, governance, and war.'),
  ('scene-four-princes-grow-together', 'two-brother-pairs-form', 'hi', 'लक्ष्मण राम से और शत्रुघ्न भरत से गहराई से जुड़ते हैं', 'लक्ष्मण राम से इतने जुड़े रहते हैं कि उनके बिना भोजन और विश्राम भी अधूरा लगता है; शत्रुघ्न का ऐसा ही संबंध भरत से बनता है। ये साथी एक-दूसरे के स्थान पर रखे जा सकने वाले नहीं हैं। दोनों भाई-युगल आगे वनवास, दूरी, शासन और युद्ध में परिवार की भावनात्मक राह तय करेंगे।'),
  ('scene-vishvamitra-asks-for-rama', 'vishvamitra-enters-court', 'en', 'Ayodhya receives a formidable ascetic', 'Vishvamitra arrives at Dasharatha''s court and is welcomed with ritual respect, questions of wellbeing, and an open promise of assistance. Dasharatha speaks generously before knowing the request, placing his reputation for truth and hospitality inside the decision that follows.'),
  ('scene-vishvamitra-asks-for-rama', 'vishvamitra-enters-court', 'hi', 'अयोध्या एक प्रबल तपस्वी का स्वागत करती है', 'विश्वामित्र दशरथ के दरबार में आते हैं और उनका विधिपूर्वक सम्मान, कुशल-प्रश्न तथा सहायता के खुले आश्वासन से स्वागत होता है। दशरथ माँग जानने से पहले उदार वचन देते हैं; आगे का निर्णय अब उनकी सत्यनिष्ठा और आतिथ्य की प्रतिष्ठा से जुड़ जाता है।'),
  ('scene-vishvamitra-asks-for-rama', 'sacrifice-is-under-attack', 'en', 'Maricha and Subahu repeatedly break the rite', 'Vishvamitra explains that Maricha and Subahu can change form and shower blood and flesh onto the altar just as his sacrifice nears completion. Bound by his own discipline during the rite, he will not answer their violence with anger or a curse. He needs protection that can act while he remains committed to the vow.'),
  ('scene-vishvamitra-asks-for-rama', 'sacrifice-is-under-attack', 'hi', 'मारीच और सुबाहु बार-बार अनुष्ठान भंग करते हैं', 'विश्वामित्र बताते हैं कि मारीच और सुबाहु रूप बदलकर अनुष्ठान पूर्ण होने के समय वेदी पर रक्त और मांस बरसाते हैं। यज्ञ-व्रत के दौरान वे स्वयं क्रोध या शाप से उत्तर नहीं देंगे। उन्हें ऐसी रक्षा चाहिए जो उनके संकल्प में स्थिर रहते हुए बाहर से कार्य कर सके।'),
  ('scene-vishvamitra-asks-for-rama', 'request-names-rama-alone', 'en', 'The requested protector is not Dasharatha''s army', 'Vishvamitra asks for Rama for ten nights, insisting that the prince can defeat the attackers under his guidance. The precision shocks the court: an army, senior champion, or royal escort would leave the family hierarchy intact, but the request specifically removes the treasured young heir from palace protection.'),
  ('scene-vishvamitra-asks-for-rama', 'request-names-rama-alone', 'hi', 'माँग दशरथ की सेना नहीं, राम की है', 'विश्वामित्र दस रातों के लिए राम को माँगते हैं और कहते हैं कि उनके मार्गदर्शन में राजकुमार आक्रमणकारियों को परास्त कर सकता है। माँग की स्पष्टता दरबार को स्तब्ध करती है—सेना या वरिष्ठ योद्धा भेजने से परिवार की व्यवस्था बनी रहती, पर यहाँ प्रिय युवा उत्तराधिकारी को ही महल की सुरक्षा से बाहर ले जाना है।'),
  ('scene-vishvamitra-asks-for-rama', 'dasharatha-collapses-under-request', 'en', 'A public promise collides with a father''s fear', 'Dasharatha trembles and loses composure when he understands the request. The scene does not mock his attachment: the long-awaited child has barely entered youth, and the named enemies are experienced in deception. Courtly confidence gives way to a father''s immediate terror of loss.'),
  ('scene-vishvamitra-asks-for-rama', 'dasharatha-collapses-under-request', 'hi', 'सार्वजनिक वचन पिता के भय से टकराता है', 'माँग का अर्थ समझते ही दशरथ काँप उठते हैं और उनका संतुलन टूट जाता है। दृश्य उनके स्नेह का उपहास नहीं करता—लंबे समय से प्रतीक्षित पुत्र अभी किशोर है और सामने बताए गए शत्रु छल-युद्ध में अनुभवी हैं। राजकीय आत्मविश्वास एक पिता के तत्काल वियोग-भय में बदल जाता है।'),
  ('scene-dasharatha-cannot-release-his-son', 'rama-is-not-yet-sixteen', 'en', 'Dasharatha names Rama''s youth', 'Recovering from shock, Dasharatha says Rama is not yet sixteen and lacks experience against shape-changing attackers. The objection is concrete rather than cowardly: training inside Ayodhya is not the same as reading an unpredictable battlefield where opponents use terror and deception.'),
  ('scene-dasharatha-cannot-release-his-son', 'rama-is-not-yet-sixteen', 'hi', 'दशरथ राम की कम आयु सामने रखते हैं', 'आघात से सँभलकर दशरथ कहते हैं कि राम अभी सोलह वर्ष के भी नहीं हैं और रूप बदलने वाले आक्रमणकारियों से लड़ने का अनुभव नहीं रखते। आपत्ति ठोस है—अयोध्या का प्रशिक्षण उस अनिश्चित युद्धभूमि के समान नहीं जहाँ शत्रु भय और छल का उपयोग करते हैं।'),
  ('scene-dasharatha-cannot-release-his-son', 'king-offers-himself-and-army', 'en', 'Take my army; let me stand in front', 'Dasharatha offers his full army and his own bow, promising to guard the sacrifice as long as he lives. He is not refusing the public duty; he is attempting to absorb its danger himself. Yet every substitute changes the request Vishvamitra deliberately made.'),
  ('scene-dasharatha-cannot-release-his-son', 'king-offers-himself-and-army', 'hi', 'मेरी सेना ले जाइए, मैं स्वयं आगे खड़ा रहूँगा', 'दशरथ अपनी पूरी सेना और स्वयं अपना धनुष देने का प्रस्ताव रखते हैं; वे जीवन रहते अनुष्ठान की रक्षा का वचन देते हैं। वे सार्वजनिक कर्तव्य से भाग नहीं रहे, बल्कि संकट को अपने ऊपर लेना चाहते हैं। फिर भी हर विकल्प विश्वामित्र की सोच-समझकर की गई माँग को बदल देता है।'),
  ('scene-dasharatha-cannot-release-his-son', 'ravana-name-deepens-fear', 'en', 'The shadow behind the attackers is Ravana', 'When Dasharatha learns that Maricha and Subahu operate under Ravana''s wider power, his fear intensifies. He describes Ravana as beyond his own capacity and concludes that neither he nor Rama can face such a threat. Information meant to clarify the mission instead enlarges the imagined catastrophe.'),
  ('scene-dasharatha-cannot-release-his-son', 'ravana-name-deepens-fear', 'hi', 'आक्रमणकारियों के पीछे रावण की छाया है', 'जब दशरथ जानते हैं कि मारीच और सुबाहु के पीछे रावण की व्यापक शक्ति है, उनका भय और बढ़ता है। वे रावण को अपनी क्षमता से भी परे बताते हैं और मान लेते हैं कि न वे, न राम ऐसा संकट झेल सकते हैं। मिशन स्पष्ट करने वाली सूचना उनके मन में विनाश की छवि और बड़ी कर देती है।'),
  ('scene-dasharatha-cannot-release-his-son', 'fear-hardens-into-refusal', 'en', 'Dasharatha withdraws the promise', 'Dasharatha finally says he will not part with Rama and asks Vishvamitra to abandon the request. The earlier open promise is now in danger of becoming false. Vishvamitra''s anger rises because the king sought the honour of generosity without accepting the cost of the specific help requested.'),
  ('scene-dasharatha-cannot-release-his-son', 'fear-hardens-into-refusal', 'hi', 'दशरथ अपना वचन वापस लेने लगते हैं', 'अंततः दशरथ कहते हैं कि वे राम से अलग नहीं होंगे और विश्वामित्र से माँग छोड़ने की विनती करते हैं। पहले दिया खुला वचन अब असत्य होने की ओर बढ़ता है। विश्वामित्र का क्रोध इसलिए उठता है कि राजा ने उदारता का सम्मान तो चाहा, पर माँगी गई विशेष सहायता की कीमत स्वीकार नहीं की।'),
  ('scene-vasishta-makes-promise-actionable', 'anger-shakes-the-court', 'en', 'Vishvamitra names the broken promise', 'Vishvamitra tells Dasharatha that offering help and then retracting it is unworthy of the Raghu line. His anger unsettles the court and even the earth in the source''s heightened telling. The conflict can no longer be softened into a misunderstanding about logistics.'),
  ('scene-vasishta-makes-promise-actionable', 'anger-shakes-the-court', 'hi', 'विश्वामित्र टूटते वचन को स्पष्ट नाम देते हैं', 'विश्वामित्र दशरथ से कहते हैं कि सहायता का वचन देकर पीछे हटना रघुवंश के योग्य नहीं है। स्रोत की तीव्र कथा में उनका क्रोध दरबार और पृथ्वी तक को विचलित करता है। अब विवाद को केवल व्यवस्था की गलतफहमी कहकर हल्का नहीं किया जा सकता।'),
  ('scene-vasishta-makes-promise-actionable', 'vasishta-restates-the-duty', 'en', 'A ruler''s word must survive private fear', 'Vasishta reminds Dasharatha that truthfulness is not an ornament for easy moments. As king, he cannot let affection erase a promise made before the court. But Vasishta does not stop at moral pressure; he turns immediately to whether Rama will actually be safe.'),
  ('scene-vasishta-makes-promise-actionable', 'vasishta-restates-the-duty', 'hi', 'राजा का वचन निजी भय से बड़ा होना चाहिए', 'वसिष्ठ दशरथ को याद दिलाते हैं कि सत्यनिष्ठा केवल आसान समय की सजावट नहीं है। राजा होकर वे स्नेह के कारण दरबार में दिए वचन को मिटा नहीं सकते। पर वसिष्ठ केवल नैतिक दबाव पर नहीं रुकते; वे तुरंत इस प्रश्न पर आते हैं कि राम वास्तव में सुरक्षित रहेंगे या नहीं।'),
  ('scene-vasishta-makes-promise-actionable', 'vishvamitra-is-the-protection', 'en', 'The guide asking for Rama is also his strongest protection', 'Vasishta describes Vishvamitra''s command of weapons, knowledge, discipline, and powers inherited or mastered through austerity. He insists the ascetic could defeat the attackers himself and seeks Rama for the prince''s welfare and growth. The mission is supervised apprenticeship, not abandonment.'),
  ('scene-vasishta-makes-promise-actionable', 'vishvamitra-is-the-protection', 'hi', 'राम को माँगने वाले मार्गदर्शक ही उनकी सबसे बड़ी रक्षा हैं', 'वसिष्ठ विश्वामित्र के अस्त्र-ज्ञान, अनुशासन और तप से अर्जित शक्तियों का वर्णन करते हैं। वे कहते हैं कि ऋषि स्वयं आक्रमणकारियों को परास्त कर सकते हैं और राम को उनके हित तथा विकास के लिए माँग रहे हैं। यह त्याग नहीं, संरक्षित शिक्षुता है।'),
  ('scene-vasishta-makes-promise-actionable', 'dasharatha-consents-with-knowledge', 'en', 'Consent follows evidence, not exhaustion', 'Dasharatha''s decision changes after Vasishta supplies a credible protection model. He can now keep his word without pretending the danger is small. The king begins preparing to entrust Rama to Vishvamitra, and fear becomes a careful farewell rather than a permanent veto.'),
  ('scene-vasishta-makes-promise-actionable', 'dasharatha-consents-with-knowledge', 'hi', 'सहमति थकान से नहीं, जानकारी से आती है', 'वसिष्ठ द्वारा विश्वसनीय सुरक्षा-व्यवस्था समझाने के बाद दशरथ का निर्णय बदलता है। अब वे संकट को छोटा बताए बिना अपना वचन निभा सकते हैं। राजा राम को विश्वामित्र के साथ भेजने की तैयारी करते हैं और भय स्थायी रोक के बजाय सावधान विदाई बन जाता है।'),
  ('scene-rama-lakshmana-leave-palace', 'farewell-becomes-formal-trust', 'en', 'The family performs the farewell it feared', 'Dasharatha summons Rama and Lakshmana. Parents and Vasishta perform blessings and protective rites; Dasharatha embraces and formally entrusts Rama to Vishvamitra. The goodbye does not erase grief, but gives it a shape the family can act through.'),
  ('scene-rama-lakshmana-leave-palace', 'farewell-becomes-formal-trust', 'hi', 'परिवार वही विदाई निभाता है जिससे वह डरता था', 'दशरथ राम और लक्ष्मण को बुलाते हैं। माता-पिता और वसिष्ठ आशीर्वाद तथा रक्षा-विधि करते हैं; दशरथ राम को गले लगाकर औपचारिक रूप से विश्वामित्र को सौंपते हैं। विदाई दुःख मिटाती नहीं, पर उसे ऐसा रूप देती है जिसके भीतर परिवार कार्य कर सके।'),
  ('scene-rama-lakshmana-leave-palace', 'three-figures-take-the-road', 'en', 'Vishvamitra leads; the brothers follow', 'Vishvamitra walks first, Rama follows with bow and quiver, and Lakshmana follows Rama. The compact formation makes their relationships visible: guide, principal learner, and brother-companion. Celestial celebration in the source contrasts with the very human distance opening behind them.'),
  ('scene-rama-lakshmana-leave-palace', 'three-figures-take-the-road', 'hi', 'विश्वामित्र आगे चलते हैं और दोनों भाई पीछे', 'विश्वामित्र सबसे आगे, धनुष-तरकश के साथ राम उनके पीछे और लक्ष्मण राम के पीछे चलते हैं। यह छोटा क्रम संबंध स्पष्ट करता है—मार्गदर्शक, मुख्य शिक्षार्थी और भाई-सहचर। स्रोत का दिव्य उत्सव पीछे बढ़ती मानवीय दूरी के साथ विरोध रचता है।'),
  ('scene-rama-lakshmana-leave-palace', 'bala-atibala-received', 'en', 'The first weapons are disciplines of endurance', 'Beside the Sarayu, Vishvamitra teaches Rama Bala and Atibala, disciplines the source says protect against fatigue, hunger, surprise, and loss of mental clarity. Before giving destructive weapons, the teacher strengthens attention and endurance—the capacities needed to decide well under pressure.'),
  ('scene-rama-lakshmana-leave-palace', 'bala-atibala-received', 'hi', 'पहली विद्याएँ सहनशक्ति और सजगता की हैं', 'सरयू के किनारे विश्वामित्र राम को बला और अतिबला सिखाते हैं, जिन्हें स्रोत थकान, भूख, अचानक आक्रमण और मानसिक भ्रम से रक्षा करने वाली विद्याएँ बताता है। विनाशकारी अस्त्रों से पहले गुरु ध्यान और सहनशक्ति मजबूत करते हैं—दबाव में सही निर्णय के लिए आवश्यक क्षमताएँ।'),
  ('scene-rama-lakshmana-leave-palace', 'first-night-on-grass', 'en', 'The palace bed becomes riverbank grass', 'The brothers perform their duties toward Vishvamitra and spend the night on a bed of grass. Conversation with the guide makes the unfamiliar camp bearable. The first day ends without battle: leaving comfort, learning to listen, and sleeping outside are already part of the transformation.'),
  ('scene-rama-lakshmana-leave-palace', 'first-night-on-grass', 'hi', 'महल की शय्या सरयू तट की घास बन जाती है', 'दोनों भाई विश्वामित्र के प्रति शिष्य-कर्तव्य निभाकर घास की शय्या पर रात बिताते हैं। गुरु का संवाद अपरिचित शिविर को सहज बनाता है। पहला दिन बिना युद्ध समाप्त होता है—सुविधा छोड़ना, सुनना सीखना और खुले में सोना स्वयं परिवर्तन का हिस्सा हैं।'),
  ('scene-rivers-open-remembered-worlds', 'morning-discipline-starts-road', 'en', 'The road begins with daily practice', 'Vishvamitra wakes the brothers before dawn. They bathe, complete morning observances, greet their guide, and resume walking. Heroic travel is paced by repeated care of body, attention, and relationship; the story does not jump directly from palace to combat.'),
  ('scene-rivers-open-remembered-worlds', 'morning-discipline-starts-road', 'hi', 'रोज़ की साधना से यात्रा फिर शुरू होती है', 'विश्वामित्र भोर से पहले दोनों भाइयों को जगाते हैं। वे स्नान, प्रातः-उपासना और गुरु-अभिवादन के बाद फिर चल पड़ते हैं। वीर यात्रा शरीर, ध्यान और संबंध की दोहराई जाने वाली देखभाल से चलती है; कथा महल से सीधे युद्ध पर नहीं कूदती।'),
  ('scene-rivers-open-remembered-worlds', 'confluence-remembers-kama', 'en', 'A peaceful hermitage remembers desire burned away', 'At the Sarayu-Ganga region, Rama asks about an old hermitage. Vishvamitra connects it with Shiva''s austerity and the burning of Kama, explaining why the place carries the memory of the bodiless god of desire. The landscape becomes more than scenery because curiosity unlocks its layered past.'),
  ('scene-rivers-open-remembered-worlds', 'confluence-remembers-kama', 'hi', 'शांत आश्रम काम-दहन की स्मृति रखता है', 'सरयू-गंगा क्षेत्र में राम एक पुराने आश्रम के बारे में पूछते हैं। विश्वामित्र उसे शिव की तपस्या और काम-दहन से जोड़ते हैं और बताते हैं कि यह स्थान देह-विहीन कामदेव की स्मृति क्यों रखता है। जिज्ञासा भू-दृश्य की परतें खोलती है और स्थान केवल दृश्य नहीं रहता।'),
  ('scene-rivers-open-remembered-worlds', 'ganga-crossing-explains-sound', 'en', 'The river itself asks a question', 'While crossing the Ganga, the brothers hear a powerful sound where waters meet. Rama asks rather than pretending to know, and Vishvamitra explains the joining currents. Travel repeatedly rewards attention: sound, current, and direction become portals into knowledge of place.'),
  ('scene-rivers-open-remembered-worlds', 'ganga-crossing-explains-sound', 'hi', 'नदी की ध्वनि स्वयं एक प्रश्न बनती है', 'गंगा पार करते समय दोनों भाई जलधाराओं के मिलने की प्रबल ध्वनि सुनते हैं। राम जानने का दिखावा नहीं करते, प्रश्न पूछते हैं और विश्वामित्र संगम की धाराएँ समझाते हैं। यात्रा में ध्यान का पुरस्कार मिलता है—ध्वनि, प्रवाह और दिशा स्थान-ज्ञान के द्वार बनते हैं।'),
  ('scene-rivers-open-remembered-worlds', 'prosperous-lands-become-tataka-forest', 'en', 'Remembered prosperity gives way to an emptied forest', 'Vishvamitra recounts how the once-prosperous lands of Malada and Karusha became depopulated under Tataka''s violence. The travellers enter a forest defined by absence—broken routes, abandoned settlement, and fear. The next choice will concern not an abstract monster but a damaged inhabited world.'),
  ('scene-rivers-open-remembered-worlds', 'prosperous-lands-become-tataka-forest', 'hi', 'पुरानी समृद्धि उजड़े ताटकावन में बदलती है', 'विश्वामित्र बताते हैं कि कभी समृद्ध मालद और करूष प्रदेश ताटका की हिंसा से कैसे जनशून्य हुए। यात्री ऐसे वन में प्रवेश करते हैं जिसकी पहचान अनुपस्थिति है—टूटी राहें, छोड़ी बस्तियाँ और भय। अगला निर्णय किसी अमूर्त राक्षसी का नहीं, क्षतिग्रस्त मानवीय संसार का प्रश्न होगा।'),
  ('scene-tataka-forest-forces-choice', 'tataka-has-a-history-before-monsterhood', 'en', 'Tataka was not born as a forest terror', 'When Rama questions Tataka''s extraordinary strength, Vishvamitra tells her history: she was the daughter of the yaksha Suketu, granted immense power, married to Sunda, and mother of Maricha. After Sunda''s death and a retaliatory attack on Agastya, curse and violence transformed the family.'),
  ('scene-tataka-forest-forces-choice', 'tataka-has-a-history-before-monsterhood', 'hi', 'ताटका जन्म से वन का आतंक नहीं थी', 'राम ताटका के असाधारण बल पर प्रश्न करते हैं तो विश्वामित्र उसका इतिहास बताते हैं—वह यक्ष सुकेतु की पुत्री, महान शक्ति से संपन्न, सुंद की पत्नी और मारीच की माता थी। सुंद की मृत्यु और अगस्त्य पर प्रतिशोधी आक्रमण के बाद शाप तथा हिंसा ने पूरे परिवार को बदल दिया।'),
  ('scene-tataka-forest-forces-choice', 'command-carries-gendered-argument', 'en', 'Vishvamitra commands lethal action', 'Vishvamitra argues that a ruler must protect the population and tells Rama to kill Tataka despite his hesitation about killing a woman. The selected source uses gendered precedents to press the command. Devam preserves that reasoning as source content, not as a timeless rule requiring modern agreement.'),
  ('scene-tataka-forest-forces-choice', 'command-carries-gendered-argument', 'hi', 'विश्वामित्र प्राणघातक कार्रवाई का आदेश देते हैं', 'विश्वामित्र कहते हैं कि शासक को प्रजा की रक्षा करनी चाहिए और स्त्री-वध पर राम की झिझक के बावजूद ताटका को मारने का आदेश देते हैं। चुना हुआ स्रोत इस आदेश के समर्थन में लैंगिक उदाहरण देता है। देवम इस तर्क को स्रोत की सामग्री के रूप में रखता है, आधुनिक सहमति माँगने वाले शाश्वत नियम की तरह नहीं।'),
  ('scene-tataka-forest-forces-choice', 'battle-erases-easy-restraint', 'en', 'Rama first seeks restraint; the battle escalates', 'Rama initially speaks of disabling Tataka rather than killing her. His bow-call draws her out; dust, stones, concealment, and rapid attack overwhelm the forest. Lakshmana joins the defence, and Vishvamitra warns that darkness will increase her advantage. The space for a limited solution closes under continuing assault.'),
  ('scene-tataka-forest-forces-choice', 'battle-erases-easy-restraint', 'hi', 'राम पहले सीमित रोक चाहते हैं, पर युद्ध तीव्र हो जाता है', 'राम आरंभ में ताटका को मारने के बजाय उसकी क्षमता सीमित करने की बात करते हैं। धनुष की टंकार उसे बाहर लाती है; धूल, पत्थर, अदृश्य गति और तीव्र आक्रमण वन को भर देते हैं। लक्ष्मण रक्षा में जुड़ते हैं और विश्वामित्र चेताते हैं कि अँधेरा उसका लाभ बढ़ाएगा। लगातार हमले में सीमित समाधान की गुंजाइश घटती जाती है।'),
  ('scene-tataka-forest-forces-choice', 'tataka-falls-forest-reopens', 'en', 'Tataka falls and the forest changes', 'Rama finally strikes Tataka lethally. The source celebrates the act through celestial praise and shows the forest becoming peaceful again. The consumer telling retains both outcomes: an immediate danger ends and routes reopen, while the preceding history prevents the victory from becoming emotionally simple.'),
  ('scene-tataka-forest-forces-choice', 'tataka-falls-forest-reopens', 'hi', 'ताटका गिरती है और वन बदल जाता है', 'अंततः राम ताटका पर प्राणघातक प्रहार करते हैं। स्रोत दिव्य प्रशंसा से इस कार्य का उत्सव मनाता है और वन को फिर शांत दिखाता है। उपभोक्ता कथा दोनों परिणाम सुरक्षित रखती है—तत्काल खतरा समाप्त होकर रास्ते खुलते हैं, पर पिछला इतिहास विजय को भावनात्मक रूप से सरल नहीं बनने देता।'),
  ('scene-weapons-arrive-with-restraint', 'vishvamitra-rewards-readiness', 'en', 'Vishvamitra offers a dangerous inheritance', 'Pleased after Tataka''s defeat, Vishvamitra offers Rama a vast body of celestial weapons associated with different powers, elements, restraints, and forms of destruction. The long source catalogue communicates scale: the prince is being trusted with capabilities far beyond ordinary archery.'),
  ('scene-weapons-arrive-with-restraint', 'vishvamitra-rewards-readiness', 'hi', 'विश्वामित्र एक खतरनाक विरासत सौंपते हैं', 'ताटका-वध के बाद प्रसन्न विश्वामित्र राम को अलग-अलग शक्तियों, तत्वों, बंधनों और विनाश-रूपों से जुड़े अनेक दिव्य अस्त्र देते हैं। स्रोत की लंबी सूची विस्तार का अनुभव कराती है—राजकुमार को साधारण धनुर्विद्या से बहुत आगे की क्षमता सौंपी जा रही है।'),
  ('scene-weapons-arrive-with-restraint', 'weapons-answer-as-persons', 'en', 'The weapons present themselves as servants', 'In the selected telling, the weapons take perceptible forms, approach Rama, and promise to appear when remembered. Rama accepts them through disciplined attention rather than testing them on the landscape. Power enters a relationship of command before it enters combat.'),
  ('scene-weapons-arrive-with-restraint', 'weapons-answer-as-persons', 'hi', 'अस्त्र स्वयं को सेवक के रूप में प्रस्तुत करते हैं', 'चुनी हुई कथा में अस्त्र दृश्य रूप लेकर राम के पास आते हैं और स्मरण करने पर उपस्थित होने का वचन देते हैं। राम उन्हें भू-दृश्य पर आज़माने के बजाय अनुशासित ध्यान से स्वीकार करते हैं। शक्ति युद्ध में उतरने से पहले आदेश और उत्तरदायित्व के संबंध में प्रवेश करती है।'),
  ('scene-weapons-arrive-with-restraint', 'rama-asks-how-to-withdraw', 'en', 'The first question is how to stop them', 'As they walk, Rama asks Vishvamitra for the knowledge required to withdraw, counter, and quiet the weapons. The request is crucial: possession without recall would make every use irreversible. The teacher responds with the complementary disciplines of restraint.'),
  ('scene-weapons-arrive-with-restraint', 'rama-asks-how-to-withdraw', 'hi', 'राम का पहला प्रश्न है—इन्हें रोका कैसे जाए', 'चलते हुए राम विश्वामित्र से अस्त्रों को वापस लेने, रोकने और शांत करने की विधि माँगते हैं। यह प्रश्न निर्णायक है—वापसी का ज्ञान न हो तो हर प्रयोग अपरिवर्तनीय बन सकता है। गुरु उन्हें नियंत्रण और प्रतिहार की पूरक विद्याएँ देते हैं।'),
  ('scene-weapons-arrive-with-restraint', 'power-returns-to-curiosity', 'en', 'After weapons, Rama asks about the next place', 'Once the weapons are accepted and restrained, Rama notices a pleasant hermitage beyond the terrifying wilderness and asks whose place it is and where the threatened sacrifice will occur. Curiosity, not fascination with force, moves the journey forward toward Siddhashrama.'),
  ('scene-weapons-arrive-with-restraint', 'power-returns-to-curiosity', 'hi', 'अस्त्रों के बाद राम अगले स्थान के बारे में पूछते हैं', 'अस्त्र ग्रहण और नियंत्रित करने के बाद राम भयानक वन के पार एक सुंदर आश्रम देखते हैं और पूछते हैं कि यह किसका स्थान है तथा संकटग्रस्त अनुष्ठान कहाँ होगा। शक्ति का आकर्षण नहीं, जिज्ञासा यात्रा को सिद्धाश्रम की ओर आगे बढ़ाती है।'),
  ('scene-siddhashrama-remembers-vishnu', 'hermitage-holds-vishnu-austerity', 'en', 'Siddhashrama remembers Vishnu''s long practice', 'Vishvamitra tells Rama that Vishnu once practised austerity here for immense spans of time and attained fulfilment, giving Siddhashrama its name. The current ritual ground is therefore not an arbitrary campsite; its identity comes from sustained discipline across generations of story.'),
  ('scene-siddhashrama-remembers-vishnu', 'hermitage-holds-vishnu-austerity', 'hi', 'सिद्धाश्रम विष्णु की दीर्घ तपस्या को याद रखता है', 'विश्वामित्र राम को बताते हैं कि विष्णु ने यहाँ लंबे काल तक तपस्या करके सिद्धि प्राप्त की, इसलिए स्थान का नाम सिद्धाश्रम पड़ा। वर्तमान अनुष्ठान-स्थल कोई आकस्मिक शिविर नहीं; उसकी पहचान पीढ़ियों से चली आ रही साधना और कथा से बनती है।'),
  ('scene-siddhashrama-remembers-vishnu', 'bali-gives-within-his-vow', 'en', 'Bali''s generosity creates a difficult opening', 'The story recalls King Bali, whose victories displaced the gods and whose sacrifice made him bound to give what a petitioner properly requested. The source holds power and generosity together: Bali is an opponent of the gods, yet his commitment to giving is what makes the next encounter possible.'),
  ('scene-siddhashrama-remembers-vishnu', 'bali-gives-within-his-vow', 'hi', 'बलि की उदारता एक कठिन मार्ग खोलती है', 'कथा राजा बलि को याद करती है, जिनकी विजय से देवता विस्थापित हुए और जिनका यज्ञ उन्हें उचित याचना स्वीकार करने के वचन से बाँधता है। स्रोत शक्ति और उदारता को साथ रखता है—बलि देवताओं के प्रतिद्वंद्वी हैं, पर देने का उनका संकल्प ही अगली भेंट संभव बनाता है।'),
  ('scene-siddhashrama-remembers-vishnu', 'vamana-asks-for-three-steps', 'en', 'Vamana asks only for the ground he can cross', 'Vishnu appears as the small brahmana Vamana and asks Bali for three steps of land. Once the gift is granted, Vamana expands and measures the worlds, restoring the gods'' position. Devam presents this as the selected source''s sacred place-memory, while later traditions may interpret Bali and the encounter differently.'),
  ('scene-siddhashrama-remembers-vishnu', 'vamana-asks-for-three-steps', 'hi', 'वामन केवल तीन पग भूमि माँगते हैं', 'विष्णु छोटे ब्राह्मण वामन के रूप में आकर बलि से तीन पग भूमि माँगते हैं। दान स्वीकार होते ही वामन विराट होकर लोक नापते हैं और देवताओं की स्थिति पुनः स्थापित करते हैं। देवम इसे चुने स्रोत की पवित्र स्थान-स्मृति मानता है; बाद की परंपराएँ बलि और इस भेंट को अलग ढंग से समझ सकती हैं।'),
  ('scene-siddhashrama-remembers-vishnu', 'present-vow-begins', 'en', 'Vishvamitra enters silence; the brothers take watch', 'Vishvamitra identifies Siddhashrama as his own hermitage too and begins initiation into the sacrifice. Rama and Lakshmana complete their morning duties, honour the fire and their guide, and prepare to guard a vow whose performer must now remain silent.'),
  ('scene-siddhashrama-remembers-vishnu', 'present-vow-begins', 'hi', 'विश्वामित्र मौन-व्रत में जाते हैं और दोनों भाई पहरा लेते हैं', 'विश्वामित्र सिद्धाश्रम को अपना आश्रम भी बताते हैं और यज्ञ की दीक्षा लेते हैं। राम और लक्ष्मण प्रातः-कर्म करके अग्नि तथा गुरु का सम्मान करते हैं और ऐसे संकल्प की रक्षा के लिए तैयार होते हैं जिसके अनुष्ठाता को अब मौन रहना है।'),
  ('scene-six-nights-end-in-battle', 'brothers-ask-for-the-clock', 'en', 'Tell us when the danger will come', 'Because Vishvamitra must keep ritual silence, Rama and Lakshmana ask the other ascetics for the likely attack window. They learn that six nights of protection are required. The defence begins with timing and communication, not with random displays of readiness.'),
  ('scene-six-nights-end-in-battle', 'brothers-ask-for-the-clock', 'hi', 'हमें बताइए संकट किस समय आएगा', 'विश्वामित्र को अनुष्ठानिक मौन रखना है, इसलिए राम और लक्ष्मण अन्य तपस्वियों से आक्रमण का संभावित समय पूछते हैं। उन्हें छह रात रक्षा करनी है। पहरा अंधाधुंध वीरता से नहीं, समय और संवाद की स्पष्टता से शुरू होता है।'),
  ('scene-six-nights-end-in-battle', 'vigil-holds-through-five-nights', 'en', 'Readiness is mostly waiting', 'The brothers renounce sleep and guard the hermitage through day and night. Nothing attacks immediately. Fatigue, uncertainty, and the temptation to relax become part of the challenge, showing why the earlier disciplines of endurance mattered before any weapon was drawn.'),
  ('scene-six-nights-end-in-battle', 'vigil-holds-through-five-nights', 'hi', 'सजगता का अधिकांश भाग प्रतीक्षा है', 'दोनों भाई नींद छोड़कर दिन-रात आश्रम की रक्षा करते हैं। हमला तुरंत नहीं आता। थकान, अनिश्चितता और ढीला पड़ने का आकर्षण स्वयं चुनौती बनते हैं; इससे समझ आता है कि अस्त्र उठाने से पहले सहनशक्ति की विद्याएँ क्यों दी गई थीं।'),
  ('scene-six-nights-end-in-battle', 'sixth-day-sky-breaks', 'en', 'On the sixth day the sky fills with attack', 'Rama warns Lakshmana to be especially alert. Fire flares at the altar, a terrible sound rises, and Maricha and Subahu appear with their followers, covering the sky and raining defilement toward the rite. The long wait condenses into seconds of decision.'),
  ('scene-six-nights-end-in-battle', 'sixth-day-sky-breaks', 'hi', 'छठे दिन आकाश आक्रमण से भर जाता है', 'राम लक्ष्मण को विशेष सावधान रहने को कहते हैं। वेदी की अग्नि तेज होती है, भयानक ध्वनि उठती है और मारीच-सुबाहु अपने साथियों सहित आकाश ढककर अनुष्ठान पर अपवित्र सामग्री बरसाने आते हैं। लंबी प्रतीक्षा कुछ क्षणों के निर्णय में सिमट जाती है।'),
  ('scene-six-nights-end-in-battle', 'maricha-expelled-subahu-killed', 'en', 'Rama distinguishes between two outcomes', 'Rama uses the Manava weapon to hurl Maricha far into the sea without killing him, then kills Subahu and scatters the remaining attackers. The sacrifice reaches completion. Vishvamitra praises the brothers not for spectacle, but because the protected task was actually finished.'),
  ('scene-six-nights-end-in-battle', 'maricha-expelled-subahu-killed', 'hi', 'राम दो आक्रमणकारियों के लिए अलग परिणाम चुनते हैं', 'राम मानवास्त्र से मारीच को मारे बिना बहुत दूर समुद्र में फेंकते हैं, फिर सुबाहु को मारकर शेष आक्रमणकारियों को तितर-बितर करते हैं। अनुष्ठान पूरा होता है। विश्वामित्र भाइयों की प्रशंसा प्रदर्शन के लिए नहीं, बल्कि इसलिए करते हैं कि जिस कार्य की रक्षा करनी थी वह सचमुच संपन्न हुआ।'),
  ('scene-road-leaves-siddhashrama', 'service-complete-next-command', 'en', 'The brothers return for their next command', 'After resting at Siddhashrama, Rama and Lakshmana greet Vishvamitra and ask what service comes next. The protected sacrifice is finished, but apprenticeship does not end with one victory. Their readiness opens another road rather than a reward chamber.'),
  ('scene-road-leaves-siddhashrama', 'service-complete-next-command', 'hi', 'दोनों भाई अगले आदेश के लिए फिर उपस्थित होते हैं', 'सिद्धाश्रम में विश्राम के बाद राम और लक्ष्मण विश्वामित्र के सामने उपस्थित होकर अगला कार्य पूछते हैं। अनुष्ठान की रक्षा पूरी हो चुकी है, पर शिक्षुता एक विजय पर समाप्त नहीं होती। उनकी तत्परता पुरस्कार-कक्ष नहीं, एक नई राह खोलती है।'),
  ('scene-road-leaves-siddhashrama', 'mithila-sacrifice-and-bow', 'en', 'Mithila offers a sacrifice and a legendary bow', 'The ascetics announce that King Janaka is holding a major sacrifice and invite the princes to accompany them. Vishvamitra adds a second reason: Janaka''s house guards Shiva''s immense bow, honoured for generations and beyond the strength of visiting kings.'),
  ('scene-road-leaves-siddhashrama', 'mithila-sacrifice-and-bow', 'hi', 'मिथिला में यज्ञ और एक अद्भुत धनुष प्रतीक्षा कर रहे हैं', 'तपस्वी बताते हैं कि राजा जनक एक बड़ा यज्ञ कर रहे हैं और राजकुमारों को साथ चलने के लिए कहते हैं। विश्वामित्र दूसरा कारण जोड़ते हैं—जनक के घर में पीढ़ियों से पूजित शिव का विशाल धनुष है, जिसे आए हुए राजा भी उठा नहीं सके।'),
  ('scene-road-leaves-siddhashrama', 'whole-hermitage-takes-road', 'en', 'The journey becomes a moving community', 'Vishvamitra, the princes, and many ascetics leave Siddhashrama with carts and provisions. Forest animals follow for a time before being turned back. The scale changes from three travellers to a moving community carrying practice, memory, and practical needs across the land.'),
  ('scene-road-leaves-siddhashrama', 'whole-hermitage-takes-road', 'hi', 'यात्रा एक चलते हुए समुदाय में बदलती है', 'विश्वामित्र, दोनों राजकुमार और अनेक तपस्वी गाड़ियों तथा सामग्री के साथ सिद्धाश्रम से निकलते हैं। वन के पशु कुछ दूर तक पीछे आते हैं और फिर लौटाए जाते हैं। यात्रा तीन व्यक्तियों से बढ़कर साधना, स्मृति और दैनिक आवश्यकताएँ साथ लिए चलते समुदाय में बदल जाती है।'),
  ('scene-road-leaves-siddhashrama', 'sona-camp-opens-lineage', 'en', 'At the Sona, Rama asks about the land', 'At sunset the company camps beside the Sona. Rama notices the fertile country and asks who once ruled it. Vishvamitra begins with King Kusha and his descendants, turning the overnight halt into an entrance to his own family history and the cities shaped by it.'),
  ('scene-road-leaves-siddhashrama', 'sona-camp-opens-lineage', 'hi', 'सोन तट पर राम भूमि की कथा पूछते हैं', 'सूर्यास्त पर दल सोन नदी के किनारे रुकता है। राम समृद्ध भूमि देखकर पूछते हैं कि यहाँ किसका शासन था। विश्वामित्र राजा कुश और उनके वंश से कथा आरंभ करते हैं; रात का पड़ाव उनके अपने परिवार और उससे बने नगरों के इतिहास का द्वार बन जाता है।'),
  ('scene-kusanabha-daughters-choose-agency', 'vayu-demands-without-consent', 'en', 'Vayu demands the hundred daughters choose him', 'Kushanabha''s hundred daughters are moving together in a garden when Vayu desires them and demands that they accept him. They answer collectively that he must approach their father according to the social order they recognise. Whatever one thinks of that patriarchal structure, their immediate refusal is explicit.'),
  ('scene-kusanabha-daughters-choose-agency', 'vayu-demands-without-consent', 'hi', 'वायु सौ पुत्रियों से उन्हें चुनने की माँग करते हैं', 'कुशनाभ की सौ पुत्रियाँ उद्यान में साथ घूम रही होती हैं जब वायु उन्हें चाहकर स्वयं को स्वीकार करने की माँग करते हैं। वे एक स्वर में कहती हैं कि जिस सामाजिक व्यवस्था को वे मानती हैं उसके अनुसार वे पिता से बात करें। उस पितृसत्तात्मक व्यवस्था पर आधुनिक मत कुछ भी हो, उनका तत्काल अस्वीकार स्पष्ट है।'),
  ('scene-kusanabha-daughters-choose-agency', 'refusal-is-punished', 'en', 'Vayu answers refusal by injuring them', 'Vayu ignores their answer, enters their bodies in the source''s supernatural account, and leaves their limbs bent and painful. They do not retaliate with inherited power, fearing destruction and choosing to return together to their father. The episode preserves coercion as harm, not romance.'),
  ('scene-kusanabha-daughters-choose-agency', 'refusal-is-punished', 'hi', 'वायु अस्वीकार का उत्तर हिंसा से देते हैं', 'स्रोत की अलौकिक कथा में वायु उनका उत्तर अनसुना करके उनके शरीर में प्रवेश करते हैं और अंगों को टेढ़ा तथा पीड़ित कर देते हैं। वे विनाशकारी प्रतिकार नहीं करतीं और साथ पिता के पास लौटती हैं। यह प्रसंग दबाव को प्रेमकथा नहीं, हिंसा के रूप में रखता है।'),
  ('scene-kusanabha-daughters-choose-agency', 'father-hears-and-restoration-follows', 'en', 'Their account is heard before a future is arranged', 'Kushanabha asks what happened, hears his daughters'' account, and praises their restraint. He later arranges their marriage to Brahmadatta; in the source, his touch restores their bodies. Devam preserves this resolution while not treating marriage as a universal cure for injury.'),
  ('scene-kusanabha-daughters-choose-agency', 'father-hears-and-restoration-follows', 'hi', 'भविष्य तय होने से पहले उनकी बात सुनी जाती है', 'कुशनाभ पहले पूछते और पुत्रियों का पूरा वृत्तांत सुनते हैं, फिर उनके संयम की प्रशंसा करते हैं। बाद में वे ब्रह्मदत्त से उनका विवाह कराते हैं और स्रोत में उनके स्पर्श से पुत्रियों के शरीर पुनः स्वस्थ होते हैं। देवम इस समाधान को सुरक्षित रखता है, पर विवाह को हर चोट का सार्वभौमिक उपचार नहीं मानता।'),
  ('scene-kusanabha-daughters-choose-agency', 'lineage-reaches-vishvamitra-and-kaushiki', 'en', 'The family story reaches Vishvamitra and a river', 'Kushanabha later receives a son, Gadhi. Vishvamitra reveals that Gadhi is his father and that his elder sister Satyavati became the river Kaushiki after her marriage and ascent. A story begun with daughters denied control ends by locating the narrator inside the same complex family line.'),
  ('scene-kusanabha-daughters-choose-agency', 'lineage-reaches-vishvamitra-and-kaushiki', 'hi', 'वंश-कथा विश्वामित्र और एक नदी तक पहुँचती है', 'बाद में कुशनाभ को गाधि नामक पुत्र मिलता है। विश्वामित्र बताते हैं कि गाधि उनके पिता हैं और उनकी बड़ी बहन सत्यवती विवाह तथा दिव्य आरोहण के बाद कौशिकी नदी बनीं। पुत्रियों की इच्छा पर आक्रमण से शुरू कथा अंत में स्वयं कथावाचक को उसी जटिल परिवार में रखती है।'),
  ('scene-ganga-and-kartikeya-origins', 'himavat-has-two-daughters', 'en', 'Ganga and Uma begin as daughters of the mountain', 'When the travellers reach Ganga, Vishvamitra tells Rama that Himavat and Mena had two daughters: Ganga, who came to flow through the worlds, and Uma, who pursued fierce austerity and became Shiva''s partner. The river and goddess are introduced as related but distinct lives.'),
  ('scene-ganga-and-kartikeya-origins', 'himavat-has-two-daughters', 'hi', 'गंगा और उमा पर्वतराज की पुत्रियों के रूप में आरंभ होती हैं', 'यात्री गंगा पहुँचते हैं तो विश्वामित्र बताते हैं कि हिमवान और मेना की दो पुत्रियाँ थीं—गंगा, जो लोकों में प्रवाहित हुईं, और उमा, जिन्होंने कठोर तपस्या करके शिव को पति रूप में पाया। नदी और देवी संबंधित किंतु अलग जीवनों के रूप में सामने आती हैं।'),
  ('scene-ganga-and-kartikeya-origins', 'gods-fear-unbounded-energy', 'en', 'The gods interrupt an energy they cannot contain', 'The selected account describes Shiva and Uma''s prolonged union and the gods'' fear that its offspring would overwhelm the worlds. They ask Shiva to contain his energy. The intervention creates anger and consequence: Uma curses the gods after the hoped-for child is denied a direct birth through her.'),
  ('scene-ganga-and-kartikeya-origins', 'gods-fear-unbounded-energy', 'hi', 'देवता उस ऊर्जा को रोकते हैं जिसे वे सँभाल नहीं सकते', 'चुनी हुई कथा शिव और उमा के दीर्घ मिलन तथा देवताओं के उस भय का वर्णन करती है कि उससे उत्पन्न संतान लोकों को अभिभूत कर देगी। वे शिव से ऊर्जा रोकने को कहते हैं। हस्तक्षेप का परिणाम क्रोध है—उमा अपने माध्यम से सीधे जन्म रोके जाने पर देवताओं को शाप देती हैं।'),
  ('scene-ganga-and-kartikeya-origins', 'agni-and-ganga-carry-the-seed', 'en', 'Agni and Ganga carry what no one can hold alone', 'Shiva''s energy passes through Agni and into Ganga, whose waters and body cannot contain it indefinitely. It reaches the reed-filled landscape where the child takes form. The source makes birth a distributed event across divine bodies, elements, and place rather than one private chamber.'),
  ('scene-ganga-and-kartikeya-origins', 'agni-and-ganga-carry-the-seed', 'hi', 'अग्नि और गंगा उस तेज को सँभालते हैं जिसे कोई अकेला नहीं धारण कर सकता', 'शिव का तेज अग्नि से होकर गंगा में आता है, पर उनका जल और शरीर भी उसे अनंत समय तक नहीं सँभाल सकते। वह सरकंडों वाले भू-दृश्य तक पहुँचकर बालक का रूप लेता है। स्रोत जन्म को एक निजी कक्ष नहीं, दिव्य शरीरों, तत्वों और स्थान में बाँटी घटना बनाता है।'),
  ('scene-ganga-and-kartikeya-origins', 'kartikeya-becomes-general', 'en', 'The child becomes the gods'' commander', 'The Krittikas nurture the child, giving Kartikeya another name and a many-sided maternal story. He grows with extraordinary speed, defeats the hostile forces named in the account, and is installed as the gods'' commander. The riverbank story ends by explaining a warrior-god through care as well as combat.'),
  ('scene-ganga-and-kartikeya-origins', 'kartikeya-becomes-general', 'hi', 'बालक देवताओं का सेनापति बनता है', 'कृत्तिकाएँ बालक का पालन करती हैं और कार्तिकेय को दूसरा नाम तथा अनेक मातृ-संबंध देती हैं। वे असाधारण गति से बढ़कर कथा में बताए शत्रुओं को परास्त करते हैं और देवताओं के सेनापति बनाए जाते हैं। नदी-तट की कथा युद्ध-देव को केवल रण से नहीं, पालन से भी समझाती है।'),
  ('scene-sagara-line-brings-ganga-down', 'sagara-family-divides-into-two-futures', 'en', 'Sagara receives one heir and sixty thousand sons', 'King Sagara''s two wives receive different promised futures: one line through a single son and another through sixty thousand sons. The single line includes Asamanja, whose cruelty toward children leads Sagara to banish him, and Anshuman, who remains trusted and compassionate.'),
  ('scene-sagara-line-brings-ganga-down', 'sagara-family-divides-into-two-futures', 'hi', 'सगर को एक उत्तराधिकारी और साठ हज़ार पुत्र मिलते हैं', 'राजा सगर की दो रानियों को अलग भविष्य मिलते हैं—एक से एक पुत्र का वंश और दूसरी से साठ हज़ार पुत्र। एकल वंश में असमंज आते हैं, जिनकी बच्चों के प्रति क्रूरता के कारण सगर उन्हें निकाल देते हैं, और अंशुमान, जो विश्वसनीय तथा करुणाशील रहते हैं।'),
  ('scene-sagara-line-brings-ganga-down', 'missing-horse-turns-into-excavation', 'en', 'A stolen horse unleashes indiscriminate digging', 'During Sagara''s sacrifice, Indra steals the horse. The sixty thousand sons search by cutting into the earth, killing creatures and destroying habitats while accusing whatever they meet. Even the gods protest the damage. A legitimate search has become collective devastation through certainty without evidence.'),
  ('scene-sagara-line-brings-ganga-down', 'missing-horse-turns-into-excavation', 'hi', 'चोरी हुआ अश्व अंधाधुंध खुदाई का कारण बनता है', 'सगर के यज्ञ में इंद्र अश्व चुरा लेते हैं। साठ हज़ार पुत्र पृथ्वी को काटते हुए खोजते हैं, जीवों और आवासों को नष्ट करते हैं और सामने आने वाले पर आरोप लगाते हैं। देवता भी इस विनाश पर आपत्ति करते हैं। प्रमाण-विहीन निश्चितता ने उचित खोज को सामूहिक तबाही में बदल दिया है।'),
  ('scene-sagara-line-brings-ganga-down', 'kapila-fire-and-anshuman-restraint', 'en', 'Attack meets Kapila''s fire; restraint finds the truth', 'The sons find the horse beside Kapila and rush at him as the thief; his anger reduces them to ashes. Anshuman later follows their path, honours the beings he meets, approaches Kapila without attack, and recovers the horse. Garuda tells him only Ganga''s waters can release the dead.'),
  ('scene-sagara-line-brings-ganga-down', 'kapila-fire-and-anshuman-restraint', 'hi', 'आक्रमण कपिल के तेज से टकराता है, संयम सत्य तक पहुँचता है', 'पुत्र कपिल के पास अश्व देखकर उन्हें चोर मानकर आक्रमण करते हैं और उनके तेज से राख हो जाते हैं। बाद में अंशुमान उसी राह पर चलते हुए मिले प्राणियों का सम्मान करते हैं, कपिल के पास बिना आक्रमण जाते हैं और अश्व वापस पाते हैं। गरुड़ बताते हैं कि मृतकों की मुक्ति केवल गंगा-जल से होगी।'),
  ('scene-sagara-line-brings-ganga-down', 'three-generations-carry-unfinished-task', 'en', 'Sagara, Anshuman, and Dilipa cannot finish the descent', 'Sagara completes the sacrifice but cannot bring Ganga down. Anshuman rules and practises austerity without completing the task; his son Dilipa carries the same concern and also dies before solving it. The account makes inherited responsibility visible without pretending every sincere effort succeeds within one lifetime.'),
  ('scene-sagara-line-brings-ganga-down', 'three-generations-carry-unfinished-task', 'hi', 'सगर, अंशुमान और दिलीप गंगा-अवतरण पूरा नहीं कर पाते', 'सगर यज्ञ पूरा करते हैं, पर गंगा नहीं ला पाते। अंशुमान शासन और तपस्या करते हुए भी कार्य पूरा नहीं कर पाते; उनके पुत्र दिलीप भी वही चिंता सँभालते हैं और समाधान से पहले चले जाते हैं। कथा विरासत में मिले उत्तरदायित्व को दिखाती है, पर यह नहीं कहती कि हर सच्चा प्रयास एक जीवन में सफल होता है।'),
  ('scene-sagara-line-brings-ganga-down', 'bhagiratha-guides-ganga-to-ashes', 'en', 'Bhagiratha wins help, survives the descent, and reaches the ashes', 'Bhagiratha''s austerity gains Ganga''s consent, then Shiva''s help to absorb her otherwise destructive fall. Ganga follows Bhagiratha, is briefly swallowed and released by Jahnu after flooding his rite, reaches the ocean and underground ashes, and releases Sagara''s sons. Success requires negotiation with every force along the route.'),
  ('scene-sagara-line-brings-ganga-down', 'bhagiratha-guides-ganga-to-ashes', 'hi', 'भगीरथ सहायता प्राप्त कर अवतरण सँभालते हैं और गंगा को राख तक पहुँचाते हैं', 'भगीरथ की तपस्या से गंगा की सहमति और फिर उनके प्रचंड अवतरण को सँभालने के लिए शिव की सहायता मिलती है। गंगा भगीरथ के पीछे चलती हैं, जह्नु के यज्ञ को बहाने पर उनके द्वारा पीकर फिर छोड़ी जाती हैं, समुद्र और भूमिगत राख तक पहुँचकर सगर-पुत्रों को मुक्त करती हैं। सफलता मार्ग की हर शक्ति से संवाद माँगती है।'),
  ('scene-ocean-churning-and-maruts', 'devas-asuras-churn-together', 'en', 'Rivals cooperate to churn the ocean', 'Vishvamitra recounts how devas and asuras, both seeking freedom from decay, use a mountain and serpent to churn the ocean together. Their cooperation is instrumental rather than trusting; the same project that requires both sides will later become a struggle over who controls its result.'),
  ('scene-ocean-churning-and-maruts', 'devas-asuras-churn-together', 'hi', 'प्रतिद्वंद्वी समुद्र-मंथन के लिए साथ काम करते हैं', 'विश्वामित्र बताते हैं कि जरा-मृत्यु से मुक्ति चाहने वाले देव और असुर पर्वत तथा नाग के सहारे मिलकर समुद्र मथते हैं। उनका सहयोग विश्वास पर नहीं, आवश्यकता पर आधारित है; जिस कार्य के लिए दोनों पक्ष चाहिए, उसके फल पर बाद में संघर्ष होगा।'),
  ('scene-ocean-churning-and-maruts', 'poison-and-treasures-emerge', 'en', 'The first result is danger, not immortality', 'The churning releases lethal poison before its treasures. Shiva contains the poison, preventing the undertaking from destroying the worlds. Other beings and gifts emerge, including Dhanvantari with the vessel of amrita. Creation here produces risk, care, beauty, and contested value together.'),
  ('scene-ocean-churning-and-maruts', 'poison-and-treasures-emerge', 'hi', 'पहला परिणाम अमृत नहीं, विष है', 'मंथन से रत्नों से पहले घातक विष निकलता है। शिव विष को धारण करके लोकों को विनाश से बचाते हैं। बाद में अन्य प्राणी और रत्न आते हैं, जिनमें अमृत-कलश लिए धन्वंतरि भी हैं। सृजन यहाँ जोखिम, संरक्षण, सौंदर्य और विवादित मूल्य सब साथ उत्पन्न करता है।'),
  ('scene-ocean-churning-and-maruts', 'amrita-restarts-conflict', 'en', 'The shared labour does not create shared ownership', 'When amrita appears, cooperation breaks. Vishnu''s intervention helps the devas obtain it, and battle follows between the children of Aditi and Diti. The devas prevail. The story moves directly from a common undertaking to unequal distribution and renewed violence.'),
  ('scene-ocean-churning-and-maruts', 'amrita-restarts-conflict', 'hi', 'साझा श्रम साझा अधिकार नहीं बनाता', 'अमृत प्रकट होते ही सहयोग टूट जाता है। विष्णु के हस्तक्षेप से देवता अमृत प्राप्त करते हैं और अदिति तथा दिति के पुत्रों में युद्ध होता है। देवता विजयी होते हैं। कथा साझा प्रयास से असमान वितरण और फिर हिंसा तक सीधे जाती है।'),
  ('scene-ocean-churning-and-maruts', 'diti-grief-and-indra-infiltration', 'en', 'Diti''s grief becomes a vow Indra fears', 'After her sons are killed, Diti undertakes a long discipline to bear a son capable of defeating Indra. Indra serves her while watching for a breach, then enters and divides the embryo when she sleeps in a ritually impure posture. The source has Diti accept blame, but the covert violence remains visible.'),
  ('scene-ocean-churning-and-maruts', 'diti-grief-and-indra-infiltration', 'hi', 'दिति का शोक ऐसा संकल्प बनता है जिससे इंद्र डरते हैं', 'पुत्रों की मृत्यु के बाद दिति ऐसा पुत्र पाने के लिए दीर्घ तपस्या करती हैं जो इंद्र को परास्त कर सके। इंद्र उनकी सेवा करते हुए चूक की प्रतीक्षा करते हैं और एक अनुष्ठानिक अशुद्ध मुद्रा में सोने पर गर्भ में प्रवेश करके भ्रूण विभाजित कर देते हैं। स्रोत दिति से दोष स्वीकार कराता है, पर गुप्त हिंसा फिर भी स्पष्ट रहती है।'),
  ('scene-ocean-churning-and-maruts', 'seven-parts-become-maruts', 'en', 'The broken future is renamed and given a place', 'Diti asks that the seven divided parts become the Maruts rather than remain a destroyed pregnancy, and Indra agrees to their honoured roles. The resolution does not undo the act, but converts the feared rival into a group with names, domains, and relationship. Vishala''s lineage grows from that uneasy reconciliation.'),
  ('scene-ocean-churning-and-maruts', 'seven-parts-become-maruts', 'hi', 'टूटा हुआ भविष्य नया नाम और स्थान पाता है', 'दिति माँगती हैं कि विभाजित सात अंश नष्ट गर्भ न रहकर मरुत बनें और इंद्र उन्हें सम्मानित स्थान देने पर सहमत होते हैं। समाधान घटना मिटाता नहीं, पर भयभीत प्रतिद्वंद्वी को नाम, क्षेत्र और संबंध वाले समूह में बदलता है। उसी असहज मेल से विशाला की वंश-कथा आगे बढ़ती है।'),
  ('scene-ahalya-hermitage-awakens', 'indra-enters-in-gautama-form', 'en', 'Indra uses Gautama''s appearance to enter', 'Vishvamitra tells how Indra watched for Gautama to leave and entered the hermitage in the ascetic''s form. In this selected Dutt rendering, Ahalya recognises Indra and agrees to the encounter; other Ramayana traditions describe her knowledge and consent differently. The disguise and power imbalance remain material facts.'),
  ('scene-ahalya-hermitage-awakens', 'indra-enters-in-gautama-form', 'hi', 'इंद्र गौतम का रूप लेकर प्रवेश करते हैं', 'विश्वामित्र बताते हैं कि इंद्र गौतम के बाहर जाने की प्रतीक्षा करके उन्हीं का रूप लेकर आश्रम में आए। चुने हुए दत्त रूपांतरण में अहल्या इंद्र को पहचानकर भेंट स्वीकार करती हैं; अन्य रामायण परंपराएँ उनके ज्ञान और सहमति को अलग तरह बताती हैं। वेश-छल और शक्ति-असमानता फिर भी महत्त्वपूर्ण तथ्य हैं।'),
  ('scene-ahalya-hermitage-awakens', 'gautama-curses-both', 'en', 'Gautama returns and punishes both participants', 'Gautama discovers Indra leaving in his form and curses him, then condemns Ahalya to long isolation, unseen, fasting, and living amid ash. The punishment is severe and unequal in duration. The source also embeds a future condition: Rama''s arrival and Ahalya''s hospitality will end the sentence.'),
  ('scene-ahalya-hermitage-awakens', 'gautama-curses-both', 'hi', 'गौतम लौटकर दोनों को दंड देते हैं', 'गौतम अपने रूप में निकलते इंद्र को देखकर उन्हें शाप देते हैं और अहल्या को लंबे एकांत, अदृश्यता, उपवास तथा राख के बीच जीवन का दंड देते हैं। दंड कठोर है और अवधि में असमान भी। स्रोत भविष्य की शर्त जोड़ता है—राम का आगमन और अहल्या का आतिथ्य इस दंड को समाप्त करेंगे।'),
  ('scene-ahalya-hermitage-awakens', 'rama-enters-silent-hermitage', 'en', 'The travellers perceive the person hidden from the world', 'Rama and Lakshmana enter the apparently abandoned hermitage with Vishvamitra. The source describes Ahalya as present yet inaccessible to ordinary sight. Rama''s arrival does not begin with accusation or interrogation; the brothers recognise her, and she offers the hospitality named in the old condition.'),
  ('scene-ahalya-hermitage-awakens', 'rama-enters-silent-hermitage', 'hi', 'यात्री उस व्यक्ति को अनुभव करते हैं जो संसार से छिपी है', 'राम, लक्ष्मण और विश्वामित्र बाहर से सूने दिखते आश्रम में प्रवेश करते हैं। स्रोत अहल्या को उपस्थित किंतु सामान्य दृष्टि से परे बताता है। राम का आगमन आरोप या पूछताछ से शुरू नहीं होता; दोनों भाई उन्हें पहचानते हैं और वे पुरानी शर्त में कहा आतिथ्य देती हैं।'),
  ('scene-ahalya-hermitage-awakens', 'visibility-and-relationship-return', 'en', 'Ahalya returns to visibility; Gautama returns to the hermitage', 'The curse ends, celestial witnesses celebrate Ahalya''s purification in the selected account, and Gautama reunites with her before honouring Rama. Devam presents this as this source''s resolution, not a universal verdict on blame, consent, punishment, or what restoration should require.'),
  ('scene-ahalya-hermitage-awakens', 'visibility-and-relationship-return', 'hi', 'अहल्या फिर दिखाई देती हैं और गौतम आश्रम लौटते हैं', 'चुनी हुई कथा में शाप समाप्त होता है, दिव्य साक्षी अहल्या की शुद्धि का उत्सव मनाते हैं और गौतम उनसे पुनर्मिलन करके राम का सम्मान करते हैं। देवम इसे इसी स्रोत का समाधान मानता है, दोष, सहमति, दंड या पुनर्स्थापन पर सार्वभौमिक निर्णय नहीं।'),
  ('scene-mithila-appears-beyond-sacrifice', 'sacrifice-city-fills-horizon', 'en', 'Mithila first appears as a vast gathering', 'Approaching northeast, the company sees Janaka''s sacrificial ground crowded with learned visitors, ascetics, carts, shelters, water points, and activity. Rama asks Vishvamitra to choose a calm, well-watered place for their camp rather than forcing the group into the ceremonial centre.'),
  ('scene-mithila-appears-beyond-sacrifice', 'sacrifice-city-fills-horizon', 'hi', 'मिथिला पहले एक विशाल सभा के रूप में दिखाई देती है', 'उत्तर-पूर्व बढ़ते हुए दल को जनक का यज्ञ-स्थल विद्वानों, तपस्वियों, गाड़ियों, आश्रयों, जल-स्थलों और गतिविधि से भरा दिखता है। राम विश्वामित्र से कहते हैं कि समूह के लिए भीड़ से अलग शांत और जलयुक्त स्थान चुना जाए, न कि सबको अनुष्ठान के केंद्र में ठूँस दिया जाए।'),
  ('scene-mithila-appears-beyond-sacrifice', 'janaka-comes-out-to-welcome', 'en', 'Janaka brings the welcome beyond his court', 'Hearing that Vishvamitra has arrived, Janaka comes with Shatananda, priests, and the formal welcome offering. He honours the ascetic, reports that the sacrifice is nearing completion, and asks about the two armed young travellers on foot. Curiosity begins with hospitality rather than suspicion.'),
  ('scene-mithila-appears-beyond-sacrifice', 'janaka-comes-out-to-welcome', 'hi', 'जनक स्वागत के लिए स्वयं बाहर आते हैं', 'विश्वामित्र के आगमन का समाचार पाकर जनक शतानंद, पुरोहितों और स्वागत-सामग्री के साथ स्वयं बाहर आते हैं। वे ऋषि का सम्मान करके यज्ञ की प्रगति बताते हैं और पैदल आए दो युवा धनुर्धरों के बारे में पूछते हैं। जिज्ञासा संदेह नहीं, आतिथ्य से शुरू होती है।'),
  ('scene-mithila-appears-beyond-sacrifice', 'road-becomes-introduction', 'en', 'Vishvamitra answers with what the brothers have done', 'Vishvamitra identifies Rama and Lakshmana through their route: departure from Ayodhya, protection of Siddhashrama, the difficult forest passage, and Ahalya''s hermitage. Their identity is not reduced to Dasharatha''s sons; experience and conduct now accompany lineage.'),
  ('scene-mithila-appears-beyond-sacrifice', 'road-becomes-introduction', 'hi', 'विश्वामित्र भाइयों का परिचय उनकी यात्रा से देते हैं', 'विश्वामित्र राम और लक्ष्मण का परिचय उनकी राह से देते हैं—अयोध्या से प्रस्थान, सिद्धाश्रम की रक्षा, कठिन वन-यात्रा और अहल्या का आश्रम। उनकी पहचान केवल दशरथ के पुत्रों तक सीमित नहीं; अब वंश के साथ अनुभव और आचरण भी जुड़ते हैं।'),
  ('scene-mithila-appears-beyond-sacrifice', 'bow-question-opens-next-world', 'en', 'Their curiosity about the bow becomes the next doorway', 'Vishvamitra explains that the princes have also come to see the mighty bow preserved by Janaka''s house. The nested road stories now converge on a physical object in Mithila. The journey pauses, ready to shift from remembered worlds to Sita''s vow and the bow challenge.'),
  ('scene-mithila-appears-beyond-sacrifice', 'bow-question-opens-next-world', 'hi', 'धनुष के प्रति जिज्ञासा अगला द्वार खोलती है', 'विश्वामित्र बताते हैं कि राजकुमार जनक-गृह में सुरक्षित महान धनुष देखने भी आए हैं। राह की सभी अंतःकथाएँ अब मिथिला की एक वास्तविक वस्तु पर आकर मिलती हैं। यात्रा रुकती है और अगला संसार सीता की प्रतिज्ञा तथा धनुष-परीक्षा की ओर खुलने को तैयार है।'),
  ('scene-shatananda-greets-mothers-restorer', 'shatananda-asks-about-ahalya', 'en', 'A son needs to know what happened at the hermitage', 'When Shatananda hears that the travellers passed through Gautama''s hermitage, public ceremony gives way to urgent family questions. Did Rama see Ahalya, hear what had happened to her, receive her welcome, and witness Gautama return? The priest of Mithila speaks first as a son who has lived with a broken household.'),
  ('scene-shatananda-greets-mothers-restorer', 'shatananda-asks-about-ahalya', 'hi', 'एक पुत्र जानना चाहता है कि आश्रम में क्या हुआ', 'जब शतानंद सुनते हैं कि यात्री गौतम के आश्रम से आए हैं, तो सार्वजनिक औपचारिकता तत्काल पारिवारिक प्रश्नों में बदल जाती है। क्या राम ने अहल्या को देखा, उनकी कथा सुनी, उनका आतिथ्य स्वीकार किया और गौतम को लौटते देखा? मिथिला के पुरोहित पहले उस पुत्र की तरह बोलते हैं जिसने टूटे परिवार का भार सहा है।'),
  ('scene-shatananda-greets-mothers-restorer', 'rama-confirms-the-reunion', 'en', 'Rama answers with a completed return', 'Rama confirms that Ahalya received the brothers and that Gautama returned to the shared ascetic life. The answer does not erase the years of isolation or settle every moral difficulty in her story. It gives Shatananda one concrete relief: the separation he feared is no longer the family''s present condition.'),
  ('scene-shatananda-greets-mothers-restorer', 'rama-confirms-the-reunion', 'hi', 'राम पुनर्मिलन की पूरी खबर देते हैं', 'राम बताते हैं कि अहल्या ने दोनों भाइयों का स्वागत किया और गौतम लौटकर उनके साथ तपस्वी जीवन में जुड़ गए। यह उत्तर वर्षों के एकांत को मिटाता नहीं और कथा की हर नैतिक कठिनाई का सरल समाधान भी नहीं देता। पर शतानंद को एक ठोस राहत मिलती है—जिस वियोग का उन्हें भय था, वह अब परिवार की वर्तमान दशा नहीं है।'),
  ('scene-shatananda-greets-mothers-restorer', 'gratitude-turns-to-vishvamitra', 'en', 'Shatananda turns gratitude toward the guide', 'Relieved, Shatananda honours Rama and then tells him how fortunate he is to travel under Vishvamitra''s protection. His praise is not a list of titles. He promises the story of how a powerful king was defeated by the limits of force, wounded others through anger, began again many times, and eventually became the teacher now beside Rama.'),
  ('scene-shatananda-greets-mothers-restorer', 'gratitude-turns-to-vishvamitra', 'hi', 'शतानंद कृतज्ञता को गुरु की ओर मोड़ते हैं', 'राहत मिलने पर शतानंद राम का सम्मान करते हैं और बताते हैं कि विश्वामित्र के संरक्षण में यात्रा करना कितना महत्त्वपूर्ण है। उनकी प्रशंसा उपाधियों की सूची नहीं है। वे उस शक्तिशाली राजा की कथा आरंभ करते हैं जिसे बल की सीमा ने हराया, जिसने क्रोध में दूसरों को चोट पहुँचाई, बार-बार फिर शुरू किया और अंततः राम के साथ खड़े गुरु का रूप पाया।'),
  ('scene-shatananda-greets-mothers-restorer', 'rama-enters-his-teachers-past', 'en', 'The bow journey pauses for the teacher''s hidden road', 'Rama came to Mithila expecting to see a legendary bow, but the next doorway opens backward into his teacher''s life. This detour changes how the listener reads everything Vishvamitra has already done: disciplined guidance in the present was earned through a past full of appetite, rivalry, compassion, humiliation, and costly repair.'),
  ('scene-shatananda-greets-mothers-restorer', 'rama-enters-his-teachers-past', 'hi', 'धनुष की यात्रा गुरु की छिपी राह के लिए रुकती है', 'राम मिथिला में एक प्रसिद्ध धनुष देखने आए थे, पर अगला द्वार पीछे—उनके गुरु के जीवन में—खुलता है। यह अंतर्कथा विश्वामित्र के अब तक के हर कार्य को नया अर्थ देती है। वर्तमान का संयमित मार्गदर्शन ऐसे अतीत से निकला है जिसमें लालसा, प्रतिद्वंद्विता, करुणा, अपमान और महँगा आत्म-सुधार सब शामिल थे।'),
  ('scene-king-vishvamitra-meets-vasishta', 'army-enters-a-small-hermitage', 'en', 'A royal army enters Vasishta''s quiet world', 'In his former life, King Vishvamitra reaches Vasishta''s hermitage while travelling with a vast army. Vasishta welcomes the king, asks after the people he governs, and insists on feeding the entire company. The scale seems impossible: a forest household is offering more care than a royal expedition expects it can provide.'),
  ('scene-king-vishvamitra-meets-vasishta', 'army-enters-a-small-hermitage', 'hi', 'राजकीय सेना वसिष्ठ के शांत संसार में प्रवेश करती है', 'अपने पूर्व जीवन में राजा विश्वामित्र विशाल सेना के साथ यात्रा करते हुए वसिष्ठ के आश्रम पहुँचते हैं। वसिष्ठ राजा का स्वागत करते हैं, उनकी प्रजा की कुशल पूछते हैं और पूरे दल को भोजन कराने पर अडिग रहते हैं। यह अनुपात असंभव लगता है—वन का छोटा आश्रम राजकीय अभियान की अपेक्षा से कहीं अधिक आतिथ्य देने वाला है।'),
  ('scene-king-vishvamitra-meets-vasishta', 'shabala-makes-abundance', 'en', 'Shabala turns hospitality into abundance', 'At Vasishta''s call, Shabala produces food, drink, vessels, and every required provision until the whole army is satisfied. She is not displayed as an idle treasure in a storehouse; her abundance sustains the hermitage''s duties, guests, offerings, and community. Vishvamitra sees the result but interprets living relationship as transferable royal property.'),
  ('scene-king-vishvamitra-meets-vasishta', 'shabala-makes-abundance', 'hi', 'शबला आतिथ्य को समृद्धि में बदल देती है', 'वसिष्ठ के बुलाने पर शबला भोजन, पेय, पात्र और हर आवश्यक सामग्री प्रकट करती है, जब तक पूरी सेना तृप्त नहीं हो जाती। वह भंडार में रखी निष्क्रिय संपत्ति नहीं है; उसकी समृद्धि आश्रम के कर्तव्य, अतिथि, अर्पण और समुदाय को सँभालती है। विश्वामित्र परिणाम देखते हैं, पर जीवित संबंध को राजकीय संपत्ति समझ लेते हैं।'),
  ('scene-king-vishvamitra-meets-vasishta', 'offer-becomes-command', 'en', 'The king''s generous offer becomes coercion', 'Vishvamitra offers cattle, gold, elephants, horses, and finally his kingdom in exchange for Shabala. Vasishta refuses because she is inseparable from the practices and responsibilities of the hermitage. Unable to accept that refusal, the king changes the meaning of sovereignty from stewardship into entitlement and orders her taken by force.'),
  ('scene-king-vishvamitra-meets-vasishta', 'offer-becomes-command', 'hi', 'राजा का उदार प्रस्ताव दबाव में बदल जाता है', 'विश्वामित्र शबला के बदले गायें, सोना, हाथी, घोड़े और अंततः अपना राज्य तक देने का प्रस्ताव रखते हैं। वसिष्ठ मना करते हैं क्योंकि वह आश्रम के जीवन और उत्तरदायित्वों से अलग नहीं की जा सकती। अस्वीकार स्वीकार न कर पाने पर राजा शासन को संरक्षण नहीं, अधिकार समझ लेते हैं और उसे बलपूर्वक ले जाने का आदेश देते हैं।'),
  ('scene-king-vishvamitra-meets-vasishta', 'shabala-refuses-abandonment', 'en', 'Shabala runs back and asks whether she was abandoned', 'Dragged away by royal servants, Shabala breaks free, returns to Vasishta, and asks what fault made him abandon her. Vasishta says he has not abandoned her; the king''s armed power simply exceeds his ordinary means. Given permission to defend their shared home, Shabala creates fighters who destroy the invading force at terrible cost.'),
  ('scene-king-vishvamitra-meets-vasishta', 'shabala-refuses-abandonment', 'hi', 'शबला लौटकर पूछती है—क्या मुझे छोड़ दिया गया?', 'राजकीय सेवकों द्वारा घसीटी जा रही शबला छूटकर वसिष्ठ के पास लौटती है और पूछती है कि किस दोष के कारण उन्हें त्याग दिया गया। वसिष्ठ कहते हैं कि उन्होंने उसे छोड़ा नहीं; राजा की सशस्त्र शक्ति उनके सामान्य साधनों से बड़ी है। साझा घर की रक्षा की अनुमति पाकर शबला योद्धा उत्पन्न करती है और भारी विनाश के साथ आक्रमणकारी सेना को रोकती है।'),
  ('scene-king-vishvamitra-meets-vasishta', 'weapons-fail-before-brahma-staff', 'en', 'Every celestial weapon disappears into one staff', 'After losing his army and sons, Vishvamitra acquires a terrifying range of celestial weapons and returns to burn the hermitage. Vasishta raises his Brahma staff. Fire, water, wind, illusion, and the final supreme weapon are absorbed or quenched, leaving the attacker exhausted and the ascetic''s authority intact.'),
  ('scene-king-vishvamitra-meets-vasishta', 'weapons-fail-before-brahma-staff', 'hi', 'हर दिव्य अस्त्र एक ब्रह्मदंड में शांत हो जाता है', 'सेना और पुत्रों को खोने के बाद विश्वामित्र अनेक भयंकर दिव्य अस्त्र प्राप्त कर आश्रम नष्ट करने लौटते हैं। वसिष्ठ ब्रह्मदंड उठाते हैं। अग्नि, जल, वायु, भ्रम और अंतिम परम अस्त्र तक उसी में शांत या समाहित हो जाते हैं; आक्रमणकारी थककर रह जाता है और तपस्वी की शक्ति अडिग रहती है।'),
  ('scene-king-vishvamitra-meets-vasishta', 'defeat-becomes-a-new-ambition', 'en', 'Humiliation redirects Vishvamitra, but does not yet heal him', 'Vishvamitra finally admits that royal and military power cannot overcome the discipline he has witnessed. He resolves to gain spiritual power through austerity. Yet his first motive still carries comparison and conquest: he wants to become what defeated him. The long road ahead must transform not only his abilities but the hunger driving them.'),
  ('scene-king-vishvamitra-meets-vasishta', 'defeat-becomes-a-new-ambition', 'hi', 'अपमान विश्वामित्र की दिशा बदलता है, पर उन्हें अभी स्वस्थ नहीं करता', 'विश्वामित्र स्वीकार करते हैं कि राजकीय और सैन्य शक्ति उस साधना को नहीं हरा सकती जिसे उन्होंने देखा। वे तपस्या से आध्यात्मिक शक्ति पाने का संकल्प लेते हैं। फिर भी आरंभिक प्रेरणा में तुलना और विजय छिपी है—वे वही बनना चाहते हैं जिसने उन्हें हराया। आगे की लंबी राह को उनकी क्षमता ही नहीं, उसे चलाने वाली भूख भी बदलनी होगी।'),
  ('scene-trishanku-suspended-between-worlds', 'recognition-still-feels-too-small', 'en', 'A thousand years earn a title he considers insufficient', 'After long austerities, Vishvamitra is recognised as a royal sage, but he hears the title as proof that he has not reached Vasishta''s standing. His practice has produced real change and power, yet the old comparison still decides whether achievement feels meaningful. At this vulnerable point, Trishanku arrives carrying another refusal.'),
  ('scene-trishanku-suspended-between-worlds', 'recognition-still-feels-too-small', 'hi', 'हज़ार वर्ष बाद मिली उपाधि भी उन्हें छोटी लगती है', 'दीर्घ तपस्या के बाद विश्वामित्र को राजर्षि माना जाता है, पर वे इस उपाधि को इस प्रमाण की तरह सुनते हैं कि वे अभी वसिष्ठ के स्तर तक नहीं पहुँचे। साधना ने वास्तविक परिवर्तन और शक्ति दी है, फिर भी पुरानी तुलना तय करती है कि उपलब्धि पर्याप्त है या नहीं। इसी संवेदनशील समय त्रिशंकु एक और अस्वीकृति लेकर आते हैं।'),
  ('scene-trishanku-suspended-between-worlds', 'trishanku-arrives-cursed-and-alone', 'en', 'A king rejected by his teachers asks for refuge', 'Trishanku wants to reach heaven in his living body. Vasishta refuses, and when the king seeks help from Vasishta''s sons, the conflict ends in a curse that changes his appearance and strips away public status. Former companions flee. He reaches Vishvamitra marked as an outcast and insists he has nowhere else to go.'),
  ('scene-trishanku-suspended-between-worlds', 'trishanku-arrives-cursed-and-alone', 'hi', 'गुरुओं से अस्वीकृत राजा शरण माँगता है', 'त्रिशंकु जीवित शरीर सहित स्वर्ग जाना चाहते हैं। वसिष्ठ मना करते हैं और जब राजा उनके पुत्रों से सहायता माँगते हैं, तो विवाद ऐसे शाप पर समाप्त होता है जो उनका रूप बदल देता है और सार्वजनिक प्रतिष्ठा छीन लेता है। पुराने साथी भाग जाते हैं। बहिष्कृत चिह्नों के साथ वे विश्वामित्र के पास पहुँचकर कहते हैं कि अब कोई और आश्रय नहीं है।'),
  ('scene-trishanku-suspended-between-worlds', 'refuge-mixes-with-rivalry', 'en', 'Vishvamitra says fear not—and revives an old contest', 'Moved by the abandoned king, Vishvamitra promises protection and gathers sages for a sacrifice. Compassion is genuine, but refusal by Vasishta''s side reactivates his rage. He curses those who insult him, and other sages participate partly because they fear his anger. A rescue mission is already becoming a test of personal authority.'),
  ('scene-trishanku-suspended-between-worlds', 'refuge-mixes-with-rivalry', 'hi', 'विश्वामित्र कहते हैं ‘डरो मत’—और पुरानी प्रतिस्पर्धा फिर जागती है', 'त्यागे गए राजा को देखकर विश्वामित्र रक्षा का वचन देते हैं और यज्ञ के लिए ऋषियों को बुलाते हैं। करुणा वास्तविक है, पर वसिष्ठ के पक्ष से आया अस्वीकार फिर उनका क्रोध जगा देता है। वे अपमान करने वालों को शाप देते हैं और अन्य ऋषि आंशिक रूप से उनके रोष के भय से शामिल होते हैं। बचाव का कार्य व्यक्तिगत शक्ति की परीक्षा बनने लगता है।'),
  ('scene-trishanku-suspended-between-worlds', 'rise-fall-and-command-to-stop', 'en', 'Trishanku rises, falls, and is caught by one command', 'The rite sends Trishanku upward, but Indra refuses him entry and casts him headfirst back toward earth. As the king falls crying for rescue, Vishvamitra orders him to stop. He hangs upside down between destinations—saved from impact, still excluded from the heaven he sought, and now dependent on the sage''s continuing will.'),
  ('scene-trishanku-suspended-between-worlds', 'rise-fall-and-command-to-stop', 'hi', 'त्रिशंकु ऊपर उठते, गिरते और एक आदेश पर रुक जाते हैं', 'यज्ञ त्रिशंकु को ऊपर उठाता है, पर इंद्र प्रवेश रोककर उन्हें सिर के बल पृथ्वी की ओर गिरा देते हैं। गिरते हुए राजा सहायता पुकारते हैं और विश्वामित्र एक आदेश से उन्हें रोक देते हैं। वे दोनों गंतव्यों के बीच उलटे लटकते हैं—टकराने से बचे, इच्छित स्वर्ग से बाहर और अब ऋषि के लगातार संकल्प पर निर्भर।'),
  ('scene-trishanku-suspended-between-worlds', 'a-new-sky-preserves-the-compromise', 'en', 'A new constellation becomes both refuge and warning', 'Furious, Vishvamitra begins creating new stars and threatens a rival heaven. The gods negotiate: Trishanku may remain luminous in the southern sky, but outside their established order and still inverted. The compromise honours the promise of refuge while preserving, in the night itself, how close compassion came to cosmic retaliation.'),
  ('scene-trishanku-suspended-between-worlds', 'a-new-sky-preserves-the-compromise', 'hi', 'नया नक्षत्र आश्रय भी बनता है और चेतावनी भी', 'क्रोधित विश्वामित्र नए तारे रचने लगते हैं और दूसरा स्वर्ग बनाने की ओर बढ़ते हैं। देवता समझौता करते हैं—त्रिशंकु दक्षिणी आकाश में प्रकाशमान रहेंगे, पर स्थापित व्यवस्था से बाहर और उलटी अवस्था में। यह समाधान शरण के वचन को निभाता है, साथ ही रात के आकाश में दर्ज करता है कि करुणा कितनी जल्दी ब्रह्मांडीय प्रतिशोध के पास पहुँच गई थी।'),
  ('scene-sunashepa-finds-words-to-live', 'a-lost-animal-becomes-a-human-demand', 'en', 'A failed sacrifice transfers its danger to a child', 'When King Ambarisha''s sacrificial animal disappears, his advisers demand a human substitute. After searching widely, the king offers wealth to Richika''s family for one son. The father protects the eldest, the mother protects the youngest, and the middle child Sunahshepa hears himself defined as the one neither parent has reserved.'),
  ('scene-sunashepa-finds-words-to-live', 'a-lost-animal-becomes-a-human-demand', 'hi', 'असफल यज्ञ का संकट एक बच्चे पर डाल दिया जाता है', 'राजा अंबरीष का यज्ञ-पशु गायब होने पर पुरोहित मानव विकल्प की माँग करते हैं। बहुत खोज के बाद राजा ऋचीक के परिवार से एक पुत्र के बदले धन देते हैं। पिता ज्येष्ठ को बचाते हैं, माता कनिष्ठ को; बीच का पुत्र शुनःशेप सुनता है कि वही है जिसे किसी माता-पिता ने अपने लिए सुरक्षित नहीं रखा।'),
  ('scene-sunashepa-finds-words-to-live', 'sunahshepa-runs-to-his-uncle', 'en', 'At Pushkara, the boy chooses whom to ask', 'During a midday halt at Pushkara, exhausted and thirsty Sunahshepa sees his maternal uncle Vishvamitra and throws himself into his lap. He asks not for the king''s death or the rite''s ruin, but for a way in which Ambarisha may complete his purpose and he may still live. His plea restores moral imagination where the adults accepted a binary choice.'),
  ('scene-sunashepa-finds-words-to-live', 'sunahshepa-runs-to-his-uncle', 'hi', 'पुष्कर में बालक स्वयं तय करता है कि सहायता किससे माँगे', 'पुष्कर में दोपहर के विश्राम के समय थके और प्यासे शुनःशेप अपने मामा विश्वामित्र को देखकर उनकी गोद में गिर पड़ते हैं। वे राजा की मृत्यु या यज्ञ के विनाश की माँग नहीं करते; वे ऐसी राह चाहते हैं जिसमें अंबरीष का उद्देश्य पूरा हो और वे स्वयं भी जीवित रहें। उनकी विनती वहाँ नैतिक कल्पना लौटाती है जहाँ बड़े केवल दो कठोर विकल्प मान चुके थे।'),
  ('scene-sunashepa-finds-words-to-live', 'vishvamitra-sons-refuse-substitution', 'en', 'Vishvamitra offers his sons—and answers refusal with a curse', 'Vishvamitra asks his own sons to take Sunahshepa''s place, presenting the exchange as family duty and rescue. They refuse, protesting that saving another by sacrificing one''s own child reverses the same moral problem. Vishvamitra responds with a devastating curse. His wish to protect one vulnerable boy remains entangled with coercion toward others.'),
  ('scene-sunashepa-finds-words-to-live', 'vishvamitra-sons-refuse-substitution', 'hi', 'विश्वामित्र अपने पुत्रों को आगे रखते हैं—और अस्वीकार पर शाप देते हैं', 'विश्वामित्र अपने पुत्रों से शुनःशेप का स्थान लेने को कहते हैं और इसे परिवार का कर्तव्य तथा बचाव बताते हैं। वे मना करते हैं—किसी दूसरे को बचाने के लिए अपने ही बच्चे को बलि देना उसी नैतिक समस्या को उलट देता है। विश्वामित्र भयंकर शाप से उत्तर देते हैं। एक असहाय बालक की रक्षा की इच्छा अब भी दूसरों पर दबाव से उलझी है।'),
  ('scene-sunashepa-finds-words-to-live', 'words-create-a-third-outcome', 'en', 'The boy carries the prayers that keep him alive', 'Vishvamitra teaches Sunahshepa two prayers and tells him when to speak them at the sacrificial post. Bound, marked, and brought into the rite, the boy uses the words himself. The gods respond, grant him long life, and allow the sacrifice to conclude. Survival comes through his voiced appeal, not through pretending no danger occurred.'),
  ('scene-sunashepa-finds-words-to-live', 'words-create-a-third-outcome', 'hi', 'बालक वे प्रार्थनाएँ लेकर जाता है जो उसे जीवित रखती हैं', 'विश्वामित्र शुनःशेप को दो प्रार्थनाएँ सिखाते हैं और बताते हैं कि यज्ञ-स्तंभ पर उन्हें कब बोलना है। बाँधे, चिह्नित और अनुष्ठान में लाए गए बालक वे शब्द स्वयं कहते हैं। देवता उत्तर देते हैं, उन्हें दीर्घ जीवन मिलता है और यज्ञ भी पूर्ण होता है। बचाव उसकी अपनी कही पुकार से आता है, यह मान लेने से नहीं कि कोई संकट था ही नहीं।'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'success-keeps-an-old-measuring-stick', 'en', 'Each title reveals the comparison still ruling him', 'After Sunahshepa survives, Vishvamitra returns to austerity and receives greater recognition. Each time, he asks whether the final title—Brahmarshi—has been granted and whether his senses are truly mastered. The question is honest, but it also shows that an external rank and Vasishta''s standing still control the meaning of his inner work.'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'success-keeps-an-old-measuring-stick', 'hi', 'हर उपाधि दिखाती है कि पुरानी तुलना अभी भी उन्हें चला रही है', 'शुनःशेप के बचने के बाद विश्वामित्र फिर तपस्या करते हैं और ऊँची मान्यता पाते हैं। हर बार वे देखते हैं कि क्या अंतिम ब्रह्मर्षि उपाधि मिली और क्या इंद्रियाँ सच में वश में हुईं। प्रश्न ईमानदार है, पर यह भी दिखाता है कि बाहरी पद और वसिष्ठ का स्तर अभी उनकी भीतर की साधना का अर्थ तय कर रहे हैं।'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'menaka-and-ten-years', 'en', 'Desire turns one season into ten years', 'At Pushkara, Vishvamitra sees Menaka and asks her to stay. Ten years pass in companionship before he understands that the gods used desire to interrupt his practice. He sends her away without the destructive curse that will mark a later test, but shame drives him north. Their daughter Shakuntala belongs to the human consequence of these years, not to a disposable temptation montage.'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'menaka-and-ten-years', 'hi', 'कामना एक ऋतु को दस वर्षों में बदल देती है', 'पुष्कर में विश्वामित्र मेनका को देखकर उनसे रुकने को कहते हैं। संग-साथ में दस वर्ष बीतते हैं, तब उन्हें समझ आता है कि देवताओं ने उनकी साधना रोकने के लिए इच्छा का उपयोग किया। वे मेनका को उस विनाशकारी शाप के बिना विदा करते हैं जो आगे की परीक्षा में आएगा, पर लज्जा उन्हें उत्तर ले जाती है। उनकी पुत्री शकुंतला इन वर्षों का मानवीय परिणाम है, कोई फेंक देने योग्य बाधा नहीं।'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'rambha-bears-the-anger', 'en', 'He resists desire but fails the test of anger', 'When frightened Rambha is sent to disturb another period of austerity, Vishvamitra recognises the trap and does not yield to attraction. Yet he curses her to become stone for thousands of years. The episode refuses a false victory: control that merely transfers impulse from desire into punishment is not self-mastery, and Rambha bears the cost of his rage.'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'rambha-bears-the-anger', 'hi', 'वे इच्छा रोकते हैं, पर क्रोध की परीक्षा में हारते हैं', 'जब भयभीत रंभा को दूसरी तपस्या भंग करने भेजा जाता है, विश्वामित्र जाल पहचान लेते हैं और आकर्षण में नहीं पड़ते। फिर भी वे उसे हजारों वर्षों तक पत्थर होने का शाप देते हैं। यह घटना झूठी विजय स्वीकार नहीं करती—इच्छा को रोककर उसी आवेग को सजा में बदल देना आत्म-संयम नहीं है, और उनके क्रोध की कीमत रंभा चुकाती है।'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'silence-replaces-retaliation', 'en', 'The next discipline is not to strike back', 'Vishvamitra resolves not to speak in anger, to endure heat, cold, rain, hunger, and provocation, and to begin again if needed. The scale is deliberately exhausting: transformation is not a single revelation after the curse, but a long practice of reaching the same trigger without repeating the same harm.'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'silence-replaces-retaliation', 'hi', 'अगली साधना है—उत्तर में प्रहार न करना', 'विश्वामित्र संकल्प लेते हैं कि क्रोध में नहीं बोलेंगे, गर्मी, सर्दी, वर्षा, भूख और उकसावे को सहेंगे और आवश्यकता हुई तो फिर से आरंभ करेंगे। यह विस्तार जानबूझकर थकाने वाला है—परिवर्तन शाप के बाद मिली एक अचानक सीख नहीं, बल्कि उसी उकसावे तक पहुँचकर पुरानी हानि न दोहराने का लंबा अभ्यास है।'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'last-meal-is-given-away', 'en', 'At the edge of completion, he gives away the food', 'After a vast fast, Vishvamitra prepares to eat. Indra arrives disguised as a hungry Brahmin and asks for the entire meal. Vishvamitra gives it without anger or complaint, then continues the vow for another immense span. The scene revisits his first encounter with abundance: he no longer seizes what sustains another or treats giving as a transaction for rank.'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'last-meal-is-given-away', 'hi', 'पूर्णता के किनारे वे अपना भोजन भी दे देते हैं', 'बहुत लंबे उपवास के बाद विश्वामित्र भोजन करने बैठते हैं। इंद्र भूखे ब्राह्मण का रूप लेकर पूरा भोजन माँगते हैं। विश्वामित्र बिना क्रोध या शिकायत के सब दे देते हैं और फिर लंबी साधना जारी रखते हैं। दृश्य शबला वाले पहले प्रसंग को उलटता है—अब वे किसी दूसरे का पोषण नहीं छीनते और दान को पद पाने का सौदा नहीं बनाते।'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'vasishta-recognises-a-brahmarshi', 'en', 'The final recognition comes with reconciliation', 'The gods finally call Vishvamitra Brahmarshi, but he asks that Vasishta recognise the change too. Vasishta does so, and the old rivals make peace. The ending matters because it is relational, not merely promotional: the man who once tried to overpower Vasishta no longer needs to defeat him in order to stand beside him.'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'vasishta-recognises-a-brahmarshi', 'hi', 'अंतिम मान्यता मेल-मिलाप के साथ आती है', 'देवता अंततः विश्वामित्र को ब्रह्मर्षि कहते हैं, पर वे चाहते हैं कि वसिष्ठ भी इस परिवर्तन को स्वीकार करें। वसिष्ठ स्वीकार करते हैं और पुराने प्रतिद्वंद्वी मेल कर लेते हैं। अंत इसलिए महत्त्वपूर्ण है कि यह केवल पदोन्नति नहीं, संबंध का सुधार है—जो व्यक्ति कभी वसिष्ठ को हराना चाहता था, अब उनके बराबर खड़े होने के लिए उन्हें पराजित नहीं करना चाहता।'),
  ('scene-janaka-names-sitas-vow', 'bow-is-a-trust-not-a-trophy', 'en', 'The bow entered Janaka''s house as a trust', 'Asked to show the bow, Janaka first explains why his family keeps it. Associated with Shiva''s fury at Daksha''s sacrifice, the weapon was entrusted to an ancestor rather than won in a tournament. Its immense force and ritual care have made it a guarded inheritance long before Rama arrives to test it.'),
  ('scene-janaka-names-sitas-vow', 'bow-is-a-trust-not-a-trophy', 'hi', 'धनुष जनक के घर में धरोहर बनकर आया', 'धनुष दिखाने को कहे जाने पर जनक पहले बताते हैं कि उनका परिवार इसे क्यों सँभालता है। दक्ष-यज्ञ पर शिव के क्रोध से जुड़ा यह अस्त्र किसी प्रतियोगिता में जीता नहीं गया; इसे एक पूर्वज को धरोहर के रूप में सौंपा गया था। राम की परीक्षा से बहुत पहले से इसकी अपार शक्ति और पूजा ने इसे सुरक्षित विरासत बना रखा है।'),
  ('scene-janaka-names-sitas-vow', 'sita-rises-from-the-field', 'en', 'While Janaka ploughs, a daughter appears', 'Janaka recalls ploughing the ground for a rite when an infant emerged from the furrow. He received her as his daughter and named her Sita, tying her origin to cultivated earth and the work of preparing a sacred field. The story centres adoption and chosen parenthood: Janaka does not merely discover a marvel; he raises a child.'),
  ('scene-janaka-names-sitas-vow', 'sita-rises-from-the-field', 'hi', 'जनक के हल चलाते समय एक पुत्री प्रकट होती है', 'जनक स्मरण करते हैं कि अनुष्ठान के लिए भूमि जोतते समय हल की रेखा से एक शिशु मिली। उन्होंने उसे पुत्री के रूप में अपनाया और सीता नाम दिया; उसका जन्म खेती की धरती और पवित्र क्षेत्र तैयार करने के श्रम से जुड़ गया। कथा दत्तक संबंध को केंद्र में रखती है—जनक केवल चमत्कार नहीं पाते, वे एक बच्ची का पालन करते हैं।'),
  ('scene-janaka-names-sitas-vow', 'janaka-binds-marriage-to-the-bow', 'en', 'A father makes prowess the condition of marriage', 'As suitors arrive, Janaka declares that Sita will marry the person able to string the bow. In his account this is his vow, not a choice Sita is given a chance to speak in the hall. That distinction remains visible: the condition seeks extraordinary strength, yet it also places her future inside a public test designed by her father.'),
  ('scene-janaka-names-sitas-vow', 'janaka-binds-marriage-to-the-bow', 'hi', 'एक पिता विवाह को पराक्रम की शर्त से बाँध देता है', 'वरों के आने पर जनक घोषणा करते हैं कि सीता का विवाह उसी से होगा जो धनुष पर प्रत्यंचा चढ़ा सके। चुना हुआ स्रोत इसे जनक की प्रतिज्ञा बताता है; इस दृश्य में सीता स्वयं यह चुनाव बोलती नहीं हैं। यह अंतर स्पष्ट रहता है—शर्त असाधारण पुत्री के लिए असाधारण सामर्थ्य चाहती है, पर उसके भविष्य को पिता द्वारा बनाई सार्वजनिक परीक्षा में भी रख देती है।'),
  ('scene-janaka-names-sitas-vow', 'failed-suitors-besiege-mithila', 'en', 'Failure at the bow becomes war against the city', 'The assembled kings cannot even wield the bow. Humiliated, they besiege Mithila and exhaust Janaka''s resources for a year until divine aid provides forces that drive them away. The challenge is therefore not festive spectacle when Rama enters it; Sita''s proposed marriage and the city''s safety have already been threatened by men who treated refusal as an insult.'),
  ('scene-janaka-names-sitas-vow', 'failed-suitors-besiege-mithila', 'hi', 'धनुष पर असफलता नगर के विरुद्ध युद्ध बन जाती है', 'एकत्र राजा धनुष को चला तक नहीं पाते। अपमानित होकर वे मिथिला को घेर लेते हैं और एक वर्ष तक जनक के साधन समाप्त करते हैं; अंततः देव-सहायता से मिली सेना उन्हें हटाती है। इसलिए राम के प्रवेश के समय यह कोई हल्की प्रतियोगिता नहीं है—सीता के विवाह और नगर की सुरक्षा को उन पुरुषों ने पहले ही संकट में डाला जो अस्वीकार को अपमान मानते थे।'),
  ('scene-rama-breaks-the-bow', 'five-thousand-bring-the-chest', 'en', 'The object arrives with the weight of a world', 'Janaka orders the bow brought from its guarded chamber. Five thousand strong attendants struggle to draw the iron chest on an eight-wheeled cart into the assembly. The labour gives the audience a physical measure before Rama touches it: this is not a glowing icon floating conveniently into a hero''s hand.'),
  ('scene-rama-breaks-the-bow', 'five-thousand-bring-the-chest', 'hi', 'वस्तु पूरे संसार के भार के साथ सभा में आती है', 'जनक सुरक्षित कक्ष से धनुष लाने का आदेश देते हैं। पाँच हजार बलवान सेवक आठ पहियों वाली गाड़ी पर रखे लोहे के संदूक को कठिनाई से सभा तक खींचते हैं। राम के स्पर्श से पहले यह श्रम दर्शक को वास्तविक पैमाना देता है—यह कोई चमकता प्रतीक नहीं जो सहज ही नायक के हाथ में आ जाए।'),
  ('scene-rama-breaks-the-bow', 'rama-asks-before-touching', 'en', 'Rama waits for permission', 'The chest opens and Janaka repeats that generations of mighty beings and kings have failed to string the bow. Rama does not seize the famous object to prove himself. At Vishvamitra''s invitation he asks to examine it and to try lifting and stringing it, keeping the feat inside the trust between guest, guide, and host.'),
  ('scene-rama-breaks-the-bow', 'rama-asks-before-touching', 'hi', 'राम स्पर्श से पहले अनुमति लेते हैं', 'संदूक खुलता है और जनक बताते हैं कि पीढ़ियों के शक्तिशाली प्राणी तथा राजा इस धनुष पर प्रत्यंचा नहीं चढ़ा सके। राम प्रसिद्ध वस्तु को स्वयं को सिद्ध करने के लिए झपटकर नहीं उठाते। विश्वामित्र के संकेत पर वे उसे देखने, उठाने और चढ़ाने की अनुमति माँगते हैं; कार्य अतिथि, गुरु और मेज़बान के विश्वास के भीतर रहता है।'),
  ('scene-rama-breaks-the-bow', 'bow-breaks-like-thunder', 'en', 'Lifting becomes stringing; stringing becomes thunder', 'Rama lifts the bow before the watching multitude and begins to string and draw it. The weapon snaps in the middle with a crash compared to a mountain splitting or thunder striking nearby. Almost everyone falls stunned except Rama, Lakshmana, Vishvamitra, and Janaka; the achievement changes the hall before anyone can turn it into celebration.'),
  ('scene-rama-breaks-the-bow', 'bow-breaks-like-thunder', 'hi', 'उठाना प्रत्यंचा चढ़ाने में और प्रत्यंचा वज्र-ध्वनि में बदलती है', 'राम सबके सामने धनुष उठाकर प्रत्यंचा चढ़ाते और उसे खींचते हैं। वह बीच से ऐसी ध्वनि के साथ टूटता है मानो पर्वत फट गया हो या पास ही वज्र गिरा हो। राम, लक्ष्मण, विश्वामित्र और जनक को छोड़ लगभग पूरी सभा स्तब्ध होकर गिर पड़ती है; उत्सव शुरू होने से पहले ही यह घटना सभा का संसार बदल देती है।'),
  ('scene-rama-breaks-the-bow', 'janaka-sends-for-dasharatha', 'en', 'The vow is fulfilled, but the wedding is not assumed', 'Janaka declares that Rama has fulfilled the bow condition and says he will give beloved Sita to him. Yet he does not stage an instant marriage around a triumphant stranger. With Vishvamitra''s permission, messengers must go to Ayodhya, report the brothers'' safety and the feat, and invite Dasharatha. One family vow now opens into a meeting between two households.'),
  ('scene-rama-breaks-the-bow', 'janaka-sends-for-dasharatha', 'hi', 'प्रतिज्ञा पूरी हुई, पर विवाह को स्वतः पूर्ण नहीं माना गया', 'जनक कहते हैं कि राम ने धनुष की शर्त पूरी कर दी और वे प्रिय सीता का विवाह उनसे करेंगे। फिर भी वे विजयी अजनबी के साथ तत्काल विवाह नहीं कराते। विश्वामित्र की अनुमति से दूत अयोध्या जाएँगे, भाइयों की कुशल और घटना का समाचार देंगे तथा दशरथ को बुलाएँगे। एक परिवार की प्रतिज्ञा अब दो घरों के मिलन का द्वार खोलती है।'),
  ('scene-mithila-envoys-reach-ayodhya', 'envoys-carry-more-than-victory', 'en', 'Three days of travel carry a changed future', 'Janaka''s messengers leave Mithila immediately and reach Ayodhya after three demanding days. They carry more than news that Rama broke an impossible bow: Janaka has linked the feat to his vow concerning Sita, and the next decision belongs before Dasharatha, his priests, and the royal household.'),
  ('scene-mithila-envoys-reach-ayodhya', 'envoys-carry-more-than-victory', 'hi', 'तीन दिन की यात्रा एक बदला हुआ भविष्य लेकर आती है', 'जनक के दूत तुरंत मिथिला से निकलते हैं और कठिन तीन दिन की यात्रा के बाद अयोध्या पहुँचते हैं। वे केवल असंभव धनुष टूटने का समाचार नहीं लाते—जनक ने उस घटना को सीता के विषय में अपनी प्रतिज्ञा से जोड़ दिया है और अगला निर्णय दशरथ, पुरोहितों तथा राजपरिवार के सामने होना है।'),
  ('scene-mithila-envoys-reach-ayodhya', 'welfare-comes-before-the-feat', 'en', 'The message begins with the sons'' safety', 'Before describing the feat, the envoys exchange formal wishes for everyone''s wellbeing and report that Rama and Lakshmana are safe under Vishvamitra''s care. For a father who released two young sons into danger, that order matters. Astonishment can begin only after the household knows the travellers are alive and unharmed.'),
  ('scene-mithila-envoys-reach-ayodhya', 'welfare-comes-before-the-feat', 'hi', 'संदेश पहले पुत्रों की कुशल बताता है', 'पराक्रम बताने से पहले दूत सबकी कुशल पूछते हैं और बताते हैं कि राम तथा लक्ष्मण विश्वामित्र की रक्षा में सुरक्षित हैं। जिस पिता ने दो युवा पुत्रों को संकट की राह पर भेजा था, उसके लिए यह क्रम महत्त्वपूर्ण है। आश्चर्य तभी शुरू हो सकता है जब परिवार जान ले कि यात्री जीवित और सकुशल हैं।'),
  ('scene-mithila-envoys-reach-ayodhya', 'janaka-asks-not-assumes', 'en', 'Janaka invites Dasharatha instead of declaring a wedding', 'The envoys repeat Janaka''s promise to give Sita to the person who could string the bow and confirm that Rama has met it. Yet the king asks Dasharatha to come if the alliance is agreeable. The language leaves room for the other household; prowess has opened the proposal, not completed every family decision.'),
  ('scene-mithila-envoys-reach-ayodhya', 'janaka-asks-not-assumes', 'hi', 'जनक विवाह घोषित नहीं करते, दशरथ को आमंत्रित करते हैं', 'दूत जनक की उस प्रतिज्ञा को दोहराते हैं जिसमें सीता का विवाह धनुष चढ़ाने वाले से होना था और बताते हैं कि राम ने शर्त पूरी की। फिर भी राजा कहते हैं कि यदि संबंध स्वीकार्य हो तो दशरथ आएँ। शब्द दूसरे परिवार के लिए स्थान रखते हैं—पराक्रम ने प्रस्ताव खोला है, हर पारिवारिक निर्णय पूरा नहीं किया।'),
  ('scene-mithila-envoys-reach-ayodhya', 'dasharatha-consults-and-accepts', 'en', 'The court answers together', 'Dasharatha shares the message with Vasishta, Vamadeva, ministers, and advisers rather than answering from excitement alone. They approve the alliance, and he orders departure for the next morning. The scene turns a spectacular individual achievement into a collective commitment with witnesses and practical obligations.'),
  ('scene-mithila-envoys-reach-ayodhya', 'dasharatha-consults-and-accepts', 'hi', 'सभा मिलकर उत्तर देती है', 'दशरथ उत्साह में अकेले उत्तर देने के बजाय संदेश वसिष्ठ, वामदेव, मंत्रियों और सलाहकारों के साथ बाँटते हैं। सब संबंध स्वीकार करते हैं और वे अगली सुबह प्रस्थान का आदेश देते हैं। यह दृश्य व्यक्तिगत चमत्कार को साक्षियों तथा वास्तविक उत्तरदायित्वों वाली सामूहिक प्रतिबद्धता में बदल देता है।'),
  ('scene-dasharatha-travels-to-mithila', 'ayodhya-prepares-a-household-journey', 'en', 'A royal wedding requires more than a fast chariot', 'Dasharatha sends treasury officers, gifts, protected wealth, vehicles, and the fourfold forces ahead. Vasishta and other trusted priests accompany him, as do Bharata and Shatrughna. The travelling group is not an invasion or victory parade; it carries the people and resources required to negotiate and establish new kinship.'),
  ('scene-dasharatha-travels-to-mithila', 'ayodhya-prepares-a-household-journey', 'hi', 'राजविवाह के लिए केवल तेज़ रथ पर्याप्त नहीं', 'दशरथ कोषाध्यक्षों, उपहारों, सुरक्षित धन, वाहनों और चतुरंगिणी सेना को आगे भेजते हैं। वसिष्ठ तथा अन्य विश्वस्त पुरोहित और भरत-शत्रुघ्न भी साथ चलते हैं। यह दल आक्रमण या विजय-यात्रा नहीं; वह नए संबंध पर विचार और उसे स्थापित करने के लिए आवश्यक लोग तथा साधन लेकर चलता है।'),
  ('scene-dasharatha-travels-to-mithila', 'four-days-reconnect-the-brothers', 'en', 'The road closes the distance opened at Ayodhya', 'After four days the procession reaches Videha. Rama and Lakshmana''s earlier journey with Vishvamitra had stripped away palace support; now the family follows their path because the brothers acted well beyond it. Bharata and Shatrughna enter the Mithila world that until now belonged only to the travelling pair.'),
  ('scene-dasharatha-travels-to-mithila', 'four-days-reconnect-the-brothers', 'hi', 'राह अयोध्या से खुली दूरी को फिर बंद करती है', 'चार दिन बाद यात्रा विदेह पहुँचती है। विश्वामित्र के साथ राम-लक्ष्मण की पहली राह ने महल का सहारा पीछे छोड़ दिया था; अब परिवार उसी राह पर आता है क्योंकि दोनों भाइयों ने बाहर जाकर उत्तरदायित्व निभाया। भरत और शत्रुघ्न उस मिथिला-संसार में प्रवेश करते हैं जो अब तक केवल यात्री जोड़ी का था।'),
  ('scene-dasharatha-travels-to-mithila', 'janaka-welcomes-rama-father', 'en', 'Janaka receives the father behind the traveller', 'Janaka goes out to honour Dasharatha and speaks openly of the joy Rama has brought to Mithila. Dasharatha answers that a giver''s invitation should guide the receiver and places the next steps with Janaka. Mutual courtesy prevents either king from treating the marriage as a conquest by his own house.'),
  ('scene-dasharatha-travels-to-mithila', 'janaka-welcomes-rama-father', 'hi', 'जनक यात्री के पीछे खड़े पिता का स्वागत करते हैं', 'जनक दशरथ का सम्मान करने बाहर आते हैं और उस आनंद की बात कहते हैं जो राम ने मिथिला को दिया। दशरथ उत्तर देते हैं कि देने वाले का निमंत्रण पाने वाले का मार्ग तय करता है और आगे की प्रक्रिया जनक पर छोड़ते हैं। परस्पर सम्मान किसी भी राजा को विवाह को अपने घर की विजय मानने से रोकता है।'),
  ('scene-dasharatha-travels-to-mithila', 'sacrifice-makes-room-for-wedding', 'en', 'Janaka completes one duty before beginning another', 'Janaka explains that his sacrifice must reach its proper conclusion before the marriage rites begin. He completes the remaining observances and prepares what his daughters'' weddings require. Celebration therefore grows from ordered responsibilities rather than allowing the dramatic bow moment to sweep every existing commitment aside.'),
  ('scene-dasharatha-travels-to-mithila', 'sacrifice-makes-room-for-wedding', 'hi', 'जनक नया कर्तव्य शुरू करने से पहले पहला पूरा करते हैं', 'जनक बताते हैं कि विवाह-विधि शुरू होने से पहले यज्ञ को उचित रूप से पूरा करना होगा। वे शेष अनुष्ठान पूर्ण करते हैं और पुत्रियों के विवाह की तैयारी करते हैं। इस तरह उत्सव व्यवस्थित उत्तरदायित्वों से निकलता है; धनुष का नाटकीय क्षण पहले से चल रहे हर कर्तव्य को बहा नहीं ले जाता।'),
  ('scene-two-houses-recite-their-lineages', 'janaka-calls-his-brother', 'en', 'Kushadhvaja must share the family''s decision', 'Janaka first summons his brother Kushadhvaja from Sankashya. He does not treat Sita and Urmila''s marriages as an isolated royal command, because Kushadhvaja governs beside this household and has daughters of his own. The alliance enters a wider family network before anyone settles all four pairings.'),
  ('scene-two-houses-recite-their-lineages', 'janaka-calls-his-brother', 'hi', 'कुशध्वज को परिवार के निर्णय में शामिल होना है', 'जनक पहले अपने भाई कुशध्वज को सांकाश्य से बुलाते हैं। वे सीता और उर्मिला के विवाह को अकेली राजाज्ञा नहीं मानते, क्योंकि कुशध्वज इस परिवार के साथ शासन करते हैं और उनकी अपनी पुत्रियाँ भी हैं। चारों संबंध तय होने से पहले प्रस्ताव व्यापक पारिवारिक जाल में प्रवेश करता है।'),
  ('scene-two-houses-recite-their-lineages', 'vasishta-turns-names-into-history', 'en', 'Vasishta tells what the Ikshvaku house carries', 'Vasishta recounts the Ayodhya line from ancient beginnings through famous rulers to Dasharatha and his four sons. The experience need not force users to memorise a column of names: the important movement is continuity—public duty, hard-won reputation, failures, and promises accumulating behind the young men now asking to join another family.'),
  ('scene-two-houses-recite-their-lineages', 'vasishta-turns-names-into-history', 'hi', 'वसिष्ठ बताते हैं कि इक्ष्वाकु घराना क्या साथ लाता है', 'वसिष्ठ अयोध्या के वंश को प्राचीन आरंभ से प्रसिद्ध राजाओं, दशरथ और उनके चार पुत्रों तक सुनाते हैं। उपयोगकर्ता को नामों का लंबा स्तंभ याद करना आवश्यक नहीं; महत्त्वपूर्ण गति है निरंतरता—सार्वजनिक कर्तव्य, कमाई प्रतिष्ठा, असफलताएँ और वचन उन युवाओं के पीछे जमा हैं जो अब दूसरे परिवार से जुड़ेंगे।'),
  ('scene-two-houses-recite-their-lineages', 'janaka-answers-with-videha-line', 'en', 'Janaka answers with the history of Videha', 'Janaka responds with the Videha line from Nimi and Mithi through the successive Janakas to himself and Kushadhvaja. He includes the conflict that placed the brothers in their present kingdoms. Disclosure is reciprocal: Sita and the other women are not entering an examined house from an invisible one; both families state who they are.'),
  ('scene-two-houses-recite-their-lineages', 'janaka-answers-with-videha-line', 'hi', 'जनक विदेह के इतिहास से उत्तर देते हैं', 'जनक निमि और मिथि से आरंभ होकर अनेक जनकों, स्वयं और कुशध्वज तक विदेह वंश बताते हैं। वे उस संघर्ष को भी शामिल करते हैं जिसने दोनों भाइयों को वर्तमान राज्यों में रखा। परिचय परस्पर है—सीता और अन्य युवतियाँ किसी अदृश्य घर से जाँचे गए घर में नहीं जा रहीं; दोनों परिवार अपना इतिहास सामने रखते हैं।'),
  ('scene-two-houses-recite-their-lineages', 'alliance-expands-to-four-couples', 'en', 'One proposal becomes four distinct partnerships', 'Janaka offers Sita to Rama and Urmila to Lakshmana. Vishvamitra and Vasishta then propose Kushadhvaja''s daughters Mandavi and Shrutakirti for Bharata and Shatrughna. The expansion is not four interchangeable royal matches; it creates four named relationships whose lives will later follow different emotional and political roads.'),
  ('scene-two-houses-recite-their-lineages', 'alliance-expands-to-four-couples', 'hi', 'एक प्रस्ताव चार अलग साझेदारियों में बढ़ता है', 'जनक सीता का विवाह राम से और उर्मिला का लक्ष्मण से प्रस्तावित करते हैं। विश्वामित्र तथा वसिष्ठ फिर कुशध्वज की पुत्रियों मांडवी और श्रुतकीर्ति का संबंध भरत तथा शत्रुघ्न से रखते हैं। यह चार समान राजकीय जोड़ियाँ नहीं; चार नामित रिश्ते हैं जिनके जीवन आगे अलग भावनात्मक और राजनीतिक राहों पर चलेंगे।'),
  ('scene-two-houses-recite-their-lineages', 'time-gifts-and-ancestors-prepare', 'en', 'Agreement becomes preparation', 'The households choose an auspicious time, perform ancestral remembrance, and distribute cattle and wealth before the weddings. These actions connect future couples to people beyond the hall—ancestors, dependants, priests, and communities. The family alliance is made materially visible before vows are spoken around the fire.'),
  ('scene-two-houses-recite-their-lineages', 'time-gifts-and-ancestors-prepare', 'hi', 'सहमति वास्तविक तैयारी में बदलती है', 'दोनों परिवार शुभ समय चुनते हैं, पूर्वजों का स्मरण करते हैं और विवाह से पहले गायें तथा धन बाँटते हैं। ये कार्य नए दंपतियों को सभा से बाहर के लोगों—पूर्वजों, आश्रितों, पुरोहितों और समुदाय—से जोड़ते हैं। अग्नि के सामने वचन से पहले ही पारिवारिक संबंध वास्तविक रूप में दिखाई देने लगता है।'),
  ('scene-four-brothers-four-marriages', 'pavilion-gathers-both-houses', 'en', 'The prepared world gathers around one fire', 'The wedding pavilion is arranged with altar, vessels, flowers, grain, elders, visiting kin, musicians, and witnesses. Vasishta establishes the sacred fire and completes the shared rites. The setting makes the marriage public and relational: the couples do not disappear into a private cut-scene detached from the world they will inhabit.'),
  ('scene-four-brothers-four-marriages', 'pavilion-gathers-both-houses', 'hi', 'तैयार संसार एक अग्नि के चारों ओर जुटता है', 'विवाह-मंडप में वेदी, पात्र, फूल, अन्न, बड़े-बुज़ुर्ग, आए हुए संबंधी, संगीत और साक्षी व्यवस्थित हैं। वसिष्ठ अग्नि स्थापित कर साझा विधि पूरी करते हैं। विवाह सार्वजनिक और संबंधपूर्ण बनता है—दंपति उस संसार से कटी निजी झलक में गायब नहीं होते जिसमें उन्हें आगे जीना है।'),
  ('scene-four-brothers-four-marriages', 'janaka-places-sita-beside-rama', 'en', 'Janaka gives Sita''s hand and asks for partnership', 'Janaka brings Sita beside Rama, pours the ceremonial water, and asks him to receive her as a partner in shared duty. The bow feat recedes; the scene now concerns a person leaving one household and entering another. Sita stands at the centre of the transition rather than appearing as the prize attached to a broken object.'),
  ('scene-four-brothers-four-marriages', 'janaka-places-sita-beside-rama', 'hi', 'जनक सीता का हाथ देकर साझेदारी का आग्रह करते हैं', 'जनक सीता को राम के पास लाते हैं, विधि का जल अर्पित करते हैं और उन्हें साझा धर्म की सहचरी के रूप में स्वीकार करने को कहते हैं। धनुष-भंग पीछे चला जाता है; अब दृश्य एक व्यक्ति के एक घर से दूसरे घर में प्रवेश का है। सीता टूटे अस्त्र से जुड़ा पुरस्कार नहीं, परिवर्तन के केंद्र में खड़ी हैं।'),
  ('scene-four-brothers-four-marriages', 'three-more-couples-step-forward', 'en', 'Urmila, Mandavi, and Shrutakirti enter their own vows', 'Urmila joins Lakshmana, Mandavi joins Bharata, and Shrutakirti joins Shatrughna. Each pairing receives a separate movement and name rather than being compressed into ''the brothers also married.'' The shared ceremony binds the family, while distinct staging preserves four beginnings that will not have identical futures.'),
  ('scene-four-brothers-four-marriages', 'three-more-couples-step-forward', 'hi', 'उर्मिला, मांडवी और श्रुतकीर्ति अपने वचनों में प्रवेश करती हैं', 'उर्मिला लक्ष्मण, मांडवी भरत और श्रुतकीर्ति शत्रुघ्न के साथ आगे आती हैं। हर जोड़ी को अलग गति और नाम मिलता है; उन्हें ‘बाकी भाइयों का भी विवाह हुआ’ में नहीं समेटा जाता। साझा विधि परिवार जोड़ती है, जबकि अलग प्रस्तुति चार ऐसे आरंभ बचाती है जिनका भविष्य एक जैसा नहीं होगा।'),
  ('scene-four-brothers-four-marriages', 'four-circles-around-the-fire', 'en', 'The couples complete the shared movement', 'Hands joined, the couples circle the fire while blessings, music, and celebration fill the pavilion. The movement closes the formal transition but opens four new story routes. Users can follow any person from this hub—back to Mithila, forward to Ayodhya, or later into exile, governance, waiting, and family separation.'),
  ('scene-four-brothers-four-marriages', 'four-circles-around-the-fire', 'hi', 'चारों दंपति साझा परिक्रमा पूरी करते हैं', 'हाथ जोड़कर चारों दंपति अग्नि की परिक्रमा करते हैं और मंडप आशीर्वाद, संगीत तथा उत्सव से भर जाता है। यह गति औपचारिक परिवर्तन पूरा करती है, पर चार नई कथा-राहें खोलती है। उपयोगकर्ता यहाँ से किसी भी व्यक्ति के साथ चल सकता है—पीछे मिथिला, आगे अयोध्या या बाद में वनवास, शासन, प्रतीक्षा और पारिवारिक वियोग तक।'),
  ('scene-four-brothers-four-marriages', 'celebration-becomes-a-new-party', 'en', 'Two households become one travelling group', 'After the rites, the couples return to Dasharatha''s encampment amid public celebration. The Ayodhya party is no longer the group that arrived: four women, their attendants, relationships, memories, and responsibilities now reshape it. The next road home must carry this expanded household rather than merely escort four victorious princes.'),
  ('scene-four-brothers-four-marriages', 'celebration-becomes-a-new-party', 'hi', 'दो घराने एक यात्रा-दल में बदलते हैं', 'विधि के बाद सार्वजनिक उत्सव के बीच दंपति दशरथ के शिविर लौटते हैं। अयोध्या का दल अब वह नहीं रहा जो आया था—चार स्त्रियाँ, उनके परिचारक, संबंध, स्मृतियाँ और उत्तरदायित्व उसे नया रूप देते हैं। घर की अगली राह केवल चार विजयी राजकुमारों की वापसी नहीं, विस्तृत परिवार की यात्रा होगी।'),
  ('scene-families-begin-homeward-road', 'vishvamitra-leaves-the-story-road', 'en', 'The guide departs toward the northern mountains', 'With the marriages complete, Vishvamitra greets the kings and leaves alone for the northern mountains. His departure closes the journey that began when he asked Dasharatha for Rama. The prince who left Ayodhya under a teacher''s protection now returns married, tested, and able to meet the next threat without that guide beside him.'),
  ('scene-families-begin-homeward-road', 'vishvamitra-leaves-the-story-road', 'hi', 'मार्गदर्शक उत्तर पर्वतों की ओर चले जाते हैं', 'विवाह पूर्ण होने पर विश्वामित्र राजाओं को प्रणाम कर अकेले उत्तर पर्वतों की ओर चले जाते हैं। उनका जाना उस यात्रा को पूरा करता है जो दशरथ से राम को माँगने पर शुरू हुई थी। गुरु की रक्षा में अयोध्या छोड़ने वाला राजकुमार अब विवाहित, परीक्षित और अगले संकट से उनके बिना मिलने योग्य होकर लौट रहा है।'),
  ('scene-families-begin-homeward-road', 'janaka-sends-daughters-forward', 'en', 'Janaka''s farewell carries people, goods, and memory', 'Janaka gives cattle, cloth, vehicles, wealth, and attendants as his daughters leave. A modern journey view should neither romanticise every transfer nor reduce it to a loot counter. The visible truth is scale: moving four women into another royal household also moves support networks, labour, material security, and ties back to Mithila.'),
  ('scene-families-begin-homeward-road', 'janaka-sends-daughters-forward', 'hi', 'जनक की विदाई लोगों, वस्तुओं और स्मृतियों को साथ भेजती है', 'पुत्रियों की विदाई में जनक गायें, वस्त्र, वाहन, धन और परिचारक देते हैं। आधुनिक यात्रा-दृश्य को न हर लेन-देन का महिमामंडन करना चाहिए, न उसे खेल के लूट-अंक में बदलना। वास्तविक बात पैमाना है—चार स्त्रियों का दूसरे राजघराने में जाना सहायता-जाल, श्रम, भौतिक सुरक्षा और मिथिला से संबंध भी साथ ले जाता है।'),
  ('scene-families-begin-homeward-road', 'omens-break-the-celebration', 'en', 'Bird cries and restless animals change the road', 'As Dasharatha''s party travels, harsh bird cries, frightened animals, wind, dust, and darkness unsettle the procession. Vasishta reads the signs as danger followed by possible relief, but nobody yet knows the form it will take. Wedding music drains away while the group instinctively tightens around the new couples.'),
  ('scene-families-begin-homeward-road', 'omens-break-the-celebration', 'hi', 'पक्षियों की पुकार और बेचैन पशु राह का भाव बदल देते हैं', 'दशरथ का दल आगे बढ़ता है तो तीखी पक्षी-पुकार, घबराए पशु, हवा, धूल और अँधेरा यात्रा को अस्थिर कर देते हैं। वसिष्ठ संकेतों में संकट और उसके बाद संभावित राहत देखते हैं, पर किसी को उसका रूप ज्ञात नहीं। विवाह-संगीत धीमा पड़ता है और दल सहज ही नए दंपतियों के चारों ओर सिमटता है।'),
  ('scene-families-begin-homeward-road', 'parashurama-blocks-the-road', 'en', 'Another Rama appears with another bow', 'Parashurama emerges from the storm carrying an axe and a second great bow. His history of violent vengeance against warrior kings makes the elders fear that an old campaign has returned. The newly joined household cannot simply travel around him; he addresses Rama directly and turns the road into an arena before Ayodhya is even visible.'),
  ('scene-families-begin-homeward-road', 'parashurama-blocks-the-road', 'hi', 'एक और राम, एक और धनुष लेकर राह रोकते हैं', 'तूफ़ान से परशुराम कुल्हाड़ी और दूसरा महान धनुष लेकर प्रकट होते हैं। क्षत्रिय राजाओं के विरुद्ध उनके हिंसक प्रतिशोध का इतिहास बड़ों को डराता है कि पुराना अभियान लौट आया है। नया जुड़ा परिवार उन्हें घेरकर आगे नहीं निकल सकता; वे सीधे राम को संबोधित करते हैं और अयोध्या दिखने से पहले राह को परीक्षा-स्थल बना देते हैं।'),
  ('scene-parashurama-tests-rama', 'broken-bow-is-not-enough', 'en', 'Parashurama dismisses the first feat', 'Parashurama says he has heard of Shiva''s bow breaking but offers Vishnu''s bow as the real measure. If Rama can string it, they will fight. The challenge changes celebration into hierarchy: the older warrior refuses to let a younger man''s reputation stand until it has passed through his own standard.'),
  ('scene-parashurama-tests-rama', 'broken-bow-is-not-enough', 'hi', 'परशुराम पहली उपलब्धि को पर्याप्त नहीं मानते', 'परशुराम कहते हैं कि शिव-धनुष टूटने का समाचार सुना है, पर वास्तविक माप के लिए विष्णु का धनुष सामने रखते हैं। राम उसे चढ़ा सकें तो युद्ध होगा। चुनौती उत्सव को पदक्रम में बदल देती है—पुराना योद्धा युवा की प्रतिष्ठा को तब तक नहीं मानता जब तक वह उसके बनाए माप से न गुज़रे।'),
  ('scene-parashurama-tests-rama', 'dasharatha-pleads-for-his-sons', 'en', 'Dasharatha''s old fear returns on the wedding road', 'Dasharatha folds his hands and reminds Parashurama that he had laid down his campaign against warrior kings. He begs him not to destroy his young sons and says the whole family would die with Rama. The father who once resisted Vishvamitra''s request is again watching danger choose one child in front of him.'),
  ('scene-parashurama-tests-rama', 'dasharatha-pleads-for-his-sons', 'hi', 'विवाह की राह पर दशरथ का पुराना भय लौटता है', 'दशरथ हाथ जोड़कर याद दिलाते हैं कि परशुराम क्षत्रिय राजाओं के विरुद्ध अभियान छोड़ चुके थे। वे युवा पुत्रों को नष्ट न करने की विनती करते हैं और कहते हैं कि राम के साथ पूरा परिवार मर जाएगा। जो पिता कभी विश्वामित्र की माँग से डरे थे, वे फिर सामने संकट को एक पुत्र चुनते देख रहे हैं।'),
  ('scene-parashurama-tests-rama', 'two-bows-carry-an-old-rivalry', 'en', 'Parashurama explains the weapons behind the test', 'Parashurama tells how the two great bows were associated with Shiva and Vishnu and how rivalry once tested their strength. The bow he carries came through his own family; his identity and accumulated power are invested in it. Rama is therefore not handling neutral equipment but the challenger''s inheritance, grievance, and claim to supremacy.'),
  ('scene-parashurama-tests-rama', 'two-bows-carry-an-old-rivalry', 'hi', 'परशुराम परीक्षा के पीछे दोनों धनुषों का इतिहास बताते हैं', 'परशुराम बताते हैं कि दो महान धनुष शिव और विष्णु से कैसे जुड़े और पुरानी प्रतिद्वंद्विता ने उनकी शक्ति की परीक्षा कैसे ली। उनके हाथ का धनुष परिवार से मिला है; उनकी पहचान और संचित शक्ति उसमें लगी है। इसलिए राम कोई निष्पक्ष उपकरण नहीं, चुनौती देने वाले की विरासत, पीड़ा और श्रेष्ठता का दावा हाथ में लेते हैं।'),
  ('scene-parashurama-tests-rama', 'rama-answers-the-insult', 'en', 'Respect does not require Rama to accept humiliation', 'Rama acknowledges Parashurama''s history and standing but says the challenge treats him as weak and unworthy of his warrior duty. In deference to his father he has remained controlled; he will not remain passive. His answer draws a boundary without insulting Dasharatha, abandoning courtesy, or beginning with lethal force.'),
  ('scene-parashurama-tests-rama', 'rama-answers-the-insult', 'hi', 'सम्मान का अर्थ अपमान स्वीकार करना नहीं', 'राम परशुराम के इतिहास और स्थान को स्वीकार करते हैं, पर कहते हैं कि चुनौती उन्हें दुर्बल और क्षत्रिय-कर्तव्य के अयोग्य मानती है। पिता की उपस्थिति में वे संयमित रहे हैं; अब निष्क्रिय नहीं रहेंगे। उनका उत्तर दशरथ का अपमान, शिष्टता का त्याग या घातक आक्रमण किए बिना सीमा खींचता है।'),
  ('scene-parashurama-tests-rama', 'arrow-must-have-a-destination', 'en', 'The bow yields, and the drawn arrow cannot be wasted', 'Rama takes, strings, and draws Vishnu''s bow with the offered arrow. He refuses to kill Parashurama because of his ascetic standing and connection to Vishvamitra, but explains that the charged arrow needs a target. He offers a choice: lose the power of swift movement or the heavenly regions earned through austerity.'),
  ('scene-parashurama-tests-rama', 'arrow-must-have-a-destination', 'hi', 'धनुष झुकता है और चढ़ा बाण व्यर्थ नहीं जा सकता', 'राम विष्णु का धनुष लेकर उस पर दिया बाण चढ़ाकर खींचते हैं। परशुराम की तपस्वी स्थिति और विश्वामित्र से संबंध के कारण वे उनकी हत्या से इंकार करते हैं, पर बताते हैं कि संधान किया बाण लक्ष्य माँगता है। वे विकल्प देते हैं—तीव्र गति की शक्ति जाए या तपस्या से कमाए दिव्य लोक।'),
  ('scene-parashurama-tests-rama', 'parashurama-yields-the-road', 'en', 'Recognition ends the challenge and reopens the way home', 'Parashurama recognises Vishnu''s power in Rama, asks to keep the movement needed to return to Mahendra, and yields the spiritual regions he had earned. Rama releases the arrow accordingly. The challenger circles him in respect and departs; Dasharatha embraces his son, the darkness clears, and the expanded family finally reaches Ayodhya.'),
  ('scene-parashurama-tests-rama', 'parashurama-yields-the-road', 'hi', 'पहचान चुनौती समाप्त करती है और घर की राह खोलती है', 'परशुराम राम में विष्णु की शक्ति पहचानते हैं, महेंद्र लौटने योग्य गति बचाने को कहते हैं और तपस्या से कमाए लोक छोड़ते हैं। राम उसी अनुसार बाण छोड़ते हैं। चुनौती देने वाले सम्मान से परिक्रमा कर चले जाते हैं; दशरथ पुत्र को गले लगाते हैं, अँधेरा हटता है और विस्तृत परिवार अंततः अयोध्या पहुँचता है।'),
  ('scene-coronation-dawn', 'dasharatha-names-heir', 'en', 'Dasharatha names the future', 'Dasharatha tells the gathered rulers and elders that age weighs on him and proposes Rama as heir. The assembly answers with unmistakable approval.'),
  ('scene-coronation-dawn', 'dasharatha-names-heir', 'hi', 'दशरथ भविष्य की घोषणा करते हैं', 'दशरथ राजाओं और सभासदों से कहते हैं कि आयु का भार बढ़ रहा है और राम को युवराज बनाने का प्रस्ताव रखते हैं। सभा स्पष्ट सहमति देती है।'),
  ('scene-coronation-dawn', 'city-prepares-coronation', 'en', 'Ayodhya moves at once', 'Orders spread through streets, storehouses, kitchens, gateways, and shrines. Water, garlands, music, banners, food, and ceremonial objects gather for the morning.'),
  ('scene-coronation-dawn', 'city-prepares-coronation', 'hi', 'अयोध्या तुरंत जुट जाती है', 'आदेश गलियों, भंडारों, रसोइयों, द्वारों और पूजा-स्थलों तक फैलते हैं। जल, मालाएँ, संगीत, ध्वज, भोजन और अभिषेक-सामग्री भोर के लिए जुटती है।'),
  ('scene-coronation-dawn', 'rama-sita-keep-vigil', 'en', 'Rama and Sita keep vigil', 'Rama receives the instructions without triumph. He and Sita fast, pray, and lie on a simple bed of kusa grass while the palace stays awake around them.'),
  ('scene-coronation-dawn', 'rama-sita-keep-vigil', 'hi', 'राम और सीता रात्रि-व्रत रखते हैं', 'राम आदेश को विजय-भाव से नहीं लेते। वे और सीता उपवास, प्रार्थना और कुश की साधारण शय्या पर रात्रि बिताते हैं, जबकि महल जागता रहता है।'),
  ('scene-coronation-dawn', 'city-waits-for-dawn', 'en', 'The city waits for dawn', 'People speak of Rama''s expected rule and wait for morning. The celebration feels settled; that confidence is what the coming turn will break.'),
  ('scene-coronation-dawn', 'city-waits-for-dawn', 'hi', 'नगर भोर की प्रतीक्षा करता है', 'लोग राम के भावी शासन की चर्चा करते हुए सुबह की प्रतीक्षा करते हैं। उत्सव निश्चित लगता है—अगला मोड़ इसी विश्वास को तोड़ेगा।'),
  ('scene-manthara-sees-city', 'manthara-sees-rooftops', 'en', 'A decorated city below', 'From the palace height, Manthara sees watered streets, banners, garlands, and crowds in festive dress. She asks what has made Ayodhya radiant.'),
  ('scene-manthara-sees-city', 'manthara-sees-rooftops', 'hi', 'नीचे सजा हुआ नगर', 'महल की ऊँचाई से मंथरा धुली सड़कें, ध्वज, मालाएँ और उत्सव-वस्त्रों में भीड़ देखती है। वह पूछती है कि अयोध्या किस कारण चमक रही है।'),
  ('scene-manthara-sees-city', 'news-reaches-manthara', 'en', 'The answer changes her face', 'She learns that Rama will be installed the next morning. What others receive as good news, she immediately reads as a threat to Kaikeyi and Bharata.'),
  ('scene-manthara-sees-city', 'news-reaches-manthara', 'hi', 'उत्तर सुनते ही भाव बदलते हैं', 'उसे पता चलता है कि अगली सुबह राम का राज्याभिषेक होगा। जिसे सब शुभ समाचार मानते हैं, वह उसे कैकेयी और भरत के लिए संकट समझती है।'),
  ('scene-manthara-sees-city', 'kaikeyi-first-rejoices', 'en', 'Kaikeyi first rejoices', 'Kaikeyi does not begin in anger. She delights in the news, praises Rama, and gives Manthara an ornament—an important beginning before persuasion changes her.'),
  ('scene-manthara-sees-city', 'kaikeyi-first-rejoices', 'hi', 'कैकेयी पहले प्रसन्न होती हैं', 'कैकेयी आरंभ में क्रोधित नहीं होतीं। वे समाचार से प्रसन्न होकर राम की प्रशंसा करती हैं और मंथरा को आभूषण देती हैं—तर्क से बदलने से पहले यही उनका शुरुआती भाव है।'),
  ('scene-manthara-sees-city', 'gift-is-thrown-aside', 'en', 'The gift is thrown aside', 'Manthara rejects the gift and insists Kaikeyi is celebrating her own loss. The room changes from congratulations into an argument about power and security.'),
  ('scene-manthara-sees-city', 'gift-is-thrown-aside', 'hi', 'उपहार फेंक दिया जाता है', 'मंथरा उपहार अस्वीकार कर कहती है कि कैकेयी अपनी ही हानि का उत्सव मना रही हैं। कक्ष में बधाई की जगह सत्ता और सुरक्षा की बहस शुरू होती है।'),
  ('scene-fear-becomes-demands', 'manthara-reframes-future', 'en', 'The future is reframed as danger', 'Manthara argues that Rama''s rise will diminish Bharata and Kaikeyi. She turns affection, succession, and household rank into a chain of imagined danger.'),
  ('scene-fear-becomes-demands', 'manthara-reframes-future', 'hi', 'भविष्य को संकट की तरह दिखाया जाता है', 'मंथरा तर्क देती है कि राम का उदय भरत और कैकेयी को पीछे कर देगा। वह स्नेह, उत्तराधिकार और परिवार की स्थिति को आशंकाओं की शृंखला बना देती है।'),
  ('scene-fear-becomes-demands', 'kaikeyi-enters-anger-room', 'en', 'Kaikeyi enters the chamber of anger', 'Persuaded, Kaikeyi removes her ornaments, puts on soiled clothing, and lies on the floor so Dasharatha will find a visible crisis.'),
  ('scene-fear-becomes-demands', 'kaikeyi-enters-anger-room', 'hi', 'कैकेयी कोपभवन में जाती हैं', 'प्रभावित होकर कैकेयी आभूषण उतारती हैं, मलिन वस्त्र पहनती हैं और भूमि पर लेट जाती हैं ताकि दशरथ के सामने संकट स्पष्ट दिखाई दे।'),
  ('scene-fear-becomes-demands', 'dasharatha-renews-promise', 'en', 'Dasharatha promises before hearing', 'Alarmed by her condition, Dasharatha asks what she wants and repeatedly promises to fulfil it. Kaikeyi makes the promise public in the presence of invoked witnesses.'),
  ('scene-fear-becomes-demands', 'dasharatha-renews-promise', 'hi', 'दशरथ सुनने से पहले वचन देते हैं', 'कैकेयी की दशा देखकर दशरथ पूछते हैं कि वे क्या चाहती हैं और बार-बार उसे पूरा करने का वचन देते हैं। कैकेयी साक्षियों का आह्वान करके उस वचन को सार्वजनिक बनाती हैं।'),
  ('scene-fear-becomes-demands', 'first-demand-bharata', 'en', 'The first demand: Bharata', 'Kaikeyi calls in the boons Dasharatha once granted and demands that the prepared coronation install Bharata instead of Rama.'),
  ('scene-fear-becomes-demands', 'first-demand-bharata', 'hi', 'पहली माँग: भरत', 'कैकेयी दशरथ द्वारा दिए पुराने वरदान माँगती हैं और तैयार राज्याभिषेक में राम के स्थान पर भरत को स्थापित करने की माँग रखती हैं।'),
  ('scene-fear-becomes-demands', 'second-demand-fourteen-years', 'en', 'The second demand: fourteen years', 'The second demand removes Rama from the kingdom for fourteen years in forest dress. It is not merely a changed ceremony; it is the beginning of the epic road.'),
  ('scene-fear-becomes-demands', 'second-demand-fourteen-years', 'hi', 'दूसरी माँग: चौदह वर्ष', 'दूसरी माँग राम को वन-वस्त्र में चौदह वर्ष के लिए राज्य से दूर भेजती है। यह केवल बदला हुआ समारोह नहीं, महाकाव्य की यात्रा का आरंभ है।'),
  ('scene-king-trapped-by-word', 'dasharatha-collapses', 'en', 'The demand lands', 'Dasharatha falls senseless, recovers, and hopes he has heard a nightmare. Kaikeyi repeats the demands without softening them.'),
  ('scene-king-trapped-by-word', 'dasharatha-collapses', 'hi', 'माँग का आघात', 'दशरथ मूर्छित होकर गिरते हैं, संभलते हैं और आशा करते हैं कि यह दुःस्वप्न हो। कैकेयी बिना नरमी के माँगें दोहराती हैं।'),
  ('scene-king-trapped-by-word', 'king-pleads-through-night', 'en', 'A king pleads through the night', 'He appeals to love, reputation, family, and mercy. He offers wealth and power, but cannot make Kaikeyi release the promise.'),
  ('scene-king-trapped-by-word', 'king-pleads-through-night', 'hi', 'राजा पूरी रात विनती करते हैं', 'वे प्रेम, प्रतिष्ठा, परिवार और दया की दुहाई देते हैं। धन और सत्ता देने को तैयार होते हैं, पर कैकेयी वचन छोड़ने को नहीं मानतीं।'),
  ('scene-king-trapped-by-word', 'kaikeyi-invokes-truth', 'en', 'Kaikeyi invokes the king''s truth', 'Kaikeyi says a king celebrated for truth cannot withdraw when the cost becomes painful. The language of honour becomes the lock on the chamber.'),
  ('scene-king-trapped-by-word', 'kaikeyi-invokes-truth', 'hi', 'कैकेयी राजा के सत्य का आह्वान करती हैं', 'कैकेयी कहती हैं कि सत्य के लिए प्रसिद्ध राजा कठिन मूल्य देखकर पीछे नहीं हट सकता। सम्मान की भाषा ही कक्ष का ताला बन जाती है।'),
  ('scene-king-trapped-by-word', 'morning-waits-outside', 'en', 'Morning waits outside', 'Priests, citizens, music, and the objects of installation gather outside. Inside, Dasharatha can no longer speak the future everyone has come to celebrate.'),
  ('scene-king-trapped-by-word', 'morning-waits-outside', 'hi', 'सुबह बाहर प्रतीक्षा करती है', 'पुरोहित, नागरिक, संगीत और अभिषेक-सामग्री बाहर जुटते हैं। भीतर दशरथ उस भविष्य का नाम भी नहीं ले पाते जिसके उत्सव में सब आए हैं।'),
  ('scene-rama-crosses-celebration', 'vasishta-finds-delay', 'en', 'The ceremony is ready; the king is absent', 'Vasishta sends Sumantra to bring the king. The messenger finds Dasharatha broken and Kaikeyi directing what happens next.'),
  ('scene-rama-crosses-celebration', 'vasishta-finds-delay', 'hi', 'समारोह तैयार है, राजा नहीं', 'वसिष्ठ सुमंत्र को राजा बुलाने भेजते हैं। वे दशरथ को टूटा हुआ और आगे की दिशा तय करती कैकेयी को पाते हैं।'),
  ('scene-rama-crosses-celebration', 'sumantra-summons-rama', 'en', 'Rama is summoned', 'Kaikeyi tells Sumantra to bring Rama. Nothing in the public streets reveals that the summons is no longer for installation.'),
  ('scene-rama-crosses-celebration', 'sumantra-summons-rama', 'hi', 'राम को बुलाया जाता है', 'कैकेयी सुमंत्र से राम को बुलाने कहती हैं। सार्वजनिक गलियों में कुछ भी नहीं बताता कि बुलावा अब राज्याभिषेक के लिए नहीं है।'),
  ('scene-rama-crosses-celebration', 'rama-crosses-festival-city', 'en', 'Through a city saying his name', 'Rama crosses watered roads, raised standards, musicians, and citizens expecting to see him crowned. He answers their affection without knowing how soon he will leave them.'),
  ('scene-rama-crosses-celebration', 'rama-crosses-festival-city', 'hi', 'नाम पुकारते नगर के बीच', 'राम धुली सड़कों, ध्वजों, संगीत और राज्याभिषेक की प्रतीक्षा करती जनता के बीच से गुजरते हैं। वे स्नेह का उत्तर देते हैं, बिना जाने कि शीघ्र ही विदा होंगे।'),
  ('scene-rama-crosses-celebration', 'kaikeyi-speaks-demand', 'en', 'The silent father; the spoken demand', 'Rama finds Dasharatha unable to answer him. Kaikeyi says the king is bound by shame and then tells Rama the two demands directly.'),
  ('scene-rama-crosses-celebration', 'kaikeyi-speaks-demand', 'hi', 'मौन पिता, बोली गई माँग', 'राम दशरथ को उत्तर देने में असमर्थ पाते हैं। कैकेयी कहती हैं कि राजा संकोच से बँधे हैं और फिर दोनों माँगें सीधे राम को बताती हैं।'),
  ('scene-rama-accepts-exile', 'rama-says-he-will-go', 'en', 'Rama answers without bargaining', 'Rama says Bharata may receive the kingdom and that he will enter the forest that very day. He asks only why his father could not tell him himself.'),
  ('scene-rama-accepts-exile', 'rama-says-he-will-go', 'hi', 'राम बिना सौदे के उत्तर देते हैं', 'राम कहते हैं कि भरत राज्य लें और वे उसी दिन वन चले जाएँगे। वे केवल पूछते हैं कि पिता स्वयं यह बात क्यों नहीं कह सके।'),
  ('scene-rama-accepts-exile', 'rama-goes-to-kausalya', 'en', 'Celebration still surrounds Kausalya', 'Rama reaches Kausalya while attendants and ritual preparations still anticipate his installation. He tells her that the seat prepared for him must be exchanged for forest ground.'),
  ('scene-rama-accepts-exile', 'rama-goes-to-kausalya', 'hi', 'कौसल्या के चारों ओर अभी भी उत्सव है', 'राम कौसल्या के पास पहुँचते हैं, जहाँ सेवक और अनुष्ठान अभी भी राज्याभिषेक की प्रतीक्षा में हैं। वे बताते हैं कि उनके लिए तैयार आसन अब वन-भूमि से बदल जाएगा।'),
  ('scene-rama-accepts-exile', 'kausalya-grief-and-choice', 'en', 'Kausalya''s grief is not hurried past', 'Kausalya collapses, mourns the years of waiting, and says she would follow him. The story stays with the human cost before it turns to argument about duty.'),
  ('scene-rama-accepts-exile', 'kausalya-grief-and-choice', 'hi', 'कौसल्या के शोक को जल्दी नहीं टाला जाता', 'कौसल्या गिर पड़ती हैं, वर्षों की प्रतीक्षा का शोक करती हैं और साथ चलने की बात कहती हैं। कथा कर्तव्य की बहस से पहले मानवीय पीड़ा पर ठहरती है।'),
  ('scene-rama-accepts-exile', 'lakshmana-urges-resistance', 'en', 'Lakshmana urges resistance', 'Lakshmana calls the command unjust and offers force, defence, and the support of those loyal to Rama. His anger gives voice to the refusal others cannot articulate.'),
  ('scene-rama-accepts-exile', 'lakshmana-urges-resistance', 'hi', 'लक्ष्मण प्रतिरोध की बात करते हैं', 'लक्ष्मण आदेश को अन्यायपूर्ण कहते हैं और बल, रक्षा तथा राम-समर्थकों का सहारा देने की बात करते हैं। उनका क्रोध उस अस्वीकार को स्वर देता है जिसे दूसरे कह नहीं पाते।'),
  ('scene-rama-accepts-exile', 'rama-turns-anger-to-preparation', 'en', 'Rama turns anger toward preparation', 'Rama refuses to seize the kingdom or make his father''s word the cause of civil conflict. He asks Lakshmana to help dismantle the ceremony and prepare for departure.'),
  ('scene-rama-accepts-exile', 'rama-turns-anger-to-preparation', 'hi', 'राम क्रोध को तैयारी में बदलते हैं', 'राम राज्य छीनने या पिता के वचन को गृह-संघर्ष का कारण बनाने से इंकार करते हैं। वे लक्ष्मण से समारोह समेटकर प्रस्थान की तैयारी में सहायता माँगते हैं।'),
  ('scene-sita-chooses-road', 'sita-sees-changed-face', 'en', 'Sita sees what the city cannot', 'Sita has prepared for coronation and asks why Rama returns without royal signs, music, or attendants. His face tells her the public celebration is already false.'),
  ('scene-sita-chooses-road', 'sita-sees-changed-face', 'hi', 'सीता वह देखती हैं जो नगर नहीं देखता', 'सीता राज्याभिषेक की तैयारी में हैं और पूछती हैं कि राम राजचिह्न, संगीत और सेवकों के बिना क्यों लौटे। उनका चेहरा बता देता है कि बाहर का उत्सव अब सच नहीं रहा।'),
  ('scene-sita-chooses-road', 'rama-asks-sita-stay', 'en', 'Rama asks her to remain', 'Rama explains the command and initially asks Sita to stay in Ayodhya, honour the elders, and live carefully while he is away.'),
  ('scene-sita-chooses-road', 'rama-asks-sita-stay', 'hi', 'राम उन्हें रुकने को कहते हैं', 'राम आदेश बताते हैं और पहले सीता से अयोध्या में रहकर बड़ों का सम्मान करने तथा उनके लौटने तक सावधानी से जीवन बिताने को कहते हैं।'),
  ('scene-sita-chooses-road', 'sita-claims-shared-fortune', 'en', 'Sita claims a shared fortune', 'Sita answers that marriage does not divide hardship into his and hers. She rejects the idea that the palace can be her proper world while his road lies elsewhere.'),
  ('scene-sita-chooses-road', 'sita-claims-shared-fortune', 'hi', 'सीता साझा भाग्य का दावा करती हैं', 'सीता कहती हैं कि विवाह कठिनाई को तुम्हारी और मेरी हिस्सेदारी में नहीं बाँटता। वे इस विचार को अस्वीकार करती हैं कि उनका संसार महल हो और राम की राह कहीं और।'),
  ('scene-sita-chooses-road', 'forest-fears-are-named', 'en', 'The forest fears are named', 'Rama names rough ground, hunger, animals, weather, and hardship. Sita answers each warning not with ignorance, but with a repeated, deliberate choice to accompany him.'),
  ('scene-sita-chooses-road', 'forest-fears-are-named', 'hi', 'वन के भय स्पष्ट किए जाते हैं', 'राम कठिन भूमि, भूख, वन्य जीव, मौसम और कष्ट गिनाते हैं। सीता अज्ञान से नहीं, हर चेतावनी के बाद सोच-समझकर साथ चलने का निर्णय दोहराती हैं।'),
  ('scene-sita-chooses-road', 'rama-accepts-sita-choice', 'en', 'Rama accepts her choice', 'After the long exchange, Rama stops trying to leave her behind. They begin giving possessions away and preparing to enter the forest together.'),
  ('scene-sita-chooses-road', 'rama-accepts-sita-choice', 'hi', 'राम सीता का निर्णय स्वीकार करते हैं', 'लंबे संवाद के बाद राम उन्हें पीछे छोड़ने का प्रयास रोकते हैं। दोनों वस्तुएँ दान देकर साथ वन जाने की तैयारी करते हैं।'),
  ('scene-lakshmana-joins', 'lakshmana-asks-to-come', 'en', 'Lakshmana asks for the road', 'Lakshmana says he will walk before Rama and Sita, gather food, guard the path, and make the forest journey his own duty.'),
  ('scene-lakshmana-joins', 'lakshmana-asks-to-come', 'hi', 'लक्ष्मण साथ चलने की अनुमति माँगते हैं', 'लक्ष्मण कहते हैं कि वे राम और सीता के आगे चलेंगे, भोजन जुटाएँगे, मार्ग की रक्षा करेंगे और वन-यात्रा को अपना दायित्व बनाएँगे।'),
  ('scene-lakshmana-joins', 'weapons-and-gifts-prepared', 'en', 'Preparation replaces ceremony', 'Rama sends Lakshmana for the bows and protective equipment entrusted to the household. At the same time, wealth and belongings are distributed rather than carried into exile.'),
  ('scene-lakshmana-joins', 'weapons-and-gifts-prepared', 'hi', 'समारोह की जगह यात्रा-तैयारी', 'राम लक्ष्मण को परिवार के पास सुरक्षित धनुष और रक्षा-सामग्री लाने भेजते हैं। साथ ही धन और वस्तुएँ वन ले जाने के बजाय बाँटी जाती हैं।'),
  ('scene-lakshmana-joins', 'bark-garments-arrive', 'en', 'Bark garments replace royal dress', 'Kaikeyi brings forest garments. Rama and Lakshmana change; Sita''s discomfort and the elders'' protest are not treated as a ritual instruction or a triumphant spectacle.'),
  ('scene-lakshmana-joins', 'bark-garments-arrive', 'hi', 'राजवस्त्रों की जगह वल्कल आते हैं', 'कैकेयी वन-वस्त्र लाती हैं। राम और लक्ष्मण बदलते हैं; सीता की असुविधा और बड़ों के विरोध को न अनुष्ठान-निर्देश बनाया जाता है, न विजय-दृश्य।'),
  ('scene-lakshmana-joins', 'farewell-to-mothers', 'en', 'Farewell moves through the family', 'The three seek blessings from parents and mothers amid grief, counsel, argument, and embraces. Departure is a household rupture before it becomes adventure.'),
  ('scene-lakshmana-joins', 'farewell-to-mothers', 'hi', 'विदाई पूरे परिवार से गुजरती है', 'तीनों शोक, सलाह, तर्क और आलिंगन के बीच माता-पिता और माताओं से आशीर्वाद लेते हैं। प्रस्थान रोमांच बनने से पहले परिवार का टूटना है।'),
  ('scene-lakshmana-joins', 'three-turn-toward-gate', 'en', 'Three turn toward the gate', 'Rama, Sita, and Lakshmana stand ready together. The city is still dressed for coronation, but the next movement is toward the gate and the forest beyond.'),
  ('scene-lakshmana-joins', 'three-turn-toward-gate', 'hi', 'तीनों द्वार की ओर मुड़ते हैं', 'राम, सीता और लक्ष्मण साथ खड़े हैं। नगर अभी भी राज्याभिषेक के लिए सजा है, पर अगला कदम द्वार और उसके पार वन की ओर है।'),
  ('scene-city-follows-car', 'inner-rooms-erupt', 'en', 'The inner rooms erupt', 'As the car leaves, voices rise through the royal apartments. The people who depended on Rama ask where their refuge is going; private loss spills into the city.'),
  ('scene-city-follows-car', 'inner-rooms-erupt', 'hi', 'अंतःपुर में विलाप उठता है', 'रथ निकलते ही राजमहल के अंतःपुर में स्वर उठते हैं। राम पर निर्भर लोग पूछते हैं कि उनका सहारा कहाँ जा रहा है; निजी हानि पूरे नगर में फैल जाती है।'),
  ('scene-city-follows-car', 'dasharatha-watches-dust', 'en', 'Dasharatha watches the dust', 'Dasharatha keeps his eyes on the departing car until even its dust disappears. Only then does his body give way and Kausalya helps raise him from the road.'),
  ('scene-city-follows-car', 'dasharatha-watches-dust', 'hi', 'दशरथ धूल को देखते रहते हैं', 'दशरथ जाते रथ को तब तक देखते हैं जब तक उसकी धूल भी ओझल नहीं हो जाती। तभी उनका शरीर जवाब देता है और कौसल्या उन्हें मार्ग से उठाती हैं।'),
  ('scene-city-follows-car', 'kausalya-imagines-road', 'en', 'Kausalya imagines the road', 'Inside the darkened palace, Kausalya imagines the three without familiar beds, food, or shelter. Her grief stretches ahead to the day Ayodhya might see them return.'),
  ('scene-city-follows-car', 'kausalya-imagines-road', 'hi', 'कौसल्या आगे की राह कल्पना करती हैं', 'अँधेरे महल में कौसल्या तीनों को परिचित शय्या, भोजन और आश्रय के बिना सोचती हैं। उनका शोक उस दिन तक फैलता है जब अयोध्या उन्हें लौटते देख सकेगी।'),
  ('scene-city-follows-car', 'sumitra-holds-return', 'en', 'Sumitra keeps return imaginable', 'Sumitra does not erase the pain. She reminds Kausalya that Lakshmana and Sita chose to accompany Rama and insists that the road can still end in return.'),
  ('scene-city-follows-car', 'sumitra-holds-return', 'hi', 'सुमित्रा वापसी की आशा थामती हैं', 'सुमित्रा पीड़ा को नकारती नहीं हैं। वे कौसल्या को याद दिलाती हैं कि लक्ष्मण और सीता ने राम का साथ चुना है और यह राह वापसी पर भी समाप्त हो सकती है।'),
  ('scene-city-follows-car', 'citizens-take-road', 'en', 'The citizens take the road', 'Citizens follow on foot and ask the horses to stop. Rama leaves the car to walk beside elders who cannot keep pace, and darkness finds the crowd still following.'),
  ('scene-city-follows-car', 'citizens-take-road', 'hi', 'नगरवासी भी राह पकड़ते हैं', 'नगरवासी पैदल पीछे चलते हैं और घोड़ों से रुकने की विनती करते हैं। राम धीमे चल रहे बुज़ुर्गों के साथ पैदल हो जाते हैं, और अँधेरा भीड़ को अब भी मार्ग पर पाता है।'),
  ('scene-tamasa-night', 'first-night-named', 'en', 'Rama names the first night', 'At the Tamasa, Rama calls this the first night of exile. He speaks of the parents and city behind them while the forest answers with birds and animals settling into darkness.'),
  ('scene-tamasa-night', 'first-night-named', 'hi', 'राम पहली रात को पहचानते हैं', 'तमसा के तट पर राम इसे वनवास की पहली रात कहते हैं। वे पीछे छूटे माता-पिता और नगर की बात करते हैं, जबकि वन पक्षियों और पशुओं के रात्रि-स्वरों से उत्तर देता है।'),
  ('scene-tamasa-night', 'city-sleeps-under-trees', 'en', 'Ayodhya sleeps beneath trees', 'The citizens who followed lie exhausted nearby. Their determination has carried a piece of Ayodhya into the open country, but fatigue finally closes their eyes.'),
  ('scene-tamasa-night', 'city-sleeps-under-trees', 'hi', 'अयोध्या वृक्षों के नीचे सोती है', 'पीछे आए नगरवासी पास ही थककर लेट जाते हैं। उनका संकल्प अयोध्या का एक अंश खुले प्रदेश तक ले आया है, पर थकान अंततः उनकी आँखें बंद कर देती है।'),
  ('scene-tamasa-night', 'leave-before-dawn', 'en', 'Compassion requires leaving', 'Rama says a ruler should not let citizens destroy themselves for his hardship. He chooses to leave while they sleep rather than keep rewarding their refusal to turn home.'),
  ('scene-tamasa-night', 'leave-before-dawn', 'hi', 'करुणा अब चले जाने को कहती है', 'राम कहते हैं कि शासक को अपनी कठिनाई के कारण प्रजा को स्वयं कष्ट में नहीं डालना चाहिए। वे उनके जागने से पहले निकलना चुनते हैं, ताकि उनका लौटने से इंकार बढ़े नहीं।'),
  ('scene-tamasa-night', 'tracks-turn-north', 'en', 'The tracks tell the wrong story', 'Sumantra first drives north, then turns and takes the forest road so the trail cannot be followed. The chariot crosses the Tamasa before dawn fully arrives.'),
  ('scene-tamasa-night', 'tracks-turn-north', 'hi', 'रथचिह्न दूसरी कहानी कहते हैं', 'सुमंत्र पहले रथ उत्तर की ओर ले जाते हैं, फिर मोड़कर वनमार्ग पकड़ते हैं ताकि चिह्नों का पीछा न हो सके। पूर्ण भोर से पहले रथ तमसा पार कर जाता है।'),
  ('scene-tamasa-night', 'citizens-wake-to-absence', 'en', 'The citizens wake to absence', 'At sunrise the followers find no car and lose its track. Their return to Ayodhya is not defeat in one line: homes, markets, kitchens, music, and ordinary recognition all fall silent.'),
  ('scene-tamasa-night', 'citizens-wake-to-absence', 'hi', 'नगरवासी रिक्तता में जागते हैं', 'सूर्योदय पर अनुयायियों को रथ नहीं मिलता और उसके चिह्न खो जाते हैं। उनकी अयोध्या-वापसी एक पंक्ति की हार नहीं—घर, बाज़ार, रसोई, संगीत और रोज़मर्रा की पहचान सब मौन हो जाते हैं।'),
  ('scene-roads-beyond-kosala', 'villages-speak-aloud', 'en', 'The villages speak aloud', 'Passing ploughed fields and flowering woods, the travellers hear villagers condemn the decision that sent them away. The political rupture travels faster than the car.'),
  ('scene-roads-beyond-kosala', 'villages-speak-aloud', 'hi', 'गाँव खुलकर बोलते हैं', 'जुते खेतों और फूलते वनों से गुजरते हुए यात्री गाँववालों को उस निर्णय की निंदा करते सुनते हैं जिसने उन्हें भेजा। राजनीतिक टूटन रथ से भी तेज़ फैलती है।'),
  ('scene-roads-beyond-kosala', 'rivers-mark-distance', 'en', 'Rivers measure the distance', 'The Vedashruti, Gomati, and Sandika are crossed amid cultivated land, birds, and cattle. Each waterline makes the palace world less immediate.'),
  ('scene-roads-beyond-kosala', 'rivers-mark-distance', 'hi', 'नदियाँ दूरी मापती हैं', 'वेदश्रुति, गोमती और स्यंदिका को खेतों, पक्षियों और पशुओं के बीच पार किया जाता है। हर जलरेखा महल के संसार को थोड़ा और दूर कर देती है।'),
  ('scene-roads-beyond-kosala', 'rama-faces-ayodhya', 'en', 'Rama faces Ayodhya once more', 'At the edge of Kosala, Rama turns back, salutes the city and its guardians, and says he will return after completing what he owes his father.'),
  ('scene-roads-beyond-kosala', 'rama-faces-ayodhya', 'hi', 'राम एक बार फिर अयोध्या की ओर देखते हैं', 'कोसल की सीमा पर राम पीछे मुड़कर नगर और उसके रक्षकों को प्रणाम करते हैं और कहते हैं कि पिता का दायित्व पूरा कर वे लौटेंगे।'),
  ('scene-roads-beyond-kosala', 'ganga-fills-horizon', 'en', 'The Ganga fills the horizon', 'The journey reaches a river too vast to be another passing stream. Water, sandbanks, birds, trees, and hermitages expand into a new world beside Shringaverapura.'),
  ('scene-roads-beyond-kosala', 'ganga-fills-horizon', 'hi', 'गंगा क्षितिज भर देती है', 'यात्रा ऐसी नदी तक पहुँचती है जो केवल एक और धारा नहीं। जल, रेतीले तट, पक्षी, वृक्ष और आश्रम शृंगवेरपुर के पास एक नया संसार खोलते हैं।'),
  ('scene-roads-beyond-kosala', 'guha-arrives-as-friend', 'en', 'Guha arrives as a friend', 'Guha comes with kin and offerings, embraces Rama, and asks after the journey. The first welcome beyond Kosala is offered as friendship, not as a faceless service stop.'),
  ('scene-roads-beyond-kosala', 'guha-arrives-as-friend', 'hi', 'गुह मित्र बनकर आते हैं', 'गुह अपने लोगों और भेंटों के साथ आते हैं, राम को आलिंगन देते हैं और यात्रा का हाल पूछते हैं। कोसल के बाहर पहला स्वागत मित्रता है, कोई अनाम पड़ाव नहीं।'),
  ('scene-guha-night-watch', 'guha-offers-a-kingdom', 'en', 'Guha offers everything at hand', 'Food, beds, supplies, protection, and even the settlement are placed before Rama. Guha''s welcome has political weight as well as personal affection.'),
  ('scene-guha-night-watch', 'guha-offers-a-kingdom', 'hi', 'गुह अपने पास का सब कुछ प्रस्तुत करते हैं', 'भोजन, शय्या, सामग्री, सुरक्षा और यहाँ तक कि अपना क्षेत्र भी गुह राम के सामने रखते हैं। उनका स्वागत निजी स्नेह के साथ राजनीतिक भार भी रखता है।'),
  ('scene-guha-night-watch', 'vow-shapes-acceptance', 'en', 'The vow shapes what can be accepted', 'Rama accepts the affection but declines comforts incompatible with the life he has undertaken. He asks only that Dasharatha''s horses be fed and tended well.'),
  ('scene-guha-night-watch', 'vow-shapes-acceptance', 'hi', 'व्रत तय करता है कि क्या स्वीकार होगा', 'राम स्नेह स्वीकार करते हैं, पर अपने चुने वनजीवन से असंगत सुख-सामग्री नहीं। वे केवल दशरथ के घोड़ों के भोजन और देखभाल का आग्रह करते हैं।'),
  ('scene-guha-night-watch', 'ground-bed-by-ganga', 'en', 'Rama and Sita sleep on the ground', 'After water and evening observance, Rama and Sita lie beneath the tree. The image is not serene decoration: everyone watching knows what comforts and people lie behind them.'),
  ('scene-guha-night-watch', 'ground-bed-by-ganga', 'hi', 'राम और सीता धरती पर सोते हैं', 'जल और संध्या-क्रम के बाद राम और सीता वृक्ष के नीचे लेटते हैं। यह केवल शांत सजावट नहीं—देखने वाले जानते हैं कि उनके पीछे कौन-से सुख और लोग छूटे हैं।'),
  ('scene-guha-night-watch', 'lakshmana-refuses-bed', 'en', 'Lakshmana refuses the bed', 'Guha offers Lakshmana rest and takes responsibility for protection. Lakshmana answers that he cannot sleep while Rama and Sita lie on grass before him.'),
  ('scene-guha-night-watch', 'lakshmana-refuses-bed', 'hi', 'लक्ष्मण शय्या अस्वीकार करते हैं', 'गुह लक्ष्मण को विश्राम देते और सुरक्षा की जिम्मेदारी लेते हैं। लक्ष्मण कहते हैं कि राम और सीता को घास पर सोते देखकर वे कैसे सो सकते हैं।'),
  ('scene-guha-night-watch', 'two-friends-keep-watch', 'en', 'Two friends keep watch', 'Lakshmana speaks his fear that Dasharatha and the mothers may not survive the night. Guha listens, weeps, and keeps watch with him until daybreak.'),
  ('scene-guha-night-watch', 'two-friends-keep-watch', 'hi', 'दो मित्र रात भर पहरा देते हैं', 'लक्ष्मण अपना भय कहते हैं कि दशरथ और माताएँ शायद यह रात न सह सकें। गुह सुनते हैं, आँसू बहाते हैं और भोर तक उनके साथ पहरा देते हैं।'),
  ('scene-ganga-crossing', 'boat-waits-at-dawn', 'en', 'A boat waits at dawn', 'Bird calls announce morning and Guha has a strong boat brought to the bank. Bows, quivers, travel bundles, and Sita must all cross together.'),
  ('scene-ganga-crossing', 'boat-waits-at-dawn', 'hi', 'भोर में नाव तैयार है', 'पक्षियों के स्वर भोर बताते हैं और गुह मजबूत नाव तट पर मँगवाते हैं। धनुष, तरकश, यात्रा-सामान और सीता—सबको साथ पार होना है।'),
  ('scene-ganga-crossing', 'sumantra-asks-to-stay', 'en', 'Sumantra asks not to return alone', 'Sumantra pleads to remain for all fourteen years. He imagines Ayodhya seeing the empty car and asks how a truth so painful can be carried back.'),
  ('scene-ganga-crossing', 'sumantra-asks-to-stay', 'hi', 'सुमंत्र अकेले लौटने से मना करते हैं', 'सुमंत्र चौदहों वर्ष साथ रहने की विनती करते हैं। वे खाली रथ को देखती अयोध्या की कल्पना करते हैं और पूछते हैं कि इतना पीड़ादायक सत्य कैसे लौटाया जाए।'),
  ('scene-ganga-crossing', 'messages-return-to-ayodhya', 'en', 'Messages return in their place', 'Rama asks Sumantra to steady Dasharatha, greet the mothers, summon Bharata, and report that the three do not regret keeping the command. The empty car will carry words.'),
  ('scene-ganga-crossing', 'messages-return-to-ayodhya', 'hi', 'उनकी जगह संदेश लौटते हैं', 'राम सुमंत्र से दशरथ को संभालने, माताओं को प्रणाम कहने, भरत को बुलाने और यह बताने को कहते हैं कि तीनों आदेश निभाने पर पछता नहीं रहे। खाली रथ अब शब्द ले जाएगा।'),
  ('scene-ganga-crossing', 'forest-vow-takes-form', 'en', 'The forest vow becomes visible', 'With Guha''s help, Rama and Lakshmana bind their hair into matted locks. The change is treated as their source-story decision, not a costume reward or instruction for the user.'),
  ('scene-ganga-crossing', 'forest-vow-takes-form', 'hi', 'वन-व्रत दिखाई देने लगता है', 'गुह की सहायता से राम और लक्ष्मण जटा बाँधते हैं। यह परिवर्तन स्रोत-कथा का उनका निर्णय है, कोई पोशाक-इनाम या उपयोगकर्ता के लिए निर्देश नहीं।'),
  ('scene-ganga-crossing', 'sita-prays-midstream', 'en', 'Sita speaks hope in midstream', 'In the middle of the Ganga, Sita prays that the vow be completed and that all three return. The prayer belongs to this character and moment; it is not presented as universal modern vidhi.'),
  ('scene-ganga-crossing', 'sita-prays-midstream', 'hi', 'मध्यधारा में सीता आशा बोलती हैं', 'गंगा की मध्यधारा में सीता प्रार्थना करती हैं कि व्रत पूरा हो और तीनों लौटें। यह इस पात्र और क्षण की प्रार्थना है, सार्वभौमिक आधुनिक विधि नहीं।'),
  ('scene-first-forest-night', 'first-night-without-sumantra', 'en', 'The chariot is gone', 'Under a great tree, Rama names this the first night beyond inhabited country without Sumantra. Leaves must become the bed and the three must provide for one another.'),
  ('scene-first-forest-night', 'first-night-without-sumantra', 'hi', 'रथ अब जा चुका है', 'एक विशाल वृक्ष के नीचे राम इसे सुमंत्र और बस्ती से बाहर पहली रात कहते हैं। पत्ते शय्या बनेंगे और तीनों को एक-दूसरे की देखभाल करनी होगी।'),
  ('scene-first-forest-night', 'rama-fears-for-home', 'en', 'Rama fears for those at home', 'Rama imagines Dasharatha weakened, Kausalya exposed, and Kaikeyi pressing her advantage. Exile does not switch off anxiety about the household left behind.'),
  ('scene-first-forest-night', 'rama-fears-for-home', 'hi', 'राम घरवालों के लिए डरते हैं', 'राम दशरथ को निर्बल, कौसल्या को असुरक्षित और कैकेयी को अपना लाभ बढ़ाते सोचते हैं। वनवास पीछे छूटे परिवार की चिंता बंद नहीं करता।'),
  ('scene-first-forest-night', 'anger-is-spoken-not-acted', 'en', 'Anger is spoken, not acted', 'He admits that force could seize Ayodhya, then rejects the act as wrong. The scene preserves the anger and the refusal instead of flattening him into effortless calm.'),
  ('scene-first-forest-night', 'anger-is-spoken-not-acted', 'hi', 'क्रोध कहा जाता है, किया नहीं जाता', 'वे स्वीकारते हैं कि बल से अयोध्या ली जा सकती है, फिर उस कर्म को अनुचित कहकर छोड़ते हैं। दृश्य उन्हें सहज शांत बनाने के बजाय क्रोध और उसके त्याग दोनों को रखता है।'),
  ('scene-first-forest-night', 'lakshmana-answers-belonging', 'en', 'Lakshmana answers with belonging', 'Lakshmana tells Rama that neither he nor Sita can live apart from him. His answer does not solve Ayodhya; it makes companionship present in this forest.'),
  ('scene-first-forest-night', 'lakshmana-answers-belonging', 'hi', 'लक्ष्मण साथ होने का उत्तर देते हैं', 'लक्ष्मण कहते हैं कि न वे, न सीता राम से अलग रह सकते हैं। उनका उत्तर अयोध्या की समस्या नहीं सुलझाता; वह इस वन में साथ को उपस्थित करता है।'),
  ('scene-first-forest-night', 'leaves-become-a-bed', 'en', 'Leaves become the first bed', 'The conversation ends in practical care. A bed of leaves is spread, the night is endured, and the three remain together in a place no palace plan prepared them to inhabit.'),
  ('scene-first-forest-night', 'leaves-become-a-bed', 'hi', 'पत्ते पहली शय्या बनते हैं', 'संवाद व्यावहारिक देखभाल में समाप्त होता है। पत्तों की शय्या बिछती है, रात काटी जाती है और तीनों ऐसे स्थान में साथ रहते हैं जिसके लिए किसी महल-योजना ने उन्हें तैयार नहीं किया था।'),
  ('scene-prayaga-to-yamuna', 'smoke-above-confluence', 'en', 'Smoke rises above two rivers', 'Near evening, Rama sees smoke and hears the meeting waters of Ganga and Yamuna. Signs of human practice reveal Bharadvaja''s hermitage before the travellers reach it.'),
  ('scene-prayaga-to-yamuna', 'smoke-above-confluence', 'hi', 'दो नदियों के ऊपर धुआँ उठता है', 'साँझ के पास राम धुआँ देखते और गंगा-यमुना के मिलते जल की ध्वनि सुनते हैं। मानवीय साधना के संकेत यात्रियों के पहुँचने से पहले भरद्वाज के आश्रम का पता देते हैं।'),
  ('scene-prayaga-to-yamuna', 'bharadvaja-receives-travellers', 'en', 'Bharadvaja receives the travellers', 'The three introduce themselves and explain the exile. Bharadvaja offers water, food from the forest, a place to rest, and the possibility of staying at the confluence.'),
  ('scene-prayaga-to-yamuna', 'bharadvaja-receives-travellers', 'hi', 'भरद्वाज यात्रियों का स्वागत करते हैं', 'तीनों अपना परिचय और वनवास बताते हैं। भरद्वाज जल, वन का भोजन, विश्राम-स्थान और संगम पर रहने की संभावना देते हैं।'),
  ('scene-prayaga-to-yamuna', 'rama-chooses-deeper-solitude', 'en', 'Rama asks for a more distant home', 'Rama worries that people from the city will keep coming if he stays nearby. He asks for a place where Sita can live well without making the hermitage a public court.'),
  ('scene-prayaga-to-yamuna', 'rama-chooses-deeper-solitude', 'hi', 'राम अधिक दूर घर माँगते हैं', 'राम सोचते हैं कि पास रहने पर नगर के लोग आते रहेंगे। वे ऐसी जगह पूछते हैं जहाँ सीता ठीक रह सकें और आश्रम सार्वजनिक दरबार न बन जाए।'),
  ('scene-prayaga-to-yamuna', 'chitrakoot-road-is-drawn', 'en', 'The road to Chitrakoot is drawn', 'Bharadvaja describes the mountain, its fruit, water, animals, ascetics, and paths. The next destination becomes a lived landscape rather than an abstract name.'),
  ('scene-prayaga-to-yamuna', 'chitrakoot-road-is-drawn', 'hi', 'चित्रकूट की राह खींची जाती है', 'भरद्वाज पर्वत, फल, जल, पशु, तपस्वी और मार्गों का वर्णन करते हैं। अगला पड़ाव अमूर्त नाम के बजाय रहने योग्य भू-दृश्य बन जाता है।'),
  ('scene-prayaga-to-yamuna', 'raft-crosses-yamuna', 'en', 'A raft crosses the Yamuna', 'The brothers build a raft and a seat for Sita. Midstream she voices another hope of return; beyond the bank, flowers, the Syama tree, birds, and new questions make the road active.'),
  ('scene-prayaga-to-yamuna', 'raft-crosses-yamuna', 'hi', 'बेड़ा यमुना पार करता है', 'भाई बेड़ा और सीता के लिए आसन बनाते हैं। मध्यधारा में वे फिर वापसी की आशा कहती हैं; दूसरे तट पर फूल, श्यामा-वृक्ष, पक्षी और नए प्रश्न राह को जीवित रखते हैं।'),
  ('scene-chitrakoot-home', 'birds-call-them-forward', 'en', 'Birdsong begins the final walk', 'Rama wakes Lakshmana to the forest''s bird calls. Flowering trees, fruit, honeycombs, peacocks, and elephants make the approach to Chitrakoot feel inhabited before any cottage exists.'),
  ('scene-chitrakoot-home', 'birds-call-them-forward', 'hi', 'पक्षियों का स्वर अंतिम चाल शुरू करता है', 'राम वन-पक्षियों के स्वर पर लक्ष्मण को जगाते हैं। फूलते वृक्ष, फल, मधुकोष, मोर और हाथी किसी कुटिया से पहले ही चित्रकूट को जीवित बना देते हैं।'),
  ('scene-chitrakoot-home', 'mountain-becomes-place', 'en', 'The mountain becomes a place to stay', 'At Chitrakoot, water, roots, fruit, birds, and ascetic communities make subsistence imaginable. Rama says plainly: let this be our abode.'),
  ('scene-chitrakoot-home', 'mountain-becomes-place', 'hi', 'पर्वत रहने की जगह बनता है', 'चित्रकूट में जल, कंद, फल, पक्षी और तपस्वी समुदाय जीवन को संभव बनाते हैं। राम स्पष्ट कहते हैं—यही हमारा निवास हो।'),
  ('scene-chitrakoot-home', 'valmiki-welcomes-them', 'en', 'A hermitage receives them', 'In this selected Dutt edition, the travellers greet Valmiki and explain their journey. The district keeps that edition-specific sequence without claiming every Ramayana places the encounter here.'),
  ('scene-chitrakoot-home', 'valmiki-welcomes-them', 'hi', 'एक आश्रम उन्हें स्वीकारता है', 'इस चुने हुए दत्त संस्करण में यात्री वाल्मीकि को प्रणाम कर अपनी यात्रा बताते हैं। यह जिला इसी संस्करण-विशिष्ट क्रम को रखता है, इसे हर रामायण का क्रम नहीं कहता।'),
  ('scene-chitrakoot-home', 'lakshmana-builds-cottage', 'en', 'Lakshmana builds the cottage', 'Rama chooses the site and Lakshmana gathers strong wood, raises walls and doors, and thatches the roof with leaves. The first forest home appears through work.'),
  ('scene-chitrakoot-home', 'lakshmana-builds-cottage', 'hi', 'लक्ष्मण कुटिया बनाते हैं', 'राम स्थान चुनते हैं और लक्ष्मण मजबूत लकड़ी जुटाकर दीवारें और द्वार खड़े करते, पत्तों की छत डालते हैं। पहला वन-घर श्रम से सामने आता है।'),
  ('scene-chitrakoot-home', 'three-enter-their-home', 'en', 'The three enter their home', 'The source describes household rites before entry; Devam presents them as narrative evidence, not current user instruction. When the three enter, the text allows city-grief to loosen for the first time.'),
  ('scene-chitrakoot-home', 'three-enter-their-home', 'hi', 'तीनों अपने घर में प्रवेश करते हैं', 'स्रोत प्रवेश से पहले गृह-क्रम बताता है; देवम् उसे कथा-साक्ष्य के रूप में रखता है, आज के उपयोगकर्ता के निर्देश की तरह नहीं। तीनों के भीतर आते ही नगर-वियोग पहली बार कुछ ढीला पड़ता है।'),
  ('scene-empty-chariot-return', 'sumantra-turns-home', 'en', 'Sumantra finally turns home', 'After learning that Rama, Sita, and Lakshmana have reached Bharadvaja and are bound for Chitrakoot, Sumantra leaves Guha. The car that carried the exile out now bears only its witness back.'),
  ('scene-empty-chariot-return', 'sumantra-turns-home', 'hi', 'सुमंत्र अंततः घर की ओर मुड़ते हैं', 'राम, सीता और लक्ष्मण के भरद्वाज तक पहुँचने और चित्रकूट जाने का समाचार पाकर सुमंत्र गुह से विदा लेते हैं। जो रथ वनवास को बाहर ले गया था, अब केवल उसके साक्षी को वापस ला रहा है।'),
  ('scene-empty-chariot-return', 'crowds-find-empty-car', 'en', 'The city runs toward an absence', 'At dusk, Ayodhya looks still and joyless. Hundreds surround the returning car and ask where Rama is; the answer that he crossed the Ganga moves through streets and palace windows as a fresh wave of grief.'),
  ('scene-empty-chariot-return', 'crowds-find-empty-car', 'hi', 'नगर एक अनुपस्थिति की ओर दौड़ता है', 'साँझ में अयोध्या स्थिर और उदास दिखती है। सैकड़ों लोग लौटे रथ को घेरकर राम का पता पूछते हैं; गंगा पार करने का उत्तर गलियों और महल की खिड़कियों में शोक की नई लहर बन जाता है।'),
  ('scene-empty-chariot-return', 'dasharatha-asks-every-detail', 'en', 'Dasharatha asks how they live', 'Revived from a faint, Dasharatha asks what the three eat, where they sleep, how Sita walks, and what each person said. The questions are not court business; they are a father trying to rebuild the vanished road in his mind.'),
  ('scene-empty-chariot-return', 'dasharatha-asks-every-detail', 'hi', 'दशरथ पूछते हैं वे कैसे जी रहे हैं', 'मूर्छा से लौटकर दशरथ पूछते हैं कि तीनों क्या खाते हैं, कहाँ सोते हैं, सीता कैसे चलती हैं और किसने क्या कहा। ये राजकाज के प्रश्न नहीं—एक पिता अपने मन में खोई राह फिर से बना रहा है।'),
  ('scene-empty-chariot-return', 'messages-fill-chamber', 'en', 'Three voices return through one witness', 'Sumantra carries Rama''s respectful messages to parents and Bharata, Lakshmana''s anger at the exile, and Sita''s wordless tears beside the departing car. The people are absent, but their distinct responses fill the chamber.'),
  ('scene-empty-chariot-return', 'messages-fill-chamber', 'hi', 'एक साक्षी से तीन स्वर लौटते हैं', 'सुमंत्र माता-पिता और भरत के लिए राम के सम्मानपूर्ण संदेश, वनवास पर लक्ष्मण का क्रोध और जाते रथ के पास सीता के मौन आँसू सुनाते हैं। लोग उपस्थित नहीं, पर उनकी अलग-अलग प्रतिक्रियाएँ कक्ष भर देती हैं।'),
  ('scene-empty-chariot-return', 'horses-and-city-grieve', 'en', 'Even the road returned reluctantly', 'Sumantra remembers the horses slowing and shedding tears when he turned away. He describes a kingdom whose streets, gardens, animals, and people all appear altered by the same absence; Dasharatha begs to be taken after the car again.'),
  ('scene-empty-chariot-return', 'horses-and-city-grieve', 'hi', 'राह भी अनिच्छा से लौटी', 'सुमंत्र याद करते हैं कि लौटते समय घोड़े धीमे पड़े और आँसू बहाते रहे। वे बताते हैं कि गलियाँ, उद्यान, पशु और लोग—पूरा राज्य उसी अनुपस्थिति से बदला दिखता है; दशरथ फिर रथ के पीछे ले चलने की विनती करते हैं।'),
  ('scene-palace-grief-dialogue', 'kausalya-asks-for-car', 'en', 'Kausalya asks to be taken to them', 'Kausalya asks Sumantra to turn the car toward the forest because life without the three feels impossible. Her demand is grief speaking before counsel can make the situation orderly.'),
  ('scene-palace-grief-dialogue', 'kausalya-asks-for-car', 'hi', 'कौसल्या उनके पास ले चलने को कहती हैं', 'कौसल्या सुमंत्र से रथ वन की ओर मोड़ने को कहती हैं, क्योंकि तीनों के बिना जीवन असंभव लगता है। व्यवस्था समझाने से पहले उनका शोक बोलता है।'),
  ('scene-palace-grief-dialogue', 'sumantra-describes-road', 'en', 'Sumantra offers what reassurance he can', 'He says Lakshmana serves them attentively and Sita keeps asking about rivers, villages, trees, and the changing landscape. The report does not erase hardship; it gives Kausalya evidence that the travellers are still acting, noticing, and caring for one another.'),
  ('scene-palace-grief-dialogue', 'sumantra-describes-road', 'hi', 'सुमंत्र जितना हो सके उतना आश्वासन देते हैं', 'वे बताते हैं कि लक्ष्मण सावधानी से सेवा कर रहे हैं और सीता नदियों, गाँवों, वृक्षों और बदलते भू-दृश्य के बारे में पूछती चल रही हैं। यह कठिनाई नहीं मिटाता; बस बताता है कि तीनों अभी भी सक्रिय हैं, देख रहे हैं और एक-दूसरे का ध्यान रख रहे हैं।'),
  ('scene-palace-grief-dialogue', 'kausalya-confronts-king', 'en', 'Kausalya names what was destroyed', 'Kausalya asks how a gentle son, a young daughter-in-law, and Lakshmana can bear the forest after palace life. Her speech widens from family pain to a ruined city and a kingdom whose future has been damaged by its own king.'),
  ('scene-palace-grief-dialogue', 'kausalya-confronts-king', 'hi', 'कौसल्या बताती हैं क्या-क्या टूट गया', 'कौसल्या पूछती हैं कि महल के जीवन के बाद कोमल पुत्र, युवा पुत्रवधू और लक्ष्मण वन कैसे सहेंगे। उनका कथन परिवार के दर्द से फैलकर टूटे नगर और अपने ही राजा से घायल भविष्य तक पहुँचता है।'),
  ('scene-palace-grief-dialogue', 'dasharatha-asks-forgiveness', 'en', 'The king asks his grieving wife for mercy', 'Dasharatha joins his hands and asks Kausalya not to strike him with further words while he is already broken. She immediately recognizes the pain her speech added and bows, without pretending the original wrong has vanished.'),
  ('scene-palace-grief-dialogue', 'dasharatha-asks-forgiveness', 'hi', 'राजा शोकाकुल पत्नी से क्षमा माँगते हैं', 'दशरथ हाथ जोड़कर कौसल्या से कहते हैं कि वे पहले ही टूट चुके हैं, इसलिए शब्दों से और न घायल करें। कौसल्या तुरंत अपने शब्दों की चोट पहचानकर झुकती हैं, पर मूल अन्याय को मिटा हुआ नहीं मानतीं।'),
  ('scene-palace-grief-dialogue', 'fifth-night-stretches', 'en', 'Five nights feel like five years', 'Kausalya says sorrow destroys patience and knowledge, and that the five nights since Rama left have stretched into years. Evening closes around a temporary reconciliation, but Dasharatha''s older memory has already begun to rise.'),
  ('scene-palace-grief-dialogue', 'fifth-night-stretches', 'hi', 'पाँच रातें पाँच वर्ष लगती हैं', 'कौसल्या कहती हैं कि शोक धैर्य और ज्ञान दोनों नष्ट करता है, और राम के जाने की पाँच रातें वर्षों जैसी हो गई हैं। अस्थायी मेल के चारों ओर रात उतरती है, पर दशरथ की पुरानी स्मृति जाग चुकी है।'),
  ('scene-river-sound-confession', 'sixth-night-memory', 'en', 'On the sixth night, another loss returns', 'Dasharatha wakes at midnight and tells Kausalya that actions ripen into consequences. Rama''s exile has brought back a deed from his youth that he had never escaped.'),
  ('scene-river-sound-confession', 'sixth-night-memory', 'hi', 'छठी रात एक और हानि लौटती है', 'आधी रात दशरथ जागकर कौसल्या से कहते हैं कि कर्म परिणाम बनकर लौटते हैं। राम का वनवास उनकी युवावस्था की उस घटना को वापस ले आया है जिससे वे कभी मुक्त नहीं हुए।'),
  ('scene-river-sound-confession', 'rain-and-unseen-sound', 'en', 'A hunter aims at a sound', 'As a young prince in the rainy season, Dasharatha waits beside the Sarayu and hears what he believes is an animal filling the night with water sounds. Confident in shooting by sound, he releases an arrow without seeing the target.'),
  ('scene-river-sound-confession', 'rain-and-unseen-sound', 'hi', 'शिकारी एक ध्वनि पर निशाना लगाता है', 'वर्षा ऋतु में युवा राजकुमार दशरथ सरयू तट पर प्रतीक्षा करते हैं और जल भरने की ध्वनि को पशु समझते हैं। ध्वनि से निशाना लगाने के कौशल पर भरोसा कर वे लक्ष्य देखे बिना बाण छोड़ देते हैं।'),
  ('scene-river-sound-confession', 'human-cry-answers', 'en', 'A human voice answers the arrow', 'The cry from the water is an ascetic youth gathering water for his blind parents. Mortally wounded, he worries less about himself than about the two people waiting for him and directs Dasharatha to their hermitage.'),
  ('scene-river-sound-confession', 'human-cry-answers', 'hi', 'बाण का उत्तर मानव स्वर देता है', 'जल से उठी पुकार अपने दृष्टिहीन माता-पिता के लिए पानी भरते एक तपस्वी युवक की है। मृत्यु के निकट वह अपने से अधिक प्रतीक्षा करते माता-पिता की चिंता करता है और दशरथ को उनके आश्रम का मार्ग बताता है।'),
  ('scene-river-sound-confession', 'parents-hear-footsteps', 'en', 'The parents hear the wrong footsteps', 'The blind parents welcome approaching steps as their son''s return. Dasharatha must identify himself, confess the error, lead them to the body, and stand inside grief he caused but cannot repair.'),
  ('scene-river-sound-confession', 'parents-hear-footsteps', 'hi', 'माता-पिता गलत पदचाप सुनते हैं', 'दृष्टिहीन माता-पिता आती पदचाप को पुत्र की वापसी समझते हैं। दशरथ को अपना परिचय देना, भूल स्वीकारना, उन्हें शव तक ले जाना और उस शोक के भीतर खड़ा होना पड़ता है जिसे वे सुधार नहीं सकते।'),
  ('scene-river-sound-confession', 'curse-reaches-present', 'en', 'The old words reach the present night', 'The father says Dasharatha too will die from grief for a son. Remembering the curse, the old king feels his senses dim, calls for Rama, names the family around him, and dies before the night is half gone.'),
  ('scene-river-sound-confession', 'curse-reaches-present', 'hi', 'पुराने शब्द वर्तमान रात तक पहुँचते हैं', 'पिता कहते हैं कि दशरथ भी पुत्र-वियोग में प्राण देंगे। श्राप याद आते ही वृद्ध राजा की इंद्रियाँ मंद पड़ती हैं; वे राम और परिवार को पुकारते हैं और आधी रात बीतने से पहले प्राण छोड़ देते हैं।'),
  ('scene-city-without-king', 'morning-music-arrives', 'en', 'Morning performs the old routine', 'Bards, singers, attendants, sacred water, mirrors, garments, and royal service arrive as usual. The sun rises while everyone waits for a king who will not wake.'),
  ('scene-city-without-king', 'morning-music-arrives', 'hi', 'सुबह पुरानी दिनचर्या निभाती है', 'गायक, वंशवाचक, सेवक, पवित्र जल, दर्पण, वस्त्र और राजसेवा हमेशा की तरह पहुँचते हैं। सूर्य उगता है, पर सब उस राजा की प्रतीक्षा करते हैं जो अब नहीं जागेगा।'),
  ('scene-city-without-king', 'stillness-is-discovered', 'en', 'Touch confirms the stillness', 'The women beside Dasharatha finally feel that his pulse no longer moves. Their cries wake Kausalya and Sumitra, and the palace understands all at once what happened during the night.'),
  ('scene-city-without-king', 'stillness-is-discovered', 'hi', 'स्पर्श स्थिरता की पुष्टि करता है', 'दशरथ के पास बैठी स्त्रियाँ अंततः पाती हैं कि उनकी नाड़ी नहीं चल रही। उनके विलाप से कौसल्या और सुमित्रा जागती हैं, और महल एक साथ रात की घटना समझ लेता है।'),
  ('scene-city-without-king', 'queens-and-city-wail', 'en', 'The lament leaves the room', 'Kausalya holds Dasharatha''s head and addresses Kaikeyi; the other queens gather, and grief fills halls, terraces, and streets already wounded by Rama''s absence.'),
  ('scene-city-without-king', 'queens-and-city-wail', 'hi', 'विलाप कक्ष से बाहर फैलता है', 'कौसल्या दशरथ का सिर गोद में लेकर कैकेयी से बोलती हैं; अन्य रानियाँ जुटती हैं और राम की अनुपस्थिति से पहले ही घायल सभागार, छतें और गलियाँ शोक से भर जाती हैं।'),
  ('scene-city-without-king', 'farewell-must-wait', 'en', 'The funeral cannot yet begin', 'With the sons absent, the counsellors do not perform the final rites. Dasharatha''s body is placed in oil and the palace enters an unnatural pause between death and succession.'),
  ('scene-city-without-king', 'farewell-must-wait', 'hi', 'अंत्येष्टि अभी शुरू नहीं हो सकती', 'पुत्रों की अनुपस्थिति में मंत्री अंतिम संस्कार नहीं करते। दशरथ का शरीर तेल में सुरक्षित रखा जाता है और महल मृत्यु तथा उत्तराधिकार के बीच अस्वाभाविक ठहराव में चला जाता है।'),
  ('scene-city-without-king', 'council-faces-empty-throne', 'en', 'The council faces a kingdom without a centre', 'At dawn, Vasishta and the counsellors describe the practical danger of a kingless realm—roads, trade, protection, fields, gatherings, and public trust can all unravel. The empty throne is now more than a symbol.'),
  ('scene-city-without-king', 'council-faces-empty-throne', 'hi', 'सभा केंद्रहीन राज्य का सामना करती है', 'भोर में वसिष्ठ और मंत्री राजाविहीन राज्य के व्यावहारिक संकट बताते हैं—मार्ग, व्यापार, सुरक्षा, खेत, सभाएँ और सार्वजनिक भरोसा सब बिखर सकते हैं। खाली सिंहासन अब केवल प्रतीक नहीं रहा।'),
  ('scene-city-without-king', 'messengers-carry-silence', 'en', 'Messengers leave with guarded words', 'Vasishta sends fast riders to Kekaya to bring Bharata and Shatrughna. They are ordered not to mention Dasharatha''s death or Rama''s exile; urgency must travel without its reason.'),
  ('scene-city-without-king', 'messengers-carry-silence', 'hi', 'दूत सँभले हुए शब्द लेकर निकलते हैं', 'वसिष्ठ तेज घुड़सवारों को भरत और शत्रुघ्न को लाने के लिए केकय भेजते हैं। उन्हें दशरथ की मृत्यु और राम के वनवास का उल्लेख न करने का आदेश है; कारण के बिना ही तात्कालिकता यात्रा करती है।'),
  ('scene-bharata-urgent-return', 'bharata-dark-dream', 'en', 'A dream refuses celebration', 'On the night the messengers arrive, Bharata dreams of his father falling, the ocean drying, the moon descending, fire dying, and a dark southward journey. Music and performance cannot make him laugh afterward.'),
  ('scene-bharata-urgent-return', 'bharata-dark-dream', 'hi', 'एक स्वप्न उत्सव को अस्वीकार करता है', 'दूतों के आने की रात भरत पिता के गिरने, समुद्र सूखने, चंद्रमा उतरने, अग्नि बुझने और अँधेरी दक्षिण दिशा की यात्रा का स्वप्न देखते हैं। उसके बाद संगीत और अभिनय भी उन्हें हँसा नहीं पाते।'),
  ('scene-bharata-urgent-return', 'envoys-answer-carefully', 'en', 'Every question receives half an answer', 'Bharata asks after Dasharatha, Rama, Lakshmana, Kausalya, Sumitra, and Kaikeyi. The envoys say those he asks about are well and insist that a matter cannot wait; their careful phrasing deepens his unease.'),
  ('scene-bharata-urgent-return', 'envoys-answer-carefully', 'hi', 'हर प्रश्न को आधा उत्तर मिलता है', 'भरत दशरथ, राम, लक्ष्मण, कौसल्या, सुमित्रा और कैकेयी का कुशल पूछते हैं। दूत कहते हैं कि जिनका वे पूछ रहे हैं वे कुशल हैं और एक काम विलंब नहीं सहता; सँभली हुई भाषा उनकी बेचैनी बढ़ाती है।'),
  ('scene-bharata-urgent-return', 'seven-night-ride', 'en', 'The road is crossed without rest', 'Bharata and Shatrughna leave their maternal family and travel for seven nights across rivers, forests, settlements, and difficult crossings. The geographic sequence becomes a countdown to news they do not yet possess.'),
  ('scene-bharata-urgent-return', 'seven-night-ride', 'hi', 'राह बिना विश्राम पार होती है', 'भरत और शत्रुघ्न ननिहाल से निकलकर सात रातें नदियों, वनों, बस्तियों और कठिन पारों से गुजरते हैं। भूगोल उस समाचार की उलटी गिनती बन जाता है जो उन्हें अभी नहीं मिला।'),
  ('scene-bharata-urgent-return', 'ayodhya-silence-speaks', 'en', 'Ayodhya tells him before people do', 'From a distance Bharata sees no crowds, hears no instruments, smells no incense, and finds gardens, shops, shrines, and homes neglected. He recognizes the signs that accompany a monarch''s death.'),
  ('scene-bharata-urgent-return', 'ayodhya-silence-speaks', 'hi', 'लोगों से पहले अयोध्या बता देती है', 'दूर से भरत न भीड़ देखते हैं, न वाद्य सुनते हैं, न धूप की गंध पाते हैं; उद्यान, दुकानें, पूजा-स्थल और घर उपेक्षित हैं। वे राजा की मृत्यु के साथ आने वाले संकेत पहचान लेते हैं।'),
  ('scene-bharata-urgent-return', 'bharata-enters-palace', 'en', 'The palace has no answer at its centre', 'Bharata dismisses the gatekeepers'' courtesies and enters with his head bowed. His father''s quarters are empty, so the urgent journey ends at Kaikeyi''s door.'),
  ('scene-bharata-urgent-return', 'bharata-enters-palace', 'hi', 'महल के केंद्र में कोई उत्तर नहीं', 'भरत द्वारपालों की औपचारिकता रोककर सिर झुकाए भीतर जाते हैं। पिता का कक्ष खाली है, इसलिए तात्कालिक यात्रा कैकेयी के द्वार पर समाप्त होती है।'),
  ('scene-bharata-rejects-boons', 'kaikeyi-welcomes-son', 'en', 'Kaikeyi welcomes the son she expected to reward', 'Kaikeyi rises, embraces Bharata, asks about the journey, and expects the room to become triumphant. Bharata instead notices his father''s missing bed and asks where the king is.'),
  ('scene-bharata-rejects-boons', 'kaikeyi-welcomes-son', 'hi', 'कैकेयी उस पुत्र का स्वागत करती हैं जिससे पुरस्कार की आशा थी', 'कैकेयी उठकर भरत को गले लगाती हैं, यात्रा पूछती हैं और कक्ष के विजयी होने की अपेक्षा रखती हैं। भरत पिता की खाली शय्या देखते हैं और राजा का पता पूछते हैं।'),
  ('scene-bharata-rejects-boons', 'father-death-spoken', 'en', 'The first truth drops him to the floor', 'Kaikeyi says Dasharatha has reached the end common to all beings. Bharata collapses, grieves the father whose hand once brushed dust from him, and asks for Rama as his elder, refuge, and next father.'),
  ('scene-bharata-rejects-boons', 'father-death-spoken', 'hi', 'पहला सत्य उन्हें भूमि पर गिरा देता है', 'कैकेयी कहती हैं कि दशरथ सभी प्राणियों की समान अंतिम अवस्था को प्राप्त हुए। भरत गिर पड़ते हैं, उस पिता का शोक करते हैं जो उनके शरीर से धूल झाड़ता था, और राम को बड़े भाई, आश्रय और अब पिता के समान पुकारते हैं।'),
  ('scene-bharata-rejects-boons', 'exile-revealed-next', 'en', 'Rama is not in the next room', 'When Bharata asks to go to Rama, Kaikeyi tells him that Rama, Sita, and Lakshmana wear bark in the forest. Bharata first assumes Rama must have committed some grave wrong; he cannot imagine exile without fault.'),
  ('scene-bharata-rejects-boons', 'exile-revealed-next', 'hi', 'राम अगले कक्ष में नहीं हैं', 'भरत राम के पास जाने को कहते हैं तो कैकेयी बताती हैं कि राम, सीता और लक्ष्मण वल्कल पहनकर वन में हैं। भरत पहले किसी गंभीर अपराध की आशंका करते हैं; दोष बिना वनवास की कल्पना नहीं कर पाते।'),
  ('scene-bharata-rejects-boons', 'kaikeyi-claims-success', 'en', 'Kaikeyi names the boons as success', 'She explains that Rama did no wrong: she herself demanded Bharata''s kingdom and Rama''s exile, Dasharatha kept his promise and died grieving, and now Bharata should perform the funeral and take power.'),
  ('scene-bharata-rejects-boons', 'kaikeyi-claims-success', 'hi', 'कैकेयी वरों को सफलता बताती हैं', 'वे बताती हैं कि राम ने कोई अपराध नहीं किया: उन्होंने स्वयं भरत के लिए राज्य और राम का वनवास माँगा, दशरथ ने वचन निभाया और शोक में मरे, इसलिए अब भरत संस्कार कर सत्ता लें।'),
  ('scene-bharata-rejects-boons', 'bharata-rejects-result', 'en', 'Bharata refuses to become the ending', 'Bharata says the kingdom cannot replace father or elder brother, denies any knowledge of the plan, rejects Kaikeyi''s purpose, and vows to bring Rama from the forest and serve him.'),
  ('scene-bharata-rejects-boons', 'bharata-rejects-result', 'hi', 'भरत इस परिणाम का अंत बनने से इंकार करते हैं', 'भरत कहते हैं कि राज्य पिता या बड़े भाई का स्थान नहीं ले सकता, योजना की जानकारी से इंकार करते हैं, कैकेयी के उद्देश्य को अस्वीकार करते हैं और राम को वन से लाकर उनकी सेवा करने की प्रतिज्ञा करते हैं।'),
  ('scene-funeral-and-trust', 'kausalya-fears-complicity', 'en', 'Kausalya cannot yet know whom to trust', 'Hearing Bharata''s voice, Kausalya meets him while still believing he may have wanted the kingdom. She asks to be sent to Rama rather than live inside the result of Kaikeyi''s plan.'),
  ('scene-funeral-and-trust', 'kausalya-fears-complicity', 'hi', 'कौसल्या अभी नहीं जानतीं किस पर भरोसा करें', 'भरत की आवाज़ सुनकर कौसल्या उनसे मिलती हैं, पर अभी मानती हैं कि वे राज्य चाहते थे। वे कैकेयी की योजना के परिणाम में रहने के बजाय राम के पास भेजे जाने को कहती हैं।'),
  ('scene-funeral-and-trust', 'bharata-clears-himself', 'en', 'Bharata puts his whole self behind the denial', 'He falls at Kausalya''s feet and swears that he neither desired the kingdom nor knew of the exile. The long oath is the story''s way of making his innocence answerable, not merely asserted.'),
  ('scene-funeral-and-trust', 'bharata-clears-himself', 'hi', 'भरत अपने पूरे अस्तित्व से इंकार करते हैं', 'वे कौसल्या के चरणों में गिरकर शपथ लेते हैं कि न उन्होंने राज्य चाहा, न वनवास जाना। लंबी शपथ उनकी निर्दोषता को केवल कथन नहीं, उत्तरदायित्व बनाती है।'),
  ('scene-funeral-and-trust', 'kausalya-embraces-bharata', 'en', 'Kausalya recognizes another grieving son', 'Kausalya tells Bharata that his loyalty to what is right makes the oath itself painful to hear. She draws him into her lap, and their separate grief becomes a shared commitment to Rama.'),
  ('scene-funeral-and-trust', 'kausalya-embraces-bharata', 'hi', 'कौसल्या एक और शोकाकुल पुत्र को पहचानती हैं', 'कौसल्या कहती हैं कि धर्मनिष्ठ भरत की शपथ सुनना ही उन्हें और दुख देता है। वे उन्हें गोद में खींचती हैं और अलग-अलग शोक राम के प्रति साझा संकल्प बन जाता है।'),
  ('scene-funeral-and-trust', 'dasharatha-leaves-palace', 'en', 'The suspended farewell moves to the Sarayu', 'Vasishta asks Bharata to perform the rites. Dasharatha''s body is raised from the oil, placed on a bier, and carried with priests, queens, attendants, incense, lament, and gifts toward the funeral ground.'),
  ('scene-funeral-and-trust', 'dasharatha-leaves-palace', 'hi', 'रुकी हुई विदाई सरयू की ओर बढ़ती है', 'वसिष्ठ भरत से संस्कार करने को कहते हैं। दशरथ का शरीर तेल से उठाकर अर्थी पर रखा जाता है और पुरोहितों, रानियों, सेवकों, सुगंध, विलाप तथा दान के साथ श्मशान की ओर ले जाया जाता है।'),
  ('scene-funeral-and-trust', 'ten-days-and-ashes', 'en', 'Mourning is allowed to take time', 'The family performs water rites, sleeps on the ground through the mourning period, completes the shraddha, and returns to gather bones and ashes. Bharata and Shatrughna both collapse under the renewed finality.'),
  ('scene-funeral-and-trust', 'ten-days-and-ashes', 'hi', 'शोक को समय लेने दिया जाता है', 'परिवार जलांजलि देता है, शोक अवधि में भूमि पर सोता है, श्राद्ध पूरा करता है और अस्थियाँ तथा राख लेने लौटता है। अंतिमता फिर सामने आते ही भरत और शत्रुघ्न दोनों टूट पड़ते हैं।'),
  ('scene-funeral-and-trust', 'duties-remain-after-grief', 'en', 'The living are called back to unfinished duties', 'Vasishta and Sumantra lift the brothers and remind them that the remaining rites must be completed. The scene does not end grief; it establishes that action must now continue through it.'),
  ('scene-funeral-and-trust', 'duties-remain-after-grief', 'hi', 'जीवितों को अधूरे कर्तव्यों की ओर लौटाया जाता है', 'वसिष्ठ और सुमंत्र भाइयों को उठाकर शेष संस्कार पूरे करने की याद दिलाते हैं। दृश्य शोक समाप्त नहीं करता; वह बताता है कि अब कर्म उसी के भीतर से आगे बढ़ेगा।'),
  ('scene-crown-refused-road', 'bharata-stops-vengeance', 'en', 'Bharata stops the punishment Rama would reject', 'Shatrughna seizes Manthara in anger over the destruction around them. Bharata stops him: harming her or killing his mother would itself estrange the very brother whose standard he intends to follow.'),
  ('scene-crown-refused-road', 'bharata-stops-vengeance', 'hi', 'भरत वह दंड रोकते हैं जिसे राम स्वीकार न करते', 'चारों ओर हुए विनाश पर क्रोधित शत्रुघ्न मंथरा को पकड़ लेते हैं। भरत उन्हें रोकते हैं: उसे हानि पहुँचाना या माँ की हत्या करना उसी भाई से दूर कर देगा जिसकी मर्यादा वे मानना चाहते हैं।'),
  ('scene-crown-refused-road', 'ministers-offer-crown', 'en', 'The kingdom offers the available answer', 'Ministers place the installation materials before Bharata and argue that Dasharatha''s command has made the throne his. Their proposal is practical, lawful in their reading, and exactly what he refuses.'),
  ('scene-crown-refused-road', 'ministers-offer-crown', 'hi', 'राज्य उपलब्ध उत्तर प्रस्तुत करता है', 'मंत्री राज्याभिषेक-सामग्री भरत के सामने रखकर कहते हैं कि दशरथ की आज्ञा ने सिंहासन उन्हें दिया है। उनका प्रस्ताव व्यावहारिक और उनकी दृष्टि में वैध है—और भरत ठीक इसी को अस्वीकार करते हैं।'),
  ('scene-crown-refused-road', 'rama-named-king', 'en', 'Bharata names the absent king', 'He says the eldest must rule, Rama is king, and he will take the installation objects into the forest, ask Rama to return, and remain there himself if an exchange is required.'),
  ('scene-crown-refused-road', 'rama-named-king', 'hi', 'भरत अनुपस्थित राजा का नाम लेते हैं', 'वे कहते हैं कि ज्येष्ठ ही शासन करेंगे, राम राजा हैं; वे अभिषेक-सामग्री वन ले जाकर राम से लौटने की विनती करेंगे और आवश्यकता पड़ी तो स्वयं वहीं रहेंगे।'),
  ('scene-crown-refused-road', 'road-builders-go-first', 'en', 'A decision becomes physical work', 'Surveyors, diggers, carpenters, bridge-builders, cooks, guides, and camp workers go ahead. They level difficult ground, prepare crossings, find water, and establish the route for a huge public journey.'),
  ('scene-crown-refused-road', 'road-builders-go-first', 'hi', 'निर्णय भौतिक कार्य बनता है', 'सर्वेक्षक, खोदने वाले, बढ़ई, पुल बनाने वाले, रसोइए, मार्गदर्शक और शिविर-कर्मी आगे जाते हैं। वे कठिन भूमि समतल करते, पार बनाते, जल जुटाते और विशाल सार्वजनिक यात्रा की राह तैयार करते हैं।'),
  ('scene-crown-refused-road', 'i-am-not-the-king', 'en', 'Morning praise is silenced', 'At dawn, drums and genealogists wake Bharata with royal praise. He stops them with the words, ''I am not the king,'' before entering the great assembly called by Vasishta.'),
  ('scene-crown-refused-road', 'i-am-not-the-king', 'hi', 'सुबह की राजस्तुति रोक दी जाती है', 'भोर में नगाड़े और वंशवाचक भरत को राजस्तुति से जगाते हैं। वे ''मैं राजा नहीं हूँ'' कहकर सब रोकते हैं और वसिष्ठ की बुलाई महान सभा में जाते हैं।'),
  ('scene-crown-refused-road', 'assembly-orders-journey', 'en', 'The whole city turns toward Rama', 'When Vasishta again presents the throne, Bharata refuses before the gathered city, promises every effort to bring Rama back, and orders Sumantra to ready the car and commanders to marshal the expedition.'),
  ('scene-crown-refused-road', 'assembly-orders-journey', 'hi', 'पूरा नगर राम की ओर मुड़ता है', 'वसिष्ठ सभा में फिर सिंहासन प्रस्तुत करते हैं तो भरत सबके सामने इंकार करते हैं, राम को लौटाने का हर प्रयास करने की प्रतिज्ञा करते हैं और सुमंत्र को रथ तथा सेनानायकों को यात्रा तैयार करने का आदेश देते हैं।'),
  ('scene-expedition-reaches-ganga', 'whole-city-sets-out', 'en', 'A kingdom leaves its throne behind', 'At dawn Bharata sets out with Shatrughna, the mothers, priests, counsellors, citizens, craftspeople, and an immense royal force. This is not a prince''s private visit; Ayodhya itself travels to ask Rama home.'),
  ('scene-expedition-reaches-ganga', 'whole-city-sets-out', 'hi', 'एक राज्य सिंहासन पीछे छोड़कर निकलता है', 'भोर में भरत शत्रुघ्न, माताओं, पुरोहितों, मंत्रियों, नागरिकों, कारीगरों और विशाल राजकीय दल के साथ निकलते हैं। यह किसी राजकुमार की निजी भेंट नहीं—अयोध्या स्वयं राम को घर बुलाने चलती है।'),
  ('scene-expedition-reaches-ganga', 'hope-moves-through-crowd', 'en', 'People imagine the return before it happens', 'Along the road people ask when they will see Rama again and speak as though his face will end the city''s darkness. Hope spreads through embraces, carts, animals, and ordinary working households moving together.'),
  ('scene-expedition-reaches-ganga', 'hope-moves-through-crowd', 'hi', 'लोग वापसी को होने से पहले देख लेते हैं', 'राह में लोग पूछते हैं कि राम फिर कब दिखाई देंगे और मानते हैं कि उनका दर्शन नगर का अँधेरा दूर कर देगा। आलिंगनों, गाड़ियों, पशुओं और साथ चलते परिवारों में आशा फैलती है।'),
  ('scene-expedition-reaches-ganga', 'ganga-stops-the-road', 'en', 'The Ganga stops an army-sized road', 'The expedition reaches Shringaverapura and must become a camp. Bharata plans the crossing and offers water for Dasharatha; the river is both physical boundary and the place where grief returns.'),
  ('scene-expedition-reaches-ganga', 'ganga-stops-the-road', 'hi', 'गंगा सेना-जितनी राह रोकती है', 'यात्रा शृंगवेरपुर पहुँचकर शिविर बन जाती है। भरत पार जाने की व्यवस्था और दशरथ के लिए जल अर्पण की सोचते हैं; नदी भौतिक सीमा भी है और लौटता हुआ शोक भी।'),
  ('scene-expedition-reaches-ganga', 'guha-sees-war', 'en', 'Guha sees banners before intentions', 'Across the river, Guha sees a force without visible end and fears Bharata has come to secure the kingdom by harming Rama. He arms the riverbank and readies hundreds of boats to deny passage if necessary.'),
  ('scene-expedition-reaches-ganga', 'guha-sees-war', 'hi', 'गुह इरादों से पहले ध्वज देखते हैं', 'नदी के पार गुह ऐसा दल देखते हैं जिसका अंत नहीं दिखता और आशंका करते हैं कि भरत राम को हानि पहुँचाकर राज्य पक्का करने आए हैं। वे तट और सैकड़ों नावें रक्षा के लिए तैयार करते हैं।'),
  ('scene-expedition-reaches-ganga', 'gifts-cross-before-trust', 'en', 'A host approaches with gifts and caution', 'Guha carries forest food and hospitality toward Bharata while keeping his people ready. Sumantra identifies him as Rama''s friend and the person most likely to know the road ahead.'),
  ('scene-expedition-reaches-ganga', 'gifts-cross-before-trust', 'hi', 'आतिथ्य और सावधानी साथ आगे बढ़ते हैं', 'गुह वन का भोजन और आतिथ्य लेकर भरत के पास जाते हैं, जबकि उनके लोग सतर्क रहते हैं। सुमंत्र उन्हें राम का मित्र और आगे की राह जानने वाला व्यक्ति बताते हैं।'),
  ('scene-expedition-reaches-ganga', 'bharata-names-purpose', 'en', 'Bharata names the only purpose', 'When Guha asks directly whether the army means harm, Bharata answers without court language: Rama is dear as a father, and he has come only to persuade his elder brother to return.'),
  ('scene-expedition-reaches-ganga', 'bharata-names-purpose', 'hi', 'भरत अपना एकमात्र उद्देश्य बताते हैं', 'जब गुह सीधे पूछते हैं कि क्या यह सेना हानि पहुँचाने आई है, भरत दरबारी भाषा छोड़कर कहते हैं—राम पिता समान प्रिय हैं और वे केवल उन्हें लौटाने आए हैं।'),
  ('scene-guha-shows-first-night', 'guha-recognizes-bharata', 'en', 'Suspicion becomes recognition', 'Bharata''s answer transforms Guha''s stance. He praises a man willing to surrender an unasked-for kingdom, offers guidance to Bharadvaja, and stays near while grief keeps Bharata awake.'),
  ('scene-guha-shows-first-night', 'guha-recognizes-bharata', 'hi', 'संदेह पहचान में बदलता है', 'भरत का उत्तर गुह का रुख बदल देता है। वे अनचाहा राज्य छोड़ने वाले भाई की प्रशंसा करते, भरद्वाज तक मार्गदर्शन देते और शोक में जागते भरत के पास रहते हैं।'),
  ('scene-guha-shows-first-night', 'lakshmana-vigil-retold', 'en', 'Guha retells Lakshmana''s vigil', 'Guha recounts offering Lakshmana a bed and guard. Lakshmana refused sleep while Rama and Sita lay on grass, fearing already that Dasharatha and the mothers might not survive the separation.'),
  ('scene-guha-shows-first-night', 'lakshmana-vigil-retold', 'hi', 'गुह लक्ष्मण की जागी रात सुनाते हैं', 'गुह बताते हैं कि उन्होंने लक्ष्मण को विश्राम और पहरा देने का प्रस्ताव दिया था। राम-सीता को घास पर सोता देखकर लक्ष्मण जागते रहे और दशरथ व माताओं के जीवन के लिए भय जताते रहे।'),
  ('scene-guha-shows-first-night', 'bharata-collapses-at-news', 'en', 'The details strike harder than the headline', 'Hearing how the first night passed, Bharata collapses. Shatrughna and the mothers gather around him; when he recovers, he asks where each person slept, what they ate, and who guarded them.'),
  ('scene-guha-shows-first-night', 'bharata-collapses-at-news', 'hi', 'विवरण समाचार से अधिक चोट करते हैं', 'पहली रात का विवरण सुनकर भरत मूर्छित हो जाते हैं। शत्रुघ्न और माताएँ उन्हें घेर लेती हैं; सँभलकर वे पूछते हैं—कौन कहाँ सोया, क्या खाया और पहरा किसने दिया।'),
  ('scene-guha-shows-first-night', 'grass-bed-remains', 'en', 'The grass still carries a shape', 'At the Ingudi tree, Guha shows the pressed grass, fragments of silk and gold, and the place of Lakshmana''s watch. Bharata reads a whole vanished night from what the ground retained.'),
  ('scene-guha-shows-first-night', 'grass-bed-remains', 'hi', 'घास में अब भी आकृति बची है', 'इंगुदी वृक्ष के नीचे गुह दबा हुआ तृण, रेशम और सोने के छोटे अंश तथा लक्ष्मण की चौकसी का स्थान दिखाते हैं। भरत धरती पर बचे निशानों से पूरी बीती रात पढ़ते हैं।'),
  ('scene-guha-shows-first-night', 'bharata-chooses-exile-exchange', 'en', 'Bharata offers to exchange lives', 'He vows to sleep on the ground, wear bark and matted hair, and remain in the forest if Rama will not return. The plan is no longer only persuasion; Bharata is prepared to take the exile himself.'),
  ('scene-guha-shows-first-night', 'bharata-chooses-exile-exchange', 'hi', 'भरत जीवन बदलने का संकल्प लेते हैं', 'वे भूमि पर सोने, वल्कल और जटा धारण करने तथा राम के न लौटने पर स्वयं वन में रहने का वचन देते हैं। अब योजना केवल विनती नहीं—भरत वनवास अपने ऊपर लेने को तैयार हैं।'),
  ('scene-guha-shows-first-night', 'five-hundred-boats-move', 'en', 'A city crosses by many kinds of courage', 'At dawn Guha''s crews move people, mothers, priests, cars, animals, and supplies across the Ganga in boats and rafts; some swim. By the third watch, the expedition rests in Prayaga''s woods.'),
  ('scene-guha-shows-first-night', 'five-hundred-boats-move', 'hi', 'एक नगर अनेक साहसों से नदी पार करता है', 'भोर में गुह के नाविक लोगों, माताओं, पुरोहितों, रथों, पशुओं और सामग्री को नावों व बेड़ों से गंगा पार कराते हैं; कुछ तैरते हैं। तीसरे प्रहर तक यात्रा प्रयाग के वन में ठहरती है।'),
  ('scene-bharadvaja-tests-hosts', 'bharata-leaves-army-behind', 'en', 'Bharata approaches without force', 'A krosha from the hermitage, Bharata leaves the army, weapons, and courtly display behind. He follows Vasishta on foot so a royal expedition does not trample the ascetic world it seeks help from.'),
  ('scene-bharadvaja-tests-hosts', 'bharata-leaves-army-behind', 'hi', 'भरत सेना के बिना आगे बढ़ते हैं', 'आश्रम से एक क्रोश पहले भरत सेना, अस्त्र और राजकीय प्रदर्शन छोड़ देते हैं। वे वसिष्ठ के पीछे पैदल जाते हैं ताकि सहायता माँगती यात्रा तपोवन को रौंद न दे।'),
  ('scene-bharadvaja-tests-hosts', 'bharadvaja-tests-intention', 'en', 'A second guardian asks the same hard question', 'Bharadvaja asks whether Bharata came to harm Rama and secure the kingdom. Bharata weeps at being suspected again, rejects his mother''s act, and asks only for the way to Rama''s feet.'),
  ('scene-bharadvaja-tests-hosts', 'bharadvaja-tests-intention', 'hi', 'दूसरे संरक्षक का वही कठिन प्रश्न', 'भरद्वाज पूछते हैं कि क्या भरत राम को हानि पहुँचाकर राज्य सुरक्षित करने आए हैं। फिर संदेह सुनकर भरत रो पड़ते, माँ के कर्म को अस्वीकार करते और केवल राम तक की राह माँगते हैं।'),
  ('scene-bharadvaja-tests-hosts', 'test-becomes-direction', 'en', 'The test becomes a direction', 'Satisfied, Bharadvaja says Rama, Sita, and Lakshmana are at Chitrakoot and asks Bharata to stay the night. The unknown forest contracts into a place that can be reached tomorrow.'),
  ('scene-bharadvaja-tests-hosts', 'test-becomes-direction', 'hi', 'परीक्षा दिशा बन जाती है', 'संतुष्ट होकर भरद्वाज बताते हैं कि राम, सीता और लक्ष्मण चित्रकूट में हैं और भरत से रात रुकने को कहते हैं। अनजान वन अब कल पहुँची जा सकने वाली जगह बन जाता है।'),
  ('scene-bharadvaja-tests-hosts', 'army-invited-carefully', 'en', 'Hospitality expands without erasing restraint', 'Bharadvaja asks for the whole force. Bharata explains he kept it away to protect trees, water, animals, and cottages. Only after the host insists does the city-sized company approach.'),
  ('scene-bharadvaja-tests-hosts', 'army-invited-carefully', 'hi', 'संयम बनाए रखते हुए आतिथ्य फैलता है', 'भरद्वाज पूरे दल को बुलाते हैं। भरत बताते हैं कि वृक्ष, जल, पशु और कुटियों की रक्षा के लिए सेना दूर रखी थी। मेज़बान के आग्रह के बाद ही विशाल दल आगे आता है।'),
  ('scene-bharadvaja-tests-hosts', 'hermitage-becomes-wonder', 'en', 'The exhausted road enters a wonder', 'Bharadvaja invokes an extraordinary welcome: wind, blossom rain, music, dwellings, food, water, care for animals, and rest appear around the force. For one night, dust and grief give way to abundance.'),
  ('scene-bharadvaja-tests-hosts', 'hermitage-becomes-wonder', 'hi', 'थकी हुई यात्रा एक अद्भुत संसार में प्रवेश करती है', 'भरद्वाज अद्भुत स्वागत रचते हैं—सुगंधित वायु, पुष्पवर्षा, संगीत, आवास, भोजन, जल, पशुओं की देखभाल और विश्राम। एक रात के लिए धूल और शोक समृद्धि को स्थान देते हैं।'),
  ('scene-bharadvaja-tests-hosts', 'route-through-mandakini', 'en', 'Morning restores the purpose', 'At dawn Bharadvaja directs them south toward the Mandakini and Chitrakoot. The mothers appear together; Bharata names their grief, and the sage interrupts his hatred of Kaikeyi before the army moves on.'),
  ('scene-bharadvaja-tests-hosts', 'route-through-mandakini', 'hi', 'सुबह उद्देश्य फिर सामने आता है', 'भोर में भरद्वाज उन्हें मंदाकिनी और चित्रकूट की दक्षिणी राह बताते हैं। माताएँ साथ आती हैं; भरत उनका शोक बताते हैं और ऋषि कैकेयी के प्रति उनके घृणा-वचन को रोकते हैं।'),
  ('scene-chitrakoot-hears-army', 'forest-flees-before-force', 'en', 'The forest hears the expedition first', 'Elephants, deer, birds, and other forest life scatter before the dust and sound of Bharata''s force. The road to a loving reunion still carries the disruptive weight of a kingdom.'),
  ('scene-chitrakoot-hears-army', 'forest-flees-before-force', 'hi', 'वन सबसे पहले यात्रा सुनता है', 'भरत के दल की धूल और गर्जना से हाथी, हिरन, पक्षी और अन्य वन्य जीव भागते हैं। प्रेमपूर्ण मिलन की राह भी एक राज्य का विघटनकारी भार साथ लाती है।'),
  ('scene-chitrakoot-hears-army', 'smoke-becomes-clue', 'en', 'A line of smoke narrows the world', 'Searchers see smoke that must belong to a dwelling or hermitage. Bharata stops the army from advancing, keeps the forest from being overrun, and follows the clue with only a small company.'),
  ('scene-chitrakoot-hears-army', 'smoke-becomes-clue', 'hi', 'धुएँ की रेखा संसार को एक दिशा देती है', 'खोजी ऐसा धुआँ देखते हैं जो किसी निवास या आश्रम का हो सकता है। भरत सेना रोकते हैं, वन को रौंदने से बचाते हैं और छोटे दल के साथ उस संकेत की ओर बढ़ते हैं।'),
  ('scene-chitrakoot-hears-army', 'chitrakoot-before-alarm', 'en', 'Inside the cottage world, life is briefly whole', 'Before the noise arrives, Rama shows Sita Chitrakoot''s coloured rock, flowering forest, birds, cascades, and the Mandakini. Exile has become a place where the three can still make a life.'),
  ('scene-chitrakoot-hears-army', 'chitrakoot-before-alarm', 'hi', 'कुटिया-संसार में जीवन क्षण भर पूरा है', 'शोर आने से पहले राम सीता को चित्रकूट की रंगीन शिलाएँ, पुष्पित वन, पक्षी, झरने और मंदाकिनी दिखाते हैं। वनवास ऐसी जगह बन गया है जहाँ तीनों जीवन रच सकते हैं।'),
  ('scene-chitrakoot-hears-army', 'lakshmana-climbs-to-see', 'en', 'Lakshmana climbs into fear', 'The ground trembles and animals run. From a tree Lakshmana sees elephants, horses, chariots, infantry, and Bharata''s standard; he asks Rama to hide Sita, string the bow, and prepare for attack.'),
  ('scene-chitrakoot-hears-army', 'lakshmana-climbs-to-see', 'hi', 'लक्ष्मण भय की ओर चढ़ते हैं', 'भूमि काँपती है और पशु भागते हैं। वृक्ष से लक्ष्मण हाथी, घोड़े, रथ, पैदल दल और भरत का ध्वज देखते हैं; वे सीता को सुरक्षित करने और धनुष तैयार करने को कहते हैं।'),
  ('scene-chitrakoot-hears-army', 'rama-refuses-suspicion', 'en', 'Rama refuses to make a brother an enemy', 'Rama says a kingdom gained by killing Bharata would be poison. He trusts that Bharata came from grief and love, and reminds Lakshmana that harm to his brother would be harm to Rama himself.'),
  ('scene-chitrakoot-hears-army', 'rama-refuses-suspicion', 'hi', 'राम भाई को शत्रु मानने से इंकार करते हैं', 'राम कहते हैं कि भरत को मारकर मिला राज्य विष होगा। उन्हें विश्वास है कि भरत शोक और प्रेम से आए हैं; वे याद दिलाते हैं कि भाई को चोट पहुँचाना राम को चोट पहुँचाना होगा।'),
  ('scene-chitrakoot-hears-army', 'bharata-walks-last-distance', 'en', 'The last distance is taken on foot', 'Bharata stations the force away from the hill, searches with Shatrughna, Guha, advisers, and citizens, then sees the smoke himself. Rank and spectacle fall behind as he climbs toward Rama''s cottage.'),
  ('scene-chitrakoot-hears-army', 'bharata-walks-last-distance', 'hi', 'अंतिम दूरी पैदल तय होती है', 'भरत सेना को पर्वत से दूर रोककर शत्रुघ्न, गुह, सलाहकारों और नागरिकों के साथ खोजते हैं, फिर स्वयं धुआँ देखते हैं। पद और प्रदर्शन पीछे छूटते हैं; वे कुटिया की ओर चढ़ते हैं।'),
  ('scene-brothers-meet-death-news', 'cottage-signs-lead-in', 'en', 'Bharata reads the life around the cottage', 'Bark signs, gathered fuel, flowers, a maintained fire, and the path to the Mandakini confirm the dwelling before anyone appears. Bharata sees the practical life Lakshmana built around the exile.'),
  ('scene-brothers-meet-death-news', 'cottage-signs-lead-in', 'hi', 'भरत कुटिया के आसपास का जीवन पढ़ते हैं', 'वल्कल के संकेत, इकट्ठी लकड़ी, फूल, जीवित अग्नि और मंदाकिनी की राह किसी के दिखने से पहले निवास की पुष्टि करते हैं। भरत लक्ष्मण द्वारा रचा व्यावहारिक वन-जीवन देखते हैं।'),
  ('scene-brothers-meet-death-news', 'bharata-sees-rama', 'en', 'The person sought is finally visible', 'Inside, Bharata sees Rama in bark and matted hair beside Sita and Lakshmana. The contrast with the court he remembers overwhelms him before he can complete more than a cry of recognition.'),
  ('scene-brothers-meet-death-news', 'bharata-sees-rama', 'hi', 'जिसे खोजा गया वह अंततः सामने है', 'भीतर भरत राम को वल्कल और जटा में सीता व लक्ष्मण के साथ देखते हैं। स्मृति के राजदरबार और सामने के वन-जीवन का अंतर उन्हें केवल पुकार भर कहने देता है।'),
  ('scene-brothers-meet-death-news', 'brothers-fall-and-embrace', 'en', 'Words fail; the brothers meet', 'Bharata falls at Rama''s feet; Shatrughna follows. Rama raises and embraces them, then receives Sumantra and Guha. The forest community watches four royal brothers meet in tears rather than ceremony.'),
  ('scene-brothers-meet-death-news', 'brothers-fall-and-embrace', 'hi', 'शब्द चूकते हैं; भाई मिलते हैं', 'भरत राम के चरणों में गिरते हैं; शत्रुघ्न भी आते हैं। राम दोनों को उठाकर गले लगाते, फिर सुमंत्र और गुह से मिलते हैं। वनवासी समुदाय चार भाइयों को समारोह नहीं, आँसुओं में मिलता देखता है।'),
  ('scene-brothers-meet-death-news', 'rama-asks-as-if-king', 'en', 'Rama asks questions meant for a ruler', 'Not knowing Dasharatha is dead, Rama asks after father, mothers, priests, advisers, soldiers, farmers, justice, treasury, secrecy, and public welfare. He assumes Bharata carries responsibility and examines how he bears it.'),
  ('scene-brothers-meet-death-news', 'rama-asks-as-if-king', 'hi', 'राम शासक से पूछे जाने वाले प्रश्न करते हैं', 'दशरथ की मृत्यु न जानकर राम पिता, माताओं, पुरोहितों, मंत्रियों, सैनिकों, किसानों, न्याय, कोष, गोपनीयता और लोककल्याण का समाचार पूछते हैं। वे मानते हैं कि भरत उत्तरदायित्व संभाल रहे हैं।'),
  ('scene-brothers-meet-death-news', 'bharata-asks-return', 'en', 'Bharata answers with the empty centre', 'Bharata says the kingdom is not his, names himself servant and brother, and asks Rama to return before the mothers, ministers, and subjects who travelled to his feet. Then he tells why Dasharatha cannot come.'),
  ('scene-brothers-meet-death-news', 'bharata-asks-return', 'hi', 'भरत खाली केंद्र से उत्तर देते हैं', 'भरत कहते हैं कि राज्य उनका नहीं, वे सेवक और भाई हैं, और उन माताओं, मंत्रियों व प्रजाजनों के सामने राम से लौटने को कहते हैं जो उनके चरणों तक आए हैं। फिर वे बताते हैं कि दशरथ क्यों नहीं आए।'),
  ('scene-brothers-meet-death-news', 'death-news-breaks-reunion', 'en', 'The news fells Rama', 'Hearing that Dasharatha died grieving after the exile, Rama collapses. The brothers and Sita carry their mourning to the Mandakini, offer water and the food of their own forest life, then return together to the cottage.'),
  ('scene-brothers-meet-death-news', 'death-news-breaks-reunion', 'hi', 'समाचार राम को गिरा देता है', 'यह सुनकर कि वनवास के बाद शोक में दशरथ की मृत्यु हुई, राम गिर पड़ते हैं। भाई और सीता शोक लेकर मंदाकिनी जाते, जल और अपने वन-जीवन का अन्न अर्पित करते, फिर साथ कुटिया लौटते हैं।'),
  ('scene-family-asks-rama-home', 'mothers-follow-river-path', 'en', 'The mothers see how exile lives', 'Kausalya, Sumitra, Kaikeyi, and the other queens follow the Mandakini path used for water. Kausalya sees Dasharatha''s simple offering and the work Lakshmana performs, reading the family''s changed life in ordinary objects.'),
  ('scene-family-asks-rama-home', 'mothers-follow-river-path', 'hi', 'माताएँ वनवास का जीवन देखती हैं', 'कौसल्या, सुमित्रा, कैकेयी और अन्य रानियाँ मंदाकिनी की जल-राह पर चलती हैं। कौसल्या दशरथ का साधारण अर्पण और लक्ष्मण का श्रम देखकर सामान्य वस्तुओं में बदला पारिवारिक जीवन पढ़ती हैं।'),
  ('scene-family-asks-rama-home', 'family-embraces-dust', 'en', 'The palace family meets the forest family', 'Rama and Lakshmana bow; the mothers wipe dust from their backs. Sita takes their feet and Kausalya embraces her. The reunion is tactile and domestic before it becomes political again.'),
  ('scene-family-asks-rama-home', 'family-embraces-dust', 'hi', 'महल का परिवार वन के परिवार से मिलता है', 'राम और लक्ष्मण प्रणाम करते हैं; माताएँ उनकी पीठ की धूल पोंछती हैं। सीता उनके चरण पकड़ती हैं और कौसल्या उन्हें गले लगाती हैं। राजनीति से पहले मिलन स्पर्श और परिवार का है।'),
  ('scene-family-asks-rama-home', 'silence-before-argument', 'en', 'Everyone waits for the first claim', 'After a night of mourning and morning rites, brothers, mothers, citizens, and advisers sit in silence. The entire expedition has reached its purpose, but affection alone has not decided who must return.'),
  ('scene-family-asks-rama-home', 'silence-before-argument', 'hi', 'सब पहले तर्क की प्रतीक्षा करते हैं', 'शोक की रात और प्रातःकर्म के बाद भाई, माताएँ, नागरिक और सलाहकार मौन बैठते हैं। पूरी यात्रा अपने उद्देश्य तक पहुँच गई है, पर स्नेह ने अभी तय नहीं किया कि कौन लौटेगा।'),
  ('scene-family-asks-rama-home', 'bharata-grants-kingdom-back', 'en', 'Bharata returns what he never accepted', 'Bharata says the kingdom produced by Kaikeyi''s demand is legally in his hands, and he gives it to Rama. He compares himself to someone unable to sustain the great tree another person raised.'),
  ('scene-family-asks-rama-home', 'bharata-grants-kingdom-back', 'hi', 'भरत वह लौटाते हैं जिसे कभी स्वीकार नहीं किया', 'भरत कहते हैं कि कैकेयी की माँग से मिला राज्य विधि के अनुसार उनके हाथ में है और वे उसे राम को देते हैं। वे स्वयं को उस व्यक्ति जैसा बताते हैं जो दूसरे के उगाए विशाल वृक्ष को सँभाल नहीं सकता।'),
  ('scene-family-asks-rama-home', 'rama-holds-fathers-word', 'en', 'Rama will not turn grief into broken truth', 'Rama answers that time separates every family and Dasharatha''s command still binds both sons. Bharata must protect Ayodhya; Rama must complete fourteen years. Mourning cannot make the promise disappear.'),
  ('scene-family-asks-rama-home', 'rama-holds-fathers-word', 'hi', 'राम शोक को टूटे वचन में नहीं बदलते', 'राम कहते हैं कि समय हर परिवार को अलग करता है और दशरथ की आज्ञा दोनों पुत्रों को अब भी बाँधती है। भरत अयोध्या सँभालें, राम चौदह वर्ष पूरे करें; शोक वचन मिटा नहीं सकता।'),
  ('scene-family-asks-rama-home', 'bharata-argues-duty-to-living', 'en', 'Bharata argues that duty must repair harm', 'Bharata answers that an eldest living son should rule, a son may repair a father''s harmful act, and government is itself Rama''s responsibility. If Rama still chooses the forest, Bharata will remain there with him.'),
  ('scene-family-asks-rama-home', 'bharata-argues-duty-to-living', 'hi', 'भरत कहते हैं कि धर्म को हानि सुधारनी चाहिए', 'भरत उत्तर देते हैं कि जीवित ज्येष्ठ पुत्र को शासन करना चाहिए, पुत्र पिता के हानिकारक कर्म को सुधार सकता है और राजकार्य स्वयं राम का दायित्व है। फिर भी राम वन चुनें तो भरत भी वहीं रहेंगे।'),
  ('scene-sandals-hold-kingdom', 'rama-restates-division', 'en', 'Rama names the divided obligation', 'Rama restates the boons and says each brother preserves Dasharatha''s truth by carrying his assigned part: Bharata the kingdom, Rama the forest. The four brothers must protect one promise through different work.'),
  ('scene-sandals-hold-kingdom', 'rama-restates-division', 'hi', 'राम बँटे हुए दायित्व को नाम देते हैं', 'राम वरों को दोहराकर कहते हैं कि हर भाई अपना भाग निभाकर दशरथ का सत्य बचाए—भरत राज्य, राम वन। चारों भाइयों को अलग कार्य से एक वचन की रक्षा करनी है।'),
  ('scene-sandals-hold-kingdom', 'javali-offers-radical-exit', 'en', 'Javali attacks the premise', 'Trying to make Rama return, Javali argues that relationships end, death ends obligation, and visible welfare should outweigh rites and promises. His speech is a position inside the debate, not the narrator''s settled conclusion.'),
  ('scene-sandals-hold-kingdom', 'javali-offers-radical-exit', 'hi', 'जावालि आधार पर ही प्रश्न उठाते हैं', 'राम को लौटाने के लिए जावालि कहते हैं कि संबंध समाप्त होते हैं, मृत्यु दायित्व खत्म करती है और दृश्य लोककल्याण को संस्कार व वचन से ऊपर होना चाहिए। यह बहस का पक्ष है, अंतिम निष्कर्ष नहीं।'),
  ('scene-sandals-hold-kingdom', 'rama-answers-with-public-trust', 'en', 'Rama answers that conduct becomes public trust', 'Rama rejects Javali''s reasoning: a ruler''s conduct teaches others, and truth sustains public confidence. Javali then says he used the argument strategically, revealing the exchange as persuasion rather than simple doctrine.'),
  ('scene-sandals-hold-kingdom', 'rama-answers-with-public-trust', 'hi', 'राम कहते हैं कि आचरण सार्वजनिक विश्वास बनता है', 'राम जावालि का तर्क अस्वीकार करते हैं—शासक का आचरण दूसरों को दिशा देता है और सत्य सार्वजनिक भरोसा सँभालता है। जावालि बताते हैं कि उन्होंने यह पक्ष रणनीतिक रूप से रखा था।'),
  ('scene-sandals-hold-kingdom', 'vasishta-adds-lineage-and-care', 'en', 'Vasishta adds lineage, mother, and teacher', 'Vasishta invokes the eldest-son tradition and his authority as teacher; he asks Rama to heed mother, brother, and people. Rama answers that parental care creates a debt he can honour only by keeping Dasharatha''s command.'),
  ('scene-sandals-hold-kingdom', 'vasishta-adds-lineage-and-care', 'hi', 'वसिष्ठ वंश, माता और गुरु का पक्ष जोड़ते हैं', 'वसिष्ठ ज्येष्ठ-पुत्र परंपरा और गुरु-अधिकार रखते हुए राम से माता, भाई और प्रजा की सुनने को कहते हैं। राम कहते हैं कि माता-पिता की सेवा का ऋण दशरथ की आज्ञा निभाकर ही चुक सकता है।'),
  ('scene-sandals-hold-kingdom', 'bharata-lies-at-door', 'en', 'Bharata refuses food and movement', 'With persuasion exhausted, Bharata spreads grass at the cottage door and vows to lie there until Rama yields. When that too fails, he offers to serve the fourteen-year exile as Rama''s substitute.'),
  ('scene-sandals-hold-kingdom', 'bharata-lies-at-door', 'hi', 'भरत अन्न और गति दोनों रोक देते हैं', 'तर्क समाप्त होने पर भरत कुटिया के द्वार पर कुश बिछाकर राम के मानने तक पड़े रहने का व्रत लेते हैं। यह भी विफल होने पर वे चौदह वर्ष का वनवास स्वयं लेने की बात रखते हैं।'),
  ('scene-sandals-hold-kingdom', 'sandals-become-trust', 'en', 'The sandals become a bounded trust', 'Rama will not accept a substitute, but gives Bharata his sandals. Bharata promises to govern outside Ayodhya in their name, live austerely, and return the kingdom when Rama comes back at fourteen years.'),
  ('scene-sandals-hold-kingdom', 'sandals-become-trust', 'hi', 'पादुकाएँ सीमित धरोहर बनती हैं', 'राम प्रतिनिधि वनवास स्वीकार नहीं करते, पर भरत को अपनी पादुकाएँ देते हैं। भरत उनके नाम पर अयोध्या के बाहर रहकर संयम से शासन और चौदह वर्ष बाद राज्य लौटाने का वचन देते हैं।'),
  ('scene-nandigrama-trust', 'sandals-leave-chitrakoot', 'en', 'Bharata carries the answer above himself', 'Bharata places the sandals on his head and leaves Chitrakoot with Shatrughna, Vasishta, Javali, ministers, mothers, and citizens. Rama returns weeping to the cottage; neither road feels like victory.'),
  ('scene-nandigrama-trust', 'sandals-leave-chitrakoot', 'hi', 'भरत उत्तर को अपने ऊपर रखते हैं', 'भरत पादुकाएँ सिर पर रखकर शत्रुघ्न, वसिष्ठ, जावालि, मंत्रियों, माताओं और नागरिकों के साथ चित्रकूट से लौटते हैं। राम रोते हुए कुटिया जाते हैं; कोई भी राह विजय जैसी नहीं लगती।'),
  ('scene-nandigrama-trust', 'bharadvaja-hears-outcome', 'en', 'The road reports back', 'At Prayaga, Bharata tells Bharadvaja that Rama would not break the fourteen-year promise and that the sandals now carry the work of government. The sage recognizes the resolution without pretending the brothers agreed.'),
  ('scene-nandigrama-trust', 'bharadvaja-hears-outcome', 'hi', 'राह अपना परिणाम बताती है', 'प्रयाग में भरत भरद्वाज को बताते हैं कि राम चौदह वर्ष का वचन नहीं तोड़ेंगे और पादुकाएँ अब शासन का कार्य सँभालेंगी। ऋषि समाधान स्वीकारते हैं, भाइयों की असहमति मिटाते नहीं।'),
  ('scene-nandigrama-trust', 'rivers-reverse-direction', 'en', 'Every crossing now points away from Rama', 'The expedition crosses Yamuna and Ganga again, passes Shringaverapura, and approaches Ayodhya. The same geography that carried hope outward now carries a difficult responsibility back.'),
  ('scene-nandigrama-trust', 'rivers-reverse-direction', 'hi', 'हर नदी अब राम से दूर ले जाती है', 'यात्रा फिर यमुना और गंगा पार कर शृंगवेरपुर से अयोध्या की ओर बढ़ती है। जो भू-दृश्य आशा को बाहर ले गया था, वही अब कठिन उत्तरदायित्व वापस ला रहा है।'),
  ('scene-nandigrama-trust', 'ayodhya-still-without-rama', 'en', 'The city is still waiting', 'Ayodhya''s closed doors, silent music, empty markets, and dark palace show that the journey did not restore ordinary life. Bharata sees a city that cannot yet celebrate and refuses to occupy its centre.'),
  ('scene-nandigrama-trust', 'ayodhya-still-without-rama', 'hi', 'नगर अब भी प्रतीक्षा में है', 'अयोध्या के बंद द्वार, मौन संगीत, खाली बाज़ार और अँधेरा महल बताते हैं कि यात्रा ने सामान्य जीवन नहीं लौटाया। भरत उस नगर का केंद्र लेने से इंकार करते हैं जो अभी उत्सव नहीं मना सकता।'),
  ('scene-nandigrama-trust', 'bharata-chooses-nandigrama', 'en', 'Bharata chooses to govern from outside', 'After settling the mothers in Ayodhya, Bharata tells Vasishta and the counsellors he will live at Nandigrama. Rama is king; Bharata will carry the reins only while waiting for him.'),
  ('scene-nandigrama-trust', 'bharata-chooses-nandigrama', 'hi', 'भरत बाहर से शासन चुनते हैं', 'माताओं को अयोध्या में ठहराकर भरत वसिष्ठ और मंत्रियों से कहते हैं कि वे नंदिग्राम में रहेंगे। राजा राम हैं; भरत केवल उनकी प्रतीक्षा में कार्यभार सँभालेंगे।'),
  ('scene-nandigrama-trust', 'trust-installed-not-king', 'en', 'A trust is installed, not another king', 'At Nandigrama the sandals receive the umbrella and ceremonial place. Bharata wears bark and matted hair, reports decisions in subordination to them, and defines his rule by the moment it must end: Rama''s return.'),
  ('scene-nandigrama-trust', 'trust-installed-not-king', 'hi', 'राजा नहीं, धरोहर स्थापित होती है', 'नंदिग्राम में पादुकाओं को छत्र और राजकीय स्थान मिलता है। भरत वल्कल-जटा धारण कर उनके अधीन निर्णय लेते हैं और अपने शासन को उस क्षण से परिभाषित करते हैं जब वह समाप्त होगा—राम की वापसी।'),
  ('scene-chitrakoot-grows-unsafe', 'ascetics-speak-in-signs', 'en', 'Fear appears before its name', 'After Bharata leaves, Rama notices the neighbouring ascetics exchanging glances and preparing to move. He first asks whether he, Lakshmana, or Sita has failed them.'),
  ('scene-chitrakoot-grows-unsafe', 'ascetics-speak-in-signs', 'hi', 'नाम से पहले भय दिखाई देता है', 'भरत के लौटने के बाद राम पड़ोसी तपस्वियों को संकेतों में बात करते और जाने की तैयारी करते देखते हैं। वे पहले पूछते हैं कि क्या उनसे, लक्ष्मण से या सीता से कोई भूल हुई है।'),
  ('scene-chitrakoot-grows-unsafe', 'khara-name-enters', 'en', 'The threat has a name', 'An elder says the danger is Khara''s Janasthana world and other attackers who break vessels, spoil fires, assume frightening forms, and kill isolated ascetics.'),
  ('scene-chitrakoot-grows-unsafe', 'khara-name-enters', 'hi', 'संकट का एक नाम है', 'एक वृद्ध तपस्वी बताते हैं कि संकट खर के जनस्थान-संसार और उन आक्रमणकारियों से है जो पात्र तोड़ते, अग्नि बुझाते, भयानक रूप धरते और अकेले तपस्वियों को मारते हैं।'),
  ('scene-chitrakoot-grows-unsafe', 'hermitages-choose-survival', 'en', 'The hermitages choose to survive', 'The community will move to another wood. The elder warns that Rama''s presence may draw more danger, and Rama cannot persuade them to remain.'),
  ('scene-chitrakoot-grows-unsafe', 'hermitages-choose-survival', 'hi', 'आश्रम जीवित रहने का निर्णय लेते हैं', 'समुदाय दूसरे वन में जाने का निर्णय लेता है। वृद्ध चेताते हैं कि राम की उपस्थिति और संकट खींच सकती है, और राम उन्हें रुकने के लिए आश्वस्त नहीं कर पाते।'),
  ('scene-chitrakoot-grows-unsafe', 'memory-covers-chitrakoot', 'en', 'Bharata''s visit remains everywhere', 'The cottage still holds the meeting with Bharata and the mothers; the ground carries the trace of the enormous camp. Chitrakoot now recalls grief more readily than shelter.'),
  ('scene-chitrakoot-grows-unsafe', 'memory-covers-chitrakoot', 'hi', 'भरत की यात्रा हर ओर रह जाती है', 'कुटिया में भरत और माताओं की भेंट की स्मृति है; भूमि पर विशाल शिविर के चिह्न हैं। चित्रकूट अब आश्रय से अधिक शोक की याद दिलाता है।'),
  ('scene-chitrakoot-grows-unsafe', 'three-leave-first-home', 'en', 'Three leave the home they made', 'Rama decides to move. Sita and Lakshmana leave with him, carrying the road forward rather than treating Chitrakoot as the whole forest exile.'),
  ('scene-chitrakoot-grows-unsafe', 'three-leave-first-home', 'hi', 'तीनों अपने बनाए घर से निकलते हैं', 'राम आगे बढ़ने का निर्णय लेते हैं। सीता और लक्ष्मण उनके साथ निकलते हैं—चित्रकूट को पूरे वनवास का अंत नहीं, आगे की राह का पहला घर मानकर।'),
  ('scene-sita-tells-her-beginning', 'atri-receives-travellers', 'en', 'A new hermitage receives them', 'Atri welcomes Rama as a son and receives Sita and Lakshmana. He introduces Sita to the aged ascetic Anasuya, whose long discipline is remembered through a drought story.'),
  ('scene-sita-tells-her-beginning', 'atri-receives-travellers', 'hi', 'एक नया आश्रम उन्हें स्वीकारता है', 'अत्रि राम का पुत्र की तरह स्वागत करते हैं और सीता-लक्ष्मण को अपनाते हैं। वे सीता को वृद्ध तपस्विनी अनसूया से मिलाते हैं, जिनकी दीर्घ साधना को अकाल की कथा में याद किया जाता है।'),
  ('scene-sita-tells-her-beginning', 'historical-teaching-stays-spoken', 'en', 'An elder gives the teaching she inherited', 'Anasuya praises Sita''s companionship and speaks in the strongly patriarchal language of the selected historical translation. The scene keeps that speech attributable to its speaker rather than turning it into modern instruction.'),
  ('scene-sita-tells-her-beginning', 'historical-teaching-stays-spoken', 'hi', 'एक वृद्धा अपनी मिली हुई शिक्षा देती हैं', 'अनसूया सीता के साथ निभाने की प्रशंसा करती हैं और चुने हुए ऐतिहासिक अनुवाद की गहरी पितृसत्तात्मक भाषा में बोलती हैं। दृश्य उस वाणी को वक्ता से जोड़कर रखता है, आधुनिक निर्देश नहीं बनाता।'),
  ('scene-sita-tells-her-beginning', 'sita-answers-from-memory', 'en', 'Sita answers with memories of her own', 'Sita recalls what her mother, mother-in-law, and household taught her, then speaks of Rama''s conduct toward the royal mothers. Her response is neither silence nor a detached rule; it is personal memory inside her chosen journey.'),
  ('scene-sita-tells-her-beginning', 'sita-answers-from-memory', 'hi', 'सीता अपनी स्मृतियों से उत्तर देती हैं', 'सीता अपनी माता, सास और परिवार से मिली सीख याद करती हैं, फिर राजमाताओं के प्रति राम के व्यवहार की बात करती हैं। उनका उत्तर न मौन है, न कोई निरपेक्ष नियम—यह उनकी चुनी हुई यात्रा के भीतर निजी स्मृति है।'),
  ('scene-sita-tells-her-beginning', 'anasuya-gives-with-affection', 'en', 'Affection becomes something carried', 'When Sita asks for nothing, Anasuya gives her garments, ornaments, a garland, and fragrant paste. The gifts mark hospitality and relationship before another difficult road.'),
  ('scene-sita-tells-her-beginning', 'anasuya-gives-with-affection', 'hi', 'स्नेह साथ ले जाने योग्य बनता है', 'जब सीता कुछ नहीं माँगतीं, अनसूया उन्हें वस्त्र, आभूषण, माला और सुगंधित लेप देती हैं। ये उपहार कठिन राह से पहले आतिथ्य और संबंध का चिह्न बनते हैं।'),
  ('scene-sita-tells-her-beginning', 'sita-begins-with-earth', 'en', 'Sita begins with the earth and Janaka', 'Asked to tell her story at length, Sita says Janaka found her while ploughing sacrificial ground and accepted her as his daughter. She narrates her origin rather than appearing only as someone else''s prize.'),
  ('scene-sita-tells-her-beginning', 'sita-begins-with-earth', 'hi', 'सीता पृथ्वी और जनक से आरम्भ करती हैं', 'अपनी कथा विस्तार से सुनाने पर सीता कहती हैं कि यज्ञभूमि जोतते समय जनक ने उन्हें पाया और पुत्री रूप में स्वीकार किया। वे केवल किसी की प्राप्ति नहीं, अपनी उत्पत्ति स्वयं सुनाती हैं।'),
  ('scene-sita-tells-her-beginning', 'bow-and-choice-retold', 'en', 'The bow, the assembly, and the choice are retold', 'Sita recounts Janaka''s anxiety, the assembly around the immovable bow, Rama lifting and breaking it, and the consultations that joined the households. Night arrives while her own voice closes the Ayodhya book.'),
  ('scene-sita-tells-her-beginning', 'bow-and-choice-retold', 'hi', 'धनुष, सभा और चुनाव फिर सुनाए जाते हैं', 'सीता जनक की चिंता, अचल धनुष की सभा, राम द्वारा उसे उठाकर तोड़ने और दोनों परिवारों को जोड़ने वाली सहमति की कथा सुनाती हैं। उनकी अपनी आवाज़ में आयोध्या काण्ड का अंत होते-होते रात उतर आती है।'),
  ('scene-dandaka-receives-them', 'sun-enters-clouds', 'en', 'The forest closes around them', 'Warned that danger lies ahead, Rama, Sita, and Lakshmana enter the deeper forest. The selected edition compares their entry to the sun passing into cloud.'),
  ('scene-dandaka-receives-them', 'sun-enters-clouds', 'hi', 'वन उनके चारों ओर गहरा जाता है', 'आगे के संकट की चेतावनी लेकर राम, सीता और लक्ष्मण गहरे वन में प्रवेश करते हैं। चुना हुआ संस्करण उनके प्रवेश की तुलना बादलों में जाते सूर्य से करता है।'),
  ('scene-dandaka-receives-them', 'hermitages-form-constellation', 'en', 'Homes appear between the trees', 'Dandaka reveals fire rooms, water jars, bark dwellings, gardens, lotus tanks, recitation, birds, deer, roots, and fruit. The first impression is a living network of care and work.'),
  ('scene-dandaka-receives-them', 'hermitages-form-constellation', 'hi', 'वृक्षों के बीच घर उभरते हैं', 'दण्डक में अग्निशालाएँ, जलपात्र, वल्कल-कुटियाँ, उद्यान, कमल-सरोवर, पाठ, पक्षी, हिरण, कन्द और फल दिखाई देते हैं। पहला अनुभव श्रम और देखभाल के जीवित जाल का है।'),
  ('scene-dandaka-receives-them', 'bows-unstrung-at-threshold', 'en', 'The bow lowers at the threshold', 'Rama unstrings his bow before entering. The residents come forward, offer water, food, flowers, and shelter, and study the three travellers with wonder.'),
  ('scene-dandaka-receives-them', 'bows-unstrung-at-threshold', 'hi', 'देहरी पर धनुष नीचे होता है', 'राम प्रवेश से पहले धनुष की प्रत्यंचा उतारते हैं। निवासी आगे आकर जल, भोजन, फूल और आश्रय देते हैं तथा तीनों यात्रियों को विस्मय से देखते हैं।'),
  ('scene-dandaka-receives-them', 'king-without-city', 'en', 'A king without a city is still addressed', 'The ascetics say that Rama remains responsible for people in his dominion whether he lives in city or forest. His own displacement does not erase their expectation of protection.'),
  ('scene-dandaka-receives-them', 'king-without-city', 'hi', 'नगर बिना भी राजा को पुकारा जाता है', 'तपस्वी कहते हैं कि राम नगर में हों या वन में, अपने क्षेत्र के लोगों के प्रति उत्तरदायी हैं। उनका स्वयं विस्थापित होना दूसरों की सुरक्षा की अपेक्षा मिटाता नहीं।'),
  ('scene-dandaka-receives-them', 'hospitality-before-danger', 'en', 'The world feeds them before testing them', 'The visitors eat and rest among the hermitages. At sunrise they continue, and the ordered clearings give way to a damaged forest of frightened birds and disturbed water.'),
  ('scene-dandaka-receives-them', 'hospitality-before-danger', 'hi', 'संसार परीक्षा से पहले उन्हें भोजन देता है', 'यात्री आश्रमों में भोजन और विश्राम पाते हैं। सूर्योदय पर आगे बढ़ते ही व्यवस्थित खुली जगहों की जगह टूटे वृक्ष, डरे पक्षी और मटमैला जल आने लगता है।'),
  ('scene-viradha-breaks-the-road', 'viradha-appears-with-aftermath', 'en', 'Danger arrives carrying its aftermath', 'Viradha appears enormous, blood-marked, and carrying the bodies of animals on a spear. He declares the forest his domain and seizes Sita.'),
  ('scene-viradha-breaks-the-road', 'viradha-appears-with-aftermath', 'hi', 'संकट अपने परिणामों के साथ आता है', 'विराध विशाल, रक्त-चिह्नित और भाले पर मारे गए पशु लिए प्रकट होता है। वह वन को अपना क्षेत्र बताकर सीता को उठा लेता है।'),
  ('scene-viradha-breaks-the-road', 'old-grief-breaks-surface', 'en', 'An old grief breaks through Rama', 'Seeing Sita held, Rama connects the moment to exile, Kaikeyi, the lost kingdom, and Dasharatha''s death. Lakshmana answers the collapse with furious readiness to act.'),
  ('scene-viradha-breaks-the-road', 'old-grief-breaks-surface', 'hi', 'राम के भीतर पुराना शोक फूटता है', 'सीता को पकड़े देखकर राम इस क्षण को वनवास, कैकेयी, खोए राज्य और दशरथ की मृत्यु से जोड़ते हैं। लक्ष्मण इस टूटन का उत्तर तीव्र कार्रवाई की तैयारी से देते हैं।'),
  ('scene-viradha-breaks-the-road', 'arrows-do-not-end-it', 'en', 'The arrows land, but do not end it', 'Rama''s arrows force Viradha to release Sita, but a boon keeps weapons from killing him. He charges again and lifts both brothers onto his shoulders.'),
  ('scene-viradha-breaks-the-road', 'arrows-do-not-end-it', 'hi', 'बाण लगते हैं, पर संकट समाप्त नहीं होता', 'राम के बाण विराध को सीता छोड़ने पर विवश करते हैं, पर वरदान उसे हथियारों से मरने नहीं देता। वह फिर आक्रमण कर दोनों भाइयों को कंधों पर उठा लेता है।'),
  ('scene-viradha-breaks-the-road', 'sita-intervenes-alone', 'en', 'Sita refuses to disappear from the action', 'Left on the ground, Sita calls out and offers herself if Viradha will release Rama and Lakshmana. Her intervention gives the brothers the opening to break his arms.'),
  ('scene-viradha-breaks-the-road', 'sita-intervenes-alone', 'hi', 'सीता कार्रवाई से गायब नहीं होतीं', 'भूमि पर छूटकर सीता पुकारती हैं और राम-लक्ष्मण को छोड़ने के बदले स्वयं को ले जाने को कहती हैं। उनके हस्तक्षेप से भाइयों को विराध की भुजाएँ तोड़ने का अवसर मिलता है।'),
  ('scene-viradha-breaks-the-road', 'method-must-change', 'en', 'They change the method', 'Blows and blades still fail. Rama recognizes the limit and orders a pit; Lakshmana digs while Rama holds Viradha down.'),
  ('scene-viradha-breaks-the-road', 'method-must-change', 'hi', 'वे तरीका बदलते हैं', 'प्रहार और तलवार भी असफल रहते हैं। राम सीमा पहचानकर गड्ढा खोदने को कहते हैं; लक्ष्मण खोदते हैं और राम विराध को रोके रखते हैं।'),
  ('scene-viradha-breaks-the-road', 'enemy-becomes-direction', 'en', 'The defeated enemy becomes a direction', 'Viradha recognizes Rama, says a curse shaped his form, and points the travellers toward Sarabhanga before the burial frees him. The attack ends by changing the road ahead.'),
  ('scene-viradha-breaks-the-road', 'enemy-becomes-direction', 'hi', 'पराजित शत्रु दिशा बन जाता है', 'विराध राम को पहचानकर बताता है कि शाप ने उसका रूप बनाया और मुक्त होने से पहले यात्रियों को शरभंग की ओर भेजता है। आक्रमण आगे की राह बदलकर समाप्त होता है।'),
  ('scene-forest-asks-protection', 'indra-leaves-before-meeting', 'en', 'A celestial meeting ends as Rama arrives', 'Near Sarabhanga''s hermitage, Rama sees Indra''s airborne company. Indra departs before meeting him, saying Rama still has work to complete.'),
  ('scene-forest-asks-protection', 'indra-leaves-before-meeting', 'hi', 'राम के आते ही दिव्य भेंट समाप्त होती है', 'शरभंग के आश्रम के पास राम इन्द्र का आकाशीय दल देखते हैं। इन्द्र मिलने से पहले यह कहकर चले जाते हैं कि राम का कार्य अभी बाकी है।'),
  ('scene-forest-asks-protection', 'sarabhanga-waits-for-rama', 'en', 'Sarabhanga waited before leaving', 'Sarabhanga says he delayed his ascent until he could see Rama. Rama declines inherited heavenly regions and asks instead where he should live in the forest.'),
  ('scene-forest-asks-protection', 'sarabhanga-waits-for-rama', 'hi', 'शरभंग जाने से पहले प्रतीक्षा करते हैं', 'शरभंग कहते हैं कि उन्होंने राम को देखने तक अपना प्रस्थान टाल दिया। राम मिले हुए स्वर्गलोक अस्वीकार कर पूछते हैं कि वन में उन्हें कहाँ रहना चाहिए।'),
  ('scene-forest-asks-protection', 'sarabhanga-enters-fire', 'en', 'An old body becomes a new departure', 'After directing Rama toward Sutikshna, Sarabhanga enters the fire and rises in a youthful form toward the worlds he had attained. The travellers witness rather than interrupt the departure.'),
  ('scene-forest-asks-protection', 'sarabhanga-enters-fire', 'hi', 'वृद्ध देह नया प्रस्थान बनती है', 'राम को सुतीक्ष्ण की ओर भेजकर शरभंग अग्नि में प्रवेश करते हैं और युवा रूप में अपने प्राप्त लोकों की ओर उठते हैं। यात्री इस प्रस्थान के साक्षी रहते हैं।'),
  ('scene-forest-asks-protection', 'many-communities-gather', 'en', 'The forest arrives in many forms', 'Ascetics with many disciplines gather after Sarabhanga''s departure. Their diversity makes clear that this is not one isolated household asking for help.'),
  ('scene-forest-asks-protection', 'many-communities-gather', 'hi', 'वन अनेक समुदायों के रूप में आता है', 'शरभंग के प्रस्थान के बाद अनेक प्रकार की साधना करने वाले तपस्वी जुटते हैं। उनकी विविधता बताती है कि सहायता माँगने वाला कोई एक अलग घर नहीं, पूरा समुदाय है।'),
  ('scene-forest-asks-protection', 'bodies-make-cost-visible', 'en', 'The cost is made visible', 'They show the remains of people killed along the rivers and near Chitrakoot and say the attacks repeatedly interrupt their lives. They ask Rama to become a refuge.'),
  ('scene-forest-asks-protection', 'bodies-make-cost-visible', 'hi', 'हानि आँखों के सामने रखी जाती है', 'वे नदियों और चित्रकूट के आसपास मारे गए लोगों के अवशेष दिखाते हैं और बताते हैं कि आक्रमण बार-बार उनके जीवन को तोड़ते हैं। वे राम से आश्रय बनने को कहते हैं।'),
  ('scene-forest-asks-protection', 'rama-makes-forest-promise', 'en', 'Rama accepts a wider obligation', 'Rama says they need not beg: their protection is work he accepts alongside his father''s command. The promise sends the travellers onward to Sutikshna and will soon be questioned by Sita.'),
  ('scene-forest-asks-protection', 'rama-makes-forest-promise', 'hi', 'राम व्यापक दायित्व स्वीकारते हैं', 'राम कहते हैं कि उन्हें विनती नहीं करनी चाहिए—उनकी सुरक्षा पिता की आज्ञा के साथ स्वीकार किया गया कार्य है। यही वचन यात्रियों को सुतीक्ष्ण की ओर भेजता है और शीघ्र ही सीता के प्रश्न का विषय बनेगा।'),
  ('scene-sita-questions-the-bow', 'sutikshna-offers-stay', 'en', 'Sutikshna offers a place to remain', 'Sutikshna welcomes the travellers and offers his hermitage, but Rama worries that hunting even the troublesome deer would hurt his host. They stay one night, then ask to see the wider Dandaka world.'),
  ('scene-sita-questions-the-bow', 'sutikshna-offers-stay', 'hi', 'सुतीक्ष्ण ठहरने का स्थान देते हैं', 'सुतीक्ष्ण यात्रियों का स्वागत कर अपना आश्रम देते हैं, पर राम सोचते हैं कि उपद्रवी हिरणों को मारना भी मेजबान को दुख देगा। वे एक रात रुककर व्यापक दण्डक-संसार देखने की अनुमति माँगते हैं।'),
  ('scene-sita-questions-the-bow', 'sita-hands-over-weapons', 'en', 'Sita hands them the weapons—and then speaks', 'At departure Sita gives the bows, quivers, and swords to the brothers. On the road she begins an affectionate warning about what those weapons may invite.'),
  ('scene-sita-questions-the-bow', 'sita-hands-over-weapons', 'hi', 'सीता हथियार देती हैं—और फिर बोलती हैं', 'प्रस्थान पर सीता भाइयों को धनुष, तरकश और तलवारें देती हैं। राह में वे स्नेह से चेताती हैं कि यही हथियार किस तरह की प्रवृत्ति बुला सकते हैं।'),
  ('scene-sita-questions-the-bow', 'three-dangerous-desires', 'en', 'She names three ways desire distorts action', 'Sita rules out falsehood and betrayal in Rama, then focuses on hostility without prior offence. The danger she sees is not protection itself, but making violence precede relationship or cause.'),
  ('scene-sita-questions-the-bow', 'three-dangerous-desires', 'hi', 'वे इच्छा से बिगड़ते तीन मार्ग गिनाती हैं', 'सीता राम में असत्य और विश्वासघात की संभावना नकारकर बिना पूर्व अपराध के शत्रुता पर ध्यान देती हैं। उनके लिए संकट सुरक्षा नहीं, संबंध या कारण से पहले हिंसा को रख देना है।'),
  ('scene-sita-questions-the-bow', 'sword-changes-ascetic', 'en', 'A sword changes the person guarding it', 'She tells of an ascetic entrusted with a sword who carries it everywhere, gradually abandons discipline, and becomes governed by fierce thoughts. A tool held for safekeeping reshapes its keeper.'),
  ('scene-sita-questions-the-bow', 'sword-changes-ascetic', 'hi', 'तलवार अपने रक्षक को बदल देती है', 'वे एक तपस्वी की कथा सुनाती हैं जिसे तलवार धरोहर में मिली, जो उसे हर जगह ले जाते-ले जाते साधना छोड़कर उग्र विचारों के अधीन हो गया। सुरक्षित रखने का साधन अपने रक्षक को ही बदल देता है।'),
  ('scene-sita-questions-the-bow', 'protect-do-not-preempt', 'en', 'Protection is not the same as pre-emption', 'Sita says a bow should rescue people already in danger, not turn every unknown forest being into an enemy. She asks Rama to think before acting, not to abandon responsibility.'),
  ('scene-sita-questions-the-bow', 'protect-do-not-preempt', 'hi', 'रक्षा और पहले से आक्रमण एक नहीं', 'सीता कहती हैं कि धनुष संकट में पड़े लोगों की रक्षा करे, हर अनजान वनवासी को शत्रु न बना दे। वे राम से दायित्व छोड़ने नहीं, कार्य से पहले विचार करने को कहती हैं।'),
  ('scene-sita-questions-the-bow', 'rama-answers-from-promise', 'en', 'Rama answers from the promise already made', 'Rama honours Sita''s concern but says people personally sought refuge and he promised protection. He treats her challenge as speech born from love, yet holds that breaking the promise would also be wrong. The tension remains visible.'),
  ('scene-sita-questions-the-bow', 'rama-answers-from-promise', 'hi', 'राम पहले किए वचन से उत्तर देते हैं', 'राम सीता की चिंता का सम्मान करते हैं, पर कहते हैं कि लोगों ने स्वयं शरण माँगी और उन्होंने रक्षा का वचन दिया है। वे उनके प्रश्न को प्रेम से निकली वाणी मानते हुए भी वचन तोड़ना अनुचित मानते हैं। तनाव समाप्त नहीं होता।'),
  ('scene-ten-years-become-map', 'forest-opens-in-layers', 'en', 'The road becomes landscape', 'Rama leads, Sita walks between the brothers, and Lakshmana follows. Peaks, streams, islands, lotus tanks, deer, buffalo, boar, and elephants make travel feel inhabited at every scale.'),
  ('scene-ten-years-become-map', 'forest-opens-in-layers', 'hi', 'राह भू-दृश्य बन जाती है', 'राम आगे, सीता बीच और लक्ष्मण पीछे चलते हैं। पर्वत, धाराएँ, द्वीप, कमल-सरोवर, हिरण, भैंसे, सूअर और हाथी हर स्तर पर यात्रा को जीवित बनाते हैं।'),
  ('scene-ten-years-become-map', 'music-without-musicians', 'en', 'A lake sings without visible musicians', 'At Panchapsara they hear instruments and song but see no performers. Dharmabhrit tells the wondrous story of Mandakarni, five Apsaras, interrupted austerity, and a hidden dwelling beneath the water.'),
  ('scene-ten-years-become-map', 'music-without-musicians', 'hi', 'एक सरोवर बिना दिखते वादकों के गाता है', 'पञ्चाप्सरा पर वे संगीत और गायन सुनते हैं, पर कोई कलाकार दिखाई नहीं देता। धर्मभृत मन्दकर्णि, पाँच अप्सराओं, बाधित तपस्या और जल के भीतर छिपे निवास की अद्भुत कथा सुनाते हैं।'),
  ('scene-ten-years-become-map', 'hermitages-not-one-stop', 'en', 'Dandaka is not one destination', 'The travellers live among many hermitages, returning to hosts and moving onward again. The forest world becomes a network rather than a single linear road.'),
  ('scene-ten-years-become-map', 'hermitages-not-one-stop', 'hi', 'दण्डक कोई एक पड़ाव नहीं', 'यात्री अनेक आश्रमों में रहते, पुराने मेजबानों के पास लौटते और फिर आगे बढ़ते हैं। वन-संसार एक सीधी राह नहीं, आपस में जुड़ा जाल बन जाता है।'),
  ('scene-ten-years-become-map', 'ten-years-pass-in-stays', 'en', 'Ten years pass through uneven stays', 'The selected edition names stays of months and years before saying ten years have passed. Devam keeps that compression visible instead of pretending every day or location is already reconstructed.'),
  ('scene-ten-years-become-map', 'ten-years-pass-in-stays', 'hi', 'दस वर्ष असमान ठहरावों में बीतते हैं', 'चुना हुआ संस्करण महीनों और वर्षों के अलग-अलग ठहराव गिनाकर कहता है कि दस वर्ष बीत गए। देवम इस संक्षेप को स्पष्ट रखता है—हर दिन या स्थान के पूर्ण पुनर्निर्माण का दावा नहीं करता।'),
  ('scene-ten-years-become-map', 'return-to-sutikshna', 'en', 'The long circuit returns to Sutikshna', 'After visiting the hermitage network, Rama returns to Sutikshna. The journey now needs a new destination, not simply another anonymous clearing.'),
  ('scene-ten-years-become-map', 'return-to-sutikshna', 'hi', 'लंबा चक्र सुतीक्ष्ण के पास लौटता है', 'आश्रम-जाल की यात्रा के बाद राम सुतीक्ष्ण के पास लौटते हैं। अब यात्रा को केवल एक और अनाम खुली जगह नहीं, नई दिशा चाहिए।'),
  ('scene-ten-years-become-map', 'agastya-becomes-direction', 'en', 'A name becomes the next direction', 'Rama says he has long wanted to meet Agastya. Sutikshna gives a southward route through Agastya''s brother''s hermitage, and the travellers set out the same day.'),
  ('scene-ten-years-become-map', 'agastya-becomes-direction', 'hi', 'एक नाम अगली दिशा बनता है', 'राम कहते हैं कि वे लंबे समय से अगस्त्य से मिलना चाहते हैं। सुतीक्ष्ण अगस्त्य के भाई के आश्रम से होकर दक्षिण की राह बताते हैं, और यात्री उसी दिन निकलते हैं।'),
  ('scene-agastya-points-south', 'southern-road-has-stories', 'en', 'The road already carries remembered stories', 'Rama reads smoke, fruit trees, birds, and pippali groves as signs of the route. He retells how Agastya ended the deadly deception of Vatapi and Ilwala, making the southward world habitable in this telling.'),
  ('scene-agastya-points-south', 'southern-road-has-stories', 'hi', 'राह पहले से कथाएँ लिए है', 'राम धुएँ, फलदार वृक्षों, पक्षियों और पिप्पली वन को राह के संकेत की तरह पढ़ते हैं। वे बताते हैं कि इस कथा में अगस्त्य ने वातापि-इल्वल की घातक छलना समाप्त कर दक्षिण दिशा को रहने योग्य बनाया।'),
  ('scene-agastya-points-south', 'lakshmana-announces-arrival', 'en', 'Lakshmana carries the names across the threshold', 'At Agastya''s hermitage, Lakshmana introduces Rama, Sita, and himself to a disciple and explains the forest command that brought them there. Agastya says he had long wished for their arrival.'),
  ('scene-agastya-points-south', 'lakshmana-announces-arrival', 'hi', 'लक्ष्मण देहरी पर नाम पहुँचाते हैं', 'अगस्त्य के आश्रम पर लक्ष्मण एक शिष्य को राम, सीता और अपना परिचय देकर बताते हैं कि पिता की आज्ञा उन्हें वन में लाई। अगस्त्य कहते हैं कि वे लंबे समय से उनके आने की इच्छा रखते थे।'),
  ('scene-agastya-points-south', 'agastya-receives-guests', 'en', 'Hospitality comes before instruction', 'Agastya embraces Rama, receives all three with water, food, flowers, and a seat, and names Rama a beloved guest. The encounter begins with care, not weapons.'),
  ('scene-agastya-points-south', 'agastya-receives-guests', 'hi', 'निर्देश से पहले आतिथ्य आता है', 'अगस्त्य राम को आलिंगन देकर तीनों का जल, भोजन, फूल और आसन से स्वागत करते हैं तथा राम को प्रिय अतिथि कहते हैं। भेंट की शुरुआत हथियारों से नहीं, देखभाल से होती है।'),
  ('scene-agastya-points-south', 'weapons-enter-as-stories', 'en', 'The weapons arrive with histories attached', 'Agastya gives Rama a bow associated with Vishnu, an arrow, inexhaustible quivers, and a sword. They are presented as storied gifts inside this epic—not archaeological objects or modern ritual implements.'),
  ('scene-agastya-points-south', 'weapons-enter-as-stories', 'hi', 'हथियार अपनी कथाओं के साथ आते हैं', 'अगस्त्य राम को विष्णु से जुड़ा धनुष, एक बाण, अक्षय तरकश और तलवार देते हैं। ये इस महाकाव्य के भीतर कथा-सम्पन्न उपहार हैं—पुरातात्त्विक वस्तु या आधुनिक अनुष्ठान-सामग्री नहीं।'),
  ('scene-agastya-points-south', 'agastya-sees-sitas-fatigue', 'en', 'Agastya sees Sita''s fatigue', 'Agastya explicitly notices that Sita has crossed hardship out of love and asks Rama to make the remaining forest life easier for her. The next home is chosen with her experience in view.'),
  ('scene-agastya-points-south', 'agastya-sees-sitas-fatigue', 'hi', 'अगस्त्य सीता की थकान देखते हैं', 'अगस्त्य स्पष्ट देखते हैं कि सीता प्रेम के कारण कठिन राह से गुज़री हैं और राम से शेष वनजीवन उनके लिए सहज बनाने को कहते हैं। अगला घर उनके अनुभव को ध्यान में रखकर चुना जाता है।'),
  ('scene-agastya-points-south', 'panchavati-opens-ahead', 'en', 'Panchavati becomes the next home', 'Asked for a well-watered place, Agastya names Panchavati near the Godavari, gives a narrative route past the Madhuka wood and a hill, and sends the three onward. The district ends before Jatayu appears.'),
  ('scene-agastya-points-south', 'panchavati-opens-ahead', 'hi', 'पञ्चवटी अगला घर बनती है', 'जल और वन से भरा स्थान पूछने पर अगस्त्य गोदावरी के पास पञ्चवटी का नाम लेते हैं, मधूक वन और पहाड़ी से होकर कथा-मार्ग बताते हैं और तीनों को विदा करते हैं। यह जिला जटायु के आने से ठीक पहले समाप्त होता है।'),
  ('scene-jatayu-welcomes-panchavati', 'vulture-shape-stops-road', 'en', 'A huge shape stops the road', 'On the way to Panchavati, Rama and Lakshmana see an enormous vulture and first suspect another disguised attacker. The forest still teaches caution before recognition.'),
  ('scene-jatayu-welcomes-panchavati', 'vulture-shape-stops-road', 'hi', 'एक विशाल आकृति राह रोकती है', 'पंचवटी जाते हुए राम और लक्ष्मण एक विशाल गिद्ध को देखकर पहले उसे रूप बदले आक्रमणकारी समझते हैं। पहचान से पहले वन उन्हें सावधानी सिखाता है।'),
  ('scene-jatayu-welcomes-panchavati', 'jatayu-names-friendship', 'en', 'Jatayu names an old friendship', 'Jatayu speaks gently, recalls friendship with Dasharatha, and gives his lineage. A frightening unknown becomes someone connected to the family left behind.'),
  ('scene-jatayu-welcomes-panchavati', 'jatayu-names-friendship', 'hi', 'जटायु पुरानी मित्रता का नाम लेते हैं', 'जटायु कोमल स्वर में बोलते हैं, दशरथ से अपनी मित्रता याद करते हैं और अपना वंश बताते हैं। भयावह अजनबी पीछे छूटे परिवार से जुड़ा साथी बन जाता है।'),
  ('scene-jatayu-welcomes-panchavati', 'guardian-offers-watch', 'en', 'An elder offers to keep watch', 'Jatayu offers to protect Sita whenever the brothers are away. Rama embraces him and accepts the bond before the group continues together.'),
  ('scene-jatayu-welcomes-panchavati', 'guardian-offers-watch', 'hi', 'एक वृद्ध साथी पहरा देने का वचन देते हैं', 'जटायु कहते हैं कि भाइयों के दूर रहने पर वे सीता की रक्षा करेंगे। राम उन्हें गले लगाकर यह संबंध स्वीकार करते हैं और सब साथ आगे बढ़ते हैं।'),
  ('scene-jatayu-welcomes-panchavati', 'godavari-home-is-chosen', 'en', 'The Godavari gives the home its shape', 'At Panchavati, Rama and Lakshmana choose ground near water, flowering woods, animals, and open sightlines. The setting is selected as a lived place, not a blank backdrop.'),
  ('scene-jatayu-welcomes-panchavati', 'godavari-home-is-chosen', 'hi', 'गोदावरी घर को आकार देती है', 'पंचवटी में राम और लक्ष्मण जल, फूलों से भरे वन, पशुओं और खुली दृष्टि वाले स्थान को चुनते हैं। यह कोई खाली पृष्ठभूमि नहीं, जीने योग्य जगह है।'),
  ('scene-jatayu-welcomes-panchavati', 'lakshmana-builds-panchavati', 'en', 'Lakshmana builds; the three enter', 'Lakshmana gathers timber, earth, grass, and leaves to build the cottage. Rama praises his care, and the travellers enter Panchavati as a household.'),
  ('scene-jatayu-welcomes-panchavati', 'lakshmana-builds-panchavati', 'hi', 'लक्ष्मण बनाते हैं; तीनों प्रवेश करते हैं', 'लक्ष्मण लकड़ी, मिट्टी, घास और पत्तों से कुटिया बनाते हैं। राम उनके स्नेहपूर्ण श्रम की प्रशंसा करते हैं और तीनों पंचवटी में परिवार की तरह प्रवेश करते हैं।'),
  ('scene-jatayu-welcomes-panchavati', 'winter-morning-remembers-bharata', 'en', 'A winter morning remembers Bharata', 'As winter arrives, the brothers walk to the Godavari and Lakshmana speaks of Bharata waiting in hardship. Quiet Panchavati still remains connected to distant Nandigrama.'),
  ('scene-jatayu-welcomes-panchavati', 'winter-morning-remembers-bharata', 'hi', 'शीत की सुबह भरत को याद करती है', 'शीत आने पर भाई गोदावरी की ओर चलते हैं और लक्ष्मण कठिन जीवन जी रहे भरत को याद करते हैं। शांत पंचवटी दूर नंदिग्राम से जुड़ी रहती है।'),
  ('scene-surpanakha-breaks-quiet', 'surpanakha-sees-rama', 'en', 'Surpanakha enters the clearing', 'Surpanakha encounters Rama near the cottage and asks who these ascetic-looking armed travellers are. Rama introduces himself, Sita, and Lakshmana and explains the exile.'),
  ('scene-surpanakha-breaks-quiet', 'surpanakha-sees-rama', 'hi', 'शूर्पणखा खुले स्थान में आती हैं', 'शूर्पणखा कुटिया के पास राम से मिलती हैं और तपस्वी वेश में शस्त्रधारी यात्रियों का परिचय पूछती हैं। राम अपना, सीता और लक्ष्मण का परिचय देकर वनवास बताते हैं।'),
  ('scene-surpanakha-breaks-quiet', 'desire-turns-to-proposal', 'en', 'Desire becomes a direct proposal', 'She names her own power and family, declares desire for Rama, and dismisses Sita and Lakshmana as obstacles. The conversation is charged before it becomes dangerous.'),
  ('scene-surpanakha-breaks-quiet', 'desire-turns-to-proposal', 'hi', 'आकर्षण सीधा प्रस्ताव बनता है', 'वह अपनी शक्ति और परिवार का परिचय देकर राम के प्रति इच्छा व्यक्त करती हैं तथा सीता और लक्ष्मण को बाधा कहती हैं। संवाद हिंसक होने से पहले ही तनाव से भर जाता है।'),
  ('scene-surpanakha-breaks-quiet', 'jest-passes-between-brothers', 'en', 'A jest passes responsibility away', 'Rama points to his marriage and jokingly redirects Surpanakha toward Lakshmana; Lakshmana answers with another jest. The scene preserves the playfulness while making its escalating consequence visible.'),
  ('scene-surpanakha-breaks-quiet', 'jest-passes-between-brothers', 'hi', 'परिहास उत्तरदायित्व को आगे बढ़ाता है', 'राम अपने विवाह की बात कहकर परिहास में शूर्पणखा को लक्ष्मण की ओर भेजते हैं; लक्ष्मण भी परिहास में उत्तर देते हैं। दृश्य हास्य को रखते हुए उसके बढ़ते परिणाम को भी दिखाता है।'),
  ('scene-surpanakha-breaks-quiet', 'rivalry-targets-sita', 'en', 'Rivalry turns toward Sita', 'Humiliated and enraged, Surpanakha rushes at Sita. Rama stops treating the encounter as play and orders immediate protection.'),
  ('scene-surpanakha-breaks-quiet', 'rivalry-targets-sita', 'hi', 'प्रतिस्पर्धा सीता की ओर मुड़ती है', 'अपमानित और क्रोधित शूर्पणखा सीता पर झपटती हैं। राम अब इस भेंट को खेल नहीं मानते और तत्काल रक्षा का आदेश देते हैं।'),
  ('scene-surpanakha-breaks-quiet', 'injury-opens-janasthana', 'en', 'A violent injury opens the road to Janasthana', 'Lakshmana disfigures Surpanakha. Bleeding and furious, she leaves for Khara; Devam presents the violence as the selected narrative''s escalation, not as comic punishment or endorsed conduct.'),
  ('scene-surpanakha-breaks-quiet', 'injury-opens-janasthana', 'hi', 'हिंसक चोट जनस्थान की राह खोलती है', 'लक्ष्मण शूर्पणखा को घायल और विरूप कर देते हैं। रक्तस्राव और क्रोध में वह खर के पास जाती हैं; देवम इस हिंसा को चुनी कथा की बढ़ती घटना मानता है, हास्यपूर्ण दंड या समर्थित आचरण नहीं।'),
  ('scene-janasthana-falls', 'surpanakha-reaches-khara', 'en', 'Surpanakha demands an answer', 'Surpanakha reaches Khara, names Rama, Lakshmana, and Sita, and frames her injury as an attack demanding blood. Khara first sends fourteen fighters with her.'),
  ('scene-janasthana-falls', 'surpanakha-reaches-khara', 'hi', 'शूर्पणखा प्रतिकार माँगती हैं', 'शूर्पणखा खर के पास पहुँचकर राम, लक्ष्मण और सीता का नाम लेती हैं तथा अपनी चोट को प्रतिशोध माँगता आक्रमण बताती हैं। खर पहले चौदह योद्धा उनके साथ भेजता है।'),
  ('scene-janasthana-falls', 'first-force-does-not-return', 'en', 'The first force does not return', 'At Panchavati, Rama places Sita under Lakshmana''s protection and defeats the attacking group. Surpanakha returns to Khara with the failure, making retreat less likely.'),
  ('scene-janasthana-falls', 'first-force-does-not-return', 'hi', 'पहला दल वापस नहीं आता', 'पंचवटी में राम सीता को लक्ष्मण की सुरक्षा में रखकर आए दल को पराजित करते हैं। शूर्पणखा असफलता लेकर खर के पास लौटती हैं और पीछे हटने की संभावना घट जाती है।'),
  ('scene-janasthana-falls', 'khara-mobilizes-janasthana', 'en', 'Khara mobilizes Janasthana', 'Pressed by Surpanakha, Khara orders Dushana to mobilize the larger force. Omens gather along the march, while Rama reads the approaching danger and sends Sita and Lakshmana to shelter.'),
  ('scene-janasthana-falls', 'khara-mobilizes-janasthana', 'hi', 'खर जनस्थान को युद्ध में उतारता है', 'शूर्पणखा के दबाव में खर दूषण को बड़ी सेना तैयार करने का आदेश देता है। यात्रा में अपशकुन उभरते हैं; राम खतरा पहचानकर सीता और लक्ष्मण को आश्रय में भेजते हैं।'),
  ('scene-janasthana-falls', 'rama-holds-open-ground', 'en', 'Rama holds the open ground alone', 'The battle unfolds in waves around Rama. Dushana and Trishira fall, and Khara''s confidence narrows into a direct confrontation.'),
  ('scene-janasthana-falls', 'rama-holds-open-ground', 'hi', 'राम खुले मैदान में अकेले ठहरते हैं', 'राम के चारों ओर युद्ध लहरों में फैलता है। दूषण और त्रिशिरा गिरते हैं तथा खर का विश्वास सीधे द्वंद्व तक सिमट जाता है।'),
  ('scene-janasthana-falls', 'khara-falls-at-janasthana', 'en', 'Khara falls; Janasthana changes hands', 'Rama defeats Khara after their exchange of accusation, boast, and weapons. The selected epic describes a devastating victory; the interface keeps its consequence larger than spectacle.'),
  ('scene-janasthana-falls', 'khara-falls-at-janasthana', 'hi', 'खर गिरता है; जनस्थान बदल जाता है', 'आरोप, गर्वोक्ति और शस्त्रों के आदान-प्रदान के बाद राम खर को पराजित करते हैं। चुना महाकाव्य विनाशकारी विजय बताता है; दृश्य तमाशे से अधिक उसके परिणाम पर टिकता है।'),
  ('scene-janasthana-falls', 'akampana-carries-news', 'en', 'One report escapes toward Ravana', 'Akampana reaches Ravana and reports the destruction. Instead of recommending direct combat with Rama, he proposes making Sita the point of separation.'),
  ('scene-janasthana-falls', 'akampana-carries-news', 'hi', 'एक समाचार रावण की ओर बच निकलता है', 'अकम्पन रावण तक पहुँचकर विनाश का समाचार देता है। राम से सीधे युद्ध के स्थान पर वह सीता को अलगाव का केंद्र बनाने की योजना सुझाता है।'),
  ('scene-ravana-chooses-deception', 'first-warning-from-maricha', 'en', 'Maricha warns against the first plan', 'Ravana first approaches Maricha after Akampana''s report. Maricha recalls Rama''s power and persuades him to turn back—for the moment.'),
  ('scene-ravana-chooses-deception', 'first-warning-from-maricha', 'hi', 'मारीच पहली योजना के विरुद्ध चेताते हैं', 'अकम्पन के समाचार के बाद रावण पहली बार मारीच के पास जाता है। मारीच राम की शक्ति याद दिलाकर उसे कुछ समय के लिए लौटने पर विवश करते हैं।'),
  ('scene-ravana-chooses-deception', 'surpanakha-enters-lanka', 'en', 'Surpanakha carries Janasthana into court', 'Surpanakha reaches Ravana''s court, condemns his inattention, describes the defeat, and makes Sita''s beauty part of her argument for action.'),
  ('scene-ravana-chooses-deception', 'surpanakha-enters-lanka', 'hi', 'शूर्पणखा जनस्थान को राजसभा तक लाती हैं', 'शूर्पणखा रावण की सभा में पहुँचकर उसकी असावधानी को ललकारती हैं, हार का वर्णन करती हैं और सीता के सौंदर्य को कार्रवाई के तर्क में बदल देती हैं।'),
  ('scene-ravana-chooses-deception', 'ravana-asks-for-every-detail', 'en', 'Ravana asks who Rama and Sita are', 'Ravana questions Surpanakha about Rama''s appearance, weapons, exile, and companions. Her answer turns curiosity into fixation and revenge into acquisition.'),
  ('scene-ravana-chooses-deception', 'ravana-asks-for-every-detail', 'hi', 'रावण राम और सीता का पूरा परिचय पूछता है', 'रावण शूर्पणखा से राम के रूप, शस्त्र, वनवास और साथियों के बारे में पूछता है। उत्तर जिज्ञासा को आसक्ति और प्रतिशोध को अधिकार की इच्छा में बदल देता है।'),
  ('scene-ravana-chooses-deception', 'maricha-remembers-rama', 'en', 'Maricha answers with remembered fear', 'When Ravana returns, Maricha recounts earlier encounters with Rama and describes a life ruled by the fear of seeing Rama everywhere. His counsel is specific, personal, and unwelcome.'),
  ('scene-ravana-chooses-deception', 'maricha-remembers-rama', 'hi', 'मारीच स्मृति के भय से उत्तर देते हैं', 'रावण के लौटने पर मारीच राम से पुरानी मुठभेड़ों और हर ओर राम दिखाई देने वाले भय का वर्णन करते हैं। उनकी सलाह निजी, स्पष्ट और अप्रिय है।'),
  ('scene-ravana-chooses-deception', 'warning-becomes-coercion', 'en', 'Warning becomes coercion', 'Ravana rejects the warning, threatens Maricha, and dictates the golden-deer role. Maricha chooses the danger he believes will at least end at Rama''s hand.'),
  ('scene-ravana-chooses-deception', 'warning-becomes-coercion', 'hi', 'चेतावनी दबाव में बदलती है', 'रावण चेतावनी ठुकराकर मारीच को धमकाता और स्वर्ण-मृग की भूमिका तय करता है। मारीच उस खतरे को चुनता है जिसका अंत कम से कम राम के हाथों होने की वह आशा करता है।'),
  ('scene-golden-deer-separates-house', 'impossible-deer-enters-light', 'en', 'An impossible deer enters the clearing', 'Maricha appears near the cottage as a deer marked with gold, silver, and jewel-like colour. Sita calls Rama and Lakshmana to see what has interrupted the ordinary forest.'),
  ('scene-golden-deer-separates-house', 'impossible-deer-enters-light', 'hi', 'एक असंभव मृग खुले स्थान में आता है', 'मारीच सोने, चाँदी और रत्न-जैसे रंगों से अंकित मृग बनकर कुटिया के पास आते हैं। सीता राम और लक्ष्मण को इस असामान्य वन-दृश्य को देखने बुलाती हैं।'),
  ('scene-golden-deer-separates-house', 'sita-asks-for-wonder', 'en', 'Sita asks to keep the wonder near', 'Sita asks Rama to capture the deer if possible, imagining it alive at their forest home or remembered later in Ayodhya. The request connects present delight with a future return.'),
  ('scene-golden-deer-separates-house', 'sita-asks-for-wonder', 'hi', 'सीता उस आश्चर्य को पास रखने की इच्छा कहती हैं', 'सीता राम से संभव हो तो मृग को पकड़ने को कहती हैं—वन-घर में जीवित साथी की तरह या अयोध्या लौटने पर स्मृति की तरह। इच्छा वर्तमान आनंद को भविष्य की वापसी से जोड़ती है।'),
  ('scene-golden-deer-separates-house', 'lakshmana-names-deception', 'en', 'Lakshmana suspects the image', 'Lakshmana says no natural deer bears such colours and suspects Maricha. Rama accepts the danger but decides that either capture or ending the threat justifies pursuit.'),
  ('scene-golden-deer-separates-house', 'lakshmana-names-deception', 'hi', 'लक्ष्मण दृश्य पर संदेह करते हैं', 'लक्ष्मण कहते हैं कि स्वाभाविक मृग के ऐसे रंग नहीं होते और मारीच पर संदेह करते हैं। राम खतरा मानते हुए भी उसे पकड़ने या संकट समाप्त करने के लिए पीछा करने का निर्णय लेते हैं।'),
  ('scene-golden-deer-separates-house', 'rama-follows-changing-distance', 'en', 'The chase keeps changing distance', 'The deer moves close, vanishes, reappears, and draws Rama far from Panchavati. When the deception can no longer be contained, Rama releases the fatal arrow.'),
  ('scene-golden-deer-separates-house', 'rama-follows-changing-distance', 'hi', 'पीछा लगातार दूरी बदलता है', 'मृग पास आता, गायब होता और फिर दिखकर राम को पंचवटी से दूर ले जाता है। जब छल को रोका नहीं जा सकता, राम घातक बाण छोड़ते हैं।'),
  ('scene-golden-deer-separates-house', 'maricha-borrows-rama-voice', 'en', 'Maricha sends one last weapon back', 'Dying, Maricha imitates Rama''s voice and cries out for Sita and Lakshmana. Rama immediately fears what the sound may do at the distant cottage.'),
  ('scene-golden-deer-separates-house', 'maricha-borrows-rama-voice', 'hi', 'मारीच अंतिम अस्त्र वापस भेजते हैं', 'मरते समय मारीच राम की आवाज़ में सीता और लक्ष्मण को पुकारते हैं। राम तुरंत समझते हैं कि दूर कुटिया पर यह ध्वनि क्या कर सकती है।'),
  ('scene-mendicant-at-empty-cottage', 'sita-hears-borrowed-cry', 'en', 'Sita hears Rama''s voice in danger', 'The imitated cry reaches Panchavati. Sita believes Rama is in danger and urges Lakshmana to go, while Lakshmana insists no ordinary foe could overcome him.'),
  ('scene-mendicant-at-empty-cottage', 'sita-hears-borrowed-cry', 'hi', 'सीता संकट में राम की आवाज़ सुनती हैं', 'नकली पुकार पंचवटी पहुँचती है। सीता मानती हैं कि राम संकट में हैं और लक्ष्मण को जाने को कहती हैं, जबकि लक्ष्मण कहते हैं कि कोई साधारण शत्रु राम को हरा नहीं सकता।'),
  ('scene-mendicant-at-empty-cottage', 'fear-wounds-the-conversation', 'en', 'Fear wounds the conversation', 'As Lakshmana remains, Sita speaks harsh accusations born from panic. Lakshmana rejects them, warns of ominous signs, and finally leaves to find Rama.'),
  ('scene-mendicant-at-empty-cottage', 'fear-wounds-the-conversation', 'hi', 'भय संवाद को घायल करता है', 'लक्ष्मण के रुकने पर घबराहट में सीता कठोर आरोप कहती हैं। लक्ष्मण उन्हें अस्वीकार कर अपशकुन की चेतावनी देते हैं और अंततः राम को खोजने निकलते हैं।'),
  ('scene-mendicant-at-empty-cottage', 'ravana-enters-as-guest', 'en', 'Ravana enters under the sign of a guest', 'Ravana approaches in the appearance of a mendicant, with dress and objects that invoke hospitality. The forest and cottage are described as recoiling even before Sita knows his identity.'),
  ('scene-mendicant-at-empty-cottage', 'ravana-enters-as-guest', 'hi', 'रावण अतिथि के रूप में प्रवेश करता है', 'रावण भिक्षु के रूप, वस्त्र और चिह्नों के साथ आते हैं जो आतिथ्य की अपेक्षा जगाते हैं। सीता के पहचानने से पहले ही वन और कुटिया मानो पीछे हटते दिखाई देते हैं।'),
  ('scene-mendicant-at-empty-cottage', 'sita-offers-water-and-name', 'en', 'Sita offers hospitality and names herself', 'Sita offers water and food and, when questioned, tells her identity, marriage, and exile. Her account is spoken before the guest-mask falls.'),
  ('scene-mendicant-at-empty-cottage', 'sita-offers-water-and-name', 'hi', 'सीता आतिथ्य देती और अपना परिचय बताती हैं', 'सीता जल और भोजन देती हैं तथा पूछे जाने पर अपना परिचय, विवाह और वनवास बताती हैं। अतिथि का मुखौटा उतरने से पहले उनकी कथा उनके अपने शब्दों में आती है।'),
  ('scene-mendicant-at-empty-cottage', 'waiting-becomes-recognition', 'en', 'Waiting becomes recognition', 'Sita wonders why Rama and Lakshmana have not returned. Ravana''s questions and praise become increasingly possessive, and the protected logic of guest and host begins to collapse.'),
  ('scene-mendicant-at-empty-cottage', 'waiting-becomes-recognition', 'hi', 'प्रतीक्षा पहचान में बदलती है', 'सीता सोचती हैं कि राम और लक्ष्मण अभी तक क्यों नहीं लौटे। रावण के प्रश्न और प्रशंसा अधिकार जताने लगते हैं और अतिथि-गृहस्थ का सुरक्षित संबंध टूटने लगता है।'),
  ('scene-sita-carried-south', 'sita-names-rama-first', 'en', 'Sita answers by naming Rama', 'Sita describes Rama''s character, strength, and commitment before asking the visitor''s identity. Her speech establishes the relationship Ravana is trying to erase.'),
  ('scene-sita-carried-south', 'sita-names-rama-first', 'hi', 'सीता पहले राम का नाम लेकर उत्तर देती हैं', 'सीता आगंतुक की पहचान पूछने से पहले राम के चरित्र, शक्ति और निष्ठा का वर्णन करती हैं। उनकी वाणी उस संबंध को स्थापित करती है जिसे रावण मिटाना चाहता है।'),
  ('scene-sita-carried-south', 'ravana-reveals-name-and-power', 'en', 'The guest reveals Ravana', 'Ravana names himself, boasts of Lanka and power, and proposes that Sita leave with him. The mendicant guise gives way to the figure behind the threat.'),
  ('scene-sita-carried-south', 'ravana-reveals-name-and-power', 'hi', 'अतिथि अपना रावण रूप प्रकट करता है', 'रावण अपना नाम, लंका और शक्ति का गर्व बताते हुए सीता को साथ चलने का प्रस्ताव देता है। भिक्षु का वेश हटकर संकट का वास्तविक रूप सामने आता है।'),
  ('scene-sita-carried-south', 'sita-refuses-the-claim', 'en', 'Sita refuses possession', 'Sita rejects Ravana''s threats and comparisons, warns that taking her is impossible to separate from confronting Rama, and refuses to convert fear into consent.'),
  ('scene-sita-carried-south', 'sita-refuses-the-claim', 'hi', 'सीता अधिकार के दावे को ठुकराती हैं', 'सीता रावण की धमकियों और तुलना को अस्वीकार करती हैं, कहती हैं कि उनका हरण राम से सामना किए बिना संभव नहीं और भय को सहमति में बदलने से इंकार करती हैं।'),
  ('scene-sita-carried-south', 'forest-is-called-to-witness', 'en', 'The forest is called to witness', 'As Ravana seizes and lifts her away, Sita cries to trees, river, mountain, birds, and animals to carry news to Rama. The landscape becomes an active network of witnesses.'),
  ('scene-sita-carried-south', 'forest-is-called-to-witness', 'hi', 'वन को साक्षी पुकारा जाता है', 'रावण के उठाकर ले जाते समय सीता वृक्षों, नदी, पर्वत, पक्षियों और पशुओं से राम तक समाचार पहुँचाने की पुकार करती हैं। भू-दृश्य साक्षियों का सक्रिय जाल बन जाता है।'),
  ('scene-sita-carried-south', 'panchavati-falls-away', 'en', 'The home falls away below', 'Panchavati recedes as Sita continues to resist, reason, threaten, and call for help. The story does not reduce the scene to silent removal.'),
  ('scene-sita-carried-south', 'panchavati-falls-away', 'hi', 'घर नीचे छूट जाता है', 'पंचवटी नीचे दूर होती जाती है और सीता विरोध, तर्क, चेतावनी तथा सहायता की पुकार जारी रखती हैं। कथा इस दृश्य को मौन ले जाए जाने तक सीमित नहीं करती।'),
  ('scene-jatayu-rises-sky-road', 'jatayu-wakes-to-sitas-call', 'en', 'Jatayu wakes to Sita''s call', 'Hearing Sita, Jatayu sees Ravana carrying her away. The guardian''s earlier promise returns at the moment it is most difficult to keep.'),
  ('scene-jatayu-rises-sky-road', 'jatayu-wakes-to-sitas-call', 'hi', 'जटायु सीता की पुकार से जागते हैं', 'सीता की पुकार सुनकर जटायु रावण को उन्हें ले जाते देखते हैं। पहले दिया रक्षा-वचन उसी क्षण लौटता है जब उसे निभाना सबसे कठिन है।'),
  ('scene-jatayu-rises-sky-road', 'jatayu-challenges-ravana', 'en', 'An elder challenges a king', 'Jatayu invokes age, friendship, kingship, and duty, urging Ravana to release Sita. He does not mistake unequal strength for permission to remain still.'),
  ('scene-jatayu-rises-sky-road', 'jatayu-challenges-ravana', 'hi', 'एक वृद्ध पक्षी राजा को चुनौती देता है', 'जटायु आयु, मित्रता, राजधर्म और कर्तव्य की बात करके रावण से सीता को छोड़ने को कहते हैं। असमान शक्ति उनके लिए निष्क्रिय रहने की अनुमति नहीं बनती।'),
  ('scene-jatayu-rises-sky-road', 'wings-break-the-flight', 'en', 'Wings break the flight''s certainty', 'Jatayu attacks the chariot, weapons, and Ravana himself, disrupting the abduction and bringing the struggle close to the ground. Sita watches resistance appear where there had been no defender.'),
  ('scene-jatayu-rises-sky-road', 'wings-break-the-flight', 'hi', 'पंख उड़ान की निश्चितता तोड़ते हैं', 'जटायु रथ, शस्त्र और स्वयं रावण पर आक्रमण कर हरण की गति तोड़ते और संघर्ष को धरती के पास ले आते हैं। जहाँ कोई रक्षक नहीं था, वहाँ सीता प्रतिरोध उभरते देखती हैं।'),
  ('scene-jatayu-rises-sky-road', 'jatayu-falls-after-resistance', 'en', 'Jatayu falls after resistance', 'Ravana cuts down the aged defender and resumes the southward journey. Sita embraces the fallen ally in grief before being forced onward.'),
  ('scene-jatayu-rises-sky-road', 'jatayu-falls-after-resistance', 'hi', 'प्रतिरोध के बाद जटायु गिरते हैं', 'रावण वृद्ध रक्षक को गिराकर दक्षिण की यात्रा फिर शुरू करता है। आगे ले जाए जाने से पहले सीता शोक में घायल साथी को गले लगाती हैं।'),
  ('scene-jatayu-rises-sky-road', 'sita-keeps-speaking-south', 'en', 'Sita keeps speaking to the world', 'Carried onward, Sita continues to condemn Ravana and call for Rama and Lakshmana. Her voice keeps the route populated by witnesses rather than empty distance.'),
  ('scene-jatayu-rises-sky-road', 'sita-keeps-speaking-south', 'hi', 'सीता संसार से बोलती रहती हैं', 'आगे ले जाए जाते हुए सीता रावण की निंदा और राम-लक्ष्मण को पुकारना जारी रखती हैं। उनकी आवाज़ मार्ग को खाली दूरी नहीं, साक्षियों से भरा संसार बनाए रखती है।'),
  ('scene-jatayu-rises-sky-road', 'ornaments-become-trail', 'en', 'Ornaments become a trail', 'Seeing five vanaras below, Sita drops cloth and ornaments in the hope that they can carry news. The district ends with evidence falling back into the world, not with the route erased.'),
  ('scene-jatayu-rises-sky-road', 'ornaments-become-trail', 'hi', 'आभूषण खोज-निशान बनते हैं', 'नीचे पाँच वानरों को देखकर सीता वस्त्र और आभूषण इस आशा से गिराती हैं कि वे समाचार पहुँचा सकें। जिला रास्ता मिटने पर नहीं, संसार में खोज-साक्ष्य गिरने पर समाप्त होता है।'),
  ('scene-sita-refuses-ravana-in-lanka', 'ravana-displays-lanka', 'en', 'Ravana turns Lanka into a sales pitch', 'Ravana brings the grieving Sita through halls filled with gold, vehicles, attendants, and guarded abundance. He presents the city and his power as reasons she should choose him, treating material scale as if it could rewrite the violence that brought her there.'),
  ('scene-sita-refuses-ravana-in-lanka', 'ravana-displays-lanka', 'hi', 'रावण लंका को प्रलोभन की तरह दिखाता है', 'रावण शोकग्रस्त सीता को सोने, वाहनों, सेवकों और पहरे से भरे महलों में ले जाता है। वह नगर और अपनी शक्ति को उसे चुनने का कारण बनाता है, मानो भौतिक वैभव उस हिंसा को बदल सकता हो जिसके द्वारा वह यहाँ लाई गई।'),
  ('scene-sita-refuses-ravana-in-lanka', 'demand-becomes-deadline', 'en', 'Possession is disguised as choice', 'When persuasion fails, Ravana demands that Sita become his principal queen and gives her a deadline, after which death is threatened. The sequence exposes the false choice clearly: an answer extracted under captivity and threat would not become consent merely because time was allowed.'),
  ('scene-sita-refuses-ravana-in-lanka', 'demand-becomes-deadline', 'hi', 'अधिकार को चुनाव का रूप दिया जाता है', 'प्रलोभन असफल होने पर रावण सीता से प्रधान रानी बनने की माँग करता है और समय-सीमा देकर उसके बाद मृत्यु की धमकी देता है। दृश्य झूठा चुनाव स्पष्ट करता है—बंदीपन और भय में लिया उत्तर केवल समय मिलने से सहमति नहीं बन जाता।'),
  ('scene-sita-refuses-ravana-in-lanka', 'grass-marks-the-boundary', 'en', 'A blade of grass holds the distance', 'Sita places a blade of grass between herself and Ravana before answering. She names Dasharatha, Rama, and the relationship Ravana is trying to erase, then rejects his boasts and warns that abduction has set his destruction in motion. Her speech restores moral distance inside forced proximity.'),
  ('scene-sita-refuses-ravana-in-lanka', 'grass-marks-the-boundary', 'hi', 'घास का तिनका दूरी की सीमा बनता है', 'सीता उत्तर से पहले अपने और रावण के बीच घास का तिनका रखती हैं। वे दशरथ, राम और उस संबंध का नाम लेती हैं जिसे रावण मिटाना चाहता है, फिर उसके गर्व को ठुकराकर कहती हैं कि हरण ने उसके विनाश की राह खोल दी है। जबरन निकटता में उनकी वाणी नैतिक दूरी लौटाती है।'),
  ('scene-sita-refuses-ravana-in-lanka', 'rakshasis-surround-not-convince', 'en', 'The guards can surround her, not change her mind', 'Ravana orders the Rakshasis to use persuasion and intimidation, then leaves Sita watched and exhausted. Their threats intensify her fear and grief until she faints, but the scene does not confuse physical collapse with surrender. Her refusal remains the last decision she spoke.'),
  ('scene-sita-refuses-ravana-in-lanka', 'rakshasis-surround-not-convince', 'hi', 'पहरेदार घेर सकते हैं, मन नहीं बदल सकते', 'रावण राक्षसियों को समझाने और डराने का आदेश देकर सीता को घिरी तथा थकी छोड़ जाता है। धमकियाँ भय और शोक बढ़ाती हैं और वे मूर्छित हो जाती हैं, पर शारीरिक टूटन को समर्पण नहीं माना जाता। उनका अंतिम स्पष्ट निर्णय अस्वीकार ही रहता है।'),
  ('scene-indra-brings-sita-strength', 'brahma-sees-the-long-captivity', 'en', 'The gods recognise endurance will require food', 'As Rama hurries back through the forest, the story cuts to a practical danger in Lanka: grief, refusal, and guarded isolation may leave Sita without food. Brahma asks Indra to sustain her so that the coming search is not defeated by starvation before it can begin.'),
  ('scene-indra-brings-sita-strength', 'brahma-sees-the-long-captivity', 'hi', 'देवता समझते हैं कि प्रतीक्षा के लिए आहार चाहिए', 'राम वन में लौट रहे हैं और कथा लंका के व्यावहारिक संकट पर जाती है—शोक, अस्वीकार और पहरे के बीच सीता भोजन से वंचित हो सकती हैं। ब्रह्मा इंद्र से उन्हें सँभालने कहते हैं, ताकि खोज शुरू होने से पहले ही भूख उसे विफल न कर दे।'),
  ('scene-indra-brings-sita-strength', 'sleep-opens-the-guarded-path', 'en', 'The guards sleep; Indra enters quietly', 'Indra enters with Sleep, who overcomes the Rakshasi guards without a battle. The intervention is deliberately narrow: it creates a private interval rather than destroying Lanka or ending the captivity. Sita still has to judge whether the unfamiliar visitor is another deception.'),
  ('scene-indra-brings-sita-strength', 'sleep-opens-the-guarded-path', 'hi', 'पहरेदार सोते हैं; इंद्र शांतिपूर्वक प्रवेश करते हैं', 'इंद्र निद्रा के साथ आते हैं और बिना युद्ध राक्षसी पहरेदारों को सुला देते हैं। हस्तक्षेप जानबूझकर सीमित है—वह लंका नष्ट या बंदी जीवन समाप्त नहीं करता, केवल एक निजी क्षण बनाता है। सीता को अब भी तय करना है कि अनजान आगंतुक नया छल तो नहीं।'),
  ('scene-indra-brings-sita-strength', 'sita-demands-proof', 'en', 'Sita does not accept help without testing it', 'Indra identifies himself and offers celestial food, but Sita asks for proof before trusting him. He reveals signs she can recognise, and only then does she accept. Captivity has not removed her judgment; caution is part of survival when the enemy has already used a holy disguise.'),
  ('scene-indra-brings-sita-strength', 'sita-demands-proof', 'hi', 'सीता प्रमाण के बिना सहायता स्वीकार नहीं करतीं', 'इंद्र अपना परिचय देकर दिव्य आहार देते हैं, पर सीता विश्वास से पहले प्रमाण माँगती हैं। पहचान योग्य चिह्न देखने के बाद ही स्वीकार करती हैं। बंदीपन ने उनका विवेक नहीं छीना; शत्रु पहले पवित्र वेश में छल कर चुका है, इसलिए सावधानी जीवित रहने का हिस्सा है।'),
  ('scene-indra-brings-sita-strength', 'food-becomes-a-promise-to-endure', 'en', 'The meal preserves a future meeting', 'Sita dedicates the food in thought to Rama and Lakshmana, eats, and feels hunger and thirst recede. Nothing about her location changes, but time does: she now has bodily strength to endure while the brothers discover what happened and build a route toward her.'),
  ('scene-indra-brings-sita-strength', 'food-becomes-a-promise-to-endure', 'hi', 'आहार भविष्य के मिलन को बचाए रखता है', 'सीता मन में आहार राम और लक्ष्मण को समर्पित कर खाती हैं; भूख-प्यास शांत होती है। उनका स्थान नहीं बदलता, पर समय का अर्थ बदलता है—अब उनमें तब तक टिकने की शारीरिक शक्ति है जब तक भाई घटना समझकर उनकी ओर राह बनाएँ।'),
  ('scene-brothers-return-to-empty-cottage', 'omens-follow-rama-home', 'en', 'Rama knows the cry may have travelled ahead', 'After killing Maricha, Rama runs toward Panchavati while jackals cry, his body trembles, and his mind reconstructs the trap. Maricha used Rama''s voice to call Sita and Lakshmana; the dying deception may have done more damage at the cottage than the golden form did in the forest.'),
  ('scene-brothers-return-to-empty-cottage', 'omens-follow-rama-home', 'hi', 'राम जानते हैं कि पुकार उनसे पहले पहुँच गई होगी', 'मारीच को मारकर राम पंचवटी की ओर दौड़ते हैं; सियार बोलते, शरीर काँपता और मन जाल को जोड़ता है। मारीच ने राम की आवाज़ में सीता-लक्ष्मण को पुकारा था—मरते समय का छल वन के स्वर्ण-रूप से अधिक हानि कुटिया में कर चुका हो सकता है।'),
  ('scene-brothers-return-to-empty-cottage', 'lakshmana-appears-without-sita', 'en', 'One figure on the road confirms the fear', 'Rama sees Lakshmana approaching alone and immediately asks where Sita is. Fear erupts as blame: he demands why the entrusted protector left her. Lakshmana explains that he resisted the false cry until Sita''s panic and accusations made remaining at the cottage impossible.'),
  ('scene-brothers-return-to-empty-cottage', 'lakshmana-appears-without-sita', 'hi', 'राह पर अकेले लक्ष्मण भय की पुष्टि करते हैं', 'राम लक्ष्मण को अकेले आते देखकर तुरंत सीता के बारे में पूछते हैं। भय दोष में फूटता है—वे पूछते हैं कि सौंपे गए रक्षक ने उन्हें क्यों छोड़ा। लक्ष्मण बताते हैं कि नकली पुकार का विरोध किया, पर सीता की घबराहट और आरोपों के बाद कुटिया में रुकना असंभव हो गया।'),
  ('scene-brothers-return-to-empty-cottage', 'explanation-does-not-slow-the-run', 'en', 'Understanding the trick does not reveal Sita''s location', 'Lakshmana recounts the painful conversation, and Rama confirms the cry came from Maricha. Both can now explain how the household was separated, but explanation is not recovery. They run together toward the cottage, carrying guilt and fear without pausing to settle who suffered the greater wound.'),
  ('scene-brothers-return-to-empty-cottage', 'explanation-does-not-slow-the-run', 'hi', 'छल समझने से सीता का स्थान नहीं मिलता', 'लक्ष्मण कठिन संवाद बताते हैं और राम पुष्टि करते हैं कि पुकार मारीच की थी। दोनों समझ जाते हैं कि परिवार कैसे अलग हुआ, पर कारण जानना खोज पूरी नहीं करता। वे दोष और भय साथ लेकर कुटिया की ओर दौड़ते हैं; किसे अधिक चोट लगी, इसका निर्णय करने नहीं रुकते।'),
  ('scene-brothers-return-to-empty-cottage', 'home-is-empty-but-not-neutral', 'en', 'The empty cottage still holds Sita''s absence', 'They enter Panchavati and find no Sita. Disordered seats, fading flowers, silent animals, and remembered play spaces make the home feel actively bereaved. Rama searches each familiar place and calls her name, first hoping she may be hiding, then recognising that ordinary absence cannot explain the scene.'),
  ('scene-brothers-return-to-empty-cottage', 'home-is-empty-but-not-neutral', 'hi', 'खाली कुटिया में सीता की अनुपस्थिति भरी है', 'वे पंचवटी पहुँचते हैं और सीता नहीं मिलतीं। बिखरे आसन, मुरझाए फूल, मौन पशु और खेल के परिचित स्थान घर को शोकग्रस्त बनाते हैं। राम हर जानी जगह खोजकर उनका नाम पुकारते हैं—पहले सोचते हैं वे छिपी होंगी, फिर मानते हैं कि साधारण अनुपस्थिति इस दृश्य को नहीं समझाती।'),
  ('scene-grief-searches-everywhere', 'familiar-places-become-questions', 'en', 'Every place where Sita lived becomes a question', 'Rama moves through groves, river paths, flower sites, and the cottage, repeatedly imagining Sita just beyond sight. Memory overlays the present so strongly that he speaks to absent gestures and laughter. Lakshmana stays close, but reassurance cannot replace evidence.'),
  ('scene-grief-searches-everywhere', 'familiar-places-become-questions', 'hi', 'सीता से जुड़ी हर जगह प्रश्न बन जाती है', 'राम उपवन, नदी-पथ, फूलों की जगह और कुटिया में घूमते हुए बार-बार सीता को दृष्टि के पार कल्पना करते हैं। स्मृति वर्तमान पर इतनी गहरी चढ़ती है कि वे अनुपस्थित हँसी और संकेतों से बोलते हैं। लक्ष्मण साथ रहते हैं, पर सांत्वना प्रमाण का स्थान नहीं ले सकती।'),
  ('scene-grief-searches-everywhere', 'landscape-is-asked-to-witness', 'en', 'Trees, deer, river, and mountain are questioned', 'The brothers question animals, plants, the Godavari, and the mountain as witnesses. Some movements and tracks suggest a southward disturbance, but no voice gives a complete answer. The same landscape Sita called during abduction now becomes the network Rama is desperately learning to read.'),
  ('scene-grief-searches-everywhere', 'landscape-is-asked-to-witness', 'hi', 'वृक्ष, मृग, नदी और पर्वत से पूछा जाता है', 'भाई पशु, वनस्पति, गोदावरी और पर्वत से साक्षी की तरह पूछते हैं। कुछ गति और निशान दक्षिण की हलचल बताते हैं, पर कोई पूरा उत्तर नहीं देता। हरण के समय सीता ने जिस भू-दृश्य को पुकारा था, वही अब वह जाल है जिसे राम पढ़ना सीख रहे हैं।'),
  ('scene-grief-searches-everywhere', 'grief-turns-against-self-and-world', 'en', 'Loss becomes self-blame, then indiscriminate rage', 'Rama connects Sita''s disappearance to exile, Dasharatha''s death, lost kingdom, and a life he now calls cursed. When nothing answers, grief changes direction: he strings his bow and threatens gods, worlds, animals, mountains, and seas unless Sita is returned. The story shows the danger rather than endorsing it.'),
  ('scene-grief-searches-everywhere', 'grief-turns-against-self-and-world', 'hi', 'हानि पहले आत्म-दोष, फिर अंधे क्रोध में बदलती है', 'राम सीता के गायब होने को वनवास, दशरथ की मृत्यु, खोए राज्य और अपने कथित अभिशप्त जीवन से जोड़ते हैं। उत्तर न मिलने पर शोक दिशा बदलता है—वे धनुष चढ़ाकर सीता न लौटने पर देव, लोक, पशु, पर्वत और समुद्र नष्ट करने की धमकी देते हैं। कथा खतरा दिखाती है, समर्थन नहीं।'),
  ('scene-grief-searches-everywhere', 'lakshmana-stands-inside-the-storm', 'en', 'Lakshmana does not abandon Rama to the rage', 'Lakshmana approaches with folded hands but speaks directly: Rama''s gentleness and concern for living beings cannot be discarded because one hidden enemy committed a crime. He does not minimise Sita''s loss. He separates the urgency of rescue from the fantasy that destroying everything would repair it.'),
  ('scene-grief-searches-everywhere', 'lakshmana-stands-inside-the-storm', 'hi', 'लक्ष्मण राम को क्रोध में अकेला नहीं छोड़ते', 'लक्ष्मण हाथ जोड़कर पास आते हैं, पर स्पष्ट कहते हैं—एक छिपे शत्रु के अपराध के कारण राम की करुणा और प्राणियों की चिंता नहीं छोड़ी जा सकती। वे सीता की हानि को छोटा नहीं करते; बचाव की तात्कालिकता को इस भ्रम से अलग करते हैं कि सब नष्ट करने से वह ठीक होगी।'),
  ('scene-lakshmana-turns-rage-into-search', 'one-crime-does-not-convict-all', 'en', 'One hidden offender does not make the world guilty', 'Lakshmana tells Rama that the scattered signs point to one violent encounter, not a conspiracy by every being. Punishing the entire world before identifying the offender would repeat injustice at a larger scale. Sita needs a rescuer capable of distinction, not a grief-stricken destroyer.'),
  ('scene-lakshmana-turns-rage-into-search', 'one-crime-does-not-convict-all', 'hi', 'एक छिपा अपराधी पूरे संसार को दोषी नहीं बनाता', 'लक्ष्मण कहते हैं कि बिखरे संकेत एक हिंसक संघर्ष बताते हैं, हर प्राणी की साजिश नहीं। अपराधी पहचानने से पहले पूरे संसार को दंड देना अन्याय को बड़े स्तर पर दोहराना होगा। सीता को भेद कर सकने वाला रक्षक चाहिए, शोक में डूबा विनाशक नहीं।'),
  ('scene-lakshmana-turns-rage-into-search', 'calamity-is-not-personal-proof', 'en', 'Suffering is real without proving cosmic persecution', 'He recalls that even powerful people meet calamity and that Dasharatha also died under unbearable separation. This is not a demand for passive acceptance. It is a warning against treating pain as evidence that every law, god, creature, and place has become Rama''s deliberate enemy.'),
  ('scene-lakshmana-turns-rage-into-search', 'calamity-is-not-personal-proof', 'hi', 'दुःख वास्तविक है, पर ब्रह्मांडीय षड्यंत्र का प्रमाण नहीं', 'वे याद दिलाते हैं कि शक्तिशाली लोग भी विपत्ति झेलते हैं और दशरथ भी असह्य वियोग में मरे। यह निष्क्रिय बैठने की माँग नहीं; चेतावनी है कि पीड़ा को इस प्रमाण में न बदला जाए कि हर नियम, देव, जीव और स्थान राम का जानबूझकर शत्रु है।'),
  ('scene-lakshmana-turns-rage-into-search', 'search-before-escalation', 'en', 'Caves, rivers, mountains, and strongholds come first', 'Lakshmana proposes a concrete sweep of Janasthana: caves, rock clefts, rivers, mountains, forest strongholds, and paths used by shape-changing attackers. Allies can be asked, signs compared, and the enemy named. Force remains available, but only after inquiry and diplomacy fail.'),
  ('scene-lakshmana-turns-rage-into-search', 'search-before-escalation', 'hi', 'पहले गुफाएँ, नदियाँ, पर्वत और दुर्ग खोजे जाएँगे', 'लक्ष्मण जनस्थान की ठोस खोज रखते हैं—गुफाएँ, चट्टानी दरारें, नदियाँ, पर्वत, वन-दुर्ग और रूप बदलने वाले आक्रमणकारियों के पथ। साथियों से पूछकर संकेत मिलाए और शत्रु का नाम जाना जाए। शक्ति उपलब्ध रहेगी, पर खोज और संवाद विफल होने के बाद।'),
  ('scene-lakshmana-turns-rage-into-search', 'rama-asks-what-next', 'en', 'Rama lowers the threat and asks for the next step', 'Rama accepts the reasoning, lets the world-destroying threat subside, and asks where they should go and what they should do. The change is not emotional recovery; grief remains intense. It is the return of shared judgment, which allows the search to notice physical evidence on the road ahead.'),
  ('scene-lakshmana-turns-rage-into-search', 'rama-asks-what-next', 'hi', 'राम धमकी छोड़कर अगला कदम पूछते हैं', 'राम तर्क स्वीकार कर विश्व-विनाश की धमकी शांत करते और पूछते हैं कि कहाँ जाएँ, क्या करें। यह भावनात्मक रूप से ठीक हो जाना नहीं—शोक अब भी तीव्र है। पर साझा विवेक लौटता है, इसलिए आगे की राह पर भौतिक प्रमाण दिखाई दे सकते हैं।'),
  ('scene-jatayu-gives-last-testimony', 'wreckage-becomes-readable', 'en', 'Flowers, blood, armour, and broken weapons form a trail', 'Searching south, the brothers find scattered flowers Sita had worn, enormous footprints, broken armour, a shattered chariot, weapons, and signs of violent resistance. Rama first fears rival abductors fought over her, but the evidence increasingly points toward one aerial struggle.'),
  ('scene-jatayu-gives-last-testimony', 'wreckage-becomes-readable', 'hi', 'फूल, रक्त, कवच और टूटे शस्त्र राह बनाते हैं', 'दक्षिण खोजते हुए भाई सीता के पहने बिखरे फूल, विशाल पदचिह्न, टूटा कवच, चकनाचूर रथ, शस्त्र और संघर्ष के निशान पाते हैं। राम पहले सोचते हैं कई अपहरणकर्ता लड़े होंगे, पर प्रमाण धीरे-धीरे एक आकाशीय युद्ध की ओर इशारा करते हैं।'),
  ('scene-jatayu-gives-last-testimony', 'fallen-jatayu-is-misread', 'en', 'Grief nearly mistakes the defender for the attacker', 'They find Jatayu bloodied, wingless, and barely alive. In the first instant Rama raises his bow, fearing the huge bird devoured Sita. Jatayu uses his failing voice to stop the mistake and says Ravana carried her away while he fought to prevent it.'),
  ('scene-jatayu-gives-last-testimony', 'fallen-jatayu-is-misread', 'hi', 'शोक रक्षक को आक्रमणकारी समझने लगता है', 'वे जटायु को रक्तरंजित, कटे पंख और अंतिम साँसों में पाते हैं। पहले क्षण राम धनुष उठाते हैं, मानते हैं विशाल पक्षी ने सीता को खाया होगा। जटायु क्षीण आवाज़ से भूल रोककर बताते हैं कि रावण उन्हें ले गया और उन्होंने रोकने के लिए युद्ध किया।'),
  ('scene-jatayu-gives-last-testimony', 'witness-names-ravana-and-south', 'en', 'Jatayu gives a name, direction, and reason not to despair', 'Jatayu identifies Ravana, describes Sita calling for help, and points the search south. He adds that the abduction occurred at a moment whose gain will turn against the taker, urging Rama not to abandon hope. The broken trail becomes actionable knowledge just before the witness dies.'),
  ('scene-jatayu-gives-last-testimony', 'witness-names-ravana-and-south', 'hi', 'जटायु नाम, दिशा और आशा देते हैं', 'जटायु रावण का नाम लेते, सीता की सहायता-पुकार बताते और खोज को दक्षिण दिशा देते हैं। वे कहते हैं कि हरण ऐसे समय हुआ जिसका लाभ लेने वाले के विरुद्ध जाएगा, इसलिए आशा न छोड़ी जाए। साक्षी की मृत्यु से ठीक पहले टूटी राह कार्य योग्य ज्ञान बनती है।'),
  ('scene-jatayu-gives-last-testimony', 'rama-stops-to-honour-jatayu', 'en', 'The search pauses for a father''s friend', 'Jatayu dies in Rama''s arms. Although every moment matters for Sita, Rama and Lakshmana gather wood, light the funeral fire, offer water, and speak of the defender as worthy of the highest destination. The pause establishes what the rescue is for: a world where loyal lives are not discarded as clues.'),
  ('scene-jatayu-gives-last-testimony', 'rama-stops-to-honour-jatayu', 'hi', 'खोज पिता के मित्र के लिए रुकती है', 'जटायु राम की बाँहों में प्राण छोड़ते हैं। सीता की खोज में हर क्षण महत्त्वपूर्ण है, फिर भी राम-लक्ष्मण लकड़ी जुटाकर अग्नि देते, जल अर्पित करते और रक्षक को उच्च गति योग्य मानते हैं। यह विराम बताता है कि बचाव किस संसार के लिए है—जहाँ निष्ठावान जीवन केवल संकेत बनकर नहीं फेंके जाते।'),
  ('scene-kabandha-seizes-the-searchers', 'southwest-road-loses-its-path', 'en', 'The known trail dissolves into dense forest', 'After honouring Jatayu, Rama and Lakshmana travel southwest and then south through Krauncha and into a tract people do not use. Flowers and animals give way to tangled growth, poor sightlines, and no reliable path. They must keep choosing direction while grief makes every delay feel dangerous.'),
  ('scene-kabandha-seizes-the-searchers', 'southwest-road-loses-its-path', 'hi', 'जानी राह घने वन में मिट जाती है', 'जटायु का संस्कार कर राम-लक्ष्मण दक्षिण-पश्चिम और फिर दक्षिण चलते हुए क्रौंच वन से ऐसी भूमि में आते हैं जहाँ लोग नहीं चलते। फूल और पशु पीछे छूटते हैं; उलझी वनस्पति, कम दृश्यता और बिना राह का क्षेत्र सामने है। शोक के बीच हर देरी खतरनाक लगती है, फिर भी दिशा चुननी है।'),
  ('scene-kabandha-seizes-the-searchers', 'ayomukhi-turns-approach-into-assault', 'en', 'An unwanted embrace becomes another forest danger', 'Ayomukhi rushes toward Lakshmana, declares desire, and physically seizes him without agreement. Lakshmana frees himself with violent mutilation and the brothers move on. The moment is brief but not romanticised: pursuit and touch are not made consensual by being framed as attraction.'),
  ('scene-kabandha-seizes-the-searchers', 'ayomukhi-turns-approach-into-assault', 'hi', 'अनचाहा आलिंगन एक और वन-संकट बनता है', 'अयोमुखी लक्ष्मण की ओर दौड़कर इच्छा व्यक्त करती और बिना सहमति उन्हें पकड़ती है। लक्ष्मण हिंसक रूप से स्वयं को छुड़ाते हैं और भाई आगे बढ़ते हैं। प्रसंग छोटा है, पर रोमानी नहीं—आकर्षण कह देने से पीछा और स्पर्श सहमति नहीं बन जाते।'),
  ('scene-kabandha-seizes-the-searchers', 'omen-becomes-enormous-arms', 'en', 'A warning tremor becomes a body across the road', 'Lakshmana feels an ominous tremor before the forest erupts with a vast headless being whose mouth is in its torso and whose arms reach across the trees. Kabandha catches both brothers from a distance. Their weapons are still in hand, but the attacker controls the space before they can approach him.'),
  ('scene-kabandha-seizes-the-searchers', 'omen-becomes-enormous-arms', 'hi', 'चेतावनी की कंपकंपी राह घेरते शरीर में बदलती है', 'लक्ष्मण अशुभ कंपकंपी अनुभव करते हैं, तभी वन से ऐसा विशाल सिरहीन प्राणी निकलता है जिसका मुख धड़ में और भुजाएँ वृक्षों के पार तक फैली हैं। कबंध दूर से दोनों भाइयों को पकड़ लेता है। शस्त्र हाथ में हैं, पर निकट पहुँचने से पहले स्थान उसी के नियंत्रण में है।'),
  ('scene-kabandha-seizes-the-searchers', 'lakshmana-fears-the-search-ends-here', 'en', 'Lakshmana imagines himself traded for Rama''s escape', 'Held and exhausted, Lakshmana says destiny may have brought him to death after kingdom, father, and Sita were lost. He urges Rama to escape and continue alone. Rama refuses panic, studies the arms that create Kabandha''s advantage, and sees that the same stretched limbs can be attacked before the mouth reaches them.'),
  ('scene-kabandha-seizes-the-searchers', 'lakshmana-fears-the-search-ends-here', 'hi', 'लक्ष्मण अपने बदले राम की मुक्ति की कल्पना करते हैं', 'पकड़े और थके लक्ष्मण कहते हैं कि राज्य, पिता और सीता के बाद भाग्य उन्हें भी मृत्यु तक लाया है। वे राम से अकेले बचकर खोज जारी रखने को कहते हैं। राम घबराहट रोककर उन भुजाओं को देखते हैं जो कबंध की शक्ति हैं—मुख तक पहुँचने से पहले वही फैले अंग काटे जा सकते हैं।'),
  ('scene-kabandha-tells-how-he-fell', 'arms-are-cut-not-life', 'en', 'The brothers attack the power holding them', 'Kabandha draws the brothers toward his mouth and calls them food. Lakshmana proposes cutting the enormous arms rather than killing a being unable to fight once disarmed. They strike together, fall free, and leave Kabandha alive but unable to continue seizing travellers from beyond their sight.'),
  ('scene-kabandha-tells-how-he-fell', 'arms-are-cut-not-life', 'hi', 'भाई उस शक्ति पर वार करते हैं जो उन्हें पकड़े है', 'कबंध भाइयों को मुख की ओर खींचकर भोजन कहता है। लक्ष्मण विशाल भुजाएँ काटने का प्रस्ताव रखते हैं, क्योंकि निशस्त्र होने पर लड़ न सकने वाले प्राणी की हत्या उचित नहीं। दोनों साथ वार कर मुक्त होते हैं और कबंध जीवित, पर दूर से यात्रियों को पकड़ने में असमर्थ रह जाता है।'),
  ('scene-kabandha-tells-how-he-fell', 'names-trigger-recognition', 'en', 'Dasharatha''s sons are the names Kabandha awaited', 'Wounded Kabandha asks who overcame him. When Lakshmana names Rama, exile, and the search for Sita, the creature becomes relieved rather than vengeful. A prophecy said Rama would cut his arms and burn the body, ending the condition that trapped him in this form.'),
  ('scene-kabandha-tells-how-he-fell', 'names-trigger-recognition', 'hi', 'दशरथ के पुत्र वही नाम हैं जिनकी कबंध प्रतीक्षा कर रहा था', 'घायल कबंध विजेताओं का परिचय पूछता है। लक्ष्मण राम, वनवास और सीता की खोज बताते हैं तो वह प्रतिशोध नहीं, राहत अनुभव करता है। भविष्यवाणी थी कि राम उसकी भुजाएँ काटकर शरीर जलाएँगे और इस रूप का बंधन समाप्त होगा।'),
  ('scene-kabandha-tells-how-he-fell', 'beauty-was-used-to-frighten', 'en', 'Kabandha traces the fall before the body changed', 'Kabandha says he once possessed celebrated beauty but deliberately assumed frightening forms to torment forest ascetics. When he attacked Sthulashira, the sage cursed him to remain in the hated shape. The account does not make appearance the moral failure; using form and power to terrorise others comes first.'),
  ('scene-kabandha-tells-how-he-fell', 'beauty-was-used-to-frighten', 'hi', 'कबंध शरीर बदलने से पहले की गिरावट बताते हैं', 'कबंध बताते हैं कि कभी उनका सौंदर्य प्रसिद्ध था, पर वे डरावने रूप बनाकर वन के तपस्वियों को सताते थे। स्थूलशिरा पर आक्रमण करने पर ऋषि ने उसी घृणित रूप में रहने का शाप दिया। कथा रूप को दोष नहीं बनाती—पहला पतन रूप और शक्ति से दूसरों को आतंकित करना था।'),
  ('scene-kabandha-tells-how-he-fell', 'indra-compresses-the-body', 'en', 'A second act of aggression produces the body they met', 'Long life made Kabandha reckless enough to attack Indra. The thunderbolt drove his head and legs into his torso; when he pleaded that hunger would make life impossible, Indra gave him the vast arms and body-mouth used to seize prey. The brothers have interrupted a survival system built from repeated violence.'),
  ('scene-kabandha-tells-how-he-fell', 'indra-compresses-the-body', 'hi', 'दूसरा आक्रमण वही शरीर बनाता है जिससे भाई मिले', 'दीर्घ जीवन ने कबंध को इतना उन्मत्त किया कि उसने इंद्र पर आक्रमण किया। वज्र ने सिर और पैर धड़ में दबा दिए; भूख से जीवित न रह पाने की विनती पर इंद्र ने दूर तक फैलने वाली भुजाएँ और धड़ का मुख दिया। भाइयों ने बार-बार की हिंसा से बनी जीविका-व्यवस्था रोकी है।'),
  ('scene-kabandha-names-sugriva', 'brothers-complete-the-promised-fire', 'en', 'Release requires the difficult funeral work', 'Kabandha cannot reveal the useful path until the brothers burn his huge body. Rama and Lakshmana drag it into a mountain hollow, gather fuel, and light the pyre. The task is neither battle nor search, yet completing it honours the bargain and makes the promised transformation possible.'),
  ('scene-kabandha-names-sugriva', 'brothers-complete-the-promised-fire', 'hi', 'मुक्ति के लिए कठिन अंतिम संस्कार आवश्यक है', 'विशाल शरीर जलने से पहले कबंध उपयोगी राह नहीं बता सकता। राम-लक्ष्मण उसे पर्वतीय गड्ढे में ले जाकर ईंधन जुटाते और चिता जलाते हैं। यह न युद्ध है, न सीधी खोज; फिर भी वचन निभाने और नियत परिवर्तन के लिए आवश्यक श्रम है।'),
  ('scene-kabandha-names-sugriva', 'kabandha-rises-restored', 'en', 'The witness rises in the body he remembered', 'From the fire Kabandha rises with restored limbs and radiance, then speaks from a celestial vehicle. The visual reversal confirms his history without erasing what he did as a predator. Release gives him perspective and the capacity to repay help; it does not retroactively make every earlier action harmless.'),
  ('scene-kabandha-names-sugriva', 'kabandha-rises-restored', 'hi', 'साक्षी अपने स्मृत रूप में उठता है', 'अग्नि से कबंध पूर्ण अंग और प्रकाशमान रूप में उठकर दिव्य वाहन से बोलता है। दृश्य-परिवर्तन उसकी कथा की पुष्टि करता है, पर शिकारी रूप के कर्म नहीं मिटाता। मुक्ति उसे दृष्टि और सहायता लौटाने की क्षमता देती है; पहले की हानि को निर्दोष नहीं बनाती।'),
  ('scene-kabandha-names-sugriva', 'sugriva-is-not-an-all-knowing-saviour', 'en', 'The proposed ally is also frightened and displaced', 'Kabandha names Sugriva, who lives on Rishyamuka after his brother Vali drove him from kingdom and wife. Sugriva knows the world''s routes and can mobilise a wide search, but he is not a waiting saviour with no needs. Rama will have to hear his loss and decide what reciprocal help means.'),
  ('scene-kabandha-names-sugriva', 'sugriva-is-not-an-all-knowing-saviour', 'hi', 'प्रस्तावित साथी भी भयभीत और विस्थापित है', 'कबंध सुग्रीव का नाम लेते हैं, जो भाई वाली द्वारा राज्य और पत्नी से अलग किए जाने के बाद ऋष्यमूक पर रहते हैं। सुग्रीव मार्ग जानते और व्यापक खोज जुटा सकते हैं, पर बिना आवश्यकता वाले उद्धारक नहीं। राम को उनकी हानि सुनकर परस्पर सहायता का अर्थ तय करना होगा।'),
  ('scene-kabandha-names-sugriva', 'alliance-must-be-witnessed-and-mutual', 'en', 'Kabandha recommends a declared alliance', 'The advice is specific: approach Sugriva, speak truthfully, and establish friendship before fire as witness. Rama should not merely hire searchers or command a weaker exile. Each side has knowledge and power the other lacks, so the next world begins with a negotiated commitment rather than instant obedience.'),
  ('scene-kabandha-names-sugriva', 'alliance-must-be-witnessed-and-mutual', 'hi', 'कबंध घोषित और परस्पर मैत्री की सलाह देते हैं', 'सलाह स्पष्ट है—सुग्रीव के पास जाकर सत्य बोलो और अग्नि को साक्षी मानकर मैत्री करो। राम केवल खोजी नियुक्त या कमजोर निर्वासित को आदेश न दें। दोनों के पास दूसरे से भिन्न ज्ञान और शक्ति है, इसलिए अगला संसार तत्काल आज्ञाकारिता नहीं, तय प्रतिबद्धता से खुलेगा।'),
  ('scene-road-to-pampa-is-mapped', 'route-is-food-as-well-as-direction', 'en', 'The map includes how the travellers will live', 'Kabandha lists fruiting forests, honey, flowering trees, and water along the westward road. The detail is not decorative botany: exhausted travellers searching without supply lines need to know where they can eat, rest, and continue. Geography becomes a survival plan rather than a line between icons.'),
  ('scene-road-to-pampa-is-mapped', 'route-is-food-as-well-as-direction', 'hi', 'नक्शा यह भी बताता है कि यात्री जीवित कैसे रहेंगे', 'कबंध पश्चिमी राह के फलदार वन, मधु, फूलों वाले वृक्ष और जल बताते हैं। यह सजावटी वनस्पति-सूची नहीं—बिना रसद खोजते थके यात्रियों को भोजन, विश्राम और आगे बढ़ने के स्थान चाहिए। भूगोल चिह्नों के बीच रेखा नहीं, जीवित रहने की योजना बनता है।'),
  ('scene-road-to-pampa-is-mapped', 'pampa-is-a-living-lake', 'en', 'Pampa is described as an ecosystem, not a blue marker', 'The lake appears through clear water, fish, birds, flowering banks, gentle access points, and food that can be gathered without danger. Kabandha''s description lets Pampa exist before arrival as a place with sound, movement, and practical use, not merely the backdrop where another character will enter.'),
  ('scene-road-to-pampa-is-mapped', 'pampa-is-a-living-lake', 'hi', 'पंपा नीला चिह्न नहीं, जीवित पारिस्थितिकी है', 'पंपा स्वच्छ जल, मछलियों, पक्षियों, फूलों वाले तट, सहज घाट और सुरक्षित आहार के रूप में सामने आती है। कबंध का वर्णन पहुँचने से पहले ही उसे ध्वनि, गति और उपयोग वाला स्थान बनाता है—केवल अगले पात्र की पृष्ठभूमि नहीं।'),
  ('scene-road-to-pampa-is-mapped', 'matanga-ground-holds-memory', 'en', 'The road passes through work that outlived its workers', 'Near Pampa lies the ground of Matanga''s ascetics, where sweat from years of labour is remembered as unfading flowers and where animals lived without fear. Their bodies are gone, but maintained spaces, ritual objects, and Shabari''s continued service keep the community legible.'),
  ('scene-road-to-pampa-is-mapped', 'matanga-ground-holds-memory', 'hi', 'राह ऐसे श्रम से गुजरती है जो श्रमिकों के बाद भी जीवित है', 'पंपा के पास मातंग के तपस्वियों की भूमि है, जहाँ वर्षों के श्रम का पसीना अमर फूलों की तरह याद किया जाता और पशु निर्भय रहते थे। उनके शरीर नहीं, पर सँभाले स्थान, अनुष्ठान-वस्तुएँ और शबरी की सेवा समुदाय को पढ़ने योग्य रखते हैं।'),
  ('scene-road-to-pampa-is-mapped', 'rishyamuka-is-visible-beyond-welcome', 'en', 'Shabari is the threshold; Sugriva remains the destination', 'Kabandha places Shabari''s hermitage on the route and Rishyamuka beyond Pampa, where Vali cannot safely reach Sugriva. The map therefore carries two different encounters: a welcome completing an old promise and a political alliance that must still be formed. Neither is allowed to erase the other.'),
  ('scene-road-to-pampa-is-mapped', 'rishyamuka-is-visible-beyond-welcome', 'hi', 'शबरी देहरी हैं; सुग्रीव अभी भी गंतव्य हैं', 'कबंध राह पर शबरी का आश्रम और पंपा के पार ऋष्यमूक बताते हैं, जहाँ वाली सुग्रीव तक सुरक्षित नहीं पहुँच सकता। नक्शे में दो अलग मिलन हैं—पुराना वचन पूरा करता स्वागत और अभी बनने वाली राजनीतिक मैत्री। कोई दूसरे को नहीं मिटाता।'),
  ('scene-shabari-keeps-her-welcome', 'travellers-arrive-as-awaited-guests', 'en', 'Shabari recognises the guests she stayed to receive', 'Following Kabandha''s route, Rama and Lakshmana reach the western bank of Pampa and enter Shabari''s hermitage. She rises, welcomes them, washes their feet, and offers water. The meeting is not accidental celebrity recognition; her teachers had asked her to remain until this service could be completed.'),
  ('scene-shabari-keeps-her-welcome', 'travellers-arrive-as-awaited-guests', 'hi', 'शबरी उन अतिथियों को पहचानती हैं जिनके लिए रुकी थीं', 'कबंध की राह से राम-लक्ष्मण पंपा के पश्चिमी तट पर शबरी के आश्रम पहुँचते हैं। वे उठकर स्वागत करती, चरण धोती और जल देती हैं। यह अचानक प्रसिद्ध अतिथि पहचानना नहीं—गुरुओं ने उन्हें यह सेवा पूर्ण होने तक रुकने को कहा था।'),
  ('scene-shabari-keeps-her-welcome', 'rama-asks-about-her-life', 'en', 'The guest asks whether the host''s long discipline is well', 'Rama does not receive the welcome and move on immediately. He asks whether Shabari''s austerity, food, anger, vows, and service have remained steady and whether she has found inward satisfaction. Her years are treated as a life with its own completion, not merely waiting time before a hero arrived.'),
  ('scene-shabari-keeps-her-welcome', 'rama-asks-about-her-life', 'hi', 'अतिथि मेज़बान की दीर्घ साधना की कुशल पूछते हैं', 'राम स्वागत लेकर तुरंत आगे नहीं बढ़ते। वे पूछते हैं कि शबरी की तपस्या, आहार, क्रोध-संयम, व्रत और सेवा स्थिर रहे और उन्हें भीतर संतोष मिला या नहीं। उनके वर्षों को नायक के आने से पहले की खाली प्रतीक्षा नहीं, अपने पूर्ण अर्थ वाला जीवन माना जाता है।'),
  ('scene-shabari-keeps-her-welcome', 'forest-food-is-offered-with-knowledge', 'en', 'The meal comes from knowing this forest', 'Shabari offers gathered forest foods selected from what grows around the hermitage. The scene centres hospitality, local knowledge, and care; it need not turn later popular embellishments into a universal textual claim. What matters here is that she provisioned expected travellers from a landscape she knows intimately.'),
  ('scene-shabari-keeps-her-welcome', 'forest-food-is-offered-with-knowledge', 'hi', 'भोजन इस वन के ज्ञान से आता है', 'शबरी आश्रम के आसपास से जुटाया वन-आहार देती हैं। दृश्य आतिथ्य, स्थानीय ज्ञान और देखभाल को केंद्र में रखता है; बाद की लोकप्रिय विस्तार-कथाओं को सार्वभौमिक पाठ-दावा बनाने की आवश्यकता नहीं। यहाँ महत्त्व यह है कि उन्होंने परिचित भू-दृश्य से अपेक्षित यात्रियों की व्यवस्था की।'),
  ('scene-shabari-keeps-her-welcome', 'teachers-traces-lead-to-departure', 'en', 'Shabari shows what remains, then chooses to leave', 'She guides the brothers through altars, bathing places, garments, and garlands preserved from her teachers'' community. Having received permission from Rama and completed the welcome entrusted to her, Shabari enters the fire and joins the region she associates with her teachers. The choice closes her route on her own declared purpose.'),
  ('scene-shabari-keeps-her-welcome', 'teachers-traces-lead-to-departure', 'hi', 'शबरी बची स्मृतियाँ दिखाकर प्रस्थान चुनती हैं', 'वे भाइयों को वेदियाँ, स्नान-स्थल, वस्त्र और गुरु-समुदाय से बची मालाएँ दिखाती हैं। राम की अनुमति और सौंपा स्वागत पूरा होने पर शबरी अग्नि में प्रवेश कर उस लोक जाती हैं जिसे गुरुओं से जोड़ती हैं। उनका प्रस्थान उनके स्वयं घोषित उद्देश्य पर उनकी राह पूर्ण करता है।'),
  ('scene-pampa-opens-the-alliance-world', 'brothers-read-the-hermitage-after-shabari', 'en', 'The place remains meaningful after its guide departs', 'After Shabari departs, Rama and Lakshmana revisit the protected grove, its peaceful animals, old altars, and seven waters. They bathe and honour their ancestors. The practices do not magically solve the search; they mark a transition from accumulated pollution and grief toward readiness for the next relationship.'),
  ('scene-pampa-opens-the-alliance-world', 'brothers-read-the-hermitage-after-shabari', 'hi', 'मार्गदर्शक के बाद भी स्थान अर्थपूर्ण रहता है', 'शबरी के जाने के बाद राम-लक्ष्मण सुरक्षित उपवन, शांत पशु, पुरानी वेदियाँ और सात जल देखते हैं। वे स्नान कर पूर्वजों को अर्पण देते हैं। यह खोज को जादुई ढंग से पूरा नहीं करता; संचित शोक और अशांति से अगले संबंध के लिए तैयार होने का परिवर्तन चिह्नित करता है।'),
  ('scene-pampa-opens-the-alliance-world', 'confidence-returns-before-answer', 'en', 'Rama feels auspicious movement without claiming success', 'Rama tells Lakshmana that his mind feels lighter and that good fortune may be approaching. He does not claim Sita is found or that danger has ended. The change is enough to act: despair no longer consumes every observation, so Kabandha''s destination can become a real next step.'),
  ('scene-pampa-opens-the-alliance-world', 'confidence-returns-before-answer', 'hi', 'उत्तर मिलने से पहले राम शुभ गति अनुभव करते हैं', 'राम लक्ष्मण से कहते हैं कि मन हल्का है और शुभ अवसर निकट हो सकता है। वे यह दावा नहीं करते कि सीता मिल गईं या संकट समाप्त हुआ। परिवर्तन कार्य करने भर का है—निराशा अब हर दृश्य नहीं निगलती, इसलिए कबंध का गंतव्य वास्तविक अगला कदम बनता है।'),
  ('scene-pampa-opens-the-alliance-world', 'pampa-beauty-sharpens-absence', 'en', 'Beauty does not simply heal; it also reminds', 'Pampa opens with clear water, blossoms, birds, fish, breeze, and mountain views. Each pleasure carries an echo of how Sita would have responded, so Rama''s renewed attention also renews longing. The world becomes vivid again without requiring grief to disappear before exploration can continue.'),
  ('scene-pampa-opens-the-alliance-world', 'pampa-beauty-sharpens-absence', 'hi', 'सुंदरता केवल ठीक नहीं करती, याद भी दिलाती है', 'पंपा स्वच्छ जल, फूल, पक्षी, मछली, हवा और पर्वत-दृश्य के साथ खुलती है। हर आनंद में यह स्मृति जुड़ी है कि सीता कैसी प्रतिक्रिया देतीं; इसलिए राम का लौटता ध्यान विरह भी लौटाता है। खोज जारी रखने के लिए शोक मिटाना आवश्यक नहीं, संसार फिर जीवित हो सकता है।'),
  ('scene-pampa-opens-the-alliance-world', 'rishyamuka-becomes-next-door', 'en', 'Across the lake, the alliance world is finally reachable', 'Rishyamuka now stands within view, holding Sugriva and the network Kabandha promised could search the world. The Araṇya journey ends not with Sita recovered but with the brothers equipped to enter a new social world. The next action is encounter, listening, and reciprocal alliance—not another solitary sweep of forest.'),
  ('scene-pampa-opens-the-alliance-world', 'rishyamuka-becomes-next-door', 'hi', 'झील के पार मैत्री का संसार पहुँच में आता है', 'ऋष्यमूक अब सामने है, जहाँ सुग्रीव और वह जाल है जो संसार भर खोज सकता है। अरण्य यात्रा सीता मिलने पर नहीं, भाइयों के नए सामाजिक संसार में प्रवेश योग्य होने पर समाप्त होती है। अगला कार्य अकेली वन-खोज नहीं—मिलना, सुनना और परस्पर मैत्री बनाना है।'),
  ('scene-pampa-holds-grief-and-watchers', 'spring-makes-sita-present-by-absence', 'en', 'Spring makes every pleasure remember Sita', 'At Pampa, Rama notices lotuses, clear water, flowering trees, birds, breeze, and pairs of animals moving together. Each living detail recalls how Sita would have seen or shared it. Beauty does not cure separation; renewed attention gives grief more precise objects and words.'),
  ('scene-pampa-holds-grief-and-watchers', 'spring-makes-sita-present-by-absence', 'hi', 'वसंत हर आनंद में सीता की स्मृति जगाता है', 'पंपा पर राम कमल, स्वच्छ जल, फूलों वाले वृक्ष, पक्षी, हवा और साथ चलते पशु-युगल देखते हैं। हर जीवित विवरण याद दिलाता है कि सीता इसे कैसे देखतीं या बाँटतीं। सुंदरता वियोग नहीं मिटाती; लौटता ध्यान शोक को अधिक स्पष्ट वस्तु और शब्द देता है।'),
  ('scene-pampa-holds-grief-and-watchers', 'rama-speaks-longing-not-only-mission', 'en', 'The searcher speaks as a separated partner', 'Rama tells Lakshmana that finding Sita would make kingdom and even heaven secondary, and imagines how she may be surviving captivity. The speech keeps the search from becoming an abstract quest token: the person sought has shared seasons, gestures, conversations, and a life that continues elsewhere.'),
  ('scene-pampa-holds-grief-and-watchers', 'rama-speaks-longing-not-only-mission', 'hi', 'खोजी एक बिछड़े साथी की तरह बोलता है', 'राम लक्ष्मण से कहते हैं कि सीता मिल जाएँ तो राज्य और स्वर्ग भी गौण हैं; वे सोचते हैं बंदी जीवन में वह कैसे टिक रही होंगी। यह वाणी खोज को अमूर्त लक्ष्य बनने से रोकती है—जिस व्यक्ति को खोजा जा रहा है, उसके साझा मौसम, संकेत, संवाद और कहीं जारी जीवन हैं।'),
  ('scene-pampa-holds-grief-and-watchers', 'lakshmana-answers-with-direction', 'en', 'Lakshmana lets grief speak, then restores the next action', 'Lakshmana does not shame Rama for longing. He reminds him that determined effort can reach even a hidden enemy and points toward the promised meeting with Sugriva. Comfort here is directional: sorrow may travel with them, but it cannot be allowed to make the newly opened alliance route invisible.'),
  ('scene-pampa-holds-grief-and-watchers', 'lakshmana-answers-with-direction', 'hi', 'लक्ष्मण शोक को स्थान देकर अगला कार्य लौटाते हैं', 'लक्ष्मण राम की विरह-वाणी को लज्जित नहीं करते। वे याद दिलाते हैं कि दृढ़ प्रयास छिपे शत्रु तक भी पहुँच सकता है और सुग्रीव से नियत मिलन की दिशा दिखाते हैं। सांत्वना यहाँ दिशा देती है—शोक साथ चल सकता है, पर नई मैत्री-राह को अदृश्य नहीं कर सकता।'),
  ('scene-pampa-holds-grief-and-watchers', 'sugriva-sees-weapons-before-faces', 'en', 'Across Pampa, Sugriva sees a possible attack', 'From Rishyamuka, Sugriva and his companions notice two powerful bowmen in bark clothing moving below. The mountain is refuge because Vali cannot safely enter it, so unfamiliar strength near its boundary reads as a breach. While Rama feels exposed by loss, Sugriva feels exposed by being found.'),
  ('scene-pampa-holds-grief-and-watchers', 'sugriva-sees-weapons-before-faces', 'hi', 'पंपा के पार सुग्रीव संभावित आक्रमण देखते हैं', 'ऋष्यमूक से सुग्रीव और साथी नीचे वल्कल पहने दो शक्तिशाली धनुर्धर देखते हैं। पर्वत इसलिए आश्रय है कि वाली वहाँ सुरक्षित प्रवेश नहीं कर सकता; सीमा के पास अनजान शक्ति टूटती सुरक्षा जैसी लगती है। राम हानि से असुरक्षित हैं, सुग्रीव खोज लिए जाने से।'),
  ('scene-sugriva-sends-hanuman', 'refuge-moves-before-facts-arrive', 'en', 'Sugriva relocates before he can verify the danger', 'Sugriva panics, moves his group across the mountain, and says Vali has sent killers in ascetic disguise. His companions follow because they share the costs of a wrong guess. The response is disproportionate to available evidence, but intelligible after betrayal and continuing pursuit.'),
  ('scene-sugriva-sends-hanuman', 'refuge-moves-before-facts-arrive', 'hi', 'सुग्रीव तथ्य मिलने से पहले आश्रय बदलते हैं', 'सुग्रीव घबराकर दल को पर्वत के दूसरे भाग में ले जाते और कहते हैं कि वाली ने तपस्वी-वेश में हत्यारे भेजे हैं। साथी चलते हैं क्योंकि गलत अनुमान की कीमत सब चुकाएँगे। उपलब्ध प्रमाण से प्रतिक्रिया बड़ी है, पर विश्वासघात और लगातार पीछा झेलने के बाद समझ में आती है।'),
  ('scene-sugriva-sends-hanuman', 'hanuman-challenges-the-panic', 'en', 'Hanuman says fear is outrunning judgment', 'Hanuman reminds Sugriva that Rishyamuka remains protected and that anxious movement can expose a leader more than calm observation. He does not dismiss Vali''s danger. He separates a real long-term threat from the unverified claim that these particular travellers belong to it.'),
  ('scene-sugriva-sends-hanuman', 'hanuman-challenges-the-panic', 'hi', 'हनुमान कहते हैं भय विवेक से आगे निकल रहा है', 'हनुमान याद दिलाते हैं कि ऋष्यमूक अभी सुरक्षित है और घबराई गति नेता को शांत निरीक्षण से अधिक उजागर कर सकती है। वे वाली का खतरा नहीं नकारते; वास्तविक दीर्घ संकट को इस अप्रमाणित दावे से अलग करते हैं कि ये यात्री उसी के दूत हैं।'),
  ('scene-sugriva-sends-hanuman', 'mission-is-to-read-intent', 'en', 'Sugriva asks for gestures, words, and motive', 'Sugriva sends Hanuman to approach in another form, praise the strangers without overcommitting, ask why they entered the forest, and study how they react. If they seem sincere, Hanuman may speak favourably of Sugriva. Trust is staged through observation rather than treated as an instant character instinct.'),
  ('scene-sugriva-sends-hanuman', 'mission-is-to-read-intent', 'hi', 'सुग्रीव हावभाव, वाणी और उद्देश्य की जाँच चाहते हैं', 'सुग्रीव हनुमान को दूसरा रूप लेकर जाने, बिना वचन बाँधे अजनबियों का सम्मान करने, वन में आने का कारण पूछने और प्रतिक्रिया देखने को कहते हैं। सच्चे लगें तो सुग्रीव के पक्ष में बोलें। विश्वास तात्कालिक अंतर्ज्ञान नहीं, चरणबद्ध निरीक्षण से बनेगा।'),
  ('scene-sugriva-sends-hanuman', 'hanuman-chooses-a-mendicant-form', 'en', 'Hanuman reduces the threat of first contact', 'Hanuman accepts the task, leaves the protected height, and takes the appearance of a mendicant before approaching. The disguise is investigative and can itself create uncertainty, but it removes the immediate visual challenge of one more armed forest power meeting two tense archers.'),
  ('scene-sugriva-sends-hanuman', 'hanuman-chooses-a-mendicant-form', 'hi', 'हनुमान पहली भेंट का खतरा घटाते हैं', 'हनुमान कार्य स्वीकारकर सुरक्षित ऊँचाई से उतरते और पास जाने से पहले भिक्षु-रूप लेते हैं। वेश जाँच का साधन है और स्वयं अनिश्चितता ला सकता है, पर दो सतर्क धनुर्धरों के सामने एक और सशस्त्र शक्ति का सीधा दृश्य-संघर्ष घटाता है।'),
  ('scene-hanuman-speaks-before-he-asks', 'description-does-not-become-accusation', 'en', 'Hanuman names the contradiction he sees', 'Hanuman greets the brothers and observes that they look like disciplined ascetics yet carry royal bodies, great bows, sorrow, and battlefield strength. He asks who they are and why their presence unsettles the animals. The description is precise without converting unfamiliarity into guilt.'),
  ('scene-hanuman-speaks-before-he-asks', 'description-does-not-become-accusation', 'hi', 'हनुमान दिखाई देने वाला विरोधाभास बताते हैं', 'हनुमान भाइयों का अभिवादन कर देखते हैं कि वे अनुशासित तपस्वी जैसे हैं, फिर भी राजसी देह, महान धनुष, शोक और युद्ध-शक्ति रखते हैं। वे परिचय और पशुओं की बेचैनी का कारण पूछते हैं। वर्णन सटीक है, पर अनजान होने को दोष नहीं बनाता।'),
  ('scene-hanuman-speaks-before-he-asks', 'hanuman-discloses-the-client', 'en', 'The questioner names whom he represents', 'After receiving silence, Hanuman identifies Sugriva as an exiled leader living in fear of Vali and says he has come as Sugriva''s counsellor. He also names himself as the wind''s son and explains his assumed form. The investigator gives the strangers material with which to judge him in return.'),
  ('scene-hanuman-speaks-before-he-asks', 'hanuman-discloses-the-client', 'hi', 'प्रश्नकर्ता बताता है कि वह किसका प्रतिनिधि है', 'मौन मिलने पर हनुमान सुग्रीव को वाली से भयभीत निर्वासित नेता बताते और स्वयं को उनका मंत्री कहते हैं। वे अपना पवनपुत्र परिचय और लिया हुआ रूप भी बताते हैं। जाँच करने वाला अजनबियों को बदले में स्वयं को परखने योग्य सामग्री देता है।'),
  ('scene-hanuman-speaks-before-he-asks', 'rama-hears-training-inside-speech', 'en', 'Rama judges the envoy by how he speaks', 'Rama tells Lakshmana that such ordered, gentle, complete speech must come from deep study and self-command. Hanuman has not wasted words, distorted sounds, displayed anxiety, or given offence. Rama''s admiration concerns usable communication: a leader represented by this envoy may be reachable through reason.'),
  ('scene-hanuman-speaks-before-he-asks', 'rama-hears-training-inside-speech', 'hi', 'राम दूत को उसकी वाणी से परखते हैं', 'राम लक्ष्मण से कहते हैं कि ऐसी क्रमबद्ध, कोमल और पूर्ण वाणी गहरे अध्ययन तथा संयम से आती है। हनुमान ने शब्द व्यर्थ नहीं किए, ध्वनि बिगाड़ी नहीं, घबराहट दिखाई नहीं और अपमान नहीं किया। प्रशंसा उपयोगी संवाद की है—ऐसे दूत वाला नेता तर्क से पहुँचा जा सकता है।'),
  ('scene-hanuman-speaks-before-he-asks', 'silence-turns-into-an-invitation', 'en', 'Rama asks Lakshmana to answer the bridge', 'Rama recognises that Kabandha sent them to the very Sugriva Hanuman represents and asks Lakshmana to respond with equal care. First contact succeeds not because Hanuman magically knows their hearts, but because his method creates enough safety for the brothers to disclose why they came.'),
  ('scene-hanuman-speaks-before-he-asks', 'silence-turns-into-an-invitation', 'hi', 'राम लक्ष्मण से बने पुल का उत्तर देने को कहते हैं', 'राम पहचानते हैं कि कबंध ने जिस सुग्रीव के पास भेजा था, हनुमान उन्हीं का प्रतिनिधित्व करते हैं और लक्ष्मण से समान सावधानी से उत्तर देने को कहते हैं। पहली भेंट इसलिए सफल नहीं कि हनुमान मन पढ़ते हैं, बल्कि उनकी पद्धति कारण बताने योग्य सुरक्षा बनाती है।'),
  ('scene-lakshmana-tells-the-need', 'lakshmana-starts-before-the-abduction', 'en', 'The need is explained through the road that produced it', 'Lakshmana begins with Dasharatha, Rama''s exile, and the decision to honour a father''s word before reaching Sita''s abduction. The context prevents the armed strangers from appearing as wandering mercenaries. Their present search grows from family choices, political loss, and a specific crime.'),
  ('scene-lakshmana-tells-the-need', 'lakshmana-starts-before-the-abduction', 'hi', 'आवश्यकता उस पूरी राह से समझाई जाती है जिसने उसे जन्म दिया', 'लक्ष्मण दशरथ, राम के वनवास और पिता का वचन निभाने के निर्णय से शुरू कर सीता-हरण तक आते हैं। संदर्भ सशस्त्र अजनबियों को भटकते योद्धा बनने से रोकता है। वर्तमान खोज पारिवारिक चुनाव, राजनीतिक हानि और एक विशेष अपराध से निकली है।'),
  ('scene-lakshmana-tells-the-need', 'sugriva-was-named-before-hanuman-appeared', 'en', 'The brothers did not arrive by accident', 'Lakshmana explains that Kabandha named Sugriva as the ally capable of helping search for Sita. The statement answers the central suspicion: Rama and Lakshmana came toward Rishyamuka seeking Sugriva, not hunting him for Vali. Their weapons serve an openly stated need.'),
  ('scene-lakshmana-tells-the-need', 'sugriva-was-named-before-hanuman-appeared', 'hi', 'भाई संयोग से यहाँ नहीं पहुँचे', 'लक्ष्मण बताते हैं कि कबंध ने सीता की खोज में समर्थ साथी के रूप में सुग्रीव का नाम लिया था। इससे मुख्य संदेह का उत्तर मिलता है—राम-लक्ष्मण वाली के लिए शिकार करने नहीं, सुग्रीव को खोजते ऋष्यमूक आए हैं। उनके शस्त्र की घोषित आवश्यकता है।'),
  ('scene-lakshmana-tells-the-need', 'hanuman-offers-reciprocal-need', 'en', 'Hanuman answers with Sugriva''s own displacement', 'Hanuman says Sugriva was driven from kingdom and wife by Vali and also needs a capable friend. He predicts Sugriva will help search, but does not conceal the expected reciprocity. The prospective alliance becomes honest enough to negotiate because neither side is pretending to give without needing.'),
  ('scene-lakshmana-tells-the-need', 'hanuman-offers-reciprocal-need', 'hi', 'हनुमान सुग्रीव का अपना विस्थापन सामने रखते हैं', 'हनुमान बताते हैं कि वाली ने सुग्रीव को राज्य और पत्नी से अलग किया और उन्हें भी समर्थ मित्र चाहिए। वे खोज में सहायता का भरोसा रखते हैं, पर अपेक्षित प्रतिफल नहीं छिपाते। मैत्री बातचीत योग्य इसलिए बनती है कि कोई पक्ष आवश्यकता रहित दाता होने का अभिनय नहीं करता।'),
  ('scene-lakshmana-tells-the-need', 'hanuman-carries-them-to-rishyamuka', 'en', 'The intermediary becomes the physical route', 'With intent sufficiently clear, Hanuman leaves the mendicant guise, resumes his own form, and offers to carry both brothers up the difficult mountain. The transition from interview to transport is earned: disclosure has reduced the chance that either side will interpret sudden power as attack.'),
  ('scene-lakshmana-tells-the-need', 'hanuman-carries-them-to-rishyamuka', 'hi', 'मध्यस्थ स्वयं मिलन की राह बनता है', 'उद्देश्य पर्याप्त स्पष्ट होने पर हनुमान भिक्षु-वेश छोड़कर अपना रूप लेते और दोनों भाइयों को कठिन पर्वत पर ले जाने का प्रस्ताव रखते हैं। प्रश्नोत्तर से यात्रा का परिवर्तन अर्जित है—परिचय ने अचानक शक्ति को आक्रमण समझे जाने की संभावना घटाई है।'),
  ('scene-rama-sugriva-make-friendship', 'hanuman-presents-rama-without-exaggeration', 'en', 'The envoy reports need, character, and request', 'At Rishyamuka, Hanuman tells Sugriva who Rama and Lakshmana are, why they entered the forest, how Sita was taken, and that they seek friendship. He also says Rama is willing to assist Sugriva. The report carries what was learned without inventing certainty or hiding the exchange ahead.'),
  ('scene-rama-sugriva-make-friendship', 'hanuman-presents-rama-without-exaggeration', 'hi', 'दूत आवश्यकता, चरित्र और अनुरोध बताता है', 'ऋष्यमूक पर हनुमान सुग्रीव को राम-लक्ष्मण का परिचय, वन में आने का कारण, सीता-हरण और मैत्री की इच्छा बताते हैं। वे यह भी कहते हैं कि राम सुग्रीव की सहायता को तैयार हैं। रिपोर्ट सीखी बात रखती है, झूठी निश्चितता या आगे के विनिमय को नहीं छिपाती।'),
  ('scene-rama-sugriva-make-friendship', 'sugriva-offers-a-hand-not-submission', 'en', 'Sugriva offers friendship as an equal commitment', 'Sugriva says Hanuman''s account makes Rama worthy of friendship and extends his hand. Rama receives and embraces him. The physical movement matters: the refugee king is not kneeling to a rescuer, and the prince is not purchasing a servant. Each accepts a relationship that will constrain future choices.'),
  ('scene-rama-sugriva-make-friendship', 'sugriva-offers-a-hand-not-submission', 'hi', 'सुग्रीव अधीनता नहीं, समान मैत्री का हाथ बढ़ाते हैं', 'सुग्रीव कहते हैं कि हनुमान का परिचय राम को मैत्री योग्य बनाता है और हाथ बढ़ाते हैं। राम हाथ पकड़कर उन्हें गले लगाते हैं। शरणार्थी राजा उद्धारक के सामने झुक नहीं रहा और राजकुमार सेवक नहीं खरीद रहा; दोनों ऐसा संबंध स्वीकारते हैं जो आगे के चुनाव बाँधेगा।'),
  ('scene-rama-sugriva-make-friendship', 'fire-makes-the-promise-public', 'en', 'Hanuman lights a witness for what follows', 'Hanuman kindles fire between them, and Rama and Sugriva circle it before sitting together. The rite makes the friendship more than warm feeling after a successful introduction. Each side can later point back to a declared commitment when fear, delay, grief, or conflicting priorities test it.'),
  ('scene-rama-sugriva-make-friendship', 'fire-makes-the-promise-public', 'hi', 'हनुमान आगे की प्रतिज्ञाओं के लिए साक्षी जलाते हैं', 'हनुमान बीच में अग्नि जलाते हैं और राम-सुग्रीव उसकी परिक्रमा कर साथ बैठते हैं। यह विधि सफल परिचय की गर्म भावना से अधिक संबंध बनाती है। भय, विलंब, शोक या टकराती प्राथमिकताओं के समय दोनों घोषित वचन को उत्तरदायित्व की तरह याद कर सकेंगे।'),
  ('scene-rama-sugriva-make-friendship', 'two-promises-open-two-story-roads', 'en', 'Search for Sita and justice against Vali become reciprocal roads', 'Sugriva promises help finding Sita; Rama promises to end Vali''s wrongdoing and restore what Sugriva lost. Relief comes with moral complexity, because the second promise will require facts, confrontation, and difficult judgment. For now the solitary search has gained allies, and the fearful refuge has gained a champion.'),
  ('scene-rama-sugriva-make-friendship', 'two-promises-open-two-story-roads', 'hi', 'सीता की खोज और वाली के अन्याय का सामना परस्पर राहें बनते हैं', 'सुग्रीव सीता की खोज में सहायता और राम वाली के अन्याय को रोककर सुग्रीव की हानि लौटाने का वचन देते हैं। राहत के साथ नैतिक कठिनाई भी है, क्योंकि दूसरा वचन तथ्य, सामना और कठिन निर्णय माँगेगा। अभी अकेली खोज को साथी और भयभीत आश्रय को समर्थ मित्र मिला है।'),
  ('scene-sita-jewels-return-the-abduction', 'sugriva-names-what-he-saw', 'en', 'Sugriva separates the sighting from what he still does not know', 'Sugriva says he saw a grieving woman carried through the sky, crying the brothers'' names while he and four counsellors watched from the hill. He believes she was Sita, but does not pretend to know Ravana''s destination. His promise to help begins with a bounded eyewitness account, not certainty added after friendship.'),
  ('scene-sita-jewels-return-the-abduction', 'sugriva-names-what-he-saw', 'hi', 'सुग्रीव देखी बात को अनजान बात से अलग रखते हैं', 'सुग्रीव बताते हैं कि उन्होंने पहाड़ी से चार मंत्रियों के साथ एक शोकाकुल स्त्री को आकाश मार्ग से जाते और दोनों भाइयों के नाम पुकारते देखा। वे उसे सीता मानते हैं, पर रावण की मंज़िल जानने का दावा नहीं करते। सहायता का वचन सीमित प्रत्यक्षदर्शी बात से शुरू होता है, मैत्री के बाद जोड़ी निश्चितता से नहीं।'),
  ('scene-sita-jewels-return-the-abduction', 'sita-leaves-a-trace', 'en', 'Sita turns ornaments into a trail', 'From Ravana''s grasp, Sita drops her scarf and ornaments toward the watchers below. Sugriva preserves the bundle rather than treating it as treasure or decoration. The act gives the missing person agency inside the abduction: she reads the landscape, notices possible witnesses, and creates a clue for people she cannot yet reach.'),
  ('scene-sita-jewels-return-the-abduction', 'sita-leaves-a-trace', 'hi', 'सीता आभूषणों को संकेत-मार्ग बनाती हैं', 'रावण की पकड़ से सीता नीचे देख रहे लोगों की ओर अपना वस्त्र और आभूषण गिराती हैं। सुग्रीव गठरी को धन या सजावट नहीं मानते, सुरक्षित रखते हैं। हरण के भीतर भी सीता सक्रिय हैं—वे भू-दृश्य पढ़तीं, संभावित साक्षी पहचानतीं और उन लोगों के लिए संकेत बनाती हैं जिन तक अभी पहुँच नहीं सकतीं।'),
  ('scene-sita-jewels-return-the-abduction', 'recognition-breaks-rama-open', 'en', 'Recognition makes distance collapse', 'When Sugriva brings the bundle, Rama recognises Sita''s scarf and ornaments, presses them to his chest, and falls under the force of renewed grief. These are not collectible rewards for finishing a quest. They are objects last touched by the person he is seeking, carrying proof of danger and survival into the safety of Rishyamuka.'),
  ('scene-sita-jewels-return-the-abduction', 'recognition-breaks-rama-open', 'hi', 'पहचान दूरी को अचानक मिटा देती है', 'सुग्रीव गठरी लाते हैं तो राम सीता का वस्त्र और आभूषण पहचानकर उन्हें छाती से लगाते और फिर उमड़े शोक से भूमि पर गिर पड़ते हैं। ये खोज पूरी करने के पुरस्कार नहीं, उस व्यक्ति के अंतिम स्पर्श वाली वस्तुएँ हैं जिसकी तलाश है; वे संकट और जीवित प्रतिरोध का प्रमाण ऋष्यमूक तक लाती हैं।'),
  ('scene-sita-jewels-return-the-abduction', 'lakshmana-recognises-the-feet', 'en', 'Lakshmana''s recognition is intimate and limited', 'Lakshmana cannot identify the armlets or earrings, but recognises the anklets because he regularly bowed at Sita''s feet. The answer neither invents total knowledge nor reduces affection to a label. Rama then asks where the sighting occurred and what is known of the abductor, turning the recovered trace into the next search question.'),
  ('scene-sita-jewels-return-the-abduction', 'lakshmana-recognises-the-feet', 'hi', 'लक्ष्मण की पहचान निकट भी है और सीमित भी', 'लक्ष्मण बाजूबंद या कुंडल नहीं पहचानते, पर नूपुर पहचानते हैं क्योंकि वे नियमित सीता के चरणों में प्रणाम करते थे। उत्तर न सर्वज्ञान गढ़ता है, न स्नेह को लेबल बनाता है। राम फिर पूछते हैं कि दृश्य कहाँ देखा गया और हरणकर्ता के बारे में क्या ज्ञात है—प्रमाण अगला खोज-प्रश्न बनता है।'),
  ('scene-friendship-makes-room-for-grief', 'sugriva-admits-the-map-is-blank', 'en', 'The new ally does not know Ravana''s refuge', 'Asked for Ravana''s location and power, Sugriva says plainly that he does not know either. He still promises to mobilise effort until Sita is found. The distinction matters for the journey: a trustworthy guide can open a search without already possessing its answer, and an unknown region should stay unknown on the world map.'),
  ('scene-friendship-makes-room-for-grief', 'sugriva-admits-the-map-is-blank', 'hi', 'नया साथी रावण का ठिकाना नहीं जानता', 'रावण का स्थान और शक्ति पूछे जाने पर सुग्रीव साफ कहते हैं कि वे दोनों नहीं जानते। फिर भी वे सीता मिलने तक प्रयास जुटाने का वचन देते हैं। यात्रा के लिए यह भेद महत्वपूर्ण है—विश्वसनीय मार्गदर्शक उत्तर जाने बिना खोज खोल सकता है और अनजान क्षेत्र मानचित्र पर अनजान ही रहना चाहिए।'),
  ('scene-friendship-makes-room-for-grief', 'consolation-is-imperfect-but-needed', 'en', 'Sugriva asks Rama to recover the ability to act', 'Sugriva compares Rama''s separation with his own and urges him not to drown in sorrow. His language is stern and not a perfect theory of grief, yet it comes from a fellow exile trying to keep a friend alive and capable. The scene lets the advice be historically situated without presenting emotional suppression as a universal rule.'),
  ('scene-friendship-makes-room-for-grief', 'consolation-is-imperfect-but-needed', 'hi', 'सुग्रीव राम से कार्य करने की क्षमता लौटाने को कहते हैं', 'सुग्रीव राम के वियोग को अपने वियोग से जोड़कर उनसे शोक में डूब न जाने को कहते हैं। उनकी भाषा कठोर है और शोक का पूर्ण सिद्धांत नहीं, फिर भी यह एक निर्वासित मित्र की कोशिश है कि दूसरा जीवित और सक्षम रहे। दृश्य सलाह को प्रसंग में रखता है, भावना दबाने का सार्वभौमिक नियम नहीं बनाता।'),
  ('scene-friendship-makes-room-for-grief', 'rama-accepts-help-without-erasing-loss', 'en', 'Rama regains steadiness and names what friendship did', 'Rama wipes his face, embraces Sugriva, and says a rare friend has done what was fitting at the moment of crisis. Recovery here is not forgetting Sita or closing the grief scene. It is enough self-possession to ask for the search to continue and to hear what the other party needs in return.'),
  ('scene-friendship-makes-room-for-grief', 'rama-accepts-help-without-erasing-loss', 'hi', 'राम स्थिरता लौटाकर मैत्री के काम को पहचानते हैं', 'राम मुख पोंछकर सुग्रीव को गले लगाते और कहते हैं कि संकट की घड़ी में दुर्लभ मित्र ने उचित काम किया। यहाँ संभलना सीता को भूलना या शोक-दृश्य बंद करना नहीं है। यह खोज जारी रखने और बदले में दूसरे पक्ष की आवश्यकता सुनने जितनी स्थिरता लौटना है।'),
  ('scene-friendship-makes-room-for-grief', 'truth-binds-both-promises', 'en', 'The promise becomes reciprocal and testable', 'Rama asks Sugriva to seek Sita and destroy Ravana''s obstruction, then invites him to state his own need without reserve. He promises that he has not spoken falsely and will make Sugriva''s cause succeed. Their conversation joins joys and wounds, but it also creates two obligations whose later fulfilment can be judged.'),
  ('scene-friendship-makes-room-for-grief', 'truth-binds-both-promises', 'hi', 'वचन परस्पर और जाँच योग्य बनता है', 'राम सुग्रीव से सीता की खोज और रावण की बाधा समाप्त करने का प्रयास माँगते, फिर उन्हें अपनी आवश्यकता बिना संकोच कहने को बुलाते हैं। वे सत्य पर सुग्रीव के कार्य को सफल करने का वचन देते हैं। संवाद सुख-दुख जोड़ता है, साथ ही दो ऐसे दायित्व बनाता है जिनकी पूर्ति आगे जाँची जा सकेगी।'),
  ('scene-sugriva-names-his-fear', 'friends-share-more-than-resources', 'en', 'Sugriva defines friendship as shared refuge', 'Sugriva says true friends treat wealth, hardship, home, and danger as concerns they can share. His speech is hopeful but also a negotiation of expectations: he is not praising Rama for ceremony alone. He is explaining why each exile may ask the other to risk comfort, territory, and force for a cause not originally his own.'),
  ('scene-sugriva-names-his-fear', 'friends-share-more-than-resources', 'hi', 'सुग्रीव मैत्री को साझा आश्रय बताते हैं', 'सुग्रीव कहते हैं कि सच्चे मित्र धन, कठिनाई, घर और संकट को साझा चिंता मानते हैं। यह केवल समारोह की प्रशंसा नहीं, अपेक्षाओं की बातचीत है। वे समझाते हैं कि दोनों निर्वासित एक-दूसरे से उस कारण के लिए सुविधा, क्षेत्र और शक्ति का जोखिम क्यों माँग सकते हैं जो पहले उसका अपना नहीं था।'),
  ('scene-sugriva-names-his-fear', 'a-branch-makes-a-council', 'en', 'The mountain becomes a place to speak as equals', 'Sugriva spreads a leafy sala branch and sits beside Rama; Hanuman prepares another seat for Lakshmana. The small actions turn a refuge ledge into a council without throne, palace, or formal audience. The user can remain in the environment while dialogue changes the political world instead of being removed to a text panel.'),
  ('scene-sugriva-names-his-fear', 'a-branch-makes-a-council', 'hi', 'पर्वत बराबरी से बोलने की सभा बनता है', 'सुग्रीव पत्तों वाली साल-डाली बिछाकर राम के साथ बैठते हैं; हनुमान लक्ष्मण के लिए दूसरी आसंदी बनाते हैं। छोटे काम बिना सिंहासन या दरबार आश्रय-शिला को परिषद बना देते हैं। उपयोगकर्ता वातावरण में रहते हुए संवाद से राजनीतिक संसार बदलता देखता है, अलग पाठ-पैनल में नहीं जाता।'),
  ('scene-sugriva-names-his-fear', 'loss-has-a-living-pursuer', 'en', 'Sugriva''s exile is not safely in the past', 'Sugriva says Vali took his kingdom and wife, imprisoned friends, sent agents to kill him, and confines his remaining circle to Hanuman and a few loyal companions. Rishyamuka is therefore not a scenic hideout. It is the narrow protected space within which a displaced leader and community can still remain alive.'),
  ('scene-sugriva-names-his-fear', 'loss-has-a-living-pursuer', 'hi', 'सुग्रीव का निर्वासन सुरक्षित अतीत नहीं है', 'सुग्रीव बताते हैं कि वाली ने राज्य और पत्नी छीन ली, मित्रों को बाँधा, हत्या के लिए दूत भेजे और उनका शेष संसार हनुमान तथा कुछ निष्ठावान साथियों तक सीमित कर दिया। इसलिए ऋष्यमूक सुंदर छिपने की जगह नहीं, वह संकीर्ण सुरक्षित क्षेत्र है जहाँ विस्थापित नेता और समुदाय जीवित रह सकते हैं।'),
  ('scene-sugriva-names-his-fear', 'rama-asks-for-the-cause', 'en', 'Anger pauses for the history of the conflict', 'Rama is angered by what he hears, but asks how the hostility began and what strengths and weaknesses shape it. He strings his bow while inviting a faithful account. The combination keeps urgency without treating the first allegation as the whole case: action will follow a story that still has another brother''s interpretation inside it.'),
  ('scene-sugriva-names-his-fear', 'rama-asks-for-the-cause', 'hi', 'क्रोध संघर्ष का इतिहास सुनने के लिए रुकता है', 'सुनी बात पर राम क्रोधित होते हैं, फिर भी पूछते हैं कि वैर कैसे शुरू हुआ और दोनों की शक्ति-कमज़ोरी क्या है। वे धनुष चढ़ाते हुए सच्चा विवरण माँगते हैं। इससे तात्कालिकता बनी रहती है, पर पहली शिकायत पूरा मामला नहीं बनती—कथा में दूसरे भाई की व्याख्या भी अभी आएगी।'),
  ('scene-cave-seals-a-brothers-fate', 'sugriva-begins-below-the-throne', 'en', 'Before the rupture, Vali is king and Sugriva serves', 'Sugriva begins by saying Vali was the honoured elder whom counsellors installed after their father''s death. Sugriva remained deferential rather than competing for rule. This starting point matters because the later crown cannot be understood simply as the final move in a long rivalry; the relationship first operates through accepted seniority.'),
  ('scene-cave-seals-a-brothers-fate', 'sugriva-begins-below-the-throne', 'hi', 'टूटन से पहले वाली राजा और सुग्रीव सेवक हैं', 'सुग्रीव पहले बताते हैं कि पिता की मृत्यु के बाद मंत्रियों ने सम्मानित ज्येष्ठ वाली को राजा बनाया और वे स्वयं विनम्र सेवक की तरह रहे। यह आरंभ महत्वपूर्ण है, क्योंकि बाद का मुकुट किसी पुराने सत्ता-संघर्ष की अंतिम चाल भर नहीं माना जा सकता; संबंध पहले स्वीकृत ज्येष्ठता पर चलता था।'),
  ('scene-cave-seals-a-brothers-fate', 'mayavi-pulls-both-brothers-out', 'en', 'A midnight challenge becomes a pursuit', 'Mayavi roars at Kishkindha''s gate and challenges Vali. Though family members try to stop him, Vali rushes out, and Sugriva follows from affection. The enemy flees into a grass-covered cavern. Vali orders Sugriva to guard the entrance and makes him swear to remain while he goes underground alone.'),
  ('scene-cave-seals-a-brothers-fate', 'mayavi-pulls-both-brothers-out', 'hi', 'आधी रात की ललकार पीछा बन जाती है', 'मायावी आधी रात किष्किंधा-द्वार पर गर्जकर वाली को ललकारता है। परिवार रोकता है, फिर भी वाली निकलता और स्नेह से सुग्रीव पीछे जाते हैं। शत्रु घास से ढकी गुफा में भागता है। वाली सुग्रीव को द्वार पर रहने की शपथ देकर अकेले भीतर जाता है।'),
  ('scene-cave-seals-a-brothers-fate', 'a-year-produces-only-signs', 'en', 'Waiting receives blood, enemy roars, and no answer', 'Sugriva waits outside for more than a year. At last frothing blood flows out and he hears the cries of enemies but not Vali''s voice. With no view into the cavern and no response from his brother, he concludes that Vali has died. The conclusion is understandable from the available signs, but it remains an inference.'),
  ('scene-cave-seals-a-brothers-fate', 'a-year-produces-only-signs', 'hi', 'प्रतीक्षा को रक्त, शत्रु-गर्जना और मौन मिलता है', 'सुग्रीव गुफा के बाहर एक वर्ष से अधिक प्रतीक्षा करते हैं। अंततः झागदार रक्त निकलता, शत्रुओं की आवाज़ आती, पर वाली की पुकार नहीं। भीतर देखे बिना और भाई का उत्तर पाए बिना वे वाली को मृत मान लेते हैं। उपलब्ध संकेतों से निष्कर्ष समझ आता है, फिर भी वह अनुमान ही है।'),
  ('scene-cave-seals-a-brothers-fate', 'the-stone-closes-more-than-a-cave', 'en', 'Sugriva seals the danger and returns to an unwanted crown', 'Believing the enemy victorious, Sugriva blocks the entrance with a great stone, performs rites for Vali, and returns grieving. Counsellors discover the story and install him despite his attempt to conceal it. Then Vali appears alive, sees Sugriva on the throne, kills or seizes counsellors, and reads the entire sequence as calculated usurpation.'),
  ('scene-cave-seals-a-brothers-fate', 'the-stone-closes-more-than-a-cave', 'hi', 'सुग्रीव संकट बंद कर अनचाहे मुकुट तक लौटते हैं', 'शत्रु को विजयी मानकर सुग्रीव विशाल पत्थर से द्वार बंद करते, वाली के जल-कर्म करते और शोक में लौटते हैं। मंत्रियों को बात पता चलती और वे अनिच्छा के बावजूद उन्हें राजा बनाते हैं। तभी जीवित वाली लौटकर सिंहासन देखता, मंत्रियों पर वार करता और पूरी घटना को योजनाबद्ध सत्ता-हरण मानता है।'),
  ('scene-vali-returns-and-exiles-sugriva', 'sugriva-offers-everything-back', 'en', 'Sugriva treats the crown as a trust to return', 'Sugriva bows, welcomes Vali''s survival, offers back the umbrella, attendants, city, and full kingship, and explains that citizens forced authority on him only to protect a vacant realm. He asks to resume service beneath his elder brother. The account makes restoration possible in practical terms, if not yet emotionally.'),
  ('scene-vali-returns-and-exiles-sugriva', 'sugriva-offers-everything-back', 'hi', 'सुग्रीव मुकुट को लौटाने योग्य न्यास मानते हैं', 'सुग्रीव झुककर वाली के जीवित लौटने का स्वागत करते, छत्र, सेवक, नगर और पूरा राज्य वापस देते और बताते हैं कि खाली राज्य बचाने के लिए नागरिकों ने अधिकार उन पर रखा था। वे फिर ज्येष्ठ भाई की सेवा माँगते हैं। व्यावहारिक रूप से पुनर्स्थापना संभव है, भावनात्मक रूप से अभी नहीं।'),
  ('scene-vali-returns-and-exiles-sugriva', 'vali-tells-the-cave-from-inside', 'en', 'Vali''s survival produces a different chain of intent', 'Before the court, Vali says he fought Mayavi and his companions for a year, then found the exit sealed despite repeatedly calling Sugriva''s name. From inside the cavern, the stone and occupied throne look coordinated. His testimony explains his anger, but the public accusation turns uncertain intent into settled guilt without reconciliation.'),
  ('scene-vali-returns-and-exiles-sugriva', 'vali-tells-the-cave-from-inside', 'hi', 'वाली का जीवित बचना उद्देश्य की दूसरी कड़ी बनाता है', 'दरबार में वाली बताते हैं कि उन्होंने एक वर्ष मायावी और उसके साथियों से युद्ध किया, फिर बार-बार सुग्रीव को पुकारने पर भी द्वार बंद पाया। भीतर से पत्थर और भरा सिंहासन एक योजना जैसे दिखते हैं। गवाही क्रोध समझाती है, पर सार्वजनिक आरोप अनिश्चित उद्देश्य को बिना समाधान पक्का अपराध बना देता है।'),
  ('scene-vali-returns-and-exiles-sugriva', 'punishment-expands-beyond-the-throne', 'en', 'Vali takes kingdom, relationship, and safety', 'Vali rejects Sugriva''s explanation, sends him away with almost nothing, and takes Sugriva''s wife. Sugriva is not merely removed from office; his household, public standing, and ability to remain anywhere safely are broken together. The user can trace each loss separately rather than receiving one generic exile label.'),
  ('scene-vali-returns-and-exiles-sugriva', 'punishment-expands-beyond-the-throne', 'hi', 'वाली राज्य, संबंध और सुरक्षा सब छीनता है', 'वाली सुग्रीव का स्पष्टीकरण अस्वीकारकर उन्हें लगभग खाली हाथ निकाल देता और उनकी पत्नी को अपने अधीन कर लेता है। यह केवल पद से हटाना नहीं; घर, सार्वजनिक सम्मान और कहीं सुरक्षित रहने की क्षमता एक साथ टूटते हैं। उपयोगकर्ता हर हानि अलग देख सकता है, केवल ‘निर्वासन’ लेबल नहीं।'),
  ('scene-vali-returns-and-exiles-sugriva', 'rama-promises-redress', 'en', 'Rama hears a familiar loss and commits to redress', 'Sugriva says he wandered across forests and seas until Matanga''s protected mountain stopped Vali''s pursuit. Rama answers that the one who took his wife and kingdom will fall to his arrows and that Sugriva will recover both. The promise now has a factual history behind it, but still needs a feasible plan against Vali''s strength.'),
  ('scene-vali-returns-and-exiles-sugriva', 'rama-promises-redress', 'hi', 'राम परिचित वियोग सुनकर न्याय का वचन देते हैं', 'सुग्रीव बताते हैं कि वन और समुद्रों में भटकने के बाद मतंग का सुरक्षित पर्वत ही वाली का पीछा रोक सका। राम कहते हैं कि पत्नी और राज्य छीनने वाला उनके बाण से गिरेगा और दोनों लौटेंगे। वचन के पीछे अब घटनाओं का इतिहास है, पर वाली की शक्ति के सामने व्यवहार्य योजना अभी चाहिए।'),
  ('scene-sugriva-measures-valis-strength', 'vali-is-a-scale-not-a-boast', 'en', 'Sugriva explains why ordinary reassurance cannot work', 'Sugriva describes Vali crossing vast distances before sunrise, tossing mountain peaks, and stripping great trees. These claims arrive through a frightened brother and carry epic scale, yet their narrative function is concrete: Sugriva cannot risk another confrontation unless Rama''s promise feels proportionate to the power that has already defeated and hunted him.'),
  ('scene-sugriva-measures-valis-strength', 'vali-is-a-scale-not-a-boast', 'hi', 'सुग्रीव बताते हैं कि सामान्य आश्वासन क्यों पर्याप्त नहीं', 'सुग्रीव वाली के सूर्योदय से पहले विशाल दूरियाँ पार करने, पर्वत-शिखर उछालने और बड़े वृक्ष उजाड़ने की शक्ति बताते हैं। भयभीत भाई की वाणी में महाकाव्यात्मक विस्तार है, पर काम ठोस है—पहले हरा और पीछा कर चुका बल जितना बड़ा हो, राम का वचन उतना विश्वसनीय लगे बिना वे फिर सामना नहीं कर सकते।'),
  ('scene-sugriva-measures-valis-strength', 'dundubhi-brings-war-to-the-gate', 'en', 'A challenger searches until Vali accepts', 'Dundubhi, powerful in buffalo form, challenges the ocean and Himalaya before being directed to Vali. He roars at Kishkindha, tears the ground, and mocks the king before his household. Vali removes his family from danger, accepts the encounter, defeats Dundubhi with body, stones, and trees, and hurls the corpse far away.'),
  ('scene-sugriva-measures-valis-strength', 'dundubhi-brings-war-to-the-gate', 'hi', 'दुंदुभि प्रतिद्वंद्वी खोजते हुए वाली तक पहुँचता है', 'भैंसे के रूप में शक्तिशाली दुंदुभि समुद्र और हिमालय को चुनौती देकर अंततः वाली तक भेजा जाता है। वह किष्किंधा पर गर्जता, भूमि फाड़ता और परिवार के सामने राजा को ललकारता है। वाली परिवार हटाकर युद्ध स्वीकारता, शरीर, पत्थर और वृक्षों से उसे मारकर शव दूर फेंक देता है।'),
  ('scene-sugriva-measures-valis-strength', 'matangas-curse-creates-refuge', 'en', 'Violence outside the hermitage creates a protected boundary', 'Drops from Dundubhi''s body reach Matanga''s hermitage and the thrown mass damages the forest. The sage curses the responsible intruder with death if he returns and orders Vali''s associates away. Vali cannot reverse the decision. That consequence, born from disregard for a protected place, becomes the reason Sugriva can survive at Rishyamuka.'),
  ('scene-sugriva-measures-valis-strength', 'matangas-curse-creates-refuge', 'hi', 'आश्रम के बाहर की हिंसा सुरक्षित सीमा बनाती है', 'दुंदुभि के शव से रक्त मतंग के आश्रम तक पहुँचता और फेंका शरीर वन को हानि करता है। ऋषि लौटने वाले दोषी को मृत्यु का शाप देकर वाली के साथियों को हटाते हैं। वाली निर्णय नहीं बदलवा पाता। संरक्षित स्थान की अवहेलना से निकला यही परिणाम ऋष्यमूक पर सुग्रीव के जीवित रहने का कारण बनता है।'),
  ('scene-sugriva-measures-valis-strength', 'two-tests-replace-blind-faith', 'en', 'Bones and trees make confidence observable', 'Sugriva points to Dundubhi''s skeleton and seven sala trees: move the remains beyond a set distance and pierce a tree as Vali once did. Rama sends the dry skeleton far away with his toe, but Sugriva notes fairly that Vali threw a fresh, heavy body. Doubt is not betrayal; the second test remains necessary.'),
  ('scene-sugriva-measures-valis-strength', 'two-tests-replace-blind-faith', 'hi', 'अस्थियाँ और वृक्ष विश्वास को दृश्य परीक्षा बनाते हैं', 'सुग्रीव दुंदुभि के कंकाल और सात साल वृक्ष दिखाते हैं—अवशेष निश्चित दूरी से पार जाएँ और वृक्ष वाली की तरह भेदा जाए। राम पैर से सूखा कंकाल बहुत दूर भेजते हैं, पर सुग्रीव उचित रूप से कहते हैं कि वाली ने ताज़ा भारी शरीर फेंका था। संदेह विश्वासघात नहीं; दूसरी परीक्षा अभी आवश्यक है।'),
  ('scene-first-challenge-fails-safely', 'one-arrow-closes-the-strength-test', 'en', 'The arrow crosses seven trees and returns', 'Rama draws once. The arrow pierces all seven sala trees, enters mountain and earth, and returns to his quiver. Sugriva''s remaining doubt collapses because the demonstration meets the harder test he requested. Confidence is earned through an observable act, not demanded as proof of friendship or obedience.'),
  ('scene-first-challenge-fails-safely', 'one-arrow-closes-the-strength-test', 'hi', 'बाण सात वृक्ष भेदकर लौटता है', 'राम एक बार धनुष खींचते हैं। बाण सातों साल वृक्ष, पर्वत और धरती भेदकर तरकश में लौटता है। सुग्रीव का बचा संदेह टूटता है क्योंकि प्रदर्शन उनकी माँगी कठिन परीक्षा पूरी करता है। विश्वास मित्रता या आज्ञाकारिता के नाम पर नहीं माँगा, दृश्य कार्य से अर्जित होता है।'),
  ('scene-first-challenge-fails-safely', 'the-first-challenge-outruns-the-plan', 'en', 'Sugriva calls Vali before identification is solved', 'The group reaches Kishkindha and hides near the trees while Sugriva roars a challenge. Vali emerges and the brothers collide with palms and fists. From Rama''s position, their dress, body, motion, voice, and combat are almost identical. The plan has created the encounter before giving the hidden archer a reliable target.'),
  ('scene-first-challenge-fails-safely', 'the-first-challenge-outruns-the-plan', 'hi', 'पहचान सुलझने से पहले सुग्रीव वाली को ललकारते हैं', 'दल किष्किंधा पहुँचकर वृक्षों में छिपता और सुग्रीव गर्जकर चुनौती देते हैं। वाली निकलता है और दोनों भाई हथेलियों-मुट्ठियों से भिड़ते हैं। राम की जगह से वेश, शरीर, चाल, स्वर और युद्ध लगभग समान हैं। योजना ने छिपे धनुर्धर को विश्वसनीय लक्ष्य दिए बिना सामना शुरू कर दिया।'),
  ('scene-first-challenge-fails-safely', 'rama-withholds-the-arrow', 'en', 'Not shooting prevents the promised rescue becoming killing', 'Rama does not release a lethal arrow when he cannot know which brother it will strike. Sugriva is beaten and escapes toward Rishyamuka; Vali stops at the cursed boundary. The choice prevents an irreversible mistake, but safety for Rama also means pain, humiliation, and renewed mistrust for the ally sent into danger.'),
  ('scene-first-challenge-fails-safely', 'rama-withholds-the-arrow', 'hi', 'बाण रोकना बचाव को हत्या बनने से रोकता है', 'किस भाई को बाण लगेगा यह न जानकर राम घातक प्रहार नहीं करते। सुग्रीव पिटकर ऋष्यमूक भागते और वाली शापित सीमा पर रुकता है। निर्णय अपरिवर्तनीय भूल रोकता है, पर राम की सावधानी का मूल्य खतरे में भेजे साथी को पीड़ा, अपमान और नया अविश्वास बनकर मिलता है।'),
  ('scene-first-challenge-fails-safely', 'sugriva-demands-an-account', 'en', 'Failure is confronted and the protocol changes', 'Wounded Sugriva asks why Rama displayed power, urged the challenge, and then left him exposed. Rama explains the resemblance and accepts that another attempt needs a visible distinction. Lakshmana places a flowering gaja creeper around Sugriva''s neck. The alliance does not survive by ignoring failure; it repairs the exact condition that caused it.'),
  ('scene-first-challenge-fails-safely', 'sugriva-demands-an-account', 'hi', 'विफलता का सामना होता और व्यवस्था बदलती है', 'घायल सुग्रीव पूछते हैं कि राम ने शक्ति दिखाकर चुनौती क्यों दिलाई और फिर उन्हें अकेला क्यों छोड़ा। राम समानता समझाकर स्वीकारते हैं कि अगली कोशिश में स्पष्ट पहचान चाहिए। लक्ष्मण सुग्रीव के गले में फूलों वाली गज-लता डालते हैं। मैत्री विफलता अनदेखी करके नहीं, उसके ठीक कारण को सुधारकर बचती है।'),
  ('scene-road-back-passes-seven-sages', 'the-alliance-moves-as-a-party', 'en', 'Sugriva no longer returns alone', 'Sugriva leads from Rishyamuka with Rama and Lakshmana behind him, followed by Hanuman, Nala, Nila, and the vanara leader Tara named in this section. Their order shows both local knowledge and shared risk. The second challenge is not one desperate exile running ahead of an unseen promise; it is a moving alliance.'),
  ('scene-road-back-passes-seven-sages', 'the-alliance-moves-as-a-party', 'hi', 'सुग्रीव अब अकेले नहीं लौटते', 'सुग्रीव ऋष्यमूक से आगे चलते हैं, पीछे राम-लक्ष्मण और फिर हनुमान, नल, नील तथा इस खंड में नामित वानर-नेता तारा हैं। क्रम स्थानीय ज्ञान और साझा जोखिम दोनों दिखाता है। दूसरी चुनौती अदृश्य वचन के आगे भागता अकेला निर्वासित नहीं, चलता हुआ गठबंधन है।'),
  ('scene-road-back-passes-seven-sages', 'landscape-keeps-the-road-lived', 'en', 'The route contains water, animals, danger, and beauty', 'They pass flowering trees, clear rivers, caves, pools filled with lotuses and birds, deer feeding without fear, solitary elephants, and moving groups of vanaras. The journey is not empty distance between dialogue and fight. Its changing ecology gives the player scale, rest points, side observation, and a sense of approaching a populated kingdom.'),
  ('scene-road-back-passes-seven-sages', 'landscape-keeps-the-road-lived', 'hi', 'राह में जल, जीव, संकट और सुंदरता सब हैं', 'वे फूलों वाले वृक्ष, स्वच्छ नदियाँ, गुफाएँ, कमल-पक्षियों से भरे सरोवर, निडर चरते हिरण, अकेले हाथी और चलते वानर समूह पार करते हैं। यात्रा संवाद और युद्ध के बीच खाली दूरी नहीं। बदलती प्रकृति खिलाड़ी को पैमाना, विश्राम, पार्श्व-अवलोकन और आबाद राज्य के निकट आने का अनुभव देती है।'),
  ('scene-road-back-passes-seven-sages', 'seven-sages-remain-beyond-entry', 'en', 'Sugriva explains a hermitage no traveller enters', 'Rama asks about a dense grove. Sugriva says seven disciplined sages once practised there until they rose bodily to heaven; music, fragrance, smoke, and fire still mark the inaccessible enclosure, while creatures entering do not return. The group honours the place from outside rather than converting mystery into a lootable side quest.'),
  ('scene-road-back-passes-seven-sages', 'seven-sages-remain-beyond-entry', 'hi', 'सुग्रीव उस आश्रम की कथा कहते हैं जहाँ यात्री प्रवेश नहीं करते', 'राम घने उपवन के बारे में पूछते हैं। सुग्रीव बताते हैं कि सात संयमी ऋषियों ने वहाँ तप कर देह सहित स्वर्ग प्राप्त किया; संगीत, सुगंध, धुआँ और अग्नि अब भी दुर्गम घेरे को चिह्नित करते हैं, और भीतर गए जीव लौटते नहीं। दल बाहर से सम्मान करता है, रहस्य को लूटने योग्य सहायक खोज नहीं बनाता।'),
  ('scene-road-back-passes-seven-sages', 'kishkindha-enters-view', 'en', 'Respect completed, the contested city appears', 'Rama and Lakshmana bow with focused attention, the party resumes, and fortified Kishkindha comes into sight. Weapons are readied as the environment shifts from sacred quiet to political danger. The pause has not distracted from the mission; it establishes that even an urgent campaign crosses places with claims and boundaries of their own.'),
  ('scene-road-back-passes-seven-sages', 'kishkindha-enters-view', 'hi', 'प्रणाम के बाद विवादित नगर सामने आता है', 'राम-लक्ष्मण एकाग्र होकर प्रणाम करते हैं, दल फिर चलता और दुर्गम किष्किंधा सामने आती है। पवित्र शांति से राजनीतिक संकट की ओर वातावरण बदलते ही शस्त्र तैयार होते हैं। विराम मिशन से भटकाता नहीं; वह दिखाता है कि तात्कालिक अभियान भी अपने दावों और सीमाओं वाले स्थानों से गुजरता है।'),
  ('scene-marked-for-the-second-challenge', 'the-party-hides-with-purpose', 'en', 'Concealment now supports a corrected role', 'The group waits in dense forest outside Vali''s capital. Rama''s hidden position is again part of the plan, but this time the earlier failure is known and addressed. Sugriva is still the visible challenger and bears the immediate risk; the others have an obligation to make their concealed support reliable rather than merely dramatic.'),
  ('scene-marked-for-the-second-challenge', 'the-party-hides-with-purpose', 'hi', 'छिपना अब सुधरी भूमिका का सहारा है', 'दल वाली की राजधानी के बाहर घने वन में प्रतीक्षा करता है। राम की छिपी स्थिति फिर योजना का हिस्सा है, पर पिछली विफलता अब ज्ञात और सुधरी है। सुग्रीव दृश्य चुनौतीकर्ता होकर तत्काल जोखिम उठाते हैं; बाकी साथियों का दायित्व छिपे सहयोग को केवल नाटकीय नहीं, विश्वसनीय बनाना है।'),
  ('scene-marked-for-the-second-challenge', 'sugriva-asks-for-the-promise-again', 'en', 'Trust is restated at the point of danger', 'Looking at Kishkindha''s towers, banners, and gathered vanaras, Sugriva asks Rama to make good the promise spoken at Rishyamuka. He does not treat the seven-tree demonstration as self-executing. The person entering danger seeks confirmation that the corrected plan and the ally behind it are still present now.'),
  ('scene-marked-for-the-second-challenge', 'sugriva-asks-for-the-promise-again', 'hi', 'संकट की जगह पर विश्वास फिर कहा जाता है', 'किष्किंधा के स्वर्ण, ध्वज और वानर समूह देखकर सुग्रीव राम से ऋष्यमूक वाला वचन पूरा करने को कहते हैं। वे सात-वृक्ष प्रदर्शन को अपने-आप काम करने वाला नहीं मानते। खतरे में उतरता व्यक्ति पुष्टि चाहता है कि सुधरी योजना और उसके पीछे का साथी इस क्षण भी मौजूद हैं।'),
  ('scene-marked-for-the-second-challenge', 'rama-checks-the-visible-mark', 'en', 'Rama verifies the condition that failed before', 'Rama points to the flowering creeper Lakshmana placed around Sugriva''s neck and says it makes him distinguishable. He repeats that one arrow will end the fear and asks Sugriva to show Vali. Whatever judgment follows later, this immediate operational promise now includes an identification safeguard rather than confidence alone.'),
  ('scene-marked-for-the-second-challenge', 'rama-checks-the-visible-mark', 'hi', 'राम पिछली विफल शर्त की जाँच करते हैं', 'राम लक्ष्मण की बाँधी फूलों वाली लता दिखाकर कहते हैं कि अब सुग्रीव अलग पहचाने जाएँगे। वे एक बाण से भय समाप्त करने की बात दोहराकर वाली को सामने लाने को कहते हैं। आगे का नैतिक निर्णय जो भी हो, तत्काल योजना में अब केवल विश्वास नहीं, पहचान-सुरक्षा भी है।'),
  ('scene-marked-for-the-second-challenge', 'the-roar-opens-the-next-turn', 'en', 'Sugriva challenges again; the outcome remains ahead', 'Trusting the renewed promise, Sugriva roars until animals scatter and birds fall from their perches. The sound reaches Kishkindha and demands Vali''s response. This turn ends at commitment, not victory: two wounded lives have built an alliance, tested it, repaired a failure, and now cross into the confrontation where its justice and cost will be argued.'),
  ('scene-marked-for-the-second-challenge', 'the-roar-opens-the-next-turn', 'hi', 'सुग्रीव फिर ललकारते हैं; परिणाम अभी आगे है', 'नए वचन पर भरोसा कर सुग्रीव ऐसी गर्जना करते हैं कि पशु बिखरते और पक्षी आसन छोड़ते हैं। ध्वनि किष्किंधा पहुँचकर वाली का उत्तर माँगती है। मोड़ विजय पर नहीं, प्रतिबद्धता पर समाप्त होता है—दो घायल जीवन मैत्री बनाकर, जाँचकर और विफलता सुधारकर उस संघर्ष में प्रवेश करते हैं जहाँ न्याय और मूल्य पर बहस होगी।'),
  ('scene-tara-reads-the-second-roar', 'tara-hears-what-changed', 'en', 'The same voice now carries different confidence', 'Tara notices that Sugriva was beaten only moments earlier yet has returned with a stronger roar. She reasons that he would not challenge again without tested support. Her warning is not mystical foreknowledge: it compares two encounters, detects a changed condition, and asks Vali to delay until the new risk is understood.'),
  ('scene-tara-reads-the-second-roar', 'tara-hears-what-changed', 'hi', 'वही आवाज़ अब अलग आत्मविश्वास लाती है', 'तारा देखती हैं कि अभी-अभी पराजित सुग्रीव अधिक दृढ़ गर्जना के साथ लौटा है। वे तर्क करती हैं कि परखी सहायता के बिना वह फिर चुनौती नहीं देता। उनकी चेतावनी रहस्यमय भविष्यवाणी नहीं—दो मुठभेड़ों की तुलना, बदली परिस्थिति की पहचान और जोखिम समझने तक रुकने की माँग है।'),
  ('scene-tara-reads-the-second-roar', 'angadas-intelligence-has-a-source', 'en', 'Angada brings news gathered through the forest', 'Tara says Angada heard from travelling emissaries that Rama and Lakshmana, princes of Ayodhya, now support Sugriva. Information moves through a living network rather than appearing because the plot needs it. Tara identifies Rama''s reputation and military capacity as a material change Vali must include in his decision.'),
  ('scene-tara-reads-the-second-roar', 'angadas-intelligence-has-a-source', 'hi', 'अंगद वन से जुटी सूचना लाता है', 'तारा बताती हैं कि अंगद ने घूमते दूतों से सुना—अयोध्या के राजकुमार राम और लक्ष्मण अब सुग्रीव के साथ हैं। सूचना कथानक की सुविधा से नहीं, जीवित नेटवर्क से चलती है। तारा राम की प्रतिष्ठा और युद्ध-शक्ति को ऐसा वास्तविक बदलाव मानती हैं जिसे वाली को निर्णय में शामिल करना चाहिए।'),
  ('scene-tara-reads-the-second-roar', 'tara-offers-a-road-without-battle', 'en', 'Reconciliation still has concrete terms', 'Tara proposes restoring Sugriva as heir, honouring him, ending the feud, and making peace with Rama. The alternative is not a vague request to be kind. It redistributes status, acknowledges the younger brother, and converts dangerous outside support into a negotiated alliance before blood is shed.'),
  ('scene-tara-reads-the-second-roar', 'tara-offers-a-road-without-battle', 'hi', 'मेल के पास अभी भी ठोस शर्तें हैं', 'तारा सुग्रीव को युवराज बनाने, सम्मान लौटाने, वैर समाप्त करने और राम से मैत्री का प्रस्ताव देती हैं। विकल्प केवल ‘दयालु बनो’ नहीं है। वह पद बाँटता, छोटे भाई को स्वीकारता और रक्त बहने से पहले बाहरी शक्तिशाली समर्थन को बातचीत की मैत्री में बदलता है।'),
  ('scene-tara-reads-the-second-roar', 'anger-closes-the-counsel-route', 'en', 'Vali treats delay as humiliation', 'Vali hears the warning but experiences Sugriva''s roar before his household as an insult no undefeated warrior can tolerate. Tara''s careful comparison, Angada''s intelligence, and the offer of reconciliation do not satisfy him. He leaves only after information and a concrete alternative have been placed before him.'),
  ('scene-tara-reads-the-second-roar', 'anger-closes-the-counsel-route', 'hi', 'वाली रुकने को अपमान मानता है', 'वाली चेतावनी सुनता है, पर परिवार के सामने सुग्रीव की गर्जना को ऐसा अपमान मानता है जिसे अजेय योद्धा सह नहीं सकता। तारा की सावधान तुलना, अंगद की सूचना और मेल का प्रस्ताव उसे संतुष्ट नहीं करते। वह सूचना और ठोस विकल्प सामने रखे जाने के बाद ही निकलता है।'),
  ('scene-vali-enters-fight-and-arrow-falls', 'vali-promises-less-than-death', 'en', 'Vali says he will defeat, not kill, his brother', 'Vali tells Tara that Rama should not act unjustly and promises only to crush Sugriva''s pride, not take his life. Tara circles him, gives a tearful benediction, and returns inside. His assurance matters later: he walks out confident both in his own reading of Rama and in his ability to control the duel''s limit.'),
  ('scene-vali-enters-fight-and-arrow-falls', 'vali-promises-less-than-death', 'hi', 'वाली भाई को हराने, न मारने की बात कहता है', 'वाली तारा से कहता है कि राम अन्याय नहीं करेंगे और वह सुग्रीव का अभिमान तोड़ेगा, प्राण नहीं लेगा। तारा आँसुओं के साथ परिक्रमा और मंगल-कामना कर भीतर लौटती हैं। यह आश्वासन आगे महत्वपूर्ण है—वह राम की अपनी समझ और द्वंद्व की सीमा नियंत्रित करने के विश्वास के साथ निकलता है।'),
  ('scene-vali-enters-fight-and-arrow-falls', 'brothers-close-with-no-distance', 'en', 'The duel becomes body against body', 'Vali and Sugriva tighten their clothing, close their fists, trade threats, and strike with hands, knees, branches, rocks, and trees. The fight is not an abstract health bar: two brothers with shared strength and history search for each other''s weaknesses at close range while the marked flower garland distinguishes Sugriva from outside.'),
  ('scene-vali-enters-fight-and-arrow-falls', 'brothers-close-with-no-distance', 'hi', 'द्वंद्व शरीर से शरीर का संघर्ष बनता है', 'वाली और सुग्रीव वस्त्र कसते, मुट्ठियाँ बाँधते, ललकारते और हाथ, घुटने, डाल, पत्थर तथा वृक्ष से वार करते हैं। युद्ध केवल स्वास्थ्य-पट्टी नहीं—साझी शक्ति और इतिहास वाले दो भाई निकट से कमजोरी खोजते हैं, जबकि बाहर से पुष्प-चिह्न सुग्रीव को अलग पहचानता है।'),
  ('scene-vali-enters-fight-and-arrow-falls', 'sugriva-spends-the-last-strength', 'en', 'Sugriva weakens and invokes the corrected plan', 'Vali begins to prevail. Sugriva loses strength, suffers blows, and points out his opponent to Rama. Unlike the first challenge, the ally in danger now has both an agreed signal and a visible identity. Rama watches the deterioration and turns from observation to the arrow promised at Rishyamuka.'),
  ('scene-vali-enters-fight-and-arrow-falls', 'sugriva-spends-the-last-strength', 'hi', 'सुग्रीव कमजोर होकर सुधरी योजना का संकेत देता है', 'वाली बढ़त लेता है। सुग्रीव की शक्ति घटती, प्रहार लगते और वह राम को प्रतिद्वंद्वी दिखाता है। पहली चुनौती के विपरीत, संकट में साथी के पास तय संकेत और स्पष्ट पहचान दोनों हैं। राम उसकी गिरती हालत देखकर निरीक्षण से ऋष्यमूक पर वचन दिए बाण की ओर बढ़ते हैं।'),
  ('scene-vali-enters-fight-and-arrow-falls', 'the-hidden-arrow-strikes', 'en', 'Rama releases from outside the duel', 'Rama draws a blazing shaft from concealment and strikes Vali in the chest. Animals scatter at the bowstring; Vali falls bloodied and senseless while the brothers'' combat stops. The distance and surprise do not disappear when the arrow lands, because Vali will awaken and make the unseen attack the centre of his challenge.'),
  ('scene-vali-enters-fight-and-arrow-falls', 'the-hidden-arrow-strikes', 'hi', 'राम द्वंद्व के बाहर से बाण छोड़ते हैं', 'राम ओट से प्रज्वलित बाण खींचकर वाली की छाती में मारते हैं। प्रत्यंचा से पशु भागते, वाली रक्तरंजित और अचेत गिरता और भाइयों का युद्ध रुक जाता है। बाण लगते ही दूरी और आश्चर्य गायब नहीं होते, क्योंकि वाली चेतकर इसी अदृश्य प्रहार को अपने प्रश्न का केंद्र बनाएगा।'),
  ('scene-vali-puts-rama-on-trial', 'vali-speaks-before-anyone-celebrates', 'en', 'The fallen king is alive and demands an answer', 'Rama and Lakshmana approach Vali, who lies wounded but still possesses voice and presence. He does not begin by asking for mercy. He asks what merit Rama gained by killing someone engaged with another opponent. The narrative interrupts any immediate celebration and gives the person struck first control of the ethical frame.'),
  ('scene-vali-puts-rama-on-trial', 'vali-speaks-before-anyone-celebrates', 'hi', 'गिरा राजा जीवित है और उत्तर माँगता है', 'राम और लक्ष्मण घायल पर अभी बोलने और उपस्थिति रखने वाले वाली के पास आते हैं। वह दया नहीं माँगता; पूछता है कि दूसरे से लड़ते व्यक्ति को मारकर राम ने कौन-सा पुण्य पाया। कथा तत्काल उत्सव रोकती और प्रहार झेलने वाले को नैतिक प्रश्न की पहली आवाज़ देती है।'),
  ('scene-vali-puts-rama-on-trial', 'the-hidden-shot-is-the-charge', 'en', 'Vali challenges the method, not only the outcome', 'Vali says he trusted Rama''s reputation for truth, discipline, compassion, and royal conduct, and therefore did not expect an unseen attack while fighting Sugriva. He asks why a prince claiming righteousness used lethal force without open warning or combat. The charge makes reputation itself evidence against the method chosen.'),
  ('scene-vali-puts-rama-on-trial', 'the-hidden-shot-is-the-charge', 'hi', 'वाली परिणाम ही नहीं, तरीके पर प्रश्न करता है', 'वाली कहता है कि उसने राम की सत्य, संयम, करुणा और राजधर्म वाली प्रतिष्ठा पर भरोसा किया, इसलिए सुग्रीव से लड़ते समय अदृश्य प्रहार की आशा नहीं की। वह पूछता है कि धर्म का दावा करने वाले राजकुमार ने खुली चेतावनी या युद्ध बिना घातक बल क्यों प्रयोग किया। प्रतिष्ठा ही चुने तरीके के विरुद्ध प्रमाण बनती है।'),
  ('scene-vali-puts-rama-on-trial', 'jurisdiction-and-injury-are-disputed', 'en', 'Vali asks what authority and injury connected them', 'Vali argues that he neither invaded Rama''s city nor harmed him directly, and questions why human royal power should reach a forest-dwelling vanara in a fraternal dispute. He challenges the categories by which he has been hunted and punished, asking what land, wealth, injury, or declared war made him Rama''s target.'),
  ('scene-vali-puts-rama-on-trial', 'jurisdiction-and-injury-are-disputed', 'hi', 'वाली पूछता है कि कौन-सा अधिकार और अपराध उन्हें जोड़ता था', 'वाली तर्क देता है कि उसने न राम के नगर पर चढ़ाई की, न उन्हें सीधे हानि पहुँचाई, और पूछता है कि भाइयों के विवाद में मानव राजसत्ता वनवासी वानर तक क्यों पहुँचे। वह उन श्रेणियों को चुनौती देता है जिनसे उसका आखेट और दंड हुआ—कौन-सी भूमि, संपत्ति, चोट या घोषित युद्ध ने उसे राम का लक्ष्य बनाया?'),
  ('scene-vali-puts-rama-on-trial', 'vali-names-the-lost-alternative', 'en', 'He says he could have searched for Sita', 'Vali says that, if Rama had stated his need, he could have brought Sita back and seized Ravana. Whether that boast was feasible cannot now be tested, but it exposes a road never attempted: negotiation before killing. Accepting Sugriva''s succession, Vali still asks what answer Rama will give when others question the death.'),
  ('scene-vali-puts-rama-on-trial', 'vali-names-the-lost-alternative', 'hi', 'वह कहता है कि सीता की खोज कर सकता था', 'वाली कहता है कि राम आवश्यकता बताते तो वह सीता को ला और रावण को पकड़ सकता था। यह दावा संभव था या नहीं, अब जाँचा नहीं जा सकता, पर हत्या से पहले बातचीत की अनआजमाई राह दिखाता है। सुग्रीव का उत्तराधिकार स्वीकारकर भी वह पूछता है कि मृत्यु पर प्रश्न होने पर राम क्या उत्तर देंगे।'),
  ('scene-rama-answers-and-angada-emerges', 'rama-claims-royal-reach', 'en', 'Rama answers from a theory of royal jurisdiction', 'Rama says the wider forested land lies under Ikshvaku rule administered by Bharata, and that rulers and their agents must reward or punish conduct across humans, animals, and birds. He presents that royal reach as the authority under which he travels, judges, and acts even while personally living in exile.'),
  ('scene-rama-answers-and-angada-emerges', 'rama-claims-royal-reach', 'hi', 'राम राजकीय अधिकार के सिद्धांत से उत्तर देते हैं', 'राम कहते हैं कि विस्तृत वनभूमि भरत द्वारा संचालित इक्ष्वाकु शासन के अधीन है और शासक तथा उनके प्रतिनिधि मनुष्य, पशु और पक्षियों के आचरण पर दंड-अनुग्रह कर सकते हैं। वे इसी राजकीय पहुँच को वह अधिकार बताते हैं जिसके अंतर्गत वनवास में रहते हुए भी वे यात्रा, निर्णय और कार्रवाई करते हैं।'),
  ('scene-rama-answers-and-angada-emerges', 'ruma-and-the-promise-form-the-case', 'en', 'The core accusation is taking the younger brother''s wife', 'Rama argues that Vali violated the familial duty to treat a younger brother like a son by taking Ruma, and says punishment also fulfils the friendship promise made publicly to restore Sugriva''s wife and kingdom. The response joins an alleged wrong with an obligation already accepted; neither the kinship rule nor promise is hidden.'),
  ('scene-rama-answers-and-angada-emerges', 'ruma-and-the-promise-form-the-case', 'hi', 'मुख्य आरोप छोटे भाई की पत्नी को अपने अधीन करना है', 'राम तर्क देते हैं कि छोटे भाई को पुत्रवत मानने का धर्म तोड़कर वाली ने रूमा को अपने अधीन किया, और दंड सुग्रीव की पत्नी तथा राज्य लौटाने के सार्वजनिक मैत्री-वचन को भी पूरा करता है। उत्तर कथित अपराध और पहले स्वीकृत दायित्व जोड़ता है; न संबंध-नियम छिपता है, न वचन।'),
  ('scene-rama-answers-and-angada-emerges', 'the-hunting-analogy-remains-contestable', 'en', 'A second defence compares the shot with hunting', 'Rama adds that hunters and royal ascetics strike forest animals openly or from ambush and therefore says Vali could be hit whether fighting him or not. The comparison does not answer Vali''s own account of himself as king, brother, husband, and possible ally; it stands as one disputed part of Rama''s wider defence.'),
  ('scene-rama-answers-and-angada-emerges', 'the-hunting-analogy-remains-contestable', 'hi', 'दूसरा बचाव प्रहार की तुलना आखेट से करता है', 'राम आगे कहते हैं कि शिकारी और राजर्षि वन्य जीवों को सामने या ओट से मारते हैं, इसलिए वाली को उनसे लड़ते या न लड़ते प्रहार किया जा सकता था। तुलना वाली के अपने राजा, भाई, पति और संभावित साथी होने के वर्णन का उत्तर नहीं देती; वह राम के व्यापक बचाव का एक विवादित भाग बनी रहती है।'),
  ('scene-rama-answers-and-angada-emerges', 'angada-becomes-the-living-obligation', 'en', 'Vali redirects the argument toward his son', 'Vali accepts Rama''s reply and asks forgiveness for his accusations, but his deepest concern is Angada, young and dependent on Tara. He asks Rama to ensure Sugriva protects both. Rama promises that he and Sugriva will raise Angada with the care Vali gave him, turning justification into a future duty.'),
  ('scene-rama-answers-and-angada-emerges', 'angada-becomes-the-living-obligation', 'hi', 'वाली बहस को अपने पुत्र की ओर मोड़ता है', 'वाली राम का उत्तर स्वीकारकर आरोपों के लिए क्षमा माँगता है, पर उसकी सबसे बड़ी चिंता तारा पर निर्भर युवा अंगद है। वह राम से सुग्रीव द्वारा दोनों की रक्षा सुनिश्चित करने को कहता है। राम वचन देते हैं कि वे और सुग्रीव अंगद को वाली जैसी देखभाल देंगे—औचित्य भविष्य का दायित्व बनता है।'),
  ('scene-tara-crosses-the-fleeing-city', 'news-reaches-the-inner-cave', 'en', 'The battle enters Tara''s world as a report', 'Tara hears that Rama''s arrow has struck Vali and leaves the inner mountain with Angada. She encounters followers already fleeing at the sight of Rama''s bow. The king''s fall travels faster than any settled account of what follows, so fear begins reorganising the city before Vali''s condition or succession has been collectively faced.'),
  ('scene-tara-crosses-the-fleeing-city', 'news-reaches-the-inner-cave', 'hi', 'युद्ध तारा की दुनिया में समाचार बनकर आता है', 'तारा सुनती हैं कि राम का बाण वाली को लगा और अंगद के साथ भीतरी पर्वत से निकलती हैं। उन्हें राम का धनुष देखकर भागते अनुयायी मिलते हैं। राजा के गिरने की खबर आगे की किसी स्थिर योजना से तेज चलती है, इसलिए वाली की स्थिति या उत्तराधिकार का सामूहिक सामना होने से पहले भय नगर को पुनर्गठित करने लगता है।'),
  ('scene-tara-crosses-the-fleeing-city', 'fleeing-vanaras-see-a-power-vacuum', 'en', 'The first responders fear invasion and retaliation', 'The vanaras urge Tara to return, secure the stronghold, and install Angada before rivals exploit the vacuum. Their advice reveals households, lost wealth, and old enmities inside Vali''s kingdom. The city is not one cheering population awaiting a new ruler; different groups calculate safety as royal protection disappears.'),
  ('scene-tara-crosses-the-fleeing-city', 'fleeing-vanaras-see-a-power-vacuum', 'hi', 'पहले उत्तरदाता आक्रमण और प्रतिशोध से डरते हैं', 'वानर तारा से लौटकर दुर्ग सुरक्षित करने और प्रतिद्वंद्वी शून्य का लाभ लें उससे पहले अंगद को स्थापित करने को कहते हैं। उनकी बात वाली के राज्य के भीतर परिवार, खोया धन और पुराने वैर दिखाती है। नगर नया राजा चाहती एक जयकार करती भीड़ नहीं; राजकीय सुरक्षा हटते ही अलग समूह अपनी सुरक्षा गिनते हैं।'),
  ('scene-tara-crosses-the-fleeing-city', 'tara-refuses-power-as-first-aid', 'en', 'Tara chooses Vali over immediate rule', 'Tara says that with Vali fallen, kingdom, son, and her own safety cannot be her first destination. She will go to him. This does not deny Angada''s importance; it refuses to use his installation to bypass the human reality of the death. Political continuity must wait long enough for truth and grief to be encountered.'),
  ('scene-tara-crosses-the-fleeing-city', 'tara-refuses-power-as-first-aid', 'hi', 'तारा तत्काल शासन से पहले वाली को चुनती हैं', 'तारा कहती हैं कि वाली के गिरने पर राज्य, पुत्र और अपनी सुरक्षा उनकी पहली मंज़िल नहीं हो सकते; वे उसके पास जाएँगी। यह अंगद का महत्व नहीं नकारता, बल्कि उसकी स्थापना से मृत्यु की मानवीय सच्चाई को पार करने से इंकार है। राजनीतिक निरंतरता को सत्य और शोक से मिलने जितना रुकना होगा।'),
  ('scene-tara-crosses-the-fleeing-city', 'tara-crosses-every-party', 'en', 'She passes the victors and reaches the fallen', 'Tara passes Rama, Lakshmana, and Sugriva and finds Vali on the ground. She loses consciousness, rises, and cries out; Angada and the gathered community join the grief. Sugriva, seeing the family before the body, is no longer able to experience the fulfilled promise only as liberation.'),
  ('scene-tara-crosses-the-fleeing-city', 'tara-crosses-every-party', 'hi', 'वह विजयी पक्षों को पार कर गिरे हुए तक पहुँचती हैं', 'तारा राम, लक्ष्मण और सुग्रीव को पार कर भूमि पर पड़े वाली तक पहुँचती हैं। वे अचेत होकर उठती और पुकारती हैं; अंगद तथा समुदाय शोक में जुड़ते हैं। परिवार को शव के सामने देखकर सुग्रीव पूरा हुआ वचन केवल मुक्ति की तरह अनुभव नहीं कर सकता।'),
  ('scene-tara-laments-before-the-fallen-king', 'tara-speaks-to-silence', 'en', 'She addresses husband and king as if response were still possible', 'Tara embraces Vali and asks why he does not welcome her, why a king lies on bare earth, and why their shared forest life has ended without farewell. She recalls fragrant groves, private happiness, and the authority with which he once answered every gathering. None of those memories can make the silent body respond.'),
  ('scene-tara-laments-before-the-fallen-king', 'tara-speaks-to-silence', 'hi', 'वह पति और राजा से ऐसे बोलती हैं जैसे उत्तर अभी संभव हो', 'तारा वाली को गले लगाकर पूछती हैं कि वह स्वागत क्यों नहीं करता, राजा नंगी धरती पर क्यों पड़ा है और उनका साझा वन-जीवन बिना विदाई क्यों समाप्त हुआ। वे सुगंधित उपवन, निजी सुख और हर सभा को उत्तर देने वाली उसकी सत्ता याद करती हैं। कोई स्मृति मौन शरीर से उत्तर नहीं दिला सकती।'),
  ('scene-tara-laments-before-the-fallen-king', 'love-does-not-erase-causation', 'en', 'Tara names the wrong and the ignored warning', 'Tara says Vali''s seizure of Sugriva''s wife and exile led to this result, and that he ignored counsel intended for his welfare. She also condemns Rama''s timing and method. Grief does not force her into one loyal simplification: she can love Vali, recognise his responsibility, and still challenge the act that killed him.'),
  ('scene-tara-laments-before-the-fallen-king', 'love-does-not-erase-causation', 'hi', 'तारा भूल और अनसुनी चेतावनी दोनों कहती हैं', 'तारा कहती हैं कि सुग्रीव की पत्नी को अपने अधीन करना और उसे निकालना इस परिणाम तक लाया, और वाली ने हित की सलाह नहीं सुनी। वे राम के समय और तरीके की भी निंदा करती हैं। शोक उन्हें एक सरल निष्ठा में नहीं बाँधता—वह वाली से प्रेम, उसकी जिम्मेदारी की पहचान और हत्या पर प्रश्न साथ रखती हैं।'),
  ('scene-tara-laments-before-the-fallen-king', 'angadas-future-enters-the-lament', 'en', 'A child must face a court transformed by his father''s death', 'Tara calls Angada to look one last time and asks how his angry uncle will treat a young heir raised in privilege. She asks Vali to bless and instruct the son who can no longer receive either. Angada''s future is not a later governance checkbox; it enters the grief at the instant paternal protection disappears.'),
  ('scene-tara-laments-before-the-fallen-king', 'angadas-future-enters-the-lament', 'hi', 'पिता की मृत्यु से बदले दरबार का सामना पुत्र को करना है', 'तारा अंगद को अंतिम बार देखने बुलाती और पूछती हैं कि क्रोधित चाचा सुख में पले युवा उत्तराधिकारी से कैसा व्यवहार करेगा। वे वाली से उस पुत्र को आशीष और निर्देश माँगती हैं जो अब दोनों नहीं पा सकता। अंगद का भविष्य बाद का शासन-चेकबॉक्स नहीं; पिता की सुरक्षा मिटते ही शोक में प्रवेश करता है।'),
  ('scene-tara-laments-before-the-fallen-king', 'no-one-receives-a-clean-victory', 'en', 'Tara confronts Sugriva and Rama with the cost', 'Tara tells Sugriva that he may regain Ruma and rule without fear, but speaks those gains beside the brother''s body. She asks why Rama does not relent after the hidden shot and resolves to remain with Vali. Her words make the achieved objective inseparable from the household and community it has broken.'),
  ('scene-tara-laments-before-the-fallen-king', 'no-one-receives-a-clean-victory', 'hi', 'तारा सुग्रीव और राम को मूल्य के सामने खड़ा करती हैं', 'तारा सुग्रीव से कहती हैं कि वह रूमा को पाकर निर्भय राज्य कर सकता है, पर ये लाभ भाई के शव के पास कहती हैं। वे पूछती हैं कि छिपे प्रहार के बाद राम क्यों नहीं पिघलते और वाली के पास रहने का निश्चय करती हैं। उनकी वाणी प्राप्त लक्ष्य को टूटे परिवार और समुदाय से अलग नहीं होने देती।'),
  ('scene-hanuman-offers-duty-tara-refuses-throne', 'hanuman-consoles-from-his-worldview', 'en', 'Hanuman answers grief with impermanence and action', 'Hanuman tells Tara that embodied life is unstable and actions bear consequences, urging her to turn toward what remains. His words do not make her loss smaller or end the mourning around Vali. They introduce a different pressure: Angada, the community, and the unperformed rites still depend on decisions from the living.'),
  ('scene-hanuman-offers-duty-tara-refuses-throne', 'hanuman-consoles-from-his-worldview', 'hi', 'हनुमान अनित्यता और कर्म से शोक का उत्तर देते हैं', 'हनुमान तारा से कहते हैं कि देहधारी जीवन अस्थिर है और कर्म फल देते हैं, इसलिए जो बचा है उसकी ओर मुड़ें। उनकी वाणी हानि छोटी नहीं करती, न वाली के आसपास का शोक समाप्त। वह दूसरी आवश्यकता सामने लाती है—अंगद, समुदाय और बाकी संस्कार अब भी जीवितों के निर्णय पर निर्भर हैं।'),
  ('scene-hanuman-offers-duty-tara-refuses-throne', 'angada-and-rites-cannot-wait-forever', 'en', 'Care, funeral, and continuity require decisions', 'Hanuman points to Angada, the waiting community, Vali''s funeral rites, and the vacant rule. He proposes that Angada perform a son''s ceremonies and be installed. These are distinct needs—care for a young person, honour for the dead, and political stability—not one argument that a crown will cure sorrow.'),
  ('scene-hanuman-offers-duty-tara-refuses-throne', 'angada-and-rites-cannot-wait-forever', 'hi', 'देखभाल, अंत्येष्टि और निरंतरता को निर्णय चाहिए', 'हनुमान अंगद, प्रतीक्षारत समुदाय, वाली की अंत्येष्टि और खाली शासन की ओर संकेत करते हैं। वे अंगद से पुत्र-कर्म और उसके राज्यारोहण का प्रस्ताव रखते हैं। ये अलग आवश्यकताएँ हैं—युवा की देखभाल, मृत का सम्मान और राजनीतिक स्थिरता—यह दावा नहीं कि मुकुट शोक ठीक कर देगा।'),
  ('scene-hanuman-offers-duty-tara-refuses-throne', 'tara-refuses-an-authority-she-does-not-claim', 'en', 'Tara says succession belongs with Sugriva', 'Tara says she cannot govern or confer the kingdom on Angada and that the authority now falls to his uncle Sugriva. Her refusal is political judgment, not lack of intelligence—the previous scene has already established her as the clearest strategist. She will not use emergency grief to manufacture a legitimacy she does not accept.'),
  ('scene-hanuman-offers-duty-tara-refuses-throne', 'tara-refuses-an-authority-she-does-not-claim', 'hi', 'तारा कहती हैं कि उत्तराधिकार सुग्रीव के पास है', 'तारा कहती हैं कि वह न शासन कर सकती हैं, न अंगद को राज्य दे सकतीं; अधिकार अब उसके चाचा सुग्रीव के पास है। यह राजनीतिक निर्णय है, बुद्धि का अभाव नहीं—पहला दृश्य उन्हें सबसे स्पष्ट रणनीतिक आवाज़ बना चुका है। वे आपात शोक से ऐसी वैधता नहीं गढ़ेंगी जिसे नहीं मानतीं।'),
  ('scene-hanuman-offers-duty-tara-refuses-throne', 'grief-cannot-yet-be-instrumentalised', 'en', 'Tara remains with Vali before accepting a public role', 'Tara says that neither many sons nor a kingdom can replace the husband before her and chooses to remain at his side. She cannot yet imagine public duty as a reason to leave him. Hanuman''s proposals remain unanswered, leaving Angada, Sugriva, and the surrounding community responsible for care until she can choose again.'),
  ('scene-hanuman-offers-duty-tara-refuses-throne', 'grief-cannot-yet-be-instrumentalised', 'hi', 'तारा सार्वजनिक भूमिका से पहले वाली के पास रहती हैं', 'तारा कहती हैं कि अनेक पुत्र या राज्य सामने पड़े पति का स्थान नहीं ले सकते और उसके पास रहने को चुनती हैं। वह अभी सार्वजनिक कर्तव्य को उससे दूर जाने का कारण नहीं मान सकतीं। हनुमान के प्रस्ताव अनुत्तरित रहते हैं, इसलिए अंगद, सुग्रीव और समुदाय पर देखभाल की जिम्मेदारी रहती है जब तक वह फिर चुनाव कर सकें।'),
  ('scene-vali-entrusts-angada-and-dies', 'vali-apologises-to-sugriva', 'en', 'The brothers speak after hostility has lost its future', 'Vali calls Sugriva close and asks him not to carry the elder brother''s wrongful conduct forever. He says fate did not allow them to hold kingdom and fraternal affection together. The apology does not undo exile, seizure, fear, or death; it creates a final acknowledgment from the person who caused much of that harm.'),
  ('scene-vali-entrusts-angada-and-dies', 'vali-apologises-to-sugriva', 'hi', 'भाई तब बोलते हैं जब वैर का भविष्य समाप्त हो चुका है', 'वाली सुग्रीव को पास बुलाकर कहता है कि बड़े भाई के अनुचित आचरण को सदा हृदय में न रखे। वह मानता है कि भाग्य ने उन्हें राज्य और भाईचारा साथ नहीं दिया। क्षमा निर्वासन, हरण, भय या मृत्यु नहीं मिटाती; वह बहुत हानि करने वाले व्यक्ति की अंतिम स्वीकारोक्ति बनती है।'),
  ('scene-vali-entrusts-angada-and-dies', 'angada-is-entrusted-as-a-son', 'en', 'Sugriva receives a parental obligation', 'Vali asks Sugriva to maintain Angada as his own son, satisfy his needs, remove fear, and recognise his future courage in the search against the rakshasas. This is not only a succession request. It binds the new ruler to protect the child whose position his victory has made most dangerous.'),
  ('scene-vali-entrusts-angada-and-dies', 'angada-is-entrusted-as-a-son', 'hi', 'सुग्रीव को पिता जैसा दायित्व मिलता है', 'वाली सुग्रीव से अंगद को अपने पुत्र की तरह पालने, आवश्यकताएँ पूरी करने, भय हटाने और राक्षसों के विरुद्ध उसकी भविष्य की वीरता पहचानने को कहता है। यह केवल उत्तराधिकार निवेदन नहीं; नई सत्ता को उस बच्चे की रक्षा से बाँधता है जिसकी स्थिति विजय ने सबसे जोखिमपूर्ण बनाई।'),
  ('scene-vali-entrusts-angada-and-dies', 'tara-and-the-garland-transfer', 'en', 'Counsel and royal fortune are handed onward', 'Vali tells Sugriva to trust Tara''s judgment in danger because her counsel does not fail, and to honour the obligation owed to Rama. He then gives Sugriva the golden garland associated with his vitality and royal fortune. The transfer recognises Tara as continuing intelligence, not merely a widow attached to the former reign.'),
  ('scene-vali-entrusts-angada-and-dies', 'tara-and-the-garland-transfer', 'hi', 'सलाह और राजलक्ष्मी आगे सौंपी जाती हैं', 'वाली सुग्रीव से संकट में तारा की बुद्धि पर भरोसा करने को कहता है क्योंकि उनकी सलाह निष्फल नहीं, और राम का दायित्व निभाने को भी कहता है। फिर वह अपनी जीवन-शक्ति और राजलक्ष्मी से जुड़ी स्वर्णमाला देता है। हस्तांतरण तारा को केवल पूर्व राजा की विधवा नहीं, जारी बुद्धि मानता है।'),
  ('scene-vali-entrusts-angada-and-dies', 'angada-hears-how-to-survive-the-new-court', 'en', 'A father''s last advice is adaptation, not entitlement', 'Vali tells Angada to accept Sugriva''s authority, read time and place, endure hardship, avoid both excessive intimacy and hostile distance, and serve the new order carefully. Then he dies and the community cries out. The counsel reveals how uncertain the young heir''s safety remains even after public promises of protection.'),
  ('scene-vali-entrusts-angada-and-dies', 'angada-hears-how-to-survive-the-new-court', 'hi', 'पिता की अंतिम सीख अधिकार नहीं, अनुकूलन है', 'वाली अंगद से सुग्रीव का अधिकार मानने, समय-स्थान समझने, कठिनाई सहने, न अत्यधिक निकटता न शत्रुतापूर्ण दूरी रखने और नई व्यवस्था सावधानी से निभाने को कहता है। फिर वह मरता और समुदाय रोता है। सीख दिखाती है कि सार्वजनिक सुरक्षा-वचनों के बाद भी युवा उत्तराधिकारी की स्थिति कितनी अनिश्चित है।'),
  ('scene-tara-and-angada-say-goodbye', 'tara-keeps-addressing-vali', 'en', 'Words continue after the last breath', 'Tara smells Vali''s face and asks why he lies on rough ground after rejecting her counsel. She speaks of widowhood, broken honour, the community''s cries, and the battle-bed where his former enemies once lay. Her lament changes as death becomes certain, but relationship still structures every observation.'),
  ('scene-tara-and-angada-say-goodbye', 'tara-keeps-addressing-vali', 'hi', 'अंतिम साँस के बाद भी शब्द चलते हैं', 'तारा वाली का मुख सूँघकर पूछती हैं कि उनकी सलाह ठुकराने के बाद वह कठोर भूमि पर क्यों पड़ा है। वे विधवापन, टूटे सम्मान, समुदाय के रोने और उस रण-शय्या की बात करती हैं जहाँ कभी उसके शत्रु पड़े थे। मृत्यु निश्चित होते ही विलाप बदलता है, पर हर अवलोकन संबंध से बना है।'),
  ('scene-tara-and-angada-say-goodbye', 'nila-removes-the-arrow', 'en', 'The weapon is removed from the body', 'Tara says the arrow prevents her from embracing Vali. Nila draws it out, and blood flows from the wound. The act is physical care and evidence handling, not spectacle. Rama''s weapon remains identifiable after removal, preserving the connection between distant shot, ethical dispute, bodily injury, and funeral preparation.'),
  ('scene-tara-and-angada-say-goodbye', 'nila-removes-the-arrow', 'hi', 'शरीर से बाण निकाला जाता है', 'तारा कहती हैं कि बाण उन्हें वाली को गले लगाने से रोकता है। नील उसे निकालता और घाव से रक्त बहता है। यह शारीरिक देखभाल और प्रमाण-संभाल है, तमाशा नहीं। निकला हुआ राम का अस्त्र पहचान योग्य रहता है, जिससे दूर का प्रहार, नैतिक बहस, देह की चोट और अंत्येष्टि-तैयारी जुड़े रहते हैं।'),
  ('scene-tara-and-angada-say-goodbye', 'tara-cleans-what-war-left', 'en', 'Tears and touch replace combat motion', 'Tara washes dust and blood from Vali with her tears and calls Angada to see the end of his father''s conflict. Care work changes the battlefield''s function: a place built for strikes becomes one where family prepares the dead for farewell. Weapons lower, bodies gather, and the cost of violence becomes the only movement left.'),
  ('scene-tara-and-angada-say-goodbye', 'tara-cleans-what-war-left', 'hi', 'युद्ध की गति की जगह आँसू और स्पर्श लेते हैं', 'तारा आँसुओं से वाली के शरीर की धूल और रक्त साफ करतीं और अंगद को पिता के वैर का अंत देखने बुलाती हैं। देखभाल रणभूमि का काम बदल देती है—वार की जगह परिवार मृतक को विदाई के लिए तैयार करता है। शस्त्र झुकते, लोग पास आते और हिंसा का मूल्य ही बची हुई गति बनता है।'),
  ('scene-tara-and-angada-say-goodbye', 'angada-bows-without-a-blessing', 'en', 'The son touches feet that cannot answer', 'Angada embraces Vali''s feet, but the familiar blessing does not come. Tara names that silence and notices the royal garland is gone, already transferred to Sugriva. The child encounters two absences at once: his father''s voice and the symbol of rule that once made their household the centre of Kishkindha.'),
  ('scene-tara-and-angada-say-goodbye', 'angada-bows-without-a-blessing', 'hi', 'पुत्र उन चरणों में झुकता है जो उत्तर नहीं दे सकते', 'अंगद वाली के चरण पकड़ता है, पर परिचित आशीर्वाद नहीं आता। तारा उस मौन को कहतीं और देखती हैं कि राजमाला जा चुकी है, सुग्रीव को सौंप दी गई। पुत्र एक साथ दो अनुपस्थितियों से मिलता है—पिता की आवाज़ और वह शासन-चिह्न जिसने उनके घर को किष्किंधा का केंद्र बनाया था।'),
  ('scene-victory-turns-to-remorse', 'sugriva-cannot-enjoy-the-fulfilled-promise', 'en', 'The regained kingdom no longer feels like the desired object', 'Sugriva approaches Rama and says the promise has been fulfilled, yet Tara, Angada, subjects, and the dead brother make enjoyment impossible. He recalls preferring bare survival at Rishyamuka to a kingdom purchased at this cost. Liberation from pursuit has arrived together with responsibility for the death that enabled it.'),
  ('scene-victory-turns-to-remorse', 'sugriva-cannot-enjoy-the-fulfilled-promise', 'hi', 'लौटा राज्य अब चाही वस्तु जैसा नहीं लगता', 'सुग्रीव राम के पास कहता है कि वचन पूरा हुआ, फिर भी तारा, अंगद, प्रजा और मृत भाई राज्य-सुख असंभव बनाते हैं। वह याद करता है कि इस मूल्य पर मिले राज्य से ऋष्यमूक का साधारण जीवन बेहतर था। पीछा से मुक्ति उसी मृत्यु की जिम्मेदारी के साथ आई है जिसने उसे संभव किया।'),
  ('scene-victory-turns-to-remorse', 'memory-complicates-sugrivas-blame', 'en', 'He remembers that Vali once spared him', 'Sugriva recalls Vali ending the first duel without killing him and now judges his own desire for death more harshly. His remorse may idealise the brother after loss, but it also records moral agency: he does not hide behind Rama''s arrow or the earlier wrongs. He asks whether rule can be legitimate without facing his part.'),
  ('scene-victory-turns-to-remorse', 'memory-complicates-sugrivas-blame', 'hi', 'उसे याद आता है कि वाली ने कभी उसे छोड़ दिया था', 'सुग्रीव याद करता है कि पहली लड़ाई में वाली ने उसे जीवित छोड़ा और अब अपनी मृत्यु-कामना को अधिक कठोरता से देखता है। शोक भाई को आदर्श बना सकता है, फिर भी यह नैतिक जिम्मेदारी दर्ज करता है—वह राम के बाण या पुराने अपराधों के पीछे नहीं छिपता। वह पूछता है कि अपनी भूमिका का सामना बिना शासन वैध कैसे होगा।'),
  ('scene-victory-turns-to-remorse', 'despair-spreads-through-the-survivors', 'en', 'Sugriva and Tara both ask to leave life', 'Sugriva asks to enter fire, imagining the search can continue without him. Tara comes to Rama and asks to be killed by the same arrow so she can rejoin Vali. Rama does not grant either request. His tears and silence acknowledge that the promised victory has produced a crisis among the people who survived it.'),
  ('scene-victory-turns-to-remorse', 'despair-spreads-through-the-survivors', 'hi', 'सुग्रीव और तारा दोनों जीवन छोड़ने की बात कहते हैं', 'सुग्रीव अग्नि में जाने की अनुमति माँगता, मानता है कि खोज उसके बिना चल सकती है। तारा राम से उसी बाण से मारकर वाली के पास भेजने को कहती हैं। राम किसी माँग को स्वीकार नहीं करते। उनके आँसू और मौन मानते हैं कि वचन की विजय ने बचे लोगों के बीच गहरा संकट बनाया है।'),
  ('scene-victory-turns-to-remorse', 'rama-points-to-angadas-living-future', 'en', 'The answer is protection and a future role', 'Rama refuses Tara''s request and says Angada will become heir, asking her not to lose herself. His language invokes divine ordering and heroic endurance from the source, but the actionable commitment is earthly: keep Tara alive, protect Angada, and create a political future in which the child is not erased by his uncle''s victory.'),
  ('scene-victory-turns-to-remorse', 'rama-points-to-angadas-living-future', 'hi', 'उत्तर सुरक्षा और भविष्य की भूमिका है', 'राम तारा की माँग अस्वीकारकर कहते हैं कि अंगद युवराज होगा और उनसे स्वयं को न खोने को कहते हैं। स्रोत की भाषा दैवी व्यवस्था और वीर-सहनशीलता लेती है, पर क्रियात्मक वचन सांसारिक है—तारा को जीवित रखना, अंगद की रक्षा और ऐसा राजनीतिक भविष्य बनाना जिसमें चाचा की विजय पुत्र को न मिटाए।'),
  ('scene-kishkindha-carries-vali-to-fire', 'time-for-rites-is-spoken-not-assumed', 'en', 'Rama redirects lament toward appointed action', 'Rama tells Tara, Angada, and Sugriva that tears have expressed worldly grief and funeral duties should no longer be delayed. He speaks of Time and the consequences of prior action, then returns to the immediate responsibility before them: Vali''s body and the gathered mourners now need organised care.'),
  ('scene-kishkindha-carries-vali-to-fire', 'time-for-rites-is-spoken-not-assumed', 'hi', 'राम विलाप को नियत कर्म की ओर मोड़ते हैं', 'राम तारा, अंगद और सुग्रीव से कहते हैं कि आँसू सांसारिक शोक व्यक्त कर चुके और अंत्येष्टि अब नहीं टलनी चाहिए। वे काल और पूर्वकर्म के परिणाम की बात कर फिर सामने की जिम्मेदारी पर लौटते हैं—वाली की देह और जुटे शोकाकुलों को अब संगठित देखभाल चाहिए।'),
  ('scene-kishkindha-carries-vali-to-fire', 'lakshmana-organises-the-work', 'en', 'Grief receives materials, roles, and sequence', 'Lakshmana asks Sugriva to gather dry wood and sandal, Angada to bring cloth, garlands, scents, ghee, and oil, Tara to obtain the bier, and strong vanaras to carry it. Naming roles prevents ritual from becoming decorative montage. Each mourner has work proportionate to relationship and capacity.'),
  ('scene-kishkindha-carries-vali-to-fire', 'lakshmana-organises-the-work', 'hi', 'शोक को सामग्री, भूमिकाएँ और क्रम मिलता है', 'लक्ष्मण सुग्रीव से सूखी लकड़ी और चंदन, अंगद से वस्त्र, माला, सुगंध, घी और तेल, तारा से अर्थी और समर्थ वानरों से उसे उठाने को कहते हैं। भूमिकाएँ संस्कार को सजावटी दृश्य बनने से रोकती हैं। हर शोकाकुल को संबंध और क्षमता के अनुरूप काम मिलता है।'),
  ('scene-kishkindha-carries-vali-to-fire', 'the-city-walks-behind-its-king', 'en', 'The bier turns mourning into a public procession', 'Vali is placed on an ornamented, flower-covered conveyance. Vanaras scatter royal gifts ahead; counsellors, subjects, Tara, Angada, Sugriva, and the other women follow through hills and forest. Tara keeps speaking to Vali from the bier. The kingdom does not switch rulers in private while its former king disappears off-screen.'),
  ('scene-kishkindha-carries-vali-to-fire', 'the-city-walks-behind-its-king', 'hi', 'अर्थी शोक को सार्वजनिक यात्रा बनाती है', 'वाली को अलंकृत, पुष्पों से ढकी अर्थी पर रखा जाता है। आगे वानर राजकीय दान बिखेरते; पीछे मंत्री, प्रजा, तारा, अंगद, सुग्रीव और अन्य स्त्रियाँ पहाड़-वन से चलती हैं। तारा अर्थी पर वाली से बोलती रहती हैं। राज्य निजी रूप से राजा बदलकर पुराने राजा को पर्दे के बाहर गायब नहीं करता।'),
  ('scene-kishkindha-carries-vali-to-fire', 'angada-lights-and-community-offers-water', 'en', 'The son completes fire; the community completes water', 'At a waterside clearing, Angada and Sugriva place Vali on the pyre. Angada lights it and circles his father; afterward the mourners go to the river and offer water with Angada in front. Rama and Lakshmana remain participants in the sorrow, but the family and Kishkindha community perform the central acts.'),
  ('scene-kishkindha-carries-vali-to-fire', 'angada-lights-and-community-offers-water', 'hi', 'पुत्र अग्नि देता; समुदाय जलांजलि पूरी करता है', 'जल के पास खुले स्थान पर अंगद और सुग्रीव वाली को चिता पर रखते हैं। अंगद अग्नि देकर पिता की परिक्रमा करता; फिर शोकाकुल नदी जाकर अंगद को आगे रख जलांजलि देते हैं। राम-लक्ष्मण शोक में सहभागी हैं, पर मुख्य कर्म परिवार और किष्किंधा समुदाय करते हैं।'),
  ('scene-crown-and-heir-under-rains', 'rama-keeps-the-exile-boundary', 'en', 'Rama will direct the transition but not enter the city', 'Hanuman invites Rama to enter Kishkindha and preside over Sugriva''s installation. Rama refuses because his father''s fourteen-year command bars him from towns and cities. Helping one ruler take power does not suspend the vow governing his own conduct. He remains outside in a mountain cave with Lakshmana.'),
  ('scene-crown-and-heir-under-rains', 'rama-keeps-the-exile-boundary', 'hi', 'राम परिवर्तन निर्देशित करेंगे, नगर में प्रवेश नहीं', 'हनुमान राम को किष्किंधा आकर सुग्रीव के राज्यारोहण का नेतृत्व करने बुलाते हैं। राम मना करते हैं क्योंकि पिता की चौदह-वर्षीय आज्ञा उन्हें नगरों से दूर रखती है। एक शासक को सत्ता दिलाना अपने आचरण वाला वचन निलंबित नहीं करता। वे लक्ष्मण के साथ बाहर पर्वत-गुफा में रहते हैं।'),
  ('scene-crown-and-heir-under-rains', 'king-and-heir-are-installed-together', 'en', 'Succession includes Angada in the new order', 'Rama instructs Sugriva to install Angada as heir because Vali''s eldest son is worthy. Inside Kishkindha, the community welcomes Sugriva, gathers ritual water and regalia, and installs him; Sugriva then embraces Angada and confers the heirship. Victory does not make Vali''s line politically disappear.'),
  ('scene-crown-and-heir-under-rains', 'king-and-heir-are-installed-together', 'hi', 'नई व्यवस्था में अंगद भी स्थापित होता है', 'राम सुग्रीव से वाली के योग्य ज्येष्ठ पुत्र अंगद को युवराज बनाने कहते हैं। किष्किंधा में समुदाय सुग्रीव का स्वागत कर अभिषेक-जल और राजचिह्न जुटाकर उन्हें स्थापित करता; फिर सुग्रीव अंगद को गले लगाकर युवराज पद देता है। विजय वाली की वंश-रेखा को राजनीतिक रूप से गायब नहीं करती।'),
  ('scene-crown-and-heir-under-rains', 'monsoon-closes-the-search-roads', 'en', 'Season limits movement without ending urgency', 'The month of Shravana begins the four rainy months. Rama says this is not the time for a physical search and plans to remain in the mountain cave until Kartika. The pause is deterministic season and terrain logic, not loss of interest in Sita. A dated obligation to resume is attached to the alliance.'),
  ('scene-crown-and-heir-under-rains', 'monsoon-closes-the-search-roads', 'hi', 'ऋतु मार्ग रोकती है, तात्कालिकता नहीं', 'श्रावण से चार वर्षा-मास शुरू होते हैं। राम कहते हैं कि भौतिक खोज का समय नहीं और कार्तिक तक पर्वत-गुफा में रहेंगे। विराम ऋतु और भू-मार्ग का निश्चित तर्क है, सीता में रुचि का अंत नहीं। मैत्री के साथ फिर शुरू करने का समयबद्ध दायित्व जुड़ता है।'),
  ('scene-crown-and-heir-under-rains', 'restoration-creates-the-next-debt', 'en', 'Sugriva regains kingdom and Ruma, then owes action', 'Sugriva is crowned, Ruma returns to his household, friends celebrate, and the city raises flags. These restorations complete his side of the original exchange but do not complete the alliance. After the rains he must organise the search and confront Ravana''s reach; the next turn will test whether power remembers the promise that enabled it.'),
  ('scene-crown-and-heir-under-rains', 'restoration-creates-the-next-debt', 'hi', 'सुग्रीव राज्य और रूमा पाकर अब कार्रवाई का ऋणी है', 'सुग्रीव का राज्यारोहण होता, रूमा घर लौटतीं, मित्र उत्सव करते और नगर ध्वज उठाता है। ये वापसी मूल विनिमय में उसके पक्ष को पूरा करती हैं, मैत्री को नहीं। वर्षा बाद उसे खोज संगठित कर रावण की पहुँच का सामना करना है; अगला मोड़ जाँचेगा कि सत्ता उस वचन को याद रखती है जिसने उसे संभव बनाया।'),
  ('scene-prasravana-becomes-the-rain-shelter', 'the-brothers-choose-prasravana', 'en', 'A cave becomes the monsoon base', 'Rama and Lakshmana inspect Prasravana and choose a broad cave protected from wind and rain. A stream, flowering slopes, level stone and sightlines toward Kishkindha make it both shelter and watch-post. They can hear traces of the restored city without entering it, close enough for alliance and far enough to keep Rama''s exile vow.'),
  ('scene-prasravana-becomes-the-rain-shelter', 'the-brothers-choose-prasravana', 'hi', 'एक गुफा मानसून का पड़ाव बनती है', 'राम और लक्ष्मण प्रस्रवण को देखकर ऐसी चौड़ी गुफा चुनते हैं जो हवा और वर्षा से बचाती है। धारा, फूलों वाली ढलान, समतल शिला और किष्किंधा की ओर खुला दृश्य इसे आश्रय के साथ चौकी भी बनाते हैं। वे नगर में गए बिना उसकी ध्वनियाँ सुन सकते हैं—मित्रता के लिए पास और राम के वनवास-वचन के लिए पर्याप्त दूर।'),
  ('scene-prasravana-becomes-the-rain-shelter', 'safety-does-not-bring-sleep', 'en', 'The night is dry, but Rama cannot sleep', 'Inside the protected cave, Rama remains awake. Sugriva has recovered his wife and kingdom, while Sita''s whereabouts are still unknown; the contrast makes silence painful. Rama''s mind keeps returning to her captivity, and the comfort of the shelter exposes rather than cures his helplessness during the closed season.'),
  ('scene-prasravana-becomes-the-rain-shelter', 'safety-does-not-bring-sleep', 'hi', 'रात सूखी है, पर राम सो नहीं पाते', 'सुरक्षित गुफा के भीतर भी राम जागते रहते हैं। सुग्रीव को पत्नी और राज्य वापस मिल चुके हैं, जबकि सीता कहाँ हैं यह अब भी अज्ञात है; यह अंतर मौन को पीड़ादायक बना देता है। उनका मन बार-बार सीता की कैद पर लौटता है और आश्रय का आराम बंद ऋतु में उनकी असहायता मिटाने के बजाय उजागर करता है।'),
  ('scene-prasravana-becomes-the-rain-shelter', 'lakshmana-keeps-grief-from-stopping-action', 'en', 'Lakshmana refuses to let sorrow become surrender', 'Lakshmana does not dismiss Rama''s pain. He reminds him that endurance, energy and clear purpose are needed if Sita is to be found, and that grief without direction can consume the strength required for action. His companionship changes the night from solitary despair into a shared watch over an unfinished promise.'),
  ('scene-prasravana-becomes-the-rain-shelter', 'lakshmana-keeps-grief-from-stopping-action', 'hi', 'लक्ष्मण शोक को हार नहीं बनने देते', 'लक्ष्मण राम की पीड़ा को छोटा नहीं करते। वे याद दिलाते हैं कि सीता की खोज के लिए धैर्य, ऊर्जा और स्पष्ट उद्देश्य चाहिए, और दिशाहीन शोक उसी शक्ति को खा सकता है जिसकी आगे आवश्यकता होगी। उनका साथ उस रात को अकेली निराशा से बदलकर अधूरे वचन पर दो भाइयों की साझा पहरेदारी बना देता है।'),
  ('scene-prasravana-becomes-the-rain-shelter', 'waiting-becomes-a-seasonal-decision', 'en', 'Patience is chosen, not imposed', 'Rama agrees that the flooded season must be endured and says a worthy friend returns help when the proper moment comes. He chooses not to suspect Sugriva while roads are unusable. The brothers therefore hold position, preserve strength and attach their next movement to autumn instead of pretending that urgency can defeat terrain.'),
  ('scene-prasravana-becomes-the-rain-shelter', 'waiting-becomes-a-seasonal-decision', 'hi', 'धैर्य चुना जाता है, थोपा नहीं', 'राम मानते हैं कि बाढ़ वाली ऋतु सहनी होगी और कहते हैं कि योग्य मित्र उचित समय आने पर उपकार लौटाता है। जब मार्ग अनुपयोगी हैं तब वे सुग्रीव पर संदेह न करने का निर्णय लेते हैं। दोनों भाई वहीं रहकर शक्ति बचाते और अगली चाल को शरद से जोड़ते हैं; वे यह दिखावा नहीं करते कि केवल उतावली भूगोल को हरा सकती है।'),
  ('scene-monsoon-closes-every-road', 'sky-earth-and-rivers-change-shape', 'en', 'The land stops behaving like a road', 'Clouds erase the horizon, rivers burst their banks, slopes shed mud and tracks disappear under water. Animals seek cover while armies and merchants halt. What looks beautiful from the cave is dangerous at ground level: a rescue party could neither hold direction nor cross the swollen barriers with reliable speed.'),
  ('scene-monsoon-closes-every-road', 'sky-earth-and-rivers-change-shape', 'hi', 'धरती मार्ग की तरह काम करना छोड़ देती है', 'बादल क्षितिज मिटा देते हैं, नदियाँ किनारे तोड़ती हैं, ढलानों से कीचड़ बहता है और पगडंडियाँ पानी में खो जाती हैं। पशु आश्रय लेते हैं, सेनाएँ और व्यापारी रुकते हैं। गुफा से सुंदर दिखने वाला दृश्य धरातल पर खतरनाक है—खोज-दल दिशा नहीं पकड़ सकता और उफनती बाधाएँ भरोसेमंद गति से पार नहीं कर सकता।'),
  ('scene-monsoon-closes-every-road', 'every-weather-sign-recalls-sita', 'en', 'The monsoon keeps turning into Sita', 'Lightning, frightened birds, rain-dark earth and separated pairs all call Sita back into Rama''s thoughts. He imagines how she may hear the same storms in captivity and whether fear has deepened her suffering. Nature is not decoration around his grief; each changing sign becomes another way of measuring their distance.'),
  ('scene-monsoon-closes-every-road', 'every-weather-sign-recalls-sita', 'hi', 'मानसून बार-बार सीता की स्मृति बन जाता है', 'बिजली, डरे पक्षी, वर्षा से काली धरती और बिछुड़े जोड़े—सब राम के मन में सीता को लौटा लाते हैं। वे सोचते हैं कि कैद में वह भी यही तूफान सुनती होंगी और क्या भय ने उनकी पीड़ा और बढ़ा दी होगी। प्रकृति शोक की सजावट नहीं; उसका हर बदलता संकेत दूरी नापने का नया तरीका बन जाता है।'),
  ('scene-monsoon-closes-every-road', 'rulers-wait-for-marchable-ground', 'en', 'Even armies obey the season', 'Rama observes that rulers everywhere suspend campaigns while the rains last. Roads cannot support formations, supply lines or reliable messages, so delay is not unique to him. The recognition does not lessen Sita''s danger, but it prevents anguish from producing a doomed expedition that would waste allies before the real search begins.'),
  ('scene-monsoon-closes-every-road', 'rulers-wait-for-marchable-ground', 'hi', 'सेनाएँ भी ऋतु की सीमा मानती हैं', 'राम देखते हैं कि वर्षा रहने तक हर ओर शासक अभियान रोकते हैं। मार्ग सेना की पंक्तियाँ, रसद या भरोसेमंद संदेश नहीं संभाल सकते, इसलिए देर केवल उनकी नहीं है। यह समझ सीता के खतरे को कम नहीं करती, पर पीड़ा को ऐसे असफल अभियान में बदलने से रोकती है जो वास्तविक खोज से पहले सहयोगियों को नष्ट कर देता।'),
  ('scene-monsoon-closes-every-road', 'rama-refuses-an-early-demand', 'en', 'Rama gives Sugriva the promised season', 'Although separation hurts him, Rama will not demand that Sugriva march through impossible ground. He remembers how long Sugriva lived dispossessed and allows his friend the rest that restoration brings. Trust remains conditional on action when autumn opens the roads, but it is not withdrawn merely because waiting is painful.'),
  ('scene-monsoon-closes-every-road', 'rama-refuses-an-early-demand', 'hi', 'राम सुग्रीव को वचन वाली ऋतु पूरी देते हैं', 'वियोग उन्हें घायल करता है, फिर भी राम सुग्रीव से असंभव भूभाग में सेना चलाने की माँग नहीं करते। वे याद रखते हैं कि सुग्रीव कितने समय तक राज्य से वंचित रहे और पुनर्स्थापना के बाद उन्हें विश्राम देते हैं। भरोसा शरद में मार्ग खुलने पर कर्म से जुड़ा है, पर केवल प्रतीक्षा दुखद होने से वापस नहीं लिया जाता।'),
  ('scene-hanuman-wakes-the-promise', 'autumn-arrives-inside-a-pleasured-court', 'en', 'The roads open before the palace notices', 'The rains end and the campaign season begins, but Sugriva remains absorbed in the pleasures of recovered kingship. Hanuman sees the mismatch before an accusation arrives: Rama''s need has not changed, the agreed waiting period has ended, and a ruler who lets comfort obscure time may lose both honour and ally.'),
  ('scene-hanuman-wakes-the-promise', 'autumn-arrives-inside-a-pleasured-court', 'hi', 'महल के ध्यान देने से पहले मार्ग खुल जाते हैं', 'वर्षा समाप्त होती है और अभियान की ऋतु शुरू होती है, पर सुग्रीव पुनः मिले राजसुख में डूबे रहते हैं। आरोप आने से पहले हनुमान असंगति देख लेते हैं—राम की आवश्यकता नहीं बदली, तय प्रतीक्षा पूरी हो चुकी है और आराम में समय भूलने वाला शासक सम्मान तथा मित्र दोनों खो सकता है।'),
  ('scene-hanuman-wakes-the-promise', 'hanuman-speaks-as-a-friend-and-minister', 'en', 'Loyal counsel names the uncomfortable duty', 'Hanuman reminds Sugriva that Rama made kingdom, reputation and reunion possible. Friendship is not preserved by feeling grateful in private; it requires timely repayment when the friend''s need becomes actionable. He speaks before fear forces the issue, making correction an act of loyal service rather than courtly rebellion.'),
  ('scene-hanuman-wakes-the-promise', 'hanuman-speaks-as-a-friend-and-minister', 'hi', 'निष्ठावान सलाह असुविधाजनक कर्तव्य का नाम लेती है', 'हनुमान सुग्रीव को याद दिलाते हैं कि राम ने राज्य, प्रतिष्ठा और पुनर्मिलन संभव किया। केवल मन में कृतज्ञ होना मित्रता नहीं बचाता; मित्र की आवश्यकता पर समय से उपकार लौटाना पड़ता है। वे भय के मजबूर करने से पहले बोलते हैं, इसलिए सुधार दरबारी विद्रोह नहीं बल्कि निष्ठावान सेवा बनता है।'),
  ('scene-hanuman-wakes-the-promise', 'sugriva-orders-the-first-mobilization', 'en', 'Sugriva acts before Lakshmana arrives', 'Sugriva responds by ordering Nila to summon commanders and forces from every direction, with Angada helping inspect and count them. The command sets a strict arrival window and severe consequences for refusal. His delay is real, but so is this first corrective act; the later confrontation will occur while mobilization is already moving beyond sight.'),
  ('scene-hanuman-wakes-the-promise', 'sugriva-orders-the-first-mobilization', 'hi', 'लक्ष्मण के आने से पहले सुग्रीव कार्रवाई करते हैं', 'सुग्रीव नील को हर दिशा से सेनापति और दल बुलाने का आदेश देते हैं तथा अंगद को निरीक्षण और गिनती में साथ लगाते हैं। आदेश आने की कठोर समय-सीमा और अवज्ञा पर गंभीर दंड रखता है। उनकी देर वास्तविक है, पर यह पहला सुधार भी वास्तविक है; बाद का टकराव तब होगा जब तैयारी दृष्टि से परे चल चुकी होगी।'),
  ('scene-hanuman-wakes-the-promise', 'the-command-leaves-the-palace', 'en', 'A promise becomes messengers and deadlines', 'Nila and Angada begin turning the royal order into movement: routes are assigned, distant leaders are called and arriving forces must be counted. Sugriva then returns inside, leaving a dangerous visibility gap. Rama cannot see the work, and a command issued is not yet a completed search, so mistrust can still grow between action and proof.'),
  ('scene-hanuman-wakes-the-promise', 'the-command-leaves-the-palace', 'hi', 'वचन दूतों और समय-सीमाओं में बदलता है', 'नील और अंगद राजादेश को गति में बदलते हैं—मार्ग बाँटे जाते हैं, दूर के नायक बुलाए जाते हैं और आने वाले दल गिने जाने हैं। सुग्रीव फिर भीतर लौटते हैं, जिससे खतरनाक दृश्य-अंतर रह जाता है। राम यह काम देख नहीं सकते और आदेश देना खोज पूरी करना नहीं है, इसलिए कार्रवाई और प्रमाण के बीच अविश्वास बढ़ सकता है।'),
  ('scene-autumn-reopens-rama-grief', 'autumn-makes-the-world-passable', 'en', 'The same land becomes a road again', 'Clouds lift, rivers settle, fields brighten and firm roads return beneath the brothers'' feet. The seasonal condition Rama accepted has now ended. What was impossible during rain is possible again, so each clear horizon becomes evidence that waiting must give way to organized movement toward Sita.'),
  ('scene-autumn-reopens-rama-grief', 'autumn-makes-the-world-passable', 'hi', 'वही धरती फिर मार्ग बन जाती है', 'बादल हटते हैं, नदियाँ शांत होती हैं, खेत चमकते हैं और भाइयों के पैरों तले मजबूत मार्ग लौट आते हैं। राम ने जो ऋतु-सीमा मानी थी वह अब समाप्त है। वर्षा में असंभव काम फिर संभव है, इसलिए हर साफ क्षितिज बताता है कि प्रतीक्षा को अब सीता की ओर संगठित गति में बदलना चाहिए।'),
  ('scene-autumn-reopens-rama-grief', 'beauty-deepens-rama-separation', 'en', 'Clear skies make absence harder to bear', 'Autumn''s birds, moonlight, flowering banks and moving travellers do not console Rama. They remind him that others can reunite and journeys can resume while Sita remains beyond reach. Seasonal beauty sharpens urgency because the world now offers motion, yet no visible ally has arrived at Prasravana to begin it.'),
  ('scene-autumn-reopens-rama-grief', 'beauty-deepens-rama-separation', 'hi', 'साफ आकाश अनुपस्थिति को और कठिन बनाता है', 'शरद के पक्षी, चाँदनी, फूलों वाले तट और चलते यात्री राम को सांत्वना नहीं देते। वे याद दिलाते हैं कि दूसरे मिल सकते और यात्राएँ फिर शुरू हो सकती हैं, जबकि सीता अब भी पहुँच से बाहर हैं। ऋतु की सुंदरता उतावली बढ़ाती है, क्योंकि संसार गति दे रहा है पर प्रस्रवण पर कोई दृश्य सहयोगी नहीं आया।'),
  ('scene-autumn-reopens-rama-grief', 'rama-sees-no-sign-of-preparation', 'en', 'Hidden work looks exactly like neglect', 'Rama has not heard Sugriva''s orders or seen Nila''s couriers. From the cave, the promised friend appears to enjoy power while offering no search party, message or timetable. The conclusion is incomplete, but it is understandable from his evidence: the beneficiary is visible in comfort and the rescuer remains alone with loss.'),
  ('scene-autumn-reopens-rama-grief', 'rama-sees-no-sign-of-preparation', 'hi', 'छिपी तैयारी उपेक्षा जैसी ही दिखती है', 'राम ने सुग्रीव के आदेश नहीं सुने और न नील के दूत देखे। गुफा से वचनबद्ध मित्र सत्ता का आनंद लेते दिखते हैं, पर खोज-दल, संदेश या समय-सारणी कुछ नहीं पहुँचता। उनका निष्कर्ष अधूरा है, फिर भी उपलब्ध प्रमाण से समझ आता है—लाभ पाने वाला सुख में दिखता है और उद्धार चाहने वाला हानि के साथ अकेला।'),
  ('scene-autumn-reopens-rama-grief', 'the-message-inherits-ramas-pain', 'en', 'Rama sends a warning stronger than a reminder', 'Rama tells Lakshmana to demand the promised help and invokes Vali''s fate if Sugriva has abandoned truth. Grief turns the message into a threat against friend and kingdom. The words reveal how helpless waiting can distort judgment, even though Rama''s central claim remains valid: restored power now owes visible action for Sita.'),
  ('scene-autumn-reopens-rama-grief', 'the-message-inherits-ramas-pain', 'hi', 'राम स्मरण से अधिक कठोर चेतावनी भेजते हैं', 'राम लक्ष्मण से वचन वाली सहायता माँगने को कहते और यदि सुग्रीव ने सत्य छोड़ दिया हो तो वाली के परिणाम की याद दिलाते हैं। शोक संदेश को मित्र और राज्य के विरुद्ध धमकी बना देता है। शब्द दिखाते हैं कि असहाय प्रतीक्षा निर्णय को कैसे तीखा कर सकती है, यद्यपि मूल माँग सही है—पुनः मिली सत्ता अब सीता के लिए दृश्य कार्रवाई की ऋणी है।'),
  ('scene-lakshmana-carries-anger-to-kishkindha', 'lakshmana-wants-punishment-not-reminder', 'en', 'Lakshmana''s anger outruns Rama''s command', 'Hearing Rama''s pain, Lakshmana declares that Sugriva should die and Angada can inherit while others search for Sita. He turns a demand for accountability into immediate replacement and execution. His loyalty to Rama is fierce, but loyalty without restraint is about to create a second crisis beside the first.'),
  ('scene-lakshmana-carries-anger-to-kishkindha', 'lakshmana-wants-punishment-not-reminder', 'hi', 'लक्ष्मण का क्रोध राम की आज्ञा से आगे निकलता है', 'राम की पीड़ा सुनकर लक्ष्मण कहते हैं कि सुग्रीव को मरना चाहिए, अंगद राज्य सँभाल सकते हैं और दूसरे सीता को खोजेंगे। वे जवाबदेही की माँग को तत्काल हत्या और सत्ता-परिवर्तन में बदल देते हैं। राम के प्रति उनकी निष्ठा प्रचंड है, पर संयमहीन निष्ठा पहले संकट के साथ दूसरा संकट खड़ा करने वाली है।'),
  ('scene-lakshmana-carries-anger-to-kishkindha', 'rama-forbids-killing-a-friend', 'en', 'Rama narrows the mission back to speech', 'Rama tells Lakshmana not to kill a friend and asks him to restrain anger, use conciliatory words and remind Sugriva of the season. The correction matters: Rama''s own warning was violent, yet he refuses to let it become an execution order. The purpose is still to recover cooperation, not win another throne through blood.'),
  ('scene-lakshmana-carries-anger-to-kishkindha', 'rama-forbids-killing-a-friend', 'hi', 'राम अभियान को फिर संवाद तक सीमित करते हैं', 'राम लक्ष्मण से कहते हैं कि मित्र की हत्या न करें, क्रोध रोकें, शांत शब्द बोलें और सुग्रीव को ऋतु की याद दिलाएँ। यह सुधार महत्वपूर्ण है—राम की अपनी चेतावनी हिंसक थी, फिर भी वे उसे हत्या का आदेश नहीं बनने देते। उद्देश्य सहयोग वापस पाना है, रक्त से एक और सिंहासन जीतना नहीं।'),
  ('scene-lakshmana-carries-anger-to-kishkindha', 'the-approach-terrifies-the-city', 'en', 'Restraint does not yet look gentle', 'Lakshmana strides toward Kishkindha breaking trees and casting rocks aside. Vanaras at the gate see his bow and prepare stones and trunks for defence; families and guards read his arrival as an attack. No blow has landed, but intimidation has already widened a private breach into public fear across the city.'),
  ('scene-lakshmana-carries-anger-to-kishkindha', 'the-approach-terrifies-the-city', 'hi', 'संयम अभी कोमल नहीं दिखता', 'लक्ष्मण किष्किंधा की ओर बढ़ते हुए पेड़ गिराते और चट्टानें हटाते हैं। द्वार के वानर उनका धनुष देखकर पत्थर और तने रक्षा के लिए उठा लेते हैं; परिवार और प्रहरी आगमन को आक्रमण समझते हैं। प्रहार नहीं हुआ, फिर भी भय ने निजी दरार को नगरव्यापी संकट बना दिया है।'),
  ('scene-lakshmana-carries-anger-to-kishkindha', 'angada-carries-the-demand-inside', 'en', 'Angada becomes the first bridge', 'Lakshmana stops at the gate and sends Angada to announce that he waits outside for the promise to be fulfilled. Angada passes through frightened streets to Sugriva, Tara and the ministers. The message finally enters without an arrow, giving the court a narrow chance to wake the king, understand the anger and answer before force returns.'),
  ('scene-lakshmana-carries-anger-to-kishkindha', 'angada-carries-the-demand-inside', 'hi', 'अंगद पहला सेतु बनते हैं', 'लक्ष्मण द्वार पर रुककर अंगद को भेजते हैं कि वे बाहर वचन पूरा होने की प्रतीक्षा कर रहे हैं। अंगद भयभीत गलियों से होकर सुग्रीव, तारा और मंत्रियों तक पहुँचते हैं। संदेश अंततः बाण के बिना भीतर जाता है और दरबार को राजा जगाने, क्रोध समझने तथा बल लौटने से पहले उत्तर देने का छोटा अवसर मिलता है।'),
  ('scene-hanuman-names-the-delay', 'sugriva-wakes-to-a-crisis-he-cannot-name', 'en', 'The king asks what he has done', 'Angada and the ministers wake Sugriva from intoxicated sleep. He says he has spoken no insult and committed no deliberate injury against Rama, so he cannot understand the fury at his gate. His confusion is partly sincere and partly the blindness of comfort: neglect can damage a friend without requiring a hostile sentence or conscious betrayal.'),
  ('scene-hanuman-names-the-delay', 'sugriva-wakes-to-a-crisis-he-cannot-name', 'hi', 'राजा पूछते हैं कि उनसे क्या हुआ', 'अंगद और मंत्री सुग्रीव को मदभरी नींद से जगाते हैं। वे कहते हैं कि उन्होंने राम का अपमान नहीं किया और जानबूझकर कोई हानि नहीं पहुँचाई, इसलिए द्वार पर इतना क्रोध समझ नहीं आता। उनका भ्रम कुछ सच्चा और कुछ सुख का अंधापन है—उपेक्षा बिना शत्रुतापूर्ण शब्द या जानबूझकर विश्वासघात के भी मित्र को चोट पहुँचा सकती है।'),
  ('scene-hanuman-names-the-delay', 'hanuman-states-the-missed-season', 'en', 'Hanuman says the deadline was missed', 'Hanuman answers without flattering the throne: the rainy months are over, Rama waited as agreed, and Sugriva let pleasure consume the moment for action. He also remembers that Rama restored the very life now being enjoyed. The counsel separates malicious betrayal from a serious lapse without using the first distinction to excuse the second.'),
  ('scene-hanuman-names-the-delay', 'hanuman-states-the-missed-season', 'hi', 'हनुमान कहते हैं कि समय-सीमा चूक गई', 'हनुमान सिंहासन की चापलूसी किए बिना उत्तर देते हैं—वर्षा समाप्त है, राम ने तय समय तक प्रतीक्षा की और सुग्रीव ने सुख में कर्म का क्षण खो दिया। वे यह भी याद दिलाते हैं कि जिस जीवन का आनंद लिया जा रहा है वही राम ने लौटाया था। सलाह दुर्भावनापूर्ण विश्वासघात और गंभीर चूक को अलग रखती है, पर पहले अंतर से दूसरी गलती को नहीं ढकती।'),
  ('scene-hanuman-names-the-delay', 'receive-the-anger-without-answering-in-kind', 'en', 'Accountability begins by surviving the rebuke', 'Hanuman advises Sugriva to meet Lakshmana, bow, hear even harsh language patiently and avoid answering anger with royal pride. The goal is not humiliation; it is to keep one frightened encounter from destroying the alliance needed for Sita. A king must absorb some heat when his own delay helped produce it.'),
  ('scene-hanuman-names-the-delay', 'receive-the-anger-without-answering-in-kind', 'hi', 'जवाबदेही कठोर वचन सहने से शुरू होती है', 'हनुमान सुग्रीव को सलाह देते हैं कि लक्ष्मण से मिलें, झुकें, कठोर भाषा भी धैर्य से सुनें और राज-अभिमान से क्रोध का उत्तर न दें। उद्देश्य अपमान नहीं; भयभीत मुठभेड़ को सीता की खोज वाली मित्रता नष्ट करने से रोकना है। अपनी देर से पैदा ताप का कुछ भाग राजा को स्वयं सहना होगा।'),
  ('scene-hanuman-names-the-delay', 'fulfilment-must-follow-apology', 'en', 'Words can reopen the door; action must cross it', 'Hanuman''s final counsel is practical: acknowledge what Rama did, explain without evasion and complete the promised search. An apology without mobilization would leave the underlying wrong untouched. Sugriva already has couriers moving, so he can meet Lakshmana with both humility and evidence that correction has begun.'),
  ('scene-hanuman-names-the-delay', 'fulfilment-must-follow-apology', 'hi', 'शब्द द्वार खोल सकते हैं; कर्म को उससे गुजरना होगा', 'हनुमान की अंतिम सलाह व्यावहारिक है—राम के उपकार को स्वीकारें, बिना बचाव के स्थिति बताएँ और वचन वाली खोज पूरी करें। सेना जुटाए बिना क्षमा माँगना मूल गलती को नहीं बदलता। सुग्रीव के दूत पहले से चल रहे हैं, इसलिए वे लक्ष्मण के सामने विनम्रता और शुरू हुए सुधार का प्रमाण दोनों रख सकते हैं।'),
  ('scene-tara-meets-anger-at-the-inner-gate', 'lakshmana-crosses-a-restored-city', 'en', 'Prosperity looks like evidence against Sugriva', 'Lakshmana enters Kishkindha past gardens, streams, crowded homes and the houses of celebrated commanders. The city''s abundance shows how completely Sugriva''s fortunes changed through Rama''s help. To a messenger arriving from Rama''s bare cave, every comfort intensifies the charge that the restored king has enjoyed repayment without returning it.'),
  ('scene-tara-meets-anger-at-the-inner-gate', 'lakshmana-crosses-a-restored-city', 'hi', 'समृद्धि सुग्रीव के विरुद्ध प्रमाण जैसी लगती है', 'लक्ष्मण बागों, धाराओं, भरे घरों और प्रसिद्ध सेनापतियों के निवासों के बीच से किष्किंधा में प्रवेश करते हैं। नगर की समृद्धि दिखाती है कि राम की सहायता से सुग्रीव का भाग्य कितना बदल गया। राम की सूनी गुफा से आए संदेशवाहक को हर सुख यह आरोप और तीखा करता है कि राजा ने उपकार का फल लिया, लौटाया नहीं।'),
  ('scene-tara-meets-anger-at-the-inner-gate', 'the-bowstring-enters-before-words', 'en', 'A bowstring announces the danger', 'At the inner apartments, music and celebration make Lakshmana ashamed of entering private space and furious at the apparent neglect. He stops short, but releases a thunderous bowstring sound that travels through the palace. Sugriva understands that Angada''s warning has arrived in person, and fear reaches the throne before any accusation does.'),
  ('scene-tara-meets-anger-at-the-inner-gate', 'the-bowstring-enters-before-words', 'hi', 'शब्दों से पहले धनुष की टंकार पहुँचती है', 'अंतरमहल के पास संगीत और उत्सव देखकर लक्ष्मण निजी स्थान में आने से संकोच और दिखती उपेक्षा पर क्रोध दोनों महसूस करते हैं। वे रुकते हैं, पर धनुष की ऐसी टंकार करते हैं जो पूरे महल में फैलती है। सुग्रीव समझ जाते हैं कि अंगद की चेतावनी स्वयं आ पहुँची है और आरोप से पहले भय सिंहासन तक पहुँचता है।'),
  ('scene-tara-meets-anger-at-the-inner-gate', 'tara-opens-a-human-conversation', 'en', 'Tara asks anger to explain itself', 'Sugriva asks Tara to meet Lakshmana first. She approaches without weapons and asks who has failed him and why the prince burns like fire. Lakshmana answers that Sugriva has lost duty and friendship in pleasure while Rama suffers. By making the accusation speak, Tara moves the encounter away from threat and toward facts that can be tested.'),
  ('scene-tara-meets-anger-at-the-inner-gate', 'tara-opens-a-human-conversation', 'hi', 'तारा क्रोध से उसका कारण पूछती हैं', 'सुग्रीव तारा से पहले लक्ष्मण से मिलने को कहते हैं। वे बिना शस्त्र पास जाकर पूछती हैं कि किसने आज्ञा नहीं मानी और राजकुमार अग्नि जैसे क्यों जल रहे हैं। लक्ष्मण कहते हैं कि राम दुखी हैं और सुग्रीव सुख में कर्तव्य तथा मित्रता भूल गए। आरोप को बोलने पर मजबूर करके तारा मुठभेड़ को धमकी से जाँच योग्य तथ्यों की ओर मोड़ती हैं।'),
  ('scene-tara-meets-anger-at-the-inner-gate', 'the-first-missing-fact-reaches-lakshmana', 'en', 'The summons went out before he arrived', 'Tara admits that Sugriva was overtaken by recovered pleasure, but tells Lakshmana that orders for Rama''s work have already gone out and enormous forces are arriving. This does not erase the missed moment or excuse silence. It changes the question from whether Sugriva will act to whether delayed action can still repair trust in time.'),
  ('scene-tara-meets-anger-at-the-inner-gate', 'the-first-missing-fact-reaches-lakshmana', 'hi', 'उनके आने से पहले बुलावा जा चुका था', 'तारा मानती हैं कि पुनः मिले सुख ने सुग्रीव को बाँध लिया था, पर बताती हैं कि राम के काम के आदेश पहले ही निकल चुके हैं और विशाल दल आ रहे हैं। यह चूका समय या मौन नहीं मिटाता। अब प्रश्न यह नहीं कि सुग्रीव काम करेंगे या नहीं, बल्कि यह है कि देर से शुरू काम समय पर भरोसा सुधार सकता है या नहीं।'),
  ('scene-lakshmana-delivers-the-vali-warning', 'sugriva-rises-with-folded-hands', 'en', 'The king leaves the ease of his seat', 'When Lakshmana enters, Sugriva rises from his golden seat and stands with folded hands. He does not hide behind guards, rank or the private court. The posture follows Hanuman''s counsel and opens space for accountability, but it cannot control what the grieving messenger has carried from Rama''s cave.'),
  ('scene-lakshmana-delivers-the-vali-warning', 'sugriva-rises-with-folded-hands', 'hi', 'राजा अपने सुखासन से उठते हैं', 'लक्ष्मण के भीतर आते ही सुग्रीव स्वर्णासन छोड़कर हाथ जोड़कर खड़े होते हैं। वे प्रहरी, पद या निजी दरबार के पीछे नहीं छिपते। यह मुद्रा हनुमान की सलाह मानकर जवाबदेही का स्थान खोलती है, पर राम की गुफा से आए शोकभरे संदेश पर उसका नियंत्रण नहीं है।'),
  ('scene-lakshmana-delivers-the-vali-warning', 'lakshmana-builds-the-case-of-ingratitude', 'en', 'The accusation becomes moral judgment', 'Lakshmana contrasts a grateful, truthful ruler with one who gains help and refuses to return it. He names Rama''s intervention, Sugriva''s restored kingdom and the still-unanswered need to find Sita. The argument has force because reciprocity is real, yet it treats incomplete knowledge of mobilization as proof of deliberate falsehood.'),
  ('scene-lakshmana-delivers-the-vali-warning', 'lakshmana-builds-the-case-of-ingratitude', 'hi', 'आरोप नैतिक निर्णय बन जाता है', 'लक्ष्मण कृतज्ञ और सत्यनिष्ठ राजा की तुलना उस शासक से करते हैं जो सहायता लेकर उसे लौटाता नहीं। वे राम का हस्तक्षेप, सुग्रीव का लौटाया राज्य और सीता की अब तक अनुत्तरित खोज गिनाते हैं। पारस्परिक ऋण के कारण तर्क मजबूत है, पर वह सेना जुटने की अधूरी जानकारी को जानबूझकर बोले झूठ का प्रमाण मान लेता है।'),
  ('scene-lakshmana-delivers-the-vali-warning', 'vali-road-enters-the-room', 'en', 'The warning invokes the last king''s death', 'Lakshmana repeats that the road Vali travelled has not closed and that Rama''s arrows can send Sugriva along it. The words bring the previous violent transfer of power into the room as a threat against the new ruler. Accountability now stands dangerously close to coercion by remembered killing.'),
  ('scene-lakshmana-delivers-the-vali-warning', 'vali-road-enters-the-room', 'hi', 'चेतावनी पिछले राजा की मृत्यु बुलाती है', 'लक्ष्मण दोहराते हैं कि वाली जिस राह गए वह बंद नहीं हुई और राम के बाण सुग्रीव को भी उसी पर भेज सकते हैं। शब्द सत्ता के पिछले हिंसक परिवर्तन को नए राजा के विरुद्ध धमकी बनाकर कक्ष में ले आते हैं। जवाबदेही अब पिछली हत्या के भय से कराई जा रही आज्ञाकारिता के बहुत पास खड़ी है।'),
  ('scene-lakshmana-delivers-the-vali-warning', 'the-court-holds-before-the-answer', 'en', 'No one answers violence with violence', 'Sugriva remains standing rather than reaching for force, and the surrounding court does not attack Lakshmana. That pause preserves the possibility Tara and Hanuman created. The accusation has been delivered in full; the next task is to separate lapse from betrayal, show what has already moved and restore the alliance without pretending the threat was harmless.'),
  ('scene-lakshmana-delivers-the-vali-warning', 'the-court-holds-before-the-answer', 'hi', 'हिंसा का उत्तर हिंसा से नहीं दिया जाता', 'सुग्रीव बल उठाने के बजाय खड़े रहते हैं और आसपास का दरबार लक्ष्मण पर आक्रमण नहीं करता। यह विराम तारा और हनुमान की बनाई संभावना बचाता है। पूरा आरोप सामने आ चुका है; अब चूक को विश्वासघात से अलग करना, शुरू तैयारी दिखाना और धमकी को निर्दोष माने बिना मित्रता सुधारना है।'),
  ('scene-tara-reveals-the-mobilization', 'tara-rejects-the-word-ungrateful', 'en', 'Tara disputes betrayal, not responsibility', 'Tara tells Lakshmana that Sugriva is neither heartless nor false and has not forgotten what Rama did. She does not claim that his conduct was timely. Her defence draws a necessary boundary: being overcome by comfort after long deprivation is a serious failure of attention, but it is not the same as deciding to abandon a friend.'),
  ('scene-tara-reveals-the-mobilization', 'tara-rejects-the-word-ungrateful', 'hi', 'तारा विश्वासघात नकारती हैं, जिम्मेदारी नहीं', 'तारा लक्ष्मण से कहती हैं कि सुग्रीव न हृदयहीन हैं, न झूठे, और राम का उपकार भूले नहीं। वे यह दावा नहीं करतीं कि उनका आचरण समय पर था। उनका पक्ष जरूरी सीमा खींचता है—लंबे अभाव के बाद सुख में डूबकर ध्यान चूकना गंभीर गलती है, पर मित्र को छोड़ देने का निर्णय उससे अलग है।'),
  ('scene-tara-reveals-the-mobilization', 'pleasure-explains-but-does-not-erase', 'en', 'An explanation is not an acquittal', 'Tara describes how recovered intimacy and kingship distorted Sugriva''s sense of passing time. She asks Lakshmana to examine the whole situation before giving anger control. The explanation makes the lapse intelligible, not acceptable; Rama still waited through every agreed month and deserved communication when the season turned.'),
  ('scene-tara-reveals-the-mobilization', 'pleasure-explains-but-does-not-erase', 'hi', 'कारण बताना दोष मिटाना नहीं', 'तारा बताती हैं कि पुनः मिले संबंध और राजसुख ने सुग्रीव की समय-बोध को कैसे बिगाड़ा। वे लक्ष्मण से क्रोध को नियंत्रण देने से पहले पूरी स्थिति देखने को कहती हैं। कारण चूक को समझने योग्य बनाता है, उचित नहीं; राम ने तय हर महीना प्रतीक्षा की और ऋतु बदलते ही संदेश पाने के अधिकारी थे।'),
  ('scene-tara-reveals-the-mobilization', 'the-search-needs-a-coalition', 'en', 'Ravana cannot be pursued by outrage alone', 'Tara says the enemy commands vast, mobile forces and that Rama needs allies who know forests, mountains and strongholds. Vali had spoken of that scale before his death. Her point is operational: recovering Sita requires intelligence and reach, not only the strength of one bow, so preparation itself is part of rescue.'),
  ('scene-tara-reveals-the-mobilization', 'the-search-needs-a-coalition', 'hi', 'केवल क्रोध से रावण का पीछा नहीं हो सकता', 'तारा कहती हैं कि शत्रु के पास विशाल, रूप बदलने वाली शक्ति है और राम को ऐसे सहयोगी चाहिए जो वन, पर्वत और दुर्ग जानते हों। वाली ने मृत्यु से पहले इस विस्तार का उल्लेख किया था। बात व्यावहारिक है—सीता की वापसी के लिए सूचना और पहुँच चाहिए, केवल एक धनुष की शक्ति नहीं; तैयारी भी बचाव का भाग है।'),
  ('scene-tara-reveals-the-mobilization', 'incoming-forces-answer-the-charge', 'en', 'The roads already carry an answer', 'Tara reveals that commanders were sent to summon the host and that bears, vanaras and other contingents are converging that very day. Lakshmana can now test her words against arrivals rather than trust a promise alone. The disclosure does not complete the search, but it transforms the court from a place of indulgence into the center of a delayed mobilization.'),
  ('scene-tara-reveals-the-mobilization', 'incoming-forces-answer-the-charge', 'hi', 'मार्ग पहले से उत्तर लेकर आ रहे हैं', 'तारा बताती हैं कि सेनापतियों को दल बुलाने भेजा गया और भालू, वानर तथा अन्य टुकड़ियाँ उसी दिन जुट रही हैं। अब लक्ष्मण केवल वचन पर भरोसा करने के बजाय आते दलों से बात जाँच सकते हैं। खुलासा खोज पूरी नहीं करता, पर दरबार को विलास के स्थान से देर से चल रही तैयारी के केंद्र में बदल देता है।'),
  ('scene-friends-repair-the-breach', 'sugriva-credits-the-restoration', 'en', 'Sugriva names what Rama gave him', 'Sugriva says that kingdom, reputation and recovered fortune came through Rama. He does not claim that issuing orders makes the debt disappear. By naming the imbalance openly, he meets Lakshmana''s central moral charge and places his royal power back inside the friendship that made its recovery possible.'),
  ('scene-friends-repair-the-breach', 'sugriva-credits-the-restoration', 'hi', 'सुग्रीव राम से मिला सब कुछ गिनाते हैं', 'सुग्रीव कहते हैं कि राज्य, प्रतिष्ठा और लौटा सौभाग्य राम के कारण मिला। वे यह दावा नहीं करते कि आदेश जारी होते ही ऋण समाप्त हो गया। असमानता को खुलकर मानकर वे लक्ष्मण के मूल नैतिक आरोप का उत्तर देते और अपनी राजसत्ता को उसी मित्रता के भीतर रखते हैं जिसने उसकी वापसी संभव की।'),
  ('scene-friends-repair-the-breach', 'help-is-offered-without-self-importance', 'en', 'The ally promises service, not ownership of victory', 'Sugriva praises Rama''s strength and says the gathered forces will support rather than replace it. He will follow when Rama moves against Ravana. The humility avoids turning assistance into a boast, while the promise remains concrete: intelligence, numbers and local knowledge will now be placed behind the effort to recover Sita.'),
  ('scene-friends-repair-the-breach', 'help-is-offered-without-self-importance', 'hi', 'सहयोगी सेवा का वचन देता है, विजय का स्वामित्व नहीं', 'सुग्रीव राम की शक्ति की प्रशंसा कर कहते हैं कि जुटे दल उसका स्थान नहीं लेंगे, उसे सहारा देंगे। रावण के विरुद्ध राम चलेंगे तो वे साथ चलेंगे। विनम्रता सहायता को डींग नहीं बनने देती, जबकि वचन ठोस है—सीता की खोज में अब सूचना, संख्या और स्थानीय ज्ञान लगाया जाएगा।'),
  ('scene-friends-repair-the-breach', 'sugriva-asks-for-forgiveness', 'en', 'The lapse is admitted without a defence', 'Sugriva asks Rama to forgive any transgression born from confidence, comfort or familiarity. He does not demand that Tara''s explanation cancel the hurt. The request accepts that close friendship can make duty feel safe enough to postpone, and that the harmed friend still deserves acknowledgment even after corrective work has begun.'),
  ('scene-friends-repair-the-breach', 'sugriva-asks-for-forgiveness', 'hi', 'चूक बिना बहाने के स्वीकार की जाती है', 'सुग्रीव राम से उस चूक की क्षमा माँगते हैं जो भरोसे, आराम या घनिष्ठता से हुई। वे यह नहीं कहते कि तारा का कारण पीड़ा मिटा देता है। निवेदन मानता है कि निकट मित्रता कर्तव्य को इतना सुरक्षित दिखा सकती है कि उसे टाला जाए, और सुधार शुरू होने पर भी घायल मित्र स्वीकारोक्ति का अधिकारी है।'),
  ('scene-friends-repair-the-breach', 'lakshmana-apologises-and-invites-return', 'en', 'Lakshmana also owns his excess', 'Lakshmana accepts Sugriva''s answer, affirms his worth as Rama''s ally and asks forgiveness for the harshness carried from a grieving brother. He then asks Sugriva to come soothe Rama in person. Repair is mutual: delay required correction, but violent speech also required acknowledgment before they could move together.'),
  ('scene-friends-repair-the-breach', 'lakshmana-apologises-and-invites-return', 'hi', 'लक्ष्मण भी अपनी अति स्वीकारते हैं', 'लक्ष्मण सुग्रीव का उत्तर स्वीकारते, उन्हें राम का योग्य सहयोगी मानते और दुखी भाई की ओर से लाए कठोर शब्दों के लिए क्षमा माँगते हैं। फिर वे उनसे स्वयं राम को शांत करने चलने को कहते हैं। सुधार दोनों ओर है—देर को ठीक करना था, पर साथ चलने से पहले हिंसक भाषा को भी स्वीकारना था।'),
  ('scene-orders-cross-the-world', 'hanuman-receives-the-expanded-order', 'en', 'The summons grows beyond the first command', 'Sugriva directs Hanuman to reach communities on Mahendra, Himalaya, Vindhya, Kailasa, western coasts, remote forests, caves and hermitages. The list is not ornamental geography; each region adds travellers adapted to a different terrain. A search for an unknown destination must reach farther than the king''s ordinary chain of command.'),
  ('scene-orders-cross-the-world', 'hanuman-receives-the-expanded-order', 'hi', 'बुलावा पहले आदेश से भी व्यापक होता है', 'सुग्रीव हनुमान को महेंद्र, हिमालय, विंध्य, कैलास, पश्चिमी तटों, दूरस्थ वनों, गुफाओं और आश्रमों के समुदायों तक पहुँचने को कहते हैं। यह केवल भूगोल की सजावटी सूची नहीं; हर क्षेत्र अलग भूभाग में चलने वाले खोजी देता है। अज्ञात गंतव्य की खोज को राजा की सामान्य आदेश-श्रृंखला से कहीं दूर जाना होगा।'),
  ('scene-orders-cross-the-world', 'fast-couriers-chase-the-first-couriers', 'en', 'Speed is added to an order already moving', 'Sugriva knows the first messengers are swift, but sends more to urge every delayed leader onward. The second wave proves that mobilization did not begin only after Lakshmana''s threat; it accelerates work already underway. Correction here means monitoring an order, discovering lag and reinforcing it until distant intent becomes arrival.'),
  ('scene-orders-cross-the-world', 'fast-couriers-chase-the-first-couriers', 'hi', 'चलते आदेश में और गति जोड़ी जाती है', 'सुग्रीव जानते हैं कि पहले दूत तेज हैं, फिर भी पीछे रह गए हर दलनायक को आगे बढ़ाने के लिए और दूत भेजते हैं। दूसरी लहर साबित करती है कि तैयारी केवल लक्ष्मण की धमकी के बाद शुरू नहीं हुई; वह चल रहे काम को तेज करती है। सुधार का अर्थ आदेश देकर भूलना नहीं, बल्कि देर पहचानकर उसे तब तक मजबूत करना है जब तक दूर का इरादा आगमन न बन जाए।'),
  ('scene-orders-cross-the-world', 'the-world-answers-in-different-forms', 'en', 'Every landscape sends different strength', 'Dark mountain dwellers, golden western bands, Himalayan foragers and coastal communities leave their homes for Kishkindha. Their legendary numbers express the scale of response, while their varied origins matter more than arithmetic. Together they can cross forests, heights, rivers and shores that no single local patrol could cover.'),
  ('scene-orders-cross-the-world', 'the-world-answers-in-different-forms', 'hi', 'हर भूभाग अलग शक्ति भेजता है', 'काले पर्वतीय दल, स्वर्णिम पश्चिमी समूह, हिमालयी वनचारी और तटीय समुदाय अपने घरों से किष्किंधा की ओर निकलते हैं। उनकी विशाल संख्याएँ प्रतिक्रिया का विस्तार बताती हैं, पर गणना से अधिक उनकी विविध उत्पत्ति महत्वपूर्ण है। साथ मिलकर वे वन, ऊँचाई, नदियाँ और तट छान सकते हैं जिन्हें एक स्थानीय दल नहीं देख सकता।'),
  ('scene-orders-cross-the-world', 'returning-messengers-bring-proof', 'en', 'The order returns as evidence', 'Couriers return with leaders, healing herbs, fruits and reports that forces across the earth are on their way. Sugriva can now show more than intention: messengers completed routes, supplies moved and contingents crossed real distance. The network is not yet assigned to directions, but the disputed promise has become measurable preparation.'),
  ('scene-orders-cross-the-world', 'returning-messengers-bring-proof', 'hi', 'आदेश प्रमाण बनकर लौटता है', 'दूत दलनायकों, औषधियों, फलों और इस समाचार के साथ लौटते हैं कि धरती भर की सेनाएँ आ रही हैं। अब सुग्रीव केवल इरादा नहीं, पूरा मार्ग, चली रसद और पार की वास्तविक दूरी दिखा सकते हैं। दल अभी खोज-दिशाओं में नहीं बाँटे गए, पर विवादित वचन मापी जा सकने वाली तैयारी बन चुका है।'),
  ('scene-sugriva-returns-to-rama', 'sugriva-leaves-the-inner-court', 'en', 'Reconciliation moves out of the palace', 'Sugriva dismisses the private gathering, calls for transport and asks Lakshmana to travel with him. The public departure matters because the crisis began with a ruler apparently hidden in pleasure. He now leaves that protected space under the eyes of attendants and forces, placing his body and kingship on the road back to Rama.'),
  ('scene-sugriva-returns-to-rama', 'sugriva-leaves-the-inner-court', 'hi', 'मेल-मिलाप महल से बाहर निकलता है', 'सुग्रीव निजी सभा विदा करते, वाहन बुलाते और लक्ष्मण से साथ चलने को कहते हैं। सार्वजनिक प्रस्थान महत्वपूर्ण है क्योंकि संकट उस राजा से शुरू हुआ जो सुख में छिपा दिखाई देता था। अब वे सेवकों और सेना के सामने सुरक्षित स्थान छोड़कर स्वयं तथा अपनी राजसत्ता को राम की ओर जाने वाले मार्ग पर रखते हैं।'),
  ('scene-sugriva-returns-to-rama', 'the-king-bows-before-the-friend', 'en', 'Royal display ends in a bow', 'Sugriva arrives with royal signs and an armed escort, then steps down and folds his hands before Rama. The surrounding forces follow his gesture. He does not ask Rama to come into Kishkindha or accept court ceremony; he brings the court''s capacity to the exiled friend''s sparse shelter and acknowledges where the unfinished duty lies.'),
  ('scene-sugriva-returns-to-rama', 'the-king-bows-before-the-friend', 'hi', 'राजसी प्रदर्शन झुकने पर समाप्त होता है', 'सुग्रीव राजचिह्न और सशस्त्र दल के साथ आते हैं, फिर उतरकर राम के सामने हाथ जोड़ते हैं। आसपास की सेना भी उनका अनुसरण करती है। वे राम को किष्किंधा या दरबारी समारोह में नहीं बुलाते; दरबार की क्षमता वनवासी मित्र के साधारण आश्रय तक लाकर स्वीकारते हैं कि अधूरा कर्तव्य कहाँ है।'),
  ('scene-sugriva-returns-to-rama', 'rama-embraces-before-he-instructs', 'en', 'Relationship is restored before command resumes', 'Rama raises and embraces Sugriva rather than extending the threat carried earlier. The gesture accepts the repair and recognizes a friend, not merely a subordinate. Only after seating him does Rama speak about balancing duty, prosperity and pleasure, allowing accountability to continue without making shame the permanent basis of cooperation.'),
  ('scene-sugriva-returns-to-rama', 'rama-embraces-before-he-instructs', 'hi', 'आदेश से पहले संबंध फिर जुड़ता है', 'राम पहले वाली धमकी आगे बढ़ाने के बजाय सुग्रीव को उठाकर गले लगाते हैं। यह सुधार स्वीकारकर अधीनस्थ नहीं, मित्र को पहचानता है। बैठाने के बाद ही राम कर्तव्य, समृद्धि और सुख के संतुलन की बात करते हैं, ताकि जवाबदेही चलती रहे पर लज्जा सहयोग का स्थायी आधार न बने।'),
  ('scene-sugriva-returns-to-rama', 'rama-says-the-time-for-effort-has-come', 'en', 'Forgiveness does not extend the delay', 'Rama says a ruler must give proper time to duty, prosperity and pleasure, and that the season for effort has arrived. Sugriva answers by pointing to leaders already present and countless others still approaching. Friendship is restored, but the standard is now operational: the assembled force must be organized to find Sita and reach Ravana.'),
  ('scene-sugriva-returns-to-rama', 'rama-says-the-time-for-effort-has-come', 'hi', 'क्षमा देर को आगे नहीं बढ़ाती', 'राम कहते हैं कि शासक को कर्तव्य, समृद्धि और सुख को उचित समय देना चाहिए और अब परिश्रम की ऋतु आ गई है। सुग्रीव उपस्थित दलनायकों तथा मार्ग में आ रहे असंख्य समूहों की ओर संकेत करते हैं। मित्रता लौट गई, पर कसौटी अब व्यावहारिक है—सेना को सीता की खोज और रावण तक पहुँचने के लिए व्यवस्थित करना होगा।'),
  ('scene-the-horizon-fills-with-allies', 'rama-affirms-the-friendship', 'en', 'Rama recognizes Sugriva as the kind of friend who acts', 'Rama compares Sugriva''s help to rain, sunlight and moonlight performing their natural work. He says he trusts the ally to speak and act for his good, and places confidence in their combined effort against Ravana. The affirmation closes the personal dispute without claiming that Sita has already been found.'),
  ('scene-the-horizon-fills-with-allies', 'rama-affirms-the-friendship', 'hi', 'राम सुग्रीव को कर्म करने वाला मित्र मानते हैं', 'राम सुग्रीव की सहायता की तुलना वर्षा, सूर्यप्रकाश और चाँदनी के स्वाभाविक काम से करते हैं। वे कहते हैं कि मित्र उनके हित में बोलेगा और कर्म करेगा तथा रावण के विरुद्ध संयुक्त प्रयास पर भरोसा रखते हैं। यह स्वीकृति निजी विवाद बंद करती है, पर सीता मिल गई हैं ऐसा दावा नहीं करती।'),
  ('scene-the-horizon-fills-with-allies', 'dust-announces-the-host', 'en', 'The ground trembles before the leaders appear', 'Dust rises until sunlight dims, the earth trembles and calls roll across the forests. The arriving host is first experienced as weather and vibration, conveying scale before individual faces can be seen. What Rama mistook for absence now fills every approach, turning hidden preparation into an undeniable public fact.'),
  ('scene-the-horizon-fills-with-allies', 'dust-announces-the-host', 'hi', 'दलनायकों से पहले धरती उनका समाचार देती है', 'धूल उठकर सूर्य का प्रकाश मंद करती है, धरती काँपती है और वनों में पुकार फैलती है। आने वाली सेना पहले मौसम और कंपन की तरह महसूस होती है, जिससे अलग चेहरे दिखने से पहले ही विस्तार समझ आता है। जिसे राम ने अनुपस्थिति माना था वह अब हर मार्ग भर देता है और छिपी तैयारी निर्विवाद सार्वजनिक तथ्य बन जाती है।'),
  ('scene-the-horizon-fills-with-allies', 'leaders-emerge-from-the-mass', 'en', 'A crowd becomes a network of known leaders', 'Satavali, Sushena, Kesari, Gavaksha, Dhumra, Nila, Mainda, Dvivida, Jambavan, Angada, Hanuman and many others report with their own contingents. The scale remains legendary, but leadership gives it structure. Each named group can later receive a direction, terrain and responsibility instead of remaining an unusable sea of bodies.'),
  ('scene-the-horizon-fills-with-allies', 'leaders-emerge-from-the-mass', 'hi', 'भीड़ पहचाने हुए नायकों का जाल बनती है', 'शतबलि, सुषेण, केसरी, गवाक्ष, धूम्र, नील, मैन्द, द्विविद, जाम्बवान, अंगद, हनुमान और अनेक अन्य अपने दलों सहित पहुँचते हैं। विस्तार अलौकिक है, पर नेतृत्व उसे संरचना देता है। हर नामित समूह को आगे दिशा, भूभाग और जिम्मेदारी दी जा सकती है; वह अनुपयोगी भीड़ बनकर नहीं रहता।'),
  ('scene-the-horizon-fills-with-allies', 'the-army-is-counted-before-it-searches', 'en', 'Arrival becomes readiness through organization', 'Sugriva orders those who understand the host to station forces near streams and forests and determine who has arrived and who is missing. Numbers alone are not readiness. Counting, locating and linking leaders to their contingents creates the command picture needed for the next move: dividing the world into searchable horizons.'),
  ('scene-the-horizon-fills-with-allies', 'the-army-is-counted-before-it-searches', 'hi', 'संगठन आगमन को तैयारी बनाता है', 'सुग्रीव सेना जानने वालों को दलों को धाराओं और वनों के पास ठहराने तथा यह जाँचने का आदेश देते हैं कि कौन आया और कौन शेष है। केवल संख्या तैयारी नहीं होती। गिनती, स्थान और नायकों को उनके दल से जोड़ना अगली चाल के लिए जरूरी व्यवस्था बनाता है—संसार को खोजी जा सकने वाली दिशाओं में बाँटना।'),
  ('scene-vinata-takes-the-rising-road', 'rama-asks-for-knowledge-before-war', 'en', 'The first mission is to know, not attack', 'Sugriva offers the gathered host to Rama''s command, but Rama refuses to begin with a battle plan. He asks for two facts first: whether Sita is alive and where Ravana lives. Only after both are known will he and Sugriva choose the time and form of action. Rescue begins with reliable discovery rather than heroic guesswork.'),
  ('scene-vinata-takes-the-rising-road', 'rama-asks-for-knowledge-before-war', 'hi', 'पहला अभियान जानने का है, आक्रमण का नहीं', 'सुग्रीव जुटी सेना राम की आज्ञा में देते हैं, पर राम युद्ध-योजना से शुरुआत नहीं करते। वे पहले दो तथ्य माँगते हैं—क्या सीता जीवित हैं और रावण कहाँ रहता है। दोनों पता चलने के बाद ही वे और सुग्रीव कार्रवाई का समय तथा रूप तय करेंगे। बचाव वीरतापूर्ण अनुमान से नहीं, भरोसेमंद खोज से शुरू होता है।'),
  ('scene-vinata-takes-the-rising-road', 'rama-gives-sugriva-operational-command', 'en', 'Trust includes letting the expert lead', 'Rama says neither he nor Lakshmana should direct this search, because Sugriva knows the forces, terrain, seasons and routes. He calls Sugriva a friend whose judgment can serve their welfare. The handover is not surrender of purpose; it assigns operational leadership to the person with the knowledge needed to make the purpose possible.'),
  ('scene-vinata-takes-the-rising-road', 'rama-gives-sugriva-operational-command', 'hi', 'विश्वास में विशेषज्ञ को नेतृत्व देना भी शामिल है', 'राम कहते हैं कि इस खोज का निर्देशन न वे करें, न लक्ष्मण, क्योंकि सुग्रीव सेना, भूभाग, ऋतु और मार्ग जानते हैं। वे सुग्रीव को ऐसा मित्र कहते हैं जिसकी बुद्धि उनके हित में काम कर सकती है। यह उद्देश्य छोड़ना नहीं; उद्देश्य संभव बनाने वाले ज्ञानवान व्यक्ति को संचालन सौंपना है।'),
  ('scene-vinata-takes-the-rising-road', 'vinata-receives-the-eastern-world', 'en', 'Vinata receives rivers, cities, islands and the sunrise', 'Sugriva assigns Vinata a large eastern force and a route through great rivers, cultivated lands, forests, cities, mountain caves and ocean islands. Familiar waterways gradually give way to wondrous beings, red and milk-white seas and the mountain where daylight first appears. Every landscape is a place to inspect, not proof that Sita passed through it.'),
  ('scene-vinata-takes-the-rising-road', 'vinata-receives-the-eastern-world', 'hi', 'विनत को नदियाँ, नगर, द्वीप और सूर्योदय की दिशा मिलती है', 'सुग्रीव विनत को विशाल पूर्वी दल और महान नदियों, बसे प्रदेशों, वनों, नगरों, पर्वत-गुफाओं तथा समुद्री द्वीपों से गुजरता मार्ग देते हैं। परिचित जलधाराएँ धीरे-धीरे अद्भुत प्राणियों, लाल और दूधिया समुद्रों तथा उस पर्वत तक पहुँचती हैं जहाँ दिन का प्रकाश पहले दिखता है। हर भूभाग खोजने की जगह है, यह प्रमाण नहीं कि सीता वहाँ से गुजरीं।'),
  ('scene-vinata-takes-the-rising-road', 'the-east-has-a-limit-and-deadline', 'en', 'Even an immense map has a return boundary', 'At the rising mountain, Sugriva marks the farthest point his knowledge and the party''s movement can support. Beyond lies a sunless, unbounded region he will not pretend to understand. Vinata must search every accessible cave and stream, then return within one month with findings. Discipline means knowing where exploration stops as well as where it begins.'),
  ('scene-vinata-takes-the-rising-road', 'the-east-has-a-limit-and-deadline', 'hi', 'विशाल मानचित्र की भी वापसी-सीमा है', 'उदय पर्वत पर सुग्रीव वह अंतिम बिंदु बताते हैं जहाँ तक उनका ज्ञान और दल की गति साथ दे सकती है। आगे सूर्यहीन, असीम क्षेत्र है जिसे वे जानने का दिखावा नहीं करते। विनत को हर पहुँच योग्य गुफा और धारा खोजकर एक महीने में समाचार सहित लौटना है। अनुशासन में यह जानना भी शामिल है कि खोज कहाँ रुकती है।'),
  ('scene-angada-leads-the-southern-hope', 'angada-leads-veterans-and-specialists', 'en', 'Youth leads, experience surrounds it', 'Sugriva appoints Angada to lead the southern party, but does not leave the young prince alone with rank. Hanuman, Jambavan, Nila, Mainda, Dvivida, Gandhamadana and other proven figures travel with him. The team combines authority, endurance, engineering sense, memory and unusual movement rather than betting everything on one kind of strength.'),
  ('scene-angada-leads-the-southern-hope', 'angada-leads-veterans-and-specialists', 'hi', 'युवा नेतृत्व करता है, अनुभव उसे घेरता है', 'सुग्रीव अंगद को दक्षिणी दल का नेता बनाते हैं, पर युवा राजकुमार को केवल पद के भरोसे नहीं छोड़ते। हनुमान, जाम्बवान, नील, मैन्द, द्विविद, गंधमादन और अन्य अनुभवी वीर साथ चलते हैं। दल अधिकार, धैर्य, निर्माण-बुद्धि, स्मृति और असाधारण गति को जोड़ता है; एक ही प्रकार की शक्ति पर दाँव नहीं लगाता।'),
  ('scene-angada-leads-the-southern-hope', 'the-southern-route-crosses-known-lands', 'en', 'Rivers and kingdoms lead toward the sea', 'Their route runs through the Vindhya ranges, Narmada, Godavari, Krishnaveni, Dandaka, Kalinga, Andhra, Chola, Pandya and Kerala regions, then toward Kaveri, Tamraparni and the southern coast. The names form an ordered chain: inspect settlements, forests, caves and crossings in sequence until land ends.'),
  ('scene-angada-leads-the-southern-hope', 'the-southern-route-crosses-known-lands', 'hi', 'नदियाँ और राज्य समुद्र की ओर ले जाते हैं', 'उनका मार्ग विंध्य, नर्मदा, गोदावरी, कृष्णवेणी, दंडक, कलिंग, आंध्र, चोल, पांड्य और केरल प्रदेशों से होकर कावेरी, ताम्रपर्णी तथा दक्षिणी तट तक जाता है। ये नाम एक क्रमबद्ध शृंखला बनाते हैं—बस्तियाँ, वन, गुफाएँ और पारियाँ देखते हुए उस जगह तक जाओ जहाँ भूमि समाप्त होती है।'),
  ('scene-angada-leads-the-southern-hope', 'the-route-points-toward-ravanas-island', 'en', 'Across the sea lies the strongest lead', 'At Mahendra and the southern ocean, Sugriva describes an island a hundred yojanas away and says Ravana''s realm must be searched there with special care. He also warns of a shadow-catching predator in the sea. The route offers the first specific suspicion about the captor''s territory, but the party still has to reach and verify it.'),
  ('scene-angada-leads-the-southern-hope', 'the-route-points-toward-ravanas-island', 'hi', 'समुद्र पार सबसे मजबूत संकेत है', 'महेंद्र और दक्षिणी समुद्र पर सुग्रीव सौ योजन दूर एक द्वीप बताते और कहते हैं कि रावण के क्षेत्र को वहाँ विशेष सावधानी से खोजना होगा। वे समुद्र में छाया पकड़ने वाली राक्षसी से भी चेताते हैं। मार्ग अपहरणकर्ता के क्षेत्र का पहला ठोस संदेह देता है, पर दल को वहाँ पहुँचकर सत्य जाँचना अभी बाकी है।'),
  ('scene-angada-leads-the-southern-hope', 'south-also-has-an-edge', 'en', 'Search far, then return with truth', 'Beyond the suspected island, Sugriva names further mountains, serpent halls and increasingly inaccessible realms, then forbids entry into the dark land of the dead. The party receives the same one-month limit as the others. Whoever truly sees Sita will be cherished, but courage is measured by useful return, not disappearance into wonders without a report.'),
  ('scene-angada-leads-the-southern-hope', 'south-also-has-an-edge', 'hi', 'दूर तक खोजो, फिर सत्य लेकर लौटो', 'संदिग्ध द्वीप के आगे सुग्रीव और पर्वत, नाग-भवन तथा कठिन क्षेत्र बताते हैं, फिर मृतकों की अँधेरी भूमि में प्रवेश रोकते हैं। दल को भी एक महीने की सीमा मिलती है। जो सच में सीता को देखेगा वह अत्यंत प्रिय होगा, पर साहस की कसौटी उपयोगी समाचार लेकर लौटना है, चमत्कारों में बिना सूचना गायब हो जाना नहीं।'),
  ('scene-sushena-takes-the-setting-road', 'sugriva-bows-before-giving-command', 'en', 'Authority can still show respect', 'Sushena is Tara''s father and Sugriva''s elder, so the king approaches with folded hands before assigning him command. Respect does not make the order vague: Sushena receives a vast force and responsibility for the west. Sugriva separates personal relationship from operational clarity instead of using either to weaken the other.'),
  ('scene-sushena-takes-the-setting-road', 'sugriva-bows-before-giving-command', 'hi', 'अधिकार के साथ सम्मान भी रह सकता है', 'सुषेण तारा के पिता और सुग्रीव के वरिष्ठ हैं, इसलिए राजा आदेश देने से पहले हाथ जोड़कर उनके पास जाते हैं। सम्मान आदेश को धुँधला नहीं बनाता—सुषेण को विशाल दल और पश्चिम की जिम्मेदारी मिलती है। सुग्रीव व्यक्तिगत संबंध और संचालन की स्पष्टता को अलग रखते हैं, किसी एक से दूसरे को कमजोर नहीं करते।'),
  ('scene-sushena-takes-the-setting-road', 'west-means-coasts-ports-and-hard-ground', 'en', 'The setting road crosses inhabited and empty worlds', 'Sushena''s route crosses western provinces, busy cities, river mouths, ascetic forests, cold cliffs, deserts, coconut shores and ports before reaching the ocean. Searchers must inspect where people gather as carefully as caves and wilderness. Sita may be concealed behind political power, trade movement or remote terrain; no single landscape receives automatic priority.'),
  ('scene-sushena-takes-the-setting-road', 'west-means-coasts-ports-and-hard-ground', 'hi', 'अस्त की राह बसे और सूने दोनों संसारों से गुजरती है', 'सुषेण का मार्ग पश्चिमी प्रदेशों, व्यस्त नगरों, नदी-मुखों, तपोवनों, ठंडी चट्टानों, मरुभूमि, नारियल तटों और बंदरगाहों से होकर समुद्र तक जाता है। खोजियों को लोगों की भीड़ उतनी ही सावधानी से देखनी है जितनी गुफाएँ और वन। सीता सत्ता, व्यापारिक गति या दूरस्थ भूभाग के पीछे छिपी हो सकती हैं; किसी एक दृश्य को स्वतः प्राथमिकता नहीं।'),
  ('scene-sushena-takes-the-setting-road', 'ocean-mountains-demand-restraint', 'en', 'Not every wondrous place should be provoked', 'Beyond the coast, the route passes mountains of giant birds, guarded fruit, hard caves and legendary cities within the sea. Sugriva warns the party not to steal or challenge powerful inhabitants while searching. Their task is observation and inquiry, not conquest of every unfamiliar community encountered on the way to Ravana.'),
  ('scene-sushena-takes-the-setting-road', 'ocean-mountains-demand-restraint', 'hi', 'हर अद्भुत स्थान को ललकारना उचित नहीं', 'तट के आगे मार्ग विशाल पक्षियों वाले पर्वतों, सुरक्षित फलों, कठिन गुफाओं और समुद्र के भीतर अद्भुत नगरों से गुजरता है। सुग्रीव चेताते हैं कि खोज के दौरान शक्तिशाली निवासियों को उकसाएँ या उनकी वस्तु न लें। उनका काम देखना और पूछना है, रावण तक जाते हर अपरिचित समुदाय को जीतना नहीं।'),
  ('scene-sushena-takes-the-setting-road', 'sunset-marks-the-western-return', 'en', 'The setting mountain closes the route', 'At Meru and the setting mountain, the sun disappears and Sugriva again admits that the sunless beyond exceeds his knowledge. Sushena must ask the ascetic Merusavarni for information, inspect every accessible place and return when the month ends. Experience guides the expedition, but its strongest sign is the refusal to invent knowledge past the map''s edge.'),
  ('scene-sushena-takes-the-setting-road', 'sunset-marks-the-western-return', 'hi', 'अस्त पर्वत पश्चिमी मार्ग बंद करता है', 'मेरु और अस्त पर्वत पर सूर्य ओझल होता है और सुग्रीव फिर मानते हैं कि उसके आगे का अँधेरा उनके ज्ञान से बाहर है। सुषेण को तपस्वी मेरुसावर्णि से सूचना पूछनी, हर पहुँच योग्य स्थान देखना और महीना पूरा होते लौटना है। अनुभव का सबसे मजबूत संकेत यह है कि वह मानचित्र की सीमा के आगे ज्ञान गढ़ता नहीं।'),
  ('scene-satavali-takes-the-northern-road', 'service-repays-the-restored-life', 'en', 'Sugriva gives the search a moral center', 'Before describing terrain, Sugriva tells Satavali that helping Rama in return will make their restored lives meaningful. Rama did not aid them as a transaction calculated in advance, yet gratitude now demands competent service. The northern party is not sent to perform loyalty as spectacle; it must discover Sita and reduce a real debt through useful work.'),
  ('scene-satavali-takes-the-northern-road', 'service-repays-the-restored-life', 'hi', 'सुग्रीव खोज को नैतिक केंद्र देते हैं', 'भूभाग बताने से पहले सुग्रीव शतबलि से कहते हैं कि राम की सहायता लौटाना उनके पुनः मिले जीवन को सार्थक बनाएगा। राम ने पहले से गणना किए सौदे की तरह मदद नहीं की, फिर भी कृतज्ञता अब सक्षम सेवा माँगती है। उत्तरी दल निष्ठा का प्रदर्शन करने नहीं, सीता को खोजकर वास्तविक ऋण को कर्म से घटाने जाता है।'),
  ('scene-satavali-takes-the-northern-road', 'the-route-climbs-through-himalaya', 'en', 'The north rises through peoples, forests and snow', 'Satavali must cross many communities before entering Himalayan forests, gold-bearing mountains, high caves and the pale heights of Kailasa. Sugriva''s directions move from inhabited lands to increasingly difficult altitude. Every transition changes what the party needs—local inquiry below, endurance and careful cavern search above.'),
  ('scene-satavali-takes-the-northern-road', 'the-route-climbs-through-himalaya', 'hi', 'उत्तर जनपदों, वनों और हिम से ऊपर चढ़ता है', 'शतबलि को हिमालयी वनों, स्वर्णयुक्त पर्वतों, ऊँची गुफाओं और कैलास की धवल ऊँचाइयों में जाने से पहले अनेक समुदायों से गुजरना है। सुग्रीव के निर्देश बसे भूभाग से कठिन ऊँचाई की ओर बढ़ते हैं। हर परिवर्तन दल की आवश्यकता बदलता है—नीचे स्थानीय पूछताछ, ऊपर धैर्य और सावधान गुफा-खोज।'),
  ('scene-satavali-takes-the-northern-road', 'the-far-north-changes-the-rules', 'en', 'Beyond the desert, light no longer comes from the sky', 'The route crosses a lifeless hundred-yojana waste into lands of wondrous lakes, wish-bearing trees, self-luminous ascetics and the northern Kurus. These places belong to the expedition''s mythic far distance, where ordinary day and travel rules loosen. The party must still ask, inspect and avoid confusing marvel with evidence of Sita.'),
  ('scene-satavali-takes-the-northern-road', 'the-far-north-changes-the-rules', 'hi', 'मरुभूमि के आगे प्रकाश आकाश से नहीं आता', 'मार्ग सौ योजन के निर्जीव विस्तार को पार कर अद्भुत झीलों, इच्छा पूरी करने वाले वृक्षों, स्वयं प्रकाशमान तपस्वियों और उत्तर कुरुओं की भूमि तक पहुँचता है। यह अभियान की अलौकिक दूर सीमा है जहाँ सामान्य दिन और यात्रा के नियम ढीले पड़ते हैं। फिर भी दल को पूछना, देखना और चमत्कार को सीता का प्रमाण न मानना है।'),
  ('scene-satavali-takes-the-northern-road', 'soma-mountain-is-the-northern-limit', 'en', 'A shining summit marks the final turn back', 'At the northern ocean, Soma mountain shines without sun and marks the last region Sugriva can name. No path continues beyond it for the searchers, so they must sight the summit and turn back. The command protects them from converting devotion into endless risk and keeps the mission answerable to Rama within a finite time.'),
  ('scene-satavali-takes-the-northern-road', 'soma-mountain-is-the-northern-limit', 'hi', 'प्रकाशमान शिखर अंतिम वापसी-बिंदु बनता है', 'उत्तरी समुद्र पर सोम पर्वत बिना सूर्य के चमकता और सुग्रीव के ज्ञात अंतिम क्षेत्र को चिह्नित करता है। खोजियों के लिए उससे आगे कोई मार्ग नहीं, इसलिए शिखर देखकर लौटना है। आदेश भक्ति को अंतहीन जोखिम बनने से रोकता और अभियान को सीमित समय में राम के प्रति उत्तरदायी रखता है।'),
  ('scene-rama-entrusts-hanuman-with-the-ring', 'sugriva-names-hanumans-complete-fitness', 'en', 'Range matters because judgment travels with it', 'Sugriva tells Hanuman that earth, sky, water and hidden regions cannot obstruct him, but speed is only part of the trust. He also names strength, courage, policy, conduct and the ability to judge time and place. Finding Sita may require crossing an impossible distance, then knowing how to approach without causing fresh danger.'),
  ('scene-rama-entrusts-hanuman-with-the-ring', 'sugriva-names-hanumans-complete-fitness', 'hi', 'गति इसलिए महत्वपूर्ण है क्योंकि बुद्धि उसके साथ चलती है', 'सुग्रीव हनुमान से कहते हैं कि धरती, आकाश, जल और गुप्त क्षेत्र उनकी गति नहीं रोक सकते, पर भरोसा केवल वेग पर नहीं है। वे शक्ति, साहस, नीति, आचरण और समय-स्थान की समझ भी गिनाते हैं। सीता को खोजने में असंभव दूरी पार करने के बाद यह जानना भी होगा कि नई हानि किए बिना पास कैसे जाएँ।'),
  ('scene-rama-entrusts-hanuman-with-the-ring', 'rama-reads-sugrivas-confidence', 'en', 'One expert''s trust becomes another''s evidence', 'Rama notices that Sugriva relies on Hanuman after testing him in real work, and sees Hanuman''s own quiet confidence. He does not choose merely from reputation or affection. Sugriva knows the searchers; Hanuman has already shown intelligence at Pampa; together those observations make Rama believe success is possible.'),
  ('scene-rama-entrusts-hanuman-with-the-ring', 'rama-reads-sugrivas-confidence', 'hi', 'एक विशेषज्ञ का भरोसा दूसरे के लिए प्रमाण बनता है', 'राम देखते हैं कि सुग्रीव वास्तविक काम में परखने के बाद हनुमान पर निर्भर हैं और हनुमान में शांत आत्मविश्वास भी है। वे केवल प्रसिद्धि या स्नेह से चुनाव नहीं करते। सुग्रीव खोजियों को जानते हैं, हनुमान पंपा पर बुद्धि दिखा चुके हैं; ये दोनों प्रमाण राम को सफलता संभव लगाते हैं।'),
  ('scene-rama-entrusts-hanuman-with-the-ring', 'the-ring-can-cross-fear', 'en', 'A small object carries a private certainty', 'Rama gives Hanuman a ring inscribed with his name so Sita can recognize that an unfamiliar visitor truly comes from him. The object is not a reward or magical shortcut. It solves a human problem inside captivity: a frightened person needs a sign that cannot be supplied by bold claims alone before she risks speaking freely.'),
  ('scene-rama-entrusts-hanuman-with-the-ring', 'the-ring-can-cross-fear', 'hi', 'छोटी-सी मुद्रिका निजी निश्चितता लेकर चलती है', 'राम हनुमान को अपने नाम वाली मुद्रिका देते हैं ताकि सीता पहचान सकें कि अपरिचित आगंतुक सच में उनकी ओर से आया है। वस्तु पुरस्कार या जादुई आसान रास्ता नहीं। वह कैद की मानवीय समस्या हल करती है—डरी हुई व्यक्ति को खुलकर बोलने से पहले ऐसा चिह्न चाहिए जो केवल बड़े दावे नहीं दे सकते।'),
  ('scene-rama-entrusts-hanuman-with-the-ring', 'hanuman-accepts-without-a-boast', 'en', 'The most important commission leaves quietly', 'Hanuman receives the ring, bows and joins the departing southern host. He does not answer with the extravagant promises heard around the assembly. Rama places refuge in his strength and asks him to exert it toward one result: bringing Janaka''s daughter within reach again. The trust is immense, but the next step remains ordinary search.'),
  ('scene-rama-entrusts-hanuman-with-the-ring', 'hanuman-accepts-without-a-boast', 'hi', 'सबसे महत्वपूर्ण दायित्व शांत भाव से निकलता है', 'हनुमान मुद्रिका लेते, प्रणाम करते और दक्षिणी दल में शामिल हो जाते हैं। वे सभा के आसपास सुनाई दे रहे अतिशयोक्त दावे नहीं दोहराते। राम उनकी शक्ति में आश्रय रखकर एक परिणाम माँगते हैं—जनक की पुत्री को फिर पहुँच के भीतर लाना। भरोसा विशाल है, पर अगला कदम अभी साधारण खोज ही है।'),
  ('scene-four-forces-leave-kishkindha', 'the-world-map-activates-at-once', 'en', 'Four directions leave from one purpose', 'Vinata moves east, Satavali north, Sushena west, and Angada''s party with Hanuman moves south. The departures are coordinated rather than sequential, so no horizon receives a month''s head start over another. Sugriva''s assembly becomes a distributed search network whose parts share one deadline and one missing person.'),
  ('scene-four-forces-leave-kishkindha', 'the-world-map-activates-at-once', 'hi', 'एक उद्देश्य से चार दिशाएँ निकलती हैं', 'विनत पूर्व, शतबलि उत्तर, सुषेण पश्चिम और हनुमान सहित अंगद का दल दक्षिण जाता है। प्रस्थान क्रमशः नहीं, एक साथ होते हैं, इसलिए किसी दिशा को दूसरी पर महीने भर की बढ़त नहीं मिलती। सुग्रीव की सभा एक वितरित खोज-जाल बनती है जिसके सभी भागों की समय-सीमा और लापता व्यक्ति एक ही है।'),
  ('scene-four-forces-leave-kishkindha', 'rama-waits-beside-the-fountain', 'en', 'Command gives way to an uncertain month', 'Rama and Lakshmana remain near Prasravana while searchers move beyond sight. Rama can no longer improve the mission by issuing more orders; he must trust people, routes and reports he cannot watch. The same month that gives teams enough time to work gives him thirty more days in which no news may arrive.'),
  ('scene-four-forces-leave-kishkindha', 'rama-waits-beside-the-fountain', 'hi', 'आदेश के बाद अनिश्चित महीने की प्रतीक्षा आती है', 'राम और लक्ष्मण प्रस्रवण के पास रहते हैं जबकि खोजी दृष्टि से बाहर चले जाते हैं। अब अधिक आदेश देकर राम अभियान सुधार नहीं सकते; उन्हें उन लोगों, मार्गों और समाचारों पर भरोसा करना है जिन्हें वे देख नहीं सकते। जो महीना दलों को काम का समय देता है वही उन्हें तीस और ऐसे दिन देता है जिनमें कोई समाचार न आए।'),
  ('scene-four-forces-leave-kishkindha', 'the-searchers-roar-their-confidence', 'en', 'Departure turns into competitive boasting', 'As the forces leave, searchers shout that they will find Sita, kill Ravana, split mountains, cross oceans or descend beneath the earth alone. The boasts release months of tension and show abundant courage. They also expose a gap between imagined victory and actual search, where sleep, thirst, wrong turns and empty evidence will matter more than volume.'),
  ('scene-four-forces-leave-kishkindha', 'the-searchers-roar-their-confidence', 'hi', 'प्रस्थान प्रतिस्पर्धी दावों में बदलता है', 'दल निकलते समय पुकारते हैं कि वे सीता को पाएँगे, रावण को मारेंगे, पर्वत चीरेंगे, समुद्र लाँघेंगे या अकेले पाताल उतरेंगे। दावे महीनों का तनाव छोड़ते और प्रचुर साहस दिखाते हैं। वे कल्पित विजय और वास्तविक खोज का अंतर भी खोलते हैं, जहाँ आवाज से अधिक नींद, प्यास, गलत मोड़ और खाली प्रमाण मायने रखेंगे।'),
  ('scene-four-forces-leave-kishkindha', 'bravery-has-not-yet-become-evidence', 'en', 'Power claims do not locate Sita', 'Some claim a one-yojana leap, others a hundred or more, and each imagines no obstacle can stop him. Yet none can answer Rama''s first questions. The mission therefore leaves with confidence deliberately uncounted as progress: only inspected ground, reliable witness and a verified sign of Sita or Ravana can change the search state.'),
  ('scene-four-forces-leave-kishkindha', 'bravery-has-not-yet-become-evidence', 'hi', 'शक्ति के दावे सीता का स्थान नहीं बताते', 'कोई एक योजन, कोई सौ या उससे अधिक की छलाँग का दावा करता और हर कोई स्वयं को अजेय मानता है। फिर भी कोई राम के पहले प्रश्नों का उत्तर नहीं दे सकता। इसलिए अभियान आत्मविश्वास को प्रगति माने बिना निकलता है—केवल देखा भूभाग, भरोसेमंद साक्षी और सीता या रावण का सत्यापित संकेत खोज की स्थिति बदलेगा।'),
  ('scene-sugrivas-flight-becomes-the-map', 'rama-asks-who-could-know-so-much', 'en', 'The map itself needs an origin', 'After the forces depart, Rama asks how Sugriva knows rivers, mountains, seas and remote limits in every direction. He does not accept comprehensive confidence without asking how it was earned. Sugriva''s answer will reveal that the route plan came neither from a throne room nor from effortless omniscience.'),
  ('scene-sugrivas-flight-becomes-the-map', 'rama-asks-who-could-know-so-much', 'hi', 'मानचित्र के ज्ञान का भी स्रोत चाहिए', 'दल निकलने के बाद राम पूछते हैं कि सुग्रीव हर दिशा की नदियाँ, पर्वत, समुद्र और दूर सीमाएँ कैसे जानते हैं। वे व्यापक आत्मविश्वास को उसके अर्जन की कथा पूछे बिना स्वीकार नहीं करते। सुग्रीव का उत्तर बताएगा कि यह मार्ग-योजना न सिंहासन-कक्ष से आई, न सहज सर्वज्ञता से।'),
  ('scene-sugrivas-flight-becomes-the-map', 'the-cave-mistake-begins-the-exile', 'en', 'A sealed cave becomes the first wound', 'Sugriva recalls waiting outside a cave while Vali pursued an enemy within. After a year, blood flowed out and no brother emerged, so grief convinced him Vali was dead; he sealed the entrance and returned. Vali survived, interpreted the act as betrayal and reclaimed the kingdom in rage. The map begins with a disastrous conclusion drawn from incomplete evidence.'),
  ('scene-sugrivas-flight-becomes-the-map', 'the-cave-mistake-begins-the-exile', 'hi', 'बंद की गई गुफा पहला घाव बनती है', 'सुग्रीव याद करते हैं कि वाली एक शत्रु के पीछे गुफा में गए और वे बाहर प्रतीक्षा करते रहे। एक वर्ष बाद रक्त निकला, भाई नहीं; शोक ने उन्हें वाली की मृत्यु मानने पर मजबूर किया, उन्होंने द्वार बंद किया और लौट गए। वाली जीवित आए, इसे विश्वासघात समझा और क्रोध में राज्य वापस लिया। मानचित्र अधूरे प्रमाण से निकले विनाशकारी निष्कर्ष से शुरू होता है।'),
  ('scene-sugrivas-flight-becomes-the-map', 'vali-chases-sugriva-around-the-world', 'en', 'Flight forces every horizon into memory', 'Vali pursues Sugriva from east to south, west and north. Seeking any refuge, Sugriva crosses forests, cities, caves, sunrise and sunset mountains, Himalaya, Meru and the northern sea. He learns because his life depends on reading terrain quickly, turning a terrified circuit of the earth into the embodied route knowledge he later gives the search parties.'),
  ('scene-sugrivas-flight-becomes-the-map', 'vali-chases-sugriva-around-the-world', 'hi', 'भागते हुए हर क्षितिज स्मृति में उतरता है', 'वाली सुग्रीव का पीछा पूर्व से दक्षिण, पश्चिम और उत्तर तक करते हैं। आश्रय खोजते सुग्रीव वन, नगर, गुफाएँ, उदय-अस्त पर्वत, हिमालय, मेरु और उत्तरी समुद्र पार करते हैं। उनका जीवन भूभाग जल्दी पढ़ने पर निर्भर था; धरती का भयभीत चक्कर बाद में खोज-दलों को दिया गया शरीर में बसा मार्ग-ज्ञान बनता है।'),
  ('scene-sugrivas-flight-becomes-the-map', 'hanuman-remembers-the-one-safe-place', 'en', 'The chase ends when memory finds a boundary', 'When no direction provides safety, Hanuman remembers Matanga''s curse: Vali cannot enter Rishyamuka without dying. The fugitives turn there and finally stop. Sugriva''s world knowledge is therefore shared as well as personal—his flight mapped distance, while Hanuman''s remembered local rule found the refuge that distance alone could not.'),
  ('scene-sugrivas-flight-becomes-the-map', 'hanuman-remembers-the-one-safe-place', 'hi', 'पीछा तब रुकता है जब स्मृति सुरक्षित सीमा पाती है', 'जब किसी दिशा में सुरक्षा नहीं मिलती, हनुमान मतंग का श्राप याद करते हैं—वाली ऋष्यमूक में प्रवेश करेंगे तो मरेंगे। शरणार्थी वहाँ मुड़कर अंततः रुकते हैं। इसलिए सुग्रीव का भूज्ञान व्यक्तिगत और साझा दोनों है—उनकी भागती यात्रा ने दूरी नापी, हनुमान की स्थानीय स्मृति ने वह आश्रय पाया जो दूरी अकेले नहीं दे सकती थी।'),
  ('scene-three-directions-return-empty', 'the-search-was-daily-not-symbolic', 'en', 'A month is spent walking, inspecting and sleeping outside', 'The parties cross rivers, flooded ground, grasslands, cities, mountains, caves, islands and forests by day, then sleep wherever they can at night. Their one-month limit is filled with repetitive labour rather than a quick tour of named places. Fruit and seasonal trees sustain them, but no convenience turns breadth into certainty.'),
  ('scene-three-directions-return-empty', 'the-search-was-daily-not-symbolic', 'hi', 'महीना चलने, जाँचने और खुले में सोने में बीतता है', 'दल दिन में नदियाँ, बाढ़ वाले मैदान, घासभूमि, नगर, पर्वत, गुफाएँ, द्वीप और वन पार करते तथा रात को जहाँ संभव हो सोते हैं। एक महीने की सीमा केवल नामित स्थानों की तेज यात्रा नहीं, दोहराए श्रम से भरती है। फल और ऋतु-वृक्ष उन्हें जीवित रखते हैं, पर कोई सुविधा विस्तार को निश्चितता नहीं बनाती।'),
  ('scene-three-directions-return-empty', 'vinata-and-satavali-report-no-sighting', 'en', 'East and north return without inventing success', 'Vinata returns from the east and Satavali from the north after searching the regions assigned to them. Both are disheartened and neither claims a doubtful footprint as Sita. Their empty reports hurt, but they protect the mission from chasing fabricated certainty merely to satisfy a severe king and an anxious Rama.'),
  ('scene-three-directions-return-empty', 'vinata-and-satavali-report-no-sighting', 'hi', 'पूर्व और उत्तर सफलता गढ़े बिना लौटते हैं', 'विनत पूर्व से और शतबलि उत्तर से सौंपे क्षेत्रों को खोजकर लौटते हैं। दोनों निराश हैं और कोई संदिग्ध पदचिह्न को सीता का बताकर दावा नहीं करता। खाली समाचार पीड़ादायक हैं, पर वे कठोर राजा और चिंतित राम को संतुष्ट करने के लिए गढ़ी निश्चितता के पीछे अभियान को भटकने से बचाते हैं।'),
  ('scene-three-directions-return-empty', 'sushena-confirms-the-west-is-exhausted', 'en', 'West brings a detailed empty answer', 'Sushena reports that mountains, forests, streams, islands, provinces, caves, groves and difficult ground were searched repeatedly. His detail matters because ''not found'' is useful only when the covered boundary is known. The west is not declared eternally impossible; it is removed from this month''s evidence-based priority.'),
  ('scene-three-directions-return-empty', 'sushena-confirms-the-west-is-exhausted', 'hi', 'पश्चिम विस्तृत पर खाली उत्तर लाता है', 'सुषेण बताते हैं कि पर्वत, वन, धाराएँ, द्वीप, प्रदेश, गुफाएँ, उपवन और कठिन भूमि बार-बार खोजी गई। विवरण जरूरी है क्योंकि ''नहीं मिली'' तभी उपयोगी है जब खोजी सीमा ज्ञात हो। पश्चिम को सदा के लिए असंभव नहीं कहा जाता; इस महीने के प्रमाण-आधारित प्राथमिक मार्ग से हटाया जाता है।'),
  ('scene-three-directions-return-empty', 'absence-points-toward-the-unreturned-south', 'en', 'Three failures leave one live direction', 'Sushena says Hanuman is the one most likely to discover Sita and that he follows the direction in which she was taken. East, north and west are back; the southern party is not. Hope narrows without becoming proof. Their lateness may mean discovery, distance, danger or failure, and Rama must wait for the distinction.'),
  ('scene-three-directions-return-empty', 'absence-points-toward-the-unreturned-south', 'hi', 'तीन असफलताएँ एक जीवित दिशा छोड़ती हैं', 'सुषेण कहते हैं कि सीता का स्थान जानने की सबसे अधिक क्षमता हनुमान में है और वे उसी दिशा में गए हैं जिधर उनका अपहरण हुआ। पूर्व, उत्तर और पश्चिम लौट चुके हैं; दक्षिण नहीं। आशा सीमित होती है, प्रमाण नहीं बनती। देर का अर्थ खोज, दूरी, संकट या असफलता कुछ भी हो सकता है और राम को अंतर जानने तक प्रतीक्षा करनी होगी।'),
  ('scene-the-south-enters-the-cursed-forest', 'the-south-searches-beyond-easy-survival', 'en', 'The route loses water, food and animal life', 'Hanuman, Angada and their companions search Vindhya caves, streams, tanks and forests until they enter a still region with no water, fruit, flowers, animals or birds. Hunger and fatigue become operational threats. The team can no longer assume that the next day''s movement will be supported by the landscape.'),
  ('scene-the-south-enters-the-cursed-forest', 'the-south-searches-beyond-easy-survival', 'hi', 'मार्ग से जल, भोजन और जीव-जगत गायब हो जाते हैं', 'हनुमान, अंगद और उनके साथी विंध्य की गुफाएँ, धाराएँ, ताल तथा वन खोजते हुए ऐसे स्थिर क्षेत्र में पहुँचते हैं जहाँ जल, फल, फूल, पशु या पक्षी कुछ नहीं। भूख और थकान अभियान के संकट बनते हैं। दल अब यह नहीं मान सकता कि अगले दिन की यात्रा को भूभाग स्वयं सहारा देगा।'),
  ('scene-the-south-enters-the-cursed-forest', 'grief-is-written-into-the-dead-forest', 'en', 'The barren land carries an old loss', 'The forest''s emptiness is linked to the ascetic Kandu, whose young son''s death drove him to curse the region. The party does not pause to judge the justice of that response; it experiences the consequence in absent water, creatures and shelter. Another person''s grief has become terrain through which their own urgent grief must travel.'),
  ('scene-the-south-enters-the-cursed-forest', 'grief-is-written-into-the-dead-forest', 'hi', 'बंजर भूमि में पुराना शोक बसा है', 'वन की निर्जनता तपस्वी कंडु से जुड़ी है, जिनके छोटे पुत्र की मृत्यु ने उन्हें क्षेत्र को श्राप देने तक पहुँचा दिया। दल उस प्रतिक्रिया का न्याय तय करने नहीं रुकता; वह जल, जीव और आश्रय की अनुपस्थिति में उसका परिणाम झेलता है। किसी और का शोक ऐसा भूभाग बन गया है जिससे उनका अपना तात्कालिक शोक गुजरता है।'),
  ('scene-the-south-enters-the-cursed-forest', 'angada-strikes-the-wrong-ravana', 'en', 'A charging enemy looks like the answer', 'A huge asura rushes from concealment and threatens to destroy the searchers. Angada concludes in the instant that this must be Ravana and fells him with one blow. The party wins the fight, but identity was assumed under pressure. Strength resolves the danger before knowledge can confirm whether the enemy mattered to Sita.'),
  ('scene-the-south-enters-the-cursed-forest', 'angada-strikes-the-wrong-ravana', 'hi', 'आक्रमण करता शत्रु उत्तर जैसा दिखता है', 'एक विशाल असुर छिपे स्थान से निकलकर खोजियों को नष्ट करने दौड़ता है। अंगद उसी क्षण मान लेते हैं कि यही रावण है और एक प्रहार में उसे गिरा देते हैं। दल युद्ध जीतता है, पर पहचान दबाव में मान ली गई थी। बल खतरा समाप्त कर देता है, ज्ञान यह तय करने से पहले कि शत्रु का सीता से कोई संबंध था या नहीं।'),
  ('scene-the-south-enters-the-cursed-forest', 'victory-leaves-the-search-empty', 'en', 'The cave is cleared, but Sita is not there', 'After the asura falls, the party searches his cavern and nearby mountain spaces thoroughly. They find neither Sita nor any path to Ravana. Exhaustion returns immediately because the dramatic victory changed no mission fact. They emerge, enter another dangerous cave, find nothing again and finally sit beneath a tree with sinking hearts.'),
  ('scene-the-south-enters-the-cursed-forest', 'victory-leaves-the-search-empty', 'hi', 'गुफा साफ हो जाती है, पर सीता वहाँ नहीं हैं', 'असुर के गिरने के बाद दल उसकी गुफा और आसपास के पर्वतीय स्थानों को पूरी तरह खोजता है। न सीता मिलती हैं, न रावण का मार्ग। नाटकीय विजय ने अभियान का कोई तथ्य नहीं बदला, इसलिए थकान तुरंत लौटती है। वे दूसरी खतरनाक गुफा में भी खाली खोजकर निकलते और टूटते मन से एक वृक्ष तले बैठते हैं।'),
  ('scene-angada-refuses-despair', 'angada-names-the-failure-without-ending-the-mission', 'en', 'The leader says what has not been found', 'Angada gathers the exhausted party and states the truth: forests, rivers, valleys and caves have been searched, but neither Sita nor her captor has appeared. Much of Sugriva''s allotted month is gone. Naming failure prevents false confidence, yet he refuses to turn an unfinished deadline into permission to stop while ground remains unchecked.'),
  ('scene-angada-refuses-despair', 'angada-names-the-failure-without-ending-the-mission', 'hi', 'नेता साफ कहते हैं कि क्या नहीं मिला', 'अंगद थके दल को जुटाकर सच कहते हैं—वन, नदियाँ, घाटियाँ और गुफाएँ खोजी गईं, पर न सीता मिलीं, न अपहरणकर्ता। सुग्रीव के दिए महीने का बड़ा भाग बीत चुका है। असफलता का नाम झूठा आत्मविश्वास रोकता है, पर वे बची भूमि रहते अधूरी समय-सीमा को रुकने की अनुमति नहीं बनने देते।'),
  ('scene-angada-refuses-despair', 'fear-is-admitted-as-part-of-the-pressure', 'en', 'Duty and punishment both drive the party', 'Angada reminds them that Sugriva punishes failure severely and that Rama''s need is immense. His encouragement is not free of fear; the party searches under obligation as well as care for Sita. That mixed motive matters because exhaustion does not disappear when a leader invokes courage, and coercive pressure can produce both persistence and bad judgment.'),
  ('scene-angada-refuses-despair', 'fear-is-admitted-as-part-of-the-pressure', 'hi', 'कर्तव्य और दंड दोनों दल को आगे धकेलते हैं', 'अंगद याद दिलाते हैं कि सुग्रीव असफलता पर कठोर दंड देते हैं और राम की आवश्यकता विशाल है। उनका उत्साह भय से मुक्त नहीं; दल सीता की चिंता के साथ दायित्व और दंड के दबाव में भी खोज रहा है। यह मिश्रित प्रेरणा महत्वपूर्ण है, क्योंकि साहस कह देने से थकान नहीं मिटती और भय दृढ़ता के साथ गलत निर्णय भी पैदा कर सकता है।'),
  ('scene-angada-refuses-despair', 'gandhamadana-turns-speech-into-method', 'en', 'One more attempt receives a concrete pattern', 'Gandhamadana agrees and converts Angada''s appeal into an actionable sweep: rise together, revisit hills, rocks, empty forests, cascades and caves, and search as Sugriva instructed. The response avoids both blind wandering and speeches without movement. Morale becomes useful only when attached to a shared method.'),
  ('scene-angada-refuses-despair', 'gandhamadana-turns-speech-into-method', 'hi', 'एक और प्रयास को ठोस तरीका मिलता है', 'गंधमादन सहमत होकर अंगद की पुकार को काम के क्रम में बदलते हैं—सब साथ उठो, पहाड़, चट्टानें, सूने वन, झरने और गुफाएँ फिर देखो और सुग्रीव के निर्देशानुसार खोजो। उत्तर अंधे भटकाव और बिना गति वाले भाषण दोनों से बचता है। मनोबल तभी उपयोगी है जब वह साझा तरीके से जुड़ता है।'),
  ('scene-angada-refuses-despair', 'the-silver-mountain-yields-no-answer', 'en', 'They climb, search, descend and continue', 'The party climbs the silver-coloured mountain, searches lodhra and saptaparna woods, scans valleys and grottos, then descends without Vaidehi. Some collapse briefly at a tree before strength returns. They rise again and move through Vindhya with Hanuman at the front. Persistence has kept the south alive, but the decisive direction is still hidden.'),
  ('scene-angada-refuses-despair', 'the-silver-mountain-yields-no-answer', 'hi', 'वे चढ़ते, खोजते, उतरते और आगे बढ़ते हैं', 'दल रजत रंग के पर्वत पर चढ़ता, लोध्र और सप्तपर्ण वनों, घाटियों तथा गुफाओं को देखता और वैदेही के बिना उतरता है। कुछ वृक्ष तले थोड़ी देर चेतना और शक्ति खो देते हैं। फिर उठकर हनुमान के आगे विंध्य में बढ़ते हैं। दृढ़ता ने दक्षिणी खोज जीवित रखी है, पर निर्णायक दिशा अभी छिपी है।'),
  ('scene-waterbirds-mark-the-hidden-cave', 'wet-wings-reveal-water', 'en', 'Wet wings reveal what the eyes cannot', 'The southern party is still searching the Vindhya when hunger, thirst and exhaustion begin to break its pace. Hanuman notices waterbirds emerging from a black opening with wet feathers and lotus pollen on their bodies. He cannot see water, yet the birds are evidence that water and plant life survive somewhere inside.'),
  ('scene-waterbirds-mark-the-hidden-cave', 'wet-wings-reveal-water', 'hi', 'भीगे पंख वह बताते हैं जो आँखें नहीं देख पातीं', 'दक्षिणी दल अभी विंध्य में खोज ही रहा है कि भूख, प्यास और थकान उसकी गति तोड़ने लगती है। हनुमान एक काले छिद्र से निकलते जलपक्षियों के भीगे पंखों और शरीर पर लगे कमल-पराग को देखते हैं। पानी दिखाई नहीं देता, फिर भी पक्षी प्रमाण हैं कि भीतर कहीं जल और वनस्पति जीवित हैं।'),
  ('scene-waterbirds-mark-the-hidden-cave', 'the-party-enters-as-one-chain', 'en', 'No one enters the dark alone', 'The entrance gives no light and no promise of return, but remaining outside means dying of thirst. The searchers hold one another by hand and shoulder, placing Hanuman at the front and keeping the weakest within the chain. Their courage is not a fearless charge; it is a shared method for preventing one lost step from separating a companion forever.'),
  ('scene-waterbirds-mark-the-hidden-cave', 'the-party-enters-as-one-chain', 'hi', 'अँधेरे में कोई अकेला प्रवेश नहीं करता', 'प्रवेश-द्वार न प्रकाश देता है, न लौटने का भरोसा, पर बाहर रहना प्यास से मरना है। खोजी हाथ और कंधे पकड़कर श्रृंखला बनाते हैं, हनुमान को आगे रखते हैं और सबसे कमजोर को बीच में सँभालते हैं। उनका साहस निर्भय दौड़ नहीं, बल्कि ऐसा साझा तरीका है जो एक गलत कदम से साथी को हमेशा के लिए बिछुड़ने से बचाता है।'),
  ('scene-waterbirds-mark-the-hidden-cave', 'a-hundred-yojanas-of-darkness', 'en', 'The passage nearly consumes the mission', 'They feel their way through a passage described as a hundred yojanas long. Stone, fatigue and complete darkness erase direction until thirst and weakness bring them near death. The cave is not a shortcut awarded for bravery; it spends time, strength and certainty, forcing the group to survive together before it can search for anyone else.'),
  ('scene-waterbirds-mark-the-hidden-cave', 'a-hundred-yojanas-of-darkness', 'hi', 'अँधेरा लगभग पूरे अभियान को निगल लेता है', 'वे सौ योजन लंबा बताया गया मार्ग टटोलते हुए पार करते हैं। पत्थर, थकान और पूरा अँधेरा दिशा मिटा देते हैं, यहाँ तक कि प्यास और कमजोरी उन्हें मृत्यु के निकट पहुँचा देती है। गुफा साहस का इनाम बनी छोटी राह नहीं; वह समय, शक्ति और विश्वास खर्च कराती है और दल को किसी दूसरे की खोज से पहले स्वयं साथ जीवित रहना सिखाती है।'),
  ('scene-waterbirds-mark-the-hidden-cave', 'gold-breaks-through-the-black', 'en', 'A golden world waits beyond the ordeal', 'Without warning, darkness opens into trees, pools, food and palaces shining like gold. The abundance is so complete that it could be rescue or another danger, so the party does not begin taking whatever it sees. It finds an elderly ascetic woman clothed in bark and asks who she is, who owns this place and whether the exhausted strangers may trust it.'),
  ('scene-waterbirds-mark-the-hidden-cave', 'gold-breaks-through-the-black', 'hi', 'कठिन अँधेरे के पार स्वर्णिम संसार खुलता है', 'अचानक अँधेरा स्वर्ण जैसे चमकते वृक्षों, सरोवरों, भोजन और महलों में खुल जाता है। समृद्धि इतनी पूर्ण है कि वह बचाव भी हो सकती है और नया खतरा भी, इसलिए दल दिखती वस्तुएँ उठाना शुरू नहीं करता। उसे छाल-वस्त्र पहने वृद्ध तपस्विनी मिलती हैं और वह पूछता है कि वे कौन हैं, यह स्थान किसका है और क्या थके अजनबी इस पर भरोसा कर सकते हैं।'),
  ('scene-svayamprabha-names-the-golden-world', 'maya-built-what-stone-should-not-hold', 'en', 'Maya built a world beneath the mountain', 'The guardian explains that the Danava architect Maya created the golden trees, halls, pools and mechanisms after long austerity and mastery of design. What looked like treasure without an owner is a made environment with intention behind every surface. Its beauty is not proof that it is harmless, and its strangeness does not make it free for exhausted travellers to claim.'),
  ('scene-svayamprabha-names-the-golden-world', 'maya-built-what-stone-should-not-hold', 'hi', 'मय ने पर्वत के भीतर एक संसार रचा', 'रक्षिका बताती हैं कि दानव वास्तुकार मय ने दीर्घ तप और शिल्प-कौशल से स्वर्णिम वृक्ष, सभागार, सरोवर और यंत्र रचे थे। जो संपत्ति बिना स्वामी की लग रही थी, वह उद्देश्यपूर्वक बनाया गया संसार है, जिसकी हर सतह के पीछे किसी का श्रम है। उसकी सुंदरता सुरक्षा का प्रमाण नहीं और उसकी विचित्रता थके यात्रियों को उस पर अधिकार नहीं देती।'),
  ('scene-svayamprabha-names-the-golden-world', 'desire-and-violence-change-the-owner', 'en', 'The maker does not keep the world he made', 'Maya''s love for the apsara Hema drew him into conflict, and Indra killed him. Brahma then granted the grove and palace to Hema. Svayamprabha tells this without turning architecture into a simple reward: creation, desire, violence and transfer all sit inside the place the searchers were tempted to treat as an accidental refuge.'),
  ('scene-svayamprabha-names-the-golden-world', 'desire-and-violence-change-the-owner', 'hi', 'निर्माता अपने बनाए संसार का स्वामी नहीं रहता', 'अप्सरा हेमा के प्रति मय का प्रेम संघर्ष में बदल गया और इंद्र ने उसे मार दिया। बाद में ब्रह्मा ने उपवन और महल हेमा को दे दिए। स्वयंप्रभा यह कथा ऐसे सुनाती हैं कि वास्तु केवल पुरस्कार न बने—जिस स्थान को खोजी संयोग का आश्रय मान बैठे थे, उसके भीतर सृजन, इच्छा, हिंसा और स्वामित्व-परिवर्तन सब मौजूद हैं।'),
  ('scene-svayamprabha-names-the-golden-world', 'svayamprabha-is-hemas-trusted-guardian', 'en', 'The woman before them is the keeper', 'She names herself Svayamprabha, daughter of Merusavarni and trusted friend of Hema. Her life in the cave is not captivity or decorative holiness; she has accepted responsibility for a powerful estate that can bewilder and trap intruders. The searchers now know that the person before them has authority, knowledge and agency—not merely magic they can request.'),
  ('scene-svayamprabha-names-the-golden-world', 'svayamprabha-is-hemas-trusted-guardian', 'hi', 'उनके सामने खड़ी स्त्री इस संसार की संरक्षिका हैं', 'वे अपना नाम स्वयंप्रभा बताती हैं—मेरुसावर्णि की पुत्री और हेमा की विश्वस्त सखी। गुफा में उनका जीवन कैद या सजावटी पवित्रता नहीं; उन्होंने ऐसे शक्तिशाली उपवन की जिम्मेदारी ली है जो घुसने वालों को भ्रमित और बंद कर सकता है। अब खोजी समझते हैं कि सामने खड़ी व्यक्ति के पास अधिकार, ज्ञान और निर्णय-शक्ति है, केवल माँगी जा सकने वाली जादुई शक्ति नहीं।'),
  ('scene-svayamprabha-names-the-golden-world', 'food-comes-before-interrogation', 'en', 'A host restores the strangers before asking', 'Svayamprabha offers fruit, roots and clear water before demanding an account. Once the party can breathe and think again, she asks why armed wanderers crossed the deadly darkness and entered Hema''s protected world. Hospitality creates the conditions for truthful speech, while her question makes clear that rescue does not erase the visitors'' responsibility to explain themselves.'),
  ('scene-svayamprabha-names-the-golden-world', 'food-comes-before-interrogation', 'hi', 'मेजबान प्रश्नों से पहले अजनबियों को सँभालती हैं', 'स्वयंप्रभा विवरण माँगने से पहले फल, कंद और स्वच्छ जल देती हैं। जब दल फिर साँस और विचार कर पाता है, तब वे पूछती हैं कि शस्त्रधारी यात्री घातक अँधेरा पार करके हेमा के सुरक्षित संसार में क्यों आए। आतिथ्य सत्य बोलने की स्थिति बनाता है, और उनका प्रश्न स्पष्ट करता है कि बचाव आगंतुकों की जवाबदेही समाप्त नहीं करता।'),
  ('scene-hospitality-opens-the-impossible-exit', 'hanuman-tells-the-mission-without-inflation', 'en', 'Hanuman explains why they entered', 'Hanuman recounts Rama and Lakshmana''s exile, Ravana''s abduction of Sita, Sugriva''s promise and the southern assignment. He does not pretend they conquered the cave or arrived by wisdom alone. He admits that thirst drove them to follow birds, that they entered without permission, and that Svayamprabha''s food has saved people who still have not completed their task.'),
  ('scene-hospitality-opens-the-impossible-exit', 'hanuman-tells-the-mission-without-inflation', 'hi', 'हनुमान बताते हैं कि वे भीतर क्यों आए', 'हनुमान राम-लक्ष्मण के वनवास, रावण द्वारा सीता के अपहरण, सुग्रीव की प्रतिज्ञा और दक्षिणी खोज का क्रम बताते हैं। वे यह दावा नहीं करते कि उन्होंने गुफा जीत ली या केवल बुद्धि से यहाँ पहुँचे। वे स्वीकारते हैं कि प्यास ने पक्षियों का पीछा कराया, दल बिना अनुमति भीतर आया और स्वयंप्रभा के भोजन ने उन लोगों को बचाया है जिनका कार्य अभी अधूरा है।'),
  ('scene-hospitality-opens-the-impossible-exit', 'gratitude-is-offered-without-buying-the-host', 'en', 'The party asks how it may repay care', 'After eating, Hanuman thanks Svayamprabha and asks what service could repay the lives she has preserved. She refuses to turn compassion into a debt she can collect, saying her discipline leaves her in need of nothing. Her refusal matters: the rescue will be her decision, not a magical service purchased by warriors who happen to have a royal mission.'),
  ('scene-hospitality-opens-the-impossible-exit', 'gratitude-is-offered-without-buying-the-host', 'hi', 'दल पूछता है कि वह देखभाल का प्रतिदान कैसे दे', 'भोजन के बाद हनुमान स्वयंप्रभा को धन्यवाद देकर पूछते हैं कि बचाई गई जानों का प्रतिदान वे किस सेवा से दे सकते हैं। वे करुणा को वसूले जाने वाले ऋण में बदलने से मना करती हैं और कहती हैं कि उनके तप को किसी वस्तु की आवश्यकता नहीं। यह अस्वीकार महत्वपूर्ण है—बचाव उनका निर्णय होगा, राजकीय उद्देश्य वाले योद्धाओं द्वारा खरीदी गई जादुई सेवा नहीं।'),
  ('scene-hospitality-opens-the-impossible-exit', 'the-only-request-is-a-way-out', 'en', 'Hanuman asks for freedom, not treasure', 'Hanuman explains that the cave has consumed precious time and that no one can find a path back through its darkness. He asks only for a way out so the party can continue searching for Sita. Svayamprabha warns that those who enter this enchanted enclosure normally cannot leave alive, making clear that the danger remains real even after food and welcome.'),
  ('scene-hospitality-opens-the-impossible-exit', 'the-only-request-is-a-way-out', 'hi', 'हनुमान धन नहीं, बाहर जाने का मार्ग माँगते हैं', 'हनुमान बताते हैं कि गुफा बहुमूल्य समय निगल चुकी है और उसके अँधेरे में लौटने का मार्ग किसी को नहीं मिलता। वे केवल बाहर जाने का रास्ता माँगते हैं ताकि सीता की खोज जारी रह सके। स्वयंप्रभा चेताती हैं कि इस मायावी घेरे में आने वाले सामान्यतः जीवित बाहर नहीं निकलते; भोजन और स्वागत के बाद भी खतरा वास्तविक है।'),
  ('scene-hospitality-opens-the-impossible-exit', 'closed-eyes-cross-the-impossible-boundary', 'en', 'Svayamprabha spends her power to release them', 'Svayamprabha orders everyone to close and cover their eyes, then uses her ascetic power to move the entire party beyond the cave. They open their eyes beside the Vindhya, the Prasravana heights and the southern ocean while she returns to her guardianship. She does not join the mission or surrender her world; she restores their agency and resumes her own duty.'),
  ('scene-hospitality-opens-the-impossible-exit', 'closed-eyes-cross-the-impossible-boundary', 'hi', 'स्वयंप्रभा उन्हें मुक्त करने में अपनी शक्ति लगाती हैं', 'स्वयंप्रभा सबको आँखें बंद कर ढक लेने को कहती हैं और अपनी तपशक्ति से पूरे दल को गुफा के बाहर पहुँचा देती हैं। वे विंध्य, प्रस्रवण की ऊँचाइयों और दक्षिणी समुद्र के पास आँखें खोलते हैं, जबकि वे अपने संरक्षण-कार्य में लौट जाती हैं। वे अभियान में शामिल नहीं होतीं और अपना संसार नहीं छोड़तीं; वे दल की स्वतंत्रता लौटाकर अपना दायित्व फिर सँभालती हैं।'),
  ('scene-the-deadline-expires-at-the-sea', 'spring-proves-what-the-cave-concealed', 'en', 'The season announces the missed deadline', 'Outside the cave, flowering trees and the changed air reveal that spring has advanced. The month Sugriva allowed for the search expired while the party was trapped below ground. No one deliberately abandoned the mission, yet elapsed time does not disappear because the delay was innocent. Rescue has returned them to a world in which consequences have continued moving.'),
  ('scene-the-deadline-expires-at-the-sea', 'spring-proves-what-the-cave-concealed', 'hi', 'ऋतु बीती समय-सीमा की घोषणा करती है', 'गुफा के बाहर खिले वृक्ष और बदली हवा बताते हैं कि वसंत आगे बढ़ चुका है। सुग्रीव द्वारा खोज के लिए दिया महीना दल के भूमिगत फँसे रहने में समाप्त हो गया। किसी ने जानबूझकर अभियान नहीं छोड़ा, फिर भी निर्दोष देरी से बीता समय मिटता नहीं। बचाव उन्हें ऐसे संसार में लौटाता है जहाँ परिणाम लगातार आगे बढ़ते रहे हैं।'),
  ('scene-the-deadline-expires-at-the-sea', 'angada-fears-more-than-an-empty-report', 'en', 'Angada expects punishment and political danger', 'Angada says an empty return could mean death under Sugriva''s command. His fear is personal as well as official: Rama, not Sugriva, confirmed him as heir after Vali''s death, and he believes the king may still see the former rival''s son as a threat. These are Angada''s frightened conclusions, not knowledge the party can verify from this distant shore.'),
  ('scene-the-deadline-expires-at-the-sea', 'angada-fears-more-than-an-empty-report', 'hi', 'अंगद को दंड के साथ राजनीतिक खतरे का भय है', 'अंगद कहते हैं कि खाली लौटना सुग्रीव की आज्ञा में मृत्यु ला सकता है। उनका भय राजकीय होने के साथ निजी भी है—वाली की मृत्यु के बाद राम ने उन्हें युवराज माना था, सुग्रीव ने नहीं, इसलिए वे सोचते हैं कि राजा पुराने प्रतिद्वंद्वी के पुत्र को अब भी खतरा समझेंगे। यह दूर तट पर डरे अंगद का निष्कर्ष है, दल द्वारा सत्यापित तथ्य नहीं।'),
  ('scene-the-deadline-expires-at-the-sea', 'the-shore-offers-three-terrible-choices', 'en', 'Return, hide, or die where they stand', 'Angada proposes a fast to death rather than imprisonment or execution at home. Some companions argue that they should still find Sita or reliable news; others support returning to the enchanted cave, where food, water and walls might keep kings and weapons away. Exhaustion compresses the future into choices shaped more by fear than by fresh knowledge.'),
  ('scene-the-deadline-expires-at-the-sea', 'the-shore-offers-three-terrible-choices', 'hi', 'लौटना, छिपना या यहीं मरना', 'अंगद घर में कारावास या वध के बजाय आमरण उपवास प्रस्तावित करते हैं। कुछ साथी कहते हैं कि अभी भी सीता या भरोसेमंद समाचार ढूँढना चाहिए; दूसरे उस मायावी गुफा में लौटना चाहते हैं जहाँ भोजन, जल और दीवारें राजाओं तथा शस्त्रों से बचा सकती हैं। थकान भविष्य को ऐसे विकल्पों में समेट देती है जो नए ज्ञान से अधिक भय ने बनाए हैं।'),
  ('scene-the-deadline-expires-at-the-sea', 'a-leader-is-asked-to-choose-under-collapse', 'en', 'The frightened party gathers around Angada', 'The searchers ask Angada to choose what will save them from Sugriva''s anger. Their appeal gives a young leader enormous authority at the moment when he feels least safe and most suspicious. The sea blocks the horizon, the cave waits behind them and the lost mission remains between; this is not a council with good options, but a group nearing political and emotional rupture.'),
  ('scene-the-deadline-expires-at-the-sea', 'a-leader-is-asked-to-choose-under-collapse', 'hi', 'भयभीत दल अंगद के निर्णय के चारों ओर जुटता है', 'खोजी अंगद से ऐसा निर्णय माँगते हैं जो उन्हें सुग्रीव के क्रोध से बचा सके। उनकी पुकार एक युवा नेता को उसी क्षण विशाल अधिकार देती है जब वह स्वयं सबसे असुरक्षित और संदिग्ध महसूस कर रहा है। सामने समुद्र, पीछे गुफा और बीच में खोया अभियान है; यह अच्छे विकल्पों वाली सभा नहीं, बल्कि राजनीतिक और भावनात्मक टूटन के निकट पहुँचा दल है।'),
  ('scene-hanuman-confronts-a-possible-rupture', 'hanuman-recognises-a-rival-centre-forming', 'en', 'Fear can become a second court', 'Hanuman sees that Angada has courage, intelligence, lineage and the attention of the army. Under ordinary conditions those are strengths; under panic they could form a rival centre that separates frightened searchers from Kishkindha. He therefore treats the cave proposal as more than shelter and moves to stop a political break before it becomes an irreversible decision.'),
  ('scene-hanuman-confronts-a-possible-rupture', 'hanuman-recognises-a-rival-centre-forming', 'hi', 'भय एक दूसरा दरबार बना सकता है', 'हनुमान देखते हैं कि अंगद के पास साहस, बुद्धि, वंश और सेना का ध्यान है। सामान्य समय में ये शक्तियाँ हैं; आतंक में यही गुण भयभीत खोजियों को किष्किंधा से अलग करने वाला प्रतिद्वंद्वी केंद्र बना सकते हैं। इसलिए वे गुफा-प्रस्ताव को केवल आश्रय नहीं मानते और राजनीतिक विभाजन को अपरिवर्तनीय निर्णय बनने से पहले रोकने बढ़ते हैं।'),
  ('scene-hanuman-confronts-a-possible-rupture', 'family-ties-are-used-to-break-the-fantasy', 'en', 'Hanuman predicts that the refuge will empty', 'Hanuman tells Angada that companions now speaking bravely of exile will soon miss spouses, children and homes. He says Jambavan, Nila, Suhotra and Hanuman himself will not sustain a revolt, leaving its young leader isolated. The argument is strategic pressure: it uses likely attachments and named loyalties to puncture a collective fantasy before anyone can test it.'),
  ('scene-hanuman-confronts-a-possible-rupture', 'family-ties-are-used-to-break-the-fantasy', 'hi', 'हनुमान कहते हैं कि आश्रय अंततः खाली हो जाएगा', 'हनुमान अंगद से कहते हैं कि अभी निर्वासन की बात करने वाले साथी शीघ्र ही जीवनसाथी, बच्चों और घर को याद करेंगे। वे कहते हैं कि जाम्बवान, नील, सुहोत्र और स्वयं हनुमान विद्रोह नहीं निभाएँगे, जिससे युवा नेता अकेला रह जाएगा। यह रणनीतिक दबाव है—सामूहिक कल्पना को परखने से पहले तोड़ने के लिए संभावित लगाव और घोषित निष्ठाओं का उपयोग।'),
  ('scene-hanuman-confronts-a-possible-rupture', 'the-cave-is-not-beyond-reach', 'en', 'A hidden wall cannot guarantee safety', 'He attacks the refuge itself: a place that feels inaccessible to the exhausted party may not withstand Lakshmana''s weapons or determined pursuit. Food and water solve thirst, not political conflict, and a sealed cave can become a prison. Hanuman uses the image of its defences breaking to replace false invulnerability with the risks the frightened group has ignored.'),
  ('scene-hanuman-confronts-a-possible-rupture', 'the-cave-is-not-beyond-reach', 'hi', 'छिपी दीवार सुरक्षा की गारंटी नहीं', 'वे आश्रय पर भी प्रहार करते हैं—थके दल को अगम लगने वाला स्थान लक्ष्मण के शस्त्र या दृढ़ पीछा सह सके, यह निश्चित नहीं। भोजन और जल प्यास मिटाते हैं, राजनीतिक संघर्ष नहीं; बंद गुफा कारागार भी बन सकती है। हनुमान उसकी सुरक्षा टूटने की छवि से झूठी अभेद्यता की जगह वे जोखिम रखते हैं जिन्हें भयभीत दल ने अनदेखा किया।'),
  ('scene-hanuman-confronts-a-possible-rupture', 'reassurance-follows-the-threat', 'en', 'Hanuman also offers a path home', 'After division and warning, Hanuman says Sugriva is not seeking Angada''s death, loves Tara''s son and needs an heir because he has no son of his own. He urges Angada to return humbly instead of making fear final. The reassurance may be sincere, yet it comes inside coercive counsel; the party must weigh it rather than accept every claim as proven truth.'),
  ('scene-hanuman-confronts-a-possible-rupture', 'reassurance-follows-the-threat', 'hi', 'हनुमान घर लौटने का मार्ग भी देते हैं', 'विभाजन और चेतावनी के बाद हनुमान कहते हैं कि सुग्रीव अंगद की मृत्यु नहीं चाहते, तारा के पुत्र से प्रेम करते हैं और अपना पुत्र न होने से उत्तराधिकारी की आवश्यकता भी है। वे अंगद से भय को अंतिम बनाने के बजाय विनम्र होकर लौटने को कहते हैं। आश्वासन सच्चा हो सकता है, पर वह दबावपूर्ण परामर्श के भीतर आता है; दल को उसे परखना है, हर बात को सिद्ध सत्य नहीं मान लेना।'),
  ('scene-angada-chooses-the-fast', 'angada-answers-with-his-case-against-sugriva', 'en', 'Angada names why he does not trust the king', 'Angada answers that Sugriva has not shown the steadiness, mercy or candour Hanuman describes. He cites the taking of Vali''s queen, the old cave abandonment and the delay in helping Rama until Lakshmana arrived in anger. This is a son''s prosecution shaped by injury and fear; its force must be heard without converting every charge into an uncontested verdict.'),
  ('scene-angada-chooses-the-fast', 'angada-answers-with-his-case-against-sugriva', 'hi', 'अंगद बताते हैं कि वे राजा पर भरोसा क्यों नहीं करते', 'अंगद उत्तर देते हैं कि सुग्रीव ने वह स्थिरता, दया या साफगोई नहीं दिखाई जिसका हनुमान वर्णन करते हैं। वे वाली की रानी को अपनाने, पुरानी गुफा में छोड़ने और लक्ष्मण के क्रोध में आने तक राम की सहायता टालने का उदाहरण देते हैं। यह चोट और भय से बनी पुत्र की अभियोग-पत्रिका है; उसकी तीव्रता सुननी चाहिए, पर हर आरोप को निर्विवाद फैसला नहीं बनाना चाहिए।'),
  ('scene-angada-chooses-the-fast', 'the-heirs-fear-cannot-be-argued-away', 'en', 'Being the rival''s son feels fatal to Angada', 'He insists that a king will never rest while a strong rival''s son remains near the throne. Rama''s recognition of Angada as heir does not comfort him; it makes him fear Sugriva will see him as an imposed danger and imprison or kill him after an empty return. Hanuman''s assurances have not reached the wound beneath the argument: Angada does not believe home has a place for him.'),
  ('scene-angada-chooses-the-fast', 'the-heirs-fear-cannot-be-argued-away', 'hi', 'प्रतिद्वंद्वी का पुत्र होना अंगद को घातक लगता है', 'वे जोर देते हैं कि शक्तिशाली प्रतिद्वंद्वी का पुत्र सिंहासन के पास रहे तो राजा निश्चिंत नहीं होगा। राम द्वारा युवराज मानना उन्हें सांत्वना नहीं देता; उन्हें भय है कि सुग्रीव इसे थोपे गए खतरे की तरह देखेंगे और खाली लौटने पर कैद या वध करेंगे। हनुमान का आश्वासन तर्क के नीचे की चोट तक नहीं पहुँचा—अंगद मानते ही नहीं कि घर में उनके लिए स्थान बचा है।'),
  ('scene-angada-chooses-the-fast', 'angada-sends-his-farewell-home', 'en', 'The death vow carries messages to the living', 'Angada sits on sacred grass facing death and asks any survivor to salute Rama and Sugriva, then comfort his mother Tara. The farewell reveals that the home he rejects still holds people he loves and obligations he cannot stop feeling. His fast is not calm spiritual completion; it is a young leader''s attempt to control an ending he believes others will control cruelly.'),
  ('scene-angada-chooses-the-fast', 'angada-sends-his-farewell-home', 'hi', 'मृत्यु-व्रत जीवित लोगों के लिए संदेश भेजता है', 'अंगद पवित्र घास पर मृत्यु के लिए बैठते हैं और किसी जीवित लौटने वाले से राम तथा सुग्रीव को प्रणाम कहने, फिर माता तारा को सांत्वना देने को कहते हैं। विदाई बताती है कि जिस घर को वे ठुकरा रहे हैं, वहीं उनके प्रिय और दायित्व अब भी हैं। उनका उपवास शांत आध्यात्मिक पूर्णता नहीं, बल्कि ऐसे अंत पर नियंत्रण पाने का प्रयास है जिसे वे दूसरों के हाथों क्रूर मानते हैं।'),
  ('scene-angada-chooses-the-fast', 'the-party-recites-the-chain-of-loss', 'en', 'One grief summons every earlier grief', 'The others join the fast, praising Vali, blaming Sugriva and reciting the chain that brought them here: Rama''s exile, Dasharatha''s death, the violence at Janasthana, Sita''s abduction, Jatayu''s sacrifice and Vali''s fall. Their account mixes memory, allegiance and despair. Speaking Jatayu''s name carries farther than they know and reaches a listener above the shore.'),
  ('scene-angada-chooses-the-fast', 'the-party-recites-the-chain-of-loss', 'hi', 'एक शोक पहले के हर शोक को बुलाता है', 'अन्य खोजी उपवास में बैठते हैं, वाली की प्रशंसा, सुग्रीव की निंदा और यहाँ तक लाने वाली श्रृंखला दोहराते हैं—राम का वनवास, दशरथ की मृत्यु, जनस्थान की हिंसा, सीता का अपहरण, जटायु का बलिदान और वाली का पतन। उनके शब्दों में स्मृति, निष्ठा और निराशा मिलती है। जटायु का नाम उनकी जानकारी से कहीं दूर, तट के ऊपर बैठे एक श्रोता तक पहुँचता है।'),
  ('scene-jatayus-name-stops-a-predator', 'sampati-first-sees-a-slow-feast', 'en', 'The watcher above sees prey, not allies', 'Old, wingless Sampati watches the monkeys settle to die and calculates that he can feed on them one after another. He is not introduced as a ready-made helper waiting nobly for heroes. Hunger, age and immobility have narrowed his first response to survival at their expense, making the encounter dangerous before it becomes useful.'),
  ('scene-jatayus-name-stops-a-predator', 'sampati-first-sees-a-slow-feast', 'hi', 'ऊपर बैठा दर्शक सहयोगी नहीं, शिकार देखता है', 'वृद्ध, पंखहीन संपाति खोजियों को मरने बैठते देखते हैं और सोचते हैं कि वे एक-एक करके उनका भोजन बनेंगे। वे नायकों की प्रतीक्षा करता हुआ तैयार सहायक बनकर नहीं आते। भूख, आयु और गतिहीनता ने उनकी पहली प्रतिक्रिया को दूसरों की कीमत पर अपने जीवन तक सीमित कर दिया है, इसलिए उपयोगी बनने से पहले यह भेंट खतरनाक है।'),
  ('scene-jatayus-name-stops-a-predator', 'angada-measures-their-end-against-jatayu', 'en', 'Angada compares surrender with Jatayu''s resistance', 'Angada laments that Jatayu gave his life fighting for Sita while the search party will die without helping her. He links their fast to the wider sequence of exile, abduction and failed rescue. The comparison deepens shame, but it also speaks the one name capable of breaking through the predator''s appetite: Jatayu, Sampati''s long-lost brother.'),
  ('scene-jatayus-name-stops-a-predator', 'angada-measures-their-end-against-jatayu', 'hi', 'अंगद समर्पण की तुलना जटायु के प्रतिरोध से करते हैं', 'अंगद विलाप करते हैं कि जटायु ने सीता के लिए लड़ते हुए प्राण दिए, जबकि खोज-दल बिना सहायता किए मर जाएगा। वे अपने उपवास को वनवास, अपहरण और विफल बचाव की बड़ी श्रृंखला से जोड़ते हैं। तुलना लज्जा बढ़ाती है, पर वही एक नाम बोलती है जो शिकारी की भूख तोड़ सकता है—संपाति का वर्षों से खोया भाई जटायु।'),
  ('scene-jatayus-name-stops-a-predator', 'a-brothers-death-changes-the-question', 'en', 'Hunger gives way to grief', 'Sampati abandons the plan to wait for their deaths and demands to know who has said Jatayu was killed. He asks how his younger brother died, why Dasharatha''s name is bound to the event and what these strangers witnessed. The searchers have not defeated or persuaded him; an old relationship has changed what he is able to care about.'),
  ('scene-jatayus-name-stops-a-predator', 'a-brothers-death-changes-the-question', 'hi', 'भूख शोक को जगह देती है', 'संपाति उनकी मृत्यु की प्रतीक्षा का विचार छोड़कर पूछते हैं कि जटायु के मारे जाने की बात किसने कही। वे जानना चाहते हैं कि छोटा भाई कैसे मरा, दशरथ का नाम उससे क्यों जुड़ा है और इन अजनबियों ने क्या देखा। खोजियों ने उन्हें हराया या समझाया नहीं; पुराने संबंध ने उनके लिए महत्व रखने वाली बात बदल दी है।'),
  ('scene-jatayus-name-stops-a-predator', 'the-wingless-elder-asks-to-be-lowered', 'en', 'Sampati cannot reach the listeners alone', 'Sampati says his wings were burned and age has left him unable to descend safely. If the party wants answers, it must first help the threatening stranger down from his ledge. The request reverses the physical balance without removing danger: those he intended to eat now control whether he can reach the ground, and both sides must risk proximity to learn more.'),
  ('scene-jatayus-name-stops-a-predator', 'the-wingless-elder-asks-to-be-lowered', 'hi', 'संपाति अकेले श्रोताओं तक नहीं पहुँच सकते', 'संपाति कहते हैं कि उनके पंख जल चुके हैं और आयु ने सुरक्षित नीचे उतरने की क्षमता छीन ली है। यदि दल उत्तर चाहता है तो पहले उस खतरनाक अजनबी को चट्टान से उतारना होगा। यह अनुरोध खतरा मिटाए बिना शारीरिक संतुलन उलट देता है—जिन्हें वे खाना चाहते थे, वही तय करेंगे कि वे भूमि तक पहुँचें, और अधिक जानने के लिए दोनों पक्षों को निकटता का जोखिम लेना होगा।'),
  ('scene-angada-tells-sampati-the-whole-loss', 'the-party-accepts-danger-because-it-has-chosen-death', 'en', 'Despair makes the risk seem affordable', 'The searchers suspect Sampati may still eat them, yet their death vow makes that threat feel no worse than starvation. They lower him and agree to speak, not because trust is complete but because both sides possess something the other needs. Their damaged judgment matters: desperation opens information exchange, but it could just as easily have delivered them to a predator.'),
  ('scene-angada-tells-sampati-the-whole-loss', 'the-party-accepts-danger-because-it-has-chosen-death', 'hi', 'निराशा खतरे को स्वीकार्य बना देती है', 'खोजियों को संदेह है कि संपाति अब भी उन्हें खा सकते हैं, फिर भी मृत्यु-व्रत के कारण यह खतरा भूख से मरने से बुरा नहीं लगता। वे उन्हें नीचे उतारकर बोलने को तैयार होते हैं—पूर्ण भरोसे से नहीं, बल्कि इसलिए कि दोनों के पास दूसरे के लिए आवश्यक बात है। उनका निर्णय क्षतिग्रस्त है; निराशा संवाद खोलती है, पर उतनी ही आसानी से उन्हें शिकारी के सामने भी रख सकती थी।'),
  ('scene-angada-tells-sampati-the-whole-loss', 'angada-builds-the-road-to-jatayus-last-fight', 'en', 'The account begins before the abduction', 'Angada identifies his lineage, Vali and Sugriva''s conflict, Rama''s exile and the alliance that followed Sita''s abduction. He gives Sampati enough context to understand why forest princes, a vulture and a monkey army entered the same chain of events. The careful sequence replaces the fragments Sampati overheard with people, promises and consequences.'),
  ('scene-angada-tells-sampati-the-whole-loss', 'angada-builds-the-road-to-jatayus-last-fight', 'hi', 'वृत्तांत अपहरण से पहले शुरू होता है', 'अंगद अपना वंश, वाली-सुग्रीव संघर्ष, राम का वनवास और सीता के अपहरण के बाद बनी मैत्री बताते हैं। वे संपाति को इतना संदर्भ देते हैं कि समझ सकें—वनवासी राजकुमार, एक गिद्ध और वानर-सेना एक ही घटनाक्रम में कैसे जुड़े। क्रमबद्ध कथा सुनी हुई टूटी बातों की जगह व्यक्तियों, प्रतिज्ञाओं और परिणामों को रखती है।'),
  ('scene-angada-tells-sampati-the-whole-loss', 'jatayu-forced-ravana-to-set-sita-down', 'en', 'Jatayu did more than merely die', 'Angada says Jatayu attacked Ravana''s chariot, forced the abductor down and made him place Sita on the earth while they fought. Only after the old bird was exhausted did Ravana cut him down and carry her away again. Rama later found Jatayu, heard what had happened and performed the funeral rites owed to a protector who had acted when no army was present.'),
  ('scene-angada-tells-sampati-the-whole-loss', 'jatayu-forced-ravana-to-set-sita-down', 'hi', 'जटायु ने केवल प्राण नहीं दिए', 'अंगद बताते हैं कि जटायु ने रावण के रथ पर आक्रमण किया, अपहरणकर्ता को नीचे उतारा और युद्ध के समय सीता को भूमि पर रखने को मजबूर किया। वृद्ध पक्षी के थक जाने के बाद ही रावण ने उन्हें काट गिराया और सीता को फिर ले गया। राम ने बाद में जटायु को पाया, घटना सुनी और उस रक्षक के अंतिम संस्कार किए जिसने सेना न होने पर भी प्रतिरोध किया था।'),
  ('scene-angada-tells-sampati-the-whole-loss', 'the-searchers-admit-how-they-came-to-die', 'en', 'Angada includes the party''s own failure', 'He continues through Vali''s death, Sugriva''s commission, the fruitless southern sweep, the enchanted cave and the expired month. The party now expects punishment and has chosen to fast on the shore. By telling Sampati both Jatayu''s courage and their own collapse, Angada offers an account honest enough for the old brother to answer rather than a speech designed only to earn sympathy.'),
  ('scene-angada-tells-sampati-the-whole-loss', 'the-searchers-admit-how-they-came-to-die', 'hi', 'अंगद दल की अपनी विफलता भी छिपाते नहीं', 'वे वाली की मृत्यु, सुग्रीव की आज्ञा, निष्फल दक्षिणी खोज, मायावी गुफा और बीते महीने तक कथा जारी रखते हैं। दल अब दंड की आशंका में तट पर उपवास चुन चुका है। जटायु के साहस के साथ अपनी टूटन बताकर अंगद ऐसा ईमानदार वृत्तांत देते हैं जिसका संपाति उत्तर दे सकते हैं, केवल सहानुभूति पाने वाला भाषण नहीं।'),
  ('scene-sampati-sees-lanka-across-the-sea', 'grief-cannot-fly-but-it-can-answer', 'en', 'Sampati chooses the service still possible', 'Sampati grieves that age and burned wings prevent him from avenging Jatayu by force. Then he recognises another form of action: words, memory and the long sight of his kind can serve Rama''s rescue. He does not need to become young or invulnerable before helping; he must tell the searchers exactly what he witnessed and what he can still see.'),
  ('scene-sampati-sees-lanka-across-the-sea', 'grief-cannot-fly-but-it-can-answer', 'hi', 'संपाति वह सेवा चुनते हैं जो अब भी संभव है', 'संपाति शोक करते हैं कि आयु और जले पंख उन्हें बल से जटायु का बदला लेने नहीं देते। फिर वे दूसरी क्रिया पहचानते हैं—शब्द, स्मृति और अपनी जाति की दूर-दृष्टि राम के बचाव में काम आ सकती है। सहायता से पहले युवा या अजेय होना आवश्यक नहीं; उन्हें खोजियों को ठीक-ठीक बताना है कि उन्होंने क्या देखा और अब भी क्या देख सकते हैं।'),
  ('scene-sampati-sees-lanka-across-the-sea', 'the-crying-woman-dropped-her-ornaments', 'en', 'A remembered abduction matches Sita', 'Sampati recalls seeing Ravana carry a beautiful, distressed woman through the sky. She cried the names Rama and Lakshmana and dropped ornaments below, leaving signs for anyone following. Those details match the disappearance the searchers described. Sampati therefore identifies the captive as Sita, joining their account to an independent sighting rather than guessing from desire alone.'),
  ('scene-sampati-sees-lanka-across-the-sea', 'the-crying-woman-dropped-her-ornaments', 'hi', 'आभूषण गिराती रोती स्त्री सीता से मेल खाती है', 'संपाति याद करते हैं कि उन्होंने रावण को आकाश में एक सुंदर, व्याकुल स्त्री ले जाते देखा था। वह राम और लक्ष्मण के नाम पुकार रही थी और पीछे आने वालों के लिए आभूषण नीचे गिरा रही थी। ये बातें खोजियों द्वारा बताए अपहरण से मेल खाती हैं। इसलिए संपाति केवल इच्छा से अनुमान नहीं लगाते, बल्कि स्वतंत्र दृश्य को उनके वृत्तांत से जोड़कर बंदिनी को सीता पहचानते हैं।'),
  ('scene-sampati-sees-lanka-across-the-sea', 'lanka-rises-one-hundred-yojanas-away', 'en', 'The unknown horizon becomes a destination', 'Sampati names Ravana as Vishrava''s son and Vaishravana''s brother, then points beyond the salt water. Lanka stands one hundred yojanas away with golden gates, walls and palaces. The immense distance gives the mission a concrete destination and a crossing challenge: the searchers finally know where Sita is, but ordinary travel cannot carry them there.'),
  ('scene-sampati-sees-lanka-across-the-sea', 'lanka-rises-one-hundred-yojanas-away', 'hi', 'अनजान क्षितिज एक गंतव्य बन जाता है', 'संपाति रावण को विश्रवा का पुत्र और वैश्रवण का भाई बताते हैं, फिर खारे समुद्र के पार संकेत करते हैं। सौ योजन दूर स्वर्णिम द्वारों, दीवारों और महलों वाली लंका खड़ी है। विशाल दूरी अभियान को निश्चित गंतव्य और पार करने की चुनौती देती है—खोजी अंततः जानते हैं कि सीता कहाँ हैं, पर सामान्य यात्रा उन्हें वहाँ नहीं पहुँचा सकती।'),
  ('scene-sampati-sees-lanka-across-the-sea', 'sita-is-alive-inside-ravanas-guarded-compound', 'en', 'The search gains location and urgency', 'With his far sight, Sampati says Sita is confined inside Ravana''s inner compound and watched by rakshasi guards. She is not merely somewhere on an island; she is alive within a controlled hostile space. He urges the party to cross the ocean, see her and return with news, converting despair into a mission that now has a target but still lacks a way to reach it.'),
  ('scene-sampati-sees-lanka-across-the-sea', 'sita-is-alive-inside-ravanas-guarded-compound', 'hi', 'खोज को स्थान और तात्कालिकता दोनों मिलते हैं', 'अपनी दूर-दृष्टि से संपाति कहते हैं कि सीता रावण के भीतरी परिसर में बंद हैं और राक्षसी पहरेदार उन्हें घेरे हैं। वे केवल किसी द्वीप पर नहीं, बल्कि नियंत्रित शत्रु-क्षेत्र में जीवित हैं। वे दल से समुद्र पार कर उन्हें देखने और समाचार लाने को कहते हैं; निराशा अब लक्ष्य वाला अभियान बनती है, पर उस तक पहुँचने का उपाय अभी नहीं मिला।'),
  ('scene-suparsvas-witness-corroborates-the-road', 'jambavan-asks-for-the-knowledge-chain', 'en', 'Relief does not end verification', 'Jambavan does not let the party run toward the sea on excitement alone. He asks where Sita is, who saw her, how the witness identified Ravana and whether the direction is exact. The questions respect Sampati while separating conclusion from support. A desperate group needs good news, but that need makes disciplined checking more important, not less.'),
  ('scene-suparsvas-witness-corroborates-the-road', 'jambavan-asks-for-the-knowledge-chain', 'hi', 'राहत जाँच को समाप्त नहीं करती', 'जाम्बवान दल को केवल उत्साह में समुद्र की ओर दौड़ने नहीं देते। वे पूछते हैं—सीता कहाँ हैं, उन्हें किसने देखा, साक्षी ने रावण को कैसे पहचाना और दिशा कितनी निश्चित है। प्रश्न संपाति का सम्मान रखते हुए निष्कर्ष को आधार से अलग करते हैं। हताश दल को शुभ समाचार चाहिए, पर यही आवश्यकता अनुशासित जाँच को कम नहीं, अधिक महत्वपूर्ण बनाती है।'),
  ('scene-suparsvas-witness-corroborates-the-road', 'suparsva-blocked-the-mahendra-pass', 'en', 'Sampati''s son met the abductors', 'Sampati explains that his son Suparsva once hunted near the Mahendra passage to feed his wingless father. A powerful dark figure approached carrying a radiant woman, and Suparsva blocked their way intending to take them as prey. This encounter occurred close enough for speech and choice, not only as a remote shape seen across the sky.'),
  ('scene-suparsvas-witness-corroborates-the-road', 'suparsva-blocked-the-mahendra-pass', 'hi', 'संपाति के पुत्र ने अपहरणकर्ताओं को रोका था', 'संपाति बताते हैं कि उनका पुत्र सुपार्श्व पंखहीन पिता के लिए भोजन खोजते हुए महेंद्र मार्ग के पास शिकार करता था। एक शक्तिशाली काला पुरुष तेजस्वी स्त्री को लेकर आया और सुपार्श्व ने उन्हें शिकार बनाने की नीयत से रास्ता रोका। यह भेंट केवल दूर आकाश में दिखी आकृति नहीं थी; वह बोलने और निर्णय लेने जितनी निकट हुई थी।'),
  ('scene-suparsvas-witness-corroborates-the-road', 'a-humble-request-was-mistaken-for-mercy-earned', 'en', 'Suparsva let Ravana pass', 'Ravana spoke humbly and asked for passage, so Suparsva released him and Sita rather than attack. Airborne beings later identified them, and Suparsva saw the woman drop ornaments and call Rama and Lakshmana. The added witness strengthens identity and route, but it also preserves an uncomfortable fact: a chance to interfere appeared, and the witness let it go.'),
  ('scene-suparsvas-witness-corroborates-the-road', 'a-humble-request-was-mistaken-for-mercy-earned', 'hi', 'सुपार्श्व ने रावण को जाने दिया', 'रावण ने विनम्रता से मार्ग माँगा, इसलिए सुपार्श्व ने आक्रमण करने के बजाय उसे और सीता को जाने दिया। बाद में आकाशचारी प्राणियों ने उनकी पहचान बताई, और सुपार्श्व ने स्त्री को आभूषण गिराते तथा राम-लक्ष्मण पुकारते देखा। यह गवाही पहचान और मार्ग मजबूत करती है, पर असुविधाजनक तथ्य भी बचाती है—हस्तक्षेप का अवसर आया और साक्षी ने उसे जाने दिया।'),
  ('scene-suparsvas-witness-corroborates-the-road', 'sampati-offers-intelligence-not-excuses', 'en', 'The father cannot undo the missed moment', 'Sampati regrets that neither he nor his son rescued Sita and refuses to disguise his lack of wings as completed service. What he can offer now is a converging account: his own sight, Suparsva''s close encounter and the identifications heard in the sky all point toward Lanka. He urges the searchers not to waste the direction simply because its witnesses were imperfect.'),
  ('scene-suparsvas-witness-corroborates-the-road', 'sampati-offers-intelligence-not-excuses', 'hi', 'पिता छूटा हुआ क्षण वापस नहीं ला सकते', 'संपाति दुख जताते हैं कि न वे, न उनका पुत्र सीता को बचा सके, और पंखहीनता को पूरी हुई सेवा का रूप नहीं देते। अब वे मिलती हुई गवाहियाँ दे सकते हैं—उनकी अपनी दृष्टि, सुपार्श्व की निकट भेंट और आकाश में सुनी पहचान, सभी लंका की ओर संकेत करती हैं। वे कहते हैं कि साक्षियों की अपूर्णता के कारण मिली दिशा व्यर्थ न की जाए।'),
  ('scene-sampati-returns-to-nisakaras-hermitage', 'the-brother-receives-water-at-last', 'en', 'Sampati honours Jatayu before continuing', 'Sampati asks the searchers to carry him to the water so he can make the offering owed to his dead brother. The party pauses its newly discovered route and helps him complete the act. Information has not erased grief or turned Jatayu into a clue; the protector is mourned as a person before his brother returns to the work his sacrifice has reopened.'),
  ('scene-sampati-returns-to-nisakaras-hermitage', 'the-brother-receives-water-at-last', 'hi', 'संपाति आगे बढ़ने से पहले जटायु का तर्पण करते हैं', 'संपाति खोजियों से उन्हें जल तक ले जाने को कहते हैं ताकि वे मृत भाई का तर्पण कर सकें। दल नई मिली दिशा पर तुरंत दौड़ने के बजाय रुककर यह कर्म पूरा कराता है। सूचना शोक को मिटाकर जटायु को केवल संकेत नहीं बनाती; उनके बलिदान से खुला कार्य आगे बढ़ने से पहले रक्षक को एक व्यक्ति और भाई की तरह स्मरण किया जाता है।'),
  ('scene-sampati-returns-to-nisakaras-hermitage', 'six-nights-disappear-after-the-fall', 'en', 'The burned survivor wakes without bearings', 'Sampati recounts falling onto Vindhya after the sun burned his wings. He lay unconscious for six nights and woke unable to recognise the mountain, the direction or the fate of Jatayu. Physical survival arrived without explanation, kingdom, flight or brother. His later certainty about Lanka grew from a life that first had to rebuild basic orientation.'),
  ('scene-sampati-returns-to-nisakaras-hermitage', 'six-nights-disappear-after-the-fall', 'hi', 'जला हुआ जीवित बचा व्यक्ति दिशा खोकर जागता है', 'संपाति बताते हैं कि सूर्य से पंख जलने के बाद वे विंध्य पर गिरे। छह रात अचेत रहने के बाद जागे तो न पर्वत पहचाना, न दिशा, न जटायु का भाग्य। शरीर बच गया, पर न व्याख्या थी, न राज्य, न उड़ान, न भाई। लंका के बारे में उनकी बाद की निश्चितता ऐसे जीवन से निकली जिसे पहले अपनी मूल दिशा फिर बनानी पड़ी।'),
  ('scene-sampati-returns-to-nisakaras-hermitage', 'memory-finds-nisakaras-sacred-grove', 'en', 'An old path survives the loss', 'Slowly Sampati recognises the region and remembers the hermitage of the sage Nisakara, whom the brothers once visited. Unable to fly, he struggles down the mountain toward that familiar place. The route is small compared with his former sky journeys, yet it is the first purposeful movement available after catastrophe: reach someone who knew who he had been.'),
  ('scene-sampati-returns-to-nisakaras-hermitage', 'memory-finds-nisakaras-sacred-grove', 'hi', 'हानि के बीच पुराना मार्ग बचा रहता है', 'धीरे-धीरे संपाति क्षेत्र पहचानते हैं और ऋषि निशाकर का आश्रम याद करते हैं, जहाँ दोनों भाई पहले जाते थे। उड़ने में असमर्थ होकर वे कठिनाई से पर्वत उतरकर उस परिचित स्थान की ओर बढ़ते हैं। उनकी पुरानी आकाश-यात्राओं के सामने यह मार्ग छोटा है, फिर भी विपत्ति के बाद उपलब्ध पहली उद्देश्यपूर्ण गति है—ऐसे व्यक्ति तक पहुँचना जो उन्हें पहले से जानता था।'),
  ('scene-sampati-returns-to-nisakaras-hermitage', 'the-sage-recognises-the-changed-bird', 'en', 'Nisakara sees the person beneath the injury', 'Animals gather peacefully around Nisakara as he returns, and the sage recognises Sampati despite the burned body and missing wings. He asks what happened rather than defining the visitor by damage. That recognition gives Sampati a place from which to tell the shameful story of pride, loss and protection he had been unable to speak.'),
  ('scene-sampati-returns-to-nisakaras-hermitage', 'the-sage-recognises-the-changed-bird', 'hi', 'निशाकर घावों के भीतर व्यक्ति को पहचानते हैं', 'निशाकर लौटते हैं तो पशु शांत होकर उनके चारों ओर जुटते हैं, और ऋषि जले शरीर तथा गायब पंखों के बावजूद संपाति को पहचान लेते हैं। वे घाव से पहचान तय करने के बजाय पूछते हैं कि क्या हुआ। यह पहचान संपाति को अभिमान, हानि और रक्षा की उस लज्जापूर्ण कथा को कहने का आधार देती है जिसे वे बोल नहीं पा रहे थे।'),
  ('scene-one-brother-burns-to-save-the-other', 'the-brothers-turn-flight-into-a-vow', 'en', 'Pride makes the sky a contest', 'Sampati tells Nisakara that he and Jatayu, intoxicated by their power, vowed to follow the sun until it reached the western mountain. They wanted distant witnesses to see whose flight was greater. The journey begins not as duty or rescue but as a public test of superiority, and that motive prevents them from respecting the limits their bodies soon reveal.'),
  ('scene-one-brother-burns-to-save-the-other', 'the-brothers-turn-flight-into-a-vow', 'hi', 'अभिमान आकाश को प्रतियोगिता बना देता है', 'संपाति निशाकर से कहते हैं कि वे और जटायु अपनी शक्ति के मद में सूर्य का पश्चिमी पर्वत तक पीछा करने की प्रतिज्ञा कर बैठे। वे चाहते थे कि दूर बैठे लोग देखें कि किसकी उड़ान श्रेष्ठ है। यात्रा दायित्व या बचाव से नहीं, श्रेष्ठता के सार्वजनिक परीक्षण से शुरू होती है, और यही उद्देश्य उन्हें शरीर की जल्दी खुलती सीमा मानने से रोकता है।'),
  ('scene-one-brother-burns-to-save-the-other', 'the-world-shrinks-beneath-the-sun', 'en', 'Height erases ordinary scale', 'As they climb, cities resemble wheels, rivers become threads and mountains look like animals in a pond. Wonder becomes disorientation: heat, sweat and regret arrive, the quarters disappear and the burning world seems already destroyed. Their extraordinary sight no longer guarantees judgment. Greater reach has carried them into a space where familiar signs cannot keep them safe.'),
  ('scene-one-brother-burns-to-save-the-other', 'the-world-shrinks-beneath-the-sun', 'hi', 'ऊँचाई सामान्य माप मिटा देती है', 'ऊपर चढ़ते हुए नगर पहिए, नदियाँ धागे और पर्वत सरोवर के पशु जैसे दिखते हैं। विस्मय दिशाभ्रम बनता है—गर्मी, पसीना और पछतावा आते हैं, दिशाएँ मिटती हैं और जलता संसार पहले ही नष्ट-सा लगता है। उनकी असाधारण दृष्टि अब सही निर्णय की गारंटी नहीं। अधिक पहुँच उन्हें ऐसे क्षेत्र में लाई है जहाँ परिचित संकेत सुरक्षा नहीं दे सकते।'),
  ('scene-one-brother-burns-to-save-the-other', 'jatayu-falls-before-he-can-ask', 'en', 'The younger brother loses consciousness', 'Jatayu faints and begins dropping toward the earth without time to ask for help. Sampati sees him fall and abandons the contest instantly. The choice does not undo the pride that caused the danger, but it changes the meaning of what follows: flight is no longer about being seen as greater; every remaining movement is directed toward keeping his brother alive.'),
  ('scene-one-brother-burns-to-save-the-other', 'jatayu-falls-before-he-can-ask', 'hi', 'छोटा भाई कुछ कहने से पहले अचेत होकर गिरता है', 'जटायु अचेत होकर पृथ्वी की ओर गिरने लगते हैं और सहायता माँगने का समय भी नहीं मिलता। संपाति उन्हें देखकर उसी क्षण प्रतियोगिता छोड़ देते हैं। यह चुनाव खतरा पैदा करने वाला अभिमान मिटाता नहीं, पर आगे की घटना का अर्थ बदल देता है—अब उड़ान श्रेष्ठ दिखने के लिए नहीं, भाई को जीवित रखने के लिए है।'),
  ('scene-one-brother-burns-to-save-the-other', 'sampati-spreads-his-wings-into-the-fire', 'en', 'Protection costs Sampati his sky', 'Sampati dives over Jatayu and spreads his own wings between his brother and the sun. Jatayu survives the burning descent and falls toward Janasthana; Sampati''s wings are scorched away and he crashes on Vindhya, losing flight, kingdom and contact with his brother. The sacrifice saves a life without granting Sampati knowledge of what that life will later become.'),
  ('scene-one-brother-burns-to-save-the-other', 'sampati-spreads-his-wings-into-the-fire', 'hi', 'रक्षा की कीमत संपाति का आकाश बनता है', 'संपाति जटायु के ऊपर उतरकर अपने पंख भाई और सूर्य के बीच फैला देते हैं। जटायु जलती गिरावट से बचकर जनस्थान की ओर गिरते हैं; संपाति के पंख भस्म हो जाते हैं और वे विंध्य पर गिरकर उड़ान, राज्य तथा भाई से संपर्क खो देते हैं। बलिदान जीवन बचाता है, पर संपाति नहीं जानते कि वह जीवन आगे क्या बनेगा।'),
  ('scene-nisakara-gives-survival-a-future-purpose', 'the-sage-promises-more-than-wings', 'en', 'Nisakara says capacity will return', 'After listening, Nisakara says Sampati''s large wings and smaller pinions will grow again, along with sight, strength and energy. The promise addresses the whole injured life rather than one missing body part. Yet the sage does not restore him that day, because recovered power is tied to a future moment when Sampati''s testimony can help others.'),
  ('scene-nisakara-gives-survival-a-future-purpose', 'the-sage-promises-more-than-wings', 'hi', 'निशाकर कहते हैं कि क्षमता लौटेगी', 'सब सुनकर निशाकर कहते हैं कि संपाति के बड़े पंख और छोटे पर फिर उगेंगे, साथ में दृष्टि, शक्ति और ऊर्जा भी लौटेगी। यह वचन केवल एक खोए अंग नहीं, पूरे घायल जीवन को संबोधित करता है। फिर भी ऋषि उसी दिन उन्हें ठीक नहीं करते, क्योंकि लौटती शक्ति उस भविष्य से जुड़ी है जब संपाति की गवाही दूसरों की सहायता करेगी।'),
  ('scene-nisakara-gives-survival-a-future-purpose', 'nisakara-foresees-sitas-refusal', 'en', 'The captive keeps faith under pressure', 'Nisakara describes a future in which Ravana abducts Rama''s wife and tries to bend her with food, comfort and desire. Sita refuses what captivity offers. Even when divine food reaches her during prolonged distress, she first sets aside a share in thought for Rama and Lakshmana. The vision centres her agency and endurance, not only the men searching for her.'),
  ('scene-nisakara-gives-survival-a-future-purpose', 'nisakara-foresees-sitas-refusal', 'hi', 'बंदिनी दबाव में भी अपना संकल्प रखती हैं', 'निशाकर भविष्य बताते हैं जिसमें रावण राम की पत्नी का अपहरण करके भोजन, सुख और इच्छा से उनका संकल्प मोड़ना चाहता है। सीता कैद द्वारा दी वस्तुएँ अस्वीकार करती हैं। लंबे कष्ट में दिव्य आहार मिलने पर भी वे पहले मन से राम और लक्ष्मण के लिए अंश रखती हैं। यह दृष्टि केवल खोजते पुरुषों को नहीं, सीता की निर्णय-शक्ति और धैर्य को केंद्र में रखती है।'),
  ('scene-nisakara-gives-survival-a-future-purpose', 'the-searchers-will-need-a-witness', 'en', 'Sampati''s future task is to speak', 'The sage says Rama''s envoys will one day reach this mountain while searching for Sita. Sampati must tell them everything he knows about the captive queen and the road toward her. Remaining in place is therefore not meaningless delay. His long survival becomes a watch whose completion depends on recognising the right listeners and giving them usable truth.'),
  ('scene-nisakara-gives-survival-a-future-purpose', 'the-searchers-will-need-a-witness', 'hi', 'संपाति का भविष्य-कार्य सत्य कहना है', 'ऋषि कहते हैं कि राम के दूत एक दिन सीता की खोज करते इस पर्वत तक आएँगे। संपाति को बंदिनी रानी और उनकी दिशा के बारे में अपनी पूरी जानकारी उन्हें देनी होगी। इसलिए वहीं रहना अर्थहीन देरी नहीं। उनका लंबा जीवन ऐसी पहरेदारी बनता है जो सही श्रोताओं को पहचानकर उपयोगी सत्य देने पर पूरी होगी।'),
  ('scene-nisakara-gives-survival-a-future-purpose', 'waiting-serves-more-than-private-healing', 'en', 'Recovery is joined to the welfare of others', 'Nisakara says the delayed act will aid Rama and Lakshmana, teachers, ascetics and the wider world. He could restore Sampati immediately but chooses a future in which the bird''s knowledge has consequence before his body is renewed. The choice is demanding and cannot erase Sampati''s loneliness; it gives that survival a purpose without pretending the suffering was required or deserved.'),
  ('scene-nisakara-gives-survival-a-future-purpose', 'waiting-serves-more-than-private-healing', 'hi', 'स्वस्थ होना दूसरों के हित से जुड़ता है', 'निशाकर कहते हैं कि यह भविष्य का कार्य राम-लक्ष्मण, आचार्यों, तपस्वियों और व्यापक लोक का हित करेगा। वे संपाति को तुरंत पंख दे सकते थे, पर ऐसा समय चुनते हैं जिसमें शरीर लौटने से पहले पक्षी का ज्ञान परिणाम पैदा करे। यह कठिन चुनाव संपाति का अकेलापन मिटाता नहीं; वह पीड़ा को आवश्यक या योग्य बताए बिना जीवन को उद्देश्य देता है।'),
  ('scene-sampatis-wings-return-with-the-mission', 'sampati-waited-through-a-century', 'en', 'The promised listeners took generations to arrive', 'Sampati says he remained on Vindhya for more than a hundred years after Nisakara departed this life. Grief repeatedly pulled him toward suicide, but the remembered instruction made him wait for the right time and people. The long interval is not skipped as effortless faith; it is a repeated choice to preserve a damaged life whose usefulness could not yet be seen.'),
  ('scene-sampatis-wings-return-with-the-mission', 'sampati-waited-through-a-century', 'hi', 'प्रतिज्ञात श्रोता पीढ़ियों बाद पहुँचे', 'संपाति कहते हैं कि निशाकर के देह छोड़ने के बाद वे सौ वर्षों से अधिक विंध्य पर रहे। शोक बार-बार उन्हें आत्महत्या की ओर खींचता था, पर स्मरण की गई आज्ञा ने सही समय और लोगों की प्रतीक्षा कराई। यह लंबा अंतर सहज विश्वास कहकर नहीं छोड़ा जाता; वह ऐसे घायल जीवन को बचाए रखने का बार-बार किया चुनाव है जिसकी उपयोगिता अभी दिखाई नहीं देती थी।'),
  ('scene-sampatis-wings-return-with-the-mission', 'a-fathers-anger-faces-the-missed-rescue', 'en', 'Sampati once demanded why Suparsva did nothing', 'After learning whom Suparsva had allowed through the pass, Sampati angrily asked why his son did not rescue the woman crying for Rama. The rebuke cannot change the event and comes from a father unable to fly there himself. Remembering it now keeps the witness chain morally unfinished: knowledge was present before action, but courage and understanding did not meet in time.'),
  ('scene-sampatis-wings-return-with-the-mission', 'a-fathers-anger-faces-the-missed-rescue', 'hi', 'संपाति ने कभी सुपार्श्व से पूछा था कि उसने कुछ क्यों नहीं किया', 'जब संपाति ने जाना कि सुपार्श्व ने मार्ग से किसे जाने दिया, तो उन्होंने क्रोध में पूछा कि राम को पुकारती स्त्री को उसने बचाया क्यों नहीं। यह फटकार घटना बदल नहीं सकती और ऐसे पिता से आती है जो स्वयं उड़कर वहाँ नहीं पहुँच सकता था। अब इसे याद रखना गवाही को नैतिक रूप से अधूरा रखता है—ज्ञान आया था, पर साहस और समझ समय पर नहीं मिले।'),
  ('scene-sampatis-wings-return-with-the-mission', 'the-wings-grow-before-the-witnesses', 'en', 'The old promise becomes visible', 'As Sampati completes his account, new wings spring from his body before the assembled searchers, bright like the young sun. The recovery follows the delivered testimony rather than preceding it. Everyone present can see that the long promise has reached its condition, though the wings themselves do not prove every distant detail; the corroborated account has already done that work.'),
  ('scene-sampatis-wings-return-with-the-mission', 'the-wings-grow-before-the-witnesses', 'hi', 'पुराना वचन सबके सामने दिखाई देता है', 'संपाति अपना वृत्तांत पूरा करते हैं तो जुटे खोजियों के सामने उनके शरीर से युवा सूर्य जैसे चमकीले नए पंख निकलते हैं। स्वस्थ होना गवाही देने के बाद आता है, उससे पहले नहीं। उपस्थित सभी देखते हैं कि लंबा वचन अपनी शर्त तक पहुँचा, फिर भी पंख हर दूर की बात का प्रमाण नहीं; वह काम पहले ही मिलती हुई गवाहियों ने किया है।'),
  ('scene-sampatis-wings-return-with-the-mission', 'sampati-tests-flight-and-the-party-rises', 'en', 'Restored motion becomes shared confidence', 'Sampati launches from the mountain to test the strength he had lost, while urging the searchers to act because they will find Sita. His flight gives the fasting party an embodied sign that apparent endings can reopen, and they rise with renewed vigour. Confidence returns, but it is now attached to the specific southern road rather than vague hope.'),
  ('scene-sampatis-wings-return-with-the-mission', 'sampati-tests-flight-and-the-party-rises', 'hi', 'लौटी गति साझा विश्वास बनती है', 'संपाति खोई शक्ति परखने पर्वत से उड़ते हैं और खोजियों से आगे बढ़ने को कहते हैं क्योंकि वे सीता तक पहुँचेंगे। उनकी उड़ान उपवास करते दल को शरीर से दिखाती है कि दिखते अंत फिर खुल सकते हैं, और सब नई ऊर्जा से उठते हैं। विश्वास लौटता है, पर अब वह धुँधली आशा नहीं, निश्चित दक्षिणी दिशा से जुड़ा है।'),
  ('scene-the-ocean-becomes-the-next-question', 'the-death-vigil-becomes-a-march', 'en', 'The searchers move toward the confirmed sea', 'The party that had settled to die now roars, bounds forward and reaches the northern shore of the southern sea. Sampati''s direction gives every step purpose: beyond this water stands Ravana, and Sita is alive there. Their success is real but limited. They have completed the search for where to go, not the rescue or even the first contact.'),
  ('scene-the-ocean-becomes-the-next-question', 'the-death-vigil-becomes-a-march', 'hi', 'खोजी निश्चित समुद्र की ओर बढ़ते हैं', 'जो दल मरने बैठा था वह गर्जना करके आगे बढ़ता और दक्षिणी समुद्र के उत्तरी तट पर पहुँचता है। संपाति की दिशा हर कदम को उद्देश्य देती है—इस जल के पार रावण है और सीता वहाँ जीवित हैं। उनकी सफलता वास्तविक पर सीमित है। उन्होंने कहाँ जाना है यह खोज लिया, बचाव या पहली भेंट अभी पूरी नहीं हुई।'),
  ('scene-the-ocean-becomes-the-next-question', 'the-sea-reflects-an-entire-world', 'en', 'The destination is clear; the barrier is immense', 'At the shore, the ocean appears calm in one place, playful in another and mountainous where waves rise. Its surface reflects the world while hidden beings and depths make it frightening. The party can finally face the correct direction, yet no path lies underfoot. A hundred-yojana horizon turns verified knowledge into a physical problem no ordinary march can solve.'),
  ('scene-the-ocean-becomes-the-next-question', 'the-sea-reflects-an-entire-world', 'hi', 'गंतव्य स्पष्ट है, बाधा विशाल', 'तट पर समुद्र कहीं सोया, कहीं खेलता और कहीं पर्वत जैसी लहरों में उठता दिखता है। उसकी सतह संसार को प्रतिबिंबित करती है, जबकि छिपी गहराइयाँ और प्राणी भय जगाते हैं। दल अंततः सही दिशा में खड़ा है, फिर भी पैरों के नीचे कोई मार्ग नहीं। सौ योजन का क्षितिज सत्यापित ज्ञान को ऐसी शारीरिक समस्या बना देता है जिसे सामान्य यात्रा हल नहीं कर सकती।'),
  ('scene-the-ocean-becomes-the-next-question', 'angada-stops-grief-from-consuming-strength', 'en', 'The leader interrupts a second collapse', 'Fear spreads again, but Angada tells the party that grief destroys energy precisely when action is required. This counsel differs from his earlier death vow because new information has changed the situation: they no longer face meaningless failure, but a defined obstacle. He cannot promise an easy crossing; he can stop the group from surrendering before measuring its abilities.'),
  ('scene-the-ocean-becomes-the-next-question', 'angada-stops-grief-from-consuming-strength', 'hi', 'नेता दूसरी टूटन को रोकते हैं', 'भय फिर फैलता है, पर अंगद कहते हैं कि जब कर्म चाहिए तभी शोक ऊर्जा नष्ट करता है। यह परामर्श उनके पुराने मृत्यु-व्रत से अलग है क्योंकि नई सूचना ने स्थिति बदल दी—अब वे अर्थहीन विफलता नहीं, निश्चित बाधा के सामने हैं। वे आसान पार की प्रतिज्ञा नहीं करते; वे दल को अपनी क्षमता मापने से पहले हारने से रोकते हैं।'),
  ('scene-the-ocean-becomes-the-next-question', 'who-can-make-the-hundred-yojana-leap', 'en', 'The next mission begins with an unanswered call', 'After a night of counsel, Angada asks every leader to declare how far he can leap and who can cross the full sea, find Sita and return. At first no one answers. The silence does not mean the party lacks courage; it marks the scale of the task and the need to remember abilities not yet brought forward. The road to Lanka ends here until someone recognises the one who can take it.'),
  ('scene-the-ocean-becomes-the-next-question', 'who-can-make-the-hundred-yojana-leap', 'hi', 'अगला अभियान अनुत्तरित पुकार से शुरू होता है', 'एक रात के विचार के बाद अंगद हर नेता से अपनी छलाँग की सीमा बताने और यह कहने को कहते हैं कि कौन पूरा समुद्र पार करके सीता को देखकर लौट सकता है। पहले कोई उत्तर नहीं देता। मौन साहस की कमी नहीं; वह कार्य की विशालता और अभी सामने न आई क्षमता को याद करने की आवश्यकता बताता है। लंका का मार्ग यहीं रुकता है, जब तक कोई उस व्यक्ति को न पहचाने जो इसे पार कर सके।'),
  ('scene-every-warrior-names-a-limit', 'the-leap-ladder-begins-at-ten', 'en', 'Boasts become measurable commitments', 'Angada''s question turns the anxious council into an ability check. With Gavaya among the assembled leaders, Gaya commits to ten yojanas, Gavaksha to twenty, Sarabha to thirty and Rishava to forty. Each warrior speaks for what he can actually attempt rather than borrowing confidence from the crowd. The growing ladder makes one fact visible: sincere effort can still fall far short of Lanka.'),
  ('scene-every-warrior-names-a-limit', 'the-leap-ladder-begins-at-ten', 'hi', 'दावे मापी जा सकने वाली प्रतिज्ञाएँ बनते हैं', 'अंगद का प्रश्न चिंतित सभा को क्षमता-जाँच में बदल देता है। जुटे नेताओं में गवय भी हैं; गय दस योजन, गवाक्ष बीस, शरभ तीस और ऋषभ चालीस योजन की प्रतिज्ञा करते हैं। हर योद्धा भीड़ से उधार लिया आत्मविश्वास नहीं, अपनी वास्तविक कोशिश की सीमा बताता है। बढ़ती सीढ़ी एक तथ्य साफ करती है—ईमानदार प्रयास भी लंका से बहुत पहले समाप्त हो सकता है।'),
  ('scene-every-warrior-names-a-limit', 'stronger-leaps-still-stop-short', 'en', 'The strongest estimates approach the sea''s scale', 'Gandhamadana names fifty yojanas, Mainda sixty, Dvivida seventy and Sushena eighty. Their estimates rise without mockery of those who offered less; every declaration helps map the army''s real reach. Yet the problem is not winning a contest among companions. A messenger must cross the full hundred yojanas, search hostile Lanka and preserve enough strength to return.'),
  ('scene-every-warrior-names-a-limit', 'stronger-leaps-still-stop-short', 'hi', 'सबसे बड़ी क्षमताएँ समुद्र की दूरी के निकट पहुँचती हैं', 'गंधमादन पचास, मैंद साठ, द्विविद सत्तर और सुषेण अस्सी योजन बताते हैं। उनकी सीमाएँ बढ़ती हैं, पर कम दूरी कहने वालों का उपहास नहीं होता; हर घोषणा सेना की वास्तविक पहुँच मापती है। समस्या साथियों में प्रतियोगिता जीतना नहीं। दूत को पूरे सौ योजन पार करके शत्रु लंका खोजना और लौटने की शक्ति भी बचानी है।'),
  ('scene-every-warrior-names-a-limit', 'jambavan-names-ninety-and-his-age', 'en', 'Jambavan measures the distance age has taken', 'Jambavan says he can now cover ninety yojanas, then refuses to let that number disguise his age. In youth he had circled the world when Vishnu crossed it in three strides; the memory proves former greatness, not present fitness. He honours the urgency of Rama and Sugriva while admitting that a leap ending ten yojanas short cannot rescue anyone.'),
  ('scene-every-warrior-names-a-limit', 'jambavan-names-ninety-and-his-age', 'hi', 'जाम्बवान बताते हैं कि आयु ने कितनी शक्ति ली है', 'जाम्बवान कहते हैं कि अब वे नब्बे योजन जा सकते हैं, फिर इस संख्या से अपनी आयु छिपने नहीं देते। युवावस्था में उन्होंने विष्णु के तीन पगों से जगत नापने के समय पृथ्वी की परिक्रमा की थी; स्मृति पुरानी महानता बताती है, वर्तमान योग्यता नहीं। वे राम-सुग्रीव की तात्कालिकता मानते हैं, पर दस योजन पहले समाप्त छलाँग किसी को बचा नहीं सकती।'),
  ('scene-every-warrior-names-a-limit', 'angada-can-cross-but-cannot-promise-return', 'en', 'A one-way success is not enough', 'Angada says he can cross the full hundred yojanas, but cannot promise that he will return. The admission is braver than an empty guarantee: reaching Sita without bringing news back would leave Rama and the army unable to act. Jambavan believes Angada''s strength may be greater than he claims, yet treats uncertainty about the return as a mission-critical warning.'),
  ('scene-every-warrior-names-a-limit', 'angada-can-cross-but-cannot-promise-return', 'hi', 'एकतरफा सफलता पर्याप्त नहीं', 'अंगद कहते हैं कि वे पूरे सौ योजन पार कर सकते हैं, पर लौटने का भरोसा नहीं दे सकते। यह स्वीकार खोखली गारंटी से अधिक साहसी है—सीता तक पहुँचकर समाचार न लौटाना राम और सेना को कार्रवाई से वंचित रखेगा। जाम्बवान मानते हैं कि अंगद की शक्ति उनके कथन से अधिक हो सकती है, फिर भी वापसी की अनिश्चितता को अभियान का निर्णायक खतरा मानते हैं।'),
  ('scene-every-warrior-names-a-limit', 'the-commander-is-the-root-to-preserve', 'en', 'Jambavan keeps the leader with the army', 'Jambavan tells Angada that a commander should direct the mission rather than be spent as its first messenger. Using the household language of his age, he describes the army as dependent on its leader and calls Angada the root from which success must grow. The point is practical: if the young heir disappears across the sea, the search party loses command, continuity and its route home.'),
  ('scene-every-warrior-names-a-limit', 'the-commander-is-the-root-to-preserve', 'hi', 'जाम्बवान सेनापति को सेना के साथ रखते हैं', 'जाम्बवान अंगद से कहते हैं कि सेनापति को अभियान निर्देशित करना चाहिए, पहले दूत की तरह खर्च नहीं होना चाहिए। अपने युग की गृहस्थ उपमा में वे सेना को नेता पर निर्भर बताते और अंगद को वह जड़ कहते हैं जिससे सफलता फलनी है। व्यावहारिक बात यह है—युवा उत्तराधिकारी समुद्र पार खो गया तो दल नेतृत्व, निरंतरता और घर लौटने का मार्ग खो देगा।'),
  ('scene-every-warrior-names-a-limit', 'jambavan-turns-to-the-silent-warrior', 'en', 'The unmeasured person has been standing apart', 'Angada warns that if neither he nor another crosses, the party will return to its death fast. Jambavan answers that the mission will not lose even a feather: he knows whom to send. He turns away from the completed ladder toward Hanuman, who has listened in silence and offered no distance. The decisive capacity was present throughout but had not entered its own name into the council.'),
  ('scene-every-warrior-names-a-limit', 'jambavan-turns-to-the-silent-warrior', 'hi', 'जिसकी क्षमता नहीं मापी गई, वह अलग मौन खड़ा है', 'अंगद चेताते हैं कि यदि न वे, न कोई दूसरा पार गया तो दल फिर मृत्यु-व्रत पर बैठेगा। जाम्बवान उत्तर देते हैं कि अभियान का एक पंख भी व्यर्थ नहीं जाएगा—वे जानते हैं किसे भेजना है। वे पूरी हुई क्षमता-सीढ़ी से हटकर हनुमान की ओर मुड़ते हैं, जो मौन सुनते रहे और कोई दूरी नहीं बोले। निर्णायक शक्ति शुरू से उपस्थित थी, पर उसने सभा में अपना नाम नहीं रखा था।'),
  ('scene-jambavan-remembers-hanuman', 'why-do-you-stand-silent', 'en', 'Jambavan addresses the silence directly', 'Jambavan asks why Hanuman, learned in every discipline and equal in energy to the strongest leaders, has stood apart without speaking. He compares the power in Hanuman''s arms with the wings of Garuda, who can lift serpents from the ocean. The praise is not empty cheering; it identifies observed strength, judgment and vigour that Hanuman has not counted in the public measure.'),
  ('scene-jambavan-remembers-hanuman', 'why-do-you-stand-silent', 'hi', 'जाम्बवान सीधे मौन को संबोधित करते हैं', 'जाम्बवान पूछते हैं कि सभी विद्याओं में निपुण और महान नेताओं के समान तेजस्वी हनुमान अलग मौन क्यों खड़े हैं। वे हनुमान की भुजाओं की शक्ति की तुलना गरुड़ के पंखों से करते हैं, जो समुद्र से सर्प उठा सकते हैं। यह खाली उत्साह नहीं; यह देखी हुई शक्ति, बुद्धि और ऊर्जा की पहचान है जिसे हनुमान ने सार्वजनिक माप में गिना ही नहीं।'),
  ('scene-jambavan-remembers-hanuman', 'anjana-challenges-the-unseen-touch', 'en', 'Hanuman''s beginning includes Anjana''s alarm and voice', 'Jambavan recalls Anjana, Kunjara''s daughter and Kesari''s wife, born in vanara form under a curse but able to take different shapes. When the Wind surrounded and embraced her on a mountain, she immediately challenged the unseen force and defended her bodily honour. The Wind answered that he had not physically violated her and foretold a son with his speed. Her alarm and objection remain part of Hanuman''s beginning rather than being erased by the prophecy.'),
  ('scene-jambavan-remembers-hanuman', 'anjana-challenges-the-unseen-touch', 'hi', 'हनुमान की उत्पत्ति में अंजना का भय और आवाज दोनों हैं', 'जाम्बवान अंजना को याद करते हैं—कुंजर की पुत्री और केसरी की पत्नी, जो शाप से वानर रूप में जन्मी थीं पर अनेक रूप धारण कर सकती थीं। पर्वत पर पवन ने उन्हें घेरकर आलिंगन किया तो उन्होंने तुरंत अदृश्य शक्ति को चुनौती दी और अपने शरीर की मर्यादा की रक्षा की। पवन ने कहा कि उन्होंने शारीरिक उल्लंघन नहीं किया और अपने वेग वाला पुत्र होने का वर बताया। अंजना का भय और विरोध भविष्यवाणी से मिटते नहीं।'),
  ('scene-jambavan-remembers-hanuman', 'the-child-leaps-for-the-sun', 'en', 'Hunger once made the sky feel reachable', 'Born in a mountain cave, the young Hanuman saw the rising sun and mistook it for a fruit. He leapt three thousand yojanas into the sky, enduring the sun''s radiance without losing resolve. The childhood act was uncontrolled and innocent rather than a planned rescue, but it reveals a scale of movement far beyond every distance just named on the shore.'),
  ('scene-jambavan-remembers-hanuman', 'the-child-leaps-for-the-sun', 'hi', 'बाल भूख ने कभी आकाश को पहुँच के भीतर कर दिया', 'पर्वतीय गुफा में जन्मे बाल हनुमान ने उगते सूर्य को फल समझ लिया। वे तीन हजार योजन आकाश में उछले और सूर्य का तेज सहते हुए भी उनका उत्साह नहीं टूटा। बाल-क्रिया अनियंत्रित और निष्कपट थी, योजनाबद्ध बचाव नहीं; फिर भी वह तट पर अभी बताई हर दूरी से कहीं बड़ी गति प्रकट करती है।'),
  ('scene-jambavan-remembers-hanuman', 'the-thunderbolt-breaks-the-jaw', 'en', 'The first great leap ends in injury', 'Indra strikes the rushing child with his thunderbolt. Hanuman falls onto a mountain with his left jaw broken, and the injury becomes attached to the name by which he is known. The memory does not use childhood power as proof that nothing can hurt him. His body carries evidence that immense ability without support, timing or restraint can meet immense force.'),
  ('scene-jambavan-remembers-hanuman', 'the-thunderbolt-breaks-the-jaw', 'hi', 'पहली महान छलाँग चोट पर समाप्त होती है', 'इंद्र दौड़ते बालक पर वज्र चलाते हैं। हनुमान पर्वत पर गिरते हैं, उनका बायाँ जबड़ा टूटता है और वही चोट उनके प्रसिद्ध नाम से जुड़ती है। स्मृति बाल-शक्ति को अजेयता का प्रमाण नहीं बनाती। उनका शरीर बताता है कि सहायता, समय और संयम बिना विशाल क्षमता भी विशाल प्रहार से टकरा सकती है।'),
  ('scene-jambavan-remembers-hanuman', 'wind-withdraws-and-the-gods-answer', 'en', 'One injured child stops the breath of three worlds', 'Seeing Hanuman struck down, the Wind withdraws from the three worlds in anger, and living beings begin to suffocate. The gods approach to restore balance. Brahma grants protection from weapons, while Indra, seeing the child survive the thunderbolt, grants that death will come only by Hanuman''s own will. Protection arrives after vulnerability has shaken everyone, not before it.'),
  ('scene-jambavan-remembers-hanuman', 'wind-withdraws-and-the-gods-answer', 'hi', 'एक घायल बालक तीनों लोकों की साँस रोक देता है', 'हनुमान को गिरा देखकर पवन क्रोध में तीनों लोकों से बहना रोक देते हैं और जीवों की साँस घुटने लगती है। संतुलन लौटाने देवता आते हैं। ब्रह्मा शस्त्रों से संरक्षण देते हैं, और बालक को वज्र से जीवित देखकर इंद्र वर देते हैं कि मृत्यु हनुमान की इच्छा से ही आएगी। संरक्षण उस कमजोरी के बाद आता है जिसने सबको हिला दिया, उससे पहले नहीं।'),
  ('scene-jambavan-remembers-hanuman', 'memory-becomes-a-body-ready-to-cross', 'en', 'Jambavan turns inheritance into a present choice', 'Jambavan remembers circling the earth twenty-one times during Vishnu''s three strides and gathering herbs when the ocean was churned, then contrasts that vanished youth with the strength now before him. He does not say birth alone completes the task; intelligence, discipline and a decision to act must join power. Called to rise for Sita and the waiting party, Hanuman accepts the measure and begins enlarging into a form fit for the sea.'),
  ('scene-jambavan-remembers-hanuman', 'memory-becomes-a-body-ready-to-cross', 'hi', 'जाम्बवान विरासत को वर्तमान चुनाव में बदलते हैं', 'जाम्बवान विष्णु के तीन पगों के समय पृथ्वी की इक्कीस परिक्रमा और समुद्र-मंथन के लिए औषधियाँ जुटाने की अपनी पुरानी शक्ति याद करते हैं, फिर उसे सामने खड़ी सामर्थ्य से जोड़ते हैं। वे नहीं कहते कि जन्म ही कार्य पूरा करेगा; शक्ति के साथ बुद्धि, संयम और कर्म का निर्णय चाहिए। सीता और प्रतीक्षारत दल के लिए पुकार स्वीकारकर हनुमान समुद्र योग्य विराट रूप लेने लगते हैं।'),
  ('scene-hanuman-rises-toward-lanka', 'the-growing-form-breaks-the-armys-sorrow', 'en', 'Visible readiness changes everyone watching', 'As Hanuman enlarges for the hundred-yojana crossing, the surrounding searchers abandon despair and erupt in astonished joy. His tail rises, his hair stands with energy and his face burns like smokeless fire. The transformation is not private spectacle: the army that could not answer Angada''s question now sees one companion deliberately shaping himself to meet it.'),
  ('scene-hanuman-rises-toward-lanka', 'the-growing-form-breaks-the-armys-sorrow', 'hi', 'दिखती तैयारी हर दर्शक को बदल देती है', 'सौ योजन पार करने के लिए हनुमान विराट होते हैं तो आसपास के खोजी निराशा छोड़कर विस्मित आनंद से भर उठते हैं। उनकी पूँछ उठती, रोम ऊर्जा से खड़े होते और मुख धूमरहित अग्नि जैसा चमकता है। यह निजी प्रदर्शन नहीं—जो सेना अंगद के प्रश्न का उत्तर नहीं दे सकी, वह अब एक साथी को जानबूझकर उसके योग्य रूप लेते देखती है।'),
  ('scene-hanuman-rises-toward-lanka', 'hanuman-names-the-winds-reach-as-his-own', 'en', 'He speaks from recovered self-knowledge', 'After saluting the elders, Hanuman identifies himself with the swift Wind who breaks mountain peaks and moves through open sky. He says he can circle Meru repeatedly, race Garuda''s flight and reach the sun before it crosses the heavens. The immense comparisons express that the sea is no longer his limit; they also answer the silence in which he had previously stood apart.'),
  ('scene-hanuman-rises-toward-lanka', 'hanuman-names-the-winds-reach-as-his-own', 'hi', 'वे लौटे आत्मज्ञान से बोलते हैं', 'वृद्धों को प्रणाम करके हनुमान स्वयं को उस तीव्र पवन से जोड़ते हैं जो पर्वत-शिखर तोड़कर खुले आकाश में चलता है। वे कहते हैं कि मेरु की बार-बार परिक्रमा, गरुड़ की उड़ान से होड़ और सूर्य के आकाश पार करने से पहले उसे छू सकते हैं। विशाल तुलनाएँ बताती हैं कि समुद्र अब उनकी सीमा नहीं और पहले का मौन समाप्त हो गया है।'),
  ('scene-hanuman-rises-toward-lanka', 'the-boasts-converge-on-seeing-sita', 'en', 'Cosmic reach narrows to one rescue objective', 'Hanuman says he could scatter clouds, shake mountains, overtake lightning, drain oceans or bring ambrosia from the gods. Flowers will follow his flight like stars, and he can return without touching earth. Then he gives the claim that matters: his judgment tells him he will see Vaidehi. The extravagant reach converges on finding one captive person and returning knowledge to those who wait.'),
  ('scene-hanuman-rises-toward-lanka', 'the-boasts-converge-on-seeing-sita', 'hi', 'ब्रह्मांडीय पहुँच एक बचाव-लक्ष्य पर केंद्रित होती है', 'हनुमान कहते हैं कि वे बादल बिखेर, पर्वत हिला, बिजली से आगे निकल, समुद्र सुखा या देवताओं से अमृत ला सकते हैं। फूल उनकी उड़ान के पीछे तारों जैसे चलेंगे और वे धरती छुए बिना लौट सकते हैं। फिर वे सबसे आवश्यक बात कहते हैं—उनकी बुद्धि बताती है कि वे वैदेही को देखेंगे। विराट पहुँच एक बंदिनी को खोजकर प्रतीक्षारत लोगों तक समाचार लौटाने पर केंद्रित होती है।'),
  ('scene-hanuman-rises-toward-lanka', 'the-elders-bind-their-wait-to-his-return', 'en', 'The crossing becomes a shared undertaking', 'Jambavan blesses Hanuman in the names of elders and saints, while the searchers promise to remain on the shore until he returns. He says their lives travel with him. The messenger will cross alone, but success is not framed as solitary glory: one person carries the dangerous movement while the others hold position, hope, ritual attention and the responsibility to receive his news.'),
  ('scene-hanuman-rises-toward-lanka', 'the-elders-bind-their-wait-to-his-return', 'hi', 'समुद्र-पार एक साझा अभियान बनता है', 'जाम्बवान वृद्धों और संतों की ओर से हनुमान को आशीर्वाद देते हैं, जबकि खोजी उनके लौटने तक तट पर रहने की प्रतिज्ञा करते हैं। वे कहते हैं कि सबके प्राण उनके साथ जा रहे हैं। दूत अकेले पार करेंगे, पर सफलता अकेली महिमा नहीं—एक व्यक्ति खतरनाक गति उठाता है, दूसरे स्थान, आशा, साधना और लौटे समाचार को ग्रहण करने का दायित्व सँभालते हैं।'),
  ('scene-hanuman-rises-toward-lanka', 'mahendra-is-chosen-to-bear-the-launch', 'en', 'Hanuman looks for ground strong enough', 'Hanuman says ordinary ground cannot sustain the force of his departure. He chooses the broad, rocky summits of Mahendra and climbs through forests, flowering slopes, springs and habitats of many creatures. The launch point is not an empty platform waiting for a hero; it is a living mountain whose firmness makes the crossing possible and whose inhabitants will feel the gathered momentum.'),
  ('scene-hanuman-rises-toward-lanka', 'mahendra-is-chosen-to-bear-the-launch', 'hi', 'हनुमान इतनी शक्ति सहने वाली भूमि खोजते हैं', 'हनुमान कहते हैं कि साधारण भूमि उनके प्रस्थान का वेग नहीं सह सकती। वे महेंद्र के चौड़े, शिलामय शिखर चुनकर वनों, पुष्पित ढलानों, झरनों और अनेक जीवों के आवासों से ऊपर चढ़ते हैं। प्रस्थान-स्थल नायक की प्रतीक्षा करता खाली मंच नहीं; वह जीवित पर्वत है जिसकी दृढ़ता पार को संभव बनाती और जिसके निवासी जुटते वेग को महसूस करेंगे।'),
  ('scene-hanuman-rises-toward-lanka', 'the-mountain-cries-before-the-leap', 'en', 'Gathered power already has consequences', 'As Hanuman ranges across the summit and concentrates his strength, Mahendra shakes. Water bursts from rocks, trees whip, animals flee, serpents emerge hissing and frightened inhabitants abandon the heights. The disturbance prevents power from appearing costless. Before his body leaves the mountain, Hanuman stills his purpose on Lanka; mentally, every scattered force has become one southward path.'),
  ('scene-hanuman-rises-toward-lanka', 'the-mountain-cries-before-the-leap', 'hi', 'जुटी शक्ति छलाँग से पहले ही परिणाम पैदा करती है', 'हनुमान शिखर पर घूमकर शक्ति केंद्रित करते हैं तो महेंद्र काँपता है। चट्टानों से जल फूटता, वृक्ष झूलते, पशु भागते, सर्प फुफकारते निकलते और भयभीत निवासी ऊँचाई छोड़ते हैं। यह हलचल शक्ति को बिना कीमत का दृश्य नहीं बनने देती। शरीर पर्वत छोड़ने से पहले हनुमान अपना उद्देश्य लंका पर स्थिर करते हैं; मन में हर बिखरी ऊर्जा एक दक्षिणी मार्ग बन जाती है।'),
  ('scene-mahendra-launches-the-messenger', 'hanuman-gathers-the-southward-force', 'en', 'Every force turns toward the south', 'On Mahendra''s summit, Hanuman honours the Sun, Indra, Wind, Brahma and all beings before facing south. He enlarges for Rama''s work, steadies breath, limbs and gaze, and gathers scattered strength into one intention: cross the sea, find Sita, and bring back knowledge that can move the waiting army.'),
  ('scene-mahendra-launches-the-messenger', 'hanuman-gathers-the-southward-force', 'hi', 'हर शक्ति दक्षिण की ओर मुड़ती है', 'महेंद्र के शिखर पर हनुमान सूर्य, इंद्र, पवन, ब्रह्मा और समस्त प्राणियों को प्रणाम करके दक्षिण की ओर मुख करते हैं। वे राम के कार्य के लिए विराट होते हैं, श्वास, अंग और दृष्टि को स्थिर करते हैं और बिखरी शक्ति को एक संकल्प में बाँधते हैं—समुद्र पार करना, सीता को खोजना और प्रतीक्षारत सेना के लिए समाचार लौटाना।'),
  ('scene-mahendra-launches-the-messenger', 'mahendra-bears-the-cost-of-power', 'en', 'The living mountain bears the launch', 'The pressure passes through a mountain full of life. Flowers fall, water and bright minerals burst from cracked stone, serpents strike the rocks, trees whip, and frightened animals and residents flee the heights. Mahendra makes the leap possible, but the shaking ground prevents Hanuman''s power from looking clean or costless.'),
  ('scene-mahendra-launches-the-messenger', 'mahendra-bears-the-cost-of-power', 'hi', 'जीवित पर्वत प्रस्थान का वेग सहता है', 'दबाव जीवन से भरे पर्वत के आर-पार दौड़ता है। फूल झरते हैं, फटी शिलाओं से जल और चमकते खनिज फूटते हैं, सर्प चट्टानों पर प्रहार करते हैं, वृक्ष झूलते हैं और भयभीत पशु तथा निवासी ऊँचाइयाँ छोड़ते हैं। महेंद्र छलाँग को संभव बनाता है, पर काँपती भूमि हनुमान की शक्ति को बिना मूल्य का चमत्कार नहीं बनने देती।'),
  ('scene-mahendra-launches-the-messenger', 'rama-arrow-leaves-the-mountain', 'en', 'A messenger flies like Rama''s arrow', 'Hanuman declares that he will travel like an arrow released by Rama. If Sita is not in Lanka, he will search farther; if every search fails, he will return with Ravana or the city itself rather than surrender the mission. He springs away, and uprooted trees follow briefly like companions before falling back into the sea.'),
  ('scene-mahendra-launches-the-messenger', 'rama-arrow-leaves-the-mountain', 'hi', 'दूत राम के बाण की तरह उड़ता है', 'हनुमान घोषणा करते हैं कि वे राम के छोड़े हुए बाण की तरह जाएँगे। यदि सीता लंका में नहीं मिलीं तो वे आगे खोजेंगे; हर खोज विफल हुई तो अभियान छोड़ने के बजाय रावण या पूरी लंका को साथ लाने का प्रयास करेंगे। वे उछलते हैं और उखड़े वृक्ष कुछ दूर साथियों की तरह उड़कर अंततः समुद्र में गिर जाते हैं।'),
  ('scene-mahendra-launches-the-messenger', 'the-ocean-reveals-the-flight', 'en', 'The sea makes speed visible', 'Wind and water reveal the scale of the flight. Hanuman''s shadow races over the surface, his passage drives waves apart, cloud banks wrap and release him, and displaced water exposes creatures below. The Sun softens its heat and Wind supports his son, while falling flowers scatter across the ocean like a moving field of stars.'),
  ('scene-mahendra-launches-the-messenger', 'the-ocean-reveals-the-flight', 'hi', 'समुद्र उड़ान की गति दिखाता है', 'पवन और जल उड़ान का विस्तार दिखाते हैं। हनुमान की छाया सतह पर दौड़ती है, उनका वेग लहरों को अलग करता है, बादल उन्हें ढककर फिर छोड़ते हैं और हटता जल नीचे के जीवों को उजागर कर देता है। सूर्य अपना ताप घटाता है, पवन पुत्र का सहारा बनता है और झरते फूल समुद्र पर चलते तारामंडल जैसे फैलते हैं।'),
  ('scene-mahendra-launches-the-messenger', 'mainaka-rises-with-an-old-debt', 'en', 'A golden mountain rises to offer rest', 'Ocean remembers that Rama belongs to the Ikshvaku line whose ancestor Sagara expanded his waters. In gratitude, he asks the hidden golden mountain Mainaka to rise and offer Hanuman food and rest. Hanuman first strikes the sudden peak as an obstruction, then stops when Mainaka takes a welcoming form and explains the invitation.'),
  ('scene-mahendra-launches-the-messenger', 'mainaka-rises-with-an-old-debt', 'hi', 'स्वर्णिम पर्वत विश्राम का निमंत्रण लेकर उठता है', 'समुद्र को स्मरण होता है कि राम उसी इक्ष्वाकु वंश के हैं जिसके पूर्वज सगर ने उसके जल का विस्तार कराया था। कृतज्ञता में वह छिपे स्वर्णिम पर्वत मैनाक से उठकर हनुमान को भोजन और विश्राम देने को कहता है। अचानक उठे शिखर को हनुमान पहले बाधा समझकर टकराते हैं, फिर मैनाक के स्वागत-रूप में आकर निमंत्रण समझाने पर रुकते हैं।'),
  ('scene-mahendra-launches-the-messenger', 'wind-once-saved-mainakas-wings', 'en', 'Hospitality carries another remembered rescue', 'Mainaka explains that mountains once moved through the sky on wings until people feared their unpredictable landings and Indra cut those wings away. Wind carried Mainaka into the ocean before the thunderbolt reached him and preserved both mountain and wings. Helping Wind''s son therefore repays protection with protection across generations.'),
  ('scene-mahendra-launches-the-messenger', 'wind-once-saved-mainakas-wings', 'hi', 'आतिथ्य के भीतर एक पुराना बचाव जीवित है', 'मैनाक बताते हैं कि कभी पर्वत पंखों से आकाश में घूमते थे, पर उनके अनिश्चित उतरने से लोग डरने लगे और इंद्र ने उनके पंख काट दिए। वज्र पहुँचने से पहले पवन मैनाक को समुद्र में ले गए और पर्वत के साथ उसके पंख भी बचा दिए। इसलिए पवन-पुत्र की सहायता करना पीढ़ियों के पार मिले संरक्षण का उत्तर है।'),
  ('scene-mahendra-launches-the-messenger', 'hanuman-accepts-without-stopping', 'en', 'Respect does not require abandoning the promise', 'Hanuman cannot accept a long rest because daylight is passing and he has promised his companions not to halt. Yet he does not reject Mainaka''s care: he touches the mountain affectionately, accepts the welcome in symbol, and continues. Hospitality is honoured without allowing a generous refuge to erase the urgency of Sita''s captivity.'),
  ('scene-mahendra-launches-the-messenger', 'hanuman-accepts-without-stopping', 'hi', 'सम्मान के लिए प्रतिज्ञा छोड़ना आवश्यक नहीं', 'हनुमान लंबा विश्राम स्वीकार नहीं कर सकते, क्योंकि दिन बीत रहा है और उन्होंने साथियों से न रुकने की प्रतिज्ञा की है। फिर भी वे मैनाक की सद्भावना ठुकराते नहीं—स्नेह से पर्वत को छूकर प्रतीक रूप में आतिथ्य स्वीकार करते हैं और आगे बढ़ते हैं। इस प्रकार उदार आश्रय सीता की बंदी अवस्था की तात्कालिकता को मिटाता नहीं।'),
  ('scene-mahendra-launches-the-messenger', 'surasa-demands-entry', 'en', 'Surasa turns the open sky into a test', 'The celestial beings ask Surasa, mother of serpents, to test the traveller''s strength and judgment. She blocks the route in a fearsome form and invokes her boon: Hanuman must enter her mouth. He explains Rama and Sita''s urgent need and offers to return afterward, but Surasa keeps the condition intact and demands an answer now.'),
  ('scene-mahendra-launches-the-messenger', 'surasa-demands-entry', 'hi', 'सुरसा खुले आकाश को परीक्षा बना देती हैं', 'दैवी प्राणी सर्पमाता सुरसा से यात्री के बल और निर्णय की परीक्षा लेने को कहते हैं। वे भयंकर रूप में मार्ग रोककर अपना वर रखती हैं—हनुमान को उनके मुख में प्रवेश करना होगा। हनुमान राम और सीता की तात्कालिक आवश्यकता समझाकर लौटते समय आने का प्रस्ताव देते हैं, पर सुरसा शर्त बनाए रखकर अभी उत्तर माँगती हैं।'),
  ('scene-mahendra-launches-the-messenger', 'smallness-solves-surasas-condition', 'en', 'The size contest is won by becoming small', 'Hanuman grows; Surasa opens wider. Their measures climb until his body fills the sky and her mouth reaches beyond it. Then he abandons the contest, shrinks to the size of a thumb, enters and exits before her jaws can close, bows, and truthfully says her boon is fulfilled. Surasa reveals the test and blesses his search.'),
  ('scene-mahendra-launches-the-messenger', 'smallness-solves-surasas-condition', 'hi', 'आकार की होड़ छोटा बनकर सुलझती है', 'हनुमान बढ़ते हैं और सुरसा मुख और चौड़ा करती हैं। दोनों का आकार बढ़ता जाता है, यहाँ तक कि उनका शरीर आकाश भर देता है और उनका मुख उससे भी आगे फैलता है। तभी हनुमान होड़ छोड़कर अँगूठे जितने छोटे होते हैं, जबड़े बंद होने से पहले भीतर जाकर बाहर आते हैं, प्रणाम करते हैं और सत्यपूर्वक कहते हैं कि वर पूरा हुआ। सुरसा परीक्षा प्रकट कर खोज को आशीष देती हैं।'),
  ('scene-mahendra-launches-the-messenger', 'simhika-seizes-the-shadow', 'en', 'A hidden predator catches the shadow', 'The next slowing is not a test. Simhika reaches from below, grips Hanuman''s moving shadow, and steals speed from his body. Remembering Sugriva''s warning about a creature with this power, Hanuman studies the drag instead of striking blindly; he identifies where the attacker is and prepares for the mouth opening beneath him.'),
  ('scene-mahendra-launches-the-messenger', 'simhika-seizes-the-shadow', 'hi', 'छिपी शिकारी छाया पकड़ लेती है', 'अगली रुकावट परीक्षा नहीं है। सिंहिका नीचे से हनुमान की चलती छाया पकड़कर उनके शरीर की गति खींच लेती है। ऐसी शक्ति वाले प्राणी के बारे में सुग्रीव की चेतावनी याद करके हनुमान अंधा प्रहार नहीं करते; वे खिंचाव को पढ़ते हैं, हमलावर का स्थान पहचानते हैं और नीचे खुलते मुख के लिए तैयार होते हैं।'),
  ('scene-mahendra-launches-the-messenger', 'skill-defeats-the-shadow-hunter', 'en', 'Strength enters only after judgment', 'Hanuman enlarges so Simhika opens fully, then becomes compact enough to enter the danger on his own terms. Inside, he locates her vital centre, tears it with his claws, and escapes as she falls into the sea. Unlike Surasa, this attacker sought to consume him; endurance, sight, timing and controlled force keep the two encounters morally distinct.'),
  ('scene-mahendra-launches-the-messenger', 'skill-defeats-the-shadow-hunter', 'hi', 'निर्णय के बाद ही शक्ति प्रहार करती है', 'हनुमान इतना बढ़ते हैं कि सिंहिका पूरा मुख खोल दे, फिर उतने छोटे हो जाते हैं कि खतरे में अपनी शर्तों पर प्रवेश कर सकें। भीतर वे उसके मर्म को पहचानकर नखों से विदीर्ण करते हैं और उसके समुद्र में गिरते ही बाहर निकल आते हैं। सुरसा के विपरीत यह हमलावर सच में उन्हें निगलना चाहती थी; धैर्य, दृष्टि, समय और नियंत्रित बल दोनों प्रसंगों का अंतर बनाए रखते हैं।'),
  ('scene-mahendra-launches-the-messenger', 'the-giant-becomes-a-scout', 'en', 'The far shore demands a different heroism', 'Forests, an island and Lanka''s mountain ridges appear beyond the water. Hanuman realizes that the giant form which crossed the ocean would announce him to every guard, so he reduces himself before landing on Lamba peak. The spectacular crossing ends in deliberate quiet: the next task is not to be seen, but to see.'),
  ('scene-mahendra-launches-the-messenger', 'the-giant-becomes-a-scout', 'hi', 'दूसरा तट अलग प्रकार का साहस माँगता है', 'जल के पार वन, द्वीप और लंका की पर्वत-रेखाएँ दिखाई देती हैं। हनुमान समझते हैं कि जिस विराट रूप ने समुद्र पार किया, वही हर प्रहरी को उनकी खबर दे देगा; इसलिए वे लंब शिखर पर उतरने से पहले स्वयं को छोटा कर लेते हैं। अद्भुत उड़ान जानबूझकर रचे मौन में समाप्त होती है—अब काम दिखाई देना नहीं, देखना है।'),
  ('scene-lanka-changes-the-mission-to-stealth', 'the-crossing-leaves-no-fatigue', 'en', 'The crossing ends with capacity still in reserve', 'Hanuman settles above the coast and notices that the hundred-yojana flight has not exhausted him. The discovery matters because landing was never the whole mission: he still has to enter a guarded city, find one concealed captive, judge her condition, and preserve a return path. He rests only long enough to read the terrain below.'),
  ('scene-lanka-changes-the-mission-to-stealth', 'the-crossing-leaves-no-fatigue', 'hi', 'समुद्र पार करके भी शक्ति शेष रहती है', 'हनुमान तट के ऊपर ठहरकर देखते हैं कि सौ योजन की उड़ान ने उन्हें थकाया नहीं है। यह इसलिए महत्त्वपूर्ण है क्योंकि उतरना पूरा अभियान नहीं था—उन्हें सुरक्षित नगर में प्रवेश करना, छिपी बंदिनी को खोजना, उनकी दशा जानना और वापसी का मार्ग बचाना है। वे केवल उतनी देर रुकते हैं जितनी नीचे का भू-दृश्य समझने के लिए आवश्यक है।'),
  ('scene-lanka-changes-the-mission-to-stealth', 'beauty-and-fortification-share-one-view', 'en', 'Lanka is garden, home, and fortress at once', 'The coast opens into woods, wetlands, flowering gardens and water bright with lotuses. Beyond them rise golden walls, deep moats, banners, guarded gates and many-storeyed homes of crystal and gold. Hanuman feels delight at the city''s beauty and pressure from its defence at the same time; neither view cancels the other.'),
  ('scene-lanka-changes-the-mission-to-stealth', 'beauty-and-fortification-share-one-view', 'hi', 'लंका एक साथ उद्यान, घर और दुर्ग है', 'तट वन, आर्द्रभूमि, पुष्पित उद्यानों और कमलों से चमकते जल में खुलता है। उनके पार स्वर्णिम दीवारें, गहरी खाइयाँ, ध्वज, सुरक्षित द्वार और स्फटिक तथा सोने के बहुमंज़िला घर उठते हैं। हनुमान नगर की सुंदरता से आनंदित और उसकी रक्षा से दबावग्रस्त एक साथ होते हैं; कोई एक दृष्टि दूसरी को मिटाती नहीं।'),
  ('scene-lanka-changes-the-mission-to-stealth', 'the-northern-gate-defeats-simple-war-plans', 'en', 'The fortress rejects easy answers', 'From the northern gate, Hanuman studies the moats, walls, weapons and disciplined guards. Conciliation, gifts, division and direct force all seem powerless against a city this secure, and only a handful of the strongest companions might even cross the sea. He lets the observation reduce confidence instead of forcing it to support a premature war plan.'),
  ('scene-lanka-changes-the-mission-to-stealth', 'the-northern-gate-defeats-simple-war-plans', 'hi', 'दुर्ग सरल उत्तरों को अस्वीकार करता है', 'उत्तरी द्वार से हनुमान खाइयों, दीवारों, अस्त्रों और अनुशासित पहरेदारों को देखते हैं। समझौता, उपहार, फूट या सीधा बल—इतने सुरक्षित नगर के सामने कोई उपाय पर्याप्त नहीं लगता, और केवल कुछ अत्यंत शक्तिशाली साथी ही समुद्र पार कर सकेंगे। वे इस तथ्य को जल्दबाज़ युद्ध-योजना का समर्थन बनाने के बजाय अपने आत्मविश्वास को यथार्थ में बाँधने देते हैं।'),
  ('scene-lanka-changes-the-mission-to-stealth', 'sitas-life-comes-before-war', 'en', 'First learn whether Sita lives', 'Hanuman stops the imagined battle before it outruns the facts. Until he finds Sita and learns whether she is alive, every estimate of invasion is speculation and every alarm he triggers may endanger the person he came to save. The mission narrows again: see her, understand her situation, and carry reliable news back to Rama.'),
  ('scene-lanka-changes-the-mission-to-stealth', 'sitas-life-comes-before-war', 'hi', 'पहले जानना है कि सीता जीवित हैं', 'हनुमान कल्पित युद्ध को तथ्यों से आगे भागने से रोकते हैं। जब तक वे सीता को खोजकर यह नहीं जान लेते कि वे जीवित हैं, आक्रमण का हर अनुमान कल्पना है और उनके द्वारा उठाया गया हर अलार्म उसी व्यक्ति को संकट में डाल सकता है जिसे वे बचाने आए हैं। अभियान फिर केंद्रित होता है—उन्हें देखना, उनकी स्थिति समझना और विश्वसनीय समाचार राम तक पहुँचाना।'),
  ('scene-lanka-changes-the-mission-to-stealth', 'a-messenger-can-ruin-success', 'en', 'Pride can destroy work at the edge of success', 'Hanuman reflects that an envoy who is reckless, proud or unable to adapt can ruin careful work just when it is close to success. His great body solved the ocean, but inside Lanka it would become evidence against him. Good service now means giving up the form that earned applause and choosing the form that protects the information.'),
  ('scene-lanka-changes-the-mission-to-stealth', 'a-messenger-can-ruin-success', 'hi', 'सफलता के किनारे अहंकार सब नष्ट कर सकता है', 'हनुमान विचार करते हैं कि उतावला, अहंकारी या परिस्थिति के अनुसार न बदलने वाला दूत सावधानी से किए कार्य को सफलता के बिल्कुल पास नष्ट कर सकता है। उनके विराट शरीर ने समुद्र की समस्या सुलझाई, पर लंका के भीतर वही उनके विरुद्ध प्रमाण बनेगा। अच्छी सेवा अब प्रशंसा पाने वाले रूप को छोड़कर सूचना बचाने वाला रूप चुनना है।'),
  ('scene-lanka-changes-the-mission-to-stealth', 'the-moon-opens-the-stealth-route', 'en', 'A cat-sized scout waits for the moon', 'Hanuman reduces himself to a form no larger than a cat and waits for sunset instead of forcing immediate entry. As the moon rises over crystal roofs and golden gates, patrol sightlines change and shadows connect the wall to the interior. He moves toward the city carrying immense capacity inside a shape designed not to disturb it.'),
  ('scene-lanka-changes-the-mission-to-stealth', 'the-moon-opens-the-stealth-route', 'hi', 'बिल्ली जितना गुप्तचर चाँद की प्रतीक्षा करता है', 'हनुमान स्वयं को बिल्ली से बड़े न दिखने वाले रूप में छोटा करके तत्काल प्रवेश के बजाय सूर्यास्त की प्रतीक्षा करते हैं। स्फटिक छतों और स्वर्णिम द्वारों पर चाँद उठते ही गश्त की दृष्टि-रेखाएँ बदलती हैं और छायाएँ दीवार को भीतर से जोड़ देती हैं। वे ऐसे छोटे रूप में नगर की ओर बढ़ते हैं जिसके भीतर विराट क्षमता छिपी है, पर जो उसे अनावश्यक रूप से विचलित नहीं करेगा।'),
  ('scene-the-city-guardian-tests-entry', 'lankini-speaks-as-the-city', 'en', 'The city meets the intruder in person', 'At the wall, a formidable woman blocks the small traveller and names herself Lankini, guardian and embodied strength of Lanka under Ravana. She demands his identity and purpose and warns that entry will cost his life. The encounter gives the fortress a speaking will; it is not merely architecture waiting to be bypassed.'),
  ('scene-the-city-guardian-tests-entry', 'lankini-speaks-as-the-city', 'hi', 'नगर स्वयं घुसपैठिये के सामने आता है', 'दीवार पर एक प्रबल स्त्री छोटे यात्री को रोककर अपना परिचय लंकिनी के रूप में देती है—रावण के अधीन लंका की रक्षिका और उसकी साकार शक्ति। वह पहचान और उद्देश्य पूछती है तथा चेतावनी देती है कि प्रवेश की कीमत जीवन होगी। इस सामना से दुर्ग को बोलती हुई इच्छा मिलती है; वह केवल पार की जाने वाली इमारत नहीं रहता।'),
  ('scene-the-city-guardian-tests-entry', 'hanuman-conceals-the-rescue-mission', 'en', 'The scout answers without exposing Sita', 'Hanuman says he wishes to see the celebrated city''s groves, homes and defences and will leave after looking. He does not reveal Rama, Sita or the rescue because the guardian has not earned that knowledge and any alarm could close the search before it begins. Curiosity becomes a cover that is plausible without surrendering the true objective.'),
  ('scene-the-city-guardian-tests-entry', 'hanuman-conceals-the-rescue-mission', 'hi', 'गुप्तचर सीता का उद्देश्य प्रकट किए बिना उत्तर देता है', 'हनुमान कहते हैं कि वे प्रसिद्ध नगर के उपवन, घर और रक्षा देखना चाहते हैं और देखकर लौट जाएँगे। वे राम, सीता या बचाव का उद्देश्य नहीं बताते, क्योंकि रक्षिका को वह जानकारी देना उचित नहीं और कोई भी अलार्म खोज शुरू होने से पहले समाप्त कर सकता है। जिज्ञासा ऐसा आवरण बनती है जो विश्वसनीय भी है और वास्तविक लक्ष्य भी सुरक्षित रखती है।'),
  ('scene-the-city-guardian-tests-entry', 'lankini-strikes-first', 'en', 'The warning becomes a blow', 'Lankini refuses the explanation and strikes Hanuman with her open palm. The blow ends the possibility of simply talking past the boundary and reveals that she intends to enforce the city''s command physically. Hanuman''s anger rises, but he still has time to choose how much force the situation actually requires.'),
  ('scene-the-city-guardian-tests-entry', 'lankini-strikes-first', 'hi', 'चेतावनी प्रहार में बदलती है', 'लंकिनी स्पष्टीकरण अस्वीकार करके खुली हथेली से हनुमान पर प्रहार करती है। यह आघात सीमा को केवल बातचीत से पार करने की संभावना समाप्त करता है और दिखाता है कि वह नगर की आज्ञा को शरीर से लागू करेगी। हनुमान का क्रोध उठता है, फिर भी उनके पास यह चुनने का क्षण रहता है कि परिस्थिति को वास्तव में कितना बल चाहिए।'),
  ('scene-the-city-guardian-tests-entry', 'one-restrained-blow-ends-the-fight', 'en', 'Hanuman answers with less than his full strength', 'Hanuman uses his left fist and deliberately restrains the power that crossed the ocean. Lankini falls from the single response, and he does not continue the attack once the threat has ended. His compassion after anger preserves the difference between overcoming a guard and taking pleasure in another person''s defeat.'),
  ('scene-the-city-guardian-tests-entry', 'one-restrained-blow-ends-the-fight', 'hi', 'हनुमान पूरी शक्ति से कम बल का उत्तर देते हैं', 'हनुमान बायीं मुट्ठी से प्रहार करते हैं और समुद्र पार कराने वाली शक्ति को जानबूझकर सीमित रखते हैं। एक ही उत्तर से लंकिनी गिर जाती है और खतरा समाप्त होने पर वे आक्रमण जारी नहीं रखते। क्रोध के बाद उनकी करुणा रक्षिका को पार करने और किसी की हार में आनंद लेने के बीच का अंतर बचाए रखती है।'),
  ('scene-the-city-guardian-tests-entry', 'lankini-opens-the-prophesied-threshold', 'en', 'Defeat awakens an old warning', 'Lankini asks for mercy and remembers Brahma''s warning: when a monkey subdues her, fear will enter the people who hold Lanka, and the consequences of Sita''s abduction will begin to unfold. She grants Hanuman passage and tells him to search freely. The guardian remains the one who interprets the threshold and opens it.'),
  ('scene-the-city-guardian-tests-entry', 'lankini-opens-the-prophesied-threshold', 'hi', 'पराजय पुरानी चेतावनी जगा देती है', 'लंकिनी दया माँगकर ब्रह्मा की चेतावनी याद करती है—जब कोई वानर उसे परास्त करेगा, लंका पर अधिकार रखने वालों में भय प्रवेश करेगा और सीता-हरण के परिणाम खुलने लगेंगे। वह हनुमान को मार्ग देती है और स्वतंत्र खोज की अनुमति देती है। सीमा का अर्थ बताने और उसे खोलने वाली अब भी वही रक्षिका है।'),
  ('scene-hanuman-enters-the-watched-city', 'the-wall-is-safer-than-the-gate', 'en', 'Hanuman enters where no gate can report him', 'Hanuman avoids the guarded entrance and leaps over a section of wall where no gate controls movement. He places his left foot inside enemy-held ground, carrying an old sign of challenge without turning it into noise. The route preserves stealth because victory here depends on crossing the boundary without allowing its systems to notice.'),
  ('scene-hanuman-enters-the-watched-city', 'the-wall-is-safer-than-the-gate', 'hi', 'हनुमान वहाँ से प्रवेश करते हैं जहाँ कोई द्वार सूचना नहीं दे सकता', 'हनुमान सुरक्षित प्रवेश-द्वार से बचकर दीवार के उस भाग को लाँघते हैं जहाँ कोई द्वार आवागमन नियंत्रित नहीं करता। वे शत्रु-अधीन भूमि पर बायाँ पैर रखते हैं—पुराना चुनौती-संकेत साथ है, पर कोई शोर नहीं। यह मार्ग गुप्तता बचाता है, क्योंकि यहाँ सफलता सीमा पार करने में नहीं बल्कि उसकी व्यवस्था को खबर न होने देने में है।'),
  ('scene-hanuman-enters-the-watched-city', 'lanka-is-heard-before-it-is-mapped', 'en', 'The night city arrives as sound', 'On blossom-strewn streets, Hanuman hears laughter, ornaments, measured footsteps, clapping, trumpets, songs moving through high, middle and low registers, fierce roars, sacred recitation and murmured formulas. The layered sound refuses to reduce Lanka to silence or menace; homes, worship, celebration and military readiness occupy the night together.'),
  ('scene-hanuman-enters-the-watched-city', 'lanka-is-heard-before-it-is-mapped', 'hi', 'रात्रि का नगर पहले ध्वनि बनकर मिलता है', 'फूलों से बिखरी सड़कों पर हनुमान हँसी, आभूषणों की झंकार, नपे कदम, तालियाँ, तुरहियाँ, ऊँचे-मध्य-नीचे स्वरों में चलता गायन, उग्र गर्जना, पवित्र पाठ और धीमे मंत्र सुनते हैं। ध्वनियों की परतें लंका को केवल मौन या भय में सीमित नहीं होने देतीं; घर, उपासना, उत्सव और सैन्य तैयारी एक ही रात में साथ हैं।'),
  ('scene-hanuman-enters-the-watched-city', 'one-city-holds-many-lives', 'en', 'No single silhouette explains Lanka', 'Hanuman passes people at study and worship, households at leisure, performers, guards, workers, and residents with many bodies, roles and ways of dress. Some appear in ascetic clothing while carrying hidden duties; others display weapons openly. He observes difference as information about a complicated society, not as permission to turn its inhabitants into spectacle.'),
  ('scene-hanuman-enters-the-watched-city', 'one-city-holds-many-lives', 'hi', 'एक आकृति पूरी लंका को नहीं समझा सकती', 'हनुमान अध्ययन और उपासना में लगे लोगों, विश्राम करते परिवारों, कलाकारों, प्रहरियों, श्रमिकों और अनेक शरीर, भूमिकाएँ तथा पहनावे वाले निवासियों के पास से गुजरते हैं। कुछ तपस्वी वेश में छिपे दायित्व निभाते हैं, कुछ खुले अस्त्र रखते हैं। वे विविधता को जटिल समाज की जानकारी की तरह देखते हैं, निवासियों को तमाशा बनाने की अनुमति की तरह नहीं।'),
  ('scene-hanuman-enters-the-watched-city', 'surveillance-thickens-toward-the-centre', 'en', 'Every inward step adds another watcher', 'Disguised observers, armed patrols and dense guard formations become more frequent as Hanuman moves inward. Some watchers blend into devotional or ordinary street life; others occupy obvious military stations, and thousands protect the central compound. The city does not separate civilian movement cleanly from surveillance, so the scout must read behaviour rather than costume.'),
  ('scene-hanuman-enters-the-watched-city', 'surveillance-thickens-toward-the-centre', 'hi', 'भीतर बढ़ते हर कदम पर नया पहरेदार जुड़ता है', 'हनुमान के भीतर बढ़ने पर वेश बदले निरीक्षक, सशस्त्र गश्त और घनी प्रहरी-पंक्तियाँ बढ़ती जाती हैं। कुछ निगरानी करने वाले उपासना या सामान्य सड़क-जीवन में घुले हैं, कुछ स्पष्ट सैन्य स्थानों पर हैं और हजारों लोग केंद्रीय परिसर की रक्षा करते हैं। नगर नागरिक गतिविधि और निगरानी को साफ अलग नहीं करता, इसलिए गुप्तचर को वेश के बजाय व्यवहार पढ़ना पड़ता है।'),
  ('scene-hanuman-enters-the-watched-city', 'ravanas-inner-residence-becomes-the-next-world', 'en', 'The search reaches Ravana''s guarded interior', 'Gold arches, lotus-filled water, horses, chariots, elephants, birds, gems, pearls, sandalwood and fragrant agarwood announce Ravana''s immense inner compound. Guards and wealth thicken together until Hanuman crosses into the private residence itself. He has entered the right domain, but Sita has not yet been found; the search begins anew inside.'),
  ('scene-hanuman-enters-the-watched-city', 'ravanas-inner-residence-becomes-the-next-world', 'hi', 'खोज रावण के सुरक्षित भीतरी निवास तक पहुँचती है', 'स्वर्णिम तोरण, कमल-भरा जल, घोड़े, रथ, हाथी, पक्षी, रत्न, मोती, चंदन और अगरु की सुगंध रावण के विशाल भीतरी परिसर का संकेत देते हैं। पहरा और वैभव साथ घने होते जाते हैं, यहाँ तक कि हनुमान निजी निवास में प्रवेश कर जाते हैं। वे सही क्षेत्र में पहुँच गए हैं, पर सीता अभी नहीं मिलीं; भीतर खोज फिर आरंभ होती है।'),
  ('scene-moon-opens-lanka-at-night', 'moonlight-makes-the-city-readable', 'en', 'The moon becomes the scout''s lantern', 'The full moon rises among the stars, brightens roofs and courtyards, thins the darkness between buildings, and gives Hanuman enough light to distinguish movement without announcing his own. It also swells the sea behind him, keeping the impossible crossing visible while the search changes from distance to detail.'),
  ('scene-moon-opens-lanka-at-night', 'moonlight-makes-the-city-readable', 'hi', 'चाँद गुप्तचर का दीप बनता है', 'पूर्ण चंद्र तारों के बीच उठकर छतों और आँगनों को उजाला देता है, भवनों के बीच का अँधेरा कम करता है और हनुमान को बिना स्वयं प्रकट हुए गतिविधियाँ पहचानने देता है। पीछे समुद्र भी चाँद से उठता है, जिससे असंभव पार की गई दूरी दिखाई रहती है और खोज अब दूरी से बारीकी में बदलती है।'),
  ('scene-moon-opens-lanka-at-night', 'homes-continue-through-the-night', 'en', 'Lanka does not sleep as one body', 'Strings sound, couples settle beside one another, friends argue, revellers boast, guards flex bows, and elephants call across the compounds. Some residents are awake, some asleep, some angry, affectionate, intoxicated, dutiful, or absorbed in conversation. Hanuman enters a city of simultaneous lives rather than a silent level populated only by targets.'),
  ('scene-moon-opens-lanka-at-night', 'homes-continue-through-the-night', 'hi', 'पूरी लंका एक साथ नहीं सोती', 'तार-वाद्य बजते हैं, दंपति साथ विश्राम करते हैं, मित्र बहस करते हैं, उत्सव मनाने वाले डींगें हाँकते हैं, प्रहरी धनुष सँभालते हैं और हाथियों की पुकार परिसरों में गूँजती है। कोई जाग रहा है, कोई सो रहा है; कोई क्रोधित, स्नेही, मदमस्त, कर्तव्यरत या बातचीत में डूबा है। हनुमान केवल लक्ष्यों से भरे मौन स्तर में नहीं, एक साथ चलते अनेक जीवनों के नगर में प्रवेश करते हैं।'),
  ('scene-moon-opens-lanka-at-night', 'virtue-and-danger-share-the-streets', 'en', 'Appearance cannot sort ally from threat', 'Hanuman sees people of graceful and irregular forms, varied dress, disciplined speech, reverence, learning, vanity, courage, and tenderness. Beauty does not guarantee safety, and unfamiliar bodies do not prove wickedness. He must read conduct, weapons, authority, and attention instead of turning physical difference into a moral map.'),
  ('scene-moon-opens-lanka-at-night', 'virtue-and-danger-share-the-streets', 'hi', 'रूप से साथी और खतरे को अलग नहीं किया जा सकता', 'हनुमान सुंदर और अनगढ़ रूपों, अलग वेश, संयमित वाणी, श्रद्धा, ज्ञान, अहंकार, साहस और कोमलता वाले लोगों को देखते हैं। सुंदरता सुरक्षा की गारंटी नहीं और अपरिचित शरीर दुष्टता का प्रमाण नहीं। उन्हें शारीरिक भिन्नता को नैतिक नक्शा बनाने के बजाय आचरण, अस्त्र, अधिकार और ध्यान पढ़ना है।'),
  ('scene-moon-opens-lanka-at-night', 'every-moonlit-face-is-checked', 'en', 'Hope pauses at every possible face', 'From roof edges and shadowed openings, Hanuman checks women resting with partners, sitting in halls, laughing, grieving, waiting, or sleeping alone. He looks for the particular person Rama described, not an interchangeable beautiful figure. Each mismatch protects identity but also removes another place where Sita might have been found.'),
  ('scene-moon-opens-lanka-at-night', 'every-moonlit-face-is-checked', 'hi', 'आशा हर संभावित चेहरे पर ठहरती है', 'छतों के किनारों और अँधेरे खुले स्थानों से हनुमान साथियों के पास विश्राम करती, सभागारों में बैठी, हँसती, दुखी, प्रतीक्षा करती या अकेली सोती स्त्रियों को देखते हैं। वे किसी भी सुंदर आकृति को नहीं, राम द्वारा बताई विशिष्ट व्यक्ति को खोज रहे हैं। हर असमानता पहचान की रक्षा करती है, पर सीता के मिलने की एक और संभावना घटा देती है।'),
  ('scene-moon-opens-lanka-at-night', 'absence-becomes-heavier-than-distance', 'en', 'The search begins to doubt itself', 'After so many rooms and faces, Hanuman still finds no woman separated from Rama, worn by captivity, and fixed on returning to him. The ocean no longer feels like the hardest part; a person can be hidden inside a crowded city more completely than an island can be hidden beyond the horizon. His confidence gives way to focused sadness, not retreat.'),
  ('scene-moon-opens-lanka-at-night', 'absence-becomes-heavier-than-distance', 'hi', 'खोज स्वयं पर संदेह करने लगती है', 'इतने कक्षों और चेहरों के बाद भी हनुमान को राम से बिछड़ी, बंदीपन से क्षीण और लौटने की इच्छा में स्थिर वह स्त्री नहीं मिलती। अब समुद्र सबसे कठिन भाग नहीं लगता; भीड़ भरे नगर में एक व्यक्ति क्षितिज पार द्वीप से भी अधिक छिप सकता है। उनका आत्मविश्वास पीछे हटने में नहीं, केंद्रित उदासी में बदलता है।'),
  ('scene-hanuman-searches-the-command-houses', 'the-palace-perimeter-is-an-ecosystem', 'en', 'Ravana''s residence begins before its doors', 'A sun-bright wall, silver and gold arches, courts, gates, elephant drivers, chariot crews, tireless horses, bells, birds, beasts, guards, and crowded approaches form the palace perimeter. Hanuman cannot treat any single wall as the defence; people, animals, movement, sound, and ceremony make a living security system around the ruler.'),
  ('scene-hanuman-searches-the-command-houses', 'the-palace-perimeter-is-an-ecosystem', 'hi', 'रावण का निवास द्वार से पहले शुरू हो जाता है', 'सूर्य-सी चमकती दीवार, चाँदी-सोने के तोरण, आँगन, द्वार, महावत, रथ-दल, अथक घोड़े, घंटियाँ, पक्षी, पशु, प्रहरी और भीड़ भरे मार्ग महल की बाहरी सीमा बनाते हैं। हनुमान किसी एक दीवार को रक्षा नहीं मान सकते; लोग, पशु, गति, ध्वनि और समारोह शासक के चारों ओर जीवित सुरक्षा-तंत्र बनाते हैं।'),
  ('scene-hanuman-searches-the-command-houses', 'commanders-form-a-search-network', 'en', 'Every commander has a separate stronghold', 'Hanuman bounds through the residences of Prahasta, Mahaparshva, cloud-sized Kumbhakarna, Vibhishana, Mahodara, Virupaksha, Indrajit, and many other officers. The names matter as a command network, not a roll call: Sita could be hidden under any authority, and Ravana''s rule is distributed across households with their own guards and resources.'),
  ('scene-hanuman-searches-the-command-houses', 'commanders-form-a-search-network', 'hi', 'हर सेनापति का अलग सुरक्षित निवास है', 'हनुमान प्रहस्त, महापार्श्व, मेघाकार कुंभकर्ण, विभीषण, महोदर, विरूपाक्ष, इंद्रजित और अनेक अधिकारियों के निवासों में प्रवेश करते हैं। ये नाम केवल सूची नहीं, आदेश-तंत्र हैं—सीता किसी भी अधिकार-क्षेत्र में छिपाई जा सकती हैं और रावण का शासन अपने पहरे तथा संसाधन वाले अनेक घरों में फैला है।'),
  ('scene-hanuman-searches-the-command-houses', 'war-power-sleeps-inside-the-compound', 'en', 'Animals and vehicles are part of the army', 'Near Ravana''s sleeping quarters stand armed formations, swift horses, trained elephants able to meet other elephants, and golden chariots prepared for large forces. Hanuman reads care, training, storage, and deployment behind the display. The coming conflict would face an organised war machine, not decorative beasts parked beside a palace.'),
  ('scene-hanuman-searches-the-command-houses', 'war-power-sleeps-inside-the-compound', 'hi', 'पशु और वाहन भी सेना का भाग हैं', 'रावण के शयन-कक्षों के पास सशस्त्र दल, तीव्र घोड़े, दूसरे हाथियों से लड़ने को प्रशिक्षित हाथी और बड़ी सेनाओं के लिए तैयार स्वर्णिम रथ हैं। हनुमान प्रदर्शन के पीछे देखभाल, प्रशिक्षण, भंडारण और तैनाती पढ़ते हैं। आने वाला संघर्ष महल के पास खड़े सजावटी पशुओं से नहीं, संगठित युद्ध-तंत्र से होगा।'),
  ('scene-hanuman-searches-the-command-houses', 'power-also-builds-pleasure-and-memory', 'en', 'The compound stores more than weapons', 'Grottos, picture galleries, sporting rooms, peacock spaces, treasure chambers, flags, gems, music, and day retreats fill the inner compound. People actively protect and maintain these places. Ravana''s power sustains beauty, leisure, memory, and appetite as well as violence, making the world Hanuman enters richer and harder to judge than a bare military camp.'),
  ('scene-hanuman-searches-the-command-houses', 'power-also-builds-pleasure-and-memory', 'hi', 'परिसर में केवल अस्त्र नहीं रखे हैं', 'गुफानुमा कक्ष, चित्रशालाएँ, क्रीड़ा-स्थल, मोरों के प्रांगण, खजाने, ध्वज, रत्न, संगीत और दिन के विश्राम-कक्ष भीतरी परिसर भरते हैं। लोग इन स्थानों की सक्रिय रक्षा और देखभाल करते हैं। रावण की शक्ति हिंसा के साथ सौंदर्य, अवकाश, स्मृति और इच्छा भी चलाती है, इसलिए हनुमान का संसार साधारण सैन्य शिविर से अधिक समृद्ध और कठिन है।'),
  ('scene-hanuman-searches-the-command-houses', 'the-search-crosses-into-the-inner-palace', 'en', 'Every cleared house points inward', 'After circling the surrounding mansions and finding no Sita, Hanuman reaches Ravana''s own central residence. Bangles, drums, closely packed halls, fragrant drink vessels, guarded enclosures, beds, and seats announce a private world beyond public command. Crossing this threshold may finally bring him near the captive, but it also raises the cost of looking.'),
  ('scene-hanuman-searches-the-command-houses', 'the-search-crosses-into-the-inner-palace', 'hi', 'हर खोजा घर भीतर की ओर संकेत करता है', 'आसपास के निवासों को खोजकर भी सीता न मिलने पर हनुमान रावण के केंद्रीय घर तक पहुँचते हैं। कंगन, ढोल, पास-पास बने कक्ष, सुगंधित पेय-पात्र, सुरक्षित घेरे, शय्या और आसन सार्वजनिक आदेश के पार निजी संसार का संकेत देते हैं। यह सीमा उन्हें बंदिनी के निकट ला सकती है, पर देखने की नैतिक कीमत भी बढ़ाती है।'),
  ('scene-palace-becomes-a-sky-world', 'architecture-imitates-the-heavens', 'en', 'The palace tries to contain the sky', 'Golden windows, blue stone, silver forms, high towers, conchs, bows, clouds of reflected light, and rooms arranged by exact aesthetic rules make the palace appear lifted out of heaven. Hanuman must navigate a built illusion in which ceilings read as sky and upper chambers as mountain summits, while real guards remain embedded in the spectacle.'),
  ('scene-palace-becomes-a-sky-world', 'architecture-imitates-the-heavens', 'hi', 'महल आकाश को अपने भीतर समेटना चाहता है', 'स्वर्णिम खिड़कियाँ, नीला पत्थर, रजत आकृतियाँ, ऊँचे बुर्ज, शंख, धनुष, प्रतिबिंबित प्रकाश के बादल और सटीक सौंदर्य-विन्यास वाले कक्ष महल को स्वर्ग से उठाया हुआ दिखाते हैं। हनुमान ऐसे निर्मित भ्रम में चलते हैं जहाँ छत आकाश और ऊपरी कक्ष पर्वत-शिखर लगते हैं, जबकि वास्तविक प्रहरी उसी दृश्य में छिपे हैं।'),
  ('scene-palace-becomes-a-sky-world', 'splendour-records-conquest', 'en', 'Possession is written into the beauty', 'The structures are praised as flawless and worthy of divine builders, yet their place inside Ravana''s compound ties craft to acquisition by power. Hanuman does not need to deny their beauty to recognise that magnificence can be accumulated through conquest. The palace is both an achievement of makers and a display controlled by the conqueror.'),
  ('scene-palace-becomes-a-sky-world', 'splendour-records-conquest', 'hi', 'सौंदर्य के भीतर अधिकार का इतिहास लिखा है', 'संरचनाएँ निर्दोष और दिव्य शिल्पियों के योग्य लगती हैं, फिर भी रावण के परिसर में उनका स्थान सौंदर्य को शक्ति से किए अधिग्रहण से जोड़ता है। हनुमान को यह मानने के लिए उनकी सुंदरता नकारनी नहीं पड़ती कि वैभव विजय से भी जमा हो सकता है। महल निर्माताओं की उपलब्धि भी है और विजेता के नियंत्रण का प्रदर्शन भी।'),
  ('scene-palace-becomes-a-sky-world', 'pushpaka-contains-a-miniature-world', 'en', 'A vehicle contains hills, forests, and water', 'Hanuman finds Pushpaka filled with model hills, flowering trees, white residences, lotus pools, streams, jewelled birds, metal serpents, crafted horses, elephants, and a figure of Lakshmi. It is less a carriage than a portable world, compressing landscapes and living forms into an object designed to move under command.'),
  ('scene-palace-becomes-a-sky-world', 'pushpaka-contains-a-miniature-world', 'hi', 'एक वाहन में पहाड़, वन और जल समाए हैं', 'हनुमान पुष्पक में लघु पहाड़, पुष्पित वृक्ष, श्वेत निवास, कमल-ताल, धाराएँ, रत्न-पक्षी, धातु-सर्प, निर्मित घोड़े, हाथी और लक्ष्मी की आकृति देखते हैं। वह रथ से अधिक चलायमान संसार है, जो भू-दृश्यों और जीवित रूपों को आदेश पर चलने वाली वस्तु में समेटता है।'),
  ('scene-palace-becomes-a-sky-world', 'wonder-cannot-complete-the-mission', 'en', 'The greatest marvel still contains no answer', 'Hanuman circles the hills, pools, birds, forests, and radiant chambers in astonishment, then checks the result that matters: Janaka''s distressed daughter is not there. The palace can keep expanding the scale of wonder, but every marvel without Sita becomes another beautiful dead end. His disciplined character turns awe back into grief and continued search.'),
  ('scene-palace-becomes-a-sky-world', 'wonder-cannot-complete-the-mission', 'hi', 'सबसे बड़ा चमत्कार भी उत्तर नहीं देता', 'हनुमान विस्मय में पहाड़ों, तालों, पक्षियों, वनों और चमकते कक्षों का चक्कर लगाते हैं, फिर वह परिणाम जाँचते हैं जो महत्त्वपूर्ण है—जनक की पीड़ित पुत्री वहाँ नहीं हैं। महल विस्मय का विस्तार बढ़ा सकता है, पर सीता के बिना हर चमत्कार सुंदर बंद रास्ता है। उनका अनुशासन आश्चर्य को फिर दुःख और जारी खोज में बदल देता है।'),
  ('scene-pushpaka-holds-impossible-craft', 'no-part-of-pushpaka-is-careless', 'en', 'Every surface carries deliberate skill', 'Burnished gold windows, jewel-like joints, sculpted figures, spring flowers, mountain-like chambers, and forms praised as the height of Vishvakarma''s art leave no careless surface on Pushpaka. Hanuman studies workmanship rather than treating splendour as magic without makers. The vehicle''s wonder begins in accumulated knowledge, labour, material, and design.'),
  ('scene-pushpaka-holds-impossible-craft', 'no-part-of-pushpaka-is-careless', 'hi', 'हर सतह सोच-समझकर रची गई है', 'चमकती स्वर्ण खिड़कियाँ, रत्न-जैसे जोड़, गढ़ी आकृतियाँ, वसंत-पुष्प, पर्वत-समान कक्ष और विश्वकर्मा की कला की पराकाष्ठा कहे गए रूप पुष्पक की कोई सतह लापरवाह नहीं छोड़ते। हनुमान वैभव को बिना निर्माता का जादू मानने के बजाय शिल्प पढ़ते हैं। वाहन का चमत्कार ज्ञान, श्रम, सामग्री और रचना से शुरू होता है।'),
  ('scene-pushpaka-holds-impossible-craft', 'the-vehicle-follows-desire', 'en', 'Movement answers the master''s wish', 'Pushpaka can rise into the sky, travel with the speed of wind, change its course, and repair wherever its owner wishes to go. That responsiveness turns a crafted landscape into an instrument of reach. The same quality that makes flight marvellous also lets one ruler extend presence, appetite, and force beyond ordinary distance.'),
  ('scene-pushpaka-holds-impossible-craft', 'the-vehicle-follows-desire', 'hi', 'गति स्वामी की इच्छा मानती है', 'पुष्पक आकाश में उठ सकता है, पवन की गति से चल सकता है, मार्ग बदल सकता है और जहाँ स्वामी चाहे वहाँ पहुँच सकता है। यह आज्ञाकारिता निर्मित भू-दृश्य को पहुँच के साधन में बदलती है। जो गुण उड़ान को अद्भुत बनाता है, वही एक शासक की उपस्थिति, इच्छा और शक्ति को सामान्य दूरी से बहुत आगे ले जाता है।'),
  ('scene-pushpaka-holds-impossible-craft', 'beauty-and-control-remain-together', 'en', 'The marvel cannot be separated from its command', 'Thousands of swift attendants bear the aerial vehicle while its flowering surfaces promise comfort, delight, and freedom of movement. Hanuman does not yet know every transfer in its history, but he can see that wonder is organised around obedience. To understand Pushpaka fully, he must learn who made it, who earned it, and who seized it.'),
  ('scene-pushpaka-holds-impossible-craft', 'beauty-and-control-remain-together', 'hi', 'चमत्कार को उसके नियंत्रण से अलग नहीं किया जा सकता', 'हजारों तीव्र सेवक आकाश-वाहन को सँभालते हैं, जबकि उसकी पुष्पित सतहें आराम, आनंद और निर्बाध गति का वादा करती हैं। हनुमान अभी उसके हर हस्तांतरण का इतिहास नहीं जानते, पर देख सकते हैं कि विस्मय आज्ञाकारिता के चारों ओर संगठित है। पुष्पक को समझने के लिए जानना होगा कि उसे किसने बनाया, किसने पाया और किसने छीना।'),
  ('scene-inner-palace-reveals-power-and-captivity', 'the-private-complex-is-a-city-within-lanka', 'en', 'Another guarded world begins inside', 'Within the already immense palace, Hanuman finds a broad residence of many buildings, common halls, protected apartments, three- and four-tusked elephants, and armed defenders. Ravana''s private domain is not one bedroom but a city within the city. The scale explains how a captive might remain hidden even after the outer palace has been searched.'),
  ('scene-inner-palace-reveals-power-and-captivity', 'the-private-complex-is-a-city-within-lanka', 'hi', 'भीतर एक और सुरक्षित संसार शुरू होता है', 'पहले से विशाल महल के भीतर हनुमान अनेक भवनों, साझा सभागारों, सुरक्षित कक्षों, तीन और चार दाँत वाले हाथियों तथा सशस्त्र रक्षकों वाला विस्तृत निवास पाते हैं। रावण का निजी क्षेत्र एक शयन-कक्ष नहीं, नगर के भीतर दूसरा नगर है। यही विस्तार बताता है कि बाहरी महल खोजे जाने के बाद भी बंदिनी कैसे छिपी रह सकती है।'),
  ('scene-inner-palace-reveals-power-and-captivity', 'choice-and-captivity-share-the-halls', 'en', 'Not everyone arrived under the same conditions', 'Hanuman encounters Ravana''s wives alongside princesses explicitly brought from defeated households. Later appearances suggest affection and chosen attachment among some residents, but those relationships cannot erase the captives or speak for them. The palace contains marriage, loyalty, dependence, performance, political transfer, and coercion in conditions that must not be merged into one story of consent.'),
  ('scene-inner-palace-reveals-power-and-captivity', 'choice-and-captivity-share-the-halls', 'hi', 'हर व्यक्ति एक जैसी परिस्थिति में यहाँ नहीं आया', 'हनुमान रावण की पत्नियों के साथ पराजित घरानों से स्पष्ट रूप से लाई गई राजकुमारियों को भी देखते हैं। आगे कुछ निवासियों में स्नेह और चुना हुआ लगाव दिखाई देता है, पर वे संबंध बंदियों को मिटा नहीं सकते और उनकी ओर से बोल नहीं सकते। महल में विवाह, निष्ठा, निर्भरता, प्रदर्शन, राजनीतिक हस्तांतरण और बलप्रयोग साथ हैं; इन्हें सहमति की एक कथा में नहीं मिलाया जा सकता।'),
  ('scene-inner-palace-reveals-power-and-captivity', 'pushpaka-passes-from-maker-to-conqueror', 'en', 'The vehicle''s ownership trail is revealed', 'The palace reveals that Vishvakarma built Pushpaka for Brahma, Kubera obtained it through austerity, and Ravana took it after defeating Kubera. The sequence distinguishes making, receiving, and seizing. Pushpaka''s beauty remains real, but its current location is also evidence of Ravana converting victory over a relative into permanent command of another''s power.'),
  ('scene-inner-palace-reveals-power-and-captivity', 'pushpaka-passes-from-maker-to-conqueror', 'hi', 'वाहन के स्वामित्व की राह सामने आती है', 'महल बताता है कि विश्वकर्मा ने पुष्पक ब्रह्मा के लिए बनाया, कुबेर ने तप से उसे पाया और रावण ने कुबेर को हराकर छीन लिया। यह क्रम निर्माण, प्राप्ति और बलपूर्वक अधिकार को अलग रखता है। पुष्पक की सुंदरता वास्तविक है, पर उसका वर्तमान स्थान यह भी दिखाता है कि रावण ने संबंधी पर विजय को दूसरे की शक्ति पर स्थायी आदेश में बदल दिया।'),
  ('scene-inner-palace-reveals-power-and-captivity', 'fragrance-draws-the-scout-inward', 'en', 'The air points toward Ravana', 'Food, drink, sandalwood, incense, flowers, and warm interior air combine into a scent trail leading from Pushpaka toward Ravana''s sleeping apartment. Hanuman follows a sensory clue instead of a marked corridor. The palace seems to welcome the senses even while guards and ownership make the invitation dangerous.'),
  ('scene-inner-palace-reveals-power-and-captivity', 'fragrance-draws-the-scout-inward', 'hi', 'सुगंधित हवा रावण की दिशा बताती है', 'भोजन, पेय, चंदन, धूप, फूल और भीतर की गरम हवा मिलकर पुष्पक से रावण के शयन-कक्ष तक सुगंध की राह बनाते हैं। हनुमान चिह्नित गलियारे के बजाय इंद्रिय-संकेत का अनुसरण करते हैं। महल इंद्रियों का स्वागत करता लगता है, जबकि पहरा और स्वामित्व उस निमंत्रण को खतरनाक बनाते हैं।'),
  ('scene-inner-palace-reveals-power-and-captivity', 'the-sleeping-hall-overwhelms-the-senses', 'en', 'The chamber shines brighter than its lamps', 'Crystal terraces, jewelled stairs, ivory, coral, pearl, gold, fragrant smoke, white surfaces, patterned carpets, and steady lamps make the sleeping hall feel like heaven lowered into a private room. Hanuman briefly wonders whether he has entered a divine city. The sensory excess can disorient a scout as effectively as a weapon.'),
  ('scene-inner-palace-reveals-power-and-captivity', 'the-sleeping-hall-overwhelms-the-senses', 'hi', 'कक्ष अपने दीपों से अधिक चमकता है', 'स्फटिक छतें, रत्न-जड़ी सीढ़ियाँ, हाथीदाँत, मूँगा, मोती, सोना, सुगंधित धुआँ, श्वेत सतहें, चित्रित कालीन और स्थिर दीप शयन-कक्ष को निजी कमरे में उतरे स्वर्ग जैसा बनाते हैं। हनुमान क्षण भर सोचते हैं कि क्या वे किसी दिव्य नगर में आ गए। इंद्रियों की अधिकता गुप्तचर को अस्त्र जितना भ्रमित कर सकती है।'),
  ('scene-inner-palace-reveals-power-and-captivity', 'sleep-does-not-make-people-scenery', 'en', 'Resting bodies remain private lives', 'Thousands of women rest after music, dance, drink, conversation, and fatigue, with wreaths, ornaments, scarves, and instruments displaced by sleep. Their closeness shows companionship among some; it does not make them decorations for Ravana or for the scout. Hanuman must identify Sita without turning unconscious people, who cannot notice or answer his gaze, into spectacle.'),
  ('scene-inner-palace-reveals-power-and-captivity', 'sleep-does-not-make-people-scenery', 'hi', 'सोते शरीर अब भी निजी जीवन हैं', 'संगीत, नृत्य, पेय, बातचीत और थकान के बाद हजारों स्त्रियाँ सो रही हैं; नींद से मालाएँ, आभूषण, दुपट्टे और वाद्य अपनी जगह से खिसक गए हैं। कुछ की निकटता आपसी साथ दिखाती है; इससे वे रावण या गुप्तचर की सजावट नहीं बनतीं। हनुमान को ऐसे अचेत लोगों को तमाशा बनाए बिना सीता पहचाननी है जो उनकी दृष्टि जान या उसका उत्तर नहीं दे सकते।'),
  ('scene-inner-palace-reveals-power-and-captivity', 'luxury-cannot-settle-consent', 'en', 'The palace gives incompatible testimony', 'Some sleeping residents appear attached to Ravana and secure in their place; others were named as princesses brought by force. A claim that everyone came willingly conflicts with the captive routes Hanuman has already seen. He cannot resolve that contradiction by choosing the version more flattering to power, and he cannot identify Sita merely by assuming every other person is content.'),
  ('scene-inner-palace-reveals-power-and-captivity', 'luxury-cannot-settle-consent', 'hi', 'महल विरोधी गवाही देता है', 'कुछ सोती निवासी रावण से जुड़ी और अपने स्थान में सुरक्षित दिखती हैं; अन्य स्पष्ट रूप से बलपूर्वक लाई गई राजकुमारियाँ हैं। सबके स्वेच्छा से आने का दावा उन बंदी मार्गों से टकराता है जिन्हें हनुमान देख चुके हैं। वे सत्ता को अच्छा दिखाने वाले रूप को चुनकर विरोध नहीं मिटा सकते और यह मानकर सीता नहीं पहचान सकते कि बाकी सब संतुष्ट हैं।'),
  ('scene-mandodari-is-mistaken-for-sita', 'ravana-sleeps-inside-the-history-of-force', 'en', 'The sleeping ruler still carries past battles', 'Hanuman finds Ravana asleep beneath a white canopy, dressed in gold-threaded cloth and red sandal, breathing heavily on a jewelled bed. Scars and remembered wounds from elephant tusks, Indra''s weapon, and Vishnu''s discus mark the powerful arms stretched beside him. Sleep pauses action but does not erase the history of force concentrated in the room.'),
  ('scene-mandodari-is-mistaken-for-sita', 'ravana-sleeps-inside-the-history-of-force', 'hi', 'सोते शासक पर भी पुराने युद्ध लिखे हैं', 'हनुमान रावण को श्वेत छत्र के नीचे, स्वर्ण-तंतु वस्त्र और लाल चंदन में, रत्न-जड़ी शय्या पर भारी साँस लेते सोया पाते हैं। पास फैली शक्तिशाली भुजाओं पर हाथी-दाँत, इंद्र के अस्त्र और विष्णु के चक्र से जुड़े पुराने घाव हैं। नींद कार्रवाई रोकती है, पर कक्ष में केंद्रित शक्ति का इतिहास नहीं मिटाती।'),
  ('scene-mandodari-is-mistaken-for-sita', 'proximity-does-not-make-the-ruler-safe', 'en', 'Hanuman recoils before he studies', 'The sudden proximity to the ruler he crossed the sea to oppose makes Hanuman shrink back to the stairs. He steadies himself on a middle landing and watches rather than attacking a sleeping enemy or fleeing in panic. The moment tests whether the mission remains a search for Sita instead of becoming an impulsive chance to strike Ravana.'),
  ('scene-mandodari-is-mistaken-for-sita', 'proximity-does-not-make-the-ruler-safe', 'hi', 'अध्ययन से पहले हनुमान पीछे हटते हैं', 'समुद्र पार जिस शासक का विरोध करने आए, उसके अचानक इतने निकट पहुँचकर हनुमान सीढ़ियों तक पीछे हटते हैं। वे बीच की चौकी पर स्वयं को स्थिर करके देखते हैं; न सोते शत्रु पर अचानक वार करते हैं, न भय में भागते हैं। यह क्षण जाँचता है कि अभियान सीता की खोज रहता है या रावण पर प्रहार का आवेग बन जाता है।'),
  ('scene-mandodari-is-mistaken-for-sita', 'artists-sleep-beside-their-instruments', 'en', 'The night''s performers rest with their craft', 'Around the chamber, dancers and musicians sleep beside vina, mridanga, panava, dindima, water vessels, and other instruments, some still holding the tools used through the night. The arrangement reveals skilled work and exhausted bodies, not a decorative ring around the ruler. Their instruments preserve individual roles even while sleep quiets the performance.'),
  ('scene-mandodari-is-mistaken-for-sita', 'artists-sleep-beside-their-instruments', 'hi', 'रात की कलाकार अपने वाद्यों के पास विश्राम करती हैं', 'कक्ष के आसपास नर्तकियाँ और संगीतकार वीणा, मृदंग, पणव, डिंडिम, जल-पात्र तथा अन्य वाद्यों के पास सो रही हैं; कुछ अब भी रात भर उपयोग किए उपकरण पकड़े हैं। यह विन्यास कुशल काम और थके शरीर दिखाता है, शासक के चारों ओर सजावट नहीं। नींद प्रदर्शन शांत करती है, पर वाद्य हर व्यक्ति की भूमिका बचाए रखते हैं।'),
  ('scene-mandodari-is-mistaken-for-sita', 'mandodari-has-her-own-place', 'en', 'Mandodari is not an unnamed beautiful figure', 'Apart from the larger group rests Mandodari, radiant with gold and jewels and recognised as mistress of the inner apartment. Her separate bed and authority distinguish her before Hanuman names her correctly. She belongs to this palace in a role of her own; resemblance to Rama''s description cannot erase her identity or make her a placeholder for Sita.'),
  ('scene-mandodari-is-mistaken-for-sita', 'mandodari-has-her-own-place', 'hi', 'मंदोदरी कोई अनाम सुंदर आकृति नहीं हैं', 'बड़े समूह से अलग मंदोदरी स्वर्ण और रत्नों से दीप्त, भीतरी कक्ष की स्वामिनी के रूप में विश्राम कर रही हैं। हनुमान उन्हें सही नाम दें, उससे पहले ही अलग शय्या और अधिकार उनका विशिष्ट स्थान दिखाते हैं। वे इस महल में अपनी भूमिका वाली व्यक्ति हैं; राम के वर्णन से समानता उनकी पहचान मिटाकर उन्हें सीता का स्थानापन्न नहीं बना सकती।'),
  ('scene-mandodari-is-mistaken-for-sita', 'hope-celebrates-before-evidence', 'en', 'Hanuman mistakes relief for recognition', 'Seeing Mandodari''s beauty and ornaments, Hanuman abruptly decides she must be Sita. Relief bursts through discipline: he strikes his arms, kisses his tail, sings, climbs pillars, and jumps down in exuberant joy. The comic release remains real, but so does the error. He has matched the person he needs to find before checking her circumstances.'),
  ('scene-mandodari-is-mistaken-for-sita', 'hope-celebrates-before-evidence', 'hi', 'हनुमान राहत को पहचान समझ लेते हैं', 'मंदोदरी की सुंदरता और आभूषण देखकर हनुमान अचानक मान लेते हैं कि यही सीता हैं। राहत अनुशासन तोड़ देती है—वे भुजाएँ थपथपाते, पूँछ चूमते, गाते, स्तंभों पर चढ़ते और आनंद में नीचे कूदते हैं। यह हास्यपूर्ण राहत सच है, पर भूल भी सच है। उन्होंने परिस्थिति जाँचे बिना सामने की व्यक्ति को अपने आवश्यक उत्तर से मिला दिया है।'),
  ('scene-hanuman-tests-his-own-search', 'mandodaris-circumstances-break-the-match', 'en', 'The first conclusion cannot survive context', 'Hanuman regains calm and tests the joyful identification against Sita''s known situation. A woman resting adorned beside Ravana, secure as mistress of his inner apartment, cannot simply be assumed to be the captive who resists him and longs for Rama. The correction arises from circumstances, not from ranking one woman''s beauty or worth above another''s.'),
  ('scene-hanuman-tests-his-own-search', 'mandodaris-circumstances-break-the-match', 'hi', 'पहला निष्कर्ष परिस्थिति के सामने नहीं टिकता', 'हनुमान शांत होकर आनंदपूर्ण पहचान को सीता की ज्ञात स्थिति से परखते हैं। रावण के पास आभूषणों में, भीतरी कक्ष की स्वामिनी की तरह सुरक्षित विश्राम करती स्त्री को केवल इसलिए बंदिनी नहीं माना जा सकता जो उसका विरोध करती और राम के लिए व्याकुल है। सुधार परिस्थिति से आता है, किसी स्त्री की सुंदरता या मूल्य को दूसरी से ऊपर रखने से नहीं।'),
  ('scene-hanuman-tests-his-own-search', 'the-banquet-reconstructs-the-night', 'en', 'Food and drink reveal what happened before sleep', 'The drinking place contains separately prepared meats, sharp and mild dishes, fruit, sweets, curd, salt, natural and mixed wines, golden and crystal vessels, garlands, scattered bracelets, and beds. Hanuman reads cooks, guests, tastes, sequence, and leftovers from the arrangement. Material detail reconstructs a completed court night without requiring anyone asleep to perform it again.'),
  ('scene-hanuman-tests-his-own-search', 'the-banquet-reconstructs-the-night', 'hi', 'भोजन और पेय बीती रात की गतिविधि बताते हैं', 'पेय-कक्ष में अलग पकाए मांस, तीखे और हल्के व्यंजन, फल, मिठाइयाँ, दही, नमक, प्राकृतिक और मिश्रित मदिराएँ, स्वर्ण तथा स्फटिक पात्र, मालाएँ, बिखरे कंगन और शय्याएँ हैं। हनुमान विन्यास से रसोइयों, अतिथियों, स्वादों, क्रम और बचे भोजन को पढ़ते हैं। भौतिक विवरण सोते लोगों से फिर प्रदर्शन कराए बिना बीती दरबारी रात पुनर्निर्मित करता है।'),
  ('scene-hanuman-tests-his-own-search', 'the-performers-carry-knowledge', 'en', 'The hall contains skilled interpretation', 'The resting women are described as musicians, dancers, players, conversationalists, and people able to understand words, season, place, and the meaning of songs. Their knowledge survives intoxication and sleep. Hanuman''s search must recognise skill and social intelligence instead of reducing everyone present to appearance or relationship with Ravana.'),
  ('scene-hanuman-tests-his-own-search', 'the-performers-carry-knowledge', 'hi', 'सभागार में कुशल व्याख्या का ज्ञान है', 'विश्राम करती स्त्रियाँ संगीतकार, नर्तकी, खिलाड़ी, संवादक और शब्द, ऋतु, स्थान तथा गीत का अर्थ समझने वाली जानकार व्यक्तियों के रूप में दिखाई देती हैं। उनका ज्ञान मदिरा और नींद के बाद भी उनका है। हनुमान की खोज को उपस्थित लोगों को रूप या रावण से संबंध तक घटाने के बजाय कौशल और सामाजिक बुद्धि पहचाननी है।'),
  ('scene-hanuman-tests-his-own-search', 'the-searcher-recognises-the-privacy-breach', 'en', 'Necessity does not erase discomfort', 'Hanuman becomes afraid that looking upon sleeping people in a private apartment may violate the discipline he carries for Rama. The fear is not evidence that the sleepers have done anything wrong; it is scrutiny of his own conduct while they cannot consent to observation. He pauses instead of declaring that a rescue mission automatically makes every gaze harmless.'),
  ('scene-hanuman-tests-his-own-search', 'the-searcher-recognises-the-privacy-breach', 'hi', 'आवश्यकता असुविधा को मिटाती नहीं', 'हनुमान डरते हैं कि निजी कक्ष में सोते लोगों को देखना राम के लिए निभाए अनुशासन का उल्लंघन हो सकता है। यह भय सोने वालों की गलती का प्रमाण नहीं; यह उनके अपने आचरण की जाँच है, जब सामने वाले देखने की सहमति नहीं दे सकते। वे यह घोषित करने के बजाय रुकते हैं कि बचाव-अभियान हर दृष्टि को अपने-आप निर्दोष बना देता है।'),
  ('scene-hanuman-tests-his-own-search', 'intention-must-govern-method', 'en', 'A pure goal still requires a disciplined method', 'Hanuman reasons that his mind has not sought pleasure and that a missing woman must sometimes be searched for among women. That explains why he entered; it does not grant limitless inspection. He confines attention to signs relevant to Sita''s identity, refuses to linger, and treats the absence of inward corruption as a responsibility to keep acting carefully.'),
  ('scene-hanuman-tests-his-own-search', 'intention-must-govern-method', 'hi', 'शुद्ध लक्ष्य को भी अनुशासित तरीका चाहिए', 'हनुमान विचार करते हैं कि उनका मन सुख खोजने नहीं आया और लापता स्त्री को कभी-कभी स्त्रियों के बीच ही खोजना पड़ता है। इससे प्रवेश का कारण समझ आता है, असीम निरीक्षण का अधिकार नहीं। वे ध्यान को सीता की पहचान से जुड़े संकेतों तक सीमित रखते, ठहरने से इंकार करते और मन के विचलित न होने को सावधानी बनाए रखने की जिम्मेदारी मानते हैं।'),
  ('scene-hanuman-tests-his-own-search', 'the-scout-leaves-the-private-hall', 'en', 'Ethical review changes the next movement', 'After confirming Sita is not among the sleepers, Hanuman exits the drinking place and searches another quarter with greater care. The self-review matters because it produces action: no false identification, no moral accusation against the residents, no lingering in private space, and no abandonment of the captive. The search becomes narrower, quieter, and more deliberate.'),
  ('scene-hanuman-tests-his-own-search', 'the-scout-leaves-the-private-hall', 'hi', 'नैतिक समीक्षा अगली चाल बदलती है', 'यह निश्चित करके कि सीता सोते लोगों में नहीं हैं, हनुमान पेय-कक्ष से निकलकर अधिक सावधानी से दूसरे क्षेत्र की खोज करते हैं। आत्म-समीक्षा कार्रवाई बदलती है—न गलत पहचान, न निवासियों पर नैतिक आरोप, न निजी स्थान में अनावश्यक ठहराव और न बंदिनी का परित्याग। खोज अधिक संकीर्ण, शांत और सोच-समझकर चलती है।'),
  ('scene-perseverance-reopens-the-map', 'empty-rooms-produce-a-false-certainty', 'en', 'Repeated absence begins to sound like proof', 'Bowers, picture galleries, night rooms, and private chambers yield no Sita. Under accumulated fatigue, Hanuman leaps from ''I have not found her here'' to ''she must be dead,'' imagining Ravana killed her or that terror itself ended her life. The conclusion feels certain because the search hurts, not because the evidence establishes it.'),
  ('scene-perseverance-reopens-the-map', 'empty-rooms-produce-a-false-certainty', 'hi', 'बार-बार की अनुपस्थिति प्रमाण जैसी लगने लगती है', 'कुंज, चित्रशालाएँ, रात्रि-कक्ष और निजी स्थान सीता का पता नहीं देते। जमा थकान में हनुमान ‘वे यहाँ नहीं मिलीं’ से ‘वे अवश्य मर चुकी हैं’ पर पहुँचते हैं और सोचते हैं कि रावण ने उन्हें मारा या भय ने जीवन समाप्त कर दिया। निष्कर्ष निश्चित इसलिए लगता है कि खोज पीड़ा देती है, इसलिए नहीं कि प्रमाण उसे स्थापित करता है।'),
  ('scene-perseverance-reopens-the-map', 'failure-fear-pulls-the-shore-into-lanka', 'en', 'The waiting companions enter his thoughts', 'Hanuman imagines returning across the sea to Sugriva''s deadline, Jambavan''s question, Angada''s hope, and the assembled search party with no answer. Shame tells him that the leap, palace entry, and effort have become worthless. Yet the companions did not ask him to defend his reputation; they asked him to learn the truth about Sita.'),
  ('scene-perseverance-reopens-the-map', 'failure-fear-pulls-the-shore-into-lanka', 'hi', 'प्रतीक्षारत साथी उनके विचारों में आ जाते हैं', 'हनुमान कल्पना करते हैं कि वे सुग्रीव की समय-सीमा, जाम्बवान के प्रश्न, अंगद की आशा और जुटे खोज-दल के पास बिना उत्तर लौटेंगे। लज्जा कहती है कि छलाँग, महल-प्रवेश और पूरा प्रयास व्यर्थ हो गया। पर साथियों ने उनसे प्रतिष्ठा बचाने को नहीं, सीता के बारे में सत्य जानने को कहा था।'),
  ('scene-perseverance-reopens-the-map', 'perseverance-names-the-missing-variable', 'en', 'Energy returns as a better question', 'Hanuman remembers that perseverance produces results only when it changes effort, not when it repeats the same path. He asks which places remain unseen. The question replaces a verdict about Sita with an audit of his own coverage, converting despair from a claim about her fate into information about the search''s unfinished boundary.'),
  ('scene-perseverance-reopens-the-map', 'perseverance-names-the-missing-variable', 'hi', 'ऊर्जा बेहतर प्रश्न बनकर लौटती है', 'हनुमान याद करते हैं कि दृढ़ता तभी फल देती है जब प्रयास बदले, केवल वही मार्ग दोहराए नहीं। वे पूछते हैं कि कौन-से स्थान अब भी नहीं देखे गए। यह प्रश्न सीता पर दिए निर्णय को अपनी खोज की जाँच से बदल देता है और निराशा को उनके भाग्य का दावा नहीं, अधूरी सीमा की जानकारी बनाता है।'),
  ('scene-perseverance-reopens-the-map', 'the-search-covers-every-architectural-layer', 'en', 'Hanuman searches above, below, inside, and between', 'He checks galleries, pleasure structures, garden roads, vehicles, underground chambers, religious buildings, many-storeyed residences, crossings, trees, holes, tanks, raised platforms, and noble houses. He opens and closes doors, rises, drops, enters, exits, and returns. The choreography makes thoroughness spatial rather than a vague claim of looking everywhere.'),
  ('scene-perseverance-reopens-the-map', 'the-search-covers-every-architectural-layer', 'hi', 'हनुमान ऊपर, नीचे, भीतर और बीच सब खोजते हैं', 'वे चित्रशालाएँ, क्रीड़ा-स्थल, उद्यान-मार्ग, वाहन, भूमिगत कक्ष, उपासना-भवन, बहुमंज़िला निवास, चौराहे, वृक्ष, छिद्र, ताल, ऊँचे मंच और कुलीन घर जाँचते हैं। वे द्वार खोलते-बंद करते, ऊपर उठते, नीचे उतरते, भीतर जाते, बाहर आते और लौटते हैं। यह गति ‘हर जगह देखा’ के अस्पष्ट दावे को वास्तविक स्थानिक परिश्रम बनाती है।'),
  ('scene-perseverance-reopens-the-map', 'thoroughness-still-does-not-prove-absence', 'en', 'A nearly complete search remains incomplete', 'Even after inspecting spaces as small as a few fingers across in Ravana''s interior, Hanuman finds captive women from several peoples but not Sita. Sorrow returns, yet the lesson has changed: vast effort can narrow uncertainty without eliminating it. He descends from Pushpaka anxious, carrying a more accurate statement—she is not in the places cleared so far.'),
  ('scene-perseverance-reopens-the-map', 'thoroughness-still-does-not-prove-absence', 'hi', 'लगभग पूरी खोज अब भी अधूरी है', 'रावण के भीतर कुछ अंगुल जितने छोटे स्थानों तक देखने के बाद भी हनुमान कई समुदायों की बंदी स्त्रियाँ पाते हैं, सीता नहीं। दुःख लौटता है, पर सीख बदल चुकी है—विशाल प्रयास अनिश्चितता घटा सकता है, समाप्त नहीं। वे पुष्पक से चिंता में उतरते हैं, पर अधिक सही कथन साथ है—अब तक खोजे स्थानों में वे नहीं मिलीं।'),
  ('scene-despair-yields-to-ashoka-grove', 'sampatis-testimony-conflicts-with-the-empty-map', 'en', 'Reliable testimony and present sight disagree', 'From the wall, Hanuman compares Sampati''s clear testimony that Sita was in Ravana''s domain with a palace map that has produced no trace. Instead of discarding either one immediately, he generates possibilities: she may have fallen during the flight, died under pressure, been killed, remain concealed, or be held somewhere outside the rooms he searched.'),
  ('scene-despair-yields-to-ashoka-grove', 'sampatis-testimony-conflicts-with-the-empty-map', 'hi', 'विश्वसनीय गवाही और वर्तमान दृश्य अलग हैं', 'दीवार पर हनुमान संपाती की स्पष्ट गवाही—सीता रावण के क्षेत्र में थीं—की तुलना ऐसे महल-नक्शे से करते हैं जहाँ कोई संकेत नहीं मिला। वे किसी एक को तुरंत छोड़ने के बजाय संभावनाएँ बनाते हैं—उड़ान में गिरना, दबाव से मृत्यु, हत्या, गुप्त बंदीपन या खोजे कक्षों से बाहर किसी स्थान पर रखा जाना।'),
  ('scene-despair-yields-to-ashoka-grove', 'hanuman-refuses-an-unsupported-report', 'en', 'He cannot call Sita living, dead, or lost without proof', 'Hanuman realises that telling Rama ''I saw her'' would be false, declaring her dead would exceed the evidence, and implying that captivity changed her loyalties would injure her without knowledge. Silence would also abandon the mission. The messenger''s crisis is not lack of words but the absence of a truthful status he can responsibly carry home.'),
  ('scene-despair-yields-to-ashoka-grove', 'hanuman-refuses-an-unsupported-report', 'hi', 'प्रमाण बिना वे सीता को जीवित, मृत या लुप्त नहीं कह सकते', 'हनुमान समझते हैं कि राम से ‘मैंने उन्हें देखा’ कहना झूठ होगा, मृत्यु घोषित करना प्रमाण से आगे जाएगा और बंदीपन से उनकी निष्ठा बदलने का संकेत बिना ज्ञान उन्हें चोट पहुँचाएगा। मौन भी अभियान छोड़ देगा। दूत का संकट शब्दों की कमी नहीं, ऐसी सत्य स्थिति का अभाव है जिसे जिम्मेदारी से घर ले जाया जा सके।'),
  ('scene-despair-yields-to-ashoka-grove', 'one-failure-message-becomes-a-catastrophe', 'en', 'Fear imagines grief spreading through every bond', 'His mind races through an escalating chain: Rama collapses under the news, Lakshmana follows his brother''s grief, their family breaks, Sugriva and Tara lose hope, Angada loses another generation, and the search party destroys itself in despair. The imagined cascade shows the weight Hanuman feels, but fear is forecasting the worst—not reporting what has happened.'),
  ('scene-despair-yields-to-ashoka-grove', 'one-failure-message-becomes-a-catastrophe', 'hi', 'भय हर संबंध में फैलते शोक की कल्पना करता है', 'उनका मन बढ़ती शृंखला में दौड़ता है—समाचार से राम टूटते हैं, लक्ष्मण भाई के शोक में जाते हैं, परिवार बिखरता है, सुग्रीव और तारा आशा खोते हैं, अंगद एक और पीढ़ी खोते हैं और खोज-दल निराशा में स्वयं को नष्ट करता है। यह कल्पित क्रम हनुमान का भार दिखाता है, पर भय सबसे बुरा भविष्य बना रहा है, घटी घटना नहीं बता रहा।'),
  ('scene-despair-yields-to-ashoka-grove', 'despair-offers-disappearance-as-an-answer', 'en', 'Hanuman imagines never returning', 'Unable to bear the report, Hanuman considers disappearing from the mission, abandoning the return, or ending his own life. These thoughts are the language of acute despair, not a solution the journey endorses. Disappearing would preserve temporary hope on the far shore while permanently removing the only witness able to continue the search.'),
  ('scene-despair-yields-to-ashoka-grove', 'despair-offers-disappearance-as-an-answer', 'hi', 'हनुमान कभी न लौटने की कल्पना करते हैं', 'समाचार सह न पाने पर हनुमान अभियान से गायब हो जाने, लौटना छोड़ देने या जीवन समाप्त करने की कल्पना करते हैं। ये तीव्र निराशा की भाषा हैं, यात्रा द्वारा समर्थित समाधान नहीं। उनका गायब होना दूसरे तट पर थोड़ी देर आशा रखेगा, पर खोज जारी रखने वाले एकमात्र साक्षी को स्थायी रूप से हटा देगा।'),
  ('scene-despair-yields-to-ashoka-grove', 'life-preserves-the-next-action', 'en', 'Remaining alive becomes a mission decision', 'Hanuman interrupts the spiral with a practical insight: self-destruction creates incalculable harm, while life leaves open the possibility of good. He chooses to maintain himself. This is not a sudden disappearance of grief; it is a narrow decision that the next useful action requires a living, observing, moving messenger.'),
  ('scene-despair-yields-to-ashoka-grove', 'life-preserves-the-next-action', 'hi', 'जीवित रहना अभियान का निर्णय बनता है', 'हनुमान व्यावहारिक समझ से विचार-चक्र रोकते हैं—आत्म-विनाश अपार हानि पैदा करेगा, जबकि जीवन भलाई की संभावना खुली रखता है। वे स्वयं को जीवित रखने का निर्णय लेते हैं। दुःख अचानक नहीं मिटता; केवल इतना तय होता है कि अगली उपयोगी कार्रवाई के लिए जीवित, देखने और चलने वाला दूत आवश्यक है।'),
  ('scene-despair-yields-to-ashoka-grove', 'attack-is-another-premature-escape', 'en', 'Violence briefly offers a false shortcut', 'Energy returns first as an impulse to kill Ravana or drag him across the sea to Rama. The fantasy would convert helplessness into action, but it still would not establish where Sita is or whether an attack would endanger her. Hanuman lets the thought pass and returns to the actual unsolved task rather than mistaking revenge for rescue.'),
  ('scene-despair-yields-to-ashoka-grove', 'attack-is-another-premature-escape', 'hi', 'हिंसा क्षण भर झूठा छोटा रास्ता देती है', 'ऊर्जा पहले रावण को मारने या समुद्र पार घसीटकर राम के पास ले जाने के आवेग में लौटती है। कल्पना असहायता को कार्रवाई में बदलती, पर यह नहीं बताती कि सीता कहाँ हैं या आक्रमण उन्हें संकट में डालेगा। हनुमान विचार को जाने देते हैं और प्रतिशोध को बचाव समझने के बजाय असली अनसुलझे काम पर लौटते हैं।'),
  ('scene-despair-yields-to-ashoka-grove', 'the-unsearched-grove-breaks-the-loop', 'en', 'One green space remains outside the cleared map', 'Hanuman finally notices the extensive Ashoka grove, a protected landscape he has not entered. That single omission breaks the repeated search loop. A captive may be isolated away from households, command rooms, revelry, and royal beds; the grove is not merely another location but a new hypothesis about how Ravana keeps Sita apart.'),
  ('scene-despair-yields-to-ashoka-grove', 'the-unsearched-grove-breaks-the-loop', 'hi', 'खोजे नक्शे के बाहर एक हरा स्थान बचा है', 'हनुमान अंततः विस्तृत अशोक-वाटिका देखते हैं—एक सुरक्षित भू-दृश्य जहाँ वे गए ही नहीं। यही एक छूटा स्थान दोहराती खोज का चक्र तोड़ता है। बंदिनी को घरों, आदेश-कक्षों, उत्सव और राजकीय शय्याओं से अलग रखा जा सकता है; वाटिका केवल नया स्थान नहीं, रावण द्वारा सीता को अलग रखने की नई परिकल्पना है।'),
  ('scene-despair-yields-to-ashoka-grove', 'prayer-and-smallness-prepare-entry', 'en', 'Hanuman enters the grove first in thought', 'He bows to Rama, Lakshmana, Sita, Wind, the Sun, Moon, Fire, Indra, Varuna, the Maruts, and all beings who may aid the path. Then he studies guards, sacred boundaries, trees, and airflow and contracts his body again so Ravana will not see him. Mental rehearsal turns recovered hope into a controlled entry plan.'),
  ('scene-despair-yields-to-ashoka-grove', 'prayer-and-smallness-prepare-entry', 'hi', 'हनुमान पहले मन में वाटिका में प्रवेश करते हैं', 'वे राम, लक्ष्मण, सीता, पवन, सूर्य, चंद्र, अग्नि, इंद्र, वरुण, मरुतों और मार्ग में सहायता कर सकने वाले सभी प्राणियों को प्रणाम करते हैं। फिर प्रहरी, पवित्र सीमाएँ, वृक्ष और हवा की चाल देखकर शरीर फिर छोटा करते हैं ताकि रावण उन्हें न देखे। मानसिक अभ्यास लौटी आशा को नियंत्रित प्रवेश-योजना बनाता है।'),
  ('scene-hanuman-waits-in-shimshapa', 'the-entry-wakes-the-grove', 'en', 'A hidden scout still disturbs living things', 'Hanuman leaps from the palace wall into a grove resonant with birds, bees, peacocks, animals, flowers, and fruit. His arrival wakes sleepers and sends wings beating upward. Blossoms fall over him until creatures mistake the flower-covered moving figure for spring itself. Stealth from guards does not mean invisibility to the grove''s inhabitants.'),
  ('scene-hanuman-waits-in-shimshapa', 'the-entry-wakes-the-grove', 'hi', 'छिपा गुप्तचर भी जीवित संसार को विचलित करता है', 'हनुमान महल की दीवार से पक्षियों, भौंरों, मोरों, पशुओं, फूलों और फलों से गूँजती वाटिका में कूदते हैं। उनका आगमन सोते जीवों को जगाकर पंखों को ऊपर उड़ा देता है। फूल उन पर इतने गिरते हैं कि जीव फूलों से ढकी चलती आकृति को वसंत समझते हैं। प्रहरियों से छिपना वाटिका के निवासियों के लिए अदृश्य होना नहीं है।'),
  ('scene-hanuman-waits-in-shimshapa', 'speed-leaves-visible-damage', 'en', 'The searcher''s force strips the trees', 'As Hanuman darts through branches, trees shed fruit, flowers, leaves, and frightened birds; some tops tear and shrubs scatter under tail, hands, and feet. The grove''s beauty does not reset behind him. Like Mahendra at launch, this living place records the cost of heroic movement and pressures him to stop treating speed as the only form of urgency.'),
  ('scene-hanuman-waits-in-shimshapa', 'speed-leaves-visible-damage', 'hi', 'खोजी का वेग वृक्षों को क्षति पहुँचाता है', 'हनुमान शाखाओं में दौड़ते हैं तो वृक्ष फल, फूल, पत्ते और भयभीत पक्षी खोते हैं; कुछ शिखर फटते और झाड़ियाँ पूँछ, हाथ तथा पैरों से बिखरती हैं। पीछे वाटिका की सुंदरता अपने-आप ठीक नहीं होती। प्रस्थान के महेंद्र की तरह यह जीवित स्थान वीर गति की कीमत दर्ज करता और उन्हें वेग को ही तात्कालिकता मानना छोड़ने को बाध्य करता है।'),
  ('scene-hanuman-waits-in-shimshapa', 'the-grove-is-engineered-and-alive', 'en', 'Nature and royal design occupy the same ground', 'Jewelled and silver pavements, crystal-bottomed pools, pearl and coral sand, golden trees, lotus ponds, swans, water birds, creeper windows, artificial forests, and cool clear water reveal extensive design. Yet living birds, animals, roots, seasonal flowers, and flowing water keep exceeding the plan. The grove is neither untouched wilderness nor lifeless palace decoration.'),
  ('scene-hanuman-waits-in-shimshapa', 'the-grove-is-engineered-and-alive', 'hi', 'प्रकृति और राजकीय रचना एक ही भूमि पर हैं', 'रत्न और रजत पथ, स्फटिक-तल वाले ताल, मोती-मूँगे की रेत, स्वर्ण वृक्ष, कमल-सर, हंस, जल-पक्षी, लता-झरोखे, कृत्रिम वन और शीतल स्वच्छ जल विस्तृत रचना दिखाते हैं। फिर भी जीवित पक्षी, पशु, जड़ें, ऋतु-पुष्प और बहता जल योजना से आगे बढ़ते हैं। वाटिका न अछूता वन है, न निर्जीव महल-सजावट।'),
  ('scene-hanuman-waits-in-shimshapa', 'mountain-and-river-create-a-hidden-route', 'en', 'The garden contains its own geography', 'A cloud-like mountain rises inside the grove with caves, wooded slopes, a falling river, branches touching the stream, turning water, and ponds farther below. Hanuman reads height, cover, water access, and repeated paths. A person held apart from the palace could move within this miniature geography without appearing in any room he searched.'),
  ('scene-hanuman-waits-in-shimshapa', 'mountain-and-river-create-a-hidden-route', 'hi', 'उद्यान की अपनी भूगोल है', 'वाटिका के भीतर मेघ-समान पर्वत गुफाओं, वनाच्छादित ढलानों, गिरती नदी, जल छूती शाखाओं, मुड़ती धारा और नीचे तालों के साथ उठता है। हनुमान ऊँचाई, आड़, जल-प्रवेश और दोहराए मार्ग पढ़ते हैं। महल से अलग रखी व्यक्ति इस लघु भूगोल में चल सकती है और खोजे किसी कक्ष में दिखाई न दे।'),
  ('scene-hanuman-waits-in-shimshapa', 'the-golden-shimshapa-becomes-a-hide', 'en', 'Hanuman chooses one tree and finally stops', 'Near the ponds stands a golden shimshapa surrounded by bright pavements and chiming trees. Hanuman climbs into its dense leaves and lets the landscape conceal him instead of forcing a path through it. The shift from constant motion to one chosen vantage point is the search''s most important change in method.'),
  ('scene-hanuman-waits-in-shimshapa', 'the-golden-shimshapa-becomes-a-hide', 'hi', 'हनुमान एक वृक्ष चुनकर अंततः रुकते हैं', 'तालों के पास चमकते पथों और झंकारते वृक्षों से घिरा स्वर्णिम शीशम खड़ा है। हनुमान उसकी घनी पत्तियों में चढ़कर भू-दृश्य को चीरने के बजाय उससे स्वयं को छिपाने देते हैं। लगातार गति से एक चुने दृष्टि-बिंदु पर रुकना खोज की पद्धति का सबसे महत्त्वपूर्ण परिवर्तन है।'),
  ('scene-hanuman-waits-in-shimshapa', 'routine-becomes-the-final-hypothesis', 'en', 'He waits where Sita may choose to come', 'Hanuman remembers Sita''s love of forests, birds, animals, garden walking, morning observance, and pure water. If she is alive and held nearby, she may come to the river or pond at dawn, grieving for Rama yet following a familiar rhythm. He hides, watches every approach, and waits. The turn ends with a grounded possibility—not a sighting.'),
  ('scene-hanuman-waits-in-shimshapa', 'routine-becomes-the-final-hypothesis', 'hi', 'वे वहाँ प्रतीक्षा करते हैं जहाँ सीता स्वयं आ सकती हैं', 'हनुमान सीता का वन, पक्षी, पशु, उद्यान-विहार, प्रातः आचरण और स्वच्छ जल से प्रेम याद करते हैं। यदि वे जीवित और पास बंदी हैं, तो राम के लिए शोक करते हुए भी परिचित लय में भोर को नदी या ताल तक आ सकती हैं। वे छिपकर हर मार्ग देखते और प्रतीक्षा करते हैं। यह चरण दर्शन पर नहीं, प्रमाण-आधारित संभावना पर समाप्त होता है।'),
  ('scene-hanuman-finally-sees-sita', 'the-grove-opens-toward-one-pavilion', 'en', 'The whole grove points toward one distant structure', 'From inside the shimshapa leaves, Hanuman surveys flowering trees, ponds, birds, courtyards, seasonal fruit, and dwellings until one round white pavilion rises beyond them. Its height, coral stairs, golden floor, and guarded distance make it a place built to separate someone from ordinary movement. The search stops being a sweep of beautiful scenery and becomes a question about who is being kept there.'),
  ('scene-hanuman-finally-sees-sita', 'the-grove-opens-toward-one-pavilion', 'hi', 'पूरी वाटिका एक दूर के मंडप की ओर संकेत करती है', 'शीशम की पत्तियों के भीतर से हनुमान फूलों, तालों, पक्षियों, आँगनों, ऋतु-फलों और निवासों को देखते हुए उस दूर उठते गोल श्वेत मंडप तक पहुँचते हैं। उसकी ऊँचाई, मूँगे की सीढ़ियाँ, स्वर्णिम फर्श और पहरे की दूरी बताती है कि किसी को सामान्य आवागमन से अलग रखने के लिए यह स्थान बना है। खोज सुंदर दृश्य का चक्कर नहीं रहती; प्रश्न बनती है कि वहाँ किसे रखा गया है।'),
  ('scene-hanuman-finally-sees-sita', 'one-woman-sits-apart', 'en', 'Isolation appears before identity', 'Beneath the pavilion sits one woman in a worn yellow cloth, reduced by fasting, breathing through repeated sighs, watched by guards, and separated from every familiar person. Hanuman first registers the conditions around her: bare earth instead of chosen comfort, surveillance instead of company, and a private grief with no safe listener. Her suffering is not used as decoration or proof of virtue; it establishes captivity.'),
  ('scene-hanuman-finally-sees-sita', 'one-woman-sits-apart', 'hi', 'पहचान से पहले एकांत दिखाई देता है', 'मंडप के नीचे एक स्त्री घिसे पीले वस्त्र में, उपवास से दुर्बल, बार-बार आह भरती, पहरे में और हर परिचित व्यक्ति से अलग बैठी हैं। हनुमान पहले उनके चारों ओर की परिस्थिति पढ़ते हैं—चुने आराम के बजाय नंगी धरती, साथ के बजाय निगरानी और ऐसा निजी शोक जिसे सुनने वाला कोई सुरक्षित व्यक्ति नहीं। उनका दुःख सजावट या सद्गुण का प्रमाण नहीं; वह बंदीपन स्थापित करता है।'),
  ('scene-hanuman-finally-sees-sita', 'recognition-tests-more-than-appearance', 'en', 'Hope must survive an evidence check', 'The mistake with Mandodari is still fresh, so Hanuman does not identify this woman through beauty. He compares Rama''s remembered description with the yellow cloth seen during the abduction, the ornaments the southern party recovered, the pieces still worn and darkened by time, her guarded position, and her attention fixed beyond Lanka. No single clue is enough; their agreement makes the conclusion reliable.'),
  ('scene-hanuman-finally-sees-sita', 'recognition-tests-more-than-appearance', 'hi', 'आशा को प्रमाण की जाँच से गुजरना है', 'मंदोदरी वाली भूल अभी ताज़ा है, इसलिए हनुमान इस स्त्री को सुंदरता से नहीं पहचानते। वे राम के स्मृत वर्णन को हरण के समय दिखे पीले वस्त्र, दक्षिणी दल को मिले आभूषण, अब भी पहने और समय से मैले टुकड़े, पहरे की स्थिति तथा लंका से बाहर टिके उनके ध्यान से मिलाते हैं। कोई एक संकेत पर्याप्त नहीं; सबका मेल निष्कर्ष को विश्वसनीय बनाता है।'),
  ('scene-hanuman-finally-sees-sita', 'the-ornament-trail-reaches-its-owner', 'en', 'The trail across the earth closes a loop', 'The ornaments cast toward the monkeys were not a decorative clue; they were Sita''s action during abduction, converting possessions into a route someone might follow. Hanuman can now connect the cloth seen in the sky, the pieces preserved on the mountain, Rama''s account, and the woman before him. A message sent without knowing its receiver has crossed forest, alliance, search, and ocean to become evidence.'),
  ('scene-hanuman-finally-sees-sita', 'the-ornament-trail-reaches-its-owner', 'hi', 'धरती पर बिखरी राह अपने स्वामी तक पहुँचती है', 'वानरों की ओर फेंके आभूषण सजावटी संकेत नहीं थे; वे हरण के बीच सीता की कार्रवाई थे, जिसने वस्तुओं को ऐसी राह बनाया जिसे कोई खोज सके। हनुमान अब आकाश में दिखे वस्त्र, पर्वत पर संभाले टुकड़े, राम का वर्णन और सामने बैठी स्त्री को जोड़ सकते हैं। अपना प्राप्तकर्ता जाने बिना भेजा संदेश वन, मैत्री, खोज और समुद्र पार करके प्रमाण बना है।'),
  ('scene-hanuman-finally-sees-sita', 'mutual-memory-has-kept-two-people-moving', 'en', 'Recognition reveals two continuing inner lives', 'Hanuman sees that Sita''s mind remains with Rama and knows Rama''s effort has remained organised around finding her. Their bond has not erased terror, doubt, anger, or exhaustion, but it has kept each person''s next action possible. He does not treat Sita as an object Rama owns or a prize the search has earned; she is the missing decision-maker whose safety and message must now guide the mission.'),
  ('scene-hanuman-finally-sees-sita', 'mutual-memory-has-kept-two-people-moving', 'hi', 'पहचान दो चलते हुए भीतरी जीवन दिखाती है', 'हनुमान देखते हैं कि सीता का मन राम से जुड़ा है और जानते हैं कि राम का प्रयास उन्हें खोजने के चारों ओर संगठित रहा है। यह बंधन भय, संदेह, क्रोध या थकान नहीं मिटाता, पर दोनों की अगली कार्रवाई संभव रखता है। वे सीता को राम की संपत्ति या खोज का पुरस्कार नहीं मानते; वे वह लापता निर्णयकर्ता हैं जिनकी सुरक्षा और संदेश अब अभियान को दिशा देंगे।'),
  ('scene-hanuman-finally-sees-sita', 'certainty-changes-the-mission', 'en', 'Finding Sita creates new duties', 'Relief reaches Hanuman as tears, but he keeps still. The mission is no longer merely to locate Sita; he must learn her condition, avoid exposing her, find a way to earn trust, receive a message, and return alive with truthful evidence. Recognition narrows uncertainty while increasing responsibility. Hidden in the tree, he silently turns toward Rama and Lakshmana before resuming watch.'),
  ('scene-hanuman-finally-sees-sita', 'certainty-changes-the-mission', 'hi', 'सीता को पाना नई जिम्मेदारियाँ बनाता है', 'राहत हनुमान की आँखों में आँसू बनकर आती है, फिर भी वे स्थिर रहते हैं। अभियान अब केवल सीता का स्थान जानना नहीं; उन्हें उनकी दशा समझनी, उन्हें उजागर होने से बचाना, विश्वास पाने का तरीका खोजना, संदेश लेना और सत्य प्रमाण के साथ जीवित लौटना है। पहचान अनिश्चितता घटाती पर जिम्मेदारी बढ़ाती है। वृक्ष में छिपे वे फिर पहरा देखने से पहले मन में राम और लक्ष्मण की ओर मुड़ते हैं।'),
  ('scene-the-search-becomes-a-person', 'destiny-does-not-explain-the-harm', 'en', 'A word for fate cannot close the inquiry', 'Hanuman is overwhelmed that someone raised in care and accustomed to mutual respect now sits under armed surveillance. He names destiny because the reversal feels too large, but destiny cannot excuse Ravana''s decision, the guards'' pressure, or the systems holding Sita. Wonder at how life changed must remain separate from responsibility for who caused and continues the harm.'),
  ('scene-the-search-becomes-a-person', 'destiny-does-not-explain-the-harm', 'hi', 'भाग्य का शब्द हानि की जाँच बंद नहीं करता', 'हनुमान विचलित हैं कि देखभाल में पली और पारस्परिक सम्मान की अभ्यस्त व्यक्ति अब सशस्त्र निगरानी में बैठी हैं। उलटाव बहुत बड़ा लगने से वे भाग्य का नाम लेते हैं, पर भाग्य रावण के निर्णय, पहरेदारों के दबाव या सीता को बाँधने वाले तंत्र का बहाना नहीं बन सकता। जीवन कैसे बदला और हानि कौन कर रहा है—ये अलग प्रश्न रहते हैं।'),
  ('scene-the-search-becomes-a-person', 'the-chain-of-conflict-converges-here', 'en', 'Many victories have not yet rescued one captive', 'Hanuman remembers Viradha, Kabandha, the Janasthana battle, Vali''s death, Sugriva''s restoration, the southern search, and his own ocean crossing. The chain explains the scale of effort now gathered around this grove, but martial accomplishments do not equal Sita''s safety. Each victory is only useful insofar as it creates a truthful path toward her freedom and avoids adding needless harm.'),
  ('scene-the-search-becomes-a-person', 'the-chain-of-conflict-converges-here', 'hi', 'अनेक विजय अभी एक बंदिनी को नहीं बचा पाई हैं', 'हनुमान विराध, कबन्ध, जनस्थान का युद्ध, वाली की मृत्यु, सुग्रीव की पुनर्स्थापना, दक्षिणी खोज और अपना समुद्र-पार याद करते हैं। यह शृंखला वाटिका के चारों ओर जुटे प्रयास का आकार बताती है, पर युद्ध-विजय सीता की सुरक्षा नहीं है। हर सफलता तभी उपयोगी है जब वह उनकी स्वतंत्रता तक सत्य मार्ग बनाए और अनावश्यक हानि न बढ़ाए।'),
  ('scene-the-search-becomes-a-person', 'sitas-choices-precede-the-rescue', 'en', 'Her agency did not begin when Hanuman arrived', 'Sita chose the forest journey, adapted to its material life, resisted the abduction, left a recoverable trail, refused Ravana, and has sustained her own boundaries under pressure. Hanuman''s arrival matters because it may connect her actions to allies, not because it gives agency to someone who had none. The rescue must learn from what she has already done and ask what she now wants carried back.'),
  ('scene-the-search-becomes-a-person', 'sitas-choices-precede-the-rescue', 'hi', 'उनकी सक्रियता हनुमान के आने से शुरू नहीं हुई', 'सीता ने वन-यात्रा चुनी, उसके भौतिक जीवन में ढलीं, हरण का प्रतिरोध किया, खोजी जा सकने वाली राह छोड़ी, रावण को अस्वीकार किया और दबाव में अपनी सीमाएँ बचाए रखीं। हनुमान का पहुँचना इसलिए महत्त्वपूर्ण है कि वह उनके कर्मों को साथियों से जोड़ सकता है, न कि किसी निष्क्रिय व्यक्ति को सक्रियता देता है। बचाव को उनके किए से सीखना और अब उनका संदेश पूछना होगा।'),
  ('scene-the-search-becomes-a-person', 'value-is-not-a-comparison-of-kingdoms', 'en', 'No kingdom can price a person', 'Hanuman''s devotion reaches for comparisons grand enough to express Sita''s importance, placing kingdoms and worlds beside her. Yet praise cannot turn a person into a market value. Sita matters through personhood, relationships, judgment, memory, and choices—not because she is more expensive than land, nor because her suffering authorises unlimited destruction around her.'),
  ('scene-the-search-becomes-a-person', 'value-is-not-a-comparison-of-kingdoms', 'hi', 'कोई राज्य किसी व्यक्ति की कीमत नहीं लगा सकता', 'हनुमान की भक्ति सीता का महत्त्व कहने के लिए राज्य और संसार जैसे बड़े तुलनात्मक रूप खोजती है। फिर भी यह यात्रा उस प्रशंसा को बाज़ार की कीमत नहीं बनाती। सीता का महत्त्व व्यक्तित्व, संबंध, निर्णय, स्मृति और चुनाव से है—भूमि से अधिक महँगी होने से नहीं, और न उनका दुःख चारों ओर असीम विनाश की अनुमति देता है।'),
  ('scene-the-search-becomes-a-person', 'witnessing-requires-patience', 'en', 'Relief does not permit a rushed reveal', 'Hanuman now knows the person before him is Sita, yet he still lacks the shape of her daily danger, the guards'' routines, Ravana''s access, and the safest moment for contact. He settles deeper into cover. Love for Rama and compassion for Sita become reasons to observe more carefully, not excuses to interrupt a captive whose surroundings he has not yet understood.'),
  ('scene-the-search-becomes-a-person', 'witnessing-requires-patience', 'hi', 'राहत जल्दबाज़ी में सामने आने की अनुमति नहीं देती', 'हनुमान अब जानते हैं कि सामने सीता हैं, फिर भी उनके दैनिक खतरे, पहरे की दिनचर्या, रावण की पहुँच और संपर्क के सुरक्षित क्षण का स्वरूप नहीं जानते। वे ओट में और स्थिर होते हैं। राम से प्रेम और सीता के प्रति करुणा अधिक सावधानी से देखने के कारण बनते हैं, ऐसे बंदी जीवन में हस्तक्षेप के बहाने नहीं जिसे वे अभी पूरा नहीं समझे।'),
  ('scene-hidden-witness-holds-position', 'moonlight-reveals-a-guard-system', 'en', 'The night watch has many individual positions', 'As the moon lowers, Hanuman can distinguish guards seated near the tree, others holding weapons, some arguing, some drinking, and some watching the approaches. They are not one interchangeable ring. Different attention, authority, fatigue, and distance create gaps and dangers. Reading the system by conduct lets him plan without pretending that a person''s face or body reveals loyalty.'),
  ('scene-hidden-witness-holds-position', 'moonlight-reveals-a-guard-system', 'hi', 'रात के पहरे में अनेक अलग स्थान हैं', 'चाँद नीचे आता है तो हनुमान वृक्ष के पास बैठी, अस्त्र पकड़े, आपस में उलझती, पेय लेती और मार्गों पर नज़र रखती अलग-अलग पहरेदारों को पहचानते हैं। वे एक जैसा घेरा नहीं हैं। ध्यान, अधिकार, थकान और दूरी के फर्क अवसर और खतरे बनाते हैं। आचरण से तंत्र पढ़ने पर वे योजना बना सकते हैं, बिना यह माने कि चेहरा या शरीर निष्ठा बताता है।'),
  ('scene-hidden-witness-holds-position', 'difference-is-not-danger', 'en', 'Unfamiliar forms do not prove cruelty', 'Hanuman notices ears, limbs, faces, colour, height, and animal resemblance among the guards, but unfamiliar bodies do not make a catalogue of horror. Threat is established by surveillance, armed coercion, taunts, and who controls Sita''s exits. Physical variation remains variation; only choices and actions determine who is dangerous, conflicted, passive, or capable of change.'),
  ('scene-hidden-witness-holds-position', 'difference-is-not-danger', 'hi', 'अपरिचित रूप क्रूरता का प्रमाण नहीं', 'हनुमान पहरेदारों के कान, अंग, चेहरे, रंग, कद और पशु-समानता पर ध्यान देते हैं, पर अपरिचित शरीर भय का तमाशा नहीं बनते। खतरा निगरानी, सशस्त्र दबाव, तानों और सीता के मार्ग नियंत्रित करने से स्थापित होता है। शारीरिक भिन्नता भिन्नता ही रहती है; चुनाव और कर्म बताते हैं कि कौन खतरनाक, दुविधाग्रस्त, निष्क्रिय या बदल सकने वाला है।'),
  ('scene-hidden-witness-holds-position', 'captivity-has-not-captured-the-inner-answer', 'en', 'Sita''s surroundings and decision remain different', 'Sita startles at movement and scans every side because the grove is unsafe, but her attention repeatedly returns beyond the guards toward Rama and the world from which she was taken. Dirt, exhaustion, tears, and lack of ornaments record conditions imposed on her; they do not measure the strength of her character. Her inner answer remains her own even while nearly every outer choice is constrained.'),
  ('scene-hidden-witness-holds-position', 'captivity-has-not-captured-the-inner-answer', 'hi', 'सीता का परिवेश और उनका निर्णय अलग रहते हैं', 'सीता हलचल पर चौंकती और हर दिशा देखती हैं क्योंकि वाटिका असुरक्षित है, पर उनका ध्यान पहरे के पार राम और उस संसार की ओर लौटता है जहाँ से उन्हें लाया गया। मैल, थकान, आँसू और आभूषणों का अभाव उन पर थोपी दशा दर्ज करते हैं; वे चरित्र की शक्ति नहीं नापते। लगभग हर बाहरी चुनाव बँधा है, फिर भी भीतरी उत्तर उनका अपना है।'),
  ('scene-hidden-witness-holds-position', 'relief-must-remain-silent', 'en', 'Hanuman''s tears cannot become an alarm', 'Certainty releases tears Hanuman has held through the crossing and search. He bows inwardly to Rama and Lakshmana, yet neither branch nor leaf may betray him. The emotional reward is real, but the world does not pause for it: guards remain close, Sita remains afraid, and a hidden ally who announces himself too early could become another danger she must survive.'),
  ('scene-hidden-witness-holds-position', 'relief-must-remain-silent', 'hi', 'हनुमान के आँसू चेतावनी नहीं बन सकते', 'निश्चितता वे आँसू छोड़ती है जिन्हें हनुमान समुद्र-पार और खोज भर रोकते आए हैं। वे मन में राम और लक्ष्मण को प्रणाम करते हैं, फिर भी कोई शाखा या पत्ता उन्हें प्रकट नहीं कर सकता। भावनात्मक राहत वास्तविक है, पर संसार नहीं रुकता—पहरेदार पास हैं, सीता भय में हैं और समय से पहले सामने आया साथी भी उनके लिए नया खतरा बन सकता है।'),
  ('scene-hidden-witness-holds-position', 'the-witness-keeps-the-whole-scene', 'en', 'Seeing Sita is not the end of observation', 'Hanuman keeps Sita, the guards, paths, pavilion, and changing sky in one field of attention. He needs sequence, not a frozen image: who approaches, who commands, how Sita answers, and when the ring loosens. Remaining hidden is no longer hesitation. It is the method by which a single confirmed sighting can become an accurate account and a safe opening for conversation.'),
  ('scene-hidden-witness-holds-position', 'the-witness-keeps-the-whole-scene', 'hi', 'सीता को देख लेना निरीक्षण का अंत नहीं', 'हनुमान सीता, पहरेदारों, मार्गों, मंडप और बदलते आकाश को एक ही ध्यान में रखते हैं। उन्हें स्थिर चित्र नहीं, क्रम चाहिए—कौन आता, कौन आदेश देता, सीता कैसे उत्तर देतीं और घेरा कब ढीला पड़ता है। छिपे रहना अब संकोच नहीं; यही तरीका है जिससे एक पक्की झलक सही विवरण और सुरक्षित संवाद का अवसर बन सकती है।'),
  ('scene-ravana-enters-at-dawn', 'lanka-wakes-with-sacred-recitation', 'en', 'Dawn does not flatten Lanka into an enemy camp', 'Before Ravana appears, Hanuman hears Vedic recitation, ritual learning, instruments, and the routines that wake the palace. The sounds establish people studying, remembering, serving, and practising within Lanka. Cultural knowledge does not automatically make the ruler''s conduct just, and Ravana''s conduct does not make every resident empty of culture. The inhabited city remains morally and socially complex.'),
  ('scene-ravana-enters-at-dawn', 'lanka-wakes-with-sacred-recitation', 'hi', 'भोर लंका को केवल शत्रु-शिविर नहीं बनाती', 'रावण के आने से पहले हनुमान वैदिक पाठ, अनुष्ठान-ज्ञान, वाद्य और महल जगाने वाली दिनचर्या सुनते हैं। इन ध्वनियों में लंका के भीतर पढ़ते, स्मरण करते, सेवा और अभ्यास करते लोग हैं। सांस्कृतिक ज्ञान शासक के आचरण को अपने-आप न्यायपूर्ण नहीं बनाता, और रावण का आचरण हर निवासी को संस्कृति से रिक्त नहीं करता। जीवित नगर नैतिक और सामाजिक रूप से जटिल रहता है।'),
  ('scene-ravana-enters-at-dawn', 'the-procession-is-skilled-work', 'en', 'A royal entrance depends on many people''s labour', 'Attendants carry lamps, water, fans, a seat, umbrella, drink, and other objects through jewelled gates into the grove. Each task has timing, weight, route, and learned coordination. These workers remain visible as people maintaining a court rather than a halo around Ravana. Their labour enables his access, but their roles and degrees of choice are not assumed to be identical.'),
  ('scene-ravana-enters-at-dawn', 'the-procession-is-skilled-work', 'hi', 'राजकीय प्रवेश अनेक लोगों के श्रम पर टिका है', 'परिचारिकाएँ दीप, जल, पंखे, आसन, छत्र, पेय और अन्य वस्तुएँ रत्न-जटित द्वारों से वाटिका तक लाती हैं। हर काम में समय, भार, मार्ग और सीखा समन्वय है। ये कामगार रावण के चारों ओर चमक नहीं, दरबार चलाते लोगों की तरह सामने रहते हैं। उनका श्रम उसकी पहुँच संभव बनाता है, पर उनकी भूमिकाएँ और चुनाव की सीमाएँ एक जैसी नहीं मानी जातीं।'),
  ('scene-ravana-enters-at-dawn', 'wives-and-attendants-do-not-share-one-condition', 'en', 'Following the ruler does not prove one common motive', 'Ravana''s wives follow in disrupted dress after sleep and celebration, some described as affectionate and reverent. Hanuman has already seen that the palace contains chosen bonds, political positions, dependence, performance, and captivity. This procession cannot speak for every woman in it. Visible closeness here neither erases coercion elsewhere nor proves coercion where the events do not establish it.'),
  ('scene-ravana-enters-at-dawn', 'wives-and-attendants-do-not-share-one-condition', 'hi', 'शासक के पीछे चलना एक ही उद्देश्य का प्रमाण नहीं', 'रावण की पत्नियाँ नींद और उत्सव के बाद अस्त-व्यस्त वेश में पीछे चलती हैं; कुछ में स्नेह और आदर दिखाई देता है। हनुमान पहले देख चुके हैं कि महल में चुने संबंध, राजनीतिक स्थान, निर्भरता, प्रदर्शन और बंदीपन साथ हैं। यह जुलूस हर स्त्री की ओर से नहीं बोल सकता। दिखती निकटता कहीं और का बलप्रयोग नहीं मिटाती और जहाँ प्रमाण नहीं वहाँ बलप्रयोग गढ़ती भी नहीं।'),
  ('scene-ravana-enters-at-dawn', 'hanuman-recognises-the-sleeper', 'en', 'The private chamber and public procession join', 'Lamplight reveals the same ruler Hanuman watched sleeping beneath the canopy. The identification links battle-scarred arms, palace authority, and the current path toward Sita without requiring an omniscient label. Ravana is no longer an abstract enemy at the centre of Lanka; he is the person whose routines grant repeated access to the captive and whose decisions shape the danger around her.'),
  ('scene-ravana-enters-at-dawn', 'hanuman-recognises-the-sleeper', 'hi', 'निजी कक्ष और सार्वजनिक जुलूस जुड़ते हैं', 'दीपों का प्रकाश उसी शासक को दिखाता है जिसे हनुमान ने छत्र के नीचे सोते देखा था। पहचान युद्ध-चिह्नित भुजाओं, महल के अधिकार और सीता की ओर बढ़ते वर्तमान मार्ग को बिना सर्वज्ञ नाम-पट्टी के जोड़ती है। रावण अब लंका के केंद्र का अमूर्त शत्रु नहीं; वह वह व्यक्ति है जिसकी दिनचर्या बंदिनी तक बार-बार पहुँचती और जिसके निर्णय उनके चारों ओर खतरा बनाते हैं।'),
  ('scene-ravana-enters-at-dawn', 'splendour-increases-the-need-for-cover', 'en', 'Hanuman climbs higher instead of freezing in awe', 'Ravana''s light, ornaments, strength, and surrounding court make him difficult to watch at close range, but brilliance is not supernatural moral authority. Hanuman responds tactically: he climbs into denser leaves, narrows movement, and protects the sightline to Sita. The greater the display, the more carefully the hidden witness must distinguish visual power from actual control routes and vulnerabilities.'),
  ('scene-ravana-enters-at-dawn', 'splendour-increases-the-need-for-cover', 'hi', 'हनुमान विस्मय में रुकने के बजाय और ऊपर चढ़ते हैं', 'रावण का प्रकाश, आभूषण, बल और साथ चलता दरबार उसे पास से देखना कठिन बनाते हैं, पर चमक कोई अलौकिक नैतिक अधिकार नहीं। हनुमान रणनीति से उत्तर देते हैं—घनी पत्तियों में ऊपर जाते, गति घटाते और सीता तक दृष्टि बचाते हैं। प्रदर्शन जितना बड़ा, छिपे साक्षी को दृश्य शक्ति और वास्तविक नियंत्रण-मार्ग तथा कमजोरियों को उतनी सावधानी से अलग करना है।'),
  ('scene-sita-sees-the-threat-approach', 'the-body-recognises-danger-first', 'en', 'Fear arrives before argument', 'When Sita sees Ravana approaching with his court, she trembles before he speaks. The reaction belongs to a history of abduction, confinement, repeated pursuit, and threat; it is not coyness or uncertainty about an offer. Her body identifies a person with power to enter her guarded space at will. That recognition arrives before any persuasive words can reframe the encounter.'),
  ('scene-sita-sees-the-threat-approach', 'the-body-recognises-danger-first', 'hi', 'तर्क से पहले भय आता है', 'रावण को दरबार के साथ आते देखकर सीता उसके बोलने से पहले काँपती हैं। यह प्रतिक्रिया हरण, बंदीपन, बार-बार पीछा और धमकी के इतिहास से आती है; यह संकोची प्रणय या प्रस्ताव पर असमंजस नहीं। उनका शरीर उस व्यक्ति को पहचानता है जो उनकी पहरे वाली जगह में अपनी इच्छा से आ सकता है। कोई मीठा शब्द भेंट का अर्थ बदले, उससे पहले यह पहचान स्पष्ट हो जाती है।'),
  ('scene-sita-sees-the-threat-approach', 'covering-is-a-boundary', 'en', 'Sita shields the space she can still control', 'Sita folds her legs and arms to cover herself as Ravana enters her sight. The posture is an active boundary inside a place where doors, guards, and movement are controlled by others. It does not invite commentary on her body; it tells the approaching ruler that looking and access are unwanted. Hanuman reads the gesture as information about safety, not as a spectacle for the hidden observer.'),
  ('scene-sita-sees-the-threat-approach', 'covering-is-a-boundary', 'hi', 'सीता उस स्थान को ढकती हैं जिस पर उनका नियंत्रण बचा है', 'रावण को सामने पाकर सीता पैरों और भुजाओं से स्वयं को ढकती हैं। यह ऐसी जगह में सक्रिय सीमा है जहाँ द्वार, पहरा और गति दूसरों के नियंत्रण में हैं। मुद्रा उनके शरीर पर टिप्पणी का निमंत्रण नहीं; आने वाले शासक को बताती है कि उसकी दृष्टि और पहुँच अनचाही है। हनुमान इसे सुरक्षा की सूचना की तरह पढ़ते हैं, छिपे दर्शक के तमाशे की तरह नहीं।'),
  ('scene-sita-sees-the-threat-approach', 'the-mind-keeps-a-road-to-rama', 'en', 'Captivity cannot close the inward route', 'The narration imagines Sita travelling toward Rama in a chariot drawn by resolution. The image does not erase present terror or promise magical escape; it preserves the direction of her thought when physical movement is blocked. Memory becomes a route by which she can still compare Ravana''s claims with a relationship, life, and set of choices he cannot rewrite.'),
  ('scene-sita-sees-the-threat-approach', 'the-mind-keeps-a-road-to-rama', 'hi', 'बंदीपन मन की राह बंद नहीं कर सकता', 'कथा सीता को संकल्प से खिंचे रथ में मन ही मन राम की ओर जाते देखती है। यह चित्र वर्तमान भय नहीं मिटाता और जादुई मुक्ति का वादा नहीं करता; जब शारीरिक गति बंद है तब उनके विचार की दिशा बचाता है। स्मृति वह मार्ग बनती है जिससे वे रावण के दावों की तुलना उस संबंध, जीवन और चुनावों से करती हैं जिन्हें वह बदल नहीं सकता।'),
  ('scene-sita-sees-the-threat-approach', 'suffering-does-not-lower-status', 'en', 'Captivity cannot diminish Sita', 'Images of pollution, fallen status, ruined altars, and improper marriage surround descriptions of Sita''s condition, yet captivity cannot diminish her human worth or make a harmed woman comparable to caste exclusion. Dirt, hunger, and exhaustion are material consequences of confinement. They reveal what has been done to her body and routine, not any loss of dignity, legitimacy, or belonging.'),
  ('scene-sita-sees-the-threat-approach', 'suffering-does-not-lower-status', 'hi', 'बंदीपन सीता की गरिमा नहीं घटाता', 'अपवित्रता, गिरे दर्जे, रौंदी वेदी और अनुचित विवाह जैसी उपमाएँ सीता की दशा के वर्णन को घेरती हैं, फिर भी बंदीपन उनका मानव मूल्य नहीं घटा सकता और न पीड़ित स्त्री को जातिगत बहिष्कार के समान बना सकता है। मैल, भूख और थकान बंदी जीवन के भौतिक परिणाम हैं। वे बताते हैं कि उनके शरीर और दिनचर्या पर क्या थोपा गया, न कि गरिमा, वैधता या अपनापन कम हुआ।'),
  ('scene-sita-sees-the-threat-approach', 'silence-is-not-consent', 'en', 'Crying and withdrawal already answer the approach', 'Sita cries, withdraws, and holds herself closed while Ravana stands over her. These signals do not need a later speech to become valid. Hanuman now has direct evidence that the coming conversation begins without free access, equal power, or welcome. Whatever Ravana calls affection must be tested against this visible refusal and the captivity that makes leaving impossible.'),
  ('scene-sita-sees-the-threat-approach', 'silence-is-not-consent', 'hi', 'रोना और पीछे हटना पहले ही उत्तर हैं', 'सीता रोती, पीछे हटती और स्वयं को बंद रखती हैं जबकि रावण उनके ऊपर खड़ा है। इन संकेतों को वैध होने के लिए बाद के भाषण की आवश्यकता नहीं। हनुमान के पास प्रत्यक्ष प्रमाण है कि आने वाला संवाद स्वतंत्र पहुँच, समान शक्ति या स्वागत से शुरू नहीं होता। रावण जिसे प्रेम कहेगा उसे इसी दिखते अस्वीकार और निकलना असंभव बनाने वाले बंदीपन पर परखा जाएगा।'),
  ('scene-ravana-builds-a-false-choice', 'isolation-is-presented-as-privacy', 'en', 'Ravana turns absence of witnesses into reassurance', 'Ravana begins by telling Sita that no human or shape-changing rival is present and she should stop fearing him. The statement names the very isolation that makes the encounter unsafe, then asks her to experience it as privacy. Guards answer to him, escape routes are closed, and Hanuman must remain hidden. Being alone with the person who controls the space cannot create free consent.'),
  ('scene-ravana-builds-a-false-choice', 'isolation-is-presented-as-privacy', 'hi', 'रावण गवाहों की अनुपस्थिति को आश्वासन बताता है', 'रावण शुरुआत में कहता है कि कोई मनुष्य या रूप बदलने वाला प्रतिद्वंद्वी मौजूद नहीं और सीता को उससे डरना नहीं चाहिए। यही वाक्य उस एकांत का नाम लेता है जो भेंट को असुरक्षित बनाता है, फिर उसे निजता की तरह महसूस करने को कहता है। पहरेदार उसके अधीन हैं, निकलने के मार्ग बंद और हनुमान को छिपना पड़ रहा है। स्थान नियंत्रित करने वाले व्यक्ति के साथ अकेलापन स्वतंत्र सहमति नहीं बना सकता।'),
  ('scene-ravana-builds-a-false-choice', 'claimed-restraint-does-not-undo-abduction', 'en', 'A promise not to touch cannot reset the past', 'Ravana says force belongs to his people yet claims he will wait for Sita''s desire. The claim cannot neutralise that he abducted her, confines her, controls food and movement, and repeatedly enters her guarded space. Restraint measured only against a worse act is not freedom. A meaningful choice would include release, safety, independent support, and the ability to say no without punishment.'),
  ('scene-ravana-builds-a-false-choice', 'claimed-restraint-does-not-undo-abduction', 'hi', 'न छूने का दावा अतीत नहीं मिटाता', 'रावण बलप्रयोग को अपने समुदाय की रीति बताकर दावा करता है कि वह सीता की इच्छा की प्रतीक्षा करेगा। यह दावा हरण, बंदीपन, भोजन और गति पर नियंत्रण तथा उनके पहरे वाले स्थान में बार-बार प्रवेश को निष्प्रभावी नहीं करता। केवल बदतर कर्म से तुलना की गई रोक स्वतंत्रता नहीं। सार्थक चुनाव में मुक्ति, सुरक्षा, स्वतंत्र सहायता और बिना दंड ‘नहीं’ कहने की क्षमता होती।'),
  ('scene-ravana-builds-a-false-choice', 'luxury-is-offered-as-a-control-system', 'en', 'Every gift depends on accepting the captor', 'Garlands, sandal, ornaments, drink, beds, music, status, treasure, land, and service are offered in a rising cascade. None arrives as unconditional care for a captive. Each comfort is attached to becoming Ravana''s wife and validating his possession. The wealth may be real, but its structure is transactional pressure: the person controlling deprivation offers relief only if Sita changes the answer she has already given.'),
  ('scene-ravana-builds-a-false-choice', 'luxury-is-offered-as-a-control-system', 'hi', 'हर उपहार अपहरणकर्ता को स्वीकारने पर निर्भर है', 'मालाएँ, चंदन, आभूषण, पेय, शय्या, संगीत, पद, खजाना, भूमि और सेवा बढ़ती शृंखला में पेश होते हैं। इनमें से कोई बंदिनी की बिना शर्त देखभाल नहीं। हर आराम रावण की पत्नी बनने और उसके अधिकार को वैध करने से बँधा है। धन वास्तविक हो सकता है, पर उसका ढाँचा लेन-देन का दबाव है—अभाव नियंत्रित करने वाला व्यक्ति राहत तभी देता है जब सीता अपना पहले दिया उत्तर बदलें।'),
  ('scene-ravana-builds-a-false-choice', 'information-asymmetry-attacks-rama', 'en', 'Ravana uses captivity to control what Sita can know', 'Ravana claims Rama has lost power, may be dead, cannot find Lanka, and will never see Sita again. Because Sita has no independent news, each unsupported claim targets the uncertainty captivity created. The speech is not neutral information about Rama; it is an attempt to make isolation feel permanent and Ravana appear to be the only future available.'),
  ('scene-ravana-builds-a-false-choice', 'information-asymmetry-attacks-rama', 'hi', 'रावण बंदीपन से सीता की जानकारी नियंत्रित करता है', 'रावण कहता है कि राम शक्ति खो चुके, शायद जीवित नहीं, लंका नहीं खोज सकते और सीता को फिर कभी नहीं देखेंगे। सीता के पास स्वतंत्र समाचार नहीं, इसलिए हर अप्रमाणित दावा बंदीपन से बनी अनिश्चितता पर वार करता है। यह राम के बारे में निष्पक्ष सूचना नहीं; एकांत को स्थायी और रावण को एकमात्र भविष्य दिखाने का प्रयास है।'),
  ('scene-ravana-builds-a-false-choice', 'power-is-promised-through-more-conquest', 'en', 'The offer to honour Janaka requires taking from others', 'Ravana promises to conquer the earth and give it to Janaka, presenting further domination as a gift to Sita''s family. The offer repeats the logic of Pushpaka: seize another''s world, then rename possession as generosity. It cannot restore the consent of Janaka or Sita, and it would spread the same coercive method outward rather than repair the harm already done.'),
  ('scene-ravana-builds-a-false-choice', 'power-is-promised-through-more-conquest', 'hi', 'जनक के सम्मान का प्रस्ताव दूसरों से छीनने पर टिका है', 'रावण पृथ्वी जीतकर जनक को देने का वादा करता है और नए प्रभुत्व को सीता के परिवार के लिए उपहार बताता है। यह प्रस्ताव पुष्पक वाली तर्क-रेखा दोहराता है—दूसरे का संसार छीनो, फिर अधिकार को उदारता कहो। इससे जनक या सीता की सहमति नहीं लौटती और पहले की हानि सुधारने के बजाय वही दबाव बाहर फैलता है।'),
  ('scene-ravana-builds-a-false-choice', 'the-choice-never-includes-leaving', 'en', 'Beautiful language cannot repair missing freedom', 'Ravana ends with gardens, oceanside travel, pleasure, command, and a future in which Sita may grant wealth to others. The images simulate agency while excluding the one choice she is asking for: return to Rama and leave Lanka. Hanuman can now hear the proposal''s full architecture. Its softness and scale do not matter because refusal still carries no safe exit.'),
  ('scene-ravana-builds-a-false-choice', 'the-choice-never-includes-leaving', 'hi', 'सुंदर भाषा गायब स्वतंत्रता नहीं लौटा सकती', 'रावण उद्यान, समुद्र-तट की यात्रा, आनंद, आदेश और दूसरों को धन देने वाले भविष्य पर भाषण समाप्त करता है। ये चित्र सक्रियता का भ्रम बनाते हैं, पर सीता की माँगी एक बात—राम के पास लौटना और लंका छोड़ना—हटा देते हैं। हनुमान अब प्रस्ताव का पूरा ढाँचा सुनते हैं। उसकी कोमलता और विस्तार अर्थहीन हैं क्योंकि अस्वीकार के साथ सुरक्षित रास्ता अब भी नहीं।'),
  ('scene-sita-sets-the-grass-boundary', 'a-blade-of-grass-restores-distance', 'en', 'The smallest object becomes an unmistakable boundary', 'Sita places a blade of grass between herself and Ravana and turns partly away before answering. In a grove where he controls walls, guards, and access, she creates a line he did not author. The grass has no military force, yet it names the distance his procession and speech try to erase. Her answer begins by changing the spatial rules of the conversation.'),
  ('scene-sita-sets-the-grass-boundary', 'a-blade-of-grass-restores-distance', 'hi', 'सबसे छोटा तिनका अटल सीमा बनता है', 'सीता उत्तर देने से पहले अपने और रावण के बीच घास का तिनका रखकर कुछ मुड़ जाती हैं। जिस वाटिका की दीवार, पहरा और पहुँच उसके नियंत्रण में है, वहाँ वे ऐसी रेखा बनाती हैं जिसे उसने नहीं लिखा। तिनके में सैन्य बल नहीं, फिर भी वह उस दूरी का नाम है जिसे उसका जुलूस और भाषण मिटाना चाहते हैं। उनका उत्तर संवाद के स्थानिक नियम बदलकर शुरू होता है।'),
  ('scene-sita-sets-the-grass-boundary', 'the-same-standard-must-apply-to-every-household', 'en', 'Sita asks Ravana to recognise other people''s bonds', 'Sita tells Ravana to turn his attention toward relationships in which he is actually a participant and to protect another person''s spouse as he would expect his own household to be protected. The argument is not that wives belong to husbands; it exposes a double standard. Ravana demands security and loyalty around himself while treating another household''s bond as available for seizure.'),
  ('scene-sita-sets-the-grass-boundary', 'the-same-standard-must-apply-to-every-household', 'hi', 'सीता रावण से दूसरों के संबंध पहचानने को कहती हैं', 'सीता रावण से कहती हैं कि अपना ध्यान उन संबंधों की ओर करे जिनमें वह वास्तव में सहभागी है और दूसरे की पत्नी की रक्षा वैसे करे जैसे अपने घर की रक्षा चाहता है। तर्क यह नहीं कि पत्नियाँ पतियों की संपत्ति हैं; यह दोहरा मानदंड खोलता है। रावण अपने चारों ओर सुरक्षा और निष्ठा माँगता है, पर दूसरे घर के संबंध को छीनने योग्य मानता है।'),
  ('scene-sita-sets-the-grass-boundary', 'wealth-cannot-purchase-a-different-answer', 'en', 'Sita removes price from the conversation', 'Kingdom, treasure, ornament, status, and pleasure do not alter Sita''s answer because the question is not whether Ravana has offered enough. She states that her relationship with Rama cannot be transferred by increasing a bid. This refusal protects both her present choice and the broader truth that wealth cannot retroactively convert abduction into courtship.'),
  ('scene-sita-sets-the-grass-boundary', 'wealth-cannot-purchase-a-different-answer', 'hi', 'सीता संवाद से कीमत हटा देती हैं', 'राज्य, खजाना, आभूषण, पद और आनंद सीता का उत्तर नहीं बदलते क्योंकि प्रश्न यह नहीं कि रावण ने पर्याप्त दिया या नहीं। वे कहती हैं कि राम के साथ उनका संबंध बढ़ती बोली से स्थानांतरित नहीं हो सकता। यह अस्वीकार उनके वर्तमान चुनाव और इस बड़े सत्य दोनों को बचाता है कि धन पीछे जाकर हरण को प्रणय नहीं बना सकता।'),
  ('scene-sita-sets-the-grass-boundary', 'return-is-the-only-repair-path', 'en', 'Sita offers a route away from catastrophe', 'Sita tells Ravana to return her respectfully and seek friendship with Rama if he wants Lanka and its people to remain secure. She does not ask for a duel or immediate vengeance; she identifies restitution and de-escalation. The possibility matters because destruction is not presented as inevitable fate. Ravana can still stop the continuing wrong and choose a different political future.'),
  ('scene-sita-sets-the-grass-boundary', 'return-is-the-only-repair-path', 'hi', 'सीता विनाश से दूर जाने का मार्ग देती हैं', 'सीता रावण से कहती हैं कि यदि वह लंका और उसके लोगों को सुरक्षित रखना चाहता है तो उन्हें सम्मान से लौटाकर राम से मैत्री करे। वे द्वंद्व या तत्काल प्रतिशोध नहीं माँगतीं; प्रतिपूर्ति और तनाव घटाने का मार्ग बताती हैं। यह संभावना महत्त्वपूर्ण है क्योंकि विनाश को अपरिहार्य भाग्य नहीं दिखाया जाता। रावण चलती हानि रोककर अलग राजनीतिक भविष्य चुन सकता है।'),
  ('scene-sita-sets-the-grass-boundary', 'consequences-follow-refused-repair', 'en', 'The warning belongs to Ravana''s next decision', 'When Sita warns of Rama and Lakshmana''s arrows reaching Lanka, she is describing what follows if captivity and threat continue after a route to peace is offered. Her warning neither celebrates harm to every resident nor treats war as proof of love. It keeps cause visible: Ravana can return her; refusing repair turns his private crime into danger for the city he governs.'),
  ('scene-sita-sets-the-grass-boundary', 'consequences-follow-refused-repair', 'hi', 'चेतावनी रावण के अगले निर्णय से जुड़ी है', 'जब सीता राम और लक्ष्मण के बाणों के लंका पहुँचने की चेतावनी देती हैं, वे बताती हैं कि शांति का मार्ग मिलने के बाद भी बंदीपन और धमकी जारी रहे तो क्या होगा। उनकी चेतावनी हर निवासी की हानि का उत्सव नहीं और युद्ध को प्रेम का प्रमाण नहीं बनाती। कारण स्पष्ट रहता है—रावण उन्हें लौटा सकता है; सुधार ठुकराने पर उसका निजी अपराध शासित नगर के लिए खतरा बनता है।'),
  ('scene-sita-sets-the-grass-boundary', 'the-hidden-abduction-is-named', 'en', 'Sita strips heroism from the seizure', 'Sita recalls that Ravana used the deceptive deer to draw Rama and Lakshmana away and entered an undefended hermitage. His present boasts about conquest cannot change how he acquired power over her: through isolation and surprise rather than open victory. Naming the method restores the missing beginning of his courtship story and prevents current splendour from laundering the abduction.'),
  ('scene-sita-sets-the-grass-boundary', 'the-hidden-abduction-is-named', 'hi', 'सीता हरण से वीरता का आवरण हटाती हैं', 'सीता याद दिलाती हैं कि रावण ने छलपूर्ण मृग से राम और लक्ष्मण को दूर कराया और असुरक्षित कुटिया में आया। उसकी वर्तमान विजय-गाथाएँ यह नहीं बदल सकतीं कि उसने उन पर अधिकार कैसे पाया—खुले युद्ध से नहीं, एकांत और अचानक आक्रमण से। तरीका नाम लेने पर उसकी प्रणय-कथा की छूटी शुरुआत लौटती और आज का वैभव हरण को साफ नहीं कर पाता।'),
  ('scene-refusal-turns-persuasion-into-threat', 'ravana-blames-the-person-who-refuses', 'en', 'Resistance is recast as cruelty', 'Ravana says kindness should have brought Sita under his influence and treats her continued refusal as rough treatment of him. The move shifts attention from abduction and confinement to his injured expectation. Sita is asked to manage the captor''s feelings while her own fear and answer are dismissed. The reversal is plain: anger is being presented as wounded love.'),
  ('scene-refusal-turns-persuasion-into-threat', 'ravana-blames-the-person-who-refuses', 'hi', 'प्रतिरोध को क्रूरता कहा जाता है', 'रावण कहता है कि उसकी दयालुता से सीता को उसके प्रभाव में आ जाना चाहिए था और उनके लगातार अस्वीकार को अपने प्रति कठोर व्यवहार बताता है। इससे ध्यान हरण और बंदीपन से हटकर उसकी आहत अपेक्षा पर जाता है। सीता से अपहरणकर्ता की भावनाएँ संभालने को कहा जाता है, जबकि उनका भय और उत्तर हटाए जाते हैं। उलटाव स्पष्ट है—क्रोध को घायल प्रेम कहा जा रहा है।'),
  ('scene-refusal-turns-persuasion-into-threat', 'the-deadline-reveals-the-offers-enforcement', 'en', 'A lethal consequence was waiting behind persuasion', 'Ravana announces that Sita has two months to accept him and threatens her life if she does not. The threat is conveyed without reproducing its graphic detail. It changes the meaning of every earlier gift: luxury was never one free option among others, because refusal leads to punishment. The countdown is not romance, ritual time, or fate; it is a coercive deadline imposed by the captor.'),
  ('scene-refusal-turns-persuasion-into-threat', 'the-deadline-reveals-the-offers-enforcement', 'hi', 'मनुहार के पीछे घातक दंड पहले से था', 'रावण घोषणा करता है कि सीता के पास उसे स्वीकारने के लिए दो महीने हैं और न मानने पर जीवन लेने की धमकी देता है। धमकी का अर्थ रखा जाता है, उसका भयावह विवरण नहीं। इससे पहले के हर उपहार का अर्थ बदलता है—वैभव स्वतंत्र विकल्प नहीं था क्योंकि अस्वीकार दंड तक ले जाता है। समय-सीमा प्रणय, अनुष्ठान या भाग्य नहीं; अपहरणकर्ता द्वारा थोपा दबाव है।'),
  ('scene-refusal-turns-persuasion-into-threat', 'women-signal-support-under-the-court', 'en', 'Solidarity appears through constrained gestures', 'Women connected to the celestial and courtly households respond with sorrow and discreet movements of eyes, lips, and faces that console Sita. They do not stop Ravana''s power, but their gestures show the procession is not morally unanimous. Small signals matter in a controlled space: someone has seen the threat, believes Sita''s distress, and refuses to let the ruler''s interpretation be the only one present.'),
  ('scene-refusal-turns-persuasion-into-threat', 'women-signal-support-under-the-court', 'hi', 'दरबार के भीतर सीमित संकेतों से साथ दिखाई देता है', 'दिव्य और दरबारी घरानों से जुड़ी स्त्रियाँ दुःख के साथ आँख, होंठ और चेहरे के सूक्ष्म संकेतों से सीता को सांत्वना देती हैं। वे रावण की शक्ति रोक नहीं पातीं, पर उनके संकेत बताते हैं कि जुलूस नैतिक रूप से एकमत नहीं। नियंत्रित स्थान में छोटे संकेत महत्त्वपूर्ण हैं—किसी ने धमकी देखी, सीता के भय पर विश्वास किया और शासक के अर्थ को अकेला अर्थ मानने से इंकार किया।'),
  ('scene-refusal-turns-persuasion-into-threat', 'sita-names-the-unequal-encounter-again', 'en', 'The boast cannot survive the method of abduction', 'Sita answers the threat by returning to the fact Ravana avoids: he took her after drawing Rama and Lakshmana away. She refuses to let wealth, lineage, or battlefield reputation convert a concealed seizure into proof of courage. Her warning that she could resist through her own discipline but honours Rama''s course also preserves her power without turning it into a spectacle of magical retaliation.'),
  ('scene-refusal-turns-persuasion-into-threat', 'sita-names-the-unequal-encounter-again', 'hi', 'वीरता का दावा हरण के तरीके के सामने नहीं टिकता', 'सीता धमकी का उत्तर उस तथ्य से देती हैं जिससे रावण बचता है—उसने राम और लक्ष्मण को दूर कर उन्हें उठाया। वे धन, वंश या युद्ध-प्रतिष्ठा से छिपे हरण को वीरता का प्रमाण बनने नहीं देतीं। वे अपने अनुशासन से प्रतिरोध की क्षमता कहतीं पर राम की राह का सम्मान रखती हैं; इससे उनकी शक्ति जादुई प्रतिशोध का तमाशा बने बिना बनी रहती है।'),
  ('scene-refusal-turns-persuasion-into-threat', 'the-order-expands-pressure-by-design', 'en', 'Ravana delegates coercion after leaving', 'Ravana orders the guards to bend Sita through conciliation, gifts, threats, or any mixture that works. This is not random cruelty by isolated individuals; it is an authorised programme with interchangeable tactics and one required outcome. His departure does not end the encounter. It moves pressure into daily guard routines and makes the system around Sita responsible for continuing his demand.'),
  ('scene-refusal-turns-persuasion-into-threat', 'the-order-expands-pressure-by-design', 'hi', 'रावण जाते हुए दबाव दूसरों को सौंपता है', 'रावण पहरेदारों को आदेश देता है कि समझाने, उपहार, धमकी या किसी भी कारगर मिश्रण से सीता को झुकाएँ। यह अलग व्यक्तियों की अनियोजित क्रूरता नहीं; अधिकृत कार्यक्रम है जिसमें तरीके बदलते पर परिणाम एक माँगा जाता है। उसका जाना भेंट समाप्त नहीं करता। दबाव दैनिक पहरे में उतरता और सीता के चारों ओर का तंत्र उसकी माँग जारी रखने का जिम्मेदार बनता है।'),
  ('scene-refusal-turns-persuasion-into-threat', 'dhanyamalini-pulls-ravana-away', 'en', 'One woman interrupts without resolving the system', 'Dhanyamalini embraces Ravana, tells him that pursuing an unwilling woman burns the pursuer, and pulls him back toward the palace. Her intervention ends the immediate confrontation and explicitly names unwillingness, but it does not free Sita or cancel the guard order. Dhanyamalini''s action matters, but it cannot by itself answer for the court she still inhabits.'),
  ('scene-refusal-turns-persuasion-into-threat', 'dhanyamalini-pulls-ravana-away', 'hi', 'एक स्त्री हस्तक्षेप करती है, तंत्र फिर भी बना रहता है', 'धन्यमालिनी रावण को थामकर कहती हैं कि अनिच्छुक स्त्री का पीछा करने वाला स्वयं जलता है और उसे महल की ओर ले जाती हैं। उनका हस्तक्षेप तत्काल सामना रोकता और अनिच्छा को स्पष्ट नाम देता है, पर सीता को मुक्त नहीं करता या पहरे का आदेश नहीं मिटाता। उनका यह असरदार कर्म महत्त्वपूर्ण है, पर वह उस दरबार का पूरा नैतिक उत्तर नहीं बन सकता जिसका वे हिस्सा हैं।'),
  ('scene-guards-repeat-ravanas-propaganda', 'ekjata-uses-lineage-as-permission', 'en', 'Ancestry is made to stand in for consent', 'Ekjata begins with Pulastya, Vishrava, and Ravana''s celebrated descent, asking Sita to treat lineage as a reason to become his wife. The genealogy may establish political identity, but it cannot answer the present question of Sita''s will. A revered ancestor does not transfer moral credit automatically, and no family tree grants a descendant access to another person.'),
  ('scene-guards-repeat-ravanas-propaganda', 'ekjata-uses-lineage-as-permission', 'hi', 'वंश को सहमति का स्थान दिया जाता है', 'एकजटा पुलस्त्य, विश्रवा और रावण के प्रसिद्ध वंश से शुरू करके सीता से उसे पति मानने को कहती है। वंशावली राजनीतिक पहचान बता सकती है, पर सीता की वर्तमान इच्छा का उत्तर नहीं। पूज्य पूर्वज का नैतिक श्रेय अपने-आप वंशज को नहीं मिलता और कोई कुल-वृक्ष किसी व्यक्ति तक अधिकार नहीं देता।'),
  ('scene-guards-repeat-ravanas-propaganda', 'harijata-turns-conquest-into-desirability', 'en', 'Defeating others is offered as a relationship credential', 'Harijata lists Ravana''s victories over celestial powers and says his willingness to set aside a favoured wife should flatter Sita. Military success and displaced affection are framed as proof that he deserves acceptance. Sita''s position exposes the category error: capacity to defeat opponents or reorder a household says nothing about ability to build a freely chosen relationship.'),
  ('scene-guards-repeat-ravanas-propaganda', 'harijata-turns-conquest-into-desirability', 'hi', 'दूसरों को हराना संबंध की योग्यता बताया जाता है', 'हरिजटा रावण की दिव्य शक्तियों पर जीत गिनाकर कहती है कि प्रिय पत्नी को पीछे रखकर सीता को चाहना उनके लिए सम्मान होना चाहिए। सैन्य सफलता और हटाया गया स्नेह स्वीकृति की योग्यता बताए जाते हैं। सीता की स्थिति इस भूल को खोलती है—विरोधी हराने या घर का क्रम बदलने की क्षमता स्वतंत्र चुना संबंध बनाने की क्षमता नहीं।'),
  ('scene-guards-repeat-ravanas-propaganda', 'vikata-makes-wealth-sound-like-destiny', 'en', 'Resources are presented as an unavoidable future', 'Vikata points to Ravana''s wealth, victories, and presence as if power standing nearby settles what Sita should want. The pressure turns material advantage into inevitability: resistance is called foolish because the stronger ruler already controls the setting. Yet control over present conditions cannot manufacture desire; it only shows why Sita''s refusal requires protection.'),
  ('scene-guards-repeat-ravanas-propaganda', 'vikata-makes-wealth-sound-like-destiny', 'hi', 'संसाधनों को अपरिहार्य भविष्य बताया जाता है', 'विकटा रावण के धन, विजय और सामने मौजूद होने को ऐसे रखती है मानो निकट खड़ी शक्ति तय कर दे कि सीता को क्या चाहना चाहिए। भौतिक बढ़त को अनिवार्यता बनाया जाता है—शक्तिशाली शासक स्थान नियंत्रित करता है, इसलिए प्रतिरोध मूर्खता कहा जाता है। पर वर्तमान दशा का नियंत्रण इच्छा नहीं बना सकता; केवल बताता है कि सीता के अस्वीकार को सुरक्षा क्यों चाहिए।'),
  ('scene-guards-repeat-ravanas-propaganda', 'durmukhi-mythologises-obedience', 'en', 'The world is said to obey Ravana', 'Durmukhi claims the sun, wind, trees, hills, and clouds bend to Ravana''s will. Whether praise, fear, or courtly exaggeration, the cosmic language aims to make one captive''s resistance feel absurdly small. The boast remains Durmukhi''s claim, not a fact about nature. Sita''s small grass boundary remains more truthful about this encounter than the entire universe pressed into propaganda.'),
  ('scene-guards-repeat-ravanas-propaganda', 'durmukhi-mythologises-obedience', 'hi', 'कहा जाता है कि संसार रावण की आज्ञा मानता है', 'दुर्मुखी दावा करती है कि सूर्य, पवन, वृक्ष, पर्वत और मेघ रावण की इच्छा से चलते हैं। प्रशंसा, भय या दरबारी अतिशयोक्ति जो भी हो, यह ब्रह्मांडीय भाषा एक बंदिनी के प्रतिरोध को हास्यास्पद रूप से छोटा दिखाना चाहती है। यह दावा दुर्मुखी का कथन है, प्रकृति का तथ्य नहीं। सीता की छोटी घास-सीमा इस भेंट के बारे में पूरे प्रचारित ब्रह्मांड से अधिक सत्य है।'),
  ('scene-guards-repeat-ravanas-propaganda', 'persuasion-ends-in-an-explicit-threat', 'en', 'The pressure system reveals its final argument', 'After ancestry, conquest, wealth, and cosmic praise fail, the guards say Sita must comply or die. The sequence proves the earlier arguments were not an open exchange. Different stories served the same enforced destination, and threat appears when none changes her answer. Hanuman records both the named speakers and the command structure behind them rather than reducing the moment to anonymous evil.'),
  ('scene-guards-repeat-ravanas-propaganda', 'persuasion-ends-in-an-explicit-threat', 'hi', 'दबाव का तंत्र अपना अंतिम तर्क दिखाता है', 'वंश, विजय, धन और ब्रह्मांडीय प्रशंसा विफल होने पर पहरेदार कहती हैं कि सीता मानें या मरें। यह क्रम सिद्ध करता है कि पहले के तर्क खुला संवाद नहीं थे। अलग कथाएँ एक ही थोपी मंज़िल की सेवा करती थीं और उत्तर न बदलने पर धमकी सामने आती है। हनुमान इस क्षण को बेनाम बुराई नहीं बनाते; बोलने वालों और उनके पीछे के आदेश-तंत्र दोनों दर्ज करते हैं।'),
  ('scene-the-ring-of-threats-tightens', 'remembered-women-become-an-inner-council', 'en', 'Sita answers isolation with stories she carries', 'Sita names women remembered for sustaining chosen relationships through danger and change. The examples are not presented as a universal rule that every woman must endure harm or remain in any marriage. In this captive moment, they are an inner council Sita selects for herself, proof that Ravana and the guards do not control every story available to her or the meaning she gives her own commitment.'),
  ('scene-the-ring-of-threats-tightens', 'remembered-women-become-an-inner-council', 'hi', 'सीता अपने भीतर की कथाओं से एकांत का उत्तर देती हैं', 'सीता उन स्त्रियों के नाम लेती हैं जिन्हें संकट और परिवर्तन में चुने संबंध निभाने के लिए याद किया जाता है। ये उदाहरण ऐसा सार्वभौमिक नियम नहीं कि हर स्त्री हानि सहे या किसी भी विवाह में रहे। इस बंदी क्षण में वे सीता द्वारा चुनी भीतरी परिषद हैं—प्रमाण कि रावण और पहरेदार उनके लिए उपलब्ध हर कथा या अपनी प्रतिबद्धता का अर्थ नियंत्रित नहीं करते।'),
  ('scene-the-ring-of-threats-tightens', 'vinata-repackages-pressure-as-moderation', 'en', 'Enough loyalty is declared on Sita''s behalf', 'Vinata says Sita has shown sufficient attachment to Rama and warns that excess becomes harmful, then presents Ravana as the reasonable next choice. The language borrows moderation to invalidate a boundary it does not respect. Only Sita can decide whether her relationship continues; a guard cannot announce that her loyalty quota is complete and redirect it toward the person holding her captive.'),
  ('scene-the-ring-of-threats-tightens', 'vinata-repackages-pressure-as-moderation', 'hi', 'सीता की ओर से निष्ठा की सीमा घोषित की जाती है', 'विनता कहती है कि सीता राम के प्रति पर्याप्त लगाव दिखा चुकीं और अधिकता हानिकारक है, फिर रावण को उचित अगला चुनाव बताती है। यह भाषा संयम उधार लेकर उस सीमा को अमान्य करती है जिसका वह सम्मान नहीं करती। अपना संबंध जारी है या नहीं, यह केवल सीता तय कर सकती हैं; पहरेदार निष्ठा का कोटा पूरा घोषित करके उसे अपहरणकर्ता की ओर नहीं मोड़ सकती।'),
  ('scene-the-ring-of-threats-tightens', 'isolation-is-used-as-proof-of-hopelessness', 'en', 'The ocean becomes part of the threat', 'Vikata points to the ocean, closed room, guards, and even Indra''s supposed inability to rescue Sita. Geography is turned into psychological pressure: because help looks impossible, refusal is called useless. Hanuman''s hidden presence disproves the certainty without yet making Sita safe. The route across the ocean exists, but revealing that fact at the wrong instant could close it again.'),
  ('scene-the-ring-of-threats-tightens', 'isolation-is-used-as-proof-of-hopelessness', 'hi', 'समुद्र धमकी का हिस्सा बन जाता है', 'विकटा समुद्र, बंद कक्ष, पहरे और यहाँ तक कि इंद्र की कथित असमर्थता दिखाती है। भूगोल मनोवैज्ञानिक दबाव बनता है—सहायता असंभव दिखती है, इसलिए अस्वीकार व्यर्थ कहा जाता है। हनुमान की छिपी उपस्थिति इस निश्चितता को गलत सिद्ध करती है, पर सीता अभी सुरक्षित नहीं। समुद्र-पार का मार्ग है, पर गलत क्षण में उसका खुलना उसे फिर बंद कर सकता है।'),
  ('scene-the-ring-of-threats-tightens', 'named-voices-escalate-to-killing', 'en', 'The threats become explicit without becoming spectacle', 'Chandodara, Praghasa, Ajamukhi, Surpanakha, and others move from contempt to threats that they will kill Sita and celebrate afterward. The deadly escalation and its speakers remain clear, but anatomical or consumption detail is unnecessary. What matters is the credible danger, group reinforcement, and way cruelty becomes social performance around a trapped person.'),
  ('scene-the-ring-of-threats-tightens', 'named-voices-escalate-to-killing', 'hi', 'धमकियाँ स्पष्ट होती हैं, तमाशा नहीं', 'चंडोदरा, प्रघसा, अजमुखी, शूर्पणखा और अन्य तिरस्कार से आगे बढ़कर सीता की हत्या और उसके बाद उत्सव की धमकी देती हैं। घातक बढ़ाव और बोलने वालों के नाम स्पष्ट रहते हैं, पर शारीरिक या भक्षण-विवरण आवश्यक नहीं। महत्त्वपूर्ण है वास्तविक खतरा, समूह द्वारा एक-दूसरे को उकसाना और फँसी व्यक्ति के चारों ओर क्रूरता का सामाजिक प्रदर्शन बनना।'),
  ('scene-the-ring-of-threats-tightens', 'sita-moves-toward-the-shimshapa', 'en', 'The captive and witness draw closer without knowing', 'Under the tightening ring, Sita moves toward the shimshapa and weeps beneath the branch where Hanuman is concealed. Physical distance collapses while knowledge remains unequal: he knows an ally is present; she does not. The closeness sharpens his dilemma. Immediate appearance could frighten her or summon the guards, but continued silence leaves her alone with an unbearable threat.'),
  ('scene-the-ring-of-threats-tightens', 'sita-moves-toward-the-shimshapa', 'hi', 'बंदिनी और साक्षी अनजाने में पास आते हैं', 'कसते घेरे में सीता शीशम की ओर बढ़कर उसी शाखा के नीचे रोती हैं जहाँ हनुमान छिपे हैं। शारीरिक दूरी घटती है, पर ज्ञान असमान रहता है—वे जानते हैं कि साथी मौजूद है; सीता नहीं। निकटता दुविधा तेज करती है। तुरंत सामने आना उन्हें डरा या पहरा बुला सकता है, पर मौन उन्हें असहनीय खतरे में अकेला छोड़ता है।'),
  ('scene-the-ring-of-threats-tightens', 'witnessing-becomes-an-urgent-duty', 'en', 'Hanuman must preserve sequence before acting', 'Hanuman hears every threat and sees who speaks, who follows, who hesitates, and how Sita responds. His restraint is not indifference. Accurate witness will matter to Rama, to any rescue plan, and to Sita''s own message. Yet evidence gathering has reached a limit: if her crisis deepens, he must find a form of contact that reduces rather than adds danger.'),
  ('scene-the-ring-of-threats-tightens', 'witnessing-becomes-an-urgent-duty', 'hi', 'हनुमान को कार्रवाई से पहले क्रम बचाना है', 'हनुमान हर धमकी सुनते और देखते हैं कि कौन बोलता, कौन साथ देता, कौन हिचकता तथा सीता कैसे उत्तर देती हैं। उनका संयम उदासीनता नहीं। सही साक्ष्य राम, बचाव-योजना और सीता के अपने संदेश के लिए महत्त्वपूर्ण होगा। फिर भी प्रमाण जुटाने की सीमा आ गई है—यदि उनका संकट गहराए तो ऐसा संपर्क खोजना होगा जो खतरा बढ़ाए नहीं, घटाए।'),
  ('scene-sita-calls-across-the-distance', 'the-threat-breaks-through-composure', 'en', 'Endurance has a human limit', 'After repeated persuasion and killing threats, Sita shakes, falls, and cannot restore her previous composure. The moment does not treat collapse as weak character or failed devotion. A person deprived of safety, sleep, news, choice, and trusted company can be overwhelmed. Her body''s loss of steadiness is evidence of what the pressure system is doing, not consent to what it demands.'),
  ('scene-sita-calls-across-the-distance', 'the-threat-breaks-through-composure', 'hi', 'सहनशीलता की मानवीय सीमा है', 'बार-बार की मनुहार और हत्या की धमकियों के बाद सीता काँपती, गिरती और पहले का संयम तुरंत नहीं लौटा पातीं। यह टूटन कमजोर चरित्र या विफल निष्ठा नहीं है। सुरक्षा, नींद, समाचार, चुनाव और विश्वस्त साथ से वंचित व्यक्ति अभिभूत हो सकता है। शरीर का संतुलन खोना दबाव-तंत्र की हानि का प्रमाण है, उसकी माँग की सहमति नहीं।'),
  ('scene-sita-calls-across-the-distance', 'sita-calls-the-mothers-by-name', 'en', 'Family appears as an unreachable support network', 'Sita calls to Kausalya and Sumitra before calling again for Rama. The names widen captivity beyond a separated couple: she has been cut off from older women, household memory, and people who could recognise her distress without requiring proof. Speaking their names does not summon them magically, but it resists the guards'' claim that Lanka is the only social world left.'),
  ('scene-sita-calls-across-the-distance', 'sita-calls-the-mothers-by-name', 'hi', 'परिवार दूर का सहारा बनकर सामने आता है', 'सीता फिर राम को पुकारने से पहले कौसल्या और सुमित्रा को नाम से बुलाती हैं। ये नाम बंदीपन को बिछड़े दंपति से आगे फैलाते हैं—वे बुज़ुर्ग स्त्रियों, घर की स्मृति और ऐसे लोगों से काटी गई हैं जो बिना प्रमाण उनका दुःख पहचानते। नाम लेना उन्हें जादुई रूप से नहीं बुलाता, पर पहरेदारों के इस दावे का प्रतिरोध है कि अब लंका ही उनका एकमात्र सामाजिक संसार है।'),
  ('scene-sita-calls-across-the-distance', 'other-people-can-still-see-rama', 'en', 'Sita imagines the ordinary sight captivity denies her', 'Sita thinks of people who may still look upon Rama''s face, hear his measured speech, and walk near him. The pain is not only heroic reunion delayed; it is exclusion from ordinary shared time while life continues elsewhere. This comparison deepens loneliness, but it also preserves a living world beyond the grove rather than accepting Ravana''s claim that Rama and every route back have vanished.'),
  ('scene-sita-calls-across-the-distance', 'other-people-can-still-see-rama', 'hi', 'सीता उस सामान्य दर्शन की कल्पना करती हैं जिससे बंदीपन उन्हें रोकता है', 'सीता उन लोगों को सोचती हैं जो अब भी राम का मुख देख, उनकी संयत वाणी सुन और उनके पास चल सकते हैं। पीड़ा केवल वीर मिलन में देर नहीं; बाहर जीवन चलते समय सामान्य साझा समय से बाहर कर दिए जाने की है। तुलना एकांत बढ़ाती है, पर वाटिका के पार जीवित संसार भी बचाती है और रावण का यह दावा नहीं मानती कि राम तथा लौटने की हर राह मिट चुकी।'),
  ('scene-sita-calls-across-the-distance', 'despair-mistakes-duration-for-destiny', 'en', 'Because suffering continues, it feels endless', 'Sita repeats that death does not arrive when wanted and imagines herself forever driven on an ocean of grief. These are crisis thoughts produced by sustained terror and no reliable timeline. They are not insight, virtue, or destiny. Hanuman''s unseen presence is concrete counterevidence: change has already crossed the ocean, even though Sita has not yet been given a safe way to know it.'),
  ('scene-sita-calls-across-the-distance', 'despair-mistakes-duration-for-destiny', 'hi', 'दुःख जारी है, इसलिए अनंत लगता है', 'सीता कहती हैं कि चाहने पर मृत्यु नहीं आती और स्वयं को शोक-सागर में सदा बहता सोचती हैं। ये लगातार भय और विश्वसनीय समय-रेखा न होने से पैदा संकट-विचार हैं। ये विचार ज्ञान, सद्गुण या भाग्य नहीं हैं। हनुमान की अनदेखी उपस्थिति ठोस प्रतिप्रमाण है—परिवर्तन समुद्र पार कर चुका, भले सीता को उसे सुरक्षित रूप से जानने का मार्ग अभी न मिला हो।'),
  ('scene-sita-calls-across-the-distance', 'the-wish-to-disappear-is-not-a-solution', 'en', 'The crisis needs connection, not instruction', 'Sita wishes she could stop living under the burden, but no method is shown, rehearsed, or made actionable. Her statement communicates unbearable pain and loss of perceived options. Her words call for safety, truthful news, and human connection. It neither romanticises self-destruction as devotion nor blames her for reaching the edge of endurance.'),
  ('scene-sita-calls-across-the-distance', 'the-wish-to-disappear-is-not-a-solution', 'hi', 'संकट को जुड़ाव चाहिए, तरीका नहीं', 'सीता इस भार में जीवित न रहने की इच्छा कहती हैं, पर कोई तरीका दिखाया, दोहराया या क्रियात्मक नहीं बनाया जाता। उनका कथन असहनीय पीड़ा और विकल्प खो जाने का अनुभव बताता है। कथा इसे सुरक्षा, सत्य समाचार और मानवीय जुड़ाव की पुकार मानती है। वह आत्म-विनाश को निष्ठा का रोमानी प्रमाण नहीं बनाती और न सहन की सीमा तक पहुँचने के लिए उन्हें दोष देती है।'),
  ('scene-sita-calls-across-the-distance', 'hanuman-now-has-a-contact-deadline', 'en', 'Silence has become its own risk', 'Hidden above, Hanuman hears the crisis and knows that accurate sighting alone is no longer sufficient. He must communicate hope without appearing as another shape-changing threat, drawing the guards, or making promises he cannot support. Sita does not know he exists, so the next design problem is not whether to help but how to make help recognisable and safe.'),
  ('scene-sita-calls-across-the-distance', 'hanuman-now-has-a-contact-deadline', 'hi', 'मौन अब स्वयं खतरा बन गया है', 'ऊपर छिपे हनुमान संकट सुनकर जानते हैं कि केवल सही पहचान अब पर्याप्त नहीं। उन्हें ऐसा भरोसा पहुँचाना है जो किसी नए रूप बदलने वाले खतरे जैसा न लगे, पहरा न बुलाए और अप्रमाणित वादा न करे। सीता उनके अस्तित्व से अनजान हैं, इसलिए अगली समस्या मदद करनी है या नहीं नहीं, बल्कि मदद को पहचानने योग्य और सुरक्षित कैसे बनाना है।'),
  ('scene-grief-rewrites-every-unknown', 'the-abduction-story-is-replayed-for-a-missing-answer', 'en', 'Sita searches the past for the moment rescue failed', 'Sita revisits Maricha drawing Rama away, Ravana seizing her, and Jatayu fighting despite age and disadvantage. The sequence is not self-torment for spectacle; she is trying to infer what information survived. Jatayu could have carried the location, but she saw him fall. Without knowing who later found him, she cannot tell whether Rama even has the first truthful lead.'),
  ('scene-grief-rewrites-every-unknown', 'the-abduction-story-is-replayed-for-a-missing-answer', 'hi', 'सीता अतीत में खोजती हैं कि बचाव कहाँ रुका', 'सीता मारीच द्वारा राम को दूर ले जाने, रावण के हरण और आयु तथा असमानता के बावजूद जटायु के लड़ने को फिर देखती हैं। यह तमाशे के लिए आत्म-पीड़ा नहीं; वे समझना चाहती हैं कि कौन-सी सूचना बची। जटायु स्थान बता सकते थे, पर उन्होंने उन्हें गिरते देखा। बाद में किसने उन्हें पाया, यह न जानने से सीता तय नहीं कर सकतीं कि राम के पास पहला सत्य संकेत भी है या नहीं।'),
  ('scene-grief-rewrites-every-unknown', 'silence-creates-mutually-exclusive-stories', 'en', 'Every explanation fills the same communication void', 'Sita wonders whether Rama does not know where she is, has died, has renounced attachment, has forgotten her, or was killed with Lakshmana through treachery. These possibilities cannot all be true. Their rapid replacement reveals an information vacuum, not unstable character. Captivity prevents messages, so fear keeps producing complete stories from no new evidence.'),
  ('scene-grief-rewrites-every-unknown', 'silence-creates-mutually-exclusive-stories', 'hi', 'हर कारण उसी समाचार-शून्य को भरता है', 'सीता सोचती हैं कि शायद राम उनका स्थान नहीं जानते, मर गए, आसक्ति छोड़ चुके, उन्हें भूल गए या लक्ष्मण के साथ छल से मारे गए। ये बातें एक साथ सत्य नहीं हो सकतीं। उनका तेजी से बदलना अस्थिर चरित्र नहीं, सूचना-शून्य दिखाता है। बंदीपन संदेश रोकता है, इसलिए भय बिना नए प्रमाण पूरी कथाएँ बनाता रहता है।'),
  ('scene-grief-rewrites-every-unknown', 'self-blame-tries-to-explain-powerlessness', 'en', 'Sita turns uncertainty against her own worth', 'With no answer from outside, Sita calls herself unworthy, unchaste, foolish, or somehow at fault for still living and being separated. None of these judgments defines her. Self-blame offers a false sense that the catastrophe would make sense if she were defective. The evidence shows abduction, coercion, isolation, and blocked news—choices and conditions imposed by others, not a flaw in her person.'),
  ('scene-grief-rewrites-every-unknown', 'self-blame-tries-to-explain-powerlessness', 'hi', 'सीता अनिश्चितता को अपने मूल्य के विरुद्ध मोड़ती हैं', 'बाहर से उत्तर न आने पर सीता स्वयं को अयोग्य, पतित, मूर्ख या जीवित रहने और बिछड़ने के लिए दोषी कहती हैं। कथा इन निर्णयों को स्वीकार नहीं करती। आत्म-दोष ऐसा झूठा भरोसा देता है कि यदि उनमें कमी हो तो विपत्ति समझ आएगी। प्रमाण हरण, दबाव, एकांत और रोका समाचार दिखाता है—दूसरों द्वारा थोपी दशाएँ और कर्म, उनके व्यक्तित्व की कमी नहीं।'),
  ('scene-grief-rewrites-every-unknown', 'imagined-war-spreads-grief-through-lanka', 'en', 'Sita forecasts other households crying as she does', 'Sita imagines Rama reaching Lanka, Ravana dying, smoke filling roads, and women in many homes grieving. The vision expresses belief that captivity will bring consequences, but it also recognises civilians and families who would suffer. Her fear does not make a city becoming a cremation ground cause for celebration, and no resident is made deserving of loss. It holds the forecast as trauma-driven warning about escalation.'),
  ('scene-grief-rewrites-every-unknown', 'imagined-war-spreads-grief-through-lanka', 'hi', 'सीता लंका के घरों में अपने जैसा शोक देखती हैं', 'सीता कल्पना करती हैं कि राम लंका पहुँचते, रावण मरता, मार्ग धुएँ से भरते और अनेक घरों की स्त्रियाँ उनके जैसा शोक करती हैं। यह कल्पना बंदीपन के परिणामों पर विश्वास दिखाती है, पर नागरिकों और पीड़ित परिवारों को भी पहचानती है। कथा नगर के श्मशान बनने पर जयकार नहीं करती और हर निवासी को हानि योग्य नहीं मानती। यह बढ़ते संघर्ष की आघात-जनित चेतावनी है।'),
  ('scene-grief-rewrites-every-unknown', 'jatayus-resistance-remains-a-real-link', 'en', 'One fallen witness still connects Sita to the search', 'Amid incompatible fears, Sita returns to Jatayu''s act and honours that he confronted Ravana for her despite overwhelming odds. She assumes his death ended the message, but Hanuman knows the wider chain: Rama found Jatayu, learned the direction, and the search eventually reached Lanka. The story lets the audience hold this counterevidence without mocking Sita for lacking it.'),
  ('scene-grief-rewrites-every-unknown', 'jatayus-resistance-remains-a-real-link', 'hi', 'गिरा साक्षी अब भी सीता को खोज से जोड़ता है', 'परस्पर विरोधी भय के बीच सीता जटायु के कर्म पर लौटकर मानती हैं कि असमान परिस्थिति के बावजूद उन्होंने उनके लिए रावण का सामना किया। वे समझती हैं कि उनकी मृत्यु से संदेश टूट गया, पर हनुमान व्यापक शृंखला जानते हैं—राम को जटायु मिले, दिशा पता चली और खोज लंका तक पहुँची। दर्शक यह प्रतिप्रमाण रखते हैं, पर सीता को उसके अभाव के लिए उपहास नहीं बनाते।'),
  ('scene-grief-rewrites-every-unknown', 'the-crisis-nears-a-fatal-conclusion', 'en', 'Despair tries to turn unknowns into a final act', 'After exhausting every explanation, Sita again concludes that life has no path forward and thinks of ending it. The thought remains non-graphic and non-actionable. It is not a noble proof of love or the inevitable climax of captivity; it is the point at which blocked information, repeated threat, and self-blame have narrowed perceived options to almost none.'),
  ('scene-grief-rewrites-every-unknown', 'the-crisis-nears-a-fatal-conclusion', 'hi', 'निराशा अनजान बातों को अंतिम कदम बनाना चाहती है', 'हर कारण थक जाने पर सीता फिर मानती हैं कि जीवन में आगे कोई राह नहीं और उसे समाप्त करने का विचार आता है। विचार बिना भयावह या क्रियात्मक विवरण रहता है। यह प्रेम का महान प्रमाण या बंदीपन का अनिवार्य शिखर नहीं; वह बिंदु है जहाँ रोका समाचार, बार-बार की धमकी और आत्म-दोष ने दिखते विकल्प लगभग मिटा दिए हैं।'),
  ('scene-grief-rewrites-every-unknown', 'hanuman-understands-what-news-must-do', 'en', 'A message must reopen choice, not command hope', 'Hanuman has now heard which unknowns are crushing Sita: whether Rama lives, knows, remembers, and is moving toward her. Any first contact must answer those uncertainties with verifiable details while leaving her control over whether to listen. General encouragement would be too weak, and a sudden demand to trust a stranger would repeat the structure of coercion he is trying to interrupt.'),
  ('scene-grief-rewrites-every-unknown', 'hanuman-understands-what-news-must-do', 'hi', 'संदेश को चुनाव खोलना है, आशा का आदेश नहीं देना', 'हनुमान अब सुन चुके हैं कि कौन-सी अनजान बातें सीता को तोड़ रही हैं—राम जीवित हैं या नहीं, जानते, याद करते और उनकी ओर बढ़ रहे हैं या नहीं। पहला संपर्क इन प्रश्नों को सत्यापनीय विवरण से उत्तर दे और सुनना है या नहीं इसका नियंत्रण सीता के पास रखे। सामान्य ढाढ़स बहुत कम होगा और अजनबी पर तुरंत भरोसा माँगना उसी दबाव की रचना दोहराएगा जिसे वे रोकना चाहते हैं।'),
  ('scene-trijatas-dream-breaks-the-circle', 'trijata-stops-the-group', 'en', 'An elder voice breaks the threat rhythm', 'As the guards renew their threat, the elder Trijata tells them to stop and turn their violence away from Sita. She names Sita as Janaka''s daughter and Dasharatha''s daughter-in-law, but her intervention matters beyond pedigree: she refuses the group script, addresses the women directly, and uses standing within their own community to interrupt harm before any outside rescuer appears.'),
  ('scene-trijatas-dream-breaks-the-circle', 'trijata-stops-the-group', 'hi', 'एक बुज़ुर्ग आवाज़ धमकी की लय तोड़ती है', 'पहरेदार फिर धमकी देती हैं तो वृद्ध त्रिजटा उन्हें रोककर हिंसा सीता से दूर मोड़ने को कहती हैं। वे सीता को जनक की पुत्री और दशरथ की पुत्रवधू कहती हैं, पर हस्तक्षेप वंश से आगे महत्त्वपूर्ण है—वे समूह की लिखी भूमिका अस्वीकार करती, स्त्रियों से सीधे बोलती और किसी बाहरी उद्धारक के आने से पहले अपने समुदाय के स्थान से हानि रोकती हैं।'),
  ('scene-trijatas-dream-breaks-the-circle', 'the-dream-is-a-claim-not-a-guarantee', 'en', 'Trijata offers a different future image', 'Trijata says she dreamed of the Rakshasa order falling and Rama prevailing. The dream remains Trijata''s experience and a persuasive intervention, not a deterministic forecast of the future. Its immediate power is psychological and political: it makes the guards imagine that Ravana may lose, that Sita may survive, and that today''s choices may be judged in a changed tomorrow.'),
  ('scene-trijatas-dream-breaks-the-circle', 'the-dream-is-a-claim-not-a-guarantee', 'hi', 'त्रिजटा भविष्य की दूसरी छवि देती हैं', 'त्रिजटा कहती हैं कि उन्होंने राक्षस-व्यवस्था के पतन और राम की विजय का स्वप्न देखा। कथा इसे उनका अनुभव और प्रभावशाली हस्तक्षेप रखती है, उपयोगकर्ताओं के लिए निश्चित भविष्यवाणी नहीं। उसका तात्कालिक बल मनोवैज्ञानिक और राजनीतिक है—पहरेदार सोचती हैं कि रावण हार सकता, सीता बच सकतीं और आज के चुनाव बदले कल में परखे जा सकते हैं।'),
  ('scene-trijatas-dream-breaks-the-circle', 'sita-and-rama-rejoin-in-white', 'en', 'The dream first restores reunion', 'Trijata sees Rama and Lakshmana in white, Sita on a bright hill above the ocean, and the separated pair joined again like sunlight and radiance. Later they rise together on elephant and celestial vehicles toward the north. The images answer captivity with movement, height, companionship, and open direction. They do not erase Sita''s present fear, but they give the grove another ending to imagine.'),
  ('scene-trijatas-dream-breaks-the-circle', 'sita-and-rama-rejoin-in-white', 'hi', 'स्वप्न पहले मिलन लौटाता है', 'त्रिजटा राम और लक्ष्मण को श्वेत वेश में, सीता को समुद्र के ऊपर उजले पर्वत पर और बिछड़े जोड़े को सूर्य तथा प्रकाश की तरह मिलते देखती हैं। आगे वे हाथी और दिव्य वाहनों पर साथ उत्तर की ओर उठते हैं। चित्र बंदीपन का उत्तर गति, ऊँचाई, साथ और खुली दिशा से देते हैं। वे वर्तमान भय नहीं मिटाते, पर वाटिका को कल्पना के लिए दूसरा अंत देते हैं।'),
  ('scene-trijatas-dream-breaks-the-circle', 'ravanas-fall-reverses-the-procession', 'en', 'Royal display becomes loss of control', 'The dream turns Ravana''s bright procession upside down: he falls from Pushpaka, loses royal markers, moves south in confusion, and is dragged rather than obeyed. Kumbhakarna and Indrajit follow their own declining paths. Without grotesque detail, the reversal shows power becoming unstable. The ruler who controls everyone''s route can himself lose direction and command.'),
  ('scene-trijatas-dream-breaks-the-circle', 'ravanas-fall-reverses-the-procession', 'hi', 'राजकीय प्रदर्शन नियंत्रण खोने में बदलता है', 'स्वप्न रावण के चमकते जुलूस को उलट देता है—वह पुष्पक से गिरता, राजचिह्न खोता, भ्रम में दक्षिण जाता और आदेश देने के बजाय खींचा जाता है। कुंभकर्ण तथा इंद्रजित भी अपनी गिरती राहों पर चलते हैं। बिना विकृत विवरण यह उलटाव शक्ति को अस्थिर दिखाता है। सबकी राह नियंत्रित करने वाला शासक स्वयं दिशा और आदेश खो सकता है।'),
  ('scene-trijatas-dream-breaks-the-circle', 'vibhishana-remains-outside-collective-doom', 'en', 'The dream does not condemn every person in Lanka', 'Among the falling royal household, Trijata sees Vibhishana beneath a white umbrella with a small company, still moving through the sky. The exception matters. Even the dream of regime collapse distinguishes choices and possible futures within Ravana''s family and city. Lanka is not one moral body whose every inhabitant shares the ruler''s fate.'),
  ('scene-trijatas-dream-breaks-the-circle', 'vibhishana-remains-outside-collective-doom', 'hi', 'स्वप्न लंका के हर व्यक्ति को दोषी नहीं ठहराता', 'गिरते राजपरिवार के बीच त्रिजटा विभीषण को श्वेत छत्र और छोटे दल के साथ आकाश में चलते देखती हैं। यह अपवाद महत्त्वपूर्ण है। शासन-पतन का स्वप्न भी रावण के परिवार और नगर में अलग चुनाव तथा भविष्य पहचानता है। लंका कोई एक नैतिक शरीर नहीं जिसके हर निवासी की नियति शासक जैसी हो।'),
  ('scene-trijatas-dream-breaks-the-circle', 'dream-lanka-shows-civic-consequences', 'en', 'Broken gates and water warn the whole city', 'Trijata sees Lanka''s gates broken and the city swallowed by the ocean while people react in confusion. The image is a warning about a ruler carrying private coercion into public catastrophe, not a wish that homes and animals be destroyed. It adds urgency to stopping Ravana because regime decisions can spread far beyond the person who made them.'),
  ('scene-trijatas-dream-breaks-the-circle', 'dream-lanka-shows-civic-consequences', 'hi', 'टूटे द्वार और जल पूरे नगर को चेताते हैं', 'त्रिजटा लंका के द्वार टूटते और नगर को समुद्र में डूबते देखती हैं, जबकि लोग भ्रम में प्रतिक्रिया देते हैं। यह किसी शासक द्वारा निजी दबाव को सार्वजनिक विपत्ति बनाने की चेतावनी है, घरों और पशुओं के विनाश की इच्छा नहीं। इससे रावण को रोकने की तात्कालिकता बढ़ती है क्योंकि शासन के निर्णय उन्हें लेने वाले व्यक्ति से बहुत दूर तक फैलते हैं।'),
  ('scene-trijatas-dream-breaks-the-circle', 'trijata-asks-for-forgiveness-not-just-fear', 'en', 'The guards are offered a different next action', 'Trijata does more than predict danger. She tells the guards to stop harsh speech, console Sita, and ask forgiveness for the threats they have made. This converts fear of defeat into a repair task they can perform now. The dream may motivate them, but apology and changed conduct—not superstition alone—are the route she offers toward survival.'),
  ('scene-trijatas-dream-breaks-the-circle', 'trijata-asks-for-forgiveness-not-just-fear', 'hi', 'पहरेदारों को अलग अगला कदम मिलता है', 'त्रिजटा केवल खतरे की भविष्यवाणी नहीं करतीं। वे पहरेदारों से कठोर वाणी रोकने, सीता को सांत्वना देने और दी धमकियों के लिए क्षमा माँगने को कहती हैं। इससे हार का भय ऐसा सुधार-कर्म बनता है जिसे वे अभी कर सकती हैं। स्वप्न उन्हें प्रेरित कर सकता है, पर केवल शकुन नहीं—क्षमा और बदला आचरण वह जीवित रहने की राह है जो त्रिजटा देती हैं।'),
  ('scene-trijatas-dream-breaks-the-circle', 'sita-promises-mercy-to-her-threateners', 'en', 'Sita answers a possible change with protection', 'Sita says that if Trijata''s vision proves true, she will protect the women who have threatened her. Mercy here is Sita''s own decision, not a duty imposed on harmed people to forgive without change. It depends on a future in which power has shifted and the guards cease the threat. Her answer reveals the kind of agency Ravana''s system has failed to extinguish.'),
  ('scene-trijatas-dream-breaks-the-circle', 'sita-promises-mercy-to-her-threateners', 'hi', 'सीता संभावित बदलाव का उत्तर संरक्षण से देती हैं', 'सीता कहती हैं कि यदि त्रिजटा का स्वप्न सत्य हुआ तो वे उन्हें धमकाने वाली स्त्रियों की रक्षा करेंगी। यहाँ दया सीता का अपना निर्णय है, पीड़ित लोगों पर बिना बदलाव क्षमा करने का थोपा कर्तव्य नहीं। वह ऐसे भविष्य पर निर्भर है जहाँ शक्ति बदली और पहरेदारों ने धमकी छोड़ी। उनका उत्तर वह सक्रियता दिखाता है जिसे रावण का तंत्र मिटा नहीं सका।'),
  ('scene-trijatas-dream-breaks-the-circle', 'hope-does-not-end-the-crisis-at-once', 'en', 'A dream cannot immediately undo captivity', 'Sita''s fear of the deadline soon returns, and she again nears a fatal decision. Trijata''s intervention has changed the social field, but guards, isolation, and uncertainty remain. The returning crisis remains non-graphic and is not a contradiction. Acute despair can return even after comfort; the need for safe, credible contact is now sharper.'),
  ('scene-trijatas-dream-breaks-the-circle', 'hope-does-not-end-the-crisis-at-once', 'hi', 'एक स्वप्न बंदीपन तुरंत नहीं मिटाता', 'सीता को समय-सीमा का भय शीघ्र फिर घेरता है और वे दोबारा एक घातक निर्णय के निकट पहुँचती हैं। त्रिजटा के हस्तक्षेप ने सामाजिक क्षेत्र बदला, पर पहरा, एकांत और अनिश्चितता बने हैं। लौटा संकट बिना भयावह विवरण रहता है और कोई विरोधाभास नहीं। सांत्वना के बाद भी तीव्र निराशा लौट सकती है; सुरक्षित, विश्वसनीय संपर्क की आवश्यकता अब और तेज है।'),
  ('scene-small-signs-return-breath', 'the-story-notices-left-side-movements', 'en', 'The body becomes readable in a new way', 'Sita''s left eye, arm, and thigh move after the long strain, and her dusty cloth shifts slightly. Sita and the surrounding story receive these changes as auspicious signs of reunion and future welfare, while no diagnostic claim is made that involuntary movement reliably predicts external events.'),
  ('scene-small-signs-return-breath', 'the-story-notices-left-side-movements', 'hi', 'शरीर को नए अर्थ में पढ़ा जाता है', 'लंबे तनाव के बाद सीता की बाईं आँख, भुजा और जाँघ फड़कती हैं तथा धूल भरा वस्त्र थोड़ा खिसकता है। इस कथा में इन हलचलों को मिलन और आगे के कल्याण के शुभ संकेत माना जाता है। वह सांस्कृतिक अर्थ स्पष्ट रहता है, पर अनैच्छिक गति बाहरी घटना निश्चित बताती है—ऐसा चिकित्सकीय या सार्वभौमिक दावा नहीं किया जाता।'),
  ('scene-small-signs-return-breath', 'omen-and-nervous-release-can-coexist', 'en', 'Meaning does not require false certainty', 'Her body also appears to release a fraction of sustained tension. The auspicious meaning and the observable easing need not be identical claims or competing ones: the signs carry hope, Sita breathes, and her posture changes, without promising that such movements predict events for everyone.'),
  ('scene-small-signs-return-breath', 'omen-and-nervous-release-can-coexist', 'hi', 'अर्थ के लिए झूठी निश्चितता आवश्यक नहीं', 'उनका शरीर लंबे तनाव से मिली थोड़ी राहत भी दिखाता है। शुभ अर्थ और दिखती सहजता न एक ही दावा हैं, न विरोधी—संकेत आशा लाते हैं, सीता साँस लेती हैं और उनकी मुद्रा बदलती है, पर ऐसी हलचलें हर व्यक्ति के लिए भविष्य की गारंटी नहीं बनतीं।'),
  ('scene-small-signs-return-breath', 'hope-returns-as-a-small-capacity', 'en', 'Sita does not leap from crisis to celebration', 'The signs do not open the gates, remove the guards, or deliver Rama. They return enough steadiness for Sita''s face, breath, and attention to change. Hope is represented as a small restored capacity to remain present for the next event, not as proof that danger has ended. This scale respects both the dream''s comfort and the continuing reality of captivity.'),
  ('scene-small-signs-return-breath', 'hope-returns-as-a-small-capacity', 'hi', 'सीता संकट से सीधे उत्सव में नहीं पहुँचतीं', 'संकेत द्वार नहीं खोलते, पहरा नहीं हटाते और राम को सामने नहीं लाते। वे इतना संतुलन लौटाते हैं कि सीता का चेहरा, साँस और ध्यान बदल सके। आशा को अगले क्षण तक उपस्थित रहने की छोटी लौटी क्षमता बनाया जाता है, खतरा समाप्त होने का प्रमाण नहीं। यह पैमाना स्वप्न की सांत्वना और बंदीपन की चलती वास्तविकता दोनों का सम्मान करता है।'),
  ('scene-small-signs-return-breath', 'the-witness-sees-a-window-open', 'en', 'Hanuman gains a moment, not permission to rush', 'From the leaves, Hanuman sees Sita move from immediate collapse toward attentive stillness. This may be the first contact window, but her calm belongs to her and cannot be seized as consent to any stranger''s appearance. He must use the opening gently, beginning with something she can recognise and stop listening to if it increases fear.'),
  ('scene-small-signs-return-breath', 'the-witness-sees-a-window-open', 'hi', 'हनुमान को एक क्षण मिलता है, जल्दबाज़ी की अनुमति नहीं', 'पत्तियों से हनुमान देखते हैं कि सीता तत्काल टूटन से ध्यानपूर्ण स्थिरता की ओर आती हैं। यह पहला संपर्क-अवसर हो सकता है, पर उनका शांत होना उनका अपना है और किसी अजनबी के सामने आने की सहमति नहीं। उन्हें अवसर को कोमलता से उपयोग करना है—ऐसी बात से शुरू करके जिसे वे पहचान सकें और भय बढ़े तो सुनना रोक सकें।'),
  ('scene-hanuman-chooses-how-to-speak', 'location-alone-is-no-longer-success', 'en', 'A sighting without consolation could still fail Sita', 'Hanuman has found Sita, mapped Lanka, measured Ravana''s power, heard the deadline, and witnessed the guards. Yet leaving now would carry data home while abandoning the person who believes no message can reach her. He decides the mission requires safe contact and a message in both directions. Success is not a scout''s completed checklist if the captive remains without truthful news.'),
  ('scene-hanuman-chooses-how-to-speak', 'location-alone-is-no-longer-success', 'hi', 'सांत्वना बिना पहचान सीता के लिए अब भी विफल हो सकती है', 'हनुमान सीता को पा, लंका का नक्शा, रावण की शक्ति, समय-सीमा और पहरे की धमकियाँ जान चुके हैं। फिर भी अभी लौटना घर तक सूचना ले जाकर उस व्यक्ति को छोड़ना होगा जो मानती हैं कि कोई संदेश उन तक नहीं पहुँच सकता। वे तय करते हैं कि अभियान को सुरक्षित संपर्क और दोनों दिशाओं का संदेश चाहिए। बंदिनी सत्य समाचार से वंचित रहे तो गुप्तचर की पूरी सूची सफलता नहीं।'),
  ('scene-hanuman-chooses-how-to-speak', 'sudden-appearance-could-repeat-the-threat', 'en', 'A rescuer''s form is not self-authenticating', 'If Hanuman drops from the tree, Sita may see another shape-changing being arriving inside her guarded space. Ravana has already used disguise and controlled appearances, so surprise would ask her to trust the very kind of event that enabled the abduction. Hanuman treats her likely fear as rational. He must establish recognition before proximity, not demand that good intention excuse a frightening entrance.'),
  ('scene-hanuman-chooses-how-to-speak', 'sudden-appearance-could-repeat-the-threat', 'hi', 'उद्धारक का रूप स्वयं प्रमाण नहीं', 'यदि हनुमान वृक्ष से उतरें तो सीता अपने पहरे वाले स्थान में एक और रूप बदलने वाले प्राणी को आते देख सकती हैं। रावण पहले छल और रूप का उपयोग कर चुका, इसलिए अचानक आना उनसे उसी तरह की घटना पर भरोसा माँगेगा जिसने हरण संभव किया। हनुमान उनके संभावित भय को तर्कसंगत मानते हैं। उन्हें निकटता से पहले पहचान बनानी है, अच्छे उद्देश्य से डरावना प्रवेश उचित नहीं ठहराना।'),
  ('scene-hanuman-chooses-how-to-speak', 'formal-speech-could-sound-like-a-disguise', 'en', 'The most prestigious register is not the safest', 'Hanuman considers a highly formal learned register, then realises it may sound like a Brahmin speaker or Ravana performing another disguise. The plot point is not a lesson in Sanskrit status. It is audience design: linguistic polish can increase suspicion when it conflicts with the speaker''s visible form and the listener''s recent trauma. Credibility depends on fit, not prestige.'),
  ('scene-hanuman-chooses-how-to-speak', 'formal-speech-could-sound-like-a-disguise', 'hi', 'सबसे प्रतिष्ठित भाषा सबसे सुरक्षित नहीं', 'हनुमान अत्यंत औपचारिक विद्वत भाषा सोचते हैं, फिर समझते हैं कि वह ब्राह्मण वक्ता या नए छल में रावण जैसी लग सकती है। कथा-बिंदु संस्कृत-प्रतिष्ठा का पाठ नहीं; श्रोता के अनुरूप रचना है—भाषाई चमक तब संदेह बढ़ा सकती है जब वक्ता के दिखते रूप और श्रोता के हाल के आघात से मेल न खाए। विश्वसनीयता पद से नहीं, संगति से आती है।'),
  ('scene-hanuman-chooses-how-to-speak', 'ordinary-language-can-carry-exact-evidence', 'en', 'Approachability does not require vagueness', 'Hanuman chooses ordinary human speech, but not empty reassurance. He can name Rama''s character, the exile, the search, Sugriva''s alliance, and details a stranger could not easily invent. Simple language lets Sita understand without surrendering accuracy. The first words can therefore be approachable, specific, and worthy of trust before any learned register is needed.'),
  ('scene-hanuman-chooses-how-to-speak', 'ordinary-language-can-carry-exact-evidence', 'hi', 'सरल भाषा को अस्पष्ट होना आवश्यक नहीं', 'हनुमान सहज मानवीय वाणी चुनते हैं, पर खोखली ढाढ़स नहीं। वे राम का स्वभाव, वनवास, खोज, सुग्रीव की मैत्री और ऐसे विवरण कह सकते हैं जिन्हें अजनबी आसानी से न गढ़ सके। सरल भाषा शुद्धता छोड़े बिना सीता को समझने देती है। इसलिए पहले शब्द सहज, विशिष्ट और भरोसे योग्य हो सकते हैं; विद्वत भाषा की आवश्यकता बाद में पड़ेगी।'),
  ('scene-hanuman-chooses-how-to-speak', 'guards-make-volume-and-timing-dangerous', 'en', 'Even true words can fail when spoken badly', 'A startled cry could bring armed guards, expose Hanuman''s route, and place Sita under harsher control. He therefore considers volume, direction, timing, and whether she can listen without revealing that she hears. Communication is staged as stealth and care rather than a speech delivered for applause. The safest message may begin as words whose speaker remains unseen.'),
  ('scene-hanuman-chooses-how-to-speak', 'guards-make-volume-and-timing-dangerous', 'hi', 'सत्य शब्द भी गलत समय पर विफल हो सकते हैं', 'चौंकी पुकार सशस्त्र पहरा बुला, हनुमान की राह खोल और सीता पर अधिक कठोर नियंत्रण ला सकती है। इसलिए वे आवाज़ की ऊँचाई, दिशा, समय और यह सोचते हैं कि क्या वे बिना सुनना प्रकट किए सुन सकती हैं। संवाद तालियों वाला भाषण नहीं, छिपाव और देखभाल बनता है। सबसे सुरक्षित संदेश उन शब्दों से शुरू हो सकता है जिनका वक्ता अभी अनदेखा रहे।'),
  ('scene-hanuman-chooses-how-to-speak', 'certain-information-must-not-be-risked-in-uncertain-battle', 'en', 'Hanuman refuses to trade a known success for combat', 'Hanuman knows he could fight many guards, but battle may exhaust, capture, or kill him, endanger Sita, and erase the only return route across the ocean. Strength does not make outcome certain. He rejects the pride of an emissary who turns verified information into an avoidable contest. The mission''s scarce asset is not destructive power; it is a living witness able to carry truth both ways.'),
  ('scene-hanuman-chooses-how-to-speak', 'certain-information-must-not-be-risked-in-uncertain-battle', 'hi', 'हनुमान पक्की सफलता को अनिश्चित युद्ध में नहीं लगाते', 'हनुमान जानते हैं कि वे अनेक पहरेदारों से लड़ सकते हैं, पर युद्ध उन्हें थका, पकड़ या मार सकता, सीता को खतरे में डाल सकता और समुद्र-पार लौटने की एकमात्र राह मिटा सकता है। बल परिणाम निश्चित नहीं करता। वे उस दूत का गर्व अस्वीकार करते हैं जो पक्की सूचना को टाले जा सकने वाले संघर्ष में लगा दे। अभियान की दुर्लभ संपत्ति विनाश-शक्ति नहीं; दोनों ओर सत्य ले जा सकने वाला जीवित साक्षी है।'),
  ('scene-hanuman-chooses-how-to-speak', 'ramas-story-becomes-the-first-bridge', 'en', 'Hanuman begins with what Sita can recognise', 'Hanuman decides to speak softly of Rama''s conduct and story from within the leaves. He will not begin with ''trust me,'' his own power, or a demand for response. Familiar, specific events can reach Sita first and let her evaluate whether the voice knows the person she knows. The turn ends as the first sweet words leave the branch; Hanuman has not yet revealed himself or earned her trust.'),
  ('scene-hanuman-chooses-how-to-speak', 'ramas-story-becomes-the-first-bridge', 'hi', 'हनुमान उस कथा से शुरू करते हैं जिसे सीता पहचान सकती हैं', 'हनुमान पत्तियों के भीतर से राम के आचरण और कथा को धीरे कहना तय करते हैं। वे ‘मुझ पर भरोसा करो’, अपनी शक्ति या उत्तर की माँग से शुरू नहीं करेंगे। परिचित, विशिष्ट घटनाएँ पहले सीता तक पहुँचकर उन्हें परखने देंगी कि आवाज़ उस व्यक्ति को जानती है जिसे वे जानती हैं। चरण शाखा से निकलते पहले कोमल शब्दों पर समाप्त होता है; हनुमान अभी सामने नहीं आए और विश्वास अर्जित नहीं हुआ।'),
  ('scene-ramas-story-reaches-sita', 'the-first-words-protect-distance', 'en', 'The voice arrives before the stranger', 'Hanuman begins from inside the shimshapa, speaking softly enough for Sita to hear without exposing her attention to the guards. He does not drop beside her, announce his strength, or demand an answer. The first contact preserves distance and gives Sita time to recognise, reject, or keep listening to a voice whose owner she cannot yet see.'),
  ('scene-ramas-story-reaches-sita', 'the-first-words-protect-distance', 'hi', 'अजनबी से पहले आवाज पहुँचती है', 'हनुमान शीशम की ओट से इतनी धीमी वाणी में शुरू करते हैं कि सीता सुन सकें और पहरेदार उनका ध्यान न पकड़ें। वे पास कूदकर अपनी शक्ति नहीं बताते और उत्तर नहीं माँगते। पहला संपर्क दूरी बचाता है तथा सीता को अनदेखे वक्ता की बात पहचानने, अस्वीकार करने या सुनते रहने का समय देता है।'),
  ('scene-ramas-story-reaches-sita', 'dasharathas-house-opens-the-account', 'en', 'The account begins before the abduction', 'The voice names Dasharatha and Rama of the Ikshvaku line, then recalls the eldest son''s commitment to truth, protection, kin, and public duty. These are not empty praises floating in Lanka: they establish the household and person Sita knows before describing what broke. A captor could repeat a famous name, but the ordered life around that name can be checked.'),
  ('scene-ramas-story-reaches-sita', 'dasharathas-house-opens-the-account', 'hi', 'कथा हरण से पहले शुरू होती है', 'आवाज इक्ष्वाकु वंश के दशरथ और राम का नाम लेकर ज्येष्ठ पुत्र की सत्य, संरक्षण, परिवार और लोक-कर्तव्य के प्रति निष्ठा याद करती है। यह लंका में तैरती खोखली प्रशंसा नहीं; आगे क्या टूटा, उससे पहले उस घर और व्यक्ति को रखती है जिन्हें सीता जानती हैं। अपहरणकर्ता प्रसिद्ध नाम दोहरा सकता है, पर उस नाम का क्रमबद्ध जीवन परखा जा सकता है।'),
  ('scene-ramas-story-reaches-sita', 'exile-and-abduction-are-placed-in-order', 'en', 'Exile leads to the broken hermitage', 'Hanuman recounts that Rama obeyed his father''s forest command with Sita and Lakshmana beside him, fought the Janasthana force, and was drawn away before Ravana seized Sita from the unprotected hermitage. The sequence names deception and unequal access instead of making disappearance mysterious or blaming the person taken.'),
  ('scene-ramas-story-reaches-sita', 'exile-and-abduction-are-placed-in-order', 'hi', 'वनवास टूटी कुटिया तक पहुँचता है', 'हनुमान बताते हैं कि राम ने पिता की वन-आज्ञा मानी, सीता और लक्ष्मण साथ चले, जनस्थान की सेना से संघर्ष हुआ और फिर राम को दूर खींचकर रावण ने असुरक्षित कुटिया से सीता का हरण किया। यह क्रम छल और असमान पहुँच का नाम लेता है; गायब होने को रहस्य नहीं बनाता और ले जाई गई व्यक्ति को दोष नहीं देता।'),
  ('scene-ramas-story-reaches-sita', 'alliance-turns-grief-into-search', 'en', 'Rama''s grief enters an organised alliance', 'The hidden speaker says Rama met Sugriva, helped restore his kingdom after Vali''s death, and gained a friend who sent thousands of vanaras in every direction. The account does not offer grief alone as proof of devotion. It follows grief into agreements, messengers, routes, deadlines, and collective labour that can actually reach a captive person.'),
  ('scene-ramas-story-reaches-sita', 'alliance-turns-grief-into-search', 'hi', 'राम का शोक संगठित मैत्री में बदलता है', 'छिपी आवाज कहती है कि राम सुग्रीव से मिले, वाली की मृत्यु के बाद उनका राज्य लौटाने में सहायता की और ऐसे मित्र पाए जिसने हजारों वानरों को हर दिशा में भेजा। केवल शोक को निष्ठा का प्रमाण नहीं बनाया जाता। शोक मैत्री, दूत, मार्ग, समय-सीमा और उस सामूहिक श्रम में बदलता है जो वास्तव में बंदी व्यक्ति तक पहुँच सकता है।'),
  ('scene-ramas-story-reaches-sita', 'sampati-and-the-crossing-make-the-voice-specific', 'en', 'The voice knows how Lanka was found', 'Hanuman names Sampati as the one who revealed Sita''s location and says he crossed a hundred leagues of ocean because of that lead. These details join people and places Sita could not have supplied to a stranger in the grove. The voice is no longer merely comforting; it carries a traceable route from the southern search to this exact tree.'),
  ('scene-ramas-story-reaches-sita', 'sampati-and-the-crossing-make-the-voice-specific', 'hi', 'आवाज जानती है कि लंका कैसे मिली', 'हनुमान संपाति को सीता का स्थान बताने वाला कहते हैं और बताते हैं कि उसी संकेत पर वे सौ योजन समुद्र पार आए। ये विवरण उन लोगों और स्थानों को जोड़ते हैं जिन्हें सीता वाटिका के किसी अजनबी को नहीं बता सकती थीं। आवाज केवल सांत्वना नहीं रहती; दक्षिणी खोज से इसी वृक्ष तक की जाँची जा सकने वाली राह बनती है।'),
  ('scene-ramas-story-reaches-sita', 'sita-follows-the-words-upward', 'en', 'Silence gives Sita the next move', 'After saying that Rama''s remembered signs match the woman below, Hanuman stops. He leaves a silence in which Sita can decide what the words mean. She lifts her face, searches every direction, and finally looks into the shimshapa. There she sees a small luminous figure among the leaves; the account has reached a visible speaker, but trust has not yet followed automatically.'),
  ('scene-ramas-story-reaches-sita', 'sita-follows-the-words-upward', 'hi', 'मौन सीता को अगला कदम देता है', 'नीचे बैठी स्त्री को राम के स्मृत संकेतों से मिलाने के बाद हनुमान रुक जाते हैं। वे ऐसा मौन छोड़ते हैं जिसमें सीता शब्दों का अर्थ स्वयं तय कर सकें। वे चेहरा उठाकर दिशाएँ देखती और अंततः शीशम में नज़र डालती हैं। पत्तियों में छोटा प्रकाशमान रूप दिखता है; कथा को वक्ता मिल गया, पर विश्वास अपने-आप नहीं आया।'),
  ('scene-sita-tests-what-she-sees', 'an-unfamiliar-form-reopens-danger', 'en', 'The visible stranger is frightening', 'Sita sees a tawny monkey-shaped figure in white cloth watching from the tree. Lanka has already taught her that appearances can be manufactured and that a visitor may approach in disguise. The gentle voice does not cancel the unfamiliar form. Her breath shortens, she calls for Rama and Lakshmana, and she allows fear to challenge the hope the words created.'),
  ('scene-sita-tests-what-she-sees', 'an-unfamiliar-form-reopens-danger', 'hi', 'दिखता अजनबी भय जगाता है', 'सीता वृक्ष में श्वेत वस्त्र पहने ताम्रवर्ण वानर-रूप को देखते हैं। लंका उन्हें सिखा चुकी है कि रूप गढ़े जा सकते हैं और आगंतुक वेश में आ सकता है। कोमल आवाज अपरिचित रूप को रद्द नहीं करती। उनकी साँस अटकती, वे राम-लक्ष्मण को पुकारती और भय को शब्दों से बनी आशा पर प्रश्न करने देती हैं।'),
  ('scene-sita-tests-what-she-sees', 'dream-tradition-is-one-possible-reading', 'en', 'An omen tradition enters the test', 'Sita wonders whether she is dreaming and recalls a tradition in which seeing a monkey in a dream is inauspicious. Within her world, that association makes her immediately fear for Rama, Lakshmana, and Janaka. It is her culturally available interpretation under pressure, not a universal prediction offered to everyone who dreams of an animal.'),
  ('scene-sita-tests-what-she-sees', 'dream-tradition-is-one-possible-reading', 'hi', 'शकुन-परंपरा जाँच में आती है', 'सीता सोचती हैं कि क्या यह स्वप्न है और उस परंपरा को याद करती हैं जिसमें स्वप्न में वानर दिखना अशुभ माना जाता है। उनके संसार में यह संबंध तुरंत राम, लक्ष्मण और जनक की चिंता जगाता है। यह दबाव में उपलब्ध सांस्कृतिक अर्थ है, हर व्यक्ति के पशु-स्वप्न के लिए सार्वभौमिक भविष्यवाणी नहीं।'),
  ('scene-sita-tests-what-she-sees', 'grief-can-fill-sight-and-sound', 'en', 'Longing offers another explanation', 'Because Sita thinks and speaks of Rama constantly, she asks whether longing now makes every sight and sound resemble him. The possibility respects how isolation and repetition can shape attention without calling her irrational. She is checking whether the voice carries information from outside or whether her own exhausted mind assembled what she most needed to hear.'),
  ('scene-sita-tests-what-she-sees', 'grief-can-fill-sight-and-sound', 'hi', 'लंबी प्रतीक्षा दूसरी व्याख्या देती है', 'सीता लगातार राम को सोचती और उनका नाम लेती हैं, इसलिए पूछती हैं कि क्या लालसा हर दृश्य और ध्वनि को उन्हीं जैसा बना रही है। यह संभावना एकांत और दोहराव से ध्यान बदलने को मानती है, उन्हें अतार्किक नहीं कहती। वे जाँचती हैं कि आवाज बाहर का समाचार लाई है या थके मन ने वही जोड़ लिया जिसकी सबसे अधिक आवश्यकता थी।'),
  ('scene-sita-tests-what-she-sees', 'the-form-persists-under-attention', 'en', 'The figure remains when tested', 'Sita looks again. The figure keeps its place, shape, clothing, direction, and relation to the moving branches. It has not dissolved when attention changes. She distinguishes an external presence from a passing image while still refusing to decide who the presence serves. Reality of the visitor and trustworthiness of the visitor are two different conclusions.'),
  ('scene-sita-tests-what-she-sees', 'the-form-persists-under-attention', 'hi', 'परखने पर रूप बना रहता है', 'सीता फिर देखती हैं। रूप अपनी जगह, आकार, वस्त्र, दिशा और हिलती शाखाओं से संबंध बनाए रखता है; ध्यान बदलने पर मिटता नहीं। वे क्षणिक छवि से बाहरी उपस्थिति अलग करती हैं, फिर भी यह तय नहीं करतीं कि आगंतुक किसके लिए आया है। आगंतुक का वास्तविक होना और विश्वसनीय होना दो अलग निष्कर्ष हैं।'),
  ('scene-sita-tests-what-she-sees', 'prayer-keeps-hope-open-without-ending-inquiry', 'en', 'Sita asks that the words be real', 'Sita invokes powers connected with speech, fire, order, and protection, asking that the creature''s words prove real. The prayer does not replace investigation; it gives hope a form while she remains observant. She neither dismisses the possible messenger nor hands him immediate access. Her next safety comes from letting him approach slowly and answer what only a true route from Rama could explain.'),
  ('scene-sita-tests-what-she-sees', 'prayer-keeps-hope-open-without-ending-inquiry', 'hi', 'सीता कामना करती हैं कि शब्द सच हों', 'सीता वाणी, अग्नि, व्यवस्था और संरक्षण से जुड़े देवताओं का स्मरण करके कामना करती हैं कि प्राणी के शब्द सच हों। प्रार्थना जाँच का स्थान नहीं लेती; सावधान रहते हुए आशा को रूप देती है। वे संभावित दूत को न हटाती हैं, न तुरंत पहुँच देती हैं। अगली सुरक्षा इस बात में है कि वह धीरे आए और वही समझाए जो राम से आई सच्ची राह जान सकती है।'),
  ('scene-sita-tells-her-own-road', 'hanuman-descends-without-taking-access', 'en', 'A respectful approach remains an approach', 'Hanuman comes down in a small, humble form, joins his palms, and stops at speaking distance. He notices tears, worn cloth, the branch Sita holds, and her guarded position, then asks rather than declares who she is. His reverence reduces threat but does not entitle him to closeness; Sita still controls whether the conversation continues.'),
  ('scene-sita-tells-her-own-road', 'hanuman-descends-without-taking-access', 'hi', 'सम्मानपूर्ण निकटता भी अनुमति माँगती है', 'हनुमान छोटे विनम्र रूप में उतरकर हाथ जोड़ते और बात की दूरी पर रुकते हैं। वे आँसू, घिसे वस्त्र, पकड़ी शाखा और पहरे वाली जगह देखते हैं, फिर पहचान घोषित करने के बजाय पूछते हैं। उनका सम्मान खतरा घटाता है, निकटता का अधिकार नहीं देता; संवाद आगे बढ़े या नहीं, यह सीता तय करती हैं।'),
  ('scene-sita-tells-her-own-road', 'the-question-leaves-celestial-catalogues-behind', 'en', 'Hanuman asks who sits before him', 'Hanuman first reaches for courtly comparisons—stars, celestial women, and royal signs—then asks the questions that matter in the grove: who is she, why is she grieving, and whom does she hope to reach? Sita can answer with names, relationships, events, and the danger around her. Hanuman waits for her to tell the story in her own order.'),
  ('scene-sita-tells-her-own-road', 'the-question-leaves-celestial-catalogues-behind', 'hi', 'हनुमान सामने बैठी स्त्री का परिचय पूछते हैं', 'हनुमान पहले राजदरबार जैसी उपमाएँ देते हैं—तारे, दिव्य स्त्रियाँ और राजसी चिह्न—फिर वाटिका के जरूरी प्रश्न पूछते हैं: वे कौन हैं, क्यों दुखी हैं और किस तक पहुँचना चाहती हैं? सीता नाम, संबंध, घटनाएँ और अपने चारों ओर का खतरा बता सकती हैं। हनुमान प्रतीक्षा करते हैं कि वे अपनी कथा अपने क्रम में सुनाएँ।'),
  ('scene-sita-tells-her-own-road', 'sita-names-herself-and-her-houses', 'en', 'Sita answers in her own voice', 'Sita says she is Janaka''s daughter, Dasharatha''s daughter-in-law, and Rama''s wife, then gives her own name. The relationships locate her without exhausting her identity. More importantly, she begins telling what she witnessed and chose. The stranger must now match not a portrait of Sita but a first-person history whose order matters.'),
  ('scene-sita-tells-her-own-road', 'sita-names-herself-and-her-houses', 'hi', 'सीता अपनी आवाज में उत्तर देती हैं', 'सीता कहती हैं कि वे जनक की पुत्री, दशरथ की पुत्रवधू और राम की पत्नी हैं, फिर अपना नाम बताती हैं। संबंध उन्हें स्थित करते हैं, उनकी पूरी पहचान नहीं बनते। अधिक महत्त्वपूर्ण यह कि वे अपने देखे और चुने प्रसंग सुनाती हैं। अब अजनबी को सीता की तस्वीर नहीं, क्रम वाली प्रथम-पुरुष कथा से मेल खाना है।'),
  ('scene-sita-tells-her-own-road', 'a-coronation-collapses-into-exile', 'en', 'Ayodhya''s prepared future breaks', 'Sita recalls years in Ayodhya and the preparations to install Rama, followed by Kaikeyi''s demand that an old promise be honoured through exile. Dasharatha is overcome; Rama chooses to keep the command rather than seize the crown. Sita is not a silent parcel handed between households: she puts on forest clothing and moves before Rama rather than remain behind.'),
  ('scene-sita-tells-her-own-road', 'a-coronation-collapses-into-exile', 'hi', 'अयोध्या का तैयार भविष्य टूटता है', 'सीता अयोध्या के वर्षों और राम के राज्याभिषेक की तैयारी याद करती हैं, फिर कैकेयी की वह माँग जिसमें पुराने वचन के कारण वनवास आता है। दशरथ टूटते हैं; राम मुकुट लेने के बजाय आज्ञा निभाते हैं। सीता घरों के बीच सौंपी मौन वस्तु नहीं—वे वन-वस्त्र पहनकर पीछे रहने के बजाय राम से पहले चल पड़ती हैं।'),
  ('scene-sita-tells-her-own-road', 'three-people-enter-the-forest-by-distinct-choices', 'en', 'The forest party is formed by decisions', 'Lakshmana also takes bark and joins the road, motivated by care for his elder brother and Sita. The three share the journey, but not one merged will: Rama responds to the command, Sita refuses separation, and Lakshmana chooses service and protection. Their distinct decisions matter when Sita later asks whether news has reached each of them.'),
  ('scene-sita-tells-her-own-road', 'three-people-enter-the-forest-by-distinct-choices', 'hi', 'वन-दल अलग निर्णयों से बनता है', 'लक्ष्मण भी वल्कल पहनकर बड़े भाई और सीता की देखभाल के लिए मार्ग में जुड़ते हैं। तीनों यात्रा साझा करते हैं, पर उनकी इच्छा एक नहीं—राम आज्ञा का उत्तर देते, सीता अलगाव अस्वीकार करती और लक्ष्मण सेवा तथा संरक्षण चुनते हैं। बाद में सीता जब हर व्यक्ति का समाचार पूछती हैं, ये अलग निर्णय महत्त्व रखते हैं।'),
  ('scene-sita-tells-her-own-road', 'sita-states-abduction-and-the-clock', 'en', 'Her account reaches the present danger', 'Sita ends with Ravana taking her from Dandaka and the lethal deadline now imposed in Lanka. She does not soften the threat or turn it into fate. By giving the remaining time to the possible messenger, she converts personal terror into operational information. The conversation now has an identity, a crime, a location, and a clock that can be carried outward.'),
  ('scene-sita-tells-her-own-road', 'sita-states-abduction-and-the-clock', 'hi', 'उनकी कथा वर्तमान खतरे तक पहुँचती है', 'सीता अपनी कथा रावण द्वारा दंडक से हरण और लंका में थोपी घातक समय-सीमा पर लाती हैं। वे धमकी को नरम या भाग्य नहीं बनातीं। संभावित दूत को बचा समय बताकर निजी भय को कार्यकारी सूचना में बदलती हैं। अब संवाद में पहचान, अपराध, स्थान और बाहर ले जाई जा सकने वाली घड़ी है।'),
  ('scene-trust-opens-and-closes', 'hanuman-delivers-welfare-before-promises', 'en', 'The first answer is that they live', 'Hanuman says he comes by Rama''s direction, that Rama is alive, and that Lakshmana bows and asks after Sita''s welfare. He begins with information that directly answers the uncertainty crushing her rather than with victory claims. The news restores a missing fact: the people outside the grove remember her and have sent a living messenger toward her.'),
  ('scene-trust-opens-and-closes', 'hanuman-delivers-welfare-before-promises', 'hi', 'पहला उत्तर है कि वे जीवित हैं', 'हनुमान कहते हैं कि वे राम की आज्ञा से आए, राम जीवित हैं और लक्ष्मण प्रणाम करके सीता का कुशल पूछते हैं। वे विजय-दावों से नहीं, उस अनिश्चितता के सीधे उत्तर से शुरू करते हैं जो उन्हें तोड़ रही थी। समाचार खोया तथ्य लौटाता है—वाटिका के बाहर लोग उन्हें याद करते और जीवित दूत भेज चुके हैं।'),
  ('scene-trust-opens-and-closes', 'joy-does-not-cancel-caution', 'en', 'Relief and vigilance coexist', 'Sita experiences a rush of joy at hearing both names and begins a more confidential exchange. The relief is real, but it is not a permanent authentication token. Captivity has repeatedly punished trust, and a truthful fragment can still be used by someone serving Ravana. Her openness remains conditional on what Hanuman does next.'),
  ('scene-trust-opens-and-closes', 'joy-does-not-cancel-caution', 'hi', 'राहत और सावधानी साथ रहती हैं', 'दोनों नाम सुनकर सीता में आनंद की लहर आती और संवाद अधिक निजी होता है। राहत वास्तविक है, पर स्थायी पहचान-पत्र नहीं। बंदीपन ने विश्वास को बार-बार दंडित किया है और सच्चा अंश भी रावण का व्यक्ति उपयोग कर सकता है। उनका खुलापन हनुमान के अगले आचरण पर निर्भर रहता है।'),
  ('scene-trust-opens-and-closes', 'one-step-closer-repeats-an-old-pattern', 'en', 'Approach changes the meaning again', 'When Hanuman moves nearer, Sita remembers Ravana entering Janasthana as a mendicant before revealing another form. A visitor who knows names and changes appearance can fit that earlier attack. She releases the branch, sits on the earth, turns away, and stops rewarding the conversation with attention. Her withdrawal is a safety decision, not ingratitude.'),
  ('scene-trust-opens-and-closes', 'one-step-closer-repeats-an-old-pattern', 'hi', 'पास आना अर्थ फिर बदल देता है', 'हनुमान पास आते हैं तो सीता को जनस्थान में भिक्षु बनकर आए और फिर रूप बदलने वाले रावण की याद आती है। नाम जानने और रूप बदलने वाला आगंतुक उस पुराने आक्रमण से मेल खा सकता है। वे शाखा छोड़कर धरती पर बैठती, मुँह फेरती और ध्यान रोकती हैं। पीछे हटना सुरक्षा का निर्णय है, अकृतज्ञता नहीं।'),
  ('scene-trust-opens-and-closes', 'sita-names-the-suspicion-directly', 'en', 'The possible deception is spoken aloud', 'Sita tells the visitor that if he is Ravana in another form, distressing a fasting captive again is a further wrong. Naming the suspicion prevents politeness from trapping her inside a dangerous exchange. At the same time, she admits that hearing of Rama has brought genuine joy and asks for more if he truly is the messenger. Doubt and desire for news remain side by side.'),
  ('scene-trust-opens-and-closes', 'sita-names-the-suspicion-directly', 'hi', 'संभावित छल खुलकर कहा जाता है', 'सीता आगंतुक से कहती हैं कि यदि वह दूसरे रूप में रावण है तो उपवास करती बंदिनी को फिर सताना नया अन्याय है। संदेह का नाम लेना शिष्टता को खतरनाक संवाद का जाल नहीं बनने देता। साथ ही वे मानती हैं कि राम का समाचार सच्चा आनंद लाया और यदि वह दूत है तो अधिक बताने को कहती हैं। संदेह और समाचार की इच्छा साथ रहती हैं।'),
  ('scene-trust-opens-and-closes', 'hanuman-answers-with-a-living-rama', 'en', 'Character is described through conduct', 'Hanuman describes Rama as truthful, protective, generous, disciplined in anger, and capable of acting against the person who engineered the abduction. The useful evidence is not an idealised body catalogue but a pattern of conduct Sita knows across palace and forest. He also names Lakshmana''s grief, Sugriva''s friendship, and the shared search that brought him here.'),
  ('scene-trust-opens-and-closes', 'hanuman-answers-with-a-living-rama', 'hi', 'राम का परिचय आचरण से मिलता है', 'हनुमान राम को सत्यनिष्ठ, संरक्षक, उदार, क्रोध में संयमी और हरण रचने वाले के विरुद्ध कार्रवाई में सक्षम बताते हैं। उपयोगी प्रमाण आदर्श शरीर की सूची नहीं, महल और वन में सीता द्वारा जाना आचरण है। वे लक्ष्मण का शोक, सुग्रीव की मैत्री और उन्हें यहाँ लाने वाली साझा खोज भी बताते हैं।'),
  ('scene-trust-opens-and-closes', 'identity-is-offered-not-imposed', 'en', 'Hanuman gives a name and route', 'Hanuman identifies himself as Sugriva''s minister, says he crossed the ocean and entered Lanka, and denies being Ravana. The denial alone cannot settle the question, so he invites Sita to compare his account with details only the search network would know. He does not punish her suspicion. Trust will depend on whether the next answers survive her tests.'),
  ('scene-trust-opens-and-closes', 'identity-is-offered-not-imposed', 'hi', 'हनुमान नाम और राह देते हैं', 'हनुमान अपना परिचय सुग्रीव के मंत्री के रूप में देते, समुद्र पार कर लंका में आने की बात कहते और रावण होने से इनकार करते हैं। केवल इनकार प्रश्न नहीं सुलझाता, इसलिए वे सीता को कथा उन विवरणों से मिलाने देते हैं जिन्हें खोज-जाल जान सकता है। वे संदेह पर उन्हें दंडित नहीं करते। विश्वास अगले उत्तरों की परीक्षा पर निर्भर रहेगा।'),
  ('scene-the-search-chain-becomes-proof', 'sita-sets-the-authentication-question', 'en', 'How did humans and vanaras meet?', 'Sita asks where Hanuman met Rama, how he knows Lakshmana, and how the human princes formed brotherhood with the vanaras. She also asks for recognisable qualities of both brothers. The questions require a relational history, not a password. A convincing answer must connect people, motives, places, and consequences in the right order.'),
  ('scene-the-search-chain-becomes-proof', 'sita-sets-the-authentication-question', 'hi', 'मनुष्य और वानर कैसे मिले?', 'सीता पूछती हैं कि हनुमान राम से कहाँ मिले, लक्ष्मण को कैसे जानते और मानव राजकुमारों की वानरों से मैत्री कैसे बनी। वे दोनों भाइयों के पहचाने गुण भी पूछती हैं। प्रश्न किसी गुप्त शब्द नहीं, संबंध का इतिहास माँगते हैं। सही उत्तर को लोग, उद्देश्य, स्थान और परिणाम उचित क्रम में जोड़ने होंगे।'),
  ('scene-the-search-chain-becomes-proof', 'recognition-uses-conduct-not-anatomy', 'en', 'Hanuman describes the brothers she knows', 'Hanuman speaks of Rama''s patience, truthfulness, practical judgment, protection of others, disciplined speech, and knowledge of duty. He says Lakshmana shares his brother''s courage and has stayed beside him through exile and the search. These familiar habits and choices give Sita something she can compare with the men she knows, before Hanuman recounts the events that brought them together.'),
  ('scene-the-search-chain-becomes-proof', 'recognition-uses-conduct-not-anatomy', 'hi', 'हनुमान उन भाइयों का परिचय देते हैं जिन्हें सीता जानती हैं', 'हनुमान राम का धैर्य, सत्य, व्यवहार-बुद्धि, दूसरों की रक्षा, संयत वाणी और कर्तव्य-ज्ञान बताते हैं। वे कहते हैं कि लक्ष्मण अपने भाई जैसा साहस रखते हैं और वनवास से खोज तक उनके साथ रहे हैं। ये परिचित स्वभाव और निर्णय सीता को उन भाइयों से बात मिलाने देते हैं जिन्हें वे जानती हैं; फिर हनुमान उनके मिलन की घटनाएँ सुनाते हैं।'),
  ('scene-the-search-chain-becomes-proof', 'rishyamuka-connects-two-exiles', 'en', 'Hanuman approached the armed strangers first', 'Hanuman recounts finding Rama and Lakshmana near Rishyamuka while Sugriva lived there in fear of Vali. Sugriva sent Hanuman to learn who the bow-carrying strangers were. Hanuman spoke, heard Lakshmana explain Sita''s abduction, carried the brothers to the hill, and helped two displaced parties recognise a possible alliance.'),
  ('scene-the-search-chain-becomes-proof', 'rishyamuka-connects-two-exiles', 'hi', 'हनुमान पहले सशस्त्र अजनबियों के पास गए', 'हनुमान बताते हैं कि ऋष्यमूक के पास राम-लक्ष्मण मिले, जहाँ सुग्रीव वाली के भय से रहते थे। सुग्रीव ने धनुषधारी अजनबियों की पहचान जानने के लिए हनुमान को भेजा। हनुमान ने बात की, लक्ष्मण से सीता का हरण सुना, भाइयों को पर्वत तक ले गए और दो विस्थापित पक्षों को संभावित मैत्री पहचानने में सहायता की।'),
  ('scene-the-search-chain-becomes-proof', 'the-ornaments-link-sita-to-the-alliance', 'en', 'Objects thrown during abduction reappear', 'Hanuman says the vanara leaders had gathered the ornaments Sita dropped while being carried south. When Rama saw them, grief overwhelmed him; Hanuman and the others helped him stand, and the objects were kept within Sugriva''s circle. This is a cross-check Sita alone understands from one side and the search party from the other.'),
  ('scene-the-search-chain-becomes-proof', 'the-ornaments-link-sita-to-the-alliance', 'hi', 'हरण में फेंकी वस्तुएँ फिर सामने आती हैं', 'हनुमान कहते हैं कि दक्षिण ले जाए जाते समय सीता के गिराए आभूषण वानर-नेताओं ने समेटे थे। उन्हें देखकर राम शोक में गिर पड़े; हनुमान और साथियों ने संभाला तथा वस्तुएँ सुग्रीव के समूह में सुरक्षित रहीं। यह ऐसा मिलान है जिसका एक सिरा सीता जानती हैं और दूसरा खोज-दल।'),
  ('scene-the-search-chain-becomes-proof', 'alliance-carries-obligations-in-both-directions', 'en', 'Sugriva''s restoration becomes a search duty', 'Rama and Sugriva share their losses and make an agreement: help against Vali and help finding Sita. Vali dies, Sugriva becomes king, and the promised search must then become real. Hanuman tells the chain without pretending every decision inside it is beyond question. What authenticates him is his place within consequences Sita''s disappearance set in motion.'),
  ('scene-the-search-chain-becomes-proof', 'alliance-carries-obligations-in-both-directions', 'hi', 'सुग्रीव का राज्य लौटना खोज-कर्तव्य बनता है', 'राम और सुग्रीव अपनी हानियाँ साझा करके समझौता करते हैं—वाली के विरुद्ध सहायता और सीता की खोज। वाली की मृत्यु होती, सुग्रीव राजा बनते और खोज का वचन अब कार्य बनना होता है। हनुमान हर निर्णय को प्रश्न से परे नहीं बताते। उनकी पहचान उन परिणामों में उनकी जगह से बनती है जिन्हें सीता के गायब होने ने गति दी।'),
  ('scene-the-search-chain-becomes-proof', 'the-southern-search-nearly-collapses', 'en', 'Failure reaches the edge without becoming virtue', 'Hanuman describes Angada''s southern force losing time around Vindhya, missing its deadline, and reaching despair so severe that the group stopped eating and expected death. The crisis is part of how he knows the route, not a model of dedication to imitate. Jatayu''s name then interrupts the collapse by drawing Sampati into their story.'),
  ('scene-the-search-chain-becomes-proof', 'the-southern-search-nearly-collapses', 'hi', 'विफलता सीमा तक पहुँचती है, सद्गुण नहीं बनती', 'हनुमान बताते हैं कि अंगद का दक्षिणी दल विंध्य के आसपास समय खोकर समय-सीमा चूकता और ऐसी निराशा तक पहुँचता है कि भोजन रोककर मृत्यु की प्रतीक्षा करने लगता है। यह संकट राह मिलने की कथा का हिस्सा है, अनुकरण योग्य निष्ठा नहीं। तभी जटायु का नाम संपाति को उनकी कथा में लाकर टूटन रोकता है।'),
  ('scene-the-search-chain-becomes-proof', 'sampati-supplies-the-missing-location', 'en', 'A witness turns grief into direction', 'Sampati first asks how Jatayu died, hears that he resisted Sita''s abduction, and then reveals that Sita is held in Ravana''s Lanka across the sea. The brother''s grief produces testimony rather than ending the mission. The vanaras move from the mountain to the coast with a location they did not possess before.'),
  ('scene-the-search-chain-becomes-proof', 'sampati-supplies-the-missing-location', 'hi', 'साक्षी शोक को दिशा में बदलता है', 'संपाति पहले पूछते हैं कि जटायु कैसे मरे, सुनते हैं कि उन्होंने सीता के हरण का विरोध किया और फिर बताते हैं कि सीता समुद्र पार रावण की लंका में हैं। भाई का शोक अभियान समाप्त नहीं, गवाही देता है। वानर उस नए स्थान-ज्ञान के साथ पर्वत से तट तक पहुँचते हैं जो पहले उनके पास नहीं था।'),
  ('scene-the-search-chain-becomes-proof', 'the-route-ends-in-a-question-for-sita', 'en', 'Hanuman reaches the grove and yields the floor', 'Hanuman recounts the ocean crossing, entry into guarded Lanka, observation of Ravana, and discovery of Sita exactly where the chain predicted. Family origin and feats may decorate his identity, but the decisive evidence is the route that keeps matching independent facts. He ends by asking what Sita wants done and carried back; trust becomes a two-way mission rather than applause for him.'),
  ('scene-the-search-chain-becomes-proof', 'the-route-ends-in-a-question-for-sita', 'hi', 'हनुमान वाटिका पहुँचकर सीता को बोलने देते हैं', 'हनुमान समुद्र-पार, पहरे वाली लंका में प्रवेश, रावण को देखने और कड़ी द्वारा बताए स्थान पर सीता को पाने का क्रम कहते हैं। वंश और पराक्रम परिचय सजा सकते हैं, पर निर्णायक प्रमाण वह राह है जो स्वतंत्र तथ्यों से मिलती रहती है। अंत में वे पूछते हैं कि सीता क्या करवाना और वापस भिजवाना चाहती हैं; विश्वास उनकी प्रशंसा नहीं, दो-तरफा अभियान बनता है।'),
  ('scene-ramas-ring-enters-sitas-hand', 'the-ring-is-presented-as-a-token', 'en', 'Rama''s name crosses the ocean on metal', 'Hanuman offers the ring engraved with Rama''s name and says Rama entrusted it to him for Sita. He does not secretly place it on her or treat it as a command. Sita chooses to take it and recognises an object that belonged on Rama''s hand. The ring adds material continuity to the route Hanuman has already explained.'),
  ('scene-ramas-ring-enters-sitas-hand', 'the-ring-is-presented-as-a-token', 'hi', 'राम का नाम धातु पर समुद्र पार आता है', 'हनुमान राम के नाम वाली मुद्रिका सामने रखकर कहते हैं कि राम ने उसे सीता के लिए सौंपा। वे चुपके से पहनाते या आदेश नहीं बनाते। सीता उसे लेना चुनती और राम के हाथ की वस्तु पहचानती हैं। मुद्रिका हनुमान द्वारा बताई राह में भौतिक निरंतरता जोड़ती है।'),
  ('scene-ramas-ring-enters-sitas-hand', 'recognition-is-emotional-and-evidential', 'en', 'The object feels like contact without becoming magic', 'Looking at the familiar ring, Sita briefly feels as if Rama himself has reached the grove. Her delight comes from memory, touch, and the knowledge that he selected this object for the message. Yet the ring works because it agrees with Hanuman''s detailed account; an isolated object could be stolen. Trust rests on convergence, not on jewellery possessing supernatural certainty.'),
  ('scene-ramas-ring-enters-sitas-hand', 'recognition-is-emotional-and-evidential', 'hi', 'वस्तु संपर्क जैसी लगती है, जादू नहीं बनती', 'परिचित मुद्रिका देखकर सीता को क्षण भर लगता है मानो राम स्वयं वाटिका पहुँच गए। आनंद स्मृति, स्पर्श और यह जानने से आता है कि उन्होंने संदेश के लिए यही वस्तु चुनी। फिर भी मुद्रिका इसलिए काम करती है कि हनुमान की विस्तृत कथा से मेल खाती है; अकेली वस्तु चुराई जा सकती थी। विश्वास कई प्रमाणों के मेल पर है, आभूषण के जादुई निश्चय पर नहीं।'),
  ('scene-ramas-ring-enters-sitas-hand', 'sita-recognises-the-messenger', 'en', 'Hanuman''s risk and judgment are acknowledged', 'Sita welcomes Hanuman as the messenger Rama tested and sent, recognising that he crossed the sea, entered Ravana''s city alone, observed before acting, and stayed through her suspicion. She praises competence without surrendering authority over the mission. Acceptance means she will now entrust questions and a reply, not that every future suggestion must be obeyed.'),
  ('scene-ramas-ring-enters-sitas-hand', 'sita-recognises-the-messenger', 'hi', 'हनुमान के जोखिम और निर्णय को मान्यता मिलती है', 'सीता हनुमान का राम द्वारा परखा और भेजा दूत के रूप में स्वागत करती हैं—समुद्र पार करना, रावण के नगर में अकेले आना, कार्रवाई से पहले देखना और उनके संदेह के बीच ठहरना मानती हैं। वे क्षमता की प्रशंसा करती हैं, अभियान पर अधिकार नहीं छोड़तीं। स्वीकृति का अर्थ प्रश्न और उत्तर सौंपना है, हर अगली सलाह मानना नहीं।'),
  ('scene-ramas-ring-enters-sitas-hand', 'sita-asks-the-questions-isolation-created', 'en', 'Relief releases a flood of practical questions', 'Sita asks whether Rama and Lakshmana are safe, whether grief has weakened action, whether allies still gather, whether Sugriva will bring the vanaras, whether Bharata or other support can move, and whether preparations for rescue have begun. These are not doubts in her own worth. They are the unanswered operational questions produced by months without reliable news.'),
  ('scene-ramas-ring-enters-sitas-hand', 'sita-asks-the-questions-isolation-created', 'hi', 'राहत व्यावहारिक प्रश्नों की बाढ़ खोलती है', 'सीता पूछती हैं—राम-लक्ष्मण सुरक्षित हैं या नहीं, शोक ने कार्रवाई कमजोर की या नहीं, सहयोगी जुट रहे हैं या नहीं, सुग्रीव वानर लाएँगे या नहीं, भरत या अन्य सहायता चल सकती है या नहीं और उद्धार की तैयारी शुरू हुई या नहीं। ये अपने मूल्य पर संदेह नहीं; महीनों के अविश्वसनीय समाचार से बने कार्यकारी प्रश्न हैं।'),
  ('scene-ramas-ring-enters-sitas-hand', 'location-was-the-missing-fact', 'en', 'Hanuman explains the delay without claiming forgetfulness', 'Hanuman says Rama did not know Sita was in this grove; the search had to find a direction, cross the ocean, and confirm her exact condition. Once Hanuman returns with that knowledge, a force can move toward a real target. The answer does not pretend the delay caused no harm, but it separates an information failure from abandonment.'),
  ('scene-ramas-ring-enters-sitas-hand', 'location-was-the-missing-fact', 'hi', 'हनुमान देरी का कारण बताते हैं, भूल नहीं', 'हनुमान कहते हैं कि राम नहीं जानते थे कि सीता इसी वाटिका में हैं; खोज को दिशा पाकर समुद्र पार करना और उनकी सटीक दशा पुष्ट करनी थी। हनुमान यह ज्ञान लौटाएँगे तो सेना वास्तविक लक्ष्य की ओर चल सकेगी। उत्तर देरी की हानि नहीं मिटाता, पर सूचना की कमी को त्याग से अलग करता है।'),
  ('scene-ramas-ring-enters-sitas-hand', 'ramas-grief-and-action-must-travel-together', 'en', 'Hanuman reports longing without making paralysis romantic', 'Hanuman says Rama sleeps poorly, remembers Sita in ordinary flowers and fruit, and has little interest in pleasure while separated. Sita feels joy that the bond continues and pain that he suffers. His distress is not offered as the rescue itself. The decisive change will be verified location entering the alliance and grief becoming preparation, movement, and protection.'),
  ('scene-ramas-ring-enters-sitas-hand', 'ramas-grief-and-action-must-travel-together', 'hi', 'हनुमान विरह बताते हैं, जड़ता को रोमानी नहीं बनाते', 'हनुमान बताते हैं कि राम कम सोते, साधारण फूल-फलों में सीता को याद करते और अलगाव में सुख से विरक्त हैं। बंधन बना होने पर सीता आनंद और उनके दुःख पर पीड़ा दोनों अनुभव करती हैं। उनका कष्ट स्वयं उद्धार नहीं। निर्णायक बदलाव तब होगा जब पक्का स्थान मैत्री तक पहुँचे और शोक तैयारी, गति तथा संरक्षण बने।'),
  ('scene-sita-refuses-an-unsafe-flight', 'sita-shares-the-deadline-and-lankan-dissent', 'en', 'Not everyone in Lanka supports Ravana', 'Sita says the captor''s deadline is closing and reports that Vibhishana urged Ravana to return her, while his daughter Kala carried that information through her mother. She also names the elder Avindhya, who warned Ravana that his course endangered Lanka. These voices do not free Sita, but they prove the city is not one obedient moral block.'),
  ('scene-sita-refuses-an-unsafe-flight', 'sita-shares-the-deadline-and-lankan-dissent', 'hi', 'लंका में हर कोई रावण के साथ नहीं', 'सीता कहती हैं कि अपहरणकर्ता की समय-सीमा घट रही है और बताती हैं कि विभीषण ने रावण से उन्हें लौटाने को कहा, जिसकी सूचना उनकी पुत्री कला ने अपनी माँ के माध्यम से पहुँचाई। वे वृद्ध अविंध्य का भी नाम लेती हैं जिसने रावण को लंका के खतरे की चेतावनी दी। ये आवाजें उन्हें मुक्त नहीं करतीं, पर नगर को एक आज्ञाकारी नैतिक समूह नहीं रहने देतीं।'),
  ('scene-sita-refuses-an-unsafe-flight', 'hanuman-offers-to-carry-sita-now', 'en', 'A direct route appears', 'Moved by the deadline, Hanuman offers to take Sita on his back across the ocean to Rama immediately. He knows he crossed alone and believes he can carry far more than one person. The proposal is sincere and time-sensitive, but sincerity and strength do not settle whether the passenger can travel safely or whether this escape serves the whole rescue.'),
  ('scene-sita-refuses-an-unsafe-flight', 'hanuman-offers-to-carry-sita-now', 'hi', 'एक सीधी राह सामने आती है', 'समय-सीमा से प्रभावित हनुमान सीता को अपनी पीठ पर बैठाकर तुरंत समुद्र पार राम तक ले जाने का प्रस्ताव देते हैं। वे अकेले पार आए और मानते हैं कि एक व्यक्ति से कहीं अधिक भार ले सकते हैं। प्रस्ताव सच्चा और तात्कालिक है, पर सच्चाई तथा बल यह तय नहीं करते कि यात्री सुरक्षित रहेगी या यह पलायन पूरे उद्धार को साधेगा।'),
  ('scene-sita-refuses-an-unsafe-flight', 'sita-questions-the-visible-scale', 'en', 'The passenger asks about carrying capacity', 'Looking at Hanuman''s small form, Sita asks how he could carry her so far. The question is practical, not an insult: she has not seen the launch from Mahendra or the forms he can assume. Hanuman initially feels wounded and expands into a mountain-like size to demonstrate capacity, revealing that even a capable rescuer can overread a safety question as a challenge to pride.'),
  ('scene-sita-refuses-an-unsafe-flight', 'sita-questions-the-visible-scale', 'hi', 'यात्री वहन-क्षमता पूछती हैं', 'हनुमान के छोटे रूप को देखकर सीता पूछती हैं कि वे इतनी दूरी कैसे ले जाएँगे। प्रश्न व्यावहारिक है, अपमान नहीं—उन्होंने महेंद्र से छलाँग या उनके बदलते आकार नहीं देखे। हनुमान पहले आहत होकर पर्वत जैसा रूप बढ़ाते हैं; इससे दिखता है कि सक्षम उद्धारक भी सुरक्षा-प्रश्न को गर्व की चुनौती समझ सकता है।'),
  ('scene-sita-refuses-an-unsafe-flight', 'strength-does-not-erase-the-passengers-decision', 'en', 'Sita accepts the proof and still says no', 'Sita acknowledges Hanuman''s speed, energy, and ability to return. His demonstration answers whether he has power; it does not answer whether she consents to this route. She asks to consider the work as a whole. Her refusal is not disbelief in Hanuman and cannot be overturned by becoming larger, louder, or more certain.'),
  ('scene-sita-refuses-an-unsafe-flight', 'strength-does-not-erase-the-passengers-decision', 'hi', 'सीता शक्ति मानकर भी मना करती हैं', 'सीता हनुमान की गति, ऊर्जा और लौटने की क्षमता मानती हैं। प्रदर्शन यह बताता है कि उनमें शक्ति है; यह नहीं कि सीता इस मार्ग को स्वीकार करती हैं। वे पूरे कार्य पर विचार करने को कहती हैं। उनका अस्वीकार हनुमान पर अविश्वास नहीं और बड़ा, ऊँचा या अधिक निश्चित होकर बदला नहीं जा सकता।'),
  ('scene-sita-refuses-an-unsafe-flight', 'speed-fall-and-pursuit-create-real-risk', 'en', 'The sky route has failure modes', 'Sita names what could go wrong: violent speed may make her lose consciousness or fall, guards may see them, armed pursuers may surround Hanuman, and he may have to fight while protecting a passenger. Battle is uncertain even for the strong. Recapture could hide her in a new place and erase the only confirmed location the alliance now possesses.'),
  ('scene-sita-refuses-an-unsafe-flight', 'speed-fall-and-pursuit-create-real-risk', 'hi', 'आकाश-मार्ग में विफलता के रास्ते हैं', 'सीता जोखिम गिनाती हैं—तीव्र गति से वे चेतना खो या गिर सकती हैं, पहरेदार देख सकते हैं, सशस्त्र पीछा हनुमान को घेर सकता है और उन्हें यात्री की रक्षा करते हुए लड़ना पड़ सकता है। बलवान के लिए भी युद्ध अनिश्चित है। दोबारा पकड़कर उन्हें नई जगह छिपाया जा सकता है और मैत्री का एकमात्र पक्का स्थान मिट सकता है।'),
  ('scene-sita-refuses-an-unsafe-flight', 'bodily-choice-is-not-reduced-to-purity', 'en', 'Sita names who may carry her', 'Sita says she does not willingly want another person''s body carrying hers and distinguishes that choice from Ravana''s forced contact during abduction, when she had no safe alternative. Her boundary belongs to her relationship, comfort, and control; it is not a purity test that makes a harmed person responsible for contact imposed upon her.'),
  ('scene-sita-refuses-an-unsafe-flight', 'bodily-choice-is-not-reduced-to-purity', 'hi', 'सीता तय करती हैं कि उन्हें कौन ले जा सकता है', 'सीता कहती हैं कि वे स्वेच्छा से किसी अन्य व्यक्ति के शरीर पर बैठकर नहीं जाना चाहतीं और इसे हरण के समय रावण द्वारा थोपे स्पर्श से अलग करती हैं, जब सुरक्षित विकल्प नहीं था। यह सीमा उनके संबंध, सहजता और नियंत्रण की है; शुद्धता-परीक्षा नहीं जो पीड़ित को थोपे संपर्क के लिए जिम्मेदार बनाए।'),
  ('scene-sita-refuses-an-unsafe-flight', 'sita-chooses-a-durable-rescue', 'en', 'The answer must change the whole situation', 'Sita asks Hanuman to bring Rama, Lakshmana, Sugriva, and the allied force so that the captivity system, not merely one body, is confronted. She also wants Rama to act openly after the hidden abduction. This choice carries danger and cultural ideas of honour, but its strategic core is durable: preserve evidence, arrive prepared, prevent recapture, and end Ravana''s control over the route.'),
  ('scene-sita-refuses-an-unsafe-flight', 'sita-chooses-a-durable-rescue', 'hi', 'उत्तर को पूरी परिस्थिति बदलनी है', 'सीता हनुमान से राम, लक्ष्मण, सुग्रीव और सहयोगी सेना लाने को कहती हैं ताकि केवल एक शरीर नहीं, बंदी बनाने वाला तंत्र चुनौती पाए। वे चाहती हैं कि छिपे हरण के बाद राम खुलकर कार्रवाई करें। इसमें खतरा और सम्मान की सांस्कृतिक धारणाएँ हैं, पर रणनीतिक केंद्र टिकाऊ है—प्रमाण बचाना, तैयारी से आना, दोबारा पकड़ रोकना और मार्ग पर रावण का नियंत्रण समाप्त करना।'),
  ('scene-private-memory-becomes-a-return-token', 'hanuman-accepts-the-refusal-and-asks', 'en', 'The proposal ends when Sita says no', 'Hanuman does not repeat the carrying offer after Sita''s reasons. He says he will report her words from beginning to end and explains that urgency and care led him to suggest immediate flight. Then he asks for a token Rama will recognise. The mission changes from trying to move Sita''s body to carrying her chosen evidence and instructions.'),
  ('scene-private-memory-becomes-a-return-token', 'hanuman-accepts-the-refusal-and-asks', 'hi', 'सीता के मना करते ही प्रस्ताव समाप्त होता है', 'सीता के कारण सुनकर हनुमान वहन-प्रस्ताव नहीं दोहराते। वे कहते हैं कि उनकी बात आरंभ से अंत तक पहुँचाएँगे और बताते हैं कि तात्कालिकता तथा चिंता से तुरंत उड़ने का विचार आया था। फिर राम के पहचानने योग्य प्रमाण माँगते हैं। अभियान सीता के शरीर को ले जाने से उनके चुने प्रमाण और निर्देश ले जाने में बदलता है।'),
  ('scene-private-memory-becomes-a-return-token', 'chitrakuta-begins-with-ordinary-closeness', 'en', 'A private memory starts beside the Mandakini', 'Sita asks Hanuman to remind Rama of a day near Chitrakuta''s Mandakini, when water play, forest flowers, tiredness, laughter, and resting in one another''s laps made an ordinary shared afternoon. The specificity is intimate without exposing a secret code invented for authentication. It is a lived memory only the two of them can place from inside.'),
  ('scene-private-memory-becomes-a-return-token', 'chitrakuta-begins-with-ordinary-closeness', 'hi', 'निजी स्मृति मंदाकिनी के पास शुरू होती है', 'सीता हनुमान से चित्रकूट की मंदाकिनी के पास का दिन राम को याद दिलाने को कहती हैं—जल-क्रीड़ा, वन-फूल, थकान, हँसी और एक-दूसरे की गोद में विश्राम वाला साधारण साझा दोपहर। विवरण निजी है, पर पहचान के लिए गढ़ा गुप्त शब्द नहीं। यह ऐसी जी हुई स्मृति है जिसे दोनों भीतर से स्थान दे सकते हैं।'),
  ('scene-private-memory-becomes-a-return-token', 'the-crow-turns-play-into-harm', 'en', 'A repeated attack breaks the afternoon', 'A crow repeatedly pecks Sita despite her attempts to drive it away, and the injury finally wakes Rama. The harm is conveyed without lingering on her body or blood. The important change is that an irritation dismissed at first becomes a recognised attack, and Rama sees that Sita has been hurt while resting beside him.'),
  ('scene-private-memory-becomes-a-return-token', 'the-crow-turns-play-into-harm', 'hi', 'बार-बार का आक्रमण दोपहर तोड़ देता है', 'एक कौआ सीता के हटाने पर भी बार-बार चोंच मारता है और चोट अंततः राम को जगा देती है। हानि का अर्थ रखा जाता है, उनके शरीर या रक्त पर ठहरा नहीं जाता। महत्त्वपूर्ण बदलाव यह कि पहले छोटी बाधा समझी बात पहचाना आक्रमण बनती है और राम देखते हैं कि पास विश्राम करती सीता घायल हुई हैं।'),
  ('scene-private-memory-becomes-a-return-token', 'the-weapon-pursues-and-mercy-remains', 'en', 'Protection escalates, then accepts surrender', 'Rama charges a blade of grass with a weapon that pursues the crow through every refuge. When the exhausted bird returns and surrenders, Rama does not kill it, though the launched force cannot be made consequence-free. The crow survives with a lasting cost. The memory holds fierce protection and mercy together without inviting anyone to repeat the violence.'),
  ('scene-private-memory-becomes-a-return-token', 'the-weapon-pursues-and-mercy-remains', 'hi', 'संरक्षण बढ़ता है, फिर शरण मानता है', 'राम घास की पत्ती को ऐसे अस्त्र से जोड़ते हैं जो हर शरण तक कौए का पीछा करता है। थका पक्षी लौटकर समर्पण करता है तो राम उसे मारते नहीं, यद्यपि छोड़ी शक्ति को बिना परिणाम नहीं किया जा सकता। कौआ स्थायी कीमत देकर जीवित रहता है। स्मृति प्रबल संरक्षण और दया साथ रखती है, हिंसा दोहराने का निमंत्रण नहीं।'),
  ('scene-private-memory-becomes-a-return-token', 'sita-turns-memory-into-a-question', 'en', 'If a crow drew action, why has this harm not?', 'Sita asks Rama through Hanuman why the person who once acted over a crow has not yet reached the captor who caused far greater harm. The question is not proof that Rama abandoned her or that she caused delay. It carries the missing-location problem, her shortening time, and a demand that remembered protective power now become proportionate action.'),
  ('scene-private-memory-becomes-a-return-token', 'sita-turns-memory-into-a-question', 'hi', 'कौए पर कार्रवाई हुई, इस हानि पर क्यों नहीं?', 'सीता हनुमान के माध्यम से राम से पूछती हैं कि कौए पर कार्रवाई करने वाला व्यक्ति कहीं बड़ी हानि करने वाले अपहरणकर्ता तक अभी क्यों नहीं पहुँचा। प्रश्न राम के त्याग या सीता की गलती का प्रमाण नहीं। इसमें गायब स्थान की समस्या, घटता समय और यह माँग है कि पुरानी संरक्षण-शक्ति अब उचित कार्रवाई बने।'),
  ('scene-private-memory-becomes-a-return-token', 'messages-go-to-both-brothers', 'en', 'Sita sends affection, accountability, and urgency', 'Sita asks after Kausalya''s son Rama and sends particular words for Lakshmana, remembering how he left comfort, cared for Rama like a son, and treated her like a mother. She asks that he help end her misery and states a shorter survival boundary than the earlier threat allowed. The message reaches a network of relationships, not a lone avenger.'),
  ('scene-private-memory-becomes-a-return-token', 'messages-go-to-both-brothers', 'hi', 'सीता स्नेह, उत्तरदायित्व और तात्कालिकता भेजती हैं', 'सीता कौसल्या-पुत्र राम का कुशल पूछती और लक्ष्मण के लिए विशेष शब्द भेजती हैं—कैसे उन्होंने सुख छोड़ा, राम की पुत्रवत देखभाल और सीता का मातृवत सम्मान किया। वे उनसे कष्ट समाप्त कराने में सहायता माँगती और पहले बताई धमकी से छोटी जीवन-सीमा कहती हैं। संदेश अकेले प्रतिशोधी नहीं, संबंधों के जाल तक जाता है।'),
  ('scene-private-memory-becomes-a-return-token', 'the-chudamani-makes-the-mission-two-way', 'en', 'Sita releases the jewel she kept hidden', 'Sita unties the chudamani concealed in her clothing and asks Hanuman to give it to Rama. The object carries Janaka''s household, her life with Rama, and the fact that she preserved something recognisable under surveillance. Hanuman bows, receives it, and mentally turns toward the brothers. He now carries Sita''s selected proof, not merely proof that others assembled about her.'),
  ('scene-private-memory-becomes-a-return-token', 'the-chudamani-makes-the-mission-two-way', 'hi', 'सीता छिपाकर रखी चूड़ामणि सौंपती हैं', 'सीता वस्त्र में छिपी चूड़ामणि खोलकर हनुमान से राम को देने को कहती हैं। वस्तु जनक का घर, राम के साथ जीवन और पहरे में भी पहचाने योग्य चीज बचाए रखने का तथ्य साथ लाती है। हनुमान झुककर उसे लेते और मन से भाइयों की ओर मुड़ते हैं। अब वे सीता का चुना प्रमाण ले जाते हैं, केवल दूसरों द्वारा जुटाया प्रमाण नहीं।'),
  ('scene-sita-asks-how-an-army-crosses', 'the-token-makes-departure-real', 'en', 'Handoff opens the pain of separation again', 'Once the chudamani is in Hanuman''s care, Sita sees that the only friendly witness in the grove is preparing to leave. She asks him to send good news to Rama, Lakshmana, Sugriva, his counsellors, and the elder vanaras. The request shows how one brief contact has connected her to an entire social world she cannot yet see.'),
  ('scene-sita-asks-how-an-army-crosses', 'the-token-makes-departure-real', 'hi', 'सौंपना फिर बिछड़ने का दर्द खोलता है', 'चूड़ामणि हनुमान के पास जाते ही सीता देखती हैं कि वाटिका का एकमात्र मित्र-साक्षी जाने वाला है। वे राम, लक्ष्मण, सुग्रीव, उनके मंत्रियों और वृद्ध वानरों तक कुशल-संदेश भेजने को कहती हैं। यह अनुरोध दिखाता है कि छोटी भेंट ने उन्हें ऐसे पूरे सामाजिक संसार से जोड़ दिया है जिसे वे अभी देख नहीं सकतीं।'),
  ('scene-sita-asks-how-an-army-crosses', 'sita-asks-for-one-more-day', 'en', 'Nearby safety is hard to release', 'Sita asks whether Hanuman might rest hidden for a day because his nearness temporarily reduces her grief. She also fears he may not return and that losing this contact will deepen the crisis. The request is not used to delay the mission for sentiment. It names the cost of asking an isolated person to surrender the first credible connection she has received in months.'),
  ('scene-sita-asks-how-an-army-crosses', 'sita-asks-for-one-more-day', 'hi', 'पास की सुरक्षा छोड़ना कठिन है', 'सीता पूछती हैं कि क्या हनुमान एक दिन छिपकर विश्राम कर सकते हैं, क्योंकि उनका पास होना थोड़ी देर शोक घटाता है। उन्हें डर है कि वे न लौटें और यह संपर्क खोने से संकट बढ़े। अनुरोध भावना के लिए अभियान रोकना नहीं; महीनों में मिली पहली विश्वसनीय कड़ी छोड़ने की कीमत का नाम है।'),
  ('scene-sita-asks-how-an-army-crosses', 'the-ocean-question-remains-unsolved', 'en', 'One crossing does not prove mass passage', 'Sita asks how Rama, Lakshmana, thousands of vanaras, and bears can cross an ocean only Garuda, the Wind, or Hanuman seem able to cross. The question distinguishes a scout''s exceptional journey from logistics for an army. She refuses to accept a dramatic promise where a route, capacity, and arrival plan are still missing.'),
  ('scene-sita-asks-how-an-army-crosses', 'the-ocean-question-remains-unsolved', 'hi', 'एक पार उतरना पूरी सेना का प्रमाण नहीं', 'सीता पूछती हैं कि राम, लक्ष्मण, हजारों वानर और भालू उस समुद्र को कैसे पार करेंगे जिसे गरुड़, पवन या हनुमान जैसे ही पार कर सकते दिखते हैं। प्रश्न गुप्तचर की असाधारण यात्रा को सेना की व्यवस्था से अलग करता है। वे नाटकीय वादा नहीं मानतीं जहाँ मार्ग, क्षमता और पहुँच-योजना अभी गायब है।'),
  ('scene-sita-asks-how-an-army-crosses', 'hanuman-locates-himself-inside-a-larger-force', 'en', 'The messenger is not the army''s upper limit', 'Hanuman says Sugriva commands many vanaras of great speed and endurance, including peers equal or superior to him. His claim is meant to correct Sita''s picture of a lone exceptional traveller, not to make strength infinite. A functioning force needs many capable crossings, coordination, and leaders who can carry Rama and Lakshmana toward Lanka.'),
  ('scene-sita-asks-how-an-army-crosses', 'hanuman-locates-himself-inside-a-larger-force', 'hi', 'दूत सेना की अधिकतम सीमा नहीं', 'हनुमान कहते हैं कि सुग्रीव के अधीन अत्यंत तेज और सहनशील अनेक वानर हैं, जिनमें उनके समान या अधिक सक्षम साथी भी हैं। दावा अकेले असाधारण यात्री वाली सीता की तस्वीर सुधारता है, शक्ति को अनंत नहीं बनाता। काम करने वाली सेना को कई सक्षम पारियाँ, समन्वय और राम-लक्ष्मण को लंका तक लाने वाले नेता चाहिए।'),
  ('scene-sita-asks-how-an-army-crosses', 'a-feasible-force-still-needs-a-chosen-method', 'en', 'Capacity opens planning, not certainty', 'Hanuman promises that Rama, Lakshmana, vanaras, and bears can reach Lanka and confront Ravana, but he does not yet know the exact collective crossing method that later decisions must create. His assurance rests on available capabilities and commitment, not a fabricated completed bridge. Sita receives a credible next stage rather than false logistical precision.'),
  ('scene-sita-asks-how-an-army-crosses', 'a-feasible-force-still-needs-a-chosen-method', 'hi', 'क्षमता योजना खोलती है, निश्चितता नहीं', 'हनुमान भरोसा देते हैं कि राम, लक्ष्मण, वानर और भालू लंका पहुँचकर रावण का सामना कर सकते हैं, पर सामूहिक पार का सटीक तरीका अभी बाद के निर्णय बनाएँगे। आश्वासन उपलब्ध क्षमताओं और प्रतिबद्धता पर है, गढ़े हुए तैयार सेतु पर नहीं। सीता को झूठी व्यवस्था नहीं, विश्वसनीय अगला चरण मिलता है।'),
  ('scene-sita-asks-how-an-army-crosses', 'sita-reaffirms-the-collective-rescue', 'en', 'The chosen victory must include arrival and return', 'Sita accepts that Hanuman may be powerful enough to act alone, yet asks for the larger rescue: Rama and the allied force must reach Lanka, break Ravana''s power to hold her, and open a protected road home. Her choice turns the mission from one daring escape into an answer to the kingdom and force that made the captivity possible.'),
  ('scene-sita-asks-how-an-army-crosses', 'sita-reaffirms-the-collective-rescue', 'hi', 'चुनी विजय में पहुँचना और लौटना दोनों हैं', 'सीता मानती हैं कि हनुमान अकेले कार्रवाई करने जितने शक्तिशाली हो सकते हैं, फिर भी वे बड़ा उद्धार चुनती हैं—राम और सहयोगी सेना लंका पहुँचे, रावण की बंदी बनाए रखने की शक्ति तोड़े और सुरक्षित घर-वापसी का मार्ग खोले। उनका निर्णय एक साहसी पलायन को उस राज्य और बल के उत्तर में बदलता है जिसने बंदीपन संभव किया।'),
  ('scene-hanuman-carries-sitas-voice-north', 'the-chudamani-carries-three-relationships', 'en', 'The jewel will recall more than one person', 'Sita says Rama will recognise the chudamani and remember her, Dasharatha, and the maternal household connected with the jewel. Its value is not merely rarity or price. It holds a network of family memory that can establish who selected and preserved it. Hanuman must present it with her words so the object does not become detached treasure.'),
  ('scene-hanuman-carries-sitas-voice-north', 'the-chudamani-carries-three-relationships', 'hi', 'मणि एक से अधिक संबंध याद दिलाएगी', 'सीता कहती हैं कि राम चूड़ामणि पहचानकर उन्हें, दशरथ को और मणि से जुड़े मातृ-घर को याद करेंगे। उसका मूल्य केवल दुर्लभता या कीमत नहीं। उसमें परिवार-स्मृति का जाल है जो बताता है कि उसे किसने चुना और बचाया। हनुमान को उसे सीता के शब्दों के साथ देना है ताकि वस्तु अलग खजाना न बन जाए।'),
  ('scene-hanuman-carries-sitas-voice-north', 'the-erased-tilaka-adds-a-second-memory', 'en', 'A small mark becomes private corroboration', 'Sita adds another memory: when her first tilaka was rubbed away, Rama painted a replacement beside her cheek with red mineral. The moment is small, domestic, and difficult for an outsider to reconstruct from public reputation. Paired with the crow account and the jewel, it gives Rama several independent reasons to know the message is hers.'),
  ('scene-hanuman-carries-sitas-voice-north', 'the-erased-tilaka-adds-a-second-memory', 'hi', 'छोटा चिह्न निजी पुष्टि बनता है', 'सीता दूसरी स्मृति जोड़ती हैं—पहला तिलक मिटने पर राम ने लाल खनिज से उनके गाल के पास नया चिह्न बनाया था। यह छोटा घरेलू क्षण है जिसे बाहरी व्यक्ति सार्वजनिक प्रसिद्धि से नहीं गढ़ सकता। कौआ-कथा और मणि के साथ यह राम को संदेश सीता का होने के कई स्वतंत्र कारण देता है।'),
  ('scene-hanuman-carries-sitas-voice-north', 'sita-states-the-time-she-believes-remains', 'en', 'The return message carries a survival boundary', 'Sita says she believes she can endure one more month and asks that Rama not delay. Earlier she had repeated that two months remained in Ravana''s imposed deadline; now she speaks of how long she herself thinks she can survive the worsening danger. Hanuman must carry both the captor''s clock and Sita''s more urgent estimate.'),
  ('scene-hanuman-carries-sitas-voice-north', 'sita-states-the-time-she-believes-remains', 'hi', 'वापसी-संदेश जीवन-सीमा ले जाता है', 'सीता कहती हैं कि वे एक महीना और सह सकती हैं और राम से देर न करने को कहती हैं। पहले उन्होंने रावण की थोपी समय-सीमा में दो महीने शेष बताए थे; अब वे कहती हैं कि बढ़ते खतरे में वे स्वयं कितने समय तक जीवित रह पाएँगी। हनुमान को अपहरणकर्ता की घड़ी और सीता का अधिक तात्कालिक आकलन—दोनों पहुँचाने हैं।'),
  ('scene-hanuman-carries-sitas-voice-north', 'sita-names-what-she-is-enduring', 'en', 'The message carries conditions, not only symbols', 'Sita tells Hanuman to report the threats, humiliating speech, constant surveillance, separation, and strain she continues to bear. The jewel and private memories prove who sent the message; these present conditions tell Rama why the manner and timing of rescue matter. Hanuman now carries both recognition and an exact warning about the danger around her.'),
  ('scene-hanuman-carries-sitas-voice-north', 'sita-names-what-she-is-enduring', 'hi', 'संदेश चिह्न ही नहीं, दशा भी ले जाता है', 'सीता हनुमान से धमकियाँ, अपमानजनक वाणी, निरंतर निगरानी, अलगाव और लगातार सहा दबाव बताने को कहती हैं। मणि और निजी स्मृतियाँ संदेश भेजने वाली की पहचान देती हैं; वर्तमान दशा राम को बताती है कि उद्धार का समय और तरीका क्यों महत्त्वपूर्ण है। हनुमान अब पहचान के साथ उनके चारों ओर के खतरे की सटीक चेतावनी भी ले जाते हैं।'),
  ('scene-hanuman-carries-sitas-voice-north', 'the-recipient-list-preserves-the-alliance', 'en', 'Sita sends news to the whole support network', 'Sita asks Hanuman to carry her welfare and urgency to Rama, Lakshmana, Sugriva, his counsellors, and the assembled elders. Each recipient holds a different capacity: relationship, military decision, route knowledge, counsel, or collective mobilisation. Her rescue is not reduced to a private message between spouses; it is now a responsibility distributed across the alliance.'),
  ('scene-hanuman-carries-sitas-voice-north', 'the-recipient-list-preserves-the-alliance', 'hi', 'सीता पूरे सहयोग-जाल को समाचार भेजती हैं', 'सीता हनुमान से अपना कुशल और तात्कालिकता राम, लक्ष्मण, सुग्रीव, उनके मंत्रियों और जुटे वृद्धों तक पहुँचाने को कहती हैं। हर प्राप्तकर्ता अलग क्षमता रखता है—संबंध, सैन्य निर्णय, मार्ग-ज्ञान, सलाह या सामूहिक जुटान। उद्धार पति-पत्नी का निजी संदेश नहीं रह जाता; मैत्री में बँटा उत्तरदायित्व बनता है।'),
  ('scene-hanuman-carries-sitas-voice-north', 'hanuman-turns-north-with-an-exact-packet', 'en', 'The messenger leaves with more than good news', 'Hanuman repeats what he will carry: he has seen Sita, received her jewel and private memories, heard the rescue she chooses, and learned how little time she believes remains. He bows and turns his mind north toward Rama, Lakshmana, and Sugriva. The grove is still quiet; the next conflict has not yet begun, and the first task is to keep Sita''s exact voice alive on the return journey.'),
  ('scene-hanuman-carries-sitas-voice-north', 'hanuman-turns-north-with-an-exact-packet', 'hi', 'दूत केवल शुभ समाचार लेकर नहीं जाता', 'हनुमान दोहराते हैं कि वे क्या ले जाएँगे—उन्होंने सीता को देखा, उनकी मणि और निजी स्मृतियाँ लीं, उनका चुना उद्धार सुना और जाना कि वे कितना कम समय शेष मानती हैं। वे झुककर राम, लक्ष्मण और सुग्रीव की ओर उत्तर का ध्यान करते हैं। वाटिका अभी शांत है; अगला संघर्ष शुरू नहीं हुआ और पहला काम वापसी-यात्रा में सीता की सटीक आवाज जीवित रखना है।'),
  ('scene-hanuman-chooses-open-disruption', 'the-primary-mission-is-already-safe', 'en', 'Sita''s message remains the first success', 'Hanuman leaves the shimshapa knowing the mission''s essential fact is secured: Sita is alive, her location is confirmed, and her words and chudamani can return to Rama. Any further action must not erase that result. He pauses before choosing whether the return journey should begin at once.'),
  ('scene-hanuman-chooses-open-disruption', 'the-primary-mission-is-already-safe', 'hi', 'सीता का संदेश पहली सफलता बना रहता है', 'हनुमान शीशम से यह जानते हुए हटते हैं कि अभियान का मुख्य तथ्य सुरक्षित है—सीता जीवित हैं, उनका स्थान पुष्ट है और उनके शब्द तथा चूड़ामणि राम तक लौट सकते हैं। आगे की कोई कार्रवाई इस सफलता को मिटा नहीं सकती। वे लौटने से पहले अगले कदम पर ठहरकर सोचते हैं।'),
  ('scene-hanuman-chooses-open-disruption', 'four-methods-lead-to-one-risky-choice', 'en', 'Hanuman rejects three quiet methods', 'He weighs conciliation, gifts, and division, then decides none can quickly expose the strength and intention of a court proud of its power. He chooses a show of force as an intelligence gamble, not because violence is the only imaginable response in every conflict. The decision is strategic, voluntary, and dangerous.'),
  ('scene-hanuman-chooses-open-disruption', 'four-methods-lead-to-one-risky-choice', 'hi', 'हनुमान तीन शांत उपाय छोड़ते हैं', 'वे समझौता, उपहार और फूट के उपाय तौलते हैं, फिर मानते हैं कि शक्ति पर गर्व करने वाली सभा की क्षमता और मंशा ये तुरंत नहीं खोलेंगे। वे बल-प्रदर्शन को हर संघर्ष का एकमात्र उत्तर नहीं, बल्कि जोखिम भरा गुप्तचर दाँव चुनते हैं। निर्णय रणनीतिक, स्वैच्छिक और खतरनाक है।'),
  ('scene-hanuman-chooses-open-disruption', 'the-grove-becomes-the-signal', 'en', 'A royal pleasure ground becomes the alarm', 'Hanuman tears through trees, pools, pavilions, and rocky structures so the damage cannot be hidden from Ravana. Birds and animals scatter in distress, making the cost larger than a clean military demonstration. The destruction succeeds as a signal, but it also harms a living place that did not choose the conflict.'),
  ('scene-hanuman-chooses-open-disruption', 'the-grove-becomes-the-signal', 'hi', 'राजकीय वाटिका चेतावनी बनती है', 'हनुमान वृक्ष, सरोवर, मंडप और शैल-रचनाएँ तोड़ते हैं ताकि क्षति रावण से छिप न सके। पक्षी और पशु भय में भागते हैं, इसलिए कीमत केवल स्वच्छ सैनिक प्रदर्शन नहीं रहती। विनाश संकेत तो बनता है, पर उस जीवित स्थान को भी चोट पहुँचाता है जिसने संघर्ष नहीं चुना।'),
  ('scene-hanuman-chooses-open-disruption', 'one-tree-is-deliberately-spared', 'en', 'Sita''s refuge stays standing', 'The shimshapa and the ground immediately around Sita remain intact while the rest of the grove is broken. This protected island tells the guards the intruder acted with knowledge and purpose. Hanuman then takes position at the main gate, openly waiting for the response he has chosen to provoke.'),
  ('scene-hanuman-chooses-open-disruption', 'one-tree-is-deliberately-spared', 'hi', 'सीता का आश्रय खड़ा रहता है', 'शीशम और सीता के तुरंत आसपास की भूमि बची रहती है, जबकि बाकी वाटिका टूट जाती है। यह सुरक्षित द्वीप रक्षकों को बताता है कि घुसपैठिया जानकारी और उद्देश्य के साथ चला। फिर हनुमान मुख्य द्वार पर खड़े होकर उस प्रतिक्रिया की खुली प्रतीक्षा करते हैं जिसे उन्होंने स्वयं उकसाया है।'),
  ('scene-the-grove-sends-an-alarm', 'the-guards-wake-to-a-pattern', 'en', 'The damage points back to Sita', 'Cracking trees and terrified birds wake the guards. They find almost every part of the grove damaged except the place where Sita sits. The pattern makes the earlier conversation suspicious, so they surround her with questions about the stranger''s identity, origin, and words.'),
  ('scene-the-grove-sends-an-alarm', 'the-guards-wake-to-a-pattern', 'hi', 'विनाश की रेखा सीता तक लौटती है', 'टूटते वृक्ष और भयभीत पक्षी रक्षकों को जगा देते हैं। लगभग पूरी वाटिका उजड़ी है, केवल सीता का स्थान बचा है। यह क्रम पिछली बातचीत को संदिग्ध बनाता है, इसलिए वे अजनबी की पहचान, आगमन और शब्दों पर सीता को प्रश्नों से घेरते हैं।'),
  ('scene-the-grove-sends-an-alarm', 'sita-does-not-expose-the-messenger', 'en', 'Sita answers without betraying Hanuman', 'Sita says shape-changing beings are best known by others of their own kind and claims she cannot identify the visitor. Her fear is believable, and her answer gives the guards no usable route to Rama''s message. She protects the contact without inventing a detailed story that later facts could easily break.'),
  ('scene-the-grove-sends-an-alarm', 'sita-does-not-expose-the-messenger', 'hi', 'सीता हनुमान को उजागर किए बिना उत्तर देती हैं', 'सीता कहती हैं कि रूप बदलने वालों को उनके अपने लोग ही बेहतर पहचानते हैं और वे आगंतुक को नहीं जानतीं। उनका भय विश्वसनीय है और उत्तर रक्षकों को राम के संदेश तक कोई उपयोगी राह नहीं देता। वे ऐसी लंबी कहानी गढ़े बिना संपर्क बचाती हैं जिसे बाद के तथ्य तोड़ दें।'),
  ('scene-the-grove-sends-an-alarm', 'ravana-receives-the-spared-tree-report', 'en', 'The report names deliberate restraint', 'Messengers tell Ravana that a vast monkey spoke with Sita, ruined the grove, and spared only her tree. They cannot tell whether the restraint came from fatigue or intention, but the untouched refuge makes intention hard to dismiss. Ravana''s anger converts the unresolved question into an order for mass capture.'),
  ('scene-the-grove-sends-an-alarm', 'ravana-receives-the-spared-tree-report', 'hi', 'सूचना जानबूझकर बचाए गए स्थान का नाम लेती है', 'दूत रावण को बताते हैं कि विशाल वानर ने सीता से बात की, वाटिका उजाड़ी और केवल उनका वृक्ष छोड़ा। वे नहीं जानते कि यह थकान थी या इरादा, पर सुरक्षित आश्रय उद्देश्य को नकारना कठिन बनाता है। रावण का क्रोध अधूरे प्रश्न को बड़ी गिरफ्तारी-आज्ञा में बदल देता है।'),
  ('scene-the-grove-sends-an-alarm', 'hanuman-names-the-alliance-at-the-gate', 'en', 'The challenger says whose mission this is', 'Surrounded at the gate, Hanuman enlarges his form and proclaims victory for Rama, Lakshmana, and Sugriva before naming himself. He defeats the first force with the gate bolt, but some soldiers escape and report what happened. The response has now revealed numbers, weapons, command speed, and Ravana''s willingness to spend lives.'),
  ('scene-the-grove-sends-an-alarm', 'hanuman-names-the-alliance-at-the-gate', 'hi', 'चुनौतीकर्ता अपने अभियान का नाम बताता है', 'द्वार पर घिरकर हनुमान अपना रूप बढ़ाते, राम, लक्ष्मण और सुग्रीव की जय कहते और अपना नाम बताते हैं। वे पहली सेना को द्वार की अर्गला से हराते हैं, पर कुछ सैनिक बचकर परिणाम बताते हैं। प्रतिक्रिया अब संख्या, हथियार, आदेश की गति और रावण द्वारा प्राण खर्च करने की तैयारी खोल देती है।'),
  ('scene-the-chaitya-falls', 'a-second-target-is-chosen', 'en', 'The gate is no longer enough', 'After defeating the first force, Hanuman decides the ceremonial building still stands as an untouched centre of authority. He leaps onto its height and announces himself again. This is a fresh escalation chosen after the original alarm already worked, not an accidental extension of the grove''s destruction.'),
  ('scene-the-chaitya-falls', 'a-second-target-is-chosen', 'hi', 'अब केवल द्वार पर्याप्त नहीं', 'पहली सेना हराने के बाद हनुमान देखते हैं कि चैत्य भवन सत्ता के अछूते केंद्र की तरह खड़ा है। वे उसकी ऊँचाई पर छलाँग लगाकर फिर अपना परिचय देते हैं। यह वाटिका के विनाश का अनजाना विस्तार नहीं, पहली चेतावनी सफल होने के बाद चुना नया उभार है।'),
  ('scene-the-chaitya-falls', 'the-guards-defend-the-structure', 'en', 'A hundred defenders close in', 'The chaitya guards emerge with spears, axes, swords, and maces. Hanuman uproots a gold-plated pillar and whirls it through their formation. Friction ignites the structure, turning an improvised weapon into a fire that the immediate fight no longer fully controls.'),
  ('scene-the-chaitya-falls', 'the-guards-defend-the-structure', 'hi', 'सौ रक्षक भवन को घेरते हैं', 'चैत्य के रक्षक भाले, कुल्हाड़ी, तलवार और गदा लेकर निकलते हैं। हनुमान स्वर्ण-मढ़ा स्तंभ उखाड़कर उनकी रचना में घुमाते हैं। घर्षण भवन में आग लगा देता है, जिससे तात्कालिक हथियार ऐसी ज्वाला बनता है जिसे युद्ध पूरी तरह नियंत्रित नहीं करता।'),
  ('scene-the-chaitya-falls', 'the-symbol-and-its-defenders-fall', 'en', 'Fire consumes more than a position', 'The building burns and its defenders are killed. The result proves Hanuman can strike guarded height and structure, but it also removes a place with ceremonial meaning to those inside Lanka. Military advantage and cultural loss now occupy the same burning landmark; neither fact cancels the other.'),
  ('scene-the-chaitya-falls', 'the-symbol-and-its-defenders-fall', 'hi', 'अग्नि केवल सैनिक स्थान नहीं जलाती', 'भवन जलता और उसके रक्षक मारे जाते हैं। परिणाम सिद्ध करता है कि हनुमान संरक्षित ऊँचाई और रचना पर प्रहार कर सकते हैं, पर यह लंका के लोगों के लिए अर्थ रखने वाला स्थान भी मिटाता है। सैनिक लाभ और सांस्कृतिक हानि अब उसी जलते भवन में साथ हैं; कोई तथ्य दूसरे को नहीं मिटाता।'),
  ('scene-the-chaitya-falls', 'hanuman-warns-of-a-larger-force', 'en', 'One scout says he is not the army', 'From above, Hanuman says Sugriva commands thousands with varied strength and speed, many equal or superior to him. The warning answers Lanka''s assumption that stopping one intruder ends the threat. It also places the violence in a coming collective war whose scale will exceed this single combatant.'),
  ('scene-the-chaitya-falls', 'hanuman-warns-of-a-larger-force', 'hi', 'एक गुप्तचर कहता है कि वही पूरी सेना नहीं', 'ऊपर से हनुमान कहते हैं कि सुग्रीव के अधीन अलग-अलग शक्ति और गति वाले हजारों योद्धा हैं, जिनमें अनेक उनके समान या अधिक सक्षम हैं। चेतावनी लंका की इस धारणा को तोड़ती है कि एक घुसपैठिए को रोकना खतरा समाप्त कर देगा। यह हिंसा को आने वाले बड़े सामूहिक युद्ध में रखती है।'),
  ('scene-jambumali-meets-the-gate', 'prahastas-son-answers-the-loss', 'en', 'Ravana sends a known household', 'Ravana sends Jambumali, son of his commander Prahasta, rather than another anonymous mass. The warrior arrives in a chariot with a powerful bow and marks Hanuman''s face, head, and arms with arrows. The conflict now carries a family name and a direct line back to the court.'),
  ('scene-jambumali-meets-the-gate', 'prahastas-son-answers-the-loss', 'hi', 'रावण एक परिचित घर का योद्धा भेजता है', 'रावण फिर अनाम भीड़ नहीं, सेनापति प्रहस्त के पुत्र जम्बुमाली को भेजता है। शक्तिशाली धनुष और रथ वाला योद्धा हनुमान के मुख, सिर और भुजाओं को बाणों से घायल करता है। संघर्ष अब परिवार का नाम और सभा तक सीधी कड़ी लेता है।'),
  ('scene-jambumali-meets-the-gate', 'rock-and-tree-are-cut-down', 'en', 'Improvised strength meets trained archery', 'Hanuman hurls a rock, but Jambumali breaks its path with arrows. Hanuman uproots a sala tree, and the archer cuts that down too while continuing to wound him. For a moment, trained distance and precision defeat the larger fighter''s available objects.'),
  ('scene-jambumali-meets-the-gate', 'rock-and-tree-are-cut-down', 'hi', 'तात्कालिक बल प्रशिक्षित धनुर्विद्या से टकराता है', 'हनुमान शिला फेंकते हैं, पर जम्बुमाली बाणों से उसका मार्ग तोड़ देता है। हनुमान साल वृक्ष उखाड़ते हैं और धनुर्धर उसे भी काटते हुए प्रहार जारी रखता है। कुछ क्षणों के लिए प्रशिक्षित दूरी और सटीकता बड़े योद्धा की उपलब्ध वस्तुओं पर भारी पड़ती है।'),
  ('scene-jambumali-meets-the-gate', 'the-gate-bolt-ends-the-duel', 'en', 'Hanuman returns to the iron bolt', 'Wounded and enraged, Hanuman takes the heavy gate bolt, spins it, and strikes Jambumali''s chest. The impact destroys the chariot fighter and ends the duel so completely that neither warrior nor vehicle can continue. Prahasta''s son does not return, and the empty route carries that fact to his father and king.'),
  ('scene-jambumali-meets-the-gate', 'the-gate-bolt-ends-the-duel', 'hi', 'हनुमान फिर लोहे की अर्गला उठाते हैं', 'घायल और क्रोधित हनुमान भारी द्वार-अर्गला उठाकर घुमाते और जम्बुमाली के वक्ष पर मारते हैं। प्रहार रथी और वाहन को ऐसा नष्ट करता है कि युद्ध आगे नहीं चल सकता। प्रहस्त का पुत्र नहीं लौटता और खाली मार्ग यह तथ्य उसके पिता तथा राजा तक पहुँचाता है।'),
  ('scene-jambumali-meets-the-gate', 'ravana-escalates-through-his-council', 'en', 'The court sends its sons', 'News of Jambumali''s death reaches Ravana and Prahasta''s circle. Ravana''s answer is to command seven sons of his counsellors, drawing more households into the wager he began. Each new dispatch increases information about Lanka''s force while also multiplying grief and pressure inside the city.'),
  ('scene-jambumali-meets-the-gate', 'ravana-escalates-through-his-council', 'hi', 'सभा अपने पुत्र भेजती है', 'जम्बुमाली की मृत्यु की खबर रावण और प्रहस्त की सभा तक पहुँचती है। रावण सात मंत्रिपुत्रों को भेजकर और घरों को अपने शुरू किए दाँव में खींचता है। हर नया प्रेषण लंका की शक्ति की जानकारी बढ़ाता है, पर नगर के भीतर शोक और दबाव भी कई गुना करता है।'),
  ('scene-seven-houses-enter-the-war', 'families-grieve-before-the-next-departure', 'en', 'The dead are mourned before battle resumes', 'The seven counsellors'' sons prepare bright chariots and heavy bows while their mothers, relatives, and friends grieve those already killed. The pause makes clear that the defeated forces belonged to homes and relationships. Ravana''s escalating orders continue despite that visible cost.'),
  ('scene-seven-houses-enter-the-war', 'families-grieve-before-the-next-departure', 'hi', 'अगला युद्ध शुरू होने से पहले मृतकों का शोक होता है', 'सात मंत्रिपुत्र चमकीले रथ और भारी धनुष तैयार करते हैं, जबकि उनकी माताएँ, संबंधी और मित्र पहले मारे गए लोगों का शोक करते हैं। यह ठहराव दिखाता है कि पराजित सेना घरों और संबंधों से आई थी। दिखाई देती कीमत के बावजूद रावण के बढ़ते आदेश जारी रहते हैं।'),
  ('scene-seven-houses-enter-the-war', 'seven-chariots-fill-the-sky-with-arrows', 'en', 'The gate disappears under arrow rain', 'The seven warriors attack together, their chariots circling while arrows hide Hanuman like rain around a mountain. He uses the open sky, changing height and direction faster than the formation can close. The scene becomes a contest of coordinated range against movement rather than raw size alone.'),
  ('scene-seven-houses-enter-the-war', 'seven-chariots-fill-the-sky-with-arrows', 'hi', 'द्वार बाण-वर्षा में छिप जाता है', 'सातों योद्धा साथ आक्रमण करते हैं; उनके रथ घूमते और बाण हनुमान को पर्वत पर वर्षा की तरह ढकते हैं। हनुमान खुले आकाश में ऊँचाई और दिशा इतनी तेजी से बदलते हैं कि रचना बंद नहीं हो पाती। दृश्य केवल आकार नहीं, समन्वित दूरी और गति का संघर्ष बनता है।'),
  ('scene-seven-houses-enter-the-war', 'the-formation-breaks-at-close-range', 'en', 'Mobility turns into close combat', 'Hanuman breaks into the formation with roars, blows, and sudden changes of direction. The seven commanders and much of their force are killed; others flee instead of remaining to complete a doomed order. Survival here comes through retreat, not through proving loyalty to Ravana by dying.'),
  ('scene-seven-houses-enter-the-war', 'the-formation-breaks-at-close-range', 'hi', 'गतिशीलता निकट युद्ध में बदलती है', 'हनुमान गर्जना, प्रहार और अचानक दिशा-बदल से रचना के भीतर पहुँचते हैं। सातों सेनानायक और बड़ी सेना मारे जाते हैं; अन्य लोग निरर्थक आदेश पूरा करने के बजाय भागते हैं। यहाँ जीवन रावण के लिए मरकर निष्ठा सिद्ध करने से नहीं, पीछे हटने से बचता है।'),
  ('scene-seven-houses-enter-the-war', 'the-streets-record-the-cost', 'en', 'Broken vehicles remain after the roar', 'Frightened elephants and horses, shattered chariots, standards, and equipment fill the roads. Lanka''s alarm is no longer confined to a royal grove or gate; residents can see and hear the failure of each dispatch. Hanuman returns to the same entrance, still inviting another response.'),
  ('scene-seven-houses-enter-the-war', 'the-streets-record-the-cost', 'hi', 'गर्जना के बाद टूटे वाहन रह जाते हैं', 'भयभीत हाथी-घोड़े, टूटे रथ, ध्वज और उपकरण मार्ग भर देते हैं। लंका की चेतावनी अब वाटिका या द्वार तक सीमित नहीं; नगरवासी हर भेजी सेना की विफलता देख और सुन सकते हैं। हनुमान फिर उसी प्रवेश पर लौटकर अगली प्रतिक्रिया की प्रतीक्षा करते हैं।'),
  ('scene-five-generals-test-the-scale', 'ravana-finally-revises-his-model', 'en', 'The king stops calling him ordinary', 'After repeated losses, Ravana tells five senior generals that the intruder may only wear a monkey''s form. He compares Hanuman with Vali, Sugriva, Jambavan, and Nila and finds the present threat different in speed, intelligence, and shape-changing ability. Fear enters the command even while he suppresses it.'),
  ('scene-five-generals-test-the-scale', 'ravana-finally-revises-his-model', 'hi', 'राजा उसे साधारण कहना छोड़ता है', 'लगातार हानि के बाद रावण पाँच वरिष्ठ सेनापतियों से कहता है कि घुसपैठिया केवल वानर-रूप धारण किए हो सकता है। वह उसकी तुलना वाली, सुग्रीव, जाम्बवान और नील से कर गति, बुद्धि तथा रूप-बदल में अलग खतरा देखता है। भय दबाया जाता है, पर आदेश में प्रवेश कर चुका है।'),
  ('scene-five-generals-test-the-scale', 'capture-is-ordered-with-caution', 'en', 'Five generals are told to preserve themselves', 'Ravana orders Virupaksha, Yupaksha, Durdhara, Praghasa, and Bhasakarna to capture Hanuman with a combined force, but also warns that victory is unstable and they must judge place and time. It is the first command that openly admits survival matters. The army still advances into a battle chosen by the king.'),
  ('scene-five-generals-test-the-scale', 'capture-is-ordered-with-caution', 'hi', 'पाँच सेनापतियों को स्वयं को बचाने की चेतावनी मिलती है', 'रावण विरूपाक्ष, यूपाक्ष, दुर्धर्ष, प्रघस और भासकर्ण को संयुक्त सेना से हनुमान पकड़ने भेजता है, साथ ही चेताता है कि विजय अस्थिर है और समय-स्थान समझकर चलें। पहली बार आदेश खुले रूप से जीवन बचाने की बात मानता है। फिर भी सेना राजा द्वारा चुने युद्ध में बढ़ती है।'),
  ('scene-five-generals-test-the-scale', 'durdharas-chariot-breaks-beneath-hanuman', 'en', 'Arrow pressure ends in a vertical strike', 'Durdhara wounds Hanuman''s head and pursues him through the sky with hundreds of arrows. Hanuman expands, rises beyond the chariot, and drops onto it with enough force to break horses, wheels, and pole. Durdhara falls with the vehicle, ending the first part of the generals'' plan.'),
  ('scene-five-generals-test-the-scale', 'durdharas-chariot-breaks-beneath-hanuman', 'hi', 'बाण-दबाव ऊर्ध्व प्रहार पर समाप्त होता है', 'दुर्धर हनुमान के सिर को घायल कर सैकड़ों बाणों से आकाश में पीछा करता है। हनुमान रूप बढ़ाकर रथ से ऊपर जाते और उस पर ऐसे गिरते हैं कि घोड़े, पहिए तथा धुरा टूट जाते हैं। दुर्धर वाहन के साथ गिरता है और योजना का पहला भाग समाप्त होता है।'),
  ('scene-five-generals-test-the-scale', 'four-generals-and-the-host-fall', 'en', 'The remaining commanders cannot recover the plan', 'Virupaksha and Yupaksha strike together and are killed by an uprooted tree. Praghasa and Bhasakarna wound Hanuman before a torn mountain crest ends their attack. The remaining force collapses, and broken vehicles block the approaches; Ravana has gained a clearer measure at an immense cost.'),
  ('scene-five-generals-test-the-scale', 'four-generals-and-the-host-fall', 'hi', 'शेष सेनापति योजना सँभाल नहीं पाते', 'विरूपाक्ष और यूपाक्ष साथ प्रहार करते और उखड़े वृक्ष से मारे जाते हैं। प्रघस और भासकर्ण हनुमान को घायल करते हैं, फिर उखड़ी पर्वत-चोटी उनका आक्रमण समाप्त करती है। शेष सेना टूटती और वाहन मार्ग रोकते हैं; रावण को भारी कीमत पर अधिक स्पष्ट माप मिलता है।'),
  ('scene-aksha-takes-the-sky', 'a-glance-sends-the-prince', 'en', 'Aksha reads his father''s command', 'Ravana turns to Prince Aksha, already eager for battle, and sends him with a glance. The young warrior departs in a sky-ranging chariot built for speed and uneven ground. His readiness does not remove the father''s responsibility for choosing another son after every earlier force failed.'),
  ('scene-aksha-takes-the-sky', 'a-glance-sends-the-prince', 'hi', 'अक्ष पिता की दृष्टि से आदेश पढ़ता है', 'रावण पहले से युद्ध को उत्सुक राजकुमार अक्ष की ओर देखकर उसे भेजता है। युवा योद्धा गति और कठिन मार्ग के लिए बने आकाशगामी रथ में निकलता है। उसकी तत्परता हर पिछली सेना की विफलता के बाद पुत्र भेजने वाले पिता की जिम्मेदारी नहीं मिटाती।'),
  ('scene-aksha-takes-the-sky', 'both-fighters-study-each-other', 'en', 'Respect sharpens the duel', 'Aksha approaches without treating Hanuman as a beast to be swept aside. Hanuman notices the prince''s concentration, weapons, and control; Aksha studies the intruder''s speed and changing scale. Their mutual assessment makes the contest more dangerous because neither repeats the contempt that ruined earlier attacks.'),
  ('scene-aksha-takes-the-sky', 'both-fighters-study-each-other', 'hi', 'परस्पर सम्मान द्वंद्व को तीखा करता है', 'अक्ष हनुमान को हटाए जाने वाला पशु मानकर नहीं आता। हनुमान राजकुमार की एकाग्रता, हथियार और नियंत्रण देखते हैं; अक्ष घुसपैठिए की गति और बदलता आकार परखता है। परस्पर आकलन द्वंद्व को अधिक खतरनाक बनाता है क्योंकि कोई पिछली सेनाओं का तिरस्कार नहीं दोहराता।'),
  ('scene-aksha-takes-the-sky', 'aksha-keeps-pace-in-the-air', 'en', 'The prince follows where armies could not', 'Aksha strikes Hanuman''s head and arm, then follows him into the sky while maintaining a dense arrow field. Hanuman threads through the shafts but cannot simply leave the chariot behind. The prince''s skill is real, and the battle grows instead of resolving through one display of size.'),
  ('scene-aksha-takes-the-sky', 'aksha-keeps-pace-in-the-air', 'hi', 'राजकुमार वहाँ पीछा करता है जहाँ सेनाएँ नहीं कर सकीं', 'अक्ष हनुमान के सिर और भुजा पर प्रहार कर घने बाण-जाल के साथ आकाश में पीछा करता है। हनुमान बाणों के बीच निकलते हैं, पर रथ को सरलता से पीछे नहीं छोड़ पाते। राजकुमार का कौशल वास्तविक है और युद्ध एक आकार-प्रदर्शन से समाप्त होने के बजाय बढ़ता है।'),
  ('scene-aksha-takes-the-sky', 'hanuman-hesitates-before-ending-the-threat', 'en', 'Admiration does not find a safe exit', 'Hanuman thinks Aksha is too accomplished for his age and feels reluctant to kill him, yet concludes the prince''s growing attack will not stop. He destroys the chariot, catches Aksha after the prince continues through the air, and casts him down. Hanuman returns to the gate; Ravana receives a son''s death, not another abstract loss.'),
  ('scene-aksha-takes-the-sky', 'hanuman-hesitates-before-ending-the-threat', 'hi', 'प्रशंसा सुरक्षित निकास नहीं खोज पाती', 'हनुमान सोचते हैं कि अक्ष आयु से कहीं अधिक निपुण है और उसे मारना नहीं चाहते, फिर मानते हैं कि बढ़ता आक्रमण रुकेगा नहीं। वे रथ तोड़ते, आकाश में आगे बढ़े अक्ष को पकड़कर नीचे गिराते हैं। हनुमान द्वार लौटते हैं; रावण को अब अनाम हानि नहीं, पुत्र की मृत्यु मिलती है।'),
  ('scene-indrajit-binds-a-willing-prisoner', 'ravana-sends-the-son-he-trusts-most', 'en', 'Indrajit receives the hardest command', 'After Aksha''s death, Ravana turns to Indrajit, praising the son who has fought celestial powers and understands weapons, timing, and counsel. He admits armies and ordinary weapons are failing. Sending Indrajit may be strategically rational, but it also shows how Ravana keeps feeding his own house into the consequences of the abduction.'),
  ('scene-indrajit-binds-a-willing-prisoner', 'ravana-sends-the-son-he-trusts-most', 'hi', 'इन्द्रजित को सबसे कठिन आदेश मिलता है', 'अक्ष की मृत्यु के बाद रावण इन्द्रजित को चुनता है—उस पुत्र को जिसने दिव्य शक्तियों से युद्ध किया और हथियार, समय तथा नीति समझता है। वह मानता है कि सेनाएँ और सामान्य अस्त्र विफल हैं। इन्द्रजित को भेजना रणनीतिक हो सकता है, पर यह भी दिखाता है कि रावण हरण के परिणामों में अपना ही घर झोंक रहा है।'),
  ('scene-indrajit-binds-a-willing-prisoner', 'neither-fighter-finds-an-opening', 'en', 'Arrows and movement reach a deadlock', 'Indrajit tracks Hanuman with disciplined volleys while Hanuman changes scale, altitude, and direction. Each reads the other quickly enough to deny a decisive opening. The duel becomes a problem of restraint rather than killing, and Indrajit stops wasting arrows on an opponent they cannot finish.'),
  ('scene-indrajit-binds-a-willing-prisoner', 'neither-fighter-finds-an-opening', 'hi', 'बाण और गति गतिरोध तक पहुँचते हैं', 'इन्द्रजित अनुशासित बाण-वर्षा से हनुमान का पीछा करता है, जबकि हनुमान आकार, ऊँचाई और दिशा बदलते हैं। दोनों एक-दूसरे को इतना जल्दी पढ़ते हैं कि निर्णायक अवसर नहीं मिलता। द्वंद्व हत्या के बजाय बंधन की समस्या बनता है और इन्द्रजित निष्फल बाण रोकता है।'),
  ('scene-indrajit-binds-a-willing-prisoner', 'the-brahma-weapon-imposes-a-pause', 'en', 'A sacred restraint reaches Hanuman', 'Indrajit invokes the weapon associated with Brahma, and Hanuman falls motionless. Remembering the boon and the weapon''s limited authority, Hanuman chooses not to break its restraint immediately. He treats the pause as real while recognising that it cannot permanently imprison or kill him.'),
  ('scene-indrajit-binds-a-willing-prisoner', 'the-brahma-weapon-imposes-a-pause', 'hi', 'दिव्य बंधन हनुमान को रोकता है', 'इन्द्रजित ब्रह्मा से जुड़ा अस्त्र चलाता है और हनुमान निश्चल गिरते हैं। वरदान और अस्त्र की सीमित शक्ति याद करके हनुमान उसका बंधन तुरंत नहीं तोड़ते। वे ठहराव को वास्तविक मानते हैं, साथ ही जानते हैं कि यह उन्हें स्थायी रूप से कैद या मार नहीं सकता।'),
  ('scene-indrajit-binds-a-willing-prisoner', 'capture-opens-the-court-route', 'en', 'Hanuman sees value in being carried', 'Hanuman decides that captors may take him to Ravana, giving the messenger the audience he wanted. He groans and stays still so the plan remains believable. Capture is therefore neither pure defeat nor proof that every earlier risk was controlled; it is a new decision made inside a dangerous constraint.'),
  ('scene-indrajit-binds-a-willing-prisoner', 'capture-opens-the-court-route', 'hi', 'हनुमान पकड़े जाने में उपयोग देखते हैं', 'हनुमान तय करते हैं कि पकड़ने वाले उन्हें रावण तक ले जा सकते हैं और दूत को वांछित सभा मिल जाएगी। योजना विश्वसनीय रखने के लिए वे कराहते और स्थिर रहते हैं। गिरफ्तारी न पूर्ण पराजय है, न प्रमाण कि हर पिछला जोखिम नियंत्रित था; यह खतरनाक बंधन के भीतर नया निर्णय है।'),
  ('scene-indrajit-binds-a-willing-prisoner', 'ordinary-ropes-cancel-the-first-bond', 'en', 'The captors unknowingly free him', 'Soldiers add bark and rope, unaware that physical binding cancels the Brahma weapon''s hold. Indrajit realises their mistake and knows the sacred restraint cannot simply be fired again. Hanuman also knows he is free, but hides the change because the escort still leads where he needs to go.'),
  ('scene-indrajit-binds-a-willing-prisoner', 'ordinary-ropes-cancel-the-first-bond', 'hi', 'पकड़ने वाले अनजाने में उन्हें मुक्त करते हैं', 'सैनिक छाल और रस्सियाँ जोड़ते हैं, यह जाने बिना कि भौतिक बंधन ब्रह्मास्त्र का प्रभाव मिटा देता है। इन्द्रजित भूल समझता है और जानता है कि दिव्य बंधन तुरंत दोहराया नहीं जा सकता। हनुमान भी अपनी मुक्ति जानते हैं, पर उसे छिपाते हैं क्योंकि पहरा उन्हें इच्छित स्थान तक ले जा रहा है।'),
  ('scene-indrajit-binds-a-willing-prisoner', 'the-city-sees-a-prisoner-who-is-not-trapped', 'en', 'Threats accompany the court procession', 'The escort drags Hanuman through the city while onlookers demand death, fire, or worse. He absorbs the abuse without revealing he can leave, studying the route and the people who gather around it. At the palace, he is presented as a captured enemy even though the decisive restraint has already failed.'),
  ('scene-indrajit-binds-a-willing-prisoner', 'the-city-sees-a-prisoner-who-is-not-trapped', 'hi', 'सभा-यात्रा के साथ धमकियाँ चलती हैं', 'पहरा हनुमान को नगर से खींचता है और दर्शक मृत्यु, अग्नि तथा कठोर दंड की माँग करते हैं। वे अपनी मुक्ति छिपाकर अपमान सहते, मार्ग और भीड़ देखते हैं। महल में उन्हें पकड़ा शत्रु दिखाया जाता है, जबकि निर्णायक बंधन पहले ही निष्फल हो चुका है।'),
  ('scene-hanuman-sees-ravanas-court', 'splendour-fills-the-first-view', 'en', 'The captive enters a brilliant court', 'Hanuman sees Ravana crowned, jewelled, richly clothed, and seated above a court designed to project wealth and command. The visual splendour is real; it explains why subjects and enemies might feel awe. It does not itself answer how Sita came to be held or whether the king''s order is just.'),
  ('scene-hanuman-sees-ravanas-court', 'splendour-fills-the-first-view', 'hi', 'बंदी चमकती सभा में प्रवेश करता है', 'हनुमान रावण को मुकुट, रत्न और महंगे वस्त्रों में ऐसी सभा पर बैठे देखते हैं जो धन और आदेश का प्रभाव बनाती है। वैभव वास्तविक है और बताता है कि प्रजा तथा शत्रु क्यों चकित हों। यह नहीं बताता कि सीता वहाँ कैसे बंदी हुईं या राजा का आदेश न्यायपूर्ण है।'),
  ('scene-hanuman-sees-ravanas-court', 'power-is-organised-around-counsel', 'en', 'Ravana is not ruling alone', 'Prahasta, Mahaparshva, Nikumbha, and other counsellors surround the throne, with attendants and old servants completing the institution. Hanuman observes a working government, not an empty chamber. Decisions about Sita, armies, and punishment therefore move through a network even when Ravana dominates it.'),
  ('scene-hanuman-sees-ravanas-court', 'power-is-organised-around-counsel', 'hi', 'रावण अकेला शासन नहीं कर रहा', 'प्रहस्त, महापार्श्व, निकुम्भ और अन्य मंत्री सिंहासन को घेरे हैं; परिचारक तथा पुराने सेवक संस्था पूरी करते हैं। हनुमान खाली कक्ष नहीं, काम करता शासन देखते हैं। इसलिए सीता, सेना और दंड के निर्णय रावण के प्रभुत्व के बावजूद एक जाल से गुजरते हैं।'),
  ('scene-hanuman-sees-ravanas-court', 'hanuman-recognises-ravanas-capacity', 'en', 'The enemy''s ability earns attention', 'Hanuman is struck by Ravana''s patience, force, presence, and ability to command. He imagines how such capacity could have protected a vast realm if directed differently. Respecting capability does not require excusing its use; accurate judgment needs both the strength and the harm it serves.'),
  ('scene-hanuman-sees-ravanas-court', 'hanuman-recognises-ravanas-capacity', 'hi', 'शत्रु की क्षमता ध्यान माँगती है', 'हनुमान रावण के धैर्य, बल, उपस्थिति और आदेश-क्षमता से प्रभावित होते हैं। वे सोचते हैं कि यही सामर्थ्य दूसरी दिशा में विशाल राज्य की रक्षा कर सकता था। क्षमता का सम्मान उसके उपयोग को क्षमा करना नहीं; सही आकलन शक्ति और उससे किए नुकसान दोनों देखता है।'),
  ('scene-hanuman-sees-ravanas-court', 'the-abduction-corrupts-the-whole-display', 'en', 'One choice changes the meaning of the throne', 'The thought returns to Sita: this ruler used extraordinary resources to seize and confine someone who refused him. The court''s beauty and discipline now intensify the question because Ravana cannot claim ignorance or lack of alternatives. Hanuman prepares to speak to the decision-maker he has finally reached.'),
  ('scene-hanuman-sees-ravanas-court', 'the-abduction-corrupts-the-whole-display', 'hi', 'एक चुनाव सिंहासन का अर्थ बदल देता है', 'विचार सीता पर लौटता है—इस शासक ने असाधारण संसाधन उस व्यक्ति को हरने और बंदी रखने में लगाए जिसने उसे अस्वीकार किया। सभा का सौंदर्य और अनुशासन प्रश्न को तीखा करते हैं क्योंकि रावण अज्ञान या विकल्पहीनता नहीं कह सकता। हनुमान अंततः मिले निर्णयकर्ता से बोलने को तैयार होते हैं।'),
  ('scene-the-prisoner-names-his-mission', 'ravana-searches-for-a-hidden-patron', 'en', 'The court assumes a greater power sent him', 'Ravana wonders whether the prisoner is Nandi, a celestial agent, or another old enemy in disguise. Prahasta offers release if Hanuman truthfully names Indra, Varuna, Yama, Kubera, or Vishnu as his patron. The court''s categories reveal whom Lanka fears, but none yet fits the actual alliance.'),
  ('scene-the-prisoner-names-his-mission', 'ravana-searches-for-a-hidden-patron', 'hi', 'सभा मानती है कि किसी बड़ी शक्ति ने उसे भेजा', 'रावण सोचता है कि बंदी नंदी, किसी देवता का दूत या पुराना शत्रु वेश बदलकर आया है। प्रहस्त सत्य बताने पर इन्द्र, वरुण, यम, कुबेर या विष्णु का भेजा मानकर मुक्ति का प्रस्ताव देता है। सभा की श्रेणियाँ लंका के भय खोलती हैं, पर वास्तविक मैत्री उनमें नहीं आती।'),
  ('scene-the-prisoner-names-his-mission', 'hanuman-keeps-his-own-identity', 'en', 'He is not a god wearing a monkey', 'Hanuman denies serving those powers in disguise and says the monkey form is his own. He names his lineage through the Wind and his role in Sugriva''s service. The answer refuses both contempt and inflation: he does not need to become a hidden god for his intelligence, strength, and mission to matter.'),
  ('scene-the-prisoner-names-his-mission', 'hanuman-keeps-his-own-identity', 'hi', 'वे वानर-वेश में देवता नहीं', 'हनुमान उन देवताओं का छद्म सेवक होने से इनकार कर कहते हैं कि वानर-रूप उनका अपना है। वे पवन से अपना वंश और सुग्रीव की सेवा में भूमिका बताते हैं। उत्तर तिरस्कार और अतिशयोक्ति दोनों छोड़ता है—उनकी बुद्धि, शक्ति और अभियान महत्त्वपूर्ण होने के लिए उन्हें छिपा देवता बनना आवश्यक नहीं।'),
  ('scene-the-prisoner-names-his-mission', 'the-destruction-is-admitted-as-access', 'en', 'Hanuman explains why he provoked the court', 'Hanuman says he damaged the grove to force an audience with Ravana and fought when forces attacked him. He also reveals that he allowed the weapon to restrain him long enough to be brought inside. The explanation makes his strategy legible without pretending every death and destroyed place was inevitable.'),
  ('scene-the-prisoner-names-his-mission', 'the-destruction-is-admitted-as-access', 'hi', 'हनुमान बताते हैं कि सभा को क्यों उकसाया', 'हनुमान कहते हैं कि उन्होंने रावण तक पहुँचने के लिए वाटिका उजाड़ी और आक्रमण करने वाली सेनाओं से लड़े। वे यह भी बताते हैं कि भीतर लाए जाने तक उन्होंने अस्त्र का बंधन स्वीकार किया। स्पष्टीकरण रणनीति समझाता है, पर हर मृत्यु और नष्ट स्थान को अपरिहार्य नहीं बनाता।'),
  ('scene-the-prisoner-names-his-mission', 'interrogation-becomes-a-message', 'en', 'The prisoner asks the king to listen', 'Hanuman says he comes on Rama''s business and carries words intended for Ravana''s own welfare. His captured posture no longer defines the exchange; the court must decide whether it will treat him as an envoy. He begins with Sugriva, whose alliance Ravana did not include in his list of celestial threats.'),
  ('scene-the-prisoner-names-his-mission', 'interrogation-becomes-a-message', 'hi', 'बंदी राजा से सुनने को कहता है', 'हनुमान कहते हैं कि वे राम के कार्य से आए हैं और रावण के हित के लिए भी शब्द लाए हैं। अब उनका बंधा रूप संवाद को परिभाषित नहीं करता; सभा को तय करना है कि उसे दूत माना जाए या नहीं। वे सुग्रीव से आरंभ करते हैं, जिसकी मैत्री रावण की दिव्य खतरा-सूची में नहीं थी।'),
  ('scene-hanuman-warns-ravana', 'sugrivas-message-opens-with-relationship', 'en', 'The warning begins as a brother''s greeting', 'Hanuman speaks in Sugriva''s name and addresses Ravana as one ruler to another, even using the language of kinship. He does not begin by shouting doom. The opening gives Ravana a path to hear the facts and change course without first surrendering his public standing.'),
  ('scene-hanuman-warns-ravana', 'sugrivas-message-opens-with-relationship', 'hi', 'चेतावनी भाई के अभिवादन से शुरू होती है', 'हनुमान सुग्रीव के नाम से एक शासक को दूसरे शासक की तरह संबोधित करते हैं और संबंध की भाषा भी रखते हैं। वे विनाश की गर्जना से शुरू नहीं करते। आरंभ रावण को तथ्य सुनने और सार्वजनिक प्रतिष्ठा तुरंत छोड़े बिना दिशा बदलने का मार्ग देता है।'),
  ('scene-hanuman-warns-ravana', 'the-chain-reaches-the-confirmed-sighting', 'en', 'Every step explains how the envoy arrived', 'Hanuman recounts Dasharatha, exile, Sita''s abduction, Rama''s meeting with Sugriva, Vali''s death, the restored kingdom, and the world-wide search. He ends with his own ocean crossing and direct sight of Sita in Ravana''s house. The message is anchored in events Ravana and the court can test.'),
  ('scene-hanuman-warns-ravana', 'the-chain-reaches-the-confirmed-sighting', 'hi', 'हर कड़ी बताती है कि दूत यहाँ कैसे पहुँचा', 'हनुमान दशरथ, वनवास, सीता-हरण, राम-सुग्रीव मिलन, वाली की मृत्यु, लौटे राज्य और विश्व-व्यापी खोज की कड़ी बताते हैं। अंत में वे अपना समुद्र-पार और रावण के घर में सीता के प्रत्यक्ष दर्शन रखते हैं। संदेश उन घटनाओं पर टिका है जिन्हें रावण और सभा परख सकते हैं।'),
  ('scene-hanuman-warns-ravana', 'return-is-presented-as-the-off-ramp', 'en', 'Ravana still has a choice', 'Hanuman asks Ravana to return Sita and preserve the people, wealth, family, and achievement his rule has gathered. The warning is severe: Rama, Lakshmana, and the allied force will not leave the abduction unanswered. Yet the immediate requested action is release, not destruction for its own sake.'),
  ('scene-hanuman-warns-ravana', 'return-is-presented-as-the-off-ramp', 'hi', 'रावण के पास अभी भी चुनाव है', 'हनुमान रावण से सीता को लौटाकर अपनी प्रजा, संपत्ति, परिवार और शासन की उपलब्धियाँ बचाने को कहते हैं। चेतावनी कठोर है—राम, लक्ष्मण और सहयोगी सेना हरण को अनुत्तरित नहीं छोड़ेंगे। फिर भी तत्काल माँग मुक्ति है, केवल विनाश नहीं।'),
  ('scene-hanuman-warns-ravana', 'past-power-cannot-cancel-present-harm', 'en', 'Ravana''s achievements do not erase the abduction', 'Hanuman acknowledges Ravana''s austerities, strength, and victories, then argues that accumulated merit and protection cannot make every later act consequence-free. The alliance is dangerous precisely because it falls outside the categories Ravana believes his boons defeated. Confidence built on old wins has become a blind spot.'),
  ('scene-hanuman-warns-ravana', 'past-power-cannot-cancel-present-harm', 'hi', 'रावण की उपलब्धियाँ हरण नहीं मिटातीं', 'हनुमान रावण की तपस्या, शक्ति और विजय मानते हैं, फिर कहते हैं कि संचित पुण्य और सुरक्षा हर बाद के कर्म को परिणामहीन नहीं बनाते। मैत्री खतरनाक है क्योंकि वह उन श्रेणियों से बाहर है जिन्हें रावण अपने वरदानों से हारा मानता है। पुरानी जीतों का विश्वास अब अंधा स्थान बन गया है।'),
  ('scene-hanuman-warns-ravana', 'ravana-answers-warning-with-death', 'en', 'The off-ramp closes in anger', 'Hanuman''s speech grows into sweeping warnings about Lanka''s destruction, but its practical demand remains Sita''s return. Ravana hears the challenge to his power and orders the envoy killed. The decision shifts the court from debating the message to debating whether a ruler may execute the person who carried it.'),
  ('scene-hanuman-warns-ravana', 'ravana-answers-warning-with-death', 'hi', 'क्रोध में निकास बंद होता है', 'हनुमान की वाणी लंका-विनाश की व्यापक चेतावनियों तक बढ़ती है, पर व्यावहारिक माँग सीता की वापसी ही रहती है। रावण शक्ति को दी चुनौती सुनकर दूत की हत्या का आदेश देता है। निर्णय सभा को संदेश से हटाकर इस प्रश्न पर लाता है कि क्या राजा संदेशवाहक को मार सकता है।'),
  ('scene-vibhishana-stops-an-execution', 'vibhishana-interrupts-before-action', 'en', 'Dissent enters before the order becomes death', 'Vibhishana does not wait for a private moment. He recognises that delay would make Ravana''s command irreversible and speaks in the same court that heard it. Respect for his elder brother remains visible, but it does not become silence when a life and a rule are at stake.'),
  ('scene-vibhishana-stops-an-execution', 'vibhishana-interrupts-before-action', 'hi', 'आदेश मृत्यु बने उससे पहले असहमति आती है', 'विभीषण निजी अवसर की प्रतीक्षा नहीं करते। वे समझते हैं कि देर रावण के आदेश को अपरिवर्तनीय बना देगी और उसी सभा में बोलते हैं जिसने उसे सुना। बड़े भाई का सम्मान बना रहता है, पर प्राण और नियम दाँव पर हों तो वह मौन नहीं बनता।'),
  ('scene-vibhishana-stops-an-execution', 'the-envoy-rule-is-stated', 'en', 'A messenger is not the message''s author', 'Vibhishana says rulers do not kill envoys for performing their assigned function, even when the envoy has caused harm and the message is hostile. Hanuman can be restrained or punished, but execution would break a shared rule of political exchange. Without that rule, no warning, negotiation, or surrender could safely cross between enemies.'),
  ('scene-vibhishana-stops-an-execution', 'the-envoy-rule-is-stated', 'hi', 'दूत संदेश का रचयिता नहीं', 'विभीषण कहते हैं कि दूत ने हानि की हो और संदेश शत्रुतापूर्ण हो, तब भी राजा उसे सौंपा कार्य करने के लिए नहीं मारते। हनुमान को रोका या दंडित किया जा सकता है, पर हत्या राजनीतिक संवाद का साझा नियम तोड़ेगी। उस नियम के बिना चेतावनी, वार्ता या समर्पण शत्रुओं के बीच सुरक्षित नहीं जा सकेगा।'),
  ('scene-vibhishana-stops-an-execution', 'ravana-tries-to-make-killing-righteous', 'en', 'Anger searches for a legal name', 'Ravana answers that killing a wrongdoer cannot itself be wrong, folding the ruined grove and dead forces into one justification. Vibhishana refuses the shortcut: wrongdoing may support punishment, but it does not erase the specific protection attached to an envoy. Rules matter most when anger has evidence it can use.'),
  ('scene-vibhishana-stops-an-execution', 'ravana-tries-to-make-killing-righteous', 'hi', 'क्रोध अपने लिए न्याय का नाम खोजता है', 'रावण कहता है कि अपराधी को मारना गलत नहीं और उजड़ी वाटिका तथा मारी सेना को एक औचित्य में जोड़ता है। विभीषण यह छोटा रास्ता अस्वीकारते हैं—हानि दंड का आधार हो सकती है, पर दूत की विशेष सुरक्षा नहीं मिटाती। नियम तब सबसे अधिक जरूरी हैं जब क्रोध के पास उपयोग करने योग्य तथ्य हों।'),
  ('scene-vibhishana-stops-an-execution', 'punishment-replaces-execution', 'en', 'The court accepts a narrower boundary', 'Vibhishana lists non-lethal punishments known to the court and argues that killing Hanuman would also destroy the route by which Rama and Lakshmana might be drawn into open confrontation. Ravana finally accepts that the envoy will live. This is not mercy without harm; it is a real boundary that survives inside a hostile court.'),
  ('scene-vibhishana-stops-an-execution', 'punishment-replaces-execution', 'hi', 'सभा संकरी मर्यादा स्वीकारती है', 'विभीषण सभा में ज्ञात गैर-घातक दंड बताते और कहते हैं कि हनुमान की हत्या राम-लक्ष्मण तक खुली चुनौती पहुँचाने का मार्ग भी मिटा देगी। रावण अंततः दूत को जीवित रखने पर मानता है। यह बिना हानि की दया नहीं, शत्रुतापूर्ण सभा के भीतर बची वास्तविक मर्यादा है।'),
  ('scene-the-burning-tail-maps-lanka', 'ravana-turns-the-tail-into-a-spectacle', 'en', 'Punishment is made public', 'Ravana orders cloth and oil wrapped around Hanuman''s tail, then commands that the burning prisoner be paraded across Lanka. The aim is humiliation: friends and allies should later see a disfigured messenger. Crowds, drums, and proclamations turn punishment into a state performance.'),
  ('scene-the-burning-tail-maps-lanka', 'ravana-turns-the-tail-into-a-spectacle', 'hi', 'दंड को सार्वजनिक तमाशा बनाया जाता है', 'रावण हनुमान की पूँछ पर कपड़ा और तेल बँधवाकर जलते बंदी को पूरे लंका में घुमाने का आदेश देता है। उद्देश्य अपमान है—मित्र और सहयोगी बाद में विकृत दूत देखें। भीड़, नगाड़े और घोषणाएँ दंड को राज्य के प्रदर्शन में बदल देती हैं।'),
  ('scene-the-burning-tail-maps-lanka', 'hanuman-chooses-to-use-the-route', 'en', 'The prisoner studies what night concealed', 'Hanuman knows he can break the ordinary bonds, but lets the parade continue because daylight reveals fortifications, courtyards, crossings, side streets, terraces, and building interiors he could not fully inspect at night. The imposed route becomes intelligence. Enduring it is a calculation, not proof that the abuse is harmless.'),
  ('scene-the-burning-tail-maps-lanka', 'hanuman-chooses-to-use-the-route', 'hi', 'बंदी वह देखता है जो रात ने छिपाया था', 'हनुमान जानते हैं कि साधारण बंधन तोड़ सकते हैं, फिर भी जुलूस चलने देते हैं क्योंकि दिन में किलेबंदी, आँगन, चौराहे, गलियाँ, छतें और भवनों के भीतर का वह भाग दिखता है जो रात में पूरा नहीं दिखा। थोपा मार्ग जानकारी बनता है। उसे सहना गणना है, यह प्रमाण नहीं कि अपमान हानिरहित है।'),
  ('scene-the-burning-tail-maps-lanka', 'sita-hears-what-the-court-has-done', 'en', 'News of the fire reaches the grove', 'Guards tell Sita that the visitor who spoke with her is being dragged through Lanka with his tail aflame. She turns to Fire and asks that the flame be cool to Hanuman if the truth, care, and commitments she has lived carry any force. The prayer responds to immediate danger; it is not a test that makes harmed people prove moral perfection.'),
  ('scene-the-burning-tail-maps-lanka', 'sita-hears-what-the-court-has-done', 'hi', 'अग्नि का समाचार वाटिका पहुँचता है', 'रक्षक सीता को बताते हैं कि उनसे बात करने वाले आगंतुक को जलती पूँछ के साथ लंका में घुमाया जा रहा है। वे अग्नि से प्रार्थना करती हैं कि उनके जिए सत्य, स्नेह और संबंधों में बल हो तो लौ हनुमान के लिए शीतल रहे। प्रार्थना तात्कालिक खतरे का उत्तर है; पीड़ित से नैतिक पूर्णता सिद्ध कराने वाली परीक्षा नहीं।'),
  ('scene-the-burning-tail-maps-lanka', 'the-flame-is-bright-but-cool', 'en', 'Hanuman feels no burn', 'The tail burns visibly, yet Hanuman feels cold rather than pain and a cool wind moves around him. He connects the protection with Sita, Rama, the Wind, and the earlier aid of Mainaka. Whatever its sacred cause, the practical fact is clear: the punishment has failed to damage him as intended.'),
  ('scene-the-burning-tail-maps-lanka', 'the-flame-is-bright-but-cool', 'hi', 'हनुमान को जलन नहीं होती', 'पूँछ स्पष्ट जलती है, फिर भी हनुमान को पीड़ा के बजाय शीतलता मिलती और ठंडी हवा उन्हें घेरे रहती है। वे रक्षा को सीता, राम, पवन और मैनाक की पिछली सहायता से जोड़ते हैं। पवित्र कारण जो भी हो, व्यावहारिक तथ्य स्पष्ट है—दंड इच्छित हानि नहीं कर पाया।'),
  ('scene-the-burning-tail-maps-lanka', 'the-bonds-break-at-an-empty-gate', 'en', 'Reconnaissance ends in escape', 'Once the route has shown enough, Hanuman snaps the bonds, changes size to shed them, and reaches a gate whose guards have thinned. He takes the iron bolt and kills the remaining warders. The city tour is complete, but the fire still burns on his tail and creates a new decision rather than a finished escape.'),
  ('scene-the-burning-tail-maps-lanka', 'the-bonds-break-at-an-empty-gate', 'hi', 'नगर-दर्शन मुक्ति पर समाप्त होता है', 'पर्याप्त मार्ग देख लेने पर हनुमान बंधन तोड़ते, आकार बदलकर रस्सियाँ उतारते और कम रक्षकों वाले द्वार पहुँचते हैं। वे लोहे की अर्गला से शेष रक्षक मारते हैं। नगर-दर्शन पूरा है, पर पूँछ की आग अभी जल रही है और समाप्त पलायन के बजाय नया निर्णय खोलती है।'),
  ('scene-the-burning-tail-maps-lanka', 'the-city-now-lies-open-before-him', 'en', 'A weapon and a map meet', 'Hanuman stands free with an iron bolt, a burning tail, and a daylight map of commanders'' houses, the palace, streets, and exits. Ravana intended the flame to mark a defeated spy. Instead it has become portable fire in the hands of someone who knows where the city''s power is concentrated.'),
  ('scene-the-burning-tail-maps-lanka', 'the-city-now-lies-open-before-him', 'hi', 'एक हथियार और मानचित्र साथ आते हैं', 'हनुमान लोहे की अर्गला, जलती पूँछ और सेनानायकों के घर, महल, गलियाँ तथा निकास दिखाते दिन के मानचित्र के साथ स्वतंत्र खड़े हैं। रावण ने लौ से पराजित गुप्तचर चिह्नित करना चाहा था। अब वही आग उस व्यक्ति के हाथ में है जो नगर की शक्ति के केंद्र जानता है।'),
  ('scene-fire-outruns-the-targets', 'command-houses-are-chosen-first', 'en', 'The first flames follow the chain of command', 'Hanuman leaps from Prahasta''s mansion to the houses of Mahaparshva, Indrajit, Jambumali, Kumbhakarna, and other named leaders. The target pattern follows military and court authority rather than random roofs. Ravana''s palace becomes the largest chosen centre of the system that ordered Sita''s captivity and Hanuman''s punishment.'),
  ('scene-fire-outruns-the-targets', 'command-houses-are-chosen-first', 'hi', 'पहली लपटें आदेश-श्रृंखला का पीछा करती हैं', 'हनुमान प्रहस्त के भवन से महापार्श्व, इन्द्रजित, जम्बुमाली, कुम्भकर्ण और अन्य नामित नेताओं के घरों पर जाते हैं। लक्ष्य-क्रम अनजान छतों के बजाय सेना और सभा की सत्ता का पीछा करता है। रावण का महल सीता की बंदी और हनुमान के दंड की व्यवस्था का सबसे बड़ा चुना केंद्र बनता है।'),
  ('scene-fire-outruns-the-targets', 'vibhishanas-house-is-spared', 'en', 'One act of dissent changes one target', 'Hanuman deliberately passes Vibhishana''s home without setting it alight. The spared house remembers the brother who stopped an envoy''s execution inside the court. It proves Hanuman is still distinguishing conduct and allegiance at the moment ignition begins, though that intention will not control every later flame.'),
  ('scene-fire-outruns-the-targets', 'vibhishanas-house-is-spared', 'hi', 'एक असहमति एक लक्ष्य बदलती है', 'हनुमान जानबूझकर विभीषण का घर बिना जलाए छोड़ते हैं। बचा भवन उस भाई को याद रखता है जिसने सभा में दूत की हत्या रोकी थी। यह सिद्ध करता है कि आग शुरू करते समय हनुमान आचरण और पक्ष में भेद कर रहे हैं, यद्यपि आगे हर लौ उनके नियंत्रण में नहीं रहेगी।'),
  ('scene-fire-outruns-the-targets', 'wind-connects-what-hanuman-separated', 'en', 'The fire stops obeying the map', 'Wind carries flame across roofs, timber, cloth, oil, and close-built streets. Fires begun at command houses join and spread beyond Hanuman''s selected points. The same element associated with his speed now multiplies a consequence he cannot direct house by house.'),
  ('scene-fire-outruns-the-targets', 'wind-connects-what-hanuman-separated', 'hi', 'अग्नि मानचित्र मानना छोड़ देती है', 'हवा लपटों को छत, लकड़ी, कपड़े, तेल और सघन गलियों में ले जाती है। सत्ता-भवनों से शुरू आग जुड़कर हनुमान के चुने बिंदुओं से आगे फैलती है। उनकी गति से जुड़ा वही तत्व अब ऐसा परिणाम बढ़ाता है जिसे वे घर-घर नियंत्रित नहीं कर सकते।'),
  ('scene-fire-outruns-the-targets', 'families-and-animals-enter-the-consequence', 'en', 'The city is more than its rulers', 'Residents run with children and elders; animals, birds, vehicles, and homes are caught in smoke, collapse, and panic. Some people fall while escaping. These lives are not interchangeable with Ravana''s commanders, and their suffering cannot be erased by calling the whole city an enemy fortress.'),
  ('scene-fire-outruns-the-targets', 'families-and-animals-enter-the-consequence', 'hi', 'नगर केवल उसके शासक नहीं', 'निवासी बच्चों और वृद्धों को लेकर भागते हैं; पशु, पक्षी, वाहन और घर धुएँ, गिरती रचनाओं और भगदड़ में फँसते हैं। कुछ लोग निकलते समय गिरते हैं। ये जीवन रावण के सेनानायकों के समान नहीं और पूरे नगर को शत्रु-दुर्ग कह देने से उनका कष्ट मिटता नहीं।'),
  ('scene-fire-outruns-the-targets', 'lanka-becomes-a-citywide-disaster', 'en', 'A targeted strike becomes catastrophe', 'Palaces crack, metals and jewels melt, smoke covers the sky, and cries move through every district. Hanuman sees fear and disarray on a scale far beyond the first objective of measuring forces. Celestial witnesses may marvel at the feat, while the city below still holds destroyed homes, dead fighters, and people who never chose Ravana''s decision.'),
  ('scene-fire-outruns-the-targets', 'lanka-becomes-a-citywide-disaster', 'hi', 'लक्षित प्रहार आपदा बनता है', 'महल फटते, धातु और रत्न पिघलते, धुआँ आकाश ढकता और हर क्षेत्र में पुकार फैलती है। हनुमान भय तथा अव्यवस्था को सेना परखने के पहले उद्देश्य से कहीं बड़े पैमाने पर देखते हैं। दिव्य साक्षी पराक्रम पर चकित हो सकते हैं, पर नीचे नगर में टूटे घर, मरे सैनिक और रावण का निर्णय न चुनने वाले लोग बने रहते हैं।'),
  ('scene-fire-outruns-the-targets', 'the-tail-is-quenched-in-the-sea', 'en', 'Hanuman ends the flame but not its effects', 'Hanuman reaches the shore and lowers his burning tail into the ocean. The portable source of ignition goes dark, but fires already moving through Lanka continue and the people harmed do not reset. Quenching creates the first still moment in which he can evaluate what his anger and strategy have produced.'),
  ('scene-fire-outruns-the-targets', 'the-tail-is-quenched-in-the-sea', 'hi', 'हनुमान लौ बुझाते हैं, परिणाम नहीं', 'हनुमान तट पर पहुँचकर जलती पूँछ समुद्र में बुझाते हैं। साथ चलती आग समाप्त होती है, पर लंका में फैल चुकी लपटें जारी रहती हैं और पीड़ित लोग फिर पूर्ववत नहीं होते। लौ बुझने से पहला शांत क्षण मिलता है जिसमें वे अपने क्रोध और रणनीति के परिणाम देख सकते हैं।'),
  ('scene-remorse-tests-the-victory', 'the-first-thought-is-not-triumph', 'en', 'Hanuman fears he has destroyed the mission', 'Looking back at fire across Lanka, Hanuman suddenly asks whether Sita was caught in it. The thought overturns every claim of victory: if the person he came to find has died through his action, the grove, battles, court message, and city fire have defeated their own purpose.'),
  ('scene-remorse-tests-the-victory', 'the-first-thought-is-not-triumph', 'hi', 'हनुमान डरते हैं कि अभियान नष्ट हो गया', 'लंका पर फैली आग देखकर हनुमान अचानक पूछते हैं कि कहीं सीता उसमें फँस तो नहीं गईं। यह विचार हर विजय-दावे को उलट देता है—यदि खोजी गई व्यक्ति उनकी कार्रवाई से मर गईं, तो वाटिका, युद्ध, सभा-संदेश और नगर-अग्नि ने अपना ही उद्देश्य हरा दिया।'),
  ('scene-remorse-tests-the-victory', 'anger-is-named-as-a-loss-of-judgment', 'en', 'Power did not guarantee control', 'Hanuman condemns the anger that acted faster than reflection and says an enraged person may speak or do what should have been refused. He does not blame fate, Ravana, or a monkey nature alone. The review returns responsibility to the moment when strategic fire became uncontrolled city fire.'),
  ('scene-remorse-tests-the-victory', 'anger-is-named-as-a-loss-of-judgment', 'hi', 'शक्ति ने नियंत्रण की गारंटी नहीं दी', 'हनुमान उस क्रोध को दोष देते हैं जो विचार से तेज चला और कहते हैं कि क्रोधित व्यक्ति वह बोल या कर सकता है जिसे रोकना चाहिए था। वे केवल भाग्य, रावण या वानर-स्वभाव पर दोष नहीं डालते। समीक्षा जिम्मेदारी को उस क्षण पर लौटाती है जब रणनीतिक आग अनियंत्रित नगर-अग्नि बनी।'),
  ('scene-remorse-tests-the-victory', 'despair-turns-against-hanuman', 'en', 'He imagines no return after failure', 'Believing Sita may be dead, Hanuman imagines Rama, Lakshmana, Sugriva, Bharata, and many others collapsing from the news. His despair turns toward ending his own life rather than facing them. The thought is shown as an acute crisis produced by assumed catastrophe, not as duty, purification, or an admirable solution.'),
  ('scene-remorse-tests-the-victory', 'despair-turns-against-hanuman', 'hi', 'विफलता के बाद उन्हें वापसी असंभव लगती है', 'सीता को मृत मानकर हनुमान कल्पना करते हैं कि समाचार से राम, लक्ष्मण, सुग्रीव, भरत और अनेक लोग टूट जाएँगे। उनका निराश मन उनका सामना करने के बजाय अपना जीवन समाप्त करने की ओर जाता है। यह अनुमानित आपदा से उपजा तीव्र संकट है, कर्तव्य, शुद्धि या प्रशंसनीय समाधान नहीं।'),
  ('scene-remorse-tests-the-victory', 'counterevidence-enters-before-a-final-act', 'en', 'Hanuman tests the worst conclusion', 'He remembers that the flame on his own tail stayed cool and asks whether the same protection could surround Sita. Auspicious signs and the limits of what he actually observed reopen uncertainty. Hope alone does not prove safety, but it is enough to stop treating the worst fear as confirmed fact.'),
  ('scene-remorse-tests-the-victory', 'counterevidence-enters-before-a-final-act', 'hi', 'हनुमान सबसे बुरे निष्कर्ष को परखते हैं', 'वे याद करते हैं कि अपनी पूँछ की लौ शीतल रही और पूछते हैं कि क्या वही रक्षा सीता को घेरे हो सकती है। शुभ संकेत और अपने प्रत्यक्ष ज्ञान की सीमा अनिश्चितता फिर खोलते हैं। केवल आशा सुरक्षा सिद्ध नहीं करती, पर सबसे बुरे भय को पुष्ट तथ्य मानना रोक देती है।'),
  ('scene-remorse-tests-the-victory', 'independent-voices-confirm-sita-lives', 'en', 'A report separates the grove from the fire', 'Hanuman hears travelling Charanas marvel that Lanka burns while Janaki remains unharmed. Their conversation is independent of his wish and matches the earlier signs. Relief returns, but it does not erase the damage to the rest of the city or make the original risk wise after the fact.'),
  ('scene-remorse-tests-the-victory', 'independent-voices-confirm-sita-lives', 'hi', 'एक सूचना वाटिका को आग से अलग करती है', 'हनुमान विचरते चारणों को आश्चर्य से कहते सुनते हैं कि लंका जल रही है, पर जानकी सुरक्षित हैं। उनकी बातचीत हनुमान की इच्छा से स्वतंत्र है और पहले संकेतों से मेल खाती है। राहत लौटती है, पर नगर की बाकी क्षति नहीं मिटाती और बाद की सफलता से मूल जोखिम बुद्धिमान सिद्ध नहीं होता।'),
  ('scene-remorse-tests-the-victory', 'verification-replaces-despair', 'en', 'Hanuman decides to see Sita again', 'With the report and signs aligned, Hanuman chooses to verify Sita''s safety directly before returning north. The next action is neither more destruction nor self-punishment; it is checking the person at the centre of the mission and carrying an accurate account of both success and consequence.'),
  ('scene-remorse-tests-the-victory', 'verification-replaces-despair', 'hi', 'हनुमान सीता को फिर देखने का निर्णय लेते हैं', 'सूचना और संकेत मिलने पर हनुमान उत्तर लौटने से पहले सीता की सुरक्षा सीधे जाँचने का निर्णय लेते हैं। अगला कदम न अधिक विनाश है, न आत्म-दंड; वह अभियान के केंद्र की व्यक्ति को देखना और सफलता तथा परिणाम दोनों का सटीक वृत्तांत ले जाना है।'),
  ('scene-leave-lanka', 'honour-the-allies', 'en', 'Before anyone leaves', 'Vibhishana asks what remains to be done. Rama''s first answer is not about himself: honour the vanaras and bears who risked their lives in the war.'),
  ('scene-leave-lanka', 'honour-the-allies', 'hi', 'प्रस्थान से पहले', 'विभीषण पूछते हैं कि अब क्या करना बाकी है। राम का पहला उत्तर अपने लिए नहीं है—उन वानरों और भालुओं का सम्मान हो जिन्होंने युद्ध में अपना जीवन दाँव पर लगाया।'),
  ('scene-leave-lanka', 'friends-ask-to-come', 'en', 'One more request', 'Rama releases his allies to their own homes. They ask instead to travel with him, see Ayodhya, witness the coronation, and only then depart.'),
  ('scene-leave-lanka', 'friends-ask-to-come', 'hi', 'एक और आग्रह', 'राम अपने साथियों को उनके घर लौटने की अनुमति देते हैं। वे आग्रह करते हैं कि पहले उनके साथ अयोध्या चलें, राज्याभिषेक देखें, फिर विदा हों।'),
  ('scene-leave-lanka', 'sita-and-lakshmana-board', 'en', 'The returning company gathers', 'Sita and Lakshmana board with Rama. Sugriva, Vibhishana, vanaras, bears, and rakshasa companions fill the extraordinary craft without being left behind.'),
  ('scene-leave-lanka', 'sita-and-lakshmana-board', 'hi', 'वापसी का दल जुटता है', 'सीता और लक्ष्मण राम के साथ चढ़ते हैं। सुग्रीव, विभीषण, वानर, भालू और राक्षस साथी भी उस अद्भुत विमान में स्थान पाते हैं।'),
  ('scene-leave-lanka', 'pushpaka-rises', 'en', 'Lanka falls away', 'At Rama''s command, the Pushpaka rises into the sky. For the first time since the exile began, home is not only a hope—it is the direction of travel.'),
  ('scene-leave-lanka', 'pushpaka-rises', 'hi', 'लंका पीछे छूटती है', 'राम के आदेश पर पुष्पक आकाश में उठता है। वनवास शुरू होने के बाद पहली बार घर केवल आशा नहीं, यात्रा की दिशा बन जाता है।'),
  ('scene-sky-road', 'battlefield-and-bridge', 'en', 'The cost below', 'Rama shows Sita Lanka, the battlefield, the ocean, and the bridge. Each place carries the memory of companions, losses, choices, and the effort made to find her.'),
  ('scene-sky-road', 'battlefield-and-bridge', 'hi', 'नीचे छूटी कीमत', 'राम सीता को लंका, युद्धभूमि, समुद्र और सेतु दिखाते हैं। हर स्थान साथियों, हानि, निर्णय और उन्हें खोजने के प्रयास की स्मृति लिए है।'),
  ('scene-sky-road', 'kishkindha-companions', 'en', 'The journey grows', 'At Kishkindha, Sita asks that Tara and the other vanara women join them. The homecoming expands again: it will be witnessed by the families behind the alliance.'),
  ('scene-sky-road', 'kishkindha-companions', 'hi', 'यात्रा का दल बढ़ता है', 'किष्किंधा में सीता चाहती हैं कि तारा और अन्य वानर स्त्रियाँ भी साथ चलें। घर-वापसी फिर बड़ी हो जाती है—अब गठबंधन के पीछे खड़े परिवार भी उसके साक्षी होंगे।'),
  ('scene-sky-road', 'places-become-memories', 'en', 'A story written across the land', 'Rishyamuka, Pampa, Panchavati, the Godavari, Chitrakuta, Yamuna, Ganga, and Shringavera appear below. The names are not a list: friendship, grief, abduction, searching, and endurance return with them.'),
  ('scene-sky-road', 'places-become-memories', 'hi', 'धरती पर लिखी कथा', 'ऋष्यमूक, पम्पा, पंचवटी, गोदावरी, चित्रकूट, यमुना, गंगा और शृंगवेरपुर नीचे उभरते हैं। ये केवल नाम नहीं—मित्रता, शोक, हरण, खोज और धैर्य फिर जीवित होते हैं।'),
  ('scene-sky-road', 'ayodhya-in-sight', 'en', 'Home appears', 'Ayodhya finally comes into view. Rama asks Sita to bow toward it, and the whole company rises to look at the city they have crossed an epic to reach.'),
  ('scene-sky-road', 'ayodhya-in-sight', 'hi', 'घर दिखाई देता है', 'अंततः अयोध्या दिखाई देती है। राम सीता से उसे प्रणाम करने को कहते हैं, और पूरा दल उस नगरी को देखने उठ खड़ा होता है जहाँ पहुँचने के लिए उन्होंने एक महाकाव्य पार किया है।'),
  ('scene-bharadvaja-hermitage', 'fourteen-years-complete', 'en', 'The vow reaches its edge', 'With the fourteen years complete, Rama reaches Bharadvaja''s hermitage and bows. Before asking about celebration or power, he asks whether Ayodhya is well, Bharata still protects it, and his mothers live.'),
  ('scene-bharadvaja-hermitage', 'fourteen-years-complete', 'hi', 'प्रतिज्ञा की अवधि पूरी', 'चौदह वर्ष पूरे होने पर राम भरद्वाज के आश्रम पहुँचकर प्रणाम करते हैं। उत्सव या सत्ता से पहले वे पूछते हैं—क्या अयोध्या कुशल है, क्या भरत अब भी उसकी रक्षा कर रहे हैं, क्या उनकी माताएँ जीवित हैं।'),
  ('scene-bharadvaja-hermitage', 'bharata-waits', 'en', 'The sandals still lead', 'Bharadvaja answers that Bharata waits with matted hair, honouring Rama''s sandals and ruling in obedience to his command. The household is safe.'),
  ('scene-bharadvaja-hermitage', 'bharata-waits', 'hi', 'पादुकाएँ अब भी आगे हैं', 'भरद्वाज बताते हैं कि भरत जटाएँ धारण किए राम की पादुकाओं का सम्मान करते हुए उनकी आज्ञा के अनुसार राज्य संभाल रहे हैं। राजपरिवार सुरक्षित है।'),
  ('scene-bharadvaja-hermitage', 'the-journey-is-known', 'en', 'Nothing was unseen', 'The sage recounts the exile''s great turns—Sita''s abduction, Sugriva''s alliance, Hanuman''s search, the bridge, and Ravana''s defeat. Rama arrives not as a rumour but as someone whose ordeal is understood.'),
  ('scene-bharadvaja-hermitage', 'the-journey-is-known', 'hi', 'कुछ भी अनदेखा नहीं रहा', 'ऋषि वनवास के बड़े मोड़ गिनाते हैं—सीता का हरण, सुग्रीव से मैत्री, हनुमान की खोज, सेतु और रावण की पराजय। राम किसी अफवाह की तरह नहीं, समझे गए संघर्ष के साथ लौटते हैं।'),
  ('scene-bharadvaja-hermitage', 'road-of-fruit', 'en', 'Hospitality for the whole company', 'Rama asks for one boon: let the road ahead bear fruit and honey for his companions. The trees flower out of season, and the weary vanaras find abundance on the final approach.'),
  ('scene-bharadvaja-hermitage', 'road-of-fruit', 'hi', 'पूरे दल के लिए आतिथ्य', 'राम एक वर माँगते हैं—आगे की राह पर उनके साथियों के लिए फल और मधु उपलब्ध हों। वृक्ष असमय फूल-फल उठते हैं और अंतिम पड़ाव पर थके वानरों को भरपूर आहार मिलता है।'),
  ('scene-hanuman-goes-ahead', 'read-bharatas-heart', 'en', 'A delicate mission', 'Rama sends Hanuman ahead not only to announce the return, but to observe Bharata''s face, words, and wishes. Fourteen years with a kingdom could have changed anyone.'),
  ('scene-hanuman-goes-ahead', 'read-bharatas-heart', 'hi', 'एक संवेदनशील दायित्व', 'राम हनुमान को केवल वापसी का समाचार देने नहीं, भरत के चेहरे, शब्द और इच्छा को समझने भी भेजते हैं। चौदह वर्ष और एक राज्य किसी को भी बदल सकते थे।'),
  ('scene-hanuman-goes-ahead', 'news-for-guha', 'en', 'An old friendship is remembered', 'Hanuman first reaches Guha at Shringavera and tells him that his friend Rama is safe and near. The return follows the same human bonds that once helped the exiles leave.'),
  ('scene-hanuman-goes-ahead', 'news-for-guha', 'hi', 'पुरानी मित्रता याद रहती है', 'हनुमान पहले शृंगवेरपुर में गुह के पास पहुँचकर बताते हैं कि उनके मित्र राम सुरक्षित और निकट हैं। वापसी उन्हीं मानवीय संबंधों से होकर गुजरती है जिन्होंने वनवास के आरंभ में सहारा दिया था।'),
  ('scene-hanuman-goes-ahead', 'nandigrama-waiting', 'en', 'The ruler who never took the throne', 'At Nandigrama, Hanuman finds Bharata thin from restraint, dressed like an ascetic, ruling with Rama''s sandals before him. The years of waiting are visible before a word is spoken.'),
  ('scene-hanuman-goes-ahead', 'nandigrama-waiting', 'hi', 'जिसने सिंहासन नहीं लिया', 'नंदिग्राम में हनुमान भरत को संयम से क्षीण, तपस्वी वेश में और सामने राम की पादुकाएँ रखकर शासन करते देखते हैं। एक शब्द बोले जाने से पहले ही वर्षों की प्रतीक्षा दिखाई देती है।'),
  ('scene-hanuman-goes-ahead', 'the-message-lands', 'en', 'Grief breaks into joy', 'Hanuman says that Rama has defeated Ravana, recovered Sita, and returned with Lakshmana and his allies. Bharata collapses in sudden joy, then rises to hear everything.'),
  ('scene-hanuman-goes-ahead', 'the-message-lands', 'hi', 'शोक आनंद में टूटता है', 'हनुमान बताते हैं कि राम ने रावण को पराजित किया, सीता को वापस पाया और लक्ष्मण व साथियों के साथ लौट आए हैं। भरत अचानक आनंद से मूर्छित हो जाते हैं, फिर उठकर पूरी कथा सुनना चाहते हैं।'),
  ('scene-bharata-hears', 'tell-me-how', 'en', 'How did this become possible?', 'Bharata does not stop at the headline that Rama lives. He asks Hanuman how Rama met the vanaras and how the years after Chitrakuta unfolded.'),
  ('scene-bharata-hears', 'tell-me-how', 'hi', 'यह सब कैसे संभव हुआ?', 'भरत केवल यह सुनकर नहीं रुकते कि राम जीवित हैं। वे हनुमान से पूछते हैं कि राम वानरों से कैसे मिले और चित्रकूट के बाद के वर्ष कैसे बीते।'),
  ('scene-bharata-hears', 'forest-turns', 'en', 'The road through loss', 'Hanuman tells of the forest dangers, Surpanakha, the golden deer, Sita''s abduction, and Jatayu''s fall. The reunion ahead is measured against what was taken away.'),
  ('scene-bharata-hears', 'forest-turns', 'hi', 'हानि से गुजरती राह', 'हनुमान वन के संकट, शूर्पणखा, स्वर्ण-मृग, सीता के हरण और जटायु के पतन की कथा कहते हैं। आने वाला मिलन अब उस सबके सामने दिखाई देता है जो छिन गया था।'),
  ('scene-bharata-hears', 'alliance-and-search', 'en', 'Strangers become the search', 'He recounts the meeting with Sugriva, the vanara search, Sampati''s clue, his own leap to Lanka, Sita in the ashoka grove, and the ring that proved Rama had found a path to her.'),
  ('scene-bharata-hears', 'alliance-and-search', 'hi', 'अजनबी खोज के साथी बनते हैं', 'वे सुग्रीव से भेंट, वानर दलों की खोज, संपाती के संकेत, अपनी लंका-छलाँग, अशोक-वाटिका में सीता और राम की मुद्रिका की कथा सुनाते हैं।'),
  ('scene-bharata-hears', 'bridge-battle-return', 'en', 'The whole road closes', 'The bridge, the battle, Ravana''s defeat, and the Pushpaka return bring the account to the present. Bharata folds his hands: after so long, the desire to see Rama can finally be fulfilled.'),
  ('scene-bharata-hears', 'bridge-battle-return', 'hi', 'पूरी राह एक साथ जुड़ती है', 'सेतु, युद्ध, रावण की पराजय और पुष्पक से वापसी कथा को वर्तमान तक ले आते हैं। भरत हाथ जोड़ते हैं—इतने लंबे समय बाद राम को देखने की इच्छा अब पूरी होगी।'),
  ('scene-ayodhya-prepares', 'city-awakens', 'en', 'Tell everyone', 'Bharata orders worship, music, and a welcome open to the royal household, soldiers, families, artists, and citizens. Rama''s return belongs to the city, not only the palace.'),
  ('scene-ayodhya-prepares', 'city-awakens', 'hi', 'सबको समाचार दो', 'भरत पूजा, संगीत और ऐसा स्वागत तैयार करने का आदेश देते हैं जिसमें राजपरिवार, सैनिक, परिवार, कलाकार और नागरिक सब शामिल हों। राम की वापसी केवल महल की नहीं, पूरे नगर की है।'),
  ('scene-ayodhya-prepares', 'prepare-the-road', 'en', 'A road made ready', 'Shatrughna has the route from Nandigrama levelled, watered, strewn with flowers, and lined with flags. The landscape itself becomes part of the welcome.'),
  ('scene-ayodhya-prepares', 'prepare-the-road', 'hi', 'राह सजती है', 'शत्रुघ्न नंदिग्राम से आने वाली राह समतल और जल-सिंचित करवाते हैं; फूल बिखरते हैं और ध्वज लगते हैं। भू-दृश्य स्वयं स्वागत का हिस्सा बन जाता है।'),
  ('scene-ayodhya-prepares', 'sandals-lead-procession', 'en', 'The promise goes first', 'Still dressed in bark, Bharata carries Rama''s sandals on his head as the queens, ministers, citizens, horses, chariots, and elephants move toward Nandigrama.'),
  ('scene-ayodhya-prepares', 'sandals-lead-procession', 'hi', 'प्रतिज्ञा सबसे आगे', 'अब भी वल्कल पहने भरत राम की पादुकाएँ सिर पर रखते हैं। रानियाँ, मंत्री, नागरिक, घोड़े, रथ और हाथी नंदिग्राम की ओर बढ़ते हैं।'),
  ('scene-ayodhya-prepares', 'brothers-meet', 'en', 'The distance ends', 'The Pushpaka descends. Rama lifts Bharata into an embrace; Bharata greets Sita, Lakshmana, and the allies, then places the sandals back at Rama''s feet and returns the kingdom held in trust.'),
  ('scene-ayodhya-prepares', 'brothers-meet', 'hi', 'दूरी समाप्त होती है', 'पुष्पक उतरता है। राम भरत को उठाकर गले लगाते हैं; भरत सीता, लक्ष्मण और साथियों का स्वागत करते हैं, फिर पादुकाएँ राम के चरणों में रखकर धरोहर की तरह संभाला राज्य लौटा देते हैं।'),
  ('scene-kingdom-returned', 'bharata-returns-burden', 'en', 'Take back what I guarded', 'Bharata tells Rama that the kingdom was never his possession and that he cannot carry its burden in Rama''s place. Rama answers, ''So be it.'''),
  ('scene-kingdom-returned', 'bharata-returns-burden', 'hi', 'जिसे संभाला, उसे वापस लो', 'भरत राम से कहते हैं कि राज्य कभी उनकी संपत्ति नहीं था और वे राम के स्थान पर उसका भार नहीं उठा सकते। राम स्वीकार करते हैं।'),
  ('scene-kingdom-returned', 'exile-clothes-fall-away', 'en', 'The signs of exile are removed', 'Rama, Lakshmana, Bharata, Sugriva, and Vibhishana bathe; the matted hair is cut and ceremonial clothes are prepared. Sita and the vanara women are adorned for the entry.'),
  ('scene-kingdom-returned', 'exile-clothes-fall-away', 'hi', 'वनवास के चिह्न उतरते हैं', 'राम, लक्ष्मण, भरत, सुग्रीव और विभीषण स्नान करते हैं; जटाएँ काटी जाती हैं और राजकीय वस्त्र तैयार होते हैं। सीता और वानर स्त्रियाँ नगर-प्रवेश के लिए सजती हैं।'),
  ('scene-kingdom-returned', 'city-entry', 'en', 'Ayodhya receives the whole story', 'Music and crowds accompany the entry. Rama publicly tells Ayodhya about Sugriva''s friendship, Hanuman''s prowess, and the work of the allies, so the victory is not reduced to one hero.'),
  ('scene-kingdom-returned', 'city-entry', 'hi', 'अयोध्या पूरी कथा का स्वागत करती है', 'संगीत और जनसमूह नगर-प्रवेश के साथ चलते हैं। राम अयोध्या को सुग्रीव की मित्रता, हनुमान के पराक्रम और सभी साथियों के कार्य बताते हैं, ताकि विजय केवल एक नायक की न रह जाए।'),
  ('scene-kingdom-returned', 'coronation-and-gifts', 'en', 'A crown, then gratitude', 'Vasishta and the gathered officiants install Rama with Sita beside him. Honours move outward to the allies; Sita gives Hanuman the pearl necklace, remembering his service.'),
  ('scene-kingdom-returned', 'coronation-and-gifts', 'hi', 'मुकुट, फिर कृतज्ञता', 'वसिष्ठ और अन्य आचार्य सीता के साथ राम का राज्याभिषेक करते हैं। सम्मान साथियों तक पहुँचता है; सीता हनुमान की सेवा याद कर उन्हें मोतियों का हार देती हैं।'),
  ('scene-kingdom-returned', 'rule-begins', 'en', 'The ending opens into duty', 'The companions eventually return to their own worlds, and governance begins. The selected telling closes with an idealized vision of Rama''s reign; Devam presents that as this source''s sacred narrative, not a modern historical statistic.'),
  ('scene-kingdom-returned', 'rule-begins', 'hi', 'अंत से कर्तव्य शुरू होता है', 'साथी अंततः अपने-अपने लोक लौटते हैं और शासन आरंभ होता है। चुना हुआ पाठ राम-राज्य की आदर्श छवि के साथ समाप्त होता है; देवम इसे इसी स्रोत की पवित्र कथा मानता है, आधुनिक ऐतिहासिक आँकड़ा नहीं।')
) as copy(moment_slug, beat_slug, language_code, title, narration)
join public.narrative_series series on series.slug = 'ramayana-dutt-consumer-v1'
join public.narrative_moments moment on moment.series_id = series.id and moment.slug = copy.moment_slug
join public.narrative_beats beat on beat.moment_id = moment.id and beat.slug = copy.beat_slug
on conflict (beat_id, language_code) do update set
  title = excluded.title,
  narration = excluded.narration,
  text_status = excluded.text_status,
  rights_lane = excluded.rights_lane,
  publication_state = excluded.publication_state,
  updated_at = now();

delete from public.narrative_moment_links link
using public.narrative_moments source, public.narrative_series series
where link.source_moment_id = source.id
  and source.series_id = series.id
  and series.slug = 'ramayana-dutt-consumer-v1'
  and link.label = 'generated narrative order';

