join public.narrative_series series on series.slug = 'ramayana-dutt-consumer-v1'
join public.narrative_moments source on source.series_id = series.id and source.slug = link.source_slug
join public.narrative_moments target on target.series_id = series.id and target.slug = link.target_slug
on conflict (source_moment_id, target_moment_id, link_kind) do update set
  label = excluded.label;

do $$
declare
  series_uuid uuid;
begin
  select id into series_uuid from public.narrative_series where slug = 'ramayana-dutt-consumer-v1';
  if series_uuid is null then raise exception 'Ramayana narrative series is missing'; end if;
  if (select count(*) from public.narrative_arcs where series_id = series_uuid) <> 7 then
    raise exception 'Expected 7 Ramayana narrative arcs';
  end if;
  if (select count(*) from public.narrative_arc_texts copy join public.narrative_arcs arc on arc.id = copy.arc_id where arc.series_id = series_uuid) <> 14 then
    raise exception 'Expected 14 bilingual Ramayana arc texts';
  end if;
  if (select count(*) from public.narrative_moments where series_id = series_uuid and moment_kind = 'backbone_turn') <> 49 then
    raise exception 'Expected 49 Ramayana backbone turns';
  end if;
  if (select count(*) from public.narrative_moments where series_id = series_uuid and moment_kind = 'backbone_turn' and publication_state = 'published') <> 34 then
    raise exception 'Expected 34 playable Ramayana turns';
  end if;
  if (select count(*) from public.narrative_moments where series_id = series_uuid and moment_kind = 'backbone_turn' and publication_state = 'draft') <> 15 then
    raise exception 'Expected 15 unfinished Ramayana turns';
  end if;
  if (select count(*) from public.narrative_moments where series_id = series_uuid and moment_kind = 'backbone_turn' and visual_direction->>'coverage' = 'outlined') <> 0 then
    raise exception 'Expected 0 outlined Ramayana turns';
  end if;
  if (select count(*) from public.narrative_moments where series_id = series_uuid and moment_kind = 'backbone_turn' and visual_direction->>'coverage' = 'orientation') <> 15 then
    raise exception 'Expected 15 orientation-only Ramayana turns';
  end if;
  if (select count(*) from public.narrative_moments where series_id = series_uuid and moment_kind = 'playable_scene' and publication_state = 'published') <> 230 then
    raise exception 'Expected 230 Ramayana playable scenes';
  end if;
  if (select count(*) from public.narrative_moments where series_id = series_uuid and moment_kind = 'playable_scene' and publication_state = 'draft') <> 0 then
    raise exception 'Expected 0 draft Ramayana scene outlines';
  end if;
  if (select count(*) from public.narrative_beats beat join public.narrative_moments moment on moment.id = beat.moment_id where moment.series_id = series_uuid) <> 1090 then
    raise exception 'Expected 1090 Ramayana narrative beats';
  end if;
  if (select count(*) from public.narrative_moment_texts copy join public.narrative_moments moment on moment.id = copy.moment_id where moment.series_id = series_uuid) <> 558 then
    raise exception 'Expected 558 bilingual Ramayana moment texts';
  end if;
  if (select count(*) from public.narrative_beat_texts copy join public.narrative_beats beat on beat.id = copy.beat_id join public.narrative_moments moment on moment.id = beat.moment_id where moment.series_id = series_uuid) <> 2180 then
    raise exception 'Expected 2180 bilingual Ramayana beat texts';
  end if;
  if exists (
    select 1 from public.narrative_moments
    where series_id = series_uuid and moment_kind = 'playable_scene' and publication_state = 'published'
      and (
        coalesce(source_range->>'sourceSha256', '') !~ '^[0-9a-f]{64}$'
        or not coalesce(
          case when source_range->>'sourceAddressKind' = 'section_span_set' then
            jsonb_typeof(source_range->'spanSha256s') = 'array'
            and jsonb_array_length(source_range->'spanSha256s') =
              (source_range->>'sourceEndOrdinal')::integer - (source_range->>'sourceOrdinal')::integer + 1
            and not exists (
              select 1 from jsonb_array_elements_text(source_range->'spanSha256s') hash(value)
              where hash.value !~ '^[0-9a-f]{64}$'
            )
          else coalesce(source_range->>'spanSha256', '') ~ '^[0-9a-f]{64}$'
          end,
          false
        )
      )
  ) then raise exception 'A playable Ramayana scene lacks an exact source address'; end if;
end
$$;

commit;
